window.ACDT_CHATEAUX_TXT = window.ACDT_CHATEAUX_TXT || {}; window.ACDT_CHATEAUX_TXT["de"] = {"ch-Q2946":{"n":"Schloss Versailles","c":"französisches Schloss, Residenz der Könige von Frankreich","r":"Das Schloss Versailles in der gleichnamigen Nachbarstadt von Paris ist eine der größten Palastanlagen Europas und war von der Mitte des 17. Jahrhunderts bis zum Ausbruch der Französischen Revolution die Hauptresidenz der Könige von Frankreich. Der Barockbau, dessen größte Ausdehnung mehr als einen halben Kilometer beträgt, gilt als ein Höhepunkt europäischer Palastarchitektur und diente vom 17. bis zum 19. Jahrhundert als Vorbild für zahlreiche weitere Schlossbauten.","w":"https://de.wikipedia.org/wiki/Schloss_Versailles"},"ch-Q1143049":{"n":"Schloss Montsoreau","c":"Schloss im Loire-Tal Frankreich und Standort des Schloss Montsoreau-Museum für zeitgenössische Kunst","r":"Das Schloss Montsoreau ist ein Schloss im Renaissancestil im Loiretal, welches direkt am Ufer der Loire im Département Maine-et-Loire in der Region Pays de la Loire in Frankreich steht. Es befindet sich im Dorf Montsoreau in der Nähe von Saumur, Chinon, Fontevraud-l’Abbaye und Candes-Saint-Martin. Das Schloss ist das einzige der Loire-Schlösser, das im Flussbett der Loire errichtet wurde.","h":"Erstmals schriftlich dokumentiert wurde die Besiedlung der Stätte im 6. Jahrhundert, bevor dort im Jahre 990 von Odo, dem ersten Grafen von Blois, die erste Festung erbaut wurde. Im Jahre 1001 wurde sie vom Grafen von Anjou, Fulko Nerra (Fulk dem Schwarzen), einem der größten Bauherren des Mittelalters, übernommen. Dieser übergab sie dem Ritter Gautier I. von Montsoreau, der zu einer der bedeutendsten Familien von Anjou gehörte. Somit war das Castrum Monsorelli eine der vierzig befestigten Burgen in Anjou und eine der wenigen, die um die Jahreswende 1000 den Herrschaftstitel erhielten. Im Umkreis der Burg entwickelte sich rasch eine Stadt, die Monte Sorelli in der 1854 von Salmon edierten Fassung narratio de commendatione Turonice provincie als eine der oppidis munitissimi et pupolosis nannte. (Ab dem 12. Jahrhundert ist anhand von schriftlichen Quellen ein Zollhaus belegbar.) In den Jahren 1152 und 1156 belagerte Heinrich II. König von England zweimal die Burg von Montsoreau. Im Jahre 1152 organisierte Gottfried VI., Bruder von Heinrich II., Herzog der Normandie, Erbe der Grafschaft Anjou, einen Aufstand gegen ebendiesen Bruder. Dieser endete während der Belagerung und Eroberung der Festung von Montsoreau mit der Kapitulation Gottfrieds. Heinrich II. blieb folglich Graf von Anjou, die Festungen von Chinon, Mirebeau, Loudun und Montsoreau gingen jedoch in Gottfrieds Besitz über. 1156 organisierte Gottfried erneut einen Aufstand gegen seinen Bruder, welcher inzwischen zum König von England ernannt worden war. Auch dieser Aufstand führte zur Eroberung von Montsoreau. Gottfried und Guillaume von Montsoreau wurden gefangen genommen. Heinrich II. behielt im weiteren Verlauf die Festung für seinen persönlichen Gebrauch, vermutlich bis zu seinem Tod.","w":"https://de.wikipedia.org/wiki/Schloss_Montsoreau"},"ch-Q201428":{"n":"Schloss Fontainebleau","c":"Schloss in Frankreich","r":"Das Schloss Fontainebleau in Fontainebleau, Département Seine-et-Marne, ist ein französisches Schloss rund 60 km südlich von Paris. Es ist vor allem berühmt für seine Innenausstattung aus der Zeit der Renaissance, an der zahlreiche italienische Künstler arbeiteten, und wurde 1981 von der UNESCO zum Weltkulturerbe erklärt.","w":"https://de.wikipedia.org/wiki/Schloss_Fontainebleau"},"ch-Q205367":{"n":"Schloss Chambord","c":"Schloss in Frankreich","r":"Schloss Chambord ist das größte Schloss des Loiretales. Es liegt ca. 15 Kilometer östlich von Blois in einem ausgedehnten früheren Jagdgebiet. Der Renaissancebau wurde in der ersten Hälfte des 16. Jahrhunderts unter König Franz I. als Prunk- und Jagdschloss bei Chambord errichtet und gilt als das prächtigste aller Loireschlösser.","w":"https://de.wikipedia.org/wiki/Schloss_Chambord"},"ch-Q329852":{"n":"Palais du Luxembourg","c":"Schloss in Frankreich","r":"Das Palais du Luxembourg ist ein Schloss im 6. Arrondissement von Paris, umgeben von einer ursprünglich barocken Parklandschaft aus dem frühen 17. Jahrhundert, genannt Jardin du Luxembourg. Es diente zunächst Mitgliedern der königlichen Familie als Wohnsitz, wurde während der Revolution in Staatsbesitz überführt und ist seit 1800 Sitz des Senats, der zweiten parlamentarischen Kammer Frankreichs.","w":"https://de.wikipedia.org/wiki/Palais_du_Luxembourg"},"ch-Q143463":{"n":"Papstpalast","c":"Palast in Frankreich","r":"Der Papstpalast zu Avignon war zwischen 1335 und 1430 die Residenz verschiedener spätmittelalterlicher Päpste und Gegenpäpste. Der Palast gehört mit der Altstadt von Avignon zum Weltkulturerbe. Es ist eines der größten und wichtigsten mittelalterlichen gotischen Gebäude in Europa. Der Ehrenhof des Palastes wurde vom französischen Staat mit dem Europäischen Kulturerbe-Siegel ausgezeichnet.","h":"Avignon, bereits 539 v. Chr. als griechisches Emporion durch die Phokäer von Marseille gegründet, war im Mittelalter eine beschauliche Provinzstadt, als sie ab 1309 durch das avignonesische Papsttum zu einem Zentrum der Weltöffentlichkeit wurde. Als Folge dessen änderte sich das Aussehen der Stadt radikal und schnell. Die mächtige Palast-Anlage ist in zwei Bauphasen errichtet worden. Sie sieht auf den ersten Blick wie eine Festung aus, innen gleicht sie eher einem Schloss. 1304 war Papst Benedikt XI. nach kurzem Pontifikat gestorben und der französische König Philipp der Schöne wollte aus dem Papsttum ein persönliches Machtinstrument machen. Der französische Einfluss im Kardinalskollegium hielt sich mit dem italienischen in etwa die Waage, sodass das Konklave elf Monate dauerte, bis es 1305 den Erzbischof von Bordeaux als Papst Clemens V. wählte. Der aus Aquitanien stammende Papst erschien zu seiner Inthronisation erst gar nicht in Rom, sondern blieb in Frankreich und wurde in Lyon gekrönt. Diese Stadt gehörte zwar nominell zum Heiligen Römischen Reich, stand jedoch damals bereits unter französischem Einfluss. Clemens äußerte wiederholt seinen Willen, nach Italien zu ziehen, hielt sich jedoch aus gesundheitlichen und politischen Gründen ausschließlich in Mittel- und Südfrankreich auf. Auf der Suche nach einer würdigen Residenz wählte man kurz darauf Avignon, eine alte Bischofsstadt, die den Vorzug hatte, dass sich deren weiteres Umland östlich der Rhone, das Comtat Venaissin, aufgrund einer Erbschaft bereits seit 1271 im Besitz des Heiligen Stuhls befand. Die Stadt selbst gehörte als Teil der Grafschaft Avignon jedoch zum Besitz des älteren Hauses Anjou. Clemens V. residierte aber nur vorübergehend in Avignon und wohnte im Kloster der Dominikaner.","w":"https://de.wikipedia.org/wiki/Papstpalast_(Avignon)"},"ch-Q193215":{"n":"Schloss Chenonceau","c":"Wasserschloss am Cher in der Region Val de Loire in Frankreich","r":"Schloss Chenonceau ist ein Wasserschloss im französischen Ort Chenonceaux im Département Indre-et-Loire in der Region Centre-Val de Loire. Sein Hauptgebäude steht – von Wasser umgeben – am nördlichen Ufer des Flusses Cher, während die später errichtete Galerie den Cher überbrückt. Etwa zwölf Kilometer südlich der Loire bei Amboise in der Mitte der Touraine gelegen, gehört Chenonceau zu den Schlössern der Loire. Neben Schloss Montsoreau in der Loire ist es das einzige, das direkt in einem Flussbett gebaut wurde.","h":"Die beinahe 800 Jahre alte Geschichte Chenonceaus wurde fast immer von Frauen geprägt, auf deren Geheiß das Schloss zu seiner heutigen Erscheinung ausgebaut wurde. Frauen machten es zum Mittelpunkt ausschweifender Festivitäten des französischen Königshofs und zeitweilig zu einem Treffpunkt illustrer Gäste aus Kunst und Kultur. Chenonceau wurde im 13. Jahrhundert erstmals schriftlich erwähnt. Ein dort existierender Mühlengrund war seit den 1230er Jahren im Besitz der Herren von Marques. Ende des 15. Jahrhunderts kam die Familie in finanzielle Schwierigkeiten, sodass ihr Oberhaupt, Pierre de Marques, ab 1496 gezwungen war, nach und nach Ländereien aus dem Familienbesitz zu veräußern. Käufer war jedes Mal der gleiche Mann: Thomas Bohier. Doch die Verkäufe konnten die Geldprobleme der Familie Marques nicht beheben. 1512 wurde der Restbesitz – bestehend aus einem befestigten Burghaus samt einer dazugehörigen Mühle im Cher sowie etwas Land – zur Versteigerung ausgeschrieben, und wieder war es Thomas Bohier – mittlerweile Eigentümer aller sonstigen Chenonceau umgebenden Ländereien – der den Marqueser Besitz erwarb. Gegen eine letzte Zahlung von 12.500 Livres wurde er am 8. Februar 1513 auch Eigentümer der Burg und der dazugehörigen Mühle. Bohier hatte unter Karl VIII. und Ludwig XII. Karriere am französischen Königshof gemacht und bekleidete während der Regierung von Franz I. zuerst das Amt des Generalsteuereinnehmers in der Normandie, anschließend das eines königlichen Finanzsekretärs. Vom König in den Adelsstand erhoben, begleitete Bohier ihn auf seinen Italienfeldzügen, sodass er in Chenonceaux während seiner Abwesenheit von seiner Frau Katherine Briçonnet vertreten wurde, die entscheidenden Einfluss auf die architektonische Gestaltung der Wasserburg und ihren Aufbau nahm.","w":"https://de.wikipedia.org/wiki/Schloss_Chenonceau"},"ch-Q936633":{"n":"Palais Bourbon","c":"Bauwerk in Paris","r":"Das Palais Bourbon ist ein Bauwerk im 7. Arrondissement von Paris, über die Pont de la Concorde direkt mit der Place de la Concorde auf der rechten Seite der Seine verbunden. Das ehemalige Hôtel particulier ist der Sitz der französischen Nationalversammlung, des Unterhauses des französischen Parlaments.","h":"Ursprünglich erbaut wurde das Palais für Louise Françoise, Herzogin von Bourbon und legitimierte Tochter König Ludwigs XIV. Die Planung lag in den Händen des italienischen Architekten Lorenzo Giardini in Zusammenarbeit mit dem französischen Baumeister Jules Hardouin-Mansart. Giardini überwachte den Baufortschritt von 1722 bis zu seinem Tod im Jahr 1724. Bis zur Fertigstellung 1728 waren danach Pierre Lassurance, Jacques Gabriel und Jean Aubert nacheinander mit der Bauleitung betraut. Da es sich um keinen königlichen Herrschaftssitz handelte, wurde das Gebäude anfangs nicht als palais (Palast), sondern als maison de plaisance (Lusthaus) bezeichnet. Zunächst bestand das Gebäude nur aus einem Hauptteil mit einfachen Flügeln, die in Pavillons endeten. Ein kleiner Hain mit sorgfältig angeordneten Bäumen trennte es vom danebengelegenen Hôtel de Lassay, das zeitgleich für den Marquis de Lassay, den Geliebten Louise Françoise de Bourbons, errichtet wurde. König Ludwig XV. erwarb das Palais im Jahr 1756 zunächst für die Krone und verkaufte es dann an Louis V. Joseph de Bourbon, Prinz von Conde und Enkel der ursprünglichen Besitzerin. Dieser ließ es 1765 durch Jacques-Germain Soufflot ausbauen. Während der Französischen Revolution wurde das Palais Bourbon verstaatlicht und ab 1798 zum Tagungsort des Rates der Fünfhundert. Als Teil von Napoleons Plänen für ein monumentaleres Paris wurde ein klassizistischer Portikus auf der der Place de la Concorde zugewandten Seite angefügt, der einen Kontrapunkt zum ähnlichen Säulengang der Kirche La Madeleine am Ende der Rue Royale bilden sollte.","w":"https://de.wikipedia.org/wiki/Palais_Bourbon"},"ch-Q4055":{"n":"Schloss Blois","c":"Französisches Schloss im Tal der Loire","r":"Das Schloss Blois ist eines der Schlösser der Loire. Es steht auf einem Bergsporn am rechten Ufer der Loire in der französischen Stadt Blois im Département Loir-et-Cher. Weil es unter den französischen Herrscherhäusern Valois und Orléans von 1498 bis 1589 Residenz der französischen Könige war und Bauwerke aus vier Epochen in einer Anlage vereint, ist es eines der bekanntesten Loireschlösser.","h":"Geschichte und Schicksal des Schlosses waren bis zur Französischen Revolution unzertrennlich erst mit der Grafschaft Blois und anschließend mit dem Herzogtum Orléans verbunden. Blois gehörte im 9. Jahrhundert zum Machtbereich der Robertiner und kam per Erbschaft im ersten Viertel des 10. Jahrhunderts an Thibaut l’Ancien, der erster Graf von Blois wurde. Dessen Sohn Thibaud I., le Tricheur genannt, legte den Grundstein für die Schlossanlage. Als Thibaud IV. von Blois 1152 starb, teilten seine beiden ältesten Söhne die Besitzungen ihres Vaters untereinander auf. Blois kam an Thibaud V., dessen Enkelin Marie die Grafschaft und den Wehrbau durch ihre Heirat 1226 in die Familie von Châtillon brachte. Als Guy II. von Blois-Châtillon seinen einzigen Sohn und Erben verloren hatte, verkaufte er die Grafschaft Blois gemeinsam mit der Grafschaft Dunois 1391 für 200.000 französische Kronen an Louis de Valois, den Bruder König Karls VI. und späteren Herzog von Orléans. Dessen Sohn Charles de Valois geriet 1415 bei der Schlacht von Azincourt in englische Gefangenschaft. Während seiner Abwesenheit wurde die Anlage von seinem Stiefbruder Jean de Dunois verwaltet, der von dort aus die Praguerie organisierte. Charles zog sich 1440 nach Blois zurück und machte das Schloss zu einem Zentrum der Poesie und der Intellektuellen. Sein Sohn Louis, seit 1465 Herzog von Orléans, wurde 1498 als Ludwig XII. König von Frankreich. Er wählte seine Geburtsstadt Blois als Hauptresidenz und machte sie damit zur Hauptstadt des französischen Königreichs. Ludwig hinterließ das Schloss 1515 seinem Nachfolger Franz I., der es ebenfalls als Hauptresidenz nutzte, weil seine Frau Claude de France sehr an der Anlage hing. Nach ihrem Tod im Juli 1524 wählte Franz I.","w":"https://de.wikipedia.org/wiki/Schloss_Blois"},"ch-Q739976":{"n":"Schloss Vaux-le-Vicomte","c":"Schloss in Frankreich","r":"Schloss Vaux-le-Vicomte im französischen Maincy, bei Melun im Département Seine-et-Marne und sein Park wurden in den Jahren 1656 bis 1661 im Auftrag des französischen Finanzministers Nicolas Fouquet nach Plänen des Architekten Louis Le Vau und des Gartenarchitekten André Le Nôtre errichtet. Sie stehen am Anfang der Entwicklung des französischen barocken Klassizismus. Die Innenausstattung entwarf der Maler Charles Lebrun, der zur Ausführung Pierre Mignard und Pierre Puget hinzuzog.","h":"Der Anlage, die neben dem Garten auch einen weitläufigen Park umfasste, mussten insgesamt drei Dörfer weichen. Am 17. August 1661 veranstaltete Nicolas Fouquet zu Ehren von König Ludwig XIV., der aus seinem Schloss Fontainebleau anreiste, ein opulentes Fest mit 6.000 erlesenen Gästen. Neben der verschwenderischen Inszenierung der Festlichkeiten in Schloss und Park (unter anderem durch den berühmten François Vatel) erregte vor allem das prunkvolle Interieur und das massiv goldene Tischgeschirr Fouquets Aufsehen. Das gesamte Haus war ausgestattet mit teurem Brokat, Spiegeln und Marmortischen mit vergoldeten Füßen. Der König, dessen verschiedene Schlösser in und um Paris dem neuartigen Konzept von Vaux-le-Vicomte nichts Vergleichbares entgegenzusetzen hatten, soll über die öffentliche Zurschaustellung von Fouquets Reichtum verärgert gewesen sein, was seine schlechte Meinung über Fouquet vertiefte. Drei Wochen nach dieser prunkvollen Einweihungsfeier ließ er Fouquet am 5. September 1661 verhaften, da dieser Staatsgelder veruntreut und eine Festung ohne Zustimmung des Königs erbaut hatte, womit er aus Sicht des Königs eine Gefahr für den Staat darstellte. Aus der Fouquet-Affäre entwickelte sich später die Legende, Ludwig XIV. habe seinen Finanzminister allein aus Neid über Vaux-le-Vicomte verhaften lassen. Dies ist wenig wahrscheinlich, denn Fouquets Absetzung und Inhaftierung war im August 1661 schon lange beschlossen. Dennoch wurde durch diese Legende die Schönheit des Schlosses nicht nur in der Kunstgeschichte unsterblich. Heute lautet einer der Werbeslogans der Domäne Vaux: Das Schloss, das den Neid des Sonnenkönigs erregte. Ludwig XIV.","w":"https://de.wikipedia.org/wiki/Schloss_Vaux-le-Vicomte"},"ch-Q663673":{"n":"Schloss Vincennes","c":"Schloss in Frankreich","r":"Das Schloss Vincennes in der am östlichen Rand von Paris gelegenen Stadt Vincennes ist neben dem Louvre eines der bedeutendsten Schlösser in der Geschichte Frankreichs. Sein Wohnturm (Donjon) ist mit 50 Meter Höhe einer der höchsten Frankreichs.","h":"Das erste echte Dokument, das den Wald von Vilcena erwähnt, stammt aus dem Jahr 847 und ist eine Urkunde der Abtei Saint-Maur; in dieser Zeit gehörte er zum Bistum Paris. Im 11. Jahrhundert wurde der Wald Eigentum der Krone, seine Grenzen entsprachen weitgehend denen von heute; er dürfte damals also rund 1000 Hektar groß gewesen sein. Der Wald von Vincennes war ein beliebtes Jagdgebiet Ludwigs VII. (1120–1180). 1164 ließ er Mönche aus Grandmont im Limousin (Grammontenser aus Grandmont bei Saint-Sylvestre (Haute-Vienne)) kommen und übergab ihnen ein von Gräben umgebenes Grundstück im Wald zur Trockenlegung, an dem sich heute der Lac des Minimes im Nordosten des Waldes befindet. 1178 unterzeichnete er in Vincennes ein Dokument, was beweist, dass hier nun eine königliche Residenz, zumindest ein Jagdpavillon, existierte, dessen erste Bauperiode in der Mitte des 12. Jahrhunderts anzusetzen ist. Nachdem Mönche der umliegenden Abteien den Wald mit Rodungen auf 50 Arpents (ca. 17 Hektar) verkleinert hatten, ließen Philipp II. Augustus (1165–1223) und seine Nachfolger ihn ab 1183 wieder aufforsten. Philipp II. ließ den Wald mit dicken Mauern umgeben und mit Wild bestücken; er und sein Enkel Ludwig IX. der Heilige (1214–1270) bauten schließlich an der Stelle einer alten Jagdhütte einen Herrensitz mit einer ersten Kapelle, das Manoir du Bois-de-Vincennes, den Ausgangspunkt des künftigen Schlosses Vincennes. Für letzteren wurde das Manoir zu seinen Hauptsitz nach dem Palais de la Cité, und auch für seine Nachfolger hatte er größere Bedeutung, zumal Philipp III. (1245–1285) hier heiratete (1274), sowie Ludwig X. (1289–1316) und Karl IV. (1295–1328) hier ihre letzten Tage verbrachten. Karl V.","w":"https://de.wikipedia.org/wiki/Schloss_Vincennes"},"ch-Q1075988":{"n":"Palais du Louvre","c":"früherer französischer Königspalast","r":"Der Louvre-Palast ist die frühere Residenz der französischen Könige in Paris. Er bildete zusammen mit dem zerstörten Palais des Tuileries das Pariser Stadtschloss. Die Herkunft des Namens Louvre ist unklar; zahlreiche Deutungen konkurrieren miteinander.","h":"Ursprünglich war der Louvre ab dem Ende des 12. Jahrhunderts unter König Philipp II. ein trutziger Zweckbau, eine kompakte Festung im Donjon-Stil zum Schutz des rechten Seineufers. Als die Stadt in der zweiten Hälfte des 14. Jahrhunderts rasch wuchs und außerdem durch einen weiteren inneren Mauerring geschützt war, ließ Karl V. die Burg ab 1364 zu einem dauerhaft bewohnbaren Residenzschloss umbauen. Unter Franz I. wurden Neubaumaßnahmen vorgenommen, die 1528 mit dem Abriss des Donjon begannen. Die mittelalterliche Anlage wurde in ein repräsentatives Königsschloss mit Bezügen zur Formensprache der Antike im Stil der italienischen Renaissance verwandelt, wobei der Grundriss aus der Zeit um 1200 – vier Flügel um einen quadratischen Hof – zunächst beibehalten wurde. Als Hauptwohnsitz des französischen Königs diente der Palast aber erst ab dem 16. Jahrhundert unter Heinrich II. Auch in den folgenden Jahrhunderten wurde der Louvre nach den Bedürfnissen der jeweiligen Herrscher umgestaltet und vor allem die Fläche des inneren Hofes auf die vierfache Größe erweitert. Heinrich IV. beschloss, den Louvre und den gegenüberliegenden Tuilerienpalast durch den Bau zweier Galerien zu verbinden, eine im Süden und eine im Norden. Dieses Projekt wurde später „Grand Dessein“ genannt, ein Begriff, der von seinem politischen Konzept für die Gestaltung Europas abgeleitet wurde. Zunächst wurde ein ganzer Stadtteil abgerissen und die „Grande Galerie“ (oder Ufergalerie) errichtet. Danach ruhte jedoch das Projekt, den Louvre und die Tuilerien zu verbinden, zwei Jahrhunderte lang, bis zu Napoleon I. Als der Königshof 1682 mit Ludwig XIV. ins Schloss Versailles umzog, verwahrloste der Bau.","w":"https://de.wikipedia.org/wiki/Palais_du_Louvre"},"ch-Q389908":{"n":"Schloss Amboise","c":"Schloss in Amboise, Frankreich","r":"Das Schloss Amboise steht in der mittelfranzösischen Kleinstadt Amboise im Département Indre-et-Loire der Region Centre-Val de Loire. Das über der Stadt und der Loire auf einem Felsplateau errichtete Schloss zählt kulturhistorisch zu den wichtigsten Schlössern der Loire und war im 15. und 16. Jahrhundert häufig königliche Residenz. Es steht seit 1840 als klassifiziertes Monument historique unter Denkmalschutz.","h":"Das Promontoir des Châtelliers (deutsch Châtelliers-Felsen) genannte Plateau, auf dem das heutige Schloss steht, war mindestens seit der Jungsteinzeit besiedelt. Für die Latènezeit ist dort ein Oppidum der Turonen verbürgt, das in gallorömischer Zeit unter dem lateinischen Namen Ambacium bekannt war. Der römische Statthalter Anician hatte das Areal durch Anlage eines tiefen Grabens an der Ostseite im 4. Jahrhundert befestigen lassen, denn es lag strategisch günstig an einer Furt der Loire. Diese ließ Anician mit einer hölzernen Brücke überspannen, sodass dem novum castellum eine wichtige Bedeutung zukam. Im Jahr 503 trafen sich der westfränkische König Chlodwig I. und Alarich II., König der Westgoten, auf der vor Amboise liegenden Loire-Insel Saint-Jean (damals Île dʼOr (deutsch Goldinsel) genannt), zu einem Friedensschluss. 853 und 877/878 überfielen Normannen Amboise und zerstörten es. Der Karolinger Ludwig der Stammler beauftragte Ingelger, den Vizegrafen von Angers, mit der Sicherung und Verteidigung von Amboise gegen die normannischen Invasoren, denn der Vizegraf hatte sich bei der Verteidigung der Touraine hervorgetan. Ingelger hatte vorher die ruinöse Befestigung in Amboise von Adalhard, dem Bischof von Tours und Onkel seiner Frau Adelais, erhalten und baute auf dem Felsplateau um 882 eine neue Burg. Allerdings hatte Karl der Kahle schon um 840 den Ort Amboise dem Ritter Aymon (auch Haimon geschrieben) de Buzançais als seinem Statthalter übertragen, sodass fortan das erste Haus Anjou und die Familie de Buzançais um die Vorherrschaft in Amboise stritten. Ingelgers Sohn Fulko I. wurde erster Graf von Anjou und baute die Burg seines Vaters weiter aus, aber von dieser Anlage ist heute nichts mehr erhalten. Über seinen Sohn Fulko II.","w":"https://de.wikipedia.org/wiki/Schloss_Amboise"},"ch-Q1520841":{"n":"Schloss Saint-Germain-en-Laye","c":"Schloss in Frankreich","r":"Das Schloss Saint-Germain-en-Laye [sɛ̃ ʒɛʁmɛ̃ ɑ̃ lɛ] ist eine Schlossanlage in der französischen Stadt Saint-Germain-en-Laye im Département Yvelines, etwa 19 Kilometer westlich von Paris. Seit seiner Errichtung als Burg im 13. Jahrhundert diente es bis in das 17. Jahrhundert als Residenz der französischen Könige, ehe Ludwig XIV. 1682 mit seinem Hof nach Versailles umzog.","h":"Ludwig VI. ließ um 1122 eine erste wehrhafte Burg an diesem Ort errichten, die 1124 unter dem Namen Grand Châtelet erstmals urkundlich erwähnt wurde. König Philippe Auguste ließ in dem von einer Ringmauer umschlossenen Areal 1223 einen ersten Kapellenbau ergänzen, von dem heute jedoch keine Spuren mehr vorhanden sind. Ludwig der Heilige erweiterte die Anlage durch das sogenannte Petit Châtelet und eine Kapelle, die nach ihrem Erbauer heute Chapelle Saint-Louis genannt wird. Ihre Errichtungszeit fiel in die Jahre zwischen 1230 und 1238. Als Baumeister der Kapelle wird wegen architektonischer Ähnlichkeiten mit der Sainte-Chapelle in Paris Pierre de Montreuil vermutet. Während des Hundertjährigen Krieges fiel die Burg in die Hände englischer Truppen unter der Führung des Schwarzen Prinzen, Edward of Woodstock. Der ließ die Anlage am 15. August 1346 niederbrennen. Nur die Kapelle blieb von dem Feuer verschont. Karl V. ließ daraufhin die Ruinen abtragen und auf ihren Fundamenten von 1364 bis 1367 eine neue Burg errichten, deren Form den Verlauf der einstigen Ringmauer nachzeichnete. Der mit dem Wiederaufbau beauftragte Architekt war Raymond du Temple. Nachdem die Gebäude errichtet waren, wurden sie mit einem breiten Wassergraben gesichert. Im viereckigen Donjon, der die südwestliche Ecke der Anlage bildete, richtete Karl V. sein königliches Studierzimmer ein. Nachdem die Burganlage 1420 erneut von englischen Truppen besetzt und im Jahr 1440 durch den Connétable de Richemont für die Franzosen zurückerobert worden war, befand sie sich in einem heruntergekommenen Zustand. König Franz I. ließ die ramponierten Gebäude während seiner Regierungszeit wiederherstellen und im Stil der Renaissance zu einem Schloss umbauen.","w":"https://de.wikipedia.org/wiki/Schloss_Saint-Germain-en-Laye"},"ch-Q912192":{"n":"Hôtel de Matignon","c":"Pariser Stadtpalais, Metonymie für das Amt des französischen Premierministers","r":"Das Hôtel de Matignon ist ein Hôtel particulier auf dem linken Ufer der Seine in Paris, im Stadtviertel Faubourg Saint-Germain. Es hat die Hausanschrift 57 Rue de Varenne. Es dient dem französischen Premierminister als Amtssitz und Residenz. Matignon steht in französischen Medienberichten als Metonymie für das Amt des Premierministers.","h":"Das luxuriöse Wohngebäude ließ im Jahr 1720 der spätere Maréchal von Montmorency, Christian Louis de Montmorency-Luxembourg, Prince de Tingry (1675–1746), Sohn des Maréchal de Luxembourg, an Stelle einer zuvor im Besitz des Barons von Pouancé befindlichen Residenz von dem Architekten Jean Courtonne errichten. Spätere Eigentümer waren ab 1723 Jacques III. de Goyon († 1725) und nach dessen Tod sein Sohn Jacques IV. Francois Léonor de Goyon, der im Jahr 1715 durch seine Heirat mit der monegassischen Erbprinzessin Louise-Hyppolite Grimaldi den Titel Prinz von Valentinois erworben hatte und von 1731 bis 1733 vorübergehend als Fürst Jacques I. von Monaco amtierte, bevor er nach dem Tod seiner Gattin zugunsten seines Sohnes Honoré III. von Monaco abdankte und bis zu seinem Lebensende in das Hôtel de Matignon zurückkehrte. Dieses kaufte im Jahr 1804 von seinen Enkeln die ehemalige Ballerina und frühere Geliebte des Herzogs von Württemberg, Anne Eléonore Sullivan geborene Franchi, die es aber bereits 1808 an Talleyrand weiterveräußerte, der es bis 1814 besaß. In jenem Jahr kam es in den Besitz von Napoléon Bonaparte, nach dem Sturz des Kaiserreiches im Tausch gegen den Élysée-Palast an die Herzogin von Bourbon († 1822), die es ihrer Nichte Adélaïde d’Orléans, der Schwester des künftigen Louis Philippe vererbte. Madame Adélaïde lebte dort bis 1830. Danach vermietete sie das Hôtel particulier. Nachdem König Louis Philippe infolge der Februarrevolution 1848 hatte abdanken und aus Frankreich fliehen müssen und das Haus Orléans nunmehr in großem Umfang seinen französischen Privatbesitz veräußerte, erwarb 1852 der Marchese Raffaele de Ferrari, Herzog von Galliera, das Hôtel de Matignon von Antoine d’Orléans, duc de Montpensier, dem jüngsten Sohn des Königs.","w":"https://de.wikipedia.org/wiki/H%C3%B4tel_Matignon"},"ch-Q13360213":{"n":"Palais de Chaillot","c":"Bauwerk in Paris, Frankreich","r":"Das Palais de Chaillot in Paris wurde von Louis-Hippolyte Boileau, Léon Azème und Jacques Carlu für die Weltausstellung 1937 auf den Fundamenten des ehemaligen Palais du Trocadéro erbaut.","w":"https://de.wikipedia.org/wiki/Palais_de_Chaillot"},"ch-Q113389":{"n":"Schloss Azay-le-Rideau","c":"Schloss in Frankreich","r":"Das Schloss Azay-le-Rideau liegt in der Gemeinde Azay-le-Rideau in Frankreich. Der zweiflügelige Renaissancebau gehört zu den bekanntesten Schlössern der Loire-Region.","w":"https://de.wikipedia.org/wiki/Schloss_Azay-le-Rideau"},"ch-Q578771":{"n":"Palais du Tau","c":"erzbischöfliche Palast in Reims, Frankreich","r":"Das Palais du Tau ist der erzbischöfliche Palast in Reims.","w":"https://de.wikipedia.org/wiki/Palais_du_Tau"},"ch-Q477613":{"n":"Schloss Villandry","c":"französisches Schloss der Renaissance im Loire-Tal","r":"Château de Villandry ist ein Schloss 15 Kilometer westlich der Stadt Tours in Frankreich. Die Gemeinde Villandry liegt am Cher und ist die letzte Gemeinde vor dessen Mündung in die Loire.","h":"Im Vorgängerbau des Schlosses, der Festung von Colombier aus dem 12. Jahrhundert, unterzeichnete Heinrich II. Plantagenet, König von England, nach seiner Niederlage gegen Philipp II. Auguste, König von Frankreich, am 4. Juli 1189 den Frieden von Colombier. Das heutige Schloss wurde im Auftrag von Jean Le Breton, Finanzminister unter Franz I., erbaut. Die gotische Festung wurde dazu 1532 bis auf die Fundamente und den Bergfried abgerissen. Das Schloss, als eines der letzten an der Loire im Renaissancestil gebauten Schlösser, wurde zusammen mit einem großen Garten 1536 fertiggestellt. Mittelalterliche Elemente wie dekorative Türmchen und Pechnasen und italienischer Einfluss fehlen fast ganz. Dieser einfachere, vollkommen französische Stil kündigt mit seiner Dachform die Schlösser Anet, Fontainebleau und den Stil der Zeit Heinrichs IV. an. 1705 übernahm der aus einer provenzalischen Familie stammende Marquis de Castellane das Schloss und ließ es nach den Komfortansprüchen des 18. Jahrhunderts umbauen. Der Garten wurde als englischer Landschaftsgarten angelegt. 1823 erwarb die Familie Hainguerlot den Besitz, der bis 1897 in Hand der Familie blieb. 1906 wurde das Schloss von Joachim Carvallo gekauft. Auch die reiche Amerikanerin Ann Coleman beteiligte sich an Kauf und Restauration. Sie ließen die französischen Gärten im Stil des 16. Jahrhunderts im Einklang mit der korrigierten Renaissance-Architektur des Schlosses anlegen. Seit 1920 ist das Schloss öffentlich zugänglich. Der heutige Besitzer, Henri Carvallo, ist der Urenkel von Joachim Carvallo.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_de_Villandry"},"ch-Q766938":{"n":"Schloss Chantilly","c":"Schloss in Frankreich","r":"Das Schloss Chantilly liegt in der französischen Kleinstadt Chantilly im Département Oise, ca. 50 Kilometer nördlich von Paris. Es ist durch seinen Park, seine Gemäldesammlung und das Musée du Cheval im Großen Marstall weithin bekannt; Schloss und Park sind für Besucher geöffnet.","h":"Die erste urkundliche Erwähnung des Schlosses Chantilly stammt aus dem Jahre 1358 im Zusammenhang mit seiner Zerstörung im Zuge des Bauernaufstandes Jacquerie und seines Wiederaufbaues durch Pierre d’Orgemont, der im Jahre 1394 beendet wurde. Im Jahre 1421, während des Hundertjährigen Krieges, belagerten englisch-bourguignonische Truppen das Schloss. Dessen Herrin Jacqueline de Paynel, Witwe von Jean de Fayel und Pierre II. d’Orgemont – dieser war in der Schlacht von Azincourt ums Leben gekommen –, musste das Schloss verlassen. Jacqueline de Paynel rettete so den Bewohnern des Schlosses das Leben; die umliegenden Dörfer wurden jedoch vollständig zerstört. 1484 gelangte ein älterer Vorgängerbau in den Besitz des Adelshauses der Montmorency und zwischen 1528 und 1551 wurde die mittelalterliche Burg vom französischen Heerführer Anne de Montmorency erheblich erweitert und zum Renaissance-Schloss umgebaut, einem unregelmäßigen Dreieck mit Türmen und einer Doppelturm-Toranlage. In den folgenden dreihundert Jahren wurden zahlreiche bauliche Veränderungen vorgenommen. Mit seinem Enkel Henri II. de Montmorency, der 1632 hingerichtet wurde, weil er sich an einem Aufstand gegen Kardinal Richelieu beteiligt hatte, erlosch die Hauptlinie der Montmorency. Seine Güter – darunter Chantilly und Schloss Écouen – wurden zunächst von Ludwig XIII. konfisziert, dann aber, da Henri II. kinderlos war, seiner Schwester Charlotte-Marguerite de Montmorency zurückgegeben. Diese war mit einem Cousin des Königs verheiratet, Henri II. de Bourbon, prince de Condé, und einst auch kurzzeitig die Geliebte seines Vaters Heinrich IV. gewesen. Sie erbte den Titel einer Herzogin von Montmorency.","w":"https://de.wikipedia.org/wiki/Schloss_Chantilly"},"ch-Q1122731":{"n":"Schloss Clos Lucé","c":"Schloss in Frankreich","r":"Das Schloss Le Clos Lucé befindet sich in Amboise, etwa 500 Meter entfernt vom Loireschloss Amboise, zu dem eine unterirdische Verbindung besteht. Es ist der Ort des letzten Wirkens und Sterbeort des Künstlers und Universalgelehrten Leonardo da Vinci.","h":"Erbaut wurde Clos Lucé von Étienne le Loup in der Mitte des 15. Jahrhunderts. Im Jahre 1490 erwarb es der französische König Karl VIII. für seine Frau Anne de Bretagne. Später wurde es von König Franz I. und seiner Schwester Margarete von Navarra benutzt, die dort begann, ihr Buch L'Heptaméron zu schreiben. Im Jahre 1516 lud Franz I. Leonardo da Vinci nach Amboise ein und überließ ihm Clos Lucé als einen Platz zum Leben und Arbeiten. Leonardo zog ein, begleitet von seinen Geliebten Salaj und Francesco Melzi sowie einem ergebenen Diener. Er brachte drei Gemälde mit: die Mona Lisa, Anna selbdritt und Johannes der Täufer. Er lebte dort drei Jahre lang bis zu seinem Tode am 2. Mai 1519.","w":"https://de.wikipedia.org/wiki/Schloss_Le_Clos_Luc%C3%A9"},"ch-Q912447":{"n":"Burg Chinon","c":"Burg in Frankreich","r":"Die Burg Chinon, franz. Château de Chinon, zählt – obwohl sie eine Burg ist – zu den Schlössern der Loire. Sie befindet sich in der Stadt Chinon im französischen Département Indre-et-Loire. Die Höhenburg liegt auf einem dreiteiligen Felsen oberhalb der Vienne, einem Zufluss der Loire.","h":"Eine römische Festung bestand hier bereits im 5. Jahrhundert. Auf dem Felsen über Chinon wurde von den Grafen von Blois im 10. Jahrhundert eine feste Burg errichtet, von der nichts erhalten blieb. 1044 fiel die Anlage nach der Schlacht von Saint-Martin-le-Beau an die Grafen von Anjou und damit an die Könige von England. Sie ließen die mittleren Türme bauen. König Heinrich II. starb hier im Jahr 1189, nachdem er sie vollständig zur Grenzfestung gegen den französischen König hatte erneuern lassen. 1205 wurde Chinon während eines Französisch-Englischen Kriegs nach einjähriger Belagerung vom französischen König Philippe II. Auguste eingenommen und von ihm und seinen Nachfolgern ausgebaut, sodass sie ihr heutiges Aussehen erhielt. Im Laufe des Hundertjährigen Kriegs ging Chinon für die Engländer verloren. König Karl VII. ließ während seiner Residenzzeit einen großen Saal bauen. Seine Geliebte Agnès Sorel lebte in einem kleinen Herrenhaus nahe dem Schloss. Am 9. März 1429 fand hier die Begegnung Jeanne d’Arcs mit dem König statt, der hier die Generalstände versammelt hatte. Hier überzeugte sie ihn, dass er Orléans zu Hilfe kommen müsse. Bis 1459 blieb der französische Königshof in Chinon. 1562 gelangte die Burg in den Besitz der Hugenotten und wurde unter Heinrich IV. zu einem Gefängnis. 1633 ging die Burg in den Besitz des Kardinals Richelieu über, dessen Erben sie bis zur Französischen Revolution hielten. Danach verfiel sie, und auch einige Sicherungsmaßnahmen des 19. Jahrhunderts durch Napoleon III. konnten nicht mehr viel retten. Zwischen 2003 und 2010 war die Burg Gegenstand einer umfangreichen Ausgrabung und Restaurierung, die 14.500.000 € kosteten.","w":"https://de.wikipedia.org/wiki/Burg_Chinon"},"ch-Q1048155":{"n":"Schloss Angers","c":"Schloss in Frankreich","r":"Das Schloss Angers liegt am Fluss Maine, in der Nähe des Zusammenflusses von Maine und Loire. Angers ist heute die Hauptstadt des Départements Maine-et-Loire in der Region Pays de la Loire; sie war die alte Hauptstadt des Anjou.","w":"https://de.wikipedia.org/wiki/Schloss_Angers"},"ch-Q684846":{"n":"Schloss Malmaison","c":"Schloss nahe Paris in Frankreich","r":"Das Schloss Malmaison in Rueil-Malmaison westlich von Paris war Wohnsitz von Kaiser Napoleon und seiner Frau Joséphine. Während das Kaiserpaar offiziell im Palais des Tuileries Hof hielt, wurde Malmaison zu ihrem privaten Rückzugsort.","h":"Das mala-mansio wird im 6. Jahrhundert zum ersten Mal als königliche Villa (eines Sohnes von Chlodwig I.) erwähnt. Aus mala-mansio wurde dann Malmaison (deutsch: „das schlechte Haus“). Einige hundert Jahre später ließ sich ein schottischer Ritter auf dem Anwesen nieder. Im 14. Jahrhundert geriet es in den Besitz des königlichen Beraters Robert de Lorris, dann erwarb es Guillaume Goudet. Das eigentliche Herrenhaus wurde erst Anfang des 17. Jahrhunderts von dessen Nachfahren erbaut. Seit September 1793 wohnte Joséphine de Beauharnais, die spätere erste Ehefrau Napoleons, in Sichtweite von Malmaison. Das Schloss befand sich von ihrem Wohnsitz in Croissy-sur-Seine aus gesehen auf der gegenüberliegenden Seite der Seine. Malmaison lag an einer landschaftlich reizvollen Lage. In der Nähe dehnten sich bewaldete Hügel bis fast zum Fluss aus. Auch existierten große Rasenflächen – ideal für die Anlage von Blumengärten. Auch die politischen Rahmenbedingungen schienen günstig für Joséphine zu sein. Da die Besitztümer von Adel und Klerus während der Französischen Revolution enteignet worden waren, standen zahlreiche Landgüter inklusive der umgebenden Gärten zum Verkauf. Auch Napoleon, mit dem Joséphine seit 1796 verheiratet war, wollte sein Vermögen durch Landbesitz bei Paris absichern. Malmaison gehörte jedoch bereits einer wohlhabenden Pariser Bankiersfamilie, die ihren Landsitz zu keinem günstigen Preis verkaufen wollte und erst kurz vorher in Umbauten investiert hatte. Auf Drängen Joséphines besichtigte Napoleon kurz vor seinem Ägyptenfeldzug Malmaison. Er bot der Familie Molay 250.000 Franc für das Schloss an. Diese forderte allerdings einen Mindestpreis von 300.000 Franc, was Napoleon zurückwies.","w":"https://de.wikipedia.org/wiki/Schloss_Malmaison"},"ch-Q1150222":{"n":"Schloss Saumur","c":"Schloss in Frankreich","r":"Das Schloss Saumur steht in der gleichnamigen französischen Stadt Saumur zwischen Nantes und Tours im Département Maine-et-Loire auf einem Felsplateau nahe dem Zusammenfluss der Loire und des Thouet.","w":"https://de.wikipedia.org/wiki/Schloss_Saumur"},"ch-Q376699":{"n":"Schloss Pierrefonds","c":"Schloss in Frankreich","r":"Schloss Pierrefonds ist eine ursprünglich aus dem Mittelalter stammende Schlossanlage, die im 19. Jahrhundert von Eugène Viollet-le-Duc für Napoleon III. als Privatresidenz rekonstruiert und ausgebaut wurde.","h":"Eine Burganlage ist an dieser Stelle im 12. Jahrhundert nachweisbar. 1392 erhob König Karl VI. die Grafschaft Valois, zu der Pierrefonds gehörte, zum Herzogtum und gab sie seinem Bruder Louis d’Orléans. 1393 bis 1407 wurde daraufhin für letzteren die Burg um- und ausgebaut. Leiter dieses Vorhabens war der Hofarchitekt Jean le Noir. Im März 1617 wurde die Burg durch Truppen von Kardinal Richelieu belagert und eingenommen. Der damalige Burgherr François-Annibal d’Estrées, der Bruder Gabrielles d’Estrées, war Mitglied einer Gruppe unzufriedener französischer Adliger, die gegen den jungen König Ludwig XIII. aufbegehrten und von Henri II. de Bourbon angeführt wurden. Die Burg wurde daraufhin weitgehend, aber nicht vollständig zerstört. Der Gebäudekomplex blieb über 200 Jahre Ruine. Napoleon Bonaparte erwarb ihn 1810 für weniger als 3000 Francs. Im August 1832 gab der Bürgerkönig Louis Philippe hier ein Bankett anlässlich der Heirat seiner Tochter Louise mit Leopold I. von Belgien. Jean-Baptiste Camille Corot malte die Ruine mehrfach zwischen 1834 und 1866. Louis-Napoléon Bonaparte, der spätere Kaiser Napoleon III., besuchte die Burgruine 1850. 1857 gab er Eugène Viollet-le-Duc den Auftrag zur Rekonstruktion und Restaurierung. 1861 erweiterte er das Projekt. Auf der Basis der vorhandenen Ruinen sollte eine kaiserliche Residenz geschaffen werden. Im Sommer 1867 zeigte Napoleon III. dem bayerischen König Ludwig II., der anlässlich der Weltausstellung in Paris war, die Baustelle. Dieser wollte sich Anregungen für seinen geplanten Neubau in Neuschwanstein holen, nachdem er zwei Monate zuvor bereits die wiederaufgebaute Wartburg besichtigt hatte. Sechs Jahre nach dem Tod Viollet-le-Ducs 1885 kam es zum endgültigen Stillstand der Arbeiten, die schon durch den Sturz Napoléons III.","w":"https://de.wikipedia.org/wiki/Schloss_Pierrefonds"},"ch-Q1552366":{"n":"Hohkönigsburg","c":"Burg in Elsass, Frankreich","r":"Die Hohkönigsburg ist eine Höhenburg in der elsässischen Gemeinde Orschwiller bei Sélestat. Im 12. Jahrhundert vom schwäbischen Herzog Friedrich II. erbaut und im 17. Jahrhundert zur Ruine verfallen, ließ der deutsche Kaiser und preußische König Wilhelm II. die Anlage vom Architekten und Denkmalpfleger Bodo Ebhardt 1901 bis 1908 wiederherstellen. Mit rund 500.000 Besuchern im Jahr gehört die Hohkönigsburg zu den beliebtesten Sehenswürdigkeiten Frankreichs.","h":"Der Stophanberch (Staufenberg), auf welchem die Burg liegt, wird bereits 774 (als Schenkung Karls des Großen) und 854 beurkundet und befand sich ursprünglich im Besitz der Abtei Saint Denis. Die Burg wurde in der ersten Hälfte des 12. Jahrhunderts als staufische Reichsburg erbaut und 1147 als Castrum Estufin erstmals urkundlich erwähnt. Von der Burg aus konnten die Orte und Handelswege in diesem Teil des Oberrheingrabens beherrscht werden. 1147 tauchte erstmals der Name Burg Staufen auf, die von Herzog Friedrich II., dem Vater des deutschen Königs Friedrich Barbarossa, gegründet worden sein soll. Aus staufischer Zeit sind unter anderem eine vermauerte Fensterarkade und ein Löwenrelief erhalten. Ab 1192 wurde der Name Kinzburg (Königsburg) verwendet. Im 13. Jahrhundert wurde der Herzog von Lothringen Eigentümer der Burg, der sie als Lehen den Grafen von Werd gab. 1359 verkauften die Grafen von Oettingen die Burg an den Bischof von Straßburg. 1454 eroberte der pfälzische Kurfürst Friedrich der Siegreiche die Burg, 1462 wurde sie wegen Raubritterei zerstört. 1479 gab Kaiser Friedrich III. die Burg als Lehnsgut an den Schweizer Grafen Oswald von Thierstein († 1488) und dessen Bruder Wilhelm. 1517 starben die Grafen von Thierstein aus; deshalb fiel die Burg an Kaiser Maximilian I. und somit an die Habsburger zurück. Während des Dreißigjährigen Krieges wurde sie 52 Tage von den Schweden belagert, am 7. September 1633 erobert und in Brand gesetzt. Zwischen 1648 und 1865 hatte die Ruine verschiedene Eigentümer. 1865 wurde sie Eigentum der Stadt Schlettstadt. In der Romantik wurde die Ruine wiederentdeckt. Christian Moritz Engelhardt beschrieb sie in seinen Reiseskizzen durch die Vogesen (1821).","w":"https://de.wikipedia.org/wiki/Hohk%C3%B6nigsburg"},"ch-Q185479":{"n":"Schloss Ussé","c":"Schloss in Frankreich","r":"Das Schloss Ussé ist eine Schlossanlage in der französischen Ortschaft Rigny-Ussé etwa zehn Kilometer nord-östlich von Chinon am südlichen Ufer der Indre, einem Nebenfluss der Loire. Es gehört zu den bekanntesten der französischen Loireschlösser und ist ein beliebtes Ausflugsziel am Rand des Forstes von Chinon im Département Indre-et-Loire, Region Centre-Val de Loire. Es soll den französischen Schriftsteller Charles Perrault bei einem seiner Aufenthalte zu seiner Erzählung La belle au bois dormant, der französischen Version von Dornröschen, inspiriert haben.","h":"Die heutige Anlage geht auf eine mittelalterliche Anlage zurück, die im Kontext der Auseinandersetzungen zwischen den zwei großen Grafschaften Anjou und Blois gegründet wurde. Ussé – im Laufe der Jahrhunderte auch Ucerum, Uceum, Uciacus und Uceium geschrieben – lag an der Grenze zwischen diesen beiden Territorien und war deshalb immer wieder umkämpft. Der Platz war jedoch schon in der Frühzeit besiedelt, was gallorömische Funde beweisen. Er nahm einen strategisch wichtigen Punkt ein, von dem aus sowohl die Straße nach Chinon als auch der Schiffsverkehr auf der Indre und der Loire kontrolliert werden konnten. 1004 war der 950 erstmals urkundlich erwähnte Guelduin I. (auch Gelduin, Gilduin, Geudouin und Geulduin geschrieben), der Teufel von Saumur genannt, Herr von Ussé. Er war ein treuer Vasall der Grafen von Blois Thibault le Tricheur sowie dessen Sohn Eudes I. und kämpfte für sie gegen ihren Widersacher Fulko Nerra, den Grafen von Anjou. Nachdem er die Burg Saumur im Kampf gegen Fulko verloren hatte, ließ er im Gegenzug die Burg in Ussé – damals noch eine Holzkonstruktion – weiter ausbauen und befestigen. Sein Sohn Guelduin II., der ab 1040 seinem Vater als Herr von Ussé folgte, ließ eine erste befestigte Anlage aus Stein errichten. Um 1350 heiratete Jeanne d’Ussé Briant IV. de Montéjean und brachte Ussé an ihren Mann. Im Jahr 1462 war der Admiral Jean V. de Bueil Burgherr von Ussé. Wie die Anlage in seinen Besitz kam, ist bisher nicht geklärt. Fest steht aber, dass er in jenem Jahr damit begann, auf den Fundamenten der alten Burg aus dem 11. Jahrhundert das heutige Schloss zu bauen. Seine Errichtung geschah somit zeitgleich zum Bau der Schlösser Chaumont, Langeais und Le Plessis-Bourré.","w":"https://de.wikipedia.org/wiki/Schloss_Uss%C3%A9"},"ch-Q1143558":{"n":"Schloss Langeais","c":"Schloss in Frankreich","r":"Schloss Langeais ist ein Schloss, das über der Stadt Langeais am rechten Ufer der Loire in Frankreich thront.","h":"Das neue Schloss entstand von 1465 an unterhalb der Festung zum Schutz der Krondomäne. Erbauer war Jean Bourré, Geheimer Rat Ludwigs XI., auf Befehl des Königs. Eine Zeit lang war das Schloss im Besitz der Krone und wurde ab 1631 den jeweiligen Schlossherren nur zur Nutzung übertragen. Das epochale Großereignis im Schloss war die glanzvolle Hochzeit von Karl VIII. mit Anne de Bretagne, die 1491 in Langeais stattfand. Sie hatte Auswirkungen sowohl auf die Geschichte Frankreichs als auch auf die Europas, weil die Bretagne dadurch an Frankreich fiel, und nicht an das Haus Habsburg. Auch für die Zeit nach dem plötzlichen Tod Karls VIII. war diese Vereinigung sichergestellt worden. Für den Besucher von heute wird die aufwändige Hochzeit im Großen Saal des Schlosses nachgestellt und im Rahmen einer Animation (auf Französisch) noch einmal zum Leben erweckt. Das Schloss selbst liegt mitten in der Stadt und beeindruckt den Neuankömmling durch drei mächtige Rundtürme und den Zugang über die wiederhergestellte Zugbrücke. Die Hofseite wirkt mit ihren Treppentürmen und Lukarnen weniger streng und wehrhaft. Der Garten des Schlosses wurde nach zeitgenössischen Miniaturen aus dem 15. Jahrhundert rekonstruiert, und von einer kleinen Anhöhe hat man einen schönen Rundblick über Schloss und Stadt. Der heutige exzellente Zustand des Schlosses ist der Hingabe von Jacques Siegfried zu verdanken, der ab 1886 sein Geld und seine Zeit darauf verwandte, baulich und hinsichtlich der Einrichtung das 15. und 16. Jahrhundert wieder auferstehen zu lassen. Am Ende vermachte er Schloss mitsamt Einrichtung und Kunstgegenständen dem Institut de France. 15 Räume des Schlosses sind komplett möbliert. Originale Sitzmöbel, Tische, Schränke, Truhen und Betten im gotischen Flamboyant-Stil des 15. und 16.","w":"https://de.wikipedia.org/wiki/Schloss_Langeais"},"ch-Q522779":{"n":"Schloss Chaumont","c":"französisches Schloss im Département Loir-et-Cher","r":"Schloss Chaumont liegt südwestlich der Stadt Blois in der französischen Gemeinde Chaumont-sur-Loire im Département Loir-et-Cher in der Region Centre-Val de Loire. Auf einer steilen Böschung hoch über der Loire bildet es die Kulisse für das Dorf, dessen Häuser in einer langen Reihe das Flussufer säumen.","h":"Bereits im Mittelalter gab es hier eine Burganlage. Graf Odo I. von Blois hatte sie im 10. Jahrhundert erbaut, um Blois vor den Angriffen von Foulques Nerra, Graf von Anjou, zu schützen. Später überließ er es dem als Vasall für das Haus Blois kämpfenden normannischen Ritter Gelduin, der die Festung verstärken ließ. Gelduins Sohn, Geoffroy, hatte keinen männlichen Nachfolger und überließ das Erbe seiner Großnichte, Denise de Fougères. Die verheiratete sich 1054 mit Sulpice I. von Amboise, so dass der Besitz auf diese Weise an die Familie von Amboise fiel, die die Burg für die nächsten fünf Jahrhunderte besitzen sollte. Hugues I., Sire d’Amboise, zweiter Herr von Chaumont, ersetzte hier wie in Montrichard die Holzkonstruktion durch einen Steinturm und stärkte damit die Verteidigung des Dreiecks Amboise-Chaumont-Montrichard. Im 12. Jahrhundert wurde das Schloss trotzdem geschleift, danach aber wieder aufgebaut. Ein denkwürdiges Ereignis war im Jahr 1170 die Zusammenkunft zwischen Heinrich II. von England und Thomas Becket, Erzbischof von Canterbury. Man las in der Kapelle eine Totenmesse, bei der man nach der Liturgie nicht den Friedenskuß zu wechseln brauchte, was als zu offensichtliche Heuchelei angesehen wurde. Bekanntermaßen ließ Becket sofort nach seiner Rückkehr nach England den König mit dem kirchlichen Bann belegen und wurde wenig später in seiner Kathedrale durch einen vom König gedungenen Mörder erdolcht. Im 13. Jahrhundert entsprach die Erbfolge den jeweiligen Verwandtschaftsverhältnissen, bis sich im 14. Jahrhundert die Linie „Chaumont d'Amboise“ abzweigte, während die ältere Linie Amboise behielt. Der Herr von Schloss Chaumont, Pierre d’Amboise, war einer der Verschwörer gegen den König in der „Liga des Allgemeinwohls“ (Ligue du Bien public).","w":"https://de.wikipedia.org/wiki/Schloss_Chaumont"},"ch-Q1141846":{"n":"Schloss Cheverny","c":"Schloss in Frankreich, in der Nähe der Stadt Tours","r":"Schloss Cheverny ist ein Loireschloss in der Gemeinde Cheverny, wenige Kilometer südlich der Stadt Blois im Département Loir-et-Cher der Region Centre-Val de Loire in Frankreich.","w":"https://de.wikipedia.org/wiki/Schloss_Cheverny"},"ch-Q1011806":{"n":"Burg Foix","c":"Burg in Frankreich","r":"Die Burg Foix ist die Ruine einer mittelalterlichen Felsenburganlage im Süden Frankreichs, die sich über die Stadt Foix im Département Ariège erhebt. Sie wurde 1840 vom französischen Kulturministerium als Monument historique eingestuft und ist damit denkmalgeschützt.","h":"Überreste frühester militärischer Nutzungen des Felsens von Foix (französisch: Roc de Foix), der den Zusammenfluss des Arget in die Ariège beherrscht, sind aus dem 7. Jahrhundert erhalten. Im Jahr 987 wird erstmals eine Burg auf dem Felsen schriftlich erwähnt, die dem Grafen Roger dem Alten von Carcassonne gehörte. Dieser vermachte sie seinem jüngeren Sohn Bernard Roger, der das Grafenhaus von Foix begründete und den ersten Turm der Burg, genannt Tour d'Arget, errichten ließ. Graf Roger II. baute den zweiten Turm, der wegen seines spitz zulaufenden Eckturms Tour Pointue genannt wird. Im 12. Jahrhundert wurde die Burg ein Zentrum der höfischen Welt Okzitaniens. Im Canso de la Crosada wurde ihre zugeschriebene Stärke von einem anonymen Trobador gewürdigt: „E·l castels es tant fortz qu’el mezeis se defent“ (Die Burg ist so stark, sie verteidigt sich selbst) Aufgrund der Unterstützung des Grafenhauses für die häretische Sekte der Katharer wurde auch Foix ein Ziel des Albigenserkreuzzuges. Dabei konnte die Burg 1211 und 1212 erfolgreich gegen den Kreuzfahrer Simon IV. de Montfort verteidigt werden. Nach der Niederlage in der Schlacht bei Muret 1213 gab Graf Raimund Roger die Burg jedoch freiwillig auf, erhielt sie aber schon im Folgejahr zurück. Im Jahr 1272 wurde die Burg von König Philipp III. von Frankreich belagert, um den Grafen Roger Bernard III. zu unterwerfen. Der Graf kapitulierte nach zweitägiger Belagerung vor der Übermacht, aber ohne dass der König die Burg gewaltsam einnehmen konnte. Unter den folgenden Grafen verlor die Burg wegen ihrer Unbequemlichkeit an Bedeutung und wurde von den repräsentativeren Schlössern in Orthez und Pau als Hauptresidenz abgelöst. Für Graf Gaston II. diente sie als Kerker für seine Mutter. Graf Gaston IV.","w":"https://de.wikipedia.org/wiki/Burg_Foix"},"ch-Q1013191":{"n":"Burg Montségur","c":"Burg in Frankreich","r":"Der Montségur ist ein 1207 Meter hoher felsiger Berg am Nordhang der östlichen Pyrenäen, etwa 20 km südöstlich der Stadt Foix, im Norden der Gemeinde Montségur im Département Ariège der Region Okzitanien in Frankreich. Auf seinem Gipfel stand die Katharerburg Montségur, die wohl bekannteste Burg der Katharer. Der später an ihrer Stelle errichtete Festungsbau ist heute eine Ruine.","h":"Der prominente Felsgipfel trägt Spuren menschlicher Besiedlung, die von steinzeitlichen über bronzezeitliche und vorrömische eisenzeitliche der Latènezeit zu Funden spätrömischer Münzen reichen. Über die Anlagen spätantiker und frühmittelalterlicher Siedlungen auf dem mont segur (okzitanisch; von lateinisch mons securus ‚sicherer Berg‘) ist wenig bekannt. Im Hochmittelalter befand sich eine Gipfelburg auf dem kuppelartigen Felsen, dem Pog, die Mitte des 12. Jahrhunderts in verfallenem Zustand war. Um das Jahr 1204 ließ Raimund de Péreille sie wiederaufbauen und 1232 die Befestigung der Höhensiedlung verstärken. Im selben Jahr wurde auf Beschluss des Katharerbischofs von Toulouse, Guilhabert de Castres, Montségur Sitz und Hauptstadt der katharischen Kirche. Nach dem Albigenserkreuzzug (1209–1229), den Papst Innozenz III. gegen die als häretisch betrachtete Glaubensgemeinschaft der Katharer in Okzitanien initiiert hatte, wurde die Burg Montségur das wichtigste Refugium der katharischen Gemeinde. Ihre Verfolgung durch die römisch-katholische Kirche verschärfte Papst Gregor IX., indem er dafür Sonderbeauftragte als Inquisitoren berief. In Toulouse war der Dominikaner Guillaume Arnaud Mitglied des Tribunals, das 1241 über drei Glaubensabtrünnige Todesurteile verhängte, deren Vollstreckung der weltlichen Justiz oblag. Jener und sein Amtskollege fielen 1242 in Avignonet einem Attentat zu Opfer, das die drei Verurteilten und weitere Glaubensgenossen verübten, mit Unterstützung von Pierre Roger II. de Mirepoix, dem Gouverneur der Festung Montségur. Daraufhin wurde der Montségur 1243 unter Führung des königlichen Seneschalls von Carcassonne durch Soldaten sowie Kreuzritter des Erzbischofs von Narbonne in Angriff genommen und belagert.","w":"https://de.wikipedia.org/wiki/Burg_Monts%C3%A9gur"},"ch-Q1470842":{"n":"Schloss Sully-sur-Loire","c":"Schloss in Frankreich","r":"Das Schloss Sully-sur-Loire steht in dem französischen Ort Sully-sur-Loire am Ostrand der Sologne. Es zählt zu den Schlössern der Loire und wurde gemeinsam mit dem Tal der Loire im Jahr 2000 von der UNESCO in die Liste des Weltkulturerbes aufgenommen.","w":"https://de.wikipedia.org/wiki/Schloss_Sully-sur-Loire"},"ch-Q786075":{"n":"Schloss Brissac","c":"Schloss in Frankreich","r":"Das Schloss Brissac befindet sich in der französischen Stadt Brissac-Quincé im Département Maine-et-Loire, rund 15 Kilometer südlich von Angers gelegen. Das Schloss verfügt über sieben Stockwerke und 204 Räume und trägt den Spitznamen „Riese der Loire“.","w":"https://de.wikipedia.org/wiki/Schloss_Brissac"},"ch-Q1557685":{"n":"Guédelon","c":"Experimentelle Burg in Frankreich","r":"Guédelon ist ein Projekt zur Errichtung einer Burg auf dem Gebiet der französischen Gemeinde Treigny im Département Yonne. Nach den Prinzipien der experimentellen Archäologie werden bei diesem Projekt nur Techniken aus dem 13. Jahrhundert angewandt, der Baubeginn war 1997. Die Fertigstellung der Burg war für das Jahr 2023 geplant, inzwischen wird ca. 2030 anvisiert.","w":"https://de.wikipedia.org/wiki/Gu%C3%A9delon"},"ch-Q1289258":{"n":"Schloss Nantes","c":"Schloss in Frankreich","r":"Das Schloss Nantes, in Frankreich Château des ducs de Bretagne genannt, ist eine weitläufige und stark befestigte Schlossanlage in Nantes, am rechten Ufer der Loire, die den Burggraben mit Wasser versorgte. Sie war ab dem 13. Jahrhundert die Residenz der bretonischen Herzöge und wurde im 16. Jahrhundert zur Residenz der französischen Könige in der Bretagne. 1841 wurde das Schloss als Monument historique unter Denkmalschutz gestellt.","h":"Ab 1207 ließ Guy de Thouars, Witwer der Herzogin Constance, am Fuß der gallorömischen Stadtmauer, die seinerzeit lediglich das historische Zentrum von Nantes, Le Bouffay, umgab, die erste Burg bauen. Um den Machtanspruch der Herzöge gegenüber den Grafen von Nantes und den Bischöfen von Nantes zu betonen, wurde die Chastel de la Tour Neuve genannt. Pierre Mauclerc und sein Sohn Jean I. verstärkten sowohl die Burg als auch die städtischen Befestigungen. Als zentrales Element der Verteidigungsanlagen schützte sie einen Arm der Loire als den Ort der meisten wirtschaftlichen Aktivitäten. In der zweiten Hälfte des 14. Jahrhunderts wurde das Chastel de la Tour Neuve von Jean IV. erweitert. Aus dieser Zeit stammt auch der polygonale Alte Donjon (französisch: Vieux Donjon), der als einziger Rest der alten Burg erhalten blieb. 1466 entschied sich François II. für den Bau eines neuen Schlosses. Der Bau sollte nicht nur Hauptresidenz des herzoglichen Hofes sein, sondern auch eine Festung, mit deren Hilfe er der Königsgewalt widerstehen konnte. Die Hofseite zeigt eine Residenz aus weißem Tuffstein (das Grand Gouvernement, der Tour de la Couronne d’Or, das Grand Logis), die Außenseite sieben massive Türme aus Schiefer und Granit, die durch Kurtinen und einen 500 Meter langen Wehrgang verbunden sind. Nach dem Tod des Herzogs 1488 führte seine Tochter Anne de Bretagne, die spätere Königin von Frankreich, die Arbeiten weiter. Sie verstärkte die Befestigungen vor allem an der Flussseite und ließ den Tour du Fer à Cheval bauen, eine Bastion für die Artillerie. 1514 erbte ihre Tochter Claude de France das Schloss, die im Jahr darauf den französischen König Franz I. heiraten sollte.","w":"https://de.wikipedia.org/wiki/Schloss_Nantes"},"ch-Q648534":{"n":"Schloss Rambouillet","c":"Schloss in Frankreich","r":"Schloss Rambouillet ist ein Schloss im gleichnamigen Ort Rambouillet etwa 50 Kilometer südwestlich von Paris in Frankreich.","h":"Erbaut wurde das Schloss im Jahr 1368 von Jean Bernier. Am 31. März 1547 starb König Franz I. im Schloss. König Ludwig XVI. erwarb das Schloss im Jahr 1783 als Privatresidenz. Es war von 1896 bis 2009 die Sommerresidenz der französischen Präsidenten. 1940 bis 1944 waren Soldaten der Wehrmacht im Schloss stationiert. Seit 2009 wird das Schloss vom Centre des monuments nationaux verwaltet und kann besichtigt werden.","w":"https://de.wikipedia.org/wiki/Schloss_Rambouillet"},"ch-Q1061469":{"n":"Château Mouton-Rothschild","c":"Weingut in Frankreich","r":"Das Château Mouton Rothschild in Pauillac bei Bordeaux ist eines der berühmtesten Weingüter der Welt. Es liegt im Norden der Gemeinde Pauillac, die Teil der übergeordneten Appellation Haut-Médoc ist.","h":"Auch wenn die wahre Geschichte des heute bekannten Gutes mit dem Jahr 1922 beginnt (→ siehe Kapitel Die Ära Philippe de Rothschild), lassen sich die Besitzverhältnisse der landwirtschaftlichen Nutzflächen bis in das frühe 14. Jahrhundert zurückverfolgen. Im Jahr 1311 gehörten die Flächen dem Lehnsherrn Pons de Castillon. In der Folge wurde der Besitz in der Familie weitervererbt. Im 15. Jahrhundert kommen die Ländereien an Humphrey, Duke of Gloucester, den jüngeren Bruder von Heinrich V. Nach der englischen Niederlage im Hundertjährigen Krieg ging der vormals englische Besitz in französische Hände über. Über die Familie Foix ging ein kleiner Besitz an den Notar Jacques de Ségur. Damals gehörten nicht nur kleinere Parzellen des heutigen Châteaus zu den Ländereien. Jacques de Ségur legte auch ab 1670 die ersten Rebflächen auf dem Gelände des heutigen Château Lafite Rothschild an. Sein Sohn Alexandre heiratete im Jahr 1695 die Erbin von Château Latour. Aus dieser Ehe ging der Sohn Nicolas-Alexandre de Ségur (1697–1755) hervor. Nachdem Nicolas-Alexandre den Besitz von Mouton im Jahr 1717 erweiterte und Château Calon-Ségur kaufte, verkaufte er Mouton bereits 1720 (andere Quellen nennen das Jahr 1725) an Joseph de Brane und leitete damit die Trennung von Mouton und Lafite ein. Ein vorhandenes Gutsgebäude ging jedoch an Dominique Armailhacq, den damaligen Besitzer von Château d’Armailhac. Joseph de Brane nannte seinen Besitz fortan Château Brane-Mouton. Unter der Führung der Familie Brane kannte das Weingut, das über kein Hauptgebäude verfügte, eine Blüte. Aus den Unterlagen des Bordelaiser Weinhandels des späten 18.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Mouton_Rothschild"},"ch-Q1067494":{"n":"Temple","c":"mittelalterliche Festung im heutigen III. Arrondissement in Paris","r":"Temple [tɑ̃pl(ə)] ist die Bezeichnung sowohl für das seinerzeit außerhalb von Paris gelegene Ordensgebiet Ville-Neuve du Temple, in dem sich die Templer nach dem Fall Akkons im Jahre 1291 niederließen, als auch für den dort errichteten Bergfried tour du Temple oder donjon du Temple, in dem unter Philipp dem Schönen der französische Staatsschatz gelagert wurde. Die Bezeichnung ging schließlich auf das 3. Arrondissement über, in dessen Bereich das Ordensgebiet lag. Von den Gebäuden blieb nichts erhalten.","h":"Die Templer hatten ihr Haus in Paris, den Temple, ab etwa 1130 bei Saint-Jean-en-Grève. Ein Nouveau Temple hinter Saint-Gervais ersetzte bald den Vieux Temple. Nach dem Fall Akkons im Jahre 1291 war der Temple die gewöhnliche Residenz des Großmeisters. Am Morgen des 13. Oktober 1307 begann die Verhaftungswelle gegen Mitglieder des Templerordens, die auch den Temple in Paris erfasst. Hier wurden 138 von den 546 Templern in Paris festgenommen. Da der Verhaftungsbefehl auch die Enteignung des als wertvoll eingeschätzten Templerschatzes beinhaltete, vermuteten die Milizen des Königs den Goldschatz im Temple, suchten ihn hier jedoch vergebens. Nach dem Fall der Templer, den Prozessen gegen die wichtigsten Amtsinhaber wie Jacques de Molay und andere durch Philipp den Schönen ab Juni 1308 und vor allem nach der päpstlichen Bulle Vox in excelso von 1314 wurde das Gebiet dem Johanniterorden übergeben, der dort bis zur Säkularisation während der Französischen Revolution 1791 die Gebietshoheit innehatte. Dieser Ordensdistrikt, der Enclos du Temple, befand sich im Nordosten des Marais. Das anfangs noch durch eine Mauer vom Rest der Stadt abgegrenzte Gebiet entwickelte sich während des 17. und 18. Jahrhunderts durch den Bau von hôtels particuliers, Straßen und Gewerbeflächen, die neben den Ordensgebäuden zu einer Stadt in der Stadt heranwuchsen. Die mittelalterliche Ummauerung wurde 1667 abgerissen. Die aus dem Mittelalter stammenden Privilegien wie zum Beispiel die Zunftfreiheit und das Kirchenasyl zogen Menschen aus unterschiedlichsten Schichten in den Temple: Neben den Ordensbrüdern bewohnten freie Händler, Gewerbetreibende, Adelige und Bürger, die Schutz vor der königlichen Polizei suchten, die etwa 125 Hektar an der Rue du Temple.","w":"https://de.wikipedia.org/wiki/Temple_(Paris)"},"ch-Q1011026":{"n":"Burg Beynac","c":"Burg in Frankreich","r":"Die Burg Beynac ist eine mittelalterliche Höhenburg in der südfranzösischen Gemeinde Beynac-et-Cazenac in der Region Nouvelle-Aquitaine. Sie zählt heute zu den besterhaltenen Burgen Frankreichs. Im 12. Jahrhundert als bloßer Bergfried auf einem 150 Meter über der Dordogne erhabenen und schwer zugänglichen Kalksteinplateau errichtet, diente die Anlage als ein strategisch optimaler Beobachtungs- und Verteidigungsposten.","h":"Nach ihrer Errichtung durch Maynard de Beynac bemächtigte sich 1194 Richard Löwenherz in seiner Eigenschaft als Herzog von Aquitanien kurzzeitig der Burg und vertraute sie dem königlichen Statthalter Marchadier an. Nach dem Tod Richards 1199 ging die Wehranlage wieder in den Besitz des lokalen Adels über. Im gegen die Katharer gerichteten Albigenserkreuzzug wurde sie 1214 von Simon IV. de Montfort eingenommen und geschleift. Durch den Vertrag von Paris 1259, der die Besitzansprüche der englischen Krone in Frankreich regelte, wurde die Burganlage englisch. Mit der Besetzung des letzten englischen Festlandbesitzes, des Herzogtums Guyenne durch König Philipp VI. 1337 und dem Beginn des Hundertjährigen Krieges wechselte die Festung Beynac abermals in französisches Lehen. In den nun folgenden Jahren war die Burg Beynac zusammen mit den umliegenden Burgen Marqueyssac, Fayrac und insbesondere Castelnaud Schauplatz permanenter Auseinandersetzungen als Ausdruck der französisch-englischen Rivalität im Périgord. 23 Jahre später erklärte der englische König Eduard III. im Frieden von Brétigny 1360 seinen Verzicht auf den französischen Thron, forderte dafür jedoch unter anderem die Guyenne und die Burg Beynac als englischen Kontinentalbesitz, musste sie aber 1368 endgültig an Frankreich abtreten.","w":"https://de.wikipedia.org/wiki/Burg_Beynac"},"ch-Q1480604":{"n":"Schloss Pau","c":"Schloss in Frankreich","r":"Im Zentrum der Altstadt von Pau im Béarn steht das Schloss Pau, Geburtsort Heinrichs IV., des Königs von Frankreich und Navarra. Als Zeichen der Herrschaft des „guten Königs“ schmückt seine Abbildung alle Mauern. Das Schloss, das weit älter ist als die Vereinigung der beiden Königreiche, ist jedoch über die Person des als Vert galant bezeichneten Heinrich IV. auch mit der bewegten modernen Geschichte verknüpft.","w":"https://de.wikipedia.org/wiki/Schloss_Pau"},"ch-Q516697":{"n":"Schloss Compiègne","c":"klassizistische Schlossanlage in der französischen Stadt Compiègne","r":"Das Schloss Compiègne ist eine klassizistische Schlossanlage in der französischen Stadt Compiègne im Département Oise in Nordfrankreich. Die weitläufige Anlage war nach Versailles und Fontainebleau die wichtigste Herrscherresidenz Frankreichs, in der sich die französischen Könige traditionell einige Tage auf dem Weg von und zu ihrer Krönung in Reims aufhielten. Der Schlosskomplex wurde am 24. Oktober 1994 als Monument historique unter Denkmalschutz gestellt.","h":"Compiègne fand in den von Gregor von Tours im 6. Jahrhundert verfassten Zehn Bücher Geschichten (Decem libri historiarum) als compendium villam erstmals Erwähnung. Eine erste Residenz der westfränkischen Könige in Compiègne ist durch zahlreiche Urkunden bekannt. Sie stammte vielleicht schon aus der Zeit Chlodwigs I. und war vermutlich aus Holz erbaut. Chlothar I. starb 561 in dieser villa regia in Compiègne. Im Laufe des 7. Jahrhunderts gewann die mehrheitlich als Jagdhaus genutzte villa immer mehr an Bedeutung und wuchs zu einer königlichen Pfalz heran, die in den Quellen Compendium palatium genannt wurde. Dagobert I. bewahrte dort seinen Königsschatz auf, den seine Söhne im Jahr 639 unter sich aufteilten. Allerdings konnte der Standort dieser Pfalz, bei der es sich nicht um einen Palast, sondern mehr um eine Art Landhaus gehandelt hat, bisher nicht lokalisiert werden. Unter den Karolingern war Compiègne ein Zentrum ihrer Herrschaft und diplomatischer Mittelpunkt des westlichen Frankenreichs. So ist zum Beispiel für das Jahr 757 der Empfang einer Gesandtschaft des byzantinischen Kaisers Konstantin V. belegt. Am 5. Mai 877 stiftete Karl der Kahle in Compiègne die Abtei Notre-Dame (später Saint-Corneille), deren Klosterkirche zugleich als königliche Kapelle diente. Zudem ließ er am Ufer der Oise eine neue Königsresidenz errichten, die sich am Vorbild der Aachener Pfalz seines Großvaters Karls des Großen orientierte und seine Lieblingsresidenz wurde. 877 wurde Ludwig II. in der Klosterkirche zum König der Westfranken gekrönt. Er starb nur zwei Jahre später in Compiègne und wurde in der Abtei begraben. Ähnliches gilt für den letzten Karolinger auf dem französischen Thron: Auch Ludwig V.","w":"https://de.wikipedia.org/wiki/Schloss_Compi%C3%A8gne"},"ch-Q1090583":{"n":"Château Latour","c":"Château Latour in Pauillac bei Bordeaux  berühmtes Weingut","r":"Das Château Latour in Pauillac bei Bordeaux ist eines der berühmtesten Weingüter der Welt.","h":"Das Land von Latour wurde mindestens seit dem frühen 14. Jahrhundert bebaut. Im späten 14. Jahrhundert erbaute man eine befestigte Anlage 300 Meter von der Gironde-Mündung, um die Mündung gegen Angriffe im „Hundertjährigen Krieg“ verteidigen zu können. Der Festungsturm, La Tour en Saint-Maubert, ergab den Namen dieses Weingutes rund um die Festung. All dies war in englischem Besitz bis zum Vertrag von Castillon 1453. Der originale Turm existiert nicht mehr, aber in den Jahren um 1620 wurde ein Rundturm mit dem Namen La Tour de Saint-Lambert auf dem Gut erbaut. Und da der neuere Turm mit seiner Rundkuppel eher ein Taubenschlag ist, dient das Bild des alten Turmes weiter als Markenzeichen des Weingutes. Obwohl es an dieser Stelle Weinbau mindestens seit dem 14. Jahrhundert gab, begann die Geschichte von Latour als einem der besten Weingüter der Erde erst im späten 17. Jahrhundert, als der Erbe Alexandre de Ségur das Château Lafite 1716 seinem Besitz hinzufügte. 1718 erweiterte sein Sohn Nicolas-Alexandre de Ségur den Besitz, indem er auch noch Château Mouton und Château Calon kaufte, und Weine von großartiger Qualität zu produzieren begann. In einem Schreiben vom 24. Mai 1787 bescheinigt Thomas Jefferson den Weinen den Rang eines premier Cru. Obwohl das Gut nach Kriterien der Wertschätzung hinter Château Lafite rangierte, gewannen die Weine von Latour an Statur und waren um 1800 zwanzigmal so teuer wie normaler Bordeauxwein. Die Klassifikation des Gutes als eines der vier Premier-Cru-Gütern, die 1855 erfolgte, sicherte den kontinuierlichen Erfolg. 1860 wurde das aktuelle Schlossgebäude erstellt. 1963 gelangte das Gut aus dem Besitz der Familie Ségur, als Erben einen Anteil von 75 % an die britischen Gesellschaften Harveys of Bristol und an die Gruppe Pearson verkauften.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Latour"},"ch-Q1063236":{"n":"Château Margaux","c":"Schloss in Frankreich","r":"Das Château Margaux ist ein Weingut im Gebiet Médoc bei Bordeaux. Es erzeugt einen der berühmtesten Weine der Welt. Seit 1855 trägt Château Margaux den Titel Premier Grand Cru, eines „Ersten Großen Gewächses“, den es sich im Médoc heute mit nur drei weiteren Châteaux teilt: Lafite, Latour, Mouton. Ferner zählt das Haut-Brion in der Region Graves zu den Premier Grand Cru.","h":"Die Ursprünge des Gutes verlieren sich im Mittelalter, seine erste urkundliche Erwähnung fällt ins späte 15. Jahrhundert. Es war damals unter dem Namen Lamothe bekannt. Es war ein befestigtes Schloss und gehörte dem Herrn de Montferrand, später dem Herrn de Durfort. Der eigentliche Weinberg wurde zwischen 1572 und 1582 vom damaligen Eigentümer Pierre de Lestonnac durch systematische Käufe von Parzellen begründet. 1654 kam das Gut von Margaux durch Heirat in den Einflussbereich der führenden Bordelaiser Familie Pontac, der auch das Château Haut-Brion gehörte. Dessen Wein wurde als erster Bordeaux überhaupt unter dem Namen des Gutes verkauft. 1750 gehört es einem Herrn de Fumel. Dieser machte bedeutende Anpflanzungen feiner Rebsorten. Seit Beginn des 18. Jahrhunderts ist auch der Wein von Margaux unter seinem Namen in England bekannt, das bis 1900 das Hauptabnehmerland blieb. Die Weinbereitung machte im 18. Jahrhundert große Fortschritte. So wurden erstmals ausschließlich blaue Trauben für den Rotwein verwendet, und die Lese erfolgte erst, nachdem der morgendliche Tau abgetrocknet war. Zu den Liebhabern des Château Margaux zählten seinerzeit der britische Premierminister Robert Walpole sowie der amerikanische Botschafter und spätere Präsident Thomas Jefferson. In einem Schreiben vom 24. Mai 1787 bescheinigt Jefferson den Weinen den Rang eines premier Cru. Die Französische Revolution brachte das Ende der dreihundertjährigen familiären Kontinuität des Gutes. Es wurde beschlagnahmt, konnte aber zunächst von der letzten Erbin der Familie zurückgekauft werden. Sie war mit dem Baron de Brane verheiratet, der jedoch in die Emigration ging. Sie war angesichts der Schuldenlast gezwungen, das Gut zu verkaufen. 1802 erwarb es der Marquis de Lacolonilla.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Margaux"},"ch-Q1479356":{"n":"Schloss Talcy","c":"Schloss in Frankreich","r":"Das Schloss Talcy steht im gleichnamigen französischen Ort Talcy im Département Loir-et-Cher, Region Centre-Val de Loire. Etwa 20 Kilometer nordöstlich von Blois und damit am äußeren Rand des Loiretals in der fruchtbaren Beauce gelegen, gehört es zu den Schlössern der Loire.","h":"Die Ursprünge des heutigen Schlosses gehen bis in das 13. Jahrhundert zurück, als Talcy eine Seigneurie war. 1221 erstmals urkundlich erwähnt, gehörte die Domäne zu jener Zeit der aus Beaugency stammenden Familie St. Lazare. 1466 erwarb der aus Paris kommende Anwalt Pierre Simon den Besitz und vererbte ihn an seinen Sohn Jean, über den er an Pierres Enkel Philippe kam. Als Philippe ohne männliche Nachkommen starb, ging Talcy an dessen Bruder Jean, der conseiller clerc im Parlement de Paris war und später Bischof von Paris wurde. Nach seinem Tod 1502 kamen das Schloss und die Seigneurie an Jeans Schwester Marie, die sie am 8. November 1517 an Bernard Salviati verkaufte. Der Florentiner Kaufmann und Bankier stand im Dienste Franz’ I. und war durch Heirat ein Verwandter der Katharina von Medici. Durch Umbauten und Erweiterungen gab er dem Schloss seine heutige äußere Gestalt. Bernard und seine Frau Madeleine de La Tour d’Auvergne hatten eine Tochter namens Cassandre, der Pierre de Ronsard anlässlich eines Balls am 25. April 1545 im Schloss Blois begegnete und in die er sich verliebte. 1552 veröffentlichte Ronsard eine Gedichtsammlung mit dem Titel Amours de Cassandre, obwohl die Angebetete sein Werben nicht erhörte und einen anderen Mann heiratete. Cassandres Bruder Jean wurde nach dem Tod des Vaters neuer Schlossherr. Seine gutaussehende Tochter Diane, die er gemeinsam mit seiner Frau Jacquette Malon de Bercy hatte, war die zweite Frau der Familie, die einem französischen Schriftsteller den Kopf verdrehte. In diesem Fall war es der junge Théodore Agrippa d’Aubigné, welcher der schönen Salviati-Tochter seine erste Gedichtsammlung Le Printemps widmete.","w":"https://de.wikipedia.org/wiki/Schloss_Talcy"},"ch-Q1815544":{"n":"Schloss Châteaudun","c":"Schloss in Frankreich","r":"Das Schloss Châteaudun liegt in der französischen Gemeinde Châteaudun im Département Eure-et-Loir in der Region Centre-Val de Loire. Zusammen mit dem Schloss Montsoreau (1453) und dem Palais Jacques Cœur (1451) ist Châteaudun eines der frühesten Beispiele für Renaissance-Architektur in Frankreich.","w":"https://de.wikipedia.org/wiki/Schloss_Ch%C3%A2teaudun"},"ch-Q2111621":{"n":"Herzogspalast Dijon","c":"Schloss in Frankreich","r":"Der Herzogspalast Dijon, auch Palast der Herzöge von Burgund ist ein Ensemble mehrerer historischer Gebäude aus dem 14., 15. und 18. Jahrhundert, die im Zentrum der Stadt Dijon in der französischen Region Burgund liegen.","w":"https://de.wikipedia.org/wiki/Herzogspalast_Dijon"},"ch-Q2971342":{"n":"Schloss La Muette","c":"Schloss in Frankreich","r":"Das Schloss La Muette war ein Schloss, das fast zwei Jahrhunderte lang als Residenz des französischen Königshauses diente. Es befand sich bis in die 1850er Jahre inmitten einer ausgedehnten Parklandschaft, die zwischen dem ursprünglichen Pariser Vorort Passy und dem Bois de Boulogne lag. Nach der 1860 erfolgten Eingemeindung von Passy zu Paris erhielt ein ganzes Stadtviertel den Namen Muette. Das Schloss wurde 1920 vollständig abgerissen und 1921/22 an anderer Stelle innerhalb des 16. Arrondissements von Paris neu errichtet. Der Neubau beherbergt seit 1949 den Hauptsitz der OECD bzw. von dessen Rechtsvorgänger OEEC.","h":"Der Ritterkönig Franz I. ließ in den 1540er Jahren am Rand des Bois de Boulogne eine Jagdhütte erbauen, die den Namen La Meute erhielt. Diese wurde 1572 auf Anordnung von Karl IX. zu einem kleinen Schloss umgebaut. Dieses vermachte er seiner Schwester Margarete von Valois, die durch ihre im selben Jahr vollzogene Heirat mit Heinrich IV. Königin von Frankreich wurde. Am 21. November 1783 war der Garten des Schlosses der Startplatz für die erste bemannte Ballonfahrt von Rozier und d’Arlandes, die über die Seine hinweg etwa 10 km weit bis zur Butte aux Cailles in der damaligen Gemeinde Gentilly führte. Aufgrund des zunehmend sanierungsbedürftigen Zustands wurde das Schloss seit 1787 nicht mehr von der königlichen Familie bewohnt. Der Versuch, es an einen privaten Investor zu verkaufen, scheiterte aufgrund des offensichtlich zu hoch angesetzten Kaufpreises. So blieb das Anwesen noch bis zur Enteignung 1792 während der Französischen Revolution im Besitz des Königshauses. Durch den Bau der Eisenbahnlinie Passy-Auteuil im Jahr 1854 wurde die weiträumige Parkanlage zerstückelt und das Land in kleine Parzellen aufgeteilt, auf denen ein neues Villen­viertel entstand. Um 1920 wurde das verbliebene Landgut von Henri de Rothschild erworben, der 1921/22 ein neues Bauwerk errichten ließ, das ebenfalls die Bezeichnung „Schloss La Muette“ trägt. 1949 wurde das Anwesen an den OECD-Rechtsvorgänger OEEC (Organisation für europäische wirtschaftliche Zusammenarbeit) verkauft, die dort seither ihren Hauptsitz unterhält.","w":"https://de.wikipedia.org/wiki/Schloss_La_Muette"},"ch-Q2092716":{"n":"Schloss Maisons-Laffitte","c":"Schloss in Frankreich","r":"Das barocke Schloss Maisons-Laffitte steht in der französischen Gemeinde Maisons-Laffitte im Département Yvelines der Region Île-de-France. Das Äußere des aus dem 17. Jahrhundert stammende Schloss ist nahezu unverändert erhalten und kann von Besuchern besichtigt werden.","h":"Bauherr des Schlosses war der zeitweilige Präsident des Parlement de Paris, René de Longueil, der den Hofarchitekten François Mansart mit dem Bau beauftragte. Mansart wurde bei der Gestaltung völlig freie Hand gelassen und durfte das Gebäude nach seinen Vorstellungen errichten. René de Longueil nutzte das Schloss nach der Fertigstellung vorwiegend als Sommerschloss. Nachdem er 1677 verstorben war, verblieb Maisons-Laffitte noch bis 1732 im Besitz seiner Familie. Im 18. Jahrhundert wechselten die Besitzer mehrfach. Auf die Familie Longueil folgten die Familien Belleforière und Soyécourt, ab 1777 ging das Schloss an den Bruder Ludwigs XVI., Charles Philippe, der während der Französischen Revolution auswanderte. Das Schloss wurde konfisziert und das Mobiliar verstreut. 1804 erstand es Marschall Lannes, ein Kampfgefährte Napoleons, und ließ es renovieren. Der Kaiser verweilte regelmäßig im Schloss. 1818 kaufte es der Pariser Bankier Jacques Laffitte, auf den ein Teil des heutigen Namens zurückgeht. Nach 1830 wandelte er einen großen Teil des Parks zu Bauland um und veranlasste auch den Abriss der Pferdestallungen des Schlosses. Auf Betreiben seines Neffen Charles Laffitte, einer der Gründer der Société d’encouragement pour l’amélioration de la race chevaline, wurden auf den Wiesen am Seineufer die ersten Rennen veranstalter. Joseph Oller, Erfinder der Rennwette, kaufte das Gelände und verwandelte es in ein Hippodrom, das 1878 eingeweiht wurde. 1844 erbte Albinne Laffitte das Schloss, bevor sie es 1850 an Charles Xavier Thomas de Colmar, Versicherer und Erfinder des Arithmometers, verkaufte. 1877 übergaben die Erben von Thomas de Colmar das Schloss an den Maler Tilman Grommé. Zu Beginn des 20. Jahrhunderts drohte dem Schloss der Abriss. Der Staat kaufte das Schloss.","w":"https://de.wikipedia.org/wiki/Schloss_Maisons-Laffitte"},"ch-Q1090764":{"n":"Château d’Yquem","c":"Weingut in Sauternes, Bordeaux","r":"Das Château d’Yquem [ʃaˈto diˈkɛm] ist eines der weltweit berühmtesten Weingüter. Es produziert hauptsächlich edelsüße Weine (Sauternes), die zu den teuersten Weinen gehören.","h":"Durch die Heirat von Henry Plantagenet, des späteren Königs Heinrich II. von England im Jahr 1152, mit Eleonore, der Erbin von Aquitanien, geriet ein großer Teil Westfrankreichs unter britische Herrschaft. Auch das befestigte, das Tal des Ciron dominierende Anwesen gehörte damit ab dem 12. Jahrhundert den Engländern. Mit dem Ende des Hundertjährigen Krieges im Jahr 1453 kam die Region um Bordeaux wieder unter die Kontrolle der französischen Krone. Der Kaufmann Ramon Felipe Eyquem erwarb das Château als Lehen des Erzbischofs Arthur de Montauban (1467–1478) am 10. Oktober 1477 von Guilhem Duboys, seigneur de Juillac. Der Kaufpreis soll 900 Goldfranken (Franc à pied) betragen haben. Dessen Enkel Pierre Eyquem, von 1554 bis 1556 Bürgermeister von Bordeaux, vererbte es wiederum seinem Sohn, dem berühmten Philosophen Michel Eyquem de Montaigne. Ein Jahr nach dessen Tod wurde das Anwesen mit Vertrag vom 8. Dezember 1593 an Jacques de Sauvage verpachtet, der bis zum Anfang des 17. Jahrhunderts die Gutsgebäude um eine Kapelle sowie einen Nordflügel erweiterte. Die Familie Sauvage begründete den guten Ruf des Weinguts. In den Adelsstand erhoben, erwarb im Jahr 1711 Léon de Sauvage das Gut als Eigentum. Durch die Heirat seiner Enkelin Françoise-Josèphe Sauvage (1768–1851) mit Louis Amédée de Lur-Saluces (1761–1788) am 6. Juni 1785 kam das Weingut in den Besitz der Familie Lur-Saluces, die durch eine Eisenschmiede in der Gemeinde Uza-les-Forges zu Reichtum gekommen war. Nachdem Louis Amédée an den Folgen eines Reitunfalls gestorben war, leitete seine Witwe das Weingut. Während der Französischen Revolution wurde sie als Adelige zweimal inhaftiert, konnte aber, im Gegensatz zu vielen anderen Weingütern des Bordelais, ihr Gut in Familienbesitz halten.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_d%E2%80%99Yquem"},"ch-Q1377160":{"n":"Schloss Le Plessis-Bourré","c":"Schloss in Frankreich","r":"Das Schloss Le Plessis-Bourré befindet sich nahe der französischen Ortschaft Écuillé, 15 Kilometer nördlich der Stadt Angers, im Département Maine-et-Loire. Die feudale Wohnstätte wurde im ausgehenden Mittelalter innerhalb von fünf Jahren fertiggestellt und präsentiert sich dem Besucher von heute praktisch unverändert.","w":"https://de.wikipedia.org/wiki/Schloss_Le_Plessis-Bourr%C3%A9"},"ch-Q1516747":{"n":"Schloss Commarque","c":"Schloss in Frankreich","r":"Die Burg Commarque liegt in der französischen Region Nouvelle-Aquitaine, im Département Dordogne, im Tal der Großen Beune, in Nachbarschaft der archäologischen Fundstätte Abri de Cap Blanc, in Sichtweite des nicht zu besichtigenden Château de Laussel, ungefähr 8 km östlich von Les Eyzies.","h":"Bereits im Jungpaläolithikum hatten sich auch im Tal der Großen Beune unter Überhängen (Abris) von senkrecht aufragenden Felsen Menschen angesiedelt und ihre Spuren hinterlassen. So gibt es unmittelbar unter den hoch aufragenden Wänden der Festung auf Höhe des ebenen Talgrundes einen Abri mit einer Höhle (Grotte de Commarque), in der die frühen Kulturen Darstellungen von Pferden und Bergziegen eingraviert haben, ein Beweis dafür, dass hier schon vor mehr als 17.000 Jahren Menschen gelebt haben und sesshaft waren. Die Höhle ist wegen ihrer Enge nicht von der Öffentlichkeit zu besichtigen. Etwas über dem Abri, auf halber Höhe der Steilwand sieht man von unten Höhlungen in den Felsen, zu denen eine schmale Stiege hinaufführt. Gleichermaßen kommt man auch seitlich aus dem Gelände der mittelalterliche Festung dahin, in Höhe der Kapelle und des ehemaligen Wehrturm-Durchgangs. Hier stößt man auf eine in den Felsen gehauene troglodytische Behausung, eine „Höhlenwohnung“, die in der Regel durch weitere Vertiefung natürlicher Steinhöhlungen für Mensch und Haustier nutzbar gemacht worden sind. Die höhere Lage in der Felswand und die meist schmalen und eher umständlichen Zugänge boten höheren Schutz und erlaubten einfachere Verteidigungen vor marodierendem Gesindel als bei ebenerdigen Wohnstätten. Vergleichbare troglodytische Behausungen, etwa diejenigen von La Madeleine, datieren um das 8. Jahrhundert. Die Unterkunft besteht hier aus einem großen Wohn- und Schlafraum mit Schlafnischen mit unmittelbaren Durchlässen zum Schweinestall und zum Schafstall. Dort lebten Mensch und Tier gemeinsam nebeneinander. In der Folge von hölzernen Wehrtürmen begann man im 12.","w":"https://de.wikipedia.org/wiki/Burg_Commarque"},"ch-Q1817122":{"n":"Château d’Écouen","c":"Schloss in Frankreich","r":"Das Château d’Écouen ist ein Schloss aus dem 16. Jahrhundert im Ort Écouen im Département Val-d’Oise. Es beherbergt das Musée national de la Renaissance.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_d%E2%80%99%C3%89couen"},"ch-Q2060046":{"n":"Schloss Roquetaillade","c":"Burg in Frankreich","r":"Das Schloss Roquetaillade in Mazères, einer französischen Gemeinde im Département Gironde in der Region Nouvelle-Aquitaine, wurde ab dem 14. Jahrhundert errichtet. Das Schloss im Südwesten der Gemeinde ist seit 2002 als Monument historique klassifiziert.","w":"https://de.wikipedia.org/wiki/Schloss_Roquetaillade"},"ch-Q2968752":{"n":"Château de Caen","c":"Französisch Burg in Caen","r":"Das Château de Caen ist die ehemalige Stadtfestung der normannischen Herzöge in der Stadt Caen in der heutigen Region Normandie im Norden Frankreichs. Es beherbergt u. a. das kulturgeschichtliche Musée de Normandie und das moderne Gebäude des Musée des Beaux-Arts. Die Gesamtanlage ist seit dem Jahr 1997 als Monument historique anerkannt.","h":"Eine Wall- und Grabenanlage existierte an dieser Stelle bereits seit dem beginnenden 11. Jahrhundert. Der Bau einer Festung wurde um das Jahr 1060 vom Normannenherzog Wilhelm dem Eroberer beauftragt; er erwählte Caen zur Hauptstadt seines Herzogtums. Sein Sohn Heinrich I. von England ließ eine Kirche und den Bergfried (französisch donjon oder englisch keep) erbauen, von dem heute nur noch die Grundmauern erkennbar sind. Zu Weihnachten des Jahres 1182 empfingen hier König Heinrich II. von England und seine beiden Söhne Richard Löwenherz und Johann Ohneland die Huldigungen von mehr als 1000 – zumeist adeligen – Rittern. Im Jahr 1204 eroberte der französische König Philipp II. das Herzogtum Normandie zurück. Er und seine Nachfolger ließen die Burg ausbauen. Während der Französischen Revolution wurde der mittelalterliche Donjon abgerissen. Im Zuge der Alliierten Invasion (Juni 1944) wurden die Stadt Caen und somit auch die Burg durch Fliegerbomben schwer beschädigt.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_de_Caen"},"ch-Q2093924":{"n":"Schloss Abbadie","c":"Schloss in Frankreich","r":"Das Schloss Abbadia steht, umgeben von einer weitläufigen Parkanlage, in der französischen Stadt Hendaye, im Département Pyrénées-Atlantiques. Den Namen erhielt es durch seinen Bauherrn, den französischen Kartographen und Weltreisenden Antoine Thomson d’Abbadie.","h":"Als Antoine Thomson d’Abbadie um 1860 beschloss, sich ein Schloss als herrschaftlichen Wohnsitz errichten zu lassen, wählte er als Bauort den Landstrich Aragorry bei Hendaye. Als Architekten beauftragte er Eugène Viollet-le-Duc, der die praktische Umsetzung seinem Assistenten Edmond Duthoit übergab. Von allen Werken Viollet-le-Ducs ist Schloss Abbadia etwas Besonderes, da es sich dabei um einen völligen Neubau und nicht um eine Ruinen-Rekonstruktion handelte. Die Bauarbeiten begannen 1864 und wurden 1879 abgeschlossen. Abbadie stiftete sein Schloss 1895 samt Inventar und den dazugehörigen Ländereien der französischen Akademie der Wissenschaften, deren Mitglied er war.","w":"https://de.wikipedia.org/wiki/Schloss_Abbadia"},"ch-Q1376597":{"n":"Schloss Troussay","c":"Schloss in Frankreich","r":"Das Schloss Troussay befindet sich in der Gemeinde Cheverny im Département Loir-et-Cher der Region Centre-Val de Loire in Frankreich. Es ist eines der kleinsten Loire-Schlösser und steht seit dem 25. Januar 2000 als Monument historique unter Denkmalschutz.","w":"https://de.wikipedia.org/wiki/Schloss_Troussay"},"ch-Q2047247":{"n":"Palais de la Cité","c":"Palast in Frankreich","r":"Das Palais de la Cité auf der Île de la Cité in Paris war vom 10. bis zum 14. Jahrhundert die Residenz der französischen Könige. Von dem mittelalterlichen Gebäudekomplex sind heute nur zwei kleinere Gebäude erhalten:die Sainte-Chapelle und die Conciergerie.","h":"An der Stelle des späteren Gebäudeensembles befand sich unter der Herrschaft des Königs Dagobert I. im 7. Jahrhundert nachweislich die königliche Münzprägeanstalt. Man vermutet gegenüber diesem Gebäude auch die Königspfalz der Merowinger, innerhalb der damals noch intakten römischen Befestigungsmauern der Ile de la Cité, von der sich jedoch keine Spuren erhalten haben. Zu Beginn des 11. Jahrhunderts ließ König Robert der Fromme († 1031) hier einen Palast errichten, der für die nächsten vier Jahrhunderte das Machtzentrum Frankreichs werden sollte. Zwischen 1244 und 1248 wurde auf Wunsch Ludwigs IX. des Heiligen vermutlich von Pierre de Montreuil der Palast um eine Kapelle, die Sainte-Chapelle ergänzt, um die kostbaren Passionsreliquien („Christi Dornenkrone“ und Teile des „Wahren Kreuzes“) aufzunehmen sowie die Spitze einer Lanze, die dem römischen Hauptmann Longinus gehört haben soll, und die der König 1237 dem lateinischen Kaiser Balduin II. abgekauft hatte. Am 26. April 1248 wurde die Kapelle der Heiligen Jungfrau Maria geweiht. In den Jahren 1302 bis 1313 ließ König Philipp der Schöne – nachdem er feststellen musste, dass der Louvre, so wie ihn Philipp August hatte bauen lassen, für Empfänge des wachsenden Hofstaates, aber auch ausländischer Gäste, nicht mehr ausreichte – den Palast neu bauen, den er Pfingsten 1313 mit einem Fest einweihte, bei dem der englische König Eduard II., sein Schwiegersohn, anwesend war und drei Söhne Philipps zu Rittern geschlagen wurden.","w":"https://de.wikipedia.org/wiki/Palais_de_la_Cit%C3%A9"},"ch-Q205659":{"n":"Schloss Lunéville","c":"Schloss(museum) in Frankreich","r":"Das Schloss Lunéville ist ein Schloss in der französischen Stadt Lunéville.","w":"https://de.wikipedia.org/wiki/Schloss_Lun%C3%A9ville"},"ch-Q769303":{"n":"Burg Le Rivau","c":"Burg in Frankreich","r":"Die Burg Le Rivau befindet sich in Lémeré nahe Chinon in der Region Centre-Val de Loire in Frankreich. Die Ländereien waren schon seit dem 11. Jahrhundert im Besitz der mit den Grafen von Anjou verwandten Familie Beauvau.","w":"https://de.wikipedia.org/wiki/Schloss_Le_Rivau"},"ch-Q761920":{"n":"Schloss Gien","c":"Schloss in Frankreich","r":"Das Schloss Gien ist eine französische Schlossanlage in Gien im Département Loiret, Region Centre-Val de Loire. Als eines der ersten Schlösser der Loire aus einem Jagdschloss hervorgegangen, steht es auf einem Felsrücken am rechten Ufer der Loire und dominiert das Bild der Stadt, die schon im Mittelalter ein beliebtes Jagdrevier am Rand der wildreichen Sologne war.","h":"Das Schloss Gien war Mittelpunkt der gleichnamigen Grafschaft und wurde auf den Grundmauern einer älteren Jagdresidenz errichtet, die aus der Zeit Karls des Großen stammte. Nachdem Anne de Beaujeu die Grafschaft Gien 1481 nach ihrer Hochzeit mit Pierre II. de Bourbon, seigneur de Beaujeu, von ihrem Vater Ludwig XI. erhalten hatte, ließ sie die damalige, durch Johann Ohnefurcht errichtete Burg von 1494 bis 1500 durch einen Neubau ersetzen, der dadurch notwendig geworden war, dass die Anlage 1378 im Hundertjährigen Krieg von Truppen Robert Knolles’ stark in Mitleidenschaft gezogen worden war. Die Anlage blieb nach Annes Tod vorerst im Besitz des Hauses Bourbon, bis Franz I. sämtliche Güter des Connetables Charles III. de Bourbon-Montpensier aufgrund dessen Verrats an der Krone im Jahr 1523 beschlagnahmte. Gien und sein Schloss wurden der Krondomäne zugeschlagen. In der Folgezeit beherbergte das Gebäude viele wichtige Persönlichkeiten der französischen Geschichte, darunter die Könige Heinrich II., Karl IX. und Heinrich III. sowie Katharina von Medici. Ende März 1652 suchte dort die Regentin Anna von Österreich gemeinsam mit ihren noch minderjährigen Sohn Ludwig XIV. und ihrem Minister Kardinal Jules Mazarin Zuflucht vor der Fronde. Der Hof verließ das Schloss erst wieder, nachdem die königlichen Truppen am 6. April des gleichen Jahres in der Schlacht von Bléneau den Sieg gegen die Aufständischen davongetragen hatte und zog weiter nach Saint-Germain-en-Laye. Im Zuge der Französischen Revolution wurde die Grafschaft Gien aufgelöst und die Schlossanlage 1823 Eigentum des Départements Loiret. Während des Ersten Empires diente der Gebäudekomplex als Sitz der Unterpräfektur, des Gerichts und zugleich auch als Gefängnis.","w":"https://de.wikipedia.org/wiki/Schloss_Gien"},"ch-Q1011692":{"n":"Burg Falaise","c":"Burg in Frankreich","r":"Die Burg Falaise befindet sich auf einer im Südwesten von Falaise gelegenen Felsnase im Département Calvados der Region Normandie.","w":"https://de.wikipedia.org/wiki/Burg_Falaise"},"ch-Q1192381":{"n":"Schloss Menars","c":"Schloss in Frankreich"},"ch-Q1229917":{"n":"Hôtel de Salm","c":"Museum in Frankreich","r":"Das Hôtel de Salm ist Sitz und Museum der französischen Ehrenlegion und des Ritterordens. Es steht am linken Seineufer in Paris zwischen dem Quai Anatole-France und der Rue de Lille, westlich des Musée d’Orsay.","h":"Das Hôtel de Salm entstand zwischen 1783 und 1787 nach Plänen der Architekten Pierre Rousseau (1751–1829) und Antoine-François Peyre für den deutschen Fürsten Friedrich III. zu Salm-Kyrburg. Am 12. Juli 1782 war er Eigentümer eines großen Grundstücks geworden, das er von Prince de Conti erwarb. Zwischen 1783 und 1788 ließ er an die Rue de Lille das klassizistische Hôtel de Salm errichten. Im Januar 1783 wurden der Grundriss, die Aufrisse des Gebäudes und die Vertragsbedingungen festgelegt und präzisiert. Thomas Jefferson war 1787 so sehr beeindruckt, dass er es als Vorbild für den Umbau seines Anwesens Monticello diente. Unter anderem die Kuppel entnahm er dem Gebäude. Der Pariser Wohnsitz der Familie Salm-Kyrburg war bald ein Treffpunkt der hochadligen Oberschicht des vorrevolutionären Frankreichs sowie der Linken der Konstituante während der Französischen Revolution und entwickelte sich später unter der Initiative von Madame de Stael zur Zeit der Direktoriums zum Club de Salm. Zur Zeit der Revolution wurde das Gebäude verstaatlicht und erhielt am 13. Mai 1804 seine neue Funktion als Sitz für die 1802 gegründete Ehrenlegion und somit auch seinen bis heute gültigen Namen. 1866 entstand entlang der neu angelegten Rue de Solférino ein Erweiterungsbau, der jedoch 1871 während der Pariser Kommune durch ein Feuer zerstört wurde. Kurz darauf wurde er unter der Mitarbeit berühmter Künstler wie dem Maler Jean-Paul Laurens rekonstruiert. Von 1922 bis 1925 entstand ein weiterer Anbau entlang der Rue de Bellechasse für das Museum der Ehrenlegion (Musée national de la Légion d’honneur et des ordres de chevalerie).","w":"https://de.wikipedia.org/wiki/H%C3%B4tel_de_Salm"},"ch-Q2633625":{"n":"Château de Brest","c":"Burg in Brest, Frankreich"},"ch-Q2032524":{"n":"Schloss Anet","c":"Schloss in Frankreich","r":"Das Schloss Anet ist ein französisches Schloss im Stil der Renaissance in Anet in der Nähe von Dreux im Département Eure-et-Loir, 65 Kilometer westlich von Paris.","h":"Anet und seine Burg treten zur Zeit des Königs Philipp II. in die Geschichte ein. Im Louvre befinden sich Briefe, die Philipp II. 1192 in Anet schreiben ließ, in denen er die Bewohner Anets, die seiner direkten Jurisdiktion unterstanden, von allen Steuern und Zöllen befreit. Unter seinen Nachfolgern gehörte Anet dann zur Domaine royal. 1317 gab Philipp V. die Herrschaft über Anet Ludwig, Graf von Évreux als Apanage. Auf Ludwig, der 1319 starb, folgten dessen Sohn Philipp, der 1328 als Philipp III. König von Navarra wurde, sowie dessen Sohn Karl der Böse, der 1349 in Navarra den Thron bestieg. Karl wiederum gab die Herrschaft Anet als Apanage an seinen jüngeren Bruder Ludwig, Graf von Beaumont-le-Roger, der es aber bald König Karl V. für 50.000 Florin verpfändete. Nach dem kinderlosen Tod Ludwigs konfiszierte Karl V. Anet und ließ die Burg weitgehend abreißen. 1404 trat Karl III. von Navarra die Grafschaften Évreux und Mantes und auch die Herrschaft Anet endgültig an den König ab. 1447 wiederum belohnte Karl VII. seinen Großseneschall der Normandie, Pierre de Brézé, Graf von Maulévrier, für die Vertreibung der Engländer aus dieser Provinz, indem er ihm Anet zu Lehen gab (siehe auch: Haus Brézé). Pierre de Brézé fiel 1446 in der Schlacht bei Montlhéry, ihm folgte sein Sohn Jacques de Brézé, der 1462 Charlotte de Valois geheiratet hatte, die uneheliche Tochter Karls VII. mit Agnès Sorel. Ihm folgte sein Sohn Louis de Brézé, der 1514 Diane de Poitiers heiratete. Als Louis 1531 starb, war Diane 32 Jahre alt; sie behielt Anet bis zu ihrem Tod 1566.","w":"https://de.wikipedia.org/wiki/Schloss_Anet"},"ch-Q576569":{"n":"Schloss Beauregard","c":"Schloss in Frankreich","r":"Das Schloss Beauregard steht im Beuvrontal auf dem Gebiet der französischen Gemeinde Cellettes etwa sechs Kilometer südöstlich von Blois im Département Loir-et-Cher der Region Centre-Val de Loire.","h":"Die Geschichtsschreibung erwähnt Beauregard erstmals 1495, als das Anwesen im Besitz des persönlichen Kammerherrn Karls VIII., Jean Doulcet, war und durch Louis d’Orléans – den späteren französischen König Ludwig XII. – in den Rang einer Seigneurie erhoben wurde. Anfang des 16. Jahrhunderts erwarb Franz I. das Land, um dort Jagden zu veranstalten, verschenkte es 1524 aber an seinen Onkel René von Savoyen. Von dessen Witwe erwarb es 1545 Jean du Thier, Staatssekretär König Heinrichs II., für 2000 Goldécus. Er ließ in der Zeit von 1545 bis 1553 auf dem Land vermutlich nach Plänen Philibert de l’Ormes ein Schloss im Stil der späten französischen Renaissance erbauen, das aber deutliche Merkmale des klassizistischen Barockstils aufweist. Jacques I. Androuet du Cerceau nahm Schloss Beauregard in den zweiten Band seines Werks Les plus excellents bastiments de France auf, sodass heute noch bekannt ist, wie es in den 1570er Jahren ausgesehen hat. Demnach war das Bauwerk als Landgut angelegt. Sein Hauptgebäude umschloss zusammen mit einigen Mauern einen rechteckigen Hof, an den weitere, unterschiedlich große Höfe grenzten; darunter ein geräumiger Wirtschaftshof mit einem Taubenschlag. An der Süd- und Westseite des Schlosses befanden sich Zier-, Obst- und Weingärten. Daneben gehörte eine Kapelle zur Anlage, die mit Fresken von Nicolò dell’Abbate nach Zeichnungen Francesco Primaticcios ausgestattet war. Sie befand sich im ersten Geschoss des Eingangspavillons, der im 19. Jahrhundert abgerissen wurde, so dass von der Kapelle heute nur noch ein Fresko-Fragment im Musée lapidaire im Schloss Blois erhalten ist. Nachdem der Finanzsekretär Ludwigs XII., Florimont II. de Robertet, die Anlage 1577 erworben hatte, verkaufte er sie 1617 an Paul Ardier.","w":"https://de.wikipedia.org/wiki/Schloss_Beauregard"},"ch-Q1451798":{"n":"Schloss Josselin","c":"Schloss in Frankreich","r":"Das Schloss Josselin befindet sich in Josselin, einer französischen Gemeinde im bretonischen Département Morbihan. Es ist bis heute Sitz des Herzogs von Rohan-Chabot und in Teilen zu besichtigen.","h":"Guéthénoc, Herr von Porhoët aus der Familie der Grafen von Rennes, ließ die erste Burg um das Jahr 1000 errichten. Er suchte dazu einen Ort von hohem militärischen und wirtschaftlichen Wert und fand ihn mit einem Felsen, der das Tal der Oust beherrscht. Die Existenz der Kirche Notre-Dame du Roncier als Pilgerstätte trug viel zum Reichtum der Bevölkerung und ihrer Herren bei. Da Eudon de Porhoët als Regent für den jungen bretonischen Herzog Conan IV. die bretonischen Barone um sich geschart hatte, die dem englischen König Heinrich II. Plantagenet und neuen Grafen von Anjou feindlich gegenüberstanden, ließ dieser unter seiner persönlichen Aufsicht die Burg Josselin schleifen. Olivier V. de Clisson erwarb die Herrschaft Josselin im Jahr 1370 und ließ die Burg als imposante Zitadelle mit acht Türmen und einem Donjon von 90 Metern Höhe wiederaufbauen. Er verheiratete seine jüngere Tochter Béatrix mit Alain VIII. de Rohan, dem Erben der Familie Rohan, dessen Burg Rohan rund 20 Kilometer von Josselin entfernt lag. Die Rohans führen sich auf die Vizegrafen von Porhoët zurück. 1488 wurde die Burg von Herzog Franz II. erobert und teilweise zerstört. Seine Tochter Anne de Bretagne gab sie dann aber an Oliviers Enkel Jean II. de Rohan zurück. Dieser ließ die Burg innerhalb der Mauern umgestalten, so dass sie von der dem Fluss abgewandten Seite wie ein Landhaus erscheint, mit einer wesentlich offeneren Fassade, die aus behauenem Granit besteht und eines der ersten Beispiele der Renaissance in Frankreich ist; zumal er dafür auch italienische Handwerker beschäftigte. Um sich erkenntlich zu zeigen, ließ er zahlreiche „A“s mit einer Kordel umwunden schnitzen, dem Emblem von Anne de Bretagne.","w":"https://de.wikipedia.org/wiki/Schloss_Josselin"},"ch-Q1461848":{"n":"Schloss Ferrières","c":"Schloss in Frankreich","r":"Das Schloss Ferrières in Ferrières-en-Brie wurde im 19. Jahrhundert zwischen 1855 und 1859 von Baron James de Rothschild und seiner Frau Betty von Rothschild als Familiensitz errichtet. Rothschild war einer der reichsten Franzosen seiner Zeit und galt als bedeutender Finanzmann. Neben dem Schloss Ferrières besaß er weitere Schlösser und Paläste, zum Beispiel das Château Lafite, ein Stadtpalais in Paris, das Schloss Boulogne und ein Stadthaus in der Rue Lafitte 19 in Paris. Ferrières war mit einem Preis von etwa 18 Millionen Francs die teuerste seiner Immobilien.","h":"Das Areal der Domaine Ferrières umfasste zur Zeit des Baus über 3000 Hektar Wald und Weideland, die Baron James de Rothschild von Joseph Fouché erwarb. Anschließend beauftragte er den englischen Architekten Joseph Paxton mit dem Bau des Schlosses, der für seinen Bruder Amschel Mayer von Rothschild das Anwesen Mentmore Towers in Buckinghamshire mitentworfen hatte. Das repräsentative Schloss der vermögenden Familie sollte ständiger Wohnsitz in guter Lage nahe Paris werden.","w":"https://de.wikipedia.org/wiki/Schloss_Ferri%C3%A8res"},"ch-Q2007231":{"n":"Schloss Les Milandes","c":"Schloss in Frankreich","r":"Das Schloss Les Milandes liegt mitten in einer terrassierten Parkanlage am linken Ufer der Dordogne in der französischen Gemeinde Castelnaud-la-Chapelle im Département Dordogne.","h":"Das Schloss wurde 1489 von François de Caumont, Graf von Castelnaud, auf Initiative seiner Frau Claude de Cardaillac erbaut. Ihm gehörten auch die Festungen Castelnaud und Berbiguières, zwischen denen das Schloss situiert war. Bis 1535 blieb das Schloss der Hauptwohnsitz dieser Familie. In der Französischen Revolution wurde es enteignet. Danach ging es durch mehrere Hände, wurde jedoch nicht bedeutend verändert. 1870 erwarb der Industrielle Charles Claverie das ursprünglich aus einem Hauptgebäude und einem viereckigen Turm bestehende Schloss. Er renovierte das Bauwerk komplett und baute es um; unter anderem wurden zwei zusätzliche Türme und ein weiteres Hauptgebäude errichtet. Auch ein neuer Weinkeller wurde angelegt. 1908 beauftragte Charles Claverie den Gartenarchitekten Jules Vacherot mit der Umgestaltung des im 15. Jahrhundert erstmals angelegten Gartens. Gotisierende Elemente an den Arkaden der Terrassen und den allegorischen Figuren auf den Balustraden bilden eine angenehme Mischung mit den Stilelementen der Renaissance. Der Wohntrakt wird von runden und viereckigen Türmen mit Treppentürmchen umrahmt. Giebelfenster mit reich dekorierten Frontispizen und steinernen Fensterkreuzen zieren das Dach. Das Schloss ist heute im Privatbesitz der Familie de St. Exupéry, die Haupt- und Nebengebäude historisch möglichst exakt restaurieren lässt. Insbesondere die Schlosskapelle von Anfang der 16. Jahrhunderts, die zu den ältesten Gebäudeteilen zählt, wurde in den Jahren 2018 bis 2023 aufwändig instand gesetzt.","w":"https://de.wikipedia.org/wiki/Schloss_Les_Milandes"},"ch-Q579961":{"n":"Schloss Ancy-le-Franc","c":"Burg in Frankreich","r":"Das Château d’Ancy-le-Franc ist ein Renaissanceschloss aus dem 16. Jahrhundert in der Stadt Ancy-le-Franc im Département Yonne in Frankreich.","h":"Ursprünglich befand sich an dieser Stelle eine Festung aus dem 12. Jahrhundert, die bis zum Ende des 16. Bestand hatte. Der Bau des bestehenden Schlosses begann 1544 auf Wunsch von Antoine III. de Clermont, dem Schwager von Diane de Poitiers und Sohn von Anne de Husson, der Gräfin von Tonnerre. Der Entwurf des Gebäudes wird traditionell dem italienischen Architekten Sebastiano Serlio zugeschrieben, der von König Franz I. nach Frankreich eingeladen worden war. Nach dem Tod Serlios 1554 in Fontainebleau übernahm der Architekt Pierre Lescot die Weiterführung der Arbeiten, wobei er die ursprünglichen Pläne Serlios respektierte. Die Inneneinrichtung ist das Werk von Francesco Primaticcio, der zu dieser Zeit im Schloss Fontainebleau arbeitete. Antoine de Clermont starb 1578 und sein Enkel Charles-Henri de Clermont († 1640) vollendete die Innenausstattung. Nach der Fertigstellung konnte das Schloss nun prestigeträchtige Gäste wie Heinrich III. (kurzer Besuch), Heinrich IV. (1591), Ludwig XIII. (1631) und Ludwig XIV. (1674) empfangen. 1683 war die Familie Clermont-Tonnerre gezwungen, die Dömäne und das Château d’Ancy-le-Franc an François Michel Le Tellier de Louvois, Minister Ludwigs XIV. zu verkaufen. Im folgenden Jahr erwarb Louvois die gesamte Grafschaft Tonnerre (einschließlich des Schlosses Maulnes). Er beauftragte den bekannten Landschaftsarchitekten André Le Nôtre mit der Anlage von Wegen und Gärten auf dem Gelände. Nach der Französischen Revolution gelang es der Familie, den Besitz des Schlosses wiederzuerlangen. Sie restaurierte das Gelände und das Innere des Schlosses. 1844 musste die Familie Ancy-le-Franc an Aimé Marie Gaspard de Clermont-Tonnerre, einen Nachkommen von Antoine III. von Clermont, abtreten.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_d%E2%80%99Ancy-le-Franc"},"ch-Q1329976":{"n":"Zitadelle von Besançon","c":"Festung in Bourgogne-Franche-Comté, Frankreich","r":"Die Zitadelle von Besançon ist eine Festung in der französischen Stadt Besançon, in Bourgogne-Franche-Comté. Es ist eines der Meisterwerke von Festungsbaumeister Sébastien Le Prestre de Vauban. Sein Standort wurde 1924 klassifiziert, dann wurde das Gebäude durch drei Dekrete von 1942 und 1944 als Monument historique eingestuft und seit dem 7. Juli 2008 auf der UNESCO-Liste des Weltkulturerbes innerhalb der Festungsanlagen von Vauban eingetragen, die zwölf repräsentative Stätten von Vaubans architektonischem Genie umfasst.","h":"Während des 17. Jahrhunderts wurde auf dem Mont Saint-Étienne ein militärisches Bauwerk errichtet, entworfen vom Militäringenieur Vauban im März 1668. Es waren jedoch die Spanier aus der königlichen Familie der spanischen Habsburger, die die Franche-Comté und Besançon besaßen seit der Hochzeit der Herzogin Maria von Burgund mit dem römisch-deutscher Kaiser, der sechs Jahre lang den Bau des Werks unter der Leitung von Prosper-Ambroise de Precipiano und der Unterstützung des flämischen Ingenieurs Cornelius Verboomb übernahm. Es wurden zwei Fronten gebaut: die Front Royal und die Front de Secours (es war Vauban, der 1668 mit dem Bau der letzteren begann). Die Provinz Franche-Comté zwischen 1674 im Schoß Ludwigs XIV. (durch den Friede von Nimwegen, der die Franche-Comté 1678 dauerhaft an Frankreich anschloss), beschloss der König, die Verteidigung der Stadt fortzusetzen und erheblich zu verbessern. 1683 wurden alle von Vauban festgesetzten Hauptarbeiten an der Zitadelle mit einer zweiten Fassade zur Stadt hin fertiggestellt. Dank der verstärkten Verteidigung ist die Stadt besser geschützt, die Zitadelle dient auch als Gefängnis und Unterkunft für die Garnisonstruppen. Fortschritte in der Artillerie im 19. Jahrhundert machten sie anfälliger. Sie ging jedoch siegreich aus den Blockaden hervor: gegen die Österreicher 1814 und die Preußen 1871 mit geringem Schaden. Staatsgefangene wie die Komplizen von La Voisin – angeklagt in Giftfällen, die den Hof des Sonnenkönigs skandalös kennzeichneten – wurden dort eingesperrt – Deserteure aus den Armeen Ludwigs XIV. und Ludwigs XV. sowie Royalisten während der Französischen Revolution. Kriegsgefangene, Österreicher, Engländer, Spanier wurden dort während des Ersten Kaiserreichs festgehalten.","w":"https://de.wikipedia.org/wiki/Zitadelle_von_Besan%C3%A7on"},"ch-Q1392601":{"n":"Schloss Hautefort","c":"Schloss in Frankreich","r":"Das Schloss Hautefort steht auf einem Plateau im Norden des französischen Départements Dordogne und überragt die Ortschaft Hautefort etwa 34 Kilometer nordöstlich von Périgueux. Es ist die größte barocke Schlossanlage Südwestfrankreichs und zugleich eines der wichtigsten Schlösser des Périgords. Im äußersten Osten des weißen Périgords gelegen, wurde das Schloss am 31. Oktober 1958 als Monument historique klassifiziert. Seine französischen Gärten und der Landschaftspark stehen seit dem 31. Dezember 1967 ebenfalls als Monument historique unter Denkmalschutz.","h":"Schon im 9. Jahrhundert gab es an der Stelle des heutigen Schlosses eine Burg der Vizegrafen von Limoges. Der Ort war bereits in römischer Zeit besiedelt. 1030 wurde die Burg Eigentum von Guy de Lastours, nachdem er im Namen des Grafen von Périgord die aufbegehrenden Vizegrafen bei Arnac geschlagen hatte. Nach seinem Tod im Jahr 1046 brachte seine einzige Tochter Aloaarz den Besitz an ihren Mann Aymar der Laron, der den Namen Lastours annahm. Durch die Heirat von Agnes de Lastours im Jahr 1160 kam die Burg an die Familie ihres Mannes Constantin de Born. Der stritt sich mit seinem Bruder, dem Troubadour Bertran de Born, um die Anlage, denn die beiden gehörten den verfeindeten Parteien der englischen Prinzen Heinrich des Jüngeren und Richard Löwenherz an. Betran hielt es mit dem Prinzen Heinrich, während Constantin dem Lager Richards angehörte. 1182 gelang es Betran, Constantin von der Burg zu vertreiben, doch schon im Jahr darauf belagerte Richard Löwenherz nach Heinrichs Tod die Anlage und konnte sie nach acht Tagen einnehmen. Er ließ Betran gefangen nehmen und schleifte die Wehranlage. Allerdings schenkte der englische König Heinrich II. dem Troubadour die Freiheit und gab ihm auch seine Burg zurück, die Betran ab 1184 wiederaufbaute. 1194/1196 zog sich der Burgherr in das Zisterzienserkloster Dalon zurück und wurde Mönch. Hautefort wurde von seinem Sohn übernommen. Zu jener Zeit bestand die Anlage aus einem großen Donjon und mehreren kleinen Türmen, die mit Kurtinen und Wehrgängen miteinander verbunden waren. Die männliche Linie der Familie de Born starb mit Bertrand III. aus. Erbin war seine Schwester Marguerite, die 1237 Aymar de Faye geheiratet hatte und ihm die Burg Hautefort zubrachte.","w":"https://de.wikipedia.org/wiki/Schloss_Hautefort"},"ch-Q1436883":{"n":"Schloss Maintenon","c":"Historisches Schlossdenkmal in Maintenon, in Eure-et-Loir, in Frankreich","r":"Das Schloss Maintenon ist ein Landschloss in der französischen Stadt Maintenon im Département Eure-et-Loir etwa 60 Kilometer südwestlich von Paris und rund 17 Kilometer nordwestlich von Chartres. Das Wasserschloss steht in der Region Centre-Val de Loire in der fruchtbaren Landschaft der Beauce und geht auf eine mittelalterliche Burg zurück.","h":"Die Wurzeln der heutigen Schlossanlage gehen auf das 13. Jahrhundert zurück, als die damalige Burg lediglich aus einem mächtigen Donjon bestand, der durch Vasallen des Grafen von Montfort erbaut worden war. Ende des 15. Jahrhunderts war sie im Besitz von Amaury (de) Loresse und zu einer viereckigen, von Wassergräben umgebenen Anlage ausgebaut worden, an deren Ecken der Donjon und drei Rundtürme aus Backstein standen, die durch Kurtinen mit Wehrgängen verbunden waren. Im ersten Jahrzehnt des 16. Jahrhunderts kam der Besitz an einen Gläubiger der Herren von Maintenon: Jean Cottereau. Er bekleidete unter den vier französischen Königen Ludwig XI., Karl VIII., Ludwig XII. und Franz I. das Amt eines Schatzmeisters von Frankreich (französisch: Trésorier de France). Kurz nachdem die Anlage in seinen Besitz übergegangen war, begann er mit umfangreichen Umbaumaßnahmen, welche die wehrhafte Burg in ein Landschloss im Stil der französischen Renaissance verwandelten. Cottereau ließ an der Nordseite zwischen den zwei Ecktürmen ein Corps de Logis errichten, dessen skulptierte Dekor-Elemente zum Teil noch an gotische Formen erinnern. Auch der niedrige Ostflügel wurde unter ihm erbaut, ebenso wie die 1521 fertiggestellte, nördlich des Schlosses stehende Kirche Saint-Nicolas, deren Errichtung im Jahr darauf die Gründung eines Kirchenkapitels mit einem Dekan und sechs Kanonikern nach sich zog. Die gesamten Bauarbeiten hielten bis in die 1520er Jahre an, denn erst in jenem Jahrzehnt wurde die Außenfassade des Nordflügels fertiggestellt. Cottereau ließ zudem – nach eigenen Entwürfen – einen ersten Obst- und Gemüsegarten auf dem Schlossareal anlegen, der heute jedoch nicht mehr erhalten ist. Die ältere der zwei Töchter Jeans, Isabeau (auch Isabelle genannt), heiratete am 13.","w":"https://de.wikipedia.org/wiki/Schloss_Maintenon"},"ch-Q2241121":{"n":"Schloss Fénelon","c":"Schloss in Frankreich","r":"Das Schloss Fénelon im Département Dordogne in der Kulturlandschaft des Périgord ist eines der besterhaltenen Schlösser Frankreichs. Der Baukomplex ist seit dem Jahr 1927 als Monument historique anerkannt.","h":"Das Schloss war vom 14. Jahrhundert an bis 1780 im Besitz der Familie Fénelon; im 17. Jahrhundert wurde es umgebaut. Vor allem während und nach der Französischen Revolution ging es durch mehrere Hände, ist aber auch heute noch in Privatbesitz. Besuchern stehen verschiedene Wohnräume und das Schlafzimmer François Fénelons offen, außerdem die Kapelle sowie die teilweise aus dem Fels herausgehauene Küche. Weiterhin gibt es eine Waffensammlung aus dem 15. bis 18. Jahrhundert sowie Tapisserien mit Darstellungen zum Werk Fénelons.","w":"https://de.wikipedia.org/wiki/Schloss_F%C3%A9nelon"},"ch-Q1765935":{"n":"Schloss Madrid","c":"zerstörtes Schloss westlich von Paris in Frankreich","r":"Das Schloss Madrid war ein Schloss der Renaissance in Frankreich. Es lag an der heutigen Porte de Madrid auf dem Gebiet der heutigen Gemeinde Neuilly-sur-Seine am Rande des Bois de Boulogne. Es wurde im 16. Jahrhundert als königliche Residenz errichtet, geriet im späteren 17. und im 18. Jahrhundert in zunehmenden Verfall und wurde während der Französischen Revolution abgerissen.","h":"Der Bau des Schlosses begann 1527 auf Anordnung des Königs Franz I., der 1525 in der Schlacht von Pavia gefangen genommen worden war und einige Monate in Madrid verbracht hatte. Die Bauarbeiten standen zunächst unter der Leitung des florentinischen Architekten Girolamo Della Robbia, anschließend übernahmen mehrere französische Architekten die Bauleitung, darunter Philibert de l’Orme. Abgeschlossen wurde der Bau im Jahr 1552 unter Heinrich II. Berühmt wurde das Schloss insbesondere durch die reich geschmückte Fassade, die von Della Robbia fast vollständig mit Basreliefs aus Terrakotta ausgestattet wurde, sowie durch die prachtvolle Innendekoration. Aus diesem Grunde wurde das Schloss auch Château de Faïence genannt. Architektonisch vereinte das Gebäude Einflüsse der italienischen Renaissance, mit dem H-förmigen Grundriss des Mittelteils und dem reichen Außenschmuck, und französische Traditionen in Form der Ecktürme an beiden Pavillons und der Anordnung der Innenräume, die den Schlössern von Chenonceau und Chambord nachempfunden waren. Im weiteren Verlauf des 16. Jahrhunderts, unmittelbar vor der Bartholomäusnacht, wurde das Schloss Madrid von Karl IX. und Katharina von Medici bewohnt, anschließend zu Beginn des 17. Jahrhunderts von Margarete von Valois. Unter Ludwig XIV., der das Schloss nie selbst aufsuchte, diente das Gebäude als Residenz des Staatssekretärs und späteren Siegelbewahrers Joseph Fleuriau d’Armenonville. 1666 wurde hier eine Manufaktur für Seidenstrümpfe eingerichtet, die jedoch wegen Mangels an qualifizierten Arbeitern und der Kriege Ludwigs XIV. nur kurzen Bestand hatte. Während der Régence von Ludwig XV.","w":"https://de.wikipedia.org/wiki/Schloss_Madrid"},"ch-Q1789782":{"n":"Schloss Candé","c":"Schloss in Frankreich","r":"Schloss Candé ist ein Schloss nahe der Stadt Monts im Département Indre-et-Loire in Frankreich. Es liegt auf einem Areal von 250 Hektar an der N10 und geht auf ein Landhaus zurück, das François Briçonnet, Bürgermeister von Tours (1499–1500) im Renaissancestil 1500 anstelle einer alten Burg errichten ließ. 1508 wurde es von dessen Tochter Jeanne Briçonnet vollendet. Im Jahr 1853 erwarb der reiche Kubaner Santiago Drake del Castillo das Anwesen und ließ es auf die dreifache Größe erweitern. Stilrichtungen waren dabei die Neugotik und die Neorenaissance.","w":"https://de.wikipedia.org/wiki/Schloss_Cand%C3%A9"},"ch-Q2418225":{"n":"Burg Vitré","c":"Burg im Département Ille-et-Vilaine, Frankreich","r":"Die Burg Vitré ist eine mittelalterliche Festung in der Stadt Vitré im Département Ille-et-Vilaine in Frankreich.","h":"Die erste Burg von Vitré wurde um das Jahr 1000 auf einer Motte auf dem Hügel Sainte-Croix aus Holz errichtet. Die Burg wurde mehrmals niedergebrannt und schließlich den Benediktinermönchen der Abtei Marmoutier vermacht. Die erste steinerne Burg wurde Ende des 11. Jahrhunderts von dem Baron Robert I. von Vitré erbaut. Der zur Verteidigung gewählte Standort, ein felsiger Vorsprung, beherrschte das Tal der Vilaine. Von diesem Gebäude ist noch ein Tor im romanischen Stil erhalten. In der ersten Hälfte des 13. Jahrhunderts baute Baron André III. die Anlage in ihrer heutigen dreieckigen Form um, die den Konturen der Felsen folgt und von trockenen Gräben umgeben ist. Nach seinem Tod fiel der Besitz an die Familie der Grafen von Laval. Guy XII. de Laval vergrößert die Burg im 15. Jahrhundert. In dieser Zeit werden die letzten Verteidigungsanlagen errichtet, insbesondere das Torhaus mit doppelter Zugbrücke, die Tour Saint-Laurent (der Hauptturm, der später mit Kanonenlöchern versehen wurde) und die Tour de la Madeleine (Magdalenenturm). Dennoch öffnete Guy XV. de Laval die Burg 1487 kampflos den französischen Truppen. Ab Ende des 15. Jahrhunderts konzentrierten sich die Umbauten auf die Verbesserung des Komforts des Schlosses, einschließlich des Baus von Galerien und eines Oratoriums im Stil der Renaissance (1530). Das bretonische Parlement suchte dreimal Zuflucht im Schloss (1564, 1582 und 1583), als in Rennes die Pest wütete. Unter den Familien Rieux und Cologny, die das Schloss zwischen 1547 und 1605 besaßen, beherbergte Vitré Protestanten und wurde für einige Jahre zu einer Hugenottenhochburg. Im Jahr 1589 widerstand das Schloss einer fünfmonatigen Belagerung durch den Herzog von Mercœur.","w":"https://de.wikipedia.org/wiki/Burg_Vitr%C3%A9"},"ch-Q1808966":{"n":"Schloss Villesavin","c":"Schloss in Frankreich","r":"Das Schloss Villesavin ist ein französisches Landschloss auf dem Ortsgebiet von Tour-en-Sologne im Département Loir-et-Cher der Region Centre-Val de Loire. Zwischen den Schlössern Chambord und Cheverny am Ufer des Beuvron in der Sologne gelegen, ist es eines der kleineren Loire-Schlösser.","h":"Obwohl Schloss Villesavin niemals in königlichem Besitz war, weilten trotzdem viele Mitglieder des französischen Königshauses als Gäste in den Gebäuden. Zu diesen Besuchern zählten unter anderem Franz I., Katharina von Medici, Maria de’ Medici und Ludwig XIII. Erster namentlich bekannter Eigentümer Villesavins war Guy I. de Châtillon, Graf von Blois, der dort 1315 einen bereits bestehenden Herrensitz erwarb. Der Besitz wurde Ende 1526 an Jean Le Breton verkauft, dem Bauherrn von Villandry. Er war ab 1528 königlicher Finanzsekretär sowie Verwalter der Grafschaft Blois und begleitete Franz I. auf dessen Italienfeldzügen. Bei seinem Tod im Jahr 1543 hinterließ er Villesavin gemeinsam mit Villandry seiner Frau Anne Gedoyn, die das Anwesen 1547 ihrer Tochter Léonor und deren Mann Claude Burgensis vermachte. Léonor bewohnte das Schloss nicht selbst, sondern lebte in Paris. Sie räumte die Gebäude leer und trat sie als Tilgung von Schulden in Höhe von 150 Livres tournois ab. 1611 erwarb Jean Phélypeaux den Besitz für 26.000 Livres. Seine Familie besaß das Anwesen bis zum Anfang des 18. Jahrhunderts, ehe es am 2. Juli 1719 an René Adine, Direktor der französischen Ostindienkompanie, verkauft wurde. Seine Familie nannte sich nachfolgend nach ihrem neuen Besitz „de Villesavin“. Die Erbtochter Marie de Villesavin brachte die Anlage 1779 an die Familie ihres Ehemanns, den Marquis Charles Robert de La Pallu. Während der Französischen Revolution wurde die Anlage zwar enteignet, aber nicht beschädigt. Lediglich das Mobiliar wurde am 19. August 1793 verkauft. Das leergeräumte Schloss erwarb am 20. Dezember 1820 der später überzeugte Legitimist Jules de Chardebœuf, comte de Pradel, der erste Kammerherr Ludwigs XVIII., der das Schloss im Stil des Historismus verändern ließ.","w":"https://de.wikipedia.org/wiki/Schloss_Villesavin"},"ch-Q2452513":{"n":"Villa Ephrussi de Rothschild","c":"Villa im Renaissance-Stil oberhalb der Côte d'Azur, Alpes-Maritimes, Frankreich","r":"Die Villa Ephrussi de Rothschild, auch bekannt als Villa Ile-de-France, ist eine Villa im Renaissance-Stil oberhalb der Côte d’Azur.","h":"Die Villa im Stil der Neorenaissance wurde zwischen 1905 und 1912 auf dem Cap Ferrat in der Gemeinde Saint-Jean-Cap-Ferrat für die Baronesse Béatrice de Rothschild (1864–1934) erbaut. «Das Museum gibt eine besonders anschauliche Vorstellung davon, dass die Besitzer der Residenz große Liebhaber der Kunst der Belle Époque waren, die einen besonderen Anreiz im 18. Jahrhundert fand.» Corcuera (Vogue Décoration, 1985) Die Baronin vermachte die Villa nach ihrem Tode der Académie des Beaux-Arts, die sie 1937 für die Öffentlichkeit zugänglich machte. Béatrice de Rothschild wurde am 14. September 1864 geboren und entstammte der Ehe von Baron Alphonse de Rothschild und Leonora de Rothschild (1837–1911). Sie gehörte demnach dem Pariser Zweig der Rothschild-Familie an. Sie heiratete im Alter von 19 Jahren am 5. Juni 1883 den russisch-jüdischen Bankier Maurice Ephrussi (1849–1916). Aufgrund der Spielsucht ihres Mannes trennte sich das Paar 1904. Das Paar sammelte leidenschaftlich Gegenstände zur Architektur, der Natur und der Kunst sowie Unikate. Die Baronesse selbst führte einen aufwändigen Lebensstil. Ebenso wie ihr Vater, Alphonse de Rothschild, Leiter der Banque de France sowie zugleich einer der Hauptaktionäre der damals größten französischen Privatbahn Compagnie des chemins de fer de Paris à Lyon et à la Méditerranée (PLM) und Mitglied der Académie des Beaux-Arts oder auch ihr Onkel Alfred in London, sammelte Béatrice Ephrussi de Rothschild Kunstgegenstände und errichtete sich mehrere Residenzen. Im Laufe ihrer Karriere sammelte sie entsprechend der Sitte der großen Kunstsammler ihrer Zeit (u. a. Henri Cernuschi, Jacquemart-André, Richard Wallace, Henry Clay Frick) mit Vorliebe französische oder außereuropäische Kunst des 18. Jahrhunderts.","w":"https://de.wikipedia.org/wiki/Villa_Ephrussi_de_Rothschild"},"ch-Q2971307":{"n":"Schloss La Mothe-Chandeniers","c":"Schlossruine im französischen Département Vienne","r":"Das Schloss La Mothe-Chandeniers ist eine Schlossruine bei der Stadt Les Trois-Moutiers in der Region Nouvelle-Aquitaine in Frankreich.","h":"Die ehemalige Burg, deren Entstehung in das 13. Jahrhundert zurückdatiert werden kann, stand ursprünglich inmitten eines großen Waldes und wurde Motte Bauçay (oder Baussay) genannt, was auf die früheren Besitzer, die Familie Bauçay, zurückzuführen ist. Die Burg wurde im Mittelalter zweimal von den Engländern erobert und während der Französischen Revolution verwüstet. 1809 wurde es von dem wohlhabenden Geschäftsmann François Hennecart gekauft, der sich verpflichtete, die Anlage zu restaurieren. Sie wurde jedoch 1857 unrestauriert an den Baron Edgard Lejeune, einen ehemaligen Stallmeister Napoleons III., verkauft. Um 1870 wurde die Burg durch einen englischen Architekten im romantischen Stil zu einem Wasserschloss (ähnlich wie das Schloss Azay-le-Rideau) umgebaut. Am 13. März 1932, als unter Baron Robert Lejeune die Installation einer Zentralheizung erfolgte, brach ein heftiges Feuer aus, welches das Gebäude zerstörte. Lediglich die Kapelle, die Nebengebäude und das Taubenhaus blieben unversehrt. Die Zeitung Le Figaro berichtete in ihrer Ausgabe vom 14. März darüber und beklagte besonders den Verlust einer Bibliothek mit seltenen Büchern sowie einzigartiger Gobelins, antiker Möbel und wertvoller Gemälde. Es wurden keine Anstrengungen unternommen, das Schloss zu restaurieren, sodass es sich noch immer im Zustand des Verfalls befindet. Allerdings versucht ein außergewöhnliches Crowdfunding-Projekt, das Schloss mittels Tausender Teilinhaber zu kaufen und zu restaurieren.","w":"https://de.wikipedia.org/wiki/Schloss_La_Mothe-Chandeniers"},"ch-Q2032139":{"n":"Schloss Serrant","c":"Schloss in Frankreich","r":"Das Schloss Serrant befindet sich nahe der französischen Ortschaft Saint-Georges-sur-Loire im Département Maine-et-Loire.","w":"https://de.wikipedia.org/wiki/Schloss_Serrant"},"ch-Q2054341":{"n":"Schloss Saché","c":"Schloss in Frankreich","r":"Das Schloss Saché liegt am Rande der Ortschaft Saché im Département Indre-et-Loire südöstlich von Tours in Frankreich. Das Gebäude wurde 1932 unter Denkmalschutz gestellt und beheimatet seit 1951 ein Balzac-Museum. Es zählt zu den Schlössern der Loire.","h":"Bereits im 14. Jahrhundert existierte an gleicher Stelle ein Vorgängerbau, von dem heute nur noch ein Rest der ehemaligen Ringmauer übrig ist. Im 15. Jahrhundert erfolgte ein Neubau des Gebäudes, das Ende des 16. Jahrhunderts erweitert wurde. Jean de Margonne ließ es im frühen 19. Jahrhundert an den damaligen Zeitgeschmack anpassen. Jean de Margonne war der väterliche Freund und Förderer Honoré de Balzacs. Der in Tours geborene und in Paris lebende Schriftsteller hatte dadurch Gelegenheit, sich zwischen 1824 und 1837 immer wieder für längere Zeit hierher zurückzuziehen. Ein Teil seiner Romane ist in diesem Schloss im Herzen seiner geliebten Touraine entstanden. Die Anlage ist heute im Besitz des Départements Indre-et-Loire.","w":"https://de.wikipedia.org/wiki/Schloss_Sach%C3%A9"},"ch-Q740250":{"n":"Burg Tarascon","c":"spätmittelalterliche Burg am Rhoneufer im Département Bouches-du-Rhône, Südfrankreich","r":"Die Burg Tarascon, auch Schloss Tarascon, französisch Château de Tarascon oder Château du roi René, ist eine spätmittelalterliche Burg aus der ersten Hälfte des 15. Jahrhunderts in der provenzalischen Stadt Tarascon im Département Bouches-du-Rhône. Sie liegt am linken Ufer der Rhone. Wegen ihrer Architektur, ihrer Lage und ihres guten Erhaltungszustands gilt sie als eine der schönsten mittelalterlichen Burgen Frankreichs.","h":"Die Burg diente den Grafen der Provence als Residenz. René I. hielt sich oft dort auf und nutzte das Gebäude auch umfassend zu repräsentativen Zwecken. Von Anbeginn diente es allerdings auch als Gefängnis. So war 1480 ein katalanischer Anhänger des Königs von Aragon, eines politischen Gegners von René I., dort inhaftiert. In die Wände zweier Kerkerzellen ritzte er außergewöhnlich hochwertige Graffiti von Kriegs- und Handelsschiffen sowie anderen Motiven religiöser sowie profaner Natur. Besonders intensiv als Gefängnis genutzt wurde die Burg zwischen 1642 und 1926. Die Räume wurden in Einzelzellen oder Zellen für mehrere Gefangene umgebaut. Während der Französischen Revolution wurden dort nach dem Sturz Robespierres 1795 Anhänger von diesem hingerichtet. Aus der langen Nutzungszeit des Bauwerks als Gefängnis sind auch hunderte Graffiti aus dem 17. und 18. Jahrhundert erhalten, die von spanischen Soldaten, britischen und niederländischen Matrosen in die Wände geritzt wurden und von den Kriegen dieser Epochen zeugen. 1840 wurde die Burg unter Denkmalschutz gestellt. Seit 1933 kann sie besichtigt werden. 2008 ging sie in das Eigentum der Gemeinde Tarascon über. Seit 2009 beherbergt die Burg, die seither den Namenszusatz Centre d’art René d’Anjou („Kunstzentrum René von Anjou“) führt, eine Ausstellung zeitgenössischer Kunst mit Bezug zur lokalen Sage von der Tarasque, einem Ungeheuer, das von der Heiligen Martha besiegt worden sein soll. Es werden unter anderem Auftragswerke von Christian Lacroix, Françoise Pétrovitch, Christian Gonzenbach und Dominique Angel gezeigt.","w":"https://de.wikipedia.org/wiki/Burg_Tarascon"},"ch-Q769365":{"n":"Schloss Montpoupon","c":"Schloss in Frankreich","r":"Das Schloss Montpoupon gehört zur französischen Gemeinde Céré-la-Ronde im Département Indre-et-Loire der Region Centre-Val de Loire. In seinen Wirtschaftsgebäuden ist seit 1971 ein Jagdmuseum beheimatet.","h":"Im Mittelalter war der Ort strategisch bedeutend genug, um den Bau einer Burg zu rechtfertigen. Von dieser Anlage aus dem 13. Jahrhundert sind nur die Türme erhalten. Vom 14. bis zum 17. Jahrhundert war das Lehnsgut im Besitz der Familie de Prie. Die Lehnsherren wurden für ihre Treue zum Haus Valois mit der Übertragung wichtiger Ämter belohnt, wie zum Beispiel dem eines Kämmerers oder dem eines Großmeisters der Armbrustschützen. Die Schlossanlage wurde im 14. und 16. Jahrhundert nach den Erfordernissen der modernen Kriegsführung erweitert. Der Torbau, die hohen Wohntrakte aus dem 15. Jahrhundert, der Westturm sowie ein isolierter Hauptturm mit Wehrgang und Pechnasen, vermitteln trotz Abriss der Mauern während der Französischen Revolution einen Eindruck von diesen befestigten Schlössern an strategischen Punkten des königlichen Straßennetzes. Montpoupon blieb bis in die Mitte des 18. Jahrhunderts im Besitz der männlichen Nachfolger der de Prie. Danach wurde das Schloss jeweils von der Mutter an die Tochter vererbt. Die Damen zeigten jedoch wenig Interesse an den Baulichkeiten, die mit der Zeit verfielen. 1763 erwarb Markgraf von Tristan, damaliger Bürgermeister von Orléans, das Anwesen. Er verbesserte die Pachthöfe und Mühlen, führte eine Flurbereinigung durch und regelte das Wasserrecht, um Montpoupon zu einem einträglichen Besitz zu machen. Zu guter Letzt beschloss er, das Schloss zu restaurieren, was sich aufgrund der Revolution nicht mehr in die Tat umsetzen ließ. Um 1840 ließ der neue Besitzer des Schlosses die Wirtschaftsgebäude errichten, die noch heute existieren. Im Jahre 1857 erwarb schließlich Jean Baptiste de la Motte Saint Pierre das Anwesen.","w":"https://de.wikipedia.org/wiki/Schloss_Montpoupon"},"ch-Q747306":{"c":"Burg in Frankreich","r":"Fort La Latte ist eine Burg auf dem Gebiet der Gemeinde Plévenon im Département Côtes-d’Armor in der Bretagne in Frankreich. Sie thront auf einer schmalen Landzunge am Eingang der Baye de la Fresnaye, etwa 4 km südöstlich von Cap Fréhel und 35 km von Saint-Malo.","h":"Erbaut wurde die Burg im 13. Jahrhundert von der einflussreichen Familie Goyon de Matignon. Im Jahre 1379 wurde die Burg von Bertrand du Guesclin erobert und für Karl V. beschlagnahmt. Durch den Vertrag von Guérande bekamen ihre Besitzer die Burg aber schon 1381 wieder zurück. 1490 wurde die Burg von den Engländern erfolglos belagert. Aus Rache belagerte 1597 Saint-Laurent, ein Bote des Herzogs de Mercœur, die Burg und besetzte sie. Die Burg, zu dieser Zeit schon La Latte genannt, wurde in Brand gesteckt und zerstört. Nur die Warte blieb damals verschont. Garengeau (Schüler des berühmten Militärarchitekten Vauban) war unter Ludwig XIV. für die Befestigung der Küste und die Verteidigung von Saint-Malo zuständig. Er übernahm die Ruine und baute sie mit Einwilligung der Matignons zwischen 1690 und 1715 wieder auf. Große Teile der Struktur der heutigen Anlage wurden damals errichtet. Außerdem wurde die Festung mit Kanonenbatterien ausgestattet, um nach Saint-Malo fahrende Schiffe vor Übergriffen durch englische oder holländische Angreifer zu schützen. Anfang des 18. Jahrhunderts wurde die Burg von der Familie Goyon dem Kriegsministerium übergeben. 1793 wurde die Burg weiter ausgebaut, unter anderem wurde ein großer Ofen gebaut, der dazu diente, die Kanonenkugeln vor dem Schuss auf Rotglut zu erhitzen. Dieser Kugelofen ist bis heute erhalten geblieben. Während der Herrschaft der Hundert Tage im Jahr 1815 versuchten Bürger aus Saint-Malo die Burg zu erstürmen, aber ohne Erfolg. Dies war die letzte kriegerische Auseinandersetzung an der Festung. Im Laufe des 19. Jahrhunderts wurde die Burg auf Befehl des Kriegsministeriums verlassen und nur ein „Hausmeister“ blieb zurück. 1892 ging die Festung in den Privatbesitz der Domaines über.","w":"https://de.wikipedia.org/wiki/Fort_La_Latte"},"ch-Q1013196":{"n":"Burg Najac","c":"Burg in Frankreich","r":"Die Burg Najac ist die Ruine einer mittelalterlichen Gipfelburg in der französischen Gemeinde Najac im Département Aveyron, Region Okzitanien. Sie ist eine der stärksten Befestigungen in der Region und wurde nie erobert.","w":"https://de.wikipedia.org/wiki/Burg_Najac"},"ch-Q1013993":{"n":"Burg Sedan","c":"Burg in Frankreich","r":"Die Burg von Sedan befindet sich in der Stadt Sedan, die im Departement Ardennes der Region Champagne-Ardenne im Nordosten Frankreichs in der Nähe zu Belgien liegt. Die mittelalterliche Burganlage mit ihren 35.000 m², die sich auf sieben Etagen erstrecken, ist eine der größten ihrer Art in Europa. Die Burg ist seit dem 4. Januar 1965 als Monument historique klassifiziert.","h":"Um 1424 begann Eberhard II. von der Marck-Arenberg mit dem Bau der Burg von Sedan. Ursprünglich befand sich dort ein Benediktinerkloster, das erstmals 1306 erwähnt wurde. Nun wurde innerhalb von sechs Jahren ein Herrenhaus mit zwei Türmen um eine Kirche herumgebaut, wobei Teile des Donjon aus dem Kloster erbaut wurden. Als Eberhard II. starb, verstärkte sein Sohn Johann II. von Marck-Arenberg die Burganlage, doch erst sein Enkel Robert I. de La Marck beendete die Bauarbeiten. Im Jahr 1530 wurden die Festungsmauern des Herrenhauses durch den Bau eines Ringwalls modernisiert und um Geschützwälle ergänzt. Henri de Turenne wurde 1611 in der Burg von Sedan geboren. Heute ist die Burg eine Touristenattraktion. Sie beherbergt die Touristinformation der Stadt und ein Museum. Außerdem befindet sich ein Hotel in den alten Gemäuern.","w":"https://de.wikipedia.org/wiki/Burg_Sedan"},"ch-Q638089":{"n":"Schloss Plessis-lès-Tours","c":"Schloss in Frankreich","r":"Plessis-lèz-Tours, früher Plessis-lez-Tours oder Plessis-du-Parc ist ein Schloss in der französischen Gemeinde La Riche im Département Indre-et-Loire, einem westlichen Vorort von Tours, das im 15. Jahrhundert erbaut wurde und zeitweilig als königliche Residenz diente. Es wurde während der Revolution teilweise zerstört, beherbergte nach einer Restaurierungskampagne (1932) zeitweilig ein Museum zur Geschichte der Seidenweberei der Touraine und dient heute einer Schauspieltruppe als Sitz.","h":"Das Schloss, damals noch Montils-lez-Tours oder Montils-les-Tours genannt, ließ die Familie Maillé im 15. Jahrhundert auf ihren zwischen der Loire um deren Nebenfluss Cher gelegenen Besitztümern errichten. Die Maillés verkauften die Domäne im Jahr 1463 an den stets misstrauischen König Ludwig XI. Er ließ sie von einer doppelten Mauer umgeben, einen Park anlegen und das Schloss vergrößern, das er zu seinem bevorzugten Aufenthaltsort machte. Als der König im Jahr 1483 schwer erkrankte, ließ er durch Papst Sixtus IV. den ehemaligen Eremiten und Ordensgründer Franz von Paola (1436–1507), der im Ruf stand, wundersame Heilungen zu vollbringen, an sein Krankenbett rufen. Der kalabresische Mönch traf im April des gleichen Jahres in Plessis ein und leistete dem König bis zu seinem dort am 30. August 1483 eingetretenen Tod seelischen Beistand. Franz von Paola ließ sich in Plessis nieder, wo er mit Hilfe von Ludwigs XI. Sohn Karl VIII. 1489 das Couvent des Grands Minimes du Plessis genannte Kloster gründen konnte; die erste Gemeinschaft der „Mindesten Brüder“ in Frankreich. Er starb am 2. April 1507 in seinem Kloster, wo er auch beigesetzt wurde. Karl VIII. und seine junge Frau Anne de Bretagne residierten nach ihrer Hochzeit (1491) in Plessis, wo ihre Kinder Charles Orland, Charles und François geboren wurden, von denen keines überlebte. Anne heiratete, nachdem Karl VIII. in Amboise verunglückt und gestorben war, dessen Cousin und Nachfolger Ludwig XII., der Plessis verschönern ließ und als Jagdschloss nutzte. Die 1506 im Großen Saal von Plessis einberufenen Generalstände verliehen dem Monarchen den Titel Père du Peuple (deutsch: Vater des Volkes). Unter Heinrich III.","w":"https://de.wikipedia.org/wiki/Schloss_Plessis-l%C3%A8s-Tours"},"ch-Q1014245":{"n":"Burg Termes","c":"Burg in Frankreich","r":"Die Burg Termes ist die Ruine einer mittelalterlichen Höhenburg im Bergmassiv der Corbières im heutigen Département Aude in der französischen Region Okzitanien. Sie steht seit dem 25. September 1989 als Monument historique unter Denkmalschutz.","h":"Rechtlich gehörte Termes zum Herrschaftsbereich der Vizegrafen von Carcassonne, faktisch waren die Seigneurs de Termes jedoch weitgehend unabhängig. Aus Quellen des 11. und 12. Jahrhunderts ist zu entnehmen, dass etwa 60 Dörfer, davon 28 befestigt, zum Einflussbereich der Burgherren von Termes gehörten. In den Corbières wurde im Mittelalter Erz abgebaut, ein Teil der Einnahmen floss an die Seigneurs de Termes. Die Burg Termes wird bereits in der Mitte des 12. Jahrhunderts erwähnt. Gegen Ende des Jahrhunderts bot sie den vielen Katharern Schutz, die sich einem befestigten Dorf (bourg oder castrum) zu ihren Füßen angesiedelt hatten. Im Jahr 1210 wurde die Anlage daraufhin im Verlauf des Albigenserkreuzzugs (1209–1229) als eine der Katharerburgen belagert, wobei beide Seiten über Katapulte verfügten. Nach knapp viermonatiger Belagerungszeit – die Wasserzisternen waren leer und die Verteidiger an der Ruhr erkrankt – fiel die Burg im Dezember 1210 an die Kreuzritter unter Simon de Montfort. Raimond de Termes, der Vater von Olivier de Termes, wurde gefangen genommen und starb kurz darauf im Kerker von Carcassonne. Im Jahre 1228 wurde in der weitgehend zerstörten Burg eine königliche Garnison einquartiert, die einerseits ein Wiederaufflammen der Katharerbewegung verhindern sollte, andererseits aber auch eine strategisch wichtige Position im Kampf gegen die Expansionsbestrebungen der Krone von Aragon innehatte. Ludwig IX. ließ die Burg ab etwa 1260 neu erbauen und erweckte sie somit zu neuem Leben. Bereits sieben Jahre vor dem Pyrenäenfrieden 1659 ordnete König Ludwig XIV. die Zerstörung der Burg an, die zu einem Stützpunkt für Räuber und Wegelagerer geworden war.","w":"https://de.wikipedia.org/wiki/Burg_Termes"},"ch-Q654569":{"n":"Schloss Montreuil-Bellay","c":"Schloss in Frankreich","r":"Das Schloss Montreuil-Bellay liegt in der französischen Stadt Montreuil-Bellay am Fluss Thouet im Département Maine-et-Loire. Schon die Römer wussten die strategisch günstige Lage auf dem Bergrücken zu schätzen und gründeten hier ein Oppidum.","w":"https://de.wikipedia.org/wiki/Schloss_Montreuil-Bellay"},"ch-Q1339136":{"n":"Schloss Grésillon","c":"Esperanto-Kulturhaus Schloss Grésillon in Frankreich","r":"Das Schloss Grésillon liegt 250 Kilometer südwestlich von Paris in der Kleinstadt Baugé zwischen den Städten Angers, Le Mans und Tours im westlichen Frankreich.","w":"https://de.wikipedia.org/wiki/Schloss_Gr%C3%A9sillon"},"ch-Q1462683":{"n":"Schloss Les Réaux","c":"Schloss in Frankreich","r":"Schloss Les Réaux liegt nahe dem Nordufer der Loire im Département Indre-et-Loire in der Region Centre in Frankreich, vier Kilometer von der Ortschaft Bourgueil entfernt. Wahrscheinlich wurde es für Jean Briçonnet, um 1515 Erbe des Anwesens, erbaut. Der Name Les Réaux geht auf den französischen Schriftsteller Gédéon Tallemant des Réaux zurück, der das Schloss 1651 erwarb.","w":"https://de.wikipedia.org/wiki/Schloss_Les_R%C3%A9aux"},"ch-Q1518981":{"n":"Schloss Puymartin","c":"Schloss in Frankreich","r":"Schloss Puymartin liegt, versteckt inmitten des Périgord noir, in der französischen Region Nouvelle-Aquitaine im Département Dordogne zwischen Sarlat und Les Eyzies auf dem Gebiet der Gemeinde Marquay. Die Festung sicherte die Verkehrswege nordwestlich von Sarlat.","h":"Schloss Puymartin wurde ursprünglich Mitte des 13. Jahrhunderts von den Äbten von Sarlat erbaut. Um 1270 ging es in den Besitz der Familie Serviens über. Im Jahr 1357 eroberten während des Hundertjährigen Krieges englische Söldner das Schloss und zogen erst nach Zahlung eines hohen Lösegeldes wieder ab, allerdings nicht, ohne es vorher geschleift zu haben. Im Jahr 1450 kaufte Radulphe de Saint-Clar das aufgelassene Anwesen zurück und nahm den Wiederaufbau sowie die Erweiterung in Angriff. Im 16. Jahrhundert war das Schloss Hauptquartier seines Enkels Raymond de Saint-Clar, Anführer der Katholiken des Perigord noir, in seinem siegreichen Kampf gegen die Protestanten. Ein jahrzehntelanger Streit um das Eigentumsrecht zwischen Suzanne de Saint-Clare und ihrem Bruder Jean endete zugunsten von Suzanne. Unter Ludwig XIV. besaß die Familie La Pleinie das Schloss, und in der Zeit danach François Roffignac de Carbonnier de Marzac. Der Seigneur wurde in der Französischen Revolution eingekerkert und das Bauwerk sich selbst überlassen. Kurz vor Ende des 19. Jahrhunderts ließ der Marquis Marc de Carbonnier de Marzac das Schloss restaurieren und teilweise im neugotischen Stil umbauen. Seine einzige Tochter heiratete den Grafen Jacques de Montbron, Vater des heutigen Besitzers Henri de Montbron. Es gibt die Schauergeschichte einer um Mitternacht durch die Räume geisternde „Weiße Dame“. Diese geht auf Thérèse de Saint-Clar zurück. Sie war die Ehefrau von Jean de Saint-Clar, Seigneur des Schlosses Puymartin im 16. Jahrhundert, und wurde von ihrem Gatten in den Armen ihres Liebhabers überrascht. Der betrogene Ehemann rächte sich, indem er sie 15 Jahre lang gefangen hielt und nach ihrem Tode den Raum zumauern ließ.","w":"https://de.wikipedia.org/wiki/Schloss_Puymartin"},"ch-Q1579344":{"n":"Schloß von Sceaux","c":"Schloss in Frankreich"},"ch-Q1859459":{"n":"Schloss La Brède","c":"Schloss im Département Gironde, Frankreich","r":"Das Schloss La Brède steht etwa einen Kilometer westlich des Ortes La Brède und 15 km südlich der Stadt Bordeaux im französischen Département Gironde. Im Schloss wurde der bekannte Richter und Rechtsphilosoph Montesquieu geboren, der dort lebte und die meisten seiner Arbeiten schrieb. Das gesamte Areal steht seit dem 7. Mai 2008 unter Denkmalschutz.","w":"https://de.wikipedia.org/wiki/Schloss_La_Br%C3%A8de"},"ch-Q1789926":{"n":"Schloss Flers","c":"Schloss in Villeneuve-d’Ascq, Frankreich","r":"Das Schloss Flers ist ein französisches Schloss im Stil der flämischen Architektur des 17. Jahrhunderts, das in Villeneuve-d’Ascq im Département Nord steht. Es ist Sitz des Fremdenverkehrsamts der Stadt und beherbergt ein Museum. Der Name des Schlosses bezieht sich auf das Dorf Flers-lez-Lille, das in der Nähe liegt.","h":"Der Bau des Schlosses Flers wurde 1661 beendet. Von 1667 bis 1747 gehörte es der Familie Dekessel, den Lehnsherren von Flers. Im Jahr 1747 erhielt Philippe André de Baudequin, Lehnsherr von Sainghin, das Gebiet von Flers und das Schloss von seinem Vetter Dekessel. Marie-Claire-Josephe de Baudequin heiratete den Grafen Ladislas de Diesbach. Als seine Frau in 1791 starb, übernahm er das Schloss und wurde der letzte Lehnsherr von Flers. Im Jahr 1787 wurde das Schloss baulich verändert: Die Mittelpfosten der Fenster wurden entfernt, Kassettendecken ersetzten die französischen Decken, und neue Kamine wurden eingebaut. Eine neue Zugbrücke, die noch heute existiert, ersetzte einen Vorgänger. Auch der Arkadengang stammt aus dieser Zeit. Während der Französischen Revolution wanderten die damaligen Schlossbewohner (zwei Tanten des Grafen) aus und kehrten in die Schweiz zurück. Das Schloss wurde dem ehemaligen Gärtner anvertraut. Im Jahr 1937 kaufte es Paul Delesalle-Dewas von der Familie von Diesbach. Im Januar 1951 wurde das Schloss als Monument historique eingetragen. Der französische Staat erwarb Schloss Flers im Jahr 1969. Vier Jahre später kaufte es der Gemeindeverbund und 1986 schließlich die Stadt Villeneuve-d’Ascq. Eine anschließende Restaurierung dauerte bis 1991. Seit Abschluss der Restaurierungsarbeiten beherbergt das Gebäude das Fremdenverkehrsamt und andere städtische Dienste. Vier Räume im Untergeschoss werden zudem von einem Museum genutzt. Dieses zeigt Ausstellungen zur archäologischen Themen sowie zur lokalen Geschichte und der regionalen Ethnografie.","w":"https://de.wikipedia.org/wiki/Schloss_Flers_(Villeneuve-d%E2%80%99Ascq)"},"ch-Q2206135":{"c":"Burg in Frankreich"},"ch-Q2259452":{"n":"Burg Annecy","c":"Burg in Frankreich","r":"Die Burg Annecy ist die alte Residenz der Grafen von Genf und der Herzöge von Nemours. Sie liegt im Stadtkern der gleichnamigen Stadt, des Zentrums des Département Haute-Savoie, welches zur Region Auvergne-Rhône-Alpes im Südosten Frankreichs gehört. Die Burg wurde 1953 von der Stadt Annecy aus dem Besitz des Ministeriums der Armee erworben, anschließend restauriert und zum Museum umgebaut. Sie beherbergt heute das Musée-Château. Die Burg steht seit dem 12. Oktober 1959 als Monument historique unter Denkmalschutz.","h":"Die Burg wurde zwischen dem 12. Jahrhundert und dem 16. Jahrhundert erbaut. In dieser Zeit war sie der Sitz der Grafen von Genf und der Herzöge von Nemours. Mehrfach wurde die Burg durch Feuer teilweise bis schwer beschädigt. Nach der Feuersbrunst von 1320 wurde die Burg Annecy für zwei Jahre als Residenz aufgegeben und in dieser Zeit unter der Regentschaft von Amadeus III. von Genf neu aufgebaut. Seit dem 17. Jahrhundert wurde sie bis zum Jahre 1947 als Kaserne genutzt.","w":"https://de.wikipedia.org/wiki/Burg_Annecy"},"ch-Q2970742":{"n":"Burg Suscinio","c":"Burg in Sarzeau, Département Morbihan, Bretagne, Frankreich","r":"Die Burg Suscinio oder Susinio ist ein bretonisches Schloss, das im späten Mittelalter als Residenz der Herzöge der Bretagne errichtet wurde. Es befindet sich in der Gemeinde Sarzeau im Département Morbihan nahe der Atlantikküste. Die Anlage besteht aus dem Wasserschloss, einer Kapellenruine, einem Taubenturm und einigen verfallenen Nebengebäuden.","h":"Ein erstes Jagdhaus am Rand eines großen Waldes wird 1218 erwähnt. In der zweiten Hälfte des 14. Jahrhunderts wurde das Herrenhaus in eine Festung mit Zugbrücke und zwei Tortürmen, Wachttürmen mit Schießscharten, Wehrgänge mit Maschikulis, Burggräben usw. umgewandelt, in einer Zeit, als die Erben des Herzogtums um ihren Besitz kämpfen mussten (die Bretagne war noch nicht vollständig mit Frankreich vereinigt und wurde es erst 1514), nachdem die Burg von Bertrand du Guesclin, dem Connétable von Frankreich († 1380), eingenommen worden war. Johann V. († 1399), und Johann VI. († 1442), errichteten einen neuen Herrschaftssitz mit einem großen, neuen Eckturm, der Tour Neuve. In der zweiten Hälfte des 15. Jahrhunderts gehörte Suscinio zum Wittum seiner Schwiegertochter Isabelle Stewart. Ende des 15. Jahrhunderts wurde eine Kasematte zum Schutz der Artillerie hinzugefügt.","w":"https://de.wikipedia.org/wiki/Burg_Suscinio"},"ch-Q1090405":{"n":"Château Cheval Blanc","c":"Schloss in Frankreich","r":"Château Cheval Blanc ist ein berühmtes französisches Weingut und liegt in Saint-Émilion in unmittelbarer Nachbarschaft zu Pomerol. Neben Château Ausone war es das einzige Weingut aus der Appellation Saint Émilion, das zwischen 1955 und 2022 ununterbrochen mit der höchsten Einstufung Premier Grand Cru Classé A der Klassifizierung der Weine von Saint-Émilion. Im Juni 2021 kündigte der Verantwortliche Pierre-Olivier Clouet an, sich für die Klassifizierung 2022 nicht für eine Auszeichnung zu bewerben; gleiches galt für Château Ausone. Sie kritisierten insbesondere, dass den Aspekten Tourismus und sozialen Netzwerken zu breiten Raum in der Bewertung gegeben wurde.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Cheval_Blanc"},"ch-Q1012864":{"n":"Burg Langoiran","c":"Burg in Frankreich","r":"Die Burg Langoiran ist die Ruine einer Höhenburg in der Gemeinde Langoiran rund 25 Kilometer südlich der Stadt Bordeaux im französischen Département Gironde. Sie ist seit Mai 1892 als Monument historique klassifiziert.","h":"Obwohl Burg und Burgherren bereits im 11. Jahrhundert erstmals urkundlich erwähnt wurden, stammen die ältesten erhaltenen Teile aus dem 13. Jahrhundert. Die neuesten Teile stammen vom Ende der Renaissance. Das Lehen von Langoiran gehörte jahrhundertelang zu den bekanntesten und mächtigsten des Herzogtums Aquitanien und war darum oft in die Auseinandersetzungen zwischen englischen und französischen Königen verwickelt. Da dieses Herzogtum nicht zu England gehörte, sondern persönlicher Besitz der englischen Könige war, nannten sich die Herrscher auf dem Thron Wilhelms des Eroberers ab Heinrich II. König von England und Herzog von Aquitanien. Die Herzöge von Langoiran fochten immer auf der Seite des englischen Königs, nur Berard d’Albret war am Ende seines Lebens, 1370 nach der Schlacht von Eymet, gezwungen, für Frankreichs König zu kämpfen. Im Laufe der Zeit kam die Burg in den Besitz der berühmtesten Geschlechter Südfrankreichs: Die Escoussan errichteten die heutige Anlage vom 13. bis zum 14. Jahrhundert, die Albret besaßen es in der zweiten Hälfte des 14. Jahrhunderts, die Montferrand vom Ende des 14. bis zum Beginn des 17. Jahrhunderts. Im Herbst 1650 zerstörten Truppen unter dem Kommando von Bernard de Nogaret de La Valette d’Épernon die Burg, da der Besitzer, der Parlamentspräsidenten von Bordeaux Guillaume d’Affis, Anhänger der Fronde war.","w":"https://de.wikipedia.org/wiki/Burg_Langoiran"},"ch-Q657892":{"n":"Schloss Le Lude","c":"Schloss in Frankreich","r":"Das Schloss Le Lude befindet sich am westlichen Ufer des Flusses Loir in der französischen Stadt Le Lude im Département Sarthe. Es zeichnet sich besonders durch die Vielfalt der an ihm sichtbaren Architekturstile aus, die von der Gotik bis zum Klassizismus reichen. Die Anlage zählt zu den Schlössern der Loire.","h":"Die Ursprünge des Schlosses liegen in einer Befestigung namens Fort de la Motte. Die Anlage war ein Bauwerk aus Holz, das die Grafen von Anjou im 10. Jahrhundert am Ufer des Flusses Loir errichteten, um das Anjou gegen die Einfälle der Normannen zu verteidigen. Das heutige Schloss wurde auf den Fundamenten einer Festung aus dem 13. Jahrhundert errichtet. Deren sechs Türme flankierten eine eckige Einfriedung, die von einem tiefen Graben umgeben und der eine Befestigung vorgebaut war. Während des Hundertjährigen Krieges wurde die Burg mehrfach von den Engländern belagert und 1425 schließlich durch Richard de Beauchamp, den Earl of Warwick, eingenommen. Der „Blaubart“ Gilles de Rais konnte es 1427 zurückerobern und stieß danach zu den Truppen Jeanne d’Arcs, die vor Orleans lagen. 1457 erwarb Jean de Daillon, Kammerherr König Ludwigs XI., das arg mitgenommene Schloss. Er und sein Sohn Jacques widmeten sich bis 1530 der Errichtung einer dreiflügeligen Anlage um einen Innenhof, deren Südfassade den Stil der frühen Renaissance zeigt und von vier Rundtürmen flankiert wird. Hier finden sich die Fassadengestaltung des Flügels Franz’ I. im Schloss Blois und die Türme von Schloss Chambord wieder. Hohe Fenster und übereinander liegende Pfeiler bewirken eine vertikale Gliederung, und horizontale Giebelbänder betonen die einzelnen Stockwerke. Steinmedaillons schmücken die Fassade und geben ihr eine besondere Prägung. Eine Neuheit war die zwischen den Türmen am Schlossgraben angelegte Terrasse. Verantwortlicher Architekt für die ab 1520 vorgenommene Umgestaltung war Jean Gendrot, Baumeister Renés von Anjou. Auf den Sohn Jean, Graf von Le Lude, der sich vornehmlich um die Inneneinrichtung des Schlosses bemühte, folgte dessen Sohn François. Er stand in Diensten Heinrichs IV.","w":"https://de.wikipedia.org/wiki/Schloss_Le_Lude"},"ch-Q1010703":{"n":"Burg Aguilar","c":"Burg in Frankreich","r":"Die Burg Aguilar auf dem Gebiet der Gemeinde Tuchan im südfranzösischen Département Aude zählt gemeinhin zu den sogenannten Katharerburgen und war ehemals von großer strategischer Bedeutung. Seit dem Jahr 1949 ist die Burgruine als Monument historique anerkannt.","h":"Die ersten Hinweise auf eine Burganlage (castrum) an dieser Stelle finden sich bereits im Jahr 1021. Die Vizegrafen von Carcassonne übergaben den Platz im 13. Jahrhundert an ihre Vasallen – die Seigneurs de Termes. Diese standen der Katharerlehre nahe; ob die Burg jedoch im Rahmen des Albigenserkreuzzugs (1209–1229) zerstört wurde, ist unklar. Erstmals gelangte die Burg im Jahre 1241 an die französische Krone, doch wurde sie 10 Jahre später an ihren letzten Besitzer Olivier de Termes zurückgegeben, der sie jedoch im Jahr 1262 an den französischen König Ludwig IX. verkaufte; fortan gehörte die Burg – neben Termes, Quéribus, Puilaurens und Peyrepertuse – zu den 'Fünf Söhnen Carcassonnes'. Ihre Aufgabe war die Bewachung und Verteidigung der Grenze zum Königreich Aragón und später zu Spanien. Doch in den Jahren 1525 und 1542 eroberten die Truppen Karls V. jeweils nur vorübergehend die Burg. Der Pyrenäenfriede von 1659 verurteilte die Anlage wegen der veränderten Grenzlage zur Bedeutungslosigkeit und sie wurde verlassen.","w":"https://de.wikipedia.org/wiki/Burg_Aguilar"},"ch-Q1906882":{"n":"Palais du Pharo","c":"Palast in Frankreich","r":"Das Palais du Pharo ist ein Palast in Marseille, der ab 1858 von Napoleon III. für seine Frau Eugénie de Montijo erbaut wurde. Er überragt die Hafenpassage des Vieux Port und grenzt an den Jardin du Pharo.","h":"Louis-Napoleon Bonaparte hatte 1851 als französischer Staatspräsident bei einem seiner Besuche in Marseille den Wunsch geäußert, einen Wohnsitz in der Stadt zu bauen. Die Gemeinde zeigte sich schnell dazu bereit, als der Prinz-Präsident eine Million Franc Eigenkapital anbot. Der Betrag wurde verwendet, um das Land zu kaufen. Kurz bevor Louis-Napoleon Bonaparte 1851 als Napoleon III. Kaiser wurde, beauftragte er den Genfer Architekten Samuel Vaucher, einen geeigneten Ort für die kaiserliche Residenz zu suchen. Vaucher schlug ein Gelände gegenüber dem Fort Saint-Jean mit Blick auf den Hafen und die Bucht von Marseille vor und präsentierte im Februar 1853 seine Pläne. Sie wurden vom Architekten Hector Lefuel überarbeitet. Der Bau ähnelt dem der Villa Eugénie in Biarritz, deren Bau 1854 begann. Die Gemeinde benötigte knapp 1,2 Millionen Franc, um das Land zu erwerben. Mit dem Bau wurde am 15. August 1858, dem Geburtstag von Napoleon Bonaparte, begonnen. Der Baufortschritt wurde durch Mangel an Geld und Lieferschwierigkeiten von Stein wegen des gleichzeitigen Baus der Kathedrale von Marseille gebremst. Im August 1861 wurde Vaucher für die Verzögerung bei der Arbeit verantwortlich gemacht und durch Henri-Jacques Espérandieu ersetzt, der auch die Kathedrale von Marseille vollendete. Die Bildhauer François Gilbert, Vittoz und Simon wurden mit der Innen- und Fassadenverzierung betraut. Beim Sturz von Napoleon III. 1870 war der Palast nach zwölf Jahren Bauzeit nicht fertiggestellt; das Kaiserpaar hat dort nie gelebt.","w":"https://de.wikipedia.org/wiki/Palais_du_Pharo"},"ch-Q1787326":{"n":"Schloss Fougères-sur-Bièvre","c":"Schloss in Frankreich","r":"Das Schloss Fougères-sur-Bièvre steht im Zentrum des gleichnamigen französischen Orts Fougères-sur-Bièvre am Ufer des Bièvre im Département Loir-et-Cher. Es wurde am Ende des 15. Jahrhunderts als befestigter Landsitz der Familie de Refuge errichtet, die damit ihren sozialen Aufstieg innerhalb des französischen Adels dokumentierte. Die Anlage ist eines der letzten Beispiele für die niedergehende Militärarchitektur in Frankreich und einzigartig in der Region, denn während dort noch eine Wehranlage nach mittelalterlichem Vorbild errichtet wurde, verfolgten die Architekten benachbarter Adelssitze bereits das Konzept des bequemeren Wohnschlosses.","h":"Die Herrschaft Fougères-sur-Bièvre wurde erstmals 1030 urkundlich erwähnt und war zu jener Zeit im Besitz eines Seigneur Frangall, der Vasall des Grafen von Blois war. Während des Hundertjährigen Krieges wurde die dortige Burg 1358 durch den Schwarzen Prinzen, Edward of Woodstock, nahezu dem Erdboden gleichgemacht. Nur der Donjon und Reste des heutigen Rundturms waren noch vorhanden. Zu Beginn des 14. Jahrhunderts gelangten Burg und Herrschaft an die Familie de Faverois, von der sie die Erbtochter Jeanne de Faverois 1438 an ihren Ehemann, den herzoglichen Rat Jean de Refuge, brachte. Bis in das 17. Jahrhundert blieb die Anlage im Besitz der Familie und ihrer direkten Nachkommen. Die Eheleute ließen die Anlage in der Zeit von 1450 bis 1475 auf den Fundamenten der geschleiften Burg und unter Einbezug der noch vorhandenen Reste wieder aufbauen, indem sie den heutigen West- und Südflügel errichteten. Ihr Sohn Pierre de Refuge machte unter Karl VII. und Ludwig XI. als Schatzmeister Karriere am französischen Königshof. Bis spätestens 1483 hatte er die Erlaubnis des Königs erhalten, sein Schloss wieder zu befestigen, so dass er mit dem heutigen Nordflügel die Baulücke zwischen dem östlichen Rundturm und dem Donjon schloss. Die Arbeiten dazu dauerten bis 1497. Pierres Enkel Jean de Villebresme, Kammerherr des Herzogs Charles de Valois-Angoulême, brachte den von seinen Urgroßeltern begonnenen Um- und Wiederaufbau um 1520/25 zum Abschluss und fügte dem Wehrbau architektonische Elemente wie Lukarnen und Flachreliefs im Stil der Renaissance hinzu. Der Donjon erhielt erstmals ein Dach, und anstelle seiner Schießscharten wurden Fenster ausgebrochen.","w":"https://de.wikipedia.org/wiki/Schloss_Foug%C3%A8res-sur-Bi%C3%A8vre"},"ch-Q1815574":{"n":"Schloss Biron","c":"Schloss in Frankreich","r":"Das Schloss Biron liegt im Zentrum der Ortschaft Biron im Département Dordogne der alten Kulturlandschaft des französischen Périgord. Das auf einem Felssporn über der Lède errichtete Bauwerk wurde im Jahr 1928 in die Liste der Monuments historiques Frankreichs aufgenommen.","h":"Schloss Biron ist der Stammsitz der Familie Gontaut-Biron, die seit dem 12. Jahrhundert hier residierte und traditionell dem politisch verstandenen Protestantismus anhing. Im Jahr 1211 wurde das Schloss von den Katharern übernommen, jedoch im folgenden Jahr von Simon IV. de Montfort im Albigenserkreuzzug als nördlichste Zufluchtsburg der Katharer belagert und erobert. Während der Hugenottenkriege (1562–1598) unterstützte der Baron von Biron den Hugenottenführer Heinrich von Navarra, jedoch nur bis zu dessen Aufstieg zum königlichen Konvertiten. Ein Höhepunkt in der Familiengeschichte war das Jahr 1598, als der nunmehrige König Heinrich IV. seinem Vertrauten Charles de Gontaut und damit den Baronen von Biron die Herzogs- und Pairswürde verlieh. Der ehrgeizige Herzog schmiedete jedoch ein Komplott gegen den König und wurde im Jahr 1602 wegen Hochverrats geköpft.","w":"https://de.wikipedia.org/wiki/Schloss_Biron"},"ch-Q2417255":{"c":"Schloss in Frankreich"},"ch-Q2450180":{"n":"Schloss La Bastie d’Urfé","c":"Renaissanceschloss in Frankreich","r":"Das Schloss La Bastie d’Urfé, auch Schloss La Bâtie d’Urfé geschrieben, ist eine französische Schlossanlage in der Gemeinde Saint-Étienne-le-Molard im Département Loire. Die Anlage im Stil der Renaissance gehört zu den Loire-Schlössern und erhielt ihr heutiges Aussehen im 16. Jahrhundert durch Umbauten unter Claude d’Urfé, dem Großvater des Autors Honoré d’Urfé. Ihre Wurzeln liegen jedoch in einem festen Haus aus dem 14. Jahrhundert. Nach Aussterben der Eigentümerfamilie ging das Anwesen von Hand zu Hand, es diente ab 1872 zum Teil sogar als Fabrik. Ende des 19.","h":"Schon im 11. Jahrhundert stand am Ort des heutigen Schlosses am Ufer des Lignon du Forez eine Scheune, die der Priorei von Champdieu gehörte. Diese tauschte das Gebäude mit Jean de Marcilly gegen anderen Besitz. Von Jean kam das Gebäude über seinen Bruder Pierre an dessen Tochter Marguerite. Durch ihre Heirat mit Arnoul d’Ulphé kam der Besitz 1270 an dessen Familie, durch die er seinen heutigen Namen erhielt: La Bastie d’Urfé. Ihren Stammsitz hatte die Familie auf der rund 23 Kilometer entfernten Burg Urfé bei Champoly. Als Arnoul Eigentümer von La Bastie wurde, handelte es sich lediglich um ein einfaches Landhaus mit Lehmmauern, das 1331 erstmals urkundlich erwähnt wurde. Die Familie Urfé befestigte das Anwesen mit Wassergräben und einer Zugbrücke und baute es somit zu einem gotischen festen Haus aus. Zu Beginn des 15. Jahrhunderts gab sie ihre alte Stammburg auf und zog gänzlich nach La Bastie d’Urfé, nachdem Guichard d’Ulphé 1408 vom Herzog Louis II. de Bourbon zum Baillie des Forez ernannt worden war. Das Amt wurde in der Folgezeit von einer Generation zur nächsten weitervererbt. Guichards Nachkomme Pierre II. (1430–1508) machte Karriere am französischen Hof und wurde in den Michaelsorden aufgenommen sowie 1484 zum Großstallmeister von Frankreich ernannt. Er war das erste Mitglied seiner Familie, das die Schreibweise seines Namens in d’Urphé änderte. Pierre II. ließ sich 1483 dauerhaft in La Bastie d’Urfé nieder und baute das schlichte Manoir seiner Vorfahren vollständig um. Die anschließend zweiflügelige Anlage war allseitig von einer zinnenbewehrten Ringmauer umgeben, und ein wuchtiger Vierecksturm an der Nordwestecke beschützte die daneben liegende Zugangsbrücke. Der Burgherr war in zweiter Ehe mit Antoinette de Beauvau, Tochter von Pierre II.","w":"https://de.wikipedia.org/wiki/Schloss_La_Bastie_d%E2%80%99Urf%C3%A9"},"ch-Q2501434":{"n":"Schloss Eu","c":"Schloss in Frankreich","r":"Das Schloss Eu ist ein Schloss in der Stadt Eu im Département Seine-Maritime der französischen Region Normandie. Anstelle einer normannischen Burg entstand später die Residenz der Grafen von Eu.","h":"Im Jahr 1050 heiratete Wilhelm der Eroberer Mathilde von Flandern in der damaligen Burg von Eu. Diese schützte die nördliche Grenze der Normandie, bis König Ludwig XI. sie brandschatzen ließ, um ihre Auslieferung an die Engländer zu verhindern. Johann von Burgund, Graf von Eu, errichtete an ihrer Stelle ein Landschloss. Dies sollte im 16. Jahrhundert auf Wunsch Catherines de Clèves, geborene Gräfin von Eu, und ihres Ehemanns Henri I. de Lorraine, Herzog von Guise, durch ein größeres Schloss ersetzt werden, von dem allerdings nur ein Flügel errichtet wurde. Im Jahr 1656 vererbte Henriette Catherine de Joyeuse, verwitwete Herzogin von Guise, die Domäne ihrer Enkeltochter Anne Marie Louise, Herzogin von Montpensier, der rebellischen Grande Mademoiselle. Als diese sich weigerte, sich den Heiratsplänen zu fügen, die ihr Cousin Ludwig XIV. für sie schmiedete, exilierte der König sie 1663 nach Eu, wo sie die Niederschrift ihrer Memoiren fortsetzte. Um die Freilassung ihres Geliebten und späteren Ehemanns, des Herzogs von Lauzun, Antonin Nompar de Caumont, zu erwirken, verzichtete sie im Jahr 1681 auf Betreiben Madame de Maintenons zugunsten von Ludwigs XIV. Sohn Louis-Auguste de Bourbon, duc du Maine auf die Grafschaft Eu. Dieser vererbte sie an seinen kinderlosen Sohn Louis Auguste de Bourbon, der sie seinem Bruder Louis Charles de Bourbon hinterließ. Von diesem ging sie an Louis Jean Marie de Bourbon, duc de Penthièvre, der den Bau eines Kanals von Le Tréport bis nach Eu plante, daraufhin an dessen Tochter Louise Marie Adélaïde de Bourbon-Penthièvre, die 1769 Louis-Philippe II.","w":"https://de.wikipedia.org/wiki/Schloss_Eu"},"ch-Q780028":{"n":"Schloss Luynes","c":"Schloss in Frankreich","r":"Das Schloss Luynes liegt in Luynes in einem Seitental nördlich der Loire im Département Indre-et-Loire in der Region Centre-Val de Loire in Frankreich. Das Schloss war einst der Sitz der Baronie und späteren Grafschaft Maillé, weswegen die Anlage noch bis in das 17. Jahrhundert Schloss Maillé genannt wurde.","w":"https://de.wikipedia.org/wiki/Schloss_Luynes"},"ch-Q197482":{"c":"Schloss in Frankreich"},"ch-Q1011985":{"n":"Burg Gisors","c":"Burg in Frankreich","r":"Die Burg Gisors ist die Ruine einer Turmhügelburg in der französischen Stadt Gisors im Département Eure, Region Normandie und stammt aus dem 11. Jahrhundert. Ihr Wehrturm (Donjon) steht auf einer Motte, einem 1097 künstlich angelegten Erdhügel. Ab 1106 wird die Burg errichtet, 1113 ist sie fertiggestellt.","w":"https://de.wikipedia.org/wiki/Burg_Gisors"},"ch-Q1090706":{"n":"Château de Joux","c":"Burg nahe Pontarlier in Frankreich","r":"Das Château de Joux ist eine befestigte Burg nahe Pontarlier, Franche-Comté, Frankreich im französischen Jura.","h":"Die Burg wurde erstmals im Jahr 1034 urkundlich erwähnt. Von dort aus überfielen die Herren von Joux als gefürchtete Raubritter immer wieder reisende Kaufleute bzw. erpressten für den Verzicht auf deren Ausplünderung hohe Wegezölle. 1410 starb die Familie der Herren von Joux aus. 1454 kaufte Philipp der Gute die Festung. 1530 kam sie in den Besitz Karls V. Durch den am 17. September 1678 unterzeichneten Vertrag von Nimwegen wurden die Freigrafschaft Burgund und damit auch das Fort de Joux französisch. Nach seiner Verhaftung 1774 wurde Gabriel de Riqueti, comte de Mirabeau vom Gefängnis Château d’If vor der Küste von Marseille 1775 in das Château de Joux verlegt. Bei einer Vollzugslockerung konnte er in die Schweiz flüchten. Am 7. April 1803 starb der inhaftierte François-Dominique Toussaint L’Ouverture, haitianischer Nationalheld afrikanischer Herkunft sowie einer der ersten Anführer der lateinamerikanischen Unabhängigkeitsbewegung und der Befreiung schwarzer Sklaven, nach achtmonatiger Haft in seiner Zelle im Château de Joux an den Haftbedingungen. Während des Vierten Koalitionskriegs zwischen Preußen und Frankreich war Heinrich von Kleist 1807 als vermeintlicher preußischer Spion vier Wochen lang im Château de Joux inhaftiert. Kleists Kamerad Carl Franz von Gauvain kam in die Zelle, in der Toussaint L’Ouverture verstorben war. In den Kriegen von 1814 und 1871 musste sich die Burg gegen Überfälle zur Wehr setzen. 1940 endete die Geschichte der Burg als Militärfestung, nachdem der deutschen Wehrmacht acht Tage lang erfolgreich Widerstand geleistet wurde.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_de_Joux"},"ch-Q1190649":{"n":"Schloss von Monte Christo","c":"Schloss in Frankreich","r":"Das Schloss Monte Christo ist ein kleines Schloss, das sich der Schriftsteller Alexandre Dumas im zweiten Viertel des 19. Jahrhunderts in Le Port-Marly (Yvelines) erbauen ließ. Nach langwierigen Restaurierungen in den 1970er bis 1990er Jahren ist es seit Juni 1994 für Besucher geöffnet.","h":"Der große finanzielle Erfolg seiner Romane Die drei Musketiere und Der Graf von Monte Christo ermöglichte es Alexandre Dumas, beim Ort Le Port-Marly ab 1844 nach und nach ein insgesamt neun Hektar großes Waldgrundstück zu kaufen und darauf für sich ein kleines Schloss im Stil der Neorenaissance als ruhige Wohn- und Arbeitsstätte errichten zu lassen. Die Pläne dazu lieferte der französische Architekt Hippolyte Durand. Der Name des Neubaus orientierte sich an Dumasʼ neuestem Roman Der Graf von Monte Christo. 1845 war Baubeginn, und nur eineinhalb Jahre später war das Projekt 1846 bereits fertiggestellt. Am 25. Juli 1847 fand die feierliche Einweihung im Beisein von 600 Gästen statt. Dies war die erste große Veranstaltung in einer Reihe von Festen und Gesellschaften, die Dumas regelmäßig auf seinem Anwesen gab. Aufgrund seiner horrenden Schulden war er am 22. März 1849 jedoch dazu gezwungen, Schloss Monte Christo für nur 31.000 Francs an Jacques-Antoine Doyen zu verkaufen, obwohl ihn der Bau mehrere hunderttausend Francs gekostet hatte. Nur wenige Monate später musste Dumas auch das wertvolle Mobiliar des Schlosses verkaufen. Zwar durfte er dort wohnen bleiben, floh aber 1851 vor seinen immer noch hohen Schulden nach Belgien. 1857 gelangte das Anwesen an einen Herrn Fowler. 1894 erwarb es ein Herr Fontaine, ehe es 1939 eine Immobilienverwaltungsgesellschaft erwarb. Ab 1954 vermietete sie es an die British School of Paris. Verwahrlost und heruntergekommen sollte das Schloss Ende der 1960er Jahre abgerissen werden, um einem Wohnhausprojekt Platz machen. Der Historiker Alain Decaux veröffentlichte daraufhin 1970 einen Artikel in der Zeitung Le Figaro, der sich für den Erhalt des Schlosses einsetzte.","w":"https://de.wikipedia.org/wiki/Schloss_Monte_Christo"},"ch-Q837153":{"n":"Schloss Commercy","c":"Schloss in Frankreich","r":"Das Schloss Commercy ist ein Barockbau in der gleichnamigen Stadt im französischen Département Meuse. Das Schloss wurde von 1708 bis 1717 durch Charles Henri de Lorraine-Vaudémont anstelle einer mittelalterlichen Burg erbaut. Nach seinem Tod kam es in den Besitz der Herzöge von Lothringen. Seine Fassadengestaltung zeigt Ähnlichkeiten zum Schloss Lunéville.","h":"Die Burg Commercy wird 967 erstmals urkundlich erwähnt. Um 1100 wird mit Richwin von Commercy erstmals ein nach dem Ort benanntes Adelsgeschlecht genannt. Durch die Heirat Simons von Commercy mit Mathilde von Saarbrücken wurde die Herrschaft Commercy nach dem Tod des letzten Saarbrücker Grafen 1274 mit der Grafschaft Saarbrücken vereint. Unter Graf Johann II. erfolgte 1344 eine Erbteilung, wobei die jüngere Linie zu Commercy den Namen „Sarrebruck“ beibehielt. 1381 wurden die Grafen von Saarbrücken-Commercy von den Grafen von Nassau beerbt, die 1444 ihren Teil der Herrschaft Commercy an Louis de Bar verkauften. Die Linie Commercy starb 1551 mit Damoiselle Philippe von Commercy aus. In der Folgezeit gab es mehrfache Besitzerwechsel. Insbesondere zu erwähnen ist Paul de Gondi, Kardinal de Retz, der hier den größten Teil seiner berühmten Memoiren verfasste. Unter dem Grafen und späteren Fürsten Charles Henri de Lorraine-Vaudémont (1649–1723) wurden Schloss und Stadt in eine barocke Residenz umgebaut. Wahrscheinlich lieferte Germain Boffrand die Entwürfe für die Pläne des 1708 bis 1717 ausgeführten Schlossbaus. Nach dem Tod Charles Henris fiel Commercy an die Herzogin von Lothringen Elisabeth Charlotte, die bis zu ihrem Tode 1744 dort residierte. Der in Lothringen exilierte polnische König Stanislaus I. Leszczyński nutzte das Schloss anschließend als Nebenresidenz und ließ durch Emmanuel Héré die Gartenanlage anlegen sowie die Schlossflügel verlängern. Nach dem Tode Stanislaus’ 1766, mit dem das Herzogtum Lothringen an Frankreich fiel, wurden die Anlagen vernachlässigt. In der Zeit von 1767 bis 1927 diente das Schloss als Kavalleriekaserne. 1944 wurde es schwer beschädigt und erst in den 1960er Jahren wiederaufgebaut.","w":"https://de.wikipedia.org/wiki/Schloss_Commercy"},"ch-Q947645":{"n":"Burg Montrichard","c":"Burg in Frankreich","r":"Die Ruine der Burg Montrichard befindet sich in der französischen Gemeinde Montrichard Val de Cher im Département Loir-et-Cher. Sie steht seit dem Jahr 1877 als Monument historique unter Denkmalschutz.","w":"https://de.wikipedia.org/wiki/Burg_Montrichard"},"ch-Q976038":{"n":"Schloss Montgeoffroy","c":"Schloss in Frankreich","r":"Das Schloss Montgeoffroy befindet sich nahe der französischen Ortschaft Mazé im Département Maine-et-Loire. Das Bauwerk und die originale Inneneinrichtung haben die Französische Revolution und die nachfolgenden Wirren dank verwandtschaftlicher Protektion ohne Schäden überstanden. So gewinnt der Besucher einen authentischen Eindruck von der Lebensart des Adels auf einem Landschloss im ausgehenden 18. Jahrhundert.","h":"Louis-Georges-Erasme de Contades war der Feldmarschall und Statthalter des Elsass, ehe er im Alter von 68 Jahren aus dem aktiven Dienst ausschied. Im Jahr 1772 begann er, nach den Plänen des Pariser Architekten Jean Benoît Vincent Barré auf dem ursprünglich mittelalterlichen Landsitz bei Mazé, den seine Vorfahren 1676 erworben hatten, mit dem Bau seines Altersruhesitzes. Die Kapelle und zwei Rundtürme, welche die Wirtschaftsbauten begrenzen, wurden vom Vorgängerschloss des 16. Jahrhunderts übernommen. Die bis 1776 andauernden Bauarbeiten wurden von des Marschalls ältestem Sohn beaufsichtigt, der deren Fortgang fortlaufend protokollierte. So lässt sich heute noch nachvollziehen, wo das Baumaterial herstammte und wie der Transport vonstattenging. Ausführende waren vornehmlich Handwerker aus der Region, und die Bauern der Umgebung halfen beim Transport.","w":"https://de.wikipedia.org/wiki/Schloss_Montgeoffroy"},"ch-Q1010879":{"n":"Burg Arques","c":"Burg in Frankreich","r":"Die Burg Arques ist die Ruine einer mittelalterlichen Burg im heutigen Département Aude in der französischen Region Okzitanien. Die Burg steht zwar im Pays Cathare, gehört jedoch aufgrund ihrer späten Bauzeit nicht zu den Katharerburgen. Sie ist schon seit dem 16. August 1887 als Monument historique klassifiziert.","h":"Im 11. Jahrhundert gehörte Arques zum Besitz der Abtei Sainte-Marie de Lagrasse, wenig später stand der Ort im Besitz der Seigneurs de Termes, die ihrerseits wiederum Untertanen der Vizegrafen von Carcassonne waren. Urkundlich ist im Jahre 1154 ein befestigter Ort erwähnt, von einer Burg ist zu jener Zeit aber noch nicht die Rede. Im Jahr 1211 oder 1217 wandte sich Simon de Montfort nach der Eroberung der Burg Termes in Richtung Arques (Villa de Arquis) und setzte den Ort, der damals wahrscheinlich noch keine Burg hatte, sondern nur ein befestigtes Dorf (castrum) war, in Brand. 1231 befand sich ein Teil der Region Razès, darunter auch Arques, im Besitz eines seiner ehemaligen Kampfgefährten: Pierre de Voisins. Dessen Sohn Gilles de Voisins begann im Jahr 1284 mit dem Bau der heutigen Burganlage, die an einem Hirtenweg in Richtung der höhergelegenen Bergregionen der Corbières lag. 1316 wurden die Bauarbeiten beendet. Im Jahre 1518 heiratete Françoise de Voisins, die letzte Erbin des Familienbesitzes, Jean de Joyeuse und zog auf dessen Besitz nach Couiza. Die Burg Arques wurde aufgegeben und 1575 von den Hugenotten angegriffen und teilweise zerstört.","w":"https://de.wikipedia.org/wiki/Burg_Arques"},"ch-Q1517348":{"n":"Burg Châteauneuf-en-Auxois","c":"Burg in Frankreich","r":"Die Burg Châteauneuf-en-Auxois, kurz auch nur Burg Châteauneuf genannt, ist eine Spornburg im gleichnamigen Ort des französischen Départements Côte-d’Or. Die Anlage steht auf dem Plateau eines 475 Meter hohen Felsens rund einen Kilometer östlich des Canal de Bourgogne und überragt die Landschaft des Auxois. Sie gilt als eines der besten Beispiele für burgundische Militärarchitektur des Spätmittelalters und diente zur Sicherung der umliegende Ebene sowie der Straße von Dijon nach Autun.","h":"Auf Veranlassung Jean de Chaudenays, von dessen eigener, etwas südlicher gelegener Burg heute nur noch Ruinen existieren, wurde in der zweiten Hälfte des 12. Jahrhunderts ein Teil von seiner Seigneurie abgetrennt. Dieser Teil wurde Châteauneuf benannt und an seinen jüngeren Sohn Jean gegeben. Zuvor hatte der Vater für ihn aber noch eine erste, einfache Burg am heutigen Ort errichtet, die als castrum novum bezeichnet wurde. Dabei handelte es sich um einen fast quadratischen Wohnturm aus Stein, den sein Sohn um 1175 bezog. Er nannte sich fortan Jean de Châteaufneuf. Pierre I. de Châteauneuf erweiterte den bestehenden Bau in der ersten Hälfte des 14. Jahrhunderts um eine Ringmauer und einen Halsgraben zum Schutz gegen englische Truppen, die im Zuge des Hundertjährigen Kriegs durch Burgund zogen. Die kleine Anlage nahm damit etwa den nördlichen bis zum heutigen Tor reichenden Burgbereich ein. Sein Enkel Simon de Châteauneuf und dessen Sohn Poinçot vergrößerten den Burghof nach Südosten um einen etwa quadratischen Bereich und umgaben die gesamte Burganlage mit einer neuen Ringmauer. Um 1420 ließ Guy(ot) de Châteauneuf südlich an den Wohnturm ein kleines Logis im Stil der Spätgotik anbauen. Seine Tochter Catherine war die letzte ihrer Familie, welche die Burganlage bewohnte. Sie starb 1465 auf dem Scheiterhaufen, weil sie ihren zweiten Mann Jacques d’Aussonville vergiftet hatte. Herzog Philipp der Gute zog ihren Besitz ein und gab ihn im April 1457 seinem Kanzler und späteren Großseneschall von Burgund Philippe Pot, Herr der Burg La Rochepot. Dieser nahm diverse Umgestaltungen und Erweiterungen der Burganlage vor. Er verstärkte die Ringmauer mit Türmen, die alle von schlanken Treppentürmen erschlossen werden. Zwei davon bewachen das von ihm neu angelegte Portal im Nordosten.","w":"https://de.wikipedia.org/wiki/Burg_Ch%C3%A2teauneuf-en-Auxois"},"ch-Q1547865":{"n":"Schloss Dampierre","c":"Schloss in Frankreich","r":"Das Schloss Dampierre ist eine klassizistische Schlossanlage in der französischen Gemeinde Dampierre-en-Yvelines. Der Ort liegt etwa 15 Kilometer südwestlich von Versailles und 30 Kilometer südwestlich von Paris im Département Yvelines in der Region Île-de-France.","h":"Die Wurzeln der Anlage liegen einem bescheidenen Herrensitz, der bereits im 14. Jahrhundert urkundlich erwähnt und während des Jacquerie genannten Bauernaufstands 1358 Opfer eines Brands wurde. Während der Regierungszeit Ludwigs XI. von Jacques de Thumery wieder aufgebaut, wurde das Anwesen durch das Anlegen eines Teichs im Jahre 1480 verschönert. 1528 erwarb der königliche Sekretär (französisch: secrétaire du roi) Je(h)an Duval (auch du Val) die Seigneurie Dampierre. Er vergrößerte nicht nur den Landbesitz der Herrschaft durch entsprechende Zukäufe, sondern ließ auch die damals vorhandenen Gebäude des alten Herrensitzes 1535 modernisieren. Zu seiner Zeit bestand er aus mehreren, zweigeschossigen Gebäuden, die sich um einen Hof gruppierten und von einem Wassergraben umgeben waren. Zugang gewährte eine Zugbrücke die zu einem befestigten Torhaus führte. Ein kleiner Garten gehörte ebenfalls zum Ensemble. 1547 empfing Jean Duval den französischen König Franz I. auf seinem Schloss, das ab 1550 Pierre Séguier als Vorbild für den Bau seines Schlosses La Verrière diente. Charles de Lorraine-Guise, Erzbischof von Reims, kaufte das Schloss Duvals am 16. Februar 1551 und ließ die vorhandenen Gebäude umfassend verändern und ausbauen. Als Architekt dieses Werks kommen sowohl Claude Foucques, der im Jahr 1565 als Charles’ Architekt verbürgt ist, als auch Francesco Primaticcio infrage. Nach Abschluss der Arbeiten, bei denen unter anderem neue Wirtschaftsgebäude errichtet und ein Studiolo im Inneren 1554 mit Fresken von Francesco Salviati ausgestattet wurden, präsentierte sich Schloss Dampierre als eine von Wassergräben umgebene geschlossene Vierflügelanlage, deren Aussehen Jacques I.","w":"https://de.wikipedia.org/wiki/Schloss_Dampierre_(Yvelines)"},"ch-Q1650661":{"n":"Burg Combourg","c":"Burg in Frankreich","r":"Burg Combourg ist eine ehemalige Wasserburg aus dem 12. Jahrhundert. Sie befindet sich auf einem Hügel oberhalb der namensgebenden Stadt Combourg im Département Ille-et-Vilaine in der Bretagne (Frankreich), etwa auf halber Strecke zwischen Rennes (39 km) und Saint-Malo (36 km).","h":"Das Lehensgut Combourg wurde 1016 n. Chr. durch den Erzbischof von Dol gegründet. Es war ein Geschenk an seinen Bruder Rivallon, gebunden an eine Beistandsverpflichtung in Notfällen. Auf einem Felsen errichtet, der damals mitten in einem See stand, erhielt die nach streng militärischen Gesichtspunkten konzipierte Wehranlage ihre heutige Form schon im 12. Jahrhundert. Die damals noch unterhalb der Wasserlinie gelegenen Gebäudeanteile wurden aber erst nach der Beseitigung der äußeren Verteidigungsanlage im 15. Jahrhundert sichtbar. Der dadurch entstandene Höhenunterschied zum Eingang an der Nordseite wurde seinerzeit durch eine Außentreppe aus Granit ausgeglichen. Seitdem erscheint die trutzige Burg noch höher und mächtiger als zuvor. Sie ist heute von einem Park umgeben. Während vom Mittelalter bis in die Neuzeit die Besitzer mehrfach wechselten, befindet sich das düstere und legendenumwobene Bauwerk mit seinen labyrinthisch verwinkelten Wehrgängen, die Eindringlinge verwirren sollten, seit dem 18. Jahrhundert in der Hand einer Familie. Der aus Saint-Malo kommende Graf René August de Chateaubriand, Vater des berühmten französischen Dichters und Staatsmanns Francois-René de Chateaubriand, hatte die Burg 1761 erworben und zum Familiensitz bestimmt. Über den ältesten Sohn, der das Anwesen 1786 erbte, gelangte es an Louis Chateaubriand, den direkten Vorfahren der heutigen Schlossherrn.","w":"https://de.wikipedia.org/wiki/Burg_Combourg"},"ch-Q2969882":{"n":"Schloss Meung-sur-Loire","c":"Schloss in Frankreich","r":"Schloss Meung-sur-Loire ist ein Loireschloss in der Ortschaft Meung-sur-Loire im Département Loiret der Region Centre-Val de Loire in Frankreich, etwa 20 Kilometer westlich von Orléans.","w":"https://de.wikipedia.org/wiki/Schloss_Meung-sur-Loire"},"ch-Q2970121":{"n":"Schloss Nemours","c":"Schloss in Frankreich","r":"Das Schloss Nemours in Nemours, einer Gemeinde im Département Seine-et-Marne in der französischen Region Île-de-France, wurde ab dem 12. Jahrhundert errichtet. Im Jahr 1926 wurde das Schloss als Monument historique in die Liste der Baudenkmäler in Frankreich aufgenommen.","h":"Gaulthier I. von Nemours ließ im letzten Drittel des 12. Jahrhunderts das Schloss als Teil einer neuen Stadtanlage, zu der auch ein Kloster mit der Kirche St-Jean-Baptiste gehörte, errichten. Es liegt am linken Ufer des Flusses Loing und nahe der alten Brücke, sodass es zur Verteidigung der Stadt und Überwachung der Brücke dienen konnte. Das festungsartige Schloss wurde im 15. und 17. Jahrhundert umgebaut.","w":"https://de.wikipedia.org/wiki/Schloss_Nemours"},"ch-Q2968843":{"n":"Schloss Chamerolles","c":"Schloss in Frankreich","r":"Schloss Chamerolles ist eine französische Schlossanlage in Chilleurs-aux-Bois im Département Loiret, Region Centre-Val de Loire. Im 12. Jahrhundert als befestigte Hofanlage erstmals urkundlich erwähnt, wurde die Anlage Anfang des 16. Jahrhunderts von Lancelot du Lac I. zu einem Schloss im Renaissance-Stil ausgebaut.","w":"https://de.wikipedia.org/wiki/Schloss_Chamerolles"},"ch-Q3361047":{"n":"Palais de la Berbie","c":"Museum in Frankreich","r":"Der Palais de la Berbie ist ein ehemaliger Bischofspalast in Albi in Südfrankreich. Der komplex verschlungene Donjon stammt aus dem Hochmittelalter und wurde mehrmals umgebaut. An den Donjon angelehnt sind Gebäude aus dem 15. bis 17. Jahrhundert.","w":"https://de.wikipedia.org/wiki/Palais_de_la_Berbie"},"ch-Q3361199":{"c":"Palast in Frankreich"},"ch-Q2706740":{"c":"Burg in Frankreich"},"ch-Q1989567":{"n":"Schloss Gaillon","c":"Burg in Gaillon, Normandie, Frankreich","r":"Schloss Gaillon ist eine Residenz der Renaissance auf dem Gelände einer mittelalterlichen Burg in der Gemeinde Gaillon im französischen Département Eure in der Normandie. Die Anlage gilt als eines der frühesten Beispiele italienisch inspirierter Architektur in Frankreich und war im 16. Jahrhundert der prunkvolle Sitz der Erzbischöfe von Rouen und steht vollständig unter Schutz als historisches Denkmal Monument historique.","h":"Gaillon wird erstmals 1025 erwähnt, als Richard II. genannt der Gute Herzog der Normandie das Gebiet der Abtei Saint-Ouen in Rouen übertrug. Im Jahr 1192 gelangte Gaillon im Rahmen eines Abkommens zwischen Philipp II. August, König von Frankreich, und Johann Ohneland, König von England und Herzog der Normandie, unter französische Kontrolle. Damit fiel Gaillon – wie auch der normannische Vexin und weitere Befestigungen, darunter Évreux – in den Besitz der französischen Krone. Johann Ohneland handelte zu dieser Zeit als Stellvertreter seines gefangenen Bruders Richard Löwenherz. Nach Richards Freilassung und seiner Rückkehr in die Normandie im Jahr 1194 besiegte er den Kapetinger bei der Schlacht von Fréteval und gewann Teile des Vexin zurück. Zwei Jahre später musste er jedoch Gaillon und Vernon im Vertrag von Gaillon (1196) an Philipp II. abtreten. Der französische König übergab die Verteidigung der Festung dem Söldnerführer Lambert Cadoc, dem er das Lehen 1197 als Belohnung für seine militärischen Verdienste verlieh. Um seine Grenzstellung entlang der Seine zu sichern, ließ Richard Löwenherz daraufhin auf der gegenüberliegenden Uferseite, bei Les Andelys, das mächtige Château Gaillard errichten. Gaillon blieb endgültig im Besitz der Krone, als der Vertrag von Le Goulet im Jahr 1200 geschlossen wurde. Diese Eingliederung ging der Einnahme von Les Andelys, dem Fall von Rouen und dem Ende des normannischen Herzogtums Normandie und dessen vollständige Eroberung durch das Königreich Frankreich (1204) voraus. Lambert Cadoc blieb von 1197 bis 1220 Herr von Gaillon. Danach ließ Philipp II. die Burg mit Gewalt zurückerobern und Cadoc inhaftieren, nachdem sich zahlreiche Bewohner über seine Plünderungen in Pont-Audemer beschwert hatten, wo er als königlicher Bailli amtierte.","w":"https://de.wikipedia.org/wiki/Schloss_Gaillon"},"ch-Q2971472":{"c":"Burg in Frankreich"},"ch-Q2095479":{"n":"Schloss Clermont","c":"Schloss in Frankreich","r":"Das Schloss Clermont ist ein zwischen 1643 und 1649 erbautes Schloss in der Gemeinde Le Cellier im französischen Département Loire-Atlantique. Besitzer des Schlosses waren die Familie de Maupassant und später der Schauspieler Louis de Funès. De Funès war seit 1943 mit Jeanne-Augustine Barthélémy de Maupassant verheiratet, einer Großnichte von Léon Nau de Maupassant. Schloss Clermont ist seit dem 19. November 1941 als Monument historique in der französischen Denkmalliste eingetragen.","h":"Das Schloss wurde von der Familie Chenu de Clermont, einer Familie hochrangiger Militärbeamter, gebaut. René Chenu (1599–1672) war lange Zeit Gouverneur der Städte Oudon und Champtoceaux. Sein Sohn Hardy Chenu (1621–1683) war für die Befestigungen, Städte, Burgen und befestigten Städte der Bretagne verantwortlich. Die Chenus waren Vasallen des Hauses Condé, das viele Besitztümer im Westen Frankreichs hatte. René Chenu war ein Zeitgenosse und loyaler Verbündeter von Henri II. de Bourbon, prince de Condé. Das Schloss wurde kurz nach der Schlacht bei Rocroi gebaut, in der Henris Sohn Louis den Thron Ludwigs XIV. sicherte und sich damit eine beträchtliche Belohnung verdiente. Die Familie de Funès hatte einen Teil des Schlosses von einer Tante, einer Gräfin von Maupassant, geerbt und 1967 vollständig per Kerzenauktion ersteigert. Erst der große Erfolg des Films Drei Bruchpiloten in Paris erlaubte ihnen, das Anwesen zu renovieren. Bekannte Bewohner des Schlosses waren neben Louis de Funès unter anderem Émile Souvestre, Marie Dorval, William Turner und Jules Sandeau.","w":"https://de.wikipedia.org/wiki/Schloss_Clermont_(Le_Cellier)"},"ch-Q2476068":{"n":"Schloss Tanlay","c":"Schloss in Frankreich","r":"Das Schloss Tanlay ist ein Wasserschloss in der französischen Gemeinde Tanlay im burgundischen Département Yonne.","h":"Im 12. Jahrhundert besaß die Familie de Noyers das Schloss. Um 1197 kam es durch die Heirat Adelines de Noyers mit Guillaume I. de Courtenay, einem Enkel des französischen Königs Ludwig VI., als Hochzeitsgeschenk an dessen Geschlecht. Über mehrere Generationen wurde der Besitz immer an den ältesten Sohn vererbt, bis Robert III. de Courtenay zwischen 1342 und 1345 kinderlos verstarb. Da sein jüngerer Bruder Jean schon vor ihm und auch ohne Nachkommen verstorben war, folgte Roberts jüngster Bruder Philippe als Besitzer von Tanlay nach. Ihn beerbte 1385 seine Enkelin Jeanne I. Mit ihr endete die Ära der Familie de Courtenay als Besitzer von Tanlay, denn auch sie starb kinderlos, und so wurde Pierre de Chamigny, Cousin Jeannes I., neuer Grundherr von Tanlay. 1485 wechselte der Besitz nach dem kinderlosen Tod Aymé de Chamignys an dessen Schwester Philiberte. Sie brachte Tanlay an ihren Mann Philippe de Courcelles, mit dem sie seit etwa 1450 verheiratet war. Eine Generation später starb die Familie de Courcelles de Tanlay mit Philippes Kindern Edme und Catherine, die beide keine Nachkommen hatten, aus. In seinem Testament vom 13. Februar 1533 bedachte Edme verschiedene Verwandte mit seinem Besitz: Ein Drittel Tanlays ging an Claude des Essarts, den Großvater der Mätresse Heinrichs IV., der mit Claude de Chamigny verheiratet war. Das zweite Drittel erhielten die noch unmündigen Kinder der Louise de Montmorency, Witwe Gaspard I. de Colignys, eines Enkels von Edmes Onkel Pierre de Courcelles. Das letzte Drittel hinterließ Edme Catherine de Beaujeu-Montcoquier, der jüngeren Schwester seiner Mutter Philiberte. Diese ließ Tanlay im Handstreich besetzen, um die Herrschaft für ihren Sohn zu sichern.","w":"https://de.wikipedia.org/wiki/Schloss_Tanlay"},"ch-Q164901":{"n":"Burg Montgilbert","c":"Burg in Frankreich","r":"Die Burg Montgilbert ist die Ruine einer mittelalterlichen Höhenburganlage, die sich in der Gemeinde Ferrières-sur-Sichon befindet, ungefähr 25 Kilometer südöstlich von Vichy im französischen Département Allier.","h":"Die Burg wurde um 1259 zur Zeit von Ludwigs IX. von der Familie Saint-Gérand an der Grenze zwischen der Auvergne und den Regionen Forez und Bourbonnais erbaut. Um 1280 erwarb die Familie Aycelin die Anlage. Ihre Mitglieder waren reiche Bürger aus der Auvergne, die später geadelt wurden. Durch Heirat gelangte die Burg in den Besitz der Familie de Vienne. Während des Hundertjährigen Kriegs beschlagnahmte der spanische Söldner Rodrigue de Villandrando, der für den Herzog von Bourbon kämpfte, die Burg und hielt sie in der Zeit von 1434 bis 1439 besetzt. In diesen Jahren wurden die Befestigungen der Anlage der modernen Waffentechnik angepasst. Zur Zeit der Renaissance verlor die Burg ihre Bedeutung als Wohnsitz ihrer Eigentümerin, der Familie de Saulx-Tavannes. Nach den Religionskriegen gehört das Bourbonnais endgültig zum französischen Königreich. Während der Zeit Ludwigs XIV. wohnten die Besitzer am Hof in Paris. Einige Teile der Burg wurden verlassen, und ihr Verfall begann. Um 1770 kam der letzte Erbe, Jean Baptiste Bravard d’Eyssat Duprat, mit seiner Mutter nach Montgilbert zurück. Diese ließ, um den Sohn zum Verlassen der Burg zwingen, statisch wichtige Verbindungen im Gebälk entfernen. Während der Französischen Revolution verfielen die Bauten endgültig. Im Jahr 1793 gingen sie in Staatsbesitz über und wurden verkauft. Im 19. Jahrhundert verwandten die Bauern der Umgegend die Burg als Steinbruch, was den Verfall beschleunigte. 1973 gründete sich eine Vereinigung zur Erhaltung und Renovierung der Ruine.","w":"https://de.wikipedia.org/wiki/Burg_Montgilbert"},"ch-Q282646":{"n":"Ulrichsburg","c":"Burg in Frankreich","r":"Die Ruine der Ulrichsburg steht bei Ribeauvillé im Elsass. Sie thront in 510 Meter Höhe über dem Strengbachtal.","h":"Es existieren Baureste aus dem 11. Jahrhundert, der Bergfried wurde aber erst gegen Anfang des 12. Jahrhunderts gebaut. Der noch in Grundmauern erhaltene Wohnturm wurde um 1200 und der Rittersaal im Jahr 1230 fertiggestellt. Gänzlich fertig war die Burg im Jahr 1289. Die älteste erhaltene Erwähnung der Burg stammt von 1298. Die dem Heiligen Ulrich geweihte Kapelle wurde im Jahr 1435 vollendet. Im 15. Jahrhundert war die Burg in Kriegshandlungen mit den Besitzern der nahen Burgen Girsberg und Hohrappoltstein verwickelt. Ab dem Dreißigjährigen Krieg verfiel die Burg.","w":"https://de.wikipedia.org/wiki/Ulrichsburg"},"ch-Q741450":{"n":"Schloss La Bourdaisière","c":"Schloss in Frankreich","r":"Das Schloss la Bourdaisière ist ein Adelssitz aus dem 19. Jahrhundert in Montlouis-sur-Loire im Département Indre-et-Loire in der Region Centre-Val de Loire, das auf Vorgängerbauten aus der Renaissance und dem 14. Jahrhundert zurückgeht. Ein Teil des Schlosses und des Parks wurden 1947 als „Monument historique“ eingetragen.","h":"Das erste bekannte Bauwerk an dieser Stelle gehörte im 14. Jahrhundert dem Marschall Jean I. Le Maingre († 1367), dann seinen beiden Söhnen, Jean II. Le Maingre († 1421) und Geoffroy Le Maingre († um 1430). Zwei Generationen später befand sich die Burg im Besitz von Pierre de Champagne-Parcé, der sie 1482 an Louis de La Mezière, Bürgermeister von Tours 1477–1478 verkaufte. Dessen Tochter Charlotte heiratete Nicolas Gaudin, Bürgermeister von Tours 1504–1506, die La Bourdaisière 1494 an Nicolas‘ Bruder Victor weitergaben. Nicolas‘ Tochter Marie Gaudin, Erbin der Burg und Mätresse des Königs Franz I., heiratete 1510 Philibert Babou, beide entschieden 1520, die Burg zu einem Renaissance-Schloss umzubauen, wobei nur einer der mittelalterlichen Türme stehen blieb. La Bourdaisière blieb im Besitz der Nachkommen Marie Gaudins und Philibert Babous, bis es 1674 an Philippe de Courcillon verkauft wurde, der es 1683 an Angehörige der Familie Albert weiterveräußerte. Der 5. Herzog von Luynes und Chevreuse tauschte La Bourdaisiére 1768 mit Étienne-François de Choiseul gegen Cinq-Mars-la-Pile; Choiseul wiederum ordnete den teilweisen Abriss des Schlosses an, da er die Steine für den Bau der Pagode im Park des Schlosses Chanteloup bei Amboise benötigte. Die Ruine und die Grundstücke wurden 1786 Louis Jean Marie de Bourbon, duc de Penthièvre verkauft, dessen Tochter Louise Marie Adélaïde de Bourbon-Penthièvre wurde enteignet, der Besitz als Bien national veräußert. Im 19. Jahrhundert wurde das Schloss von neuen Besitzern im Stil der Neorenaissance wiederaufgebaut. 1938 erwarb ein Engländer die Domäne, die im Zweiten Weltkrieg von deutschem Militär, dann von französischem Militär besetzt wurde. 1947 erfolgte die Eintragung von Teilen der Anlage als Monument historique.","w":"https://de.wikipedia.org/wiki/Schloss_La_Bourdaisi%C3%A8re"},"ch-Q752990":{"n":"Schloss Balleroy","c":"Schloss in Frankreich","r":"Das Schloss Balleroy befindet sich im gleichnamigen französischen Ort Balleroy in der Region Normandie etwa 15 Kilometer südwestlich von Bayeux. Die klassizistische Anlage ist das früheste erhaltene Werk des Architekten François Mansart und eines der ersten Beispiele für ein Urbanismusprojekt in Frankreich. Es diente als Vorbild bei der Planung des Schlosses von Versailles. Seit Januar 1951 steht die Anlage unter Denkmalschutz.","h":"Jean I. de Choisy, der Sohn eines einfachen Weinhändlers, der sich bis zum königlichen Berater hochgearbeitet hatte und später Kanzler Gaston d’Orléans’ werden sollte, kaufte am 1. April 1600 die Domäne Balleroy für 5500 Écu vom Marquis d’O. Nachdem sich das Land schon einige Jahre im Besitz der Familie befunden hatte, beauftragten Jean II. und seine Frau Olympe de Bellesbat 1626 den jungen Architekten François Mansart mit Entwürfen für einen Schlossbau. Anders als bei vielen klassizistischen Schlössern Frankreichs besaß Balleroy aber keine älteren Vorgängerbauten, sondern wurde ab Juli 1631 vollkommen neu errichtet. Da das Gebäude nicht nur als zeitweilige Residenz, sondern als Hauptwohnsitz dienen sollte, plante Mansart gleichzeitig auch eine entsprechende Ansiedlung zur Versorgung der Schlossbewohner und bezog sie in das Architekturensemble mit ein. Balleroy war somit eines der ersten Urbanismusprojekte Frankreichs. 1637 waren die Bauarbeiten an der Schlossanlage beendet. Das Amt als Kanzler des Königsbruders brachte es aber mit sich, dass der Bauherr und seine Frau meist in Paris im Palais du Luxembourg wohnten. Nach dem Tod Jean II. de Choisys wurde seine Witwe vom Hof entfernt und nach Balleroy geschickt. Sie nahm die wertvolle Innenausstattung ihrer Pariser Appartements mit und ließ sie im Schloss Balleroy installieren. Nachdem Jean Paul de Choisy 1697 ohne männliche Nachkommen verstorben war, wurde Balleroy im Jahr 1700 an Françoise de Barancas, Princesse d’Harcourt, verkauft, doch die Fürstin blieb nicht lange Besitzerin. Am 17. Dezember 1701 erwarb der Kanzler Jacques de la Cour Schloss und die zugehörigen Ländereien, die 1704 zum Marquisat erhoben wurden.","w":"https://de.wikipedia.org/wiki/Schloss_Balleroy"},"ch-Q1011752":{"n":"Burg Fleckenstein","c":"Mittelalterliche Burgruine im Nordelsass","r":"Burg Fleckenstein ist eine mittelalterliche Felsenburg im Gebiet der in Frankreich so genannten Nordvogesen nahe der Grenze zu Rheinland-Pfalz. Sie gab als Stammburg dem Adelsgeschlecht der Fleckensteiner den Namen.","h":"Die geschichtlichen Daten zur Burg Fleckenstein sind recht dürftig. 1174 wurde ein Gottfried von Fleckenstein, der zu einer Familie von Reichsministerialen gehörte, erstmals erwähnt und damit indirekt auch die Burg. Ein Kapitell, das in den Burgtrümmern gefunden wurde, stammt jedoch bereits aus dem frühen 12. Jahrhundert, so dass feststeht, dass die Burg spätestens damals errichtet worden war, also mehr als 50 Jahre vor der ersten Erwähnung. Zur Zeit ihrer Erbauung lag die Burg an einer Straße, welche die staufischen Kaiserpfalzen Hagenau und Kaiserslautern verband; deshalb kam der Burg Fleckenstein strategische Bedeutung zu. 1276 belagerte König Rudolf von Habsburg den Heinrich von Fleckenstein, um den von diesem gefangengesetzten Friedrich von Bolanden, den Bischof von Speyer, zu befreien; allerdings ist nicht bekannt, ob die Belagerung direkt die Burg Fleckenstein oder eine andere Burg dieser im Mittelalter weitverzweigten und einflussreichen Familie betraf. Ähnlich bedeutend war das Ministerialengeschlecht von Dahn, das seine Hauptsitze 15 km nördlich hatte. Seine Burg Altdahn wurde 1363 erstmals zerstört im Verlaufe einer Fehde mit den Fleckensteinern. 1407 und 1441 sind Bauarbeiten am Fleckenstein bezeugt. Ein Anlass wird nicht genannt, doch vermutlich ging es darum, durch Ausbau komfortablere Wohnverhältnisse zu schaffen. Im Dreißigjährigen Krieg und kurz danach machten drei Brüder aus dem Rittergeschlecht der Fleckensteiner von sich reden: Gottfried von Fleckenstein-Windeck fiel 1639 bei der Belagerung der Stadt Vesoul, die im Grenzbereich Burgund/Lothringen liegt. Sein Bruder Georg Heinrich wurde General bei den bayerischen Truppen. Der jüngste Bruder, Friedrich Wolfgang, trat in französische Dienste und wurde später von Ludwig XIV. zum Feldmarschall ernannt.","w":"https://de.wikipedia.org/wiki/Burg_Fleckenstein"},"ch-Q637019":{"n":"Burg Anjony","c":"Burg in Frankreich","r":"Die Burg Anjony, französisch: Château d’Anjony, ist eine gut erhaltene Höhenburg 15 Kilometer nördlich von Aurillac auf dem Gebiet der auvergnatischen Gemeinde Tournemire im französischen Département Cantal. Sie steht östlich der Départementstraße 922 im Tal der Doire und kann besichtigt werden.","h":"Die Burg ließ Louis d’Anjony im Auftrag des Königs Karl VII. zur Repräsentation der königlichen Macht und zum Schutz der Umgebung 1437–1440 erbauen. Er hatte den König nach dem Hundertjährigen Krieg gegen England feierlich nach Paris geleitet. Das Baumaterial war roter Basalt. Die Anlage erlebte bis in das 16. Jahrhundert hinein eine unruhige Periode, geprägt von einer Fehde der Familien von Anjony und Tournemire, die Rivalen in unmittelbarer Nachbarschaft waren. Rigaud de Tournemire ärgerte sich, weil die neue Burg höher als die seine war. Der Streit hierüber dauerte fast 200 Jahre. 1465 kam es zu einem ersten Höhepunkt des Streites zwischen den Familien Anjony und Tournemire, als Angestellte der Madame de’Anjony belästigt und das Kirchengestühl der Familie beschädigt wurde. Dann beleidigte ein unehelicher Sohn des Fürsten Tournemire den Haushofmeister von Louis d’Anjony. Infolgedessen kam es zu einem Duell, bei dem der Haushofmeister seinen Gegner tötete und kurz darauf von Angehörigen der Tournemire-Familie ermordet wurde. 1523 wurde einer der Söhne von Louis d'Anjony von Jean de Tournemire umgebracht. Da der Ermordete ein Geistlicher war, wurde er in der Kirche beigesetzt, jedoch zwei Monate später von Tournemire-Leuten wieder ausgegraben und vor das Burgtor geworfen, wo er von streunenden Hunden gefressen wurde. Danach dauerten die Kämpfe zwischen den Familien 100 Jahre lang an. 1590 verständigte man sich auf einen Vertrag über „gleich große Ehre“ beider Familien. Indes ging der alltägliche Streit weiter. Am 21. Juni 1623 sollte ein öffentlicher Wettstreit die Entscheidung bringen. Diesmal gewann die Familie Tournemire und war zur Beilegung des Dauerstreits bereit. 20 Jahre später führte die Liebe zwischen Michel II.","w":"https://de.wikipedia.org/wiki/Burg_Anjony"},"ch-Q643186":{"n":"Palais du Rhin","c":"Schloss in Straßburg, Frankreich","r":"Der Palais du Rhin, ehemals Kaiserpalast, an der Place de la République (Kaiserplatz) in Straßburg, wurde 1884 bis 1889 errichtet und ist eines der auffälligsten Bauwerke der Stadt. Die gesamte Anlage stellt eines der vollständigsten Zeugnisse deutscher Monumentalarchitektur des späten 19. Jahrhunderts dar.","h":"Der Kaiserpalast wurde als Palast für den Kaiser des Deutschen Reichs und als Zeugnis der Angliederung des Landes Elsaß-Lothringen angelegt und aus Anlass des 87. Geburtstags Wilhelms I. am 22. März 1884 nach Plänen des Architekten Hermann Eggert (1844–1920) mit Unterstützung durch den späteren Bremer Dombaumeister Ernst Ehrhardt (1855–1944) begonnen. Der aufgrund seiner exorbitanten Kosten (3 Millionen Goldmark) und seines pompösen Neorenaissancestils (vage dem Palazzo Pitti nachempfunden) heftig kritisierte Bau wurde 1889 fertiggestellt und im selben Jahr von Wilhelm II. eingeweiht. Dieser hielt sich in der Folge bis 1914 mindestens einmal jährlich in dem Gebäude auf, ohne jedoch dessen Architektur sonderlich zu schätzen (es erhielt den Beinamen „Elefantenstall“, da es ihn an das Elefantenhaus des Zoos im Berliner Tiergarten erinnert haben soll). Während des Ersten Weltkriegs wurde das Gebäude als Lazarett verwendet. 1920 wurde es zum Sitz der Zentralkommission für die Rheinschifffahrt (ZKR) und erhielt seinen neuen Namen. 1940 wurde der Palast zum Sitz der Kommandantur der nationalsozialistischen Lokalregierung, dann ab November 1944 zum Hauptquartier des französischen Generalmajors Philippe Leclerc de Hauteclocque. Im Zuge der Bombardierung der Stadt durch die Royal und US Air Force im August 1944 wurde der Palast schwer beschädigt. Heutzutage beherbergt das äußerlich und innerlich aufwendig restaurierte Gebäude neben der ZKR auch die elsässische Direction régionale des Affaires culturelles (DRAC). 2008 diente der Palast als Kulisse für die Dreharbeiten des französischen Fernseh-Mehrteilers La Résistance. Zu diesem Zweck wurde darin das Pariser Gestapo-Hauptquartier nachgestellt.","w":"https://de.wikipedia.org/wiki/Palais_du_Rhin"},"ch-Q1333383":{"n":"Schloss Montaigne","c":"Schloss in Frankreich","r":"Das Schloss Montaigne liegt in der Gemeinde Saint-Michel-de-Montaigne, im Département Dordogne, Region Nouvelle-Aquitaine im Südwesten von Frankreich. An dem Ort zwischen Libourne und Bergerac ist seit dem 14. Jahrhundert eine Burg nachgewiesen, die mehrfach umgebaut und erweitert wurde. Das heute dort stehende Gebäude wurde nach einem Brand im Jahr 1885 vollständig neu in einer Stilmischung zwischen mittelalterlich und Neo-Renaissance erbaut. Im 15. und 16. Jahrhundert war es Wohnsitz der Familie des französischen Philosophen Michel de Montaigne, des Begründers der Essayistik.","h":"Das Anwesen erwarb im Jahr 1477 der Urgroßvater von Michel de Montaigne, Ramon Eyquem, der durch seine Tätigkeit als Fisch- und Weinhändler in Bordeaux zu Wohlstand gekommen war. Als „Seigneur de Montaigne“ (deutsch: Herr von Montaigne) ließ er sich mit seiner Familie hier nieder und vererbte das großzügige Anwesen an seine Kinder und Enkel. Im Jahr 1860 wurde es von Pierre Magne, einem Minister unter Napoleon III., als Altersruhesitz bezogen. Nach dem Brand von 1885 veranlasste seine Tochter Marie Thirion Mautauban die Wiedererrichtung des Schlosses. Heute befindet sich das Anwesen immer noch im Privatbesitz der Familie Mähler-Besse (6. und 7. Generation nach Pierre Magne).","w":"https://de.wikipedia.org/wiki/Schloss_Montaigne"},"ch-Q1476690":{"n":"Hôtel Saint-Paul","c":"ehemaliges Hotel von Karl.V. König von Frankreich in Paris","r":"Das Hôtel Saint-Paul oder Hôtel Saint-Pol in Paris wurde von 1361 bis 1364 von Herzog Karl von Normandie, ab 1364 als Karl V. König von Frankreich, als seine bevorzugte Residenz gebaut.","w":"https://de.wikipedia.org/wiki/H%C3%B4tel_Saint-Paul"},"ch-Q1548218":{"n":"Schloss Montrésor","c":"Schloss in Frankreich","r":"Das Schloss Montrésor befindet sich in der Gemeinde Montrésor im Département Indre-et-Loire der Region Centre-Val de Loire in Frankreich. Seit dem 13. Februar 1996 steht es als Monument historique unter Denkmalschutz.","w":"https://de.wikipedia.org/wiki/Schloss_Montr%C3%A9sor"},"ch-Q1552130":{"n":"Schloss Bussy-Rabutin","c":"Schloss in Frankreich","r":"Schloss Bussy-Rabutin ist eine Renaissanceanlage beim Dorf Bussy-le-Grand im französischen Département Côte-d’Or. Das Schloss besteht aus dem Hauptgebäude, einem Gesindehaus, einem Taubenhaus und einer Kapelle aus dem 17. Jahrhundert. Der von einem großen Park umgebene Bau steht seit 1862 als Monument historique unter Denkmalschutz. Sein bekanntester Besitzer war Roger de Bussy-Rabutin aus der gleichnamigen Adelsfamilie.","w":"https://de.wikipedia.org/wiki/Schloss_Bussy-Rabutin"},"ch-Q2971586":{"n":"Schloss Chambéry","c":"Burg im Département Savoie, Frankreich","r":"Das Schloss Chambéry ist eine alte Festungsanlage und ein Schloss der Herzöge von Savoyen aus dem 11. Jahrhundert. Es befindet sich in der Gemeinde Chambéry im Département Savoie in der Region Auvergne-Rhône-Alpes (Frankreich).","h":"Die Burg wurde im 11. Jahrhundert von den Herren von Chambéry erbaut. Graf Amadeus V. machte Chambéry 1295 zur Hauptstadt der Grafschaft Savoyen, welchen Status sie bis 1563 behielt. Das Schloss wurde seit dem 13. Jahrhundert mehrmals verändert, hat aber seither seine administrative Funktion immer beibehalten. In der Schlosskapelle Sainte-Chapelle wurde von 1502 bis 1578 das Heilige Grabtuch aufbewahrt. Beim Brand der Sainte-Chapelle am 4. Dezember 1532 wurde das Grabtuch beschädigt und trägt seitdem die heute sichtbaren Brandlöcher. 1578 ließ Herzog Emanuel Philibert von Savoyen die Reliquie von Chambéry in seine neue Residenzstadt Turin in den Turiner Dom überführen. In seinem Glockenturm wurde von der Gießerei Paccard in Sévrier ein großes Glockenspiel, das Glockenspiel „Saint-François de Sales“, installiert, das aus 70 Glocken besteht. Jeden ersten und dritten Samstag im Monat findet um 17.30 Uhr ein Konzert statt. Zwischen 1536 und 1713 wurden Chambéry und dessen Schloss mehrfach von den Franzosen besetzt. Der Friede von Utrecht sprach es wieder Savoyen zu. 1730 ließ sich der König Viktor Amadeus II. von Sardinien, nachdem er die Regierung niedergelegt hatte, hier nieder. 1742 wurde Chambéry von einer französisch-spanischen Armee erobert. Von 1792 bis 1814 stand die Stadt erneut unter französischer Herrschaft und war Hauptort des Départements Mont-Blanc. Hatte der Erste Pariser Frieden vom 30. Mai 1814 Chambéry bei Frankreich gelassen; so kam es im Zweiten Pariser Frieden vom 20. November 1815 an Sardinien zurück. 1860 wurde es mit Savoyen endgültig an Frankreich abgetreten. Das Schloss beherbergt heute die Dienststellen der Präfektur Savoie, des Departementsrats Savoie und der Academie Savoie.","w":"https://de.wikipedia.org/wiki/Schloss_Chamb%C3%A9ry"},"ch-Q2968078":{"n":"Burg Ancenis","c":"Burg im Département Loire-Atlantique, Frankreich","r":"Die Burg Ancenis ist eine Festung in Ancenis im Département Loire-Atlantique in Frankreich. Sie liegt am Ufer der Loire.","h":"Die ursprüngliche Burg wurde von Aremburge, der Ehefrau Guérechs, des Herzogs der Bretagne errichtet, während dieser sich zur Huldigung bei König Lothar von Frankreich († 986) aufhielt. Dabei handelte es sich um eine Turmhügelburg, die über einfache Verteidigungsanlagen wie einen Wassergraben und eine Palisade mit einer Einfriedung zum Schutz der Bevölkerung verfügte. Aufgrund ihrer Lage entwickelte sich die Burg schnell zu einem idealen Ort für die Überwachung des Flusses und übte eine militärische und wirtschaftliche Kontrolle aus. Im Jahr 1411 wurden die Herren Ancenis angewiesen, die Boote, die die Burg passierten, nicht mehr festzuhalten und keine Strafzölle mehr auf ihre Ladung zu erheben. Aufgrund ihrer strategischen Lage wurde sie zwischen dem 12. und 16. Jahrhundert mehrfach belagert, und zwar von den englischen Königen Heinrich II. und Johann Ohneland, den französischen Königen Ludwig IX., Ludwig XI. und Franz II., vom bretonischen Herzog Karl, und auf Befehl von König Karl VIII. von Louis II. de la Trémoille. Karl VIII. befahl den Abriss der Burg und schrieb im Jahr 1488 an de la Trémoille und seine Leutnants und verbot ihnen, ihren Arbeitern Urlaub zu gewähren, bis der Abriss abgeschlossen wäre. Bei Ausgrabungen in den 1950er Jahren wurden Kanonenkugeln entdeckt, die von den Belagerungen der Burg zeugen. Ab dem 17. Jahrhundert verlor die Burg an militärischer Bedeutung. Im Jahr 1626 wurde sie auf Befehl von Kardinal Richelieu geschleift. Teile der Ringmauern und Türme wurden verunstaltet oder entfernt. Die Gräben wurden mit dem Bau von Kaianlagen 1840 zugeschüttet und die Einrichtung eines Ursulinen-Internats 1850 setzte die Beschädigungen fort.","w":"https://de.wikipedia.org/wiki/Burg_Ancenis"},"ch-Q2969961":{"n":"Burg Montaner","c":"Burg in Frankreich","r":"Die Burg Montaner ist eine mittelalterliche Burgruine in der französischen Gemeinde Montaner im Département Pyrénées-Atlantiques in der Region Nouvelle-Aquitaine.","h":"Gaston Fébus (1331–1391), Graf von Foix und Vicomte von Béarn, wollte einerseits eine bewaffnete Neutralität gegenüber den im Hundertjährigen Krieg involvierten Parteien, dem Königreich England und der französischen Krone, demonstrieren. Andererseits hatte er Pläne eines zusammenhängenden Territoriums zwischen seinen beiden Hauptstädten Orthez und Foix, die sein Rivale, der Graf von Armagnac verhindern wollte. Von der Burg Montaner war Gaston Fébus jederzeit in der Lage, in das seit dem Frieden von Brétigny im englischen Besitz befindliche Bigorre einzufallen, andererseits aufgrund der geografischen Lage das Tal des Flusses Adour zu bewachen und einen allfälligen Einfallsweg vor gegnerischen Truppen abzuriegeln. Der 3. August 1374 markierte den Beginn der Arbeiten an der neuen Burg bei Montaner. Die alte Burg wurde abgerissen und neu errichtet, der Bergfried aufgestockt. Am 25. Dezember 1375 waren die Arbeiten im vollen Gange. Spezialisten aus Foix, Pierre Terrée und Blaise Audoin, Sicard de Lordat, der für die militärischen Anlage zuständig war und der Zimmermannmeister Pierre Doat, hatten Öfen zur Herstellung von 100.000 Ziegelsteinen pro Jahr als Baumaterial eingerichtet. Im Dezember 1379 betrachtete Gaston Fébus seine neue Festung als einsatzbereit, obwohl die Arbeiten noch bis in das folgende Jahr weitergingen. Zu einem militärischen Schauplatz sollte sie allerdings nicht werden. Zwischen 1379 und 1380 wurde das Bigorre bereits Teil des Territoriums Béarn-Foix, nachdem sich die englischen Truppen zurückgezogen hatten. 1425 wurde das Bigorre offiziell Teil der Grafschaft Foix. Die Rivalität zwischen Béarn-Foix und Armagnac wurde durch eine Heirat beigelegt. Am Ende des 15. Jahrhunderts ging Foix-Béarn-Bigorre im Königreich Navarra auf.","w":"https://de.wikipedia.org/wiki/Burg_Montaner"},"ch-Q2721241":{"n":"Solidorturm","c":"Burg in Saint-Malo, Département Ille-et-Vilaine, Bretagne, Frankreich","r":"Der Tour Solidor ist ein mittelalterlicher Wehrturm an der Mündung der Rance in Saint-Malo im Département Ille-et-Vilaine in der Bretagne. Das Bauwerk ist bereits seit dem Jahr 1886 als Monument historique eingestuft.","h":"Der Tour Solidor besteht aus drei Etagen und verfügt über drei 18 Meter hohe Rundtürme an seinen Flanken und im Inneren über eine Treppe mit 104 Stufen. Er wurde im Jahr 1382 durch Herzog Johann V. zu einer Zeit an der Mündung der Rance beim heutigen Stadtteil Saint-Servan errichtet, als die Stadt Saint-Malo seine Autorität nicht anerkannte. Der Turm sollte den Zugang zur Stadt Saint-Malo kontrollieren, die Flussmündung überwachen und den Handel zwischen Saint-Malo und Dinan blockieren. Während der Französischen Revolution wurde das Bauwerk als Gefängnis und dann im 19. Jahrhundert während der Kaiserzeit als Lagerhaus genutzt. Am Fuß des Turms befindet sich ein Kreuz, das 1985 errichtet wurde, um an Jacques Cartier zu erinnern, der 1534 von hier nach Kanada ablegte. Der Turm beherbergte zuletzt das Museum Musée international du Long-Cours Cap-Hornier, das (Stand 2025) geschlossen ist.","w":"https://de.wikipedia.org/wiki/Tour_Solidor"},"ch-Q2724447":{"c":"Burg in Frankreich"},"ch-Q2971835":{"n":"Château du Taureau","c":"Festung in Frankreich","r":"Das Château du Taureau ist eine alte Festungsanlage auf einer Insel in der Bucht von Morlaix in der Bretagne. Ursprünglich diente sie der Verteidigung der Bucht und der angrenzenden Städte, später als Gefängnis. Heute ist sie ein insbesondere von Touristen besuchtes Denkmal.","h":"Die anliegenden Städte, insbesondere Morlaix, waren um 1500 reiche Handelsstädte, die ihren Wohlstand insbesondere auf den Textilhandel gründeten. Vielfach sahen sie sich deshalb Angriffen und Raubzügen ausgesetzt. Einer der schwerwiegendsten Angriffe ereignete sich 1522, als 60 englische Schiffe über die Bucht von Morlaix anlandeten und große Teile der Stadt plünderten und zerstörten. In der Folge wurden zwei Wachposten in der Nähe von Carantec und Plouezoc’h erbaut, von denen aus die Bucht von Morlaix überwacht werden sollte. Die Einwohner von Morlaix hielten dies jedoch nicht für ausreichend und errichteten auf eigene Kosten auf dem Rocher du Taureau (Stierfelsen; wohl aufgrund seiner Form) 1542 ein erstes Fort. Unter Ludwig XIV. wurden etliche Verteidigungsanlagen ausgebaut, so Ende des 17. Jahrhunderts auch das Château du Taureau. Sébastien Le Prestre de Vauban, Festungsbaumeister Ludwigs XIV., plante 1689 das neue Fort, bei dem von der ursprünglichen Konstruktion nur der Französische Turm (Tour Française) erhalten blieb. Die Verteidigung konzentrierte sich auf den westlich des Forts gelegenen Teil der Bucht, weil sich nur dieser Teil zur Durchfahrt mit großen Schiffen eignete. Im Erdgeschoss waren in den westlichen Kasematten Kanonen stationiert. Auf dem Dach stationierte Kanonen konnten weitere Distanzen überbrücken. Vaubans Planungen aus dem Jahr 1689 wurden weitgehend umgesetzt und das neue Fort 1745 fertig gestellt. In dieser Form steht die Burg bis heute. Angegriffen wurde das Château du Taureau nie. Ab 1721 wurde die Burg auch als Gefängnis genutzt. Bis zu elf Gefangene konnten in den jeweils 14 m² großen Zellen untergebracht werden. Hierbei handelte es sich zunächst um Adlige, die von ihren Familien verstoßen worden waren.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_du_Taureau"},"ch-Q2675627":{"c":"Burg in Frankreich"},"ch-Q161787":{"n":"Schloss Champs-sur-Marne","c":"Schloss nahe Paris","r":"Das Schloss Champs-sur-Marne ist ein im 18. Jahrhundert errichteter Adelssitz im Herzen der gleichnamigen Stadt im Département Seine-et-Marne, 30 Kilometer östlich von Paris. Seine berühmteste Bewohnerin war 1757/59 Madame de Pompadour. Das Schloss war von 1935 bis 1974 Staatsgästehaus der Republik Frankreich.","h":"Der Bau des Schlosses, begonnen 1701 – gegen Ende der Herrschaftszeit Ludwigs XIV. – durch den Architekten Pierre Bullet im Auftrag des Hof-Waffenlieferanten Charles Renouard de la Touanne, wurde 1703 kurzfristig unterbrochen, nachdem der Bauherr bankrottgegangen war. Der Sohn des Architekten, Jean-Baptiste Bullet de Chamblain (1665–1726), konnte die Bauarbeiten fortsetzen, als der Großgrundbesitzer Paul Poisson de Bourvallais, dessen Pariser Stadtpalais der heutige Sitz des französischen Justizministeriums ist, das Anwesen samt der Rohbauruine kaufte. Das Jahr 1706 ist das Fertigstellungsjahr des Schlosses. Madame de Pompadour wohnte dort von Juli 1757 bis Januar 1759 für 12.000 Livre jährlich zur Miete und gab in diesem Zeitraum viel Geld für die Innenausstattung aus, hauptsächlich für Gemälde und Fresken des berühmten Tiermalers Christophe Huet. Der Pariser Bankier Baron Louis Cahen d'Anvers erwarb das Anwesen 1895 und ließ eine erste Gesamtsanierung durchführen. Seine Tochter Irène Cahen d'Anvers war von 1892 bis zu ihrer Scheidung im Jahre 1901 mit dem berühmten Kunstsammler Baron Moïse de Camondo verheiratet, dessen Pariser Stadtpalais in der Rue de Monceau 63 heute das Museum Nissim de Camondo für dekorative Kunst ist. Die Sammlung ist dem Andenken an den einzigen Sohn des Paares, Nissim de Camondo, gewidmet, der als Pilot im Ersten Weltkrieg starb. 1935 vermachte der Sohn Louis’, Charles Cahen d'Anvers, das Schloss dem französischen Staat, der es bis 1974 als Gästehaus für Staatsgäste nutzte. Die fehlenden Mittel zum Unterhalt des Schlosses führten dazu, dass sich dessen Zustand seitdem immer weiter verschlimmerte. Seit einem größeren Bauschaden, der am 20.","w":"https://de.wikipedia.org/wiki/Schloss_Champs-sur-Marne"},"ch-Q1012393":{"n":"Burg Hohbarr","c":"Burg in Frankreich","r":"Die Burg Hohbarr ist die Ruine einer Felsenburg nahe Saverne im Elsass.","h":"Im Jahr 1123 wurde die Burg als Besitz der Straßburger Bischöfe erwähnt. Bis ins 14. Jahrhundert wurde sie mehrmals erweitert. 1394 wurde Hohbarr an Egenolf von Lützelburg und Genossen verpfändet, diente jedoch bis ins 17. Jahrhundert den Bischöfen als Residenz. 1583 wurde im Auftrag von Bischof Johann IV. von Manderscheid-Blankenheim eine vollständige Erneuerung und Verstärkung der Burg vorgenommen. Im Dreißigjährigen Krieg wurde die Felsenburg geschleift. Nachdem zu Beginn des 18. Jahrhunderts trotz Planung keine größeren Ausbesserungen an der Burg vorgenommen wurden, besetzten Panduren sie 1744. Mehr als ein halbes Jahrhundert später gelangte sie in Besitz von Adligen. Seit 1878 ist sie jedoch Staatseigentum.","w":"https://de.wikipedia.org/wiki/Burg_Hohbarr"},"ch-Q1012883":{"n":"Burg Laval","c":"Schloss in Frankreich","r":"Die Burg Laval liegt in der Stadt Laval im Département Mayenne in der Region Pays de la Loire in Frankreich.","h":"Die erste Seigneurie von Laval findet sich in den Geschichtsbüchern am Anfang des 11. Jahrhunderts. Die Burg Laval wurde von Gui I. de Dénéré (oder de Laval), Vasall des Grafen von Maine, Herbert I. Eveille Chien, am Ufer der Mayenne errichtet, wo der Fluss die Straße von Le Mans nach Rennes kreuzt, etwa auf halbem Weg zwischen beiden Städten. Die letzte direkte Nachkommin, Emma de Laval, heiratete im 13. Jahrhundert Mathieu de Montmorency, sodass die Herrschaft Laval in den Besitz dieser Familie überging. Als 1412 die männliche Linie der Laval-Montmorency mit dem Tod von Gui XII. erlosch, fiel der Besitz an seinen Schwiegersohn, Jean de Montfort-Gaël. Dieser nahm mit Rücksicht auf die lokale Tradition den Namen Gui XIII. an. Sein Sohn, ein Gefährte von Jeanne d’Arc, Gui XIV., folgte ihm 1415 nach. 1429 erhob König Karl VII. die Seigneurie zur Grafschaft Laval. Nach dem Tod des Guy XVII. de Laval, Comte de Laval et de Montfort, 1547 fielen die Grafschaften an die Tochter seiner Schwester, Renée de Rieux, die sich nunmehr Guyonne, Gräfin de Laval, nannte. Ein Jahr später beerbte sie auch ihren Bruder, Claude II. de Rieux und verfügte nun über große Ländereien und zahlreiche Burgen. 1545 war sie 21-jährig mit Louis de Sainte-Maure, Marquis de Nesle und Graf von Joigny, verheiratet worden, doch beide hassten sich und bekämpften sich lebenslang. Die Gräfin wurde von ihren Untertanen ihres turbulenten Lebens wegen als „Guyonne la Folle“ bezeichnet, ihr Mann hingegen war borniert und von betrügerischen Beratern umgeben. Schließlich gelang es ihm, seine Frau auf Schloss Joigny für längere Zeit einzusperren. Nachdem sie 1557 geflohen war, erwirkte er bei Papst Paul IV.","w":"https://de.wikipedia.org/wiki/Burg_Laval"},"ch-Q1012942":{"n":"Burg Lichtenberg","c":"Burg in Frankreich","r":"Die Burg Lichtenberg, franz. Château de Lichtenberg, ist eine Burgruine in der Gemeinde Lichtenberg. Die Burg war erster Mittelpunkt der Herrschaft Lichtenberg und wurde bis zum Deutsch-Französischen Krieg als Festung genutzt.","w":"https://de.wikipedia.org/wiki/Burg_Lichtenberg_(Elsass)"},"ch-Q1014314":{"n":"Burg Trémazan","c":"Burg in Frankreich","r":"Die Burg Trémazan ist die Ruine einer Burg auf dem Gemeindegebiet von Landunvez im Département Finistère in der Bretagne. Der rund 400-köpfige Verein SOS Château de Trémazan versucht, die Anlage vor dem weiteren Verfall zu schützen.","h":"Die Burg wurde im 9. oder 10. Jahrhundert erbaut und 1250 nach teilweiser Zerstörung wieder aufgebaut. Sie war Sitz der Adelsfamilie du Chastel, die im Pays de Léon zu den wichtigsten Adelsfamilien gehörte und – wie z. B. Tanneguy III. du Chastel – einflussreiche Persönlichkeiten hervorbrachte. Die Familie du Chastel blieb Ende des 16. Jahrhunderts jedoch ohne männliche Nachkommen. Die Ruine war bis Anfang des 20. Jahrhunderts noch bewohnt und ist seit Mai 1926 als Monument historique in die französische Denkmalliste eingeschrieben.","w":"https://de.wikipedia.org/wiki/Burg_Tr%C3%A9mazan"},"ch-Q1122854":{"n":"Schloss Selles","c":"Schloss in Frankreich","r":"Das Schloss Selles befindet sich in der französischen Gemeinde Selles-sur-Cher im Département Loir-et-Cher der Region Centre-Val de Loire. Die noch erhaltenen Bauten der Anlage stehen seit 1926 unter Denkmalschutz.","h":"1212 baute Robert de Courtenay die 1142 ursprünglich von Ginon de Mehun errichtete und von Richard Löwenherz geschleifte Festungsanlagen wieder auf. Im 15. Jahrhundert gehörte die Festung dem Haus La Trémoille. 1604 erwarb Philippe de Béthune, Bruder von Sully, das Land und errichtete innerhalb einer durch Wassergräben abgegrenzten Einfriedung ein neues Schloss, das Pariser und königlichen Einfluss verriet. 1787 wurde der Hauptteil der Anlage zerstört, und 1813 wurde das gesamte Schloss durch die nachrevolutionären spekulativen Aktivitäten (Bande noire) vollständig verwüstet. König Karl VII. hielt sich mehrfach im Schloss auf; 1424 versammelte er hier die Generalstände und hielt 1429 vor der Befreiung von Orléans eine Ratssitzung ab. Ludwig XI. kam 1471 in das Schloss am Cher, Ludwig XII. im Jahr 1509. Die Königin von Polen, Maria Kazimiera Sobieska, hielt sich hier im Jahr 1696 auf.","w":"https://de.wikipedia.org/wiki/Schloss_Selles"},"ch-Q947669":{"n":"Schloss Le Moulin","c":"Schloss in Frankreich","r":"Das Schloss Le Moulin gehört zur französischen Gemeinde Lassay-sur-Croisne im Département Loir-et-Cher der Region Centre-Val de Loire. Das freistehende, rechteckig angelegte Wasserschloss, dessen breite Gräben von einem Nebenfluss der Croisne gespeist werden, wurde in der Zeit von 1480 bis 1500 von dem Hofarchitekten Jacques de Persigny erbaut und 1947 umfassend restauriert. Nachdem es im Januar 1926 in die Denkmalliste eingeschrieben worden war, folgte am 27. April 1927 die Klassifizierung als Monument historique.","h":"Dem Stallmeister Philippe du Moulin, der 1495 Karl VIII. während der Schlacht bei Fornovo das Leben retten sollte, wurde 1490 erlaubt, seinen gerade im Bau befindlichen Wohnsitz von Lassay-sur-Croisne zu befestigen. Der dankbare König verhalf seinem Jugendfreund zu einer reichen Ehefrau, der Witwe von Jean d’Harcourt, machte ihn zu seinem Kammerherrn und Ratgeber und vertraute ihm die Herrschaft von Langres an, wo er 1506 starb.","w":"https://de.wikipedia.org/wiki/Schloss_Le_Moulin"},"ch-Q1326818":{"n":"Schloss Miromesnil","c":"Schloss in Frankreich","r":"Das Schloss Miromesnil steht in der Gemeinde Tourville-sur-Arques im Département Seine-Maritime, das in der Normandie im Norden Frankreichs liegt. Der Name des Schlosses geht auf den französischen Adeligen Armand Thomas Hue, vicomte de Miromesnil zurück, einen Minister des Ancien Régimes unter Ludwig XVI.","h":"Ursprünglich stand an der Stelle des Schlosses eine Burg der Familie Dyel de Miromesnil. Diese wurde 1589 nach der Schlacht von Arques von den Truppen des Herzogs de Mayenne zerstört. Stehengeblieben sind nur eine Kapelle und zwei Türme. Ende des 16. und Anfang des 17. Jahrhunderts entstand das Schloss in seiner heutigen Form. Diese beiden Burgtürme wurden bei der Errichtung des neuen Schlosses integriert. Sie sind Teil der Parkfassade, die 1590 ganz im klassischen Stil Heinrichs des IV. entstand. Die Ehrenhoffassade entstand fünfzig Jahre später im Jahr 1640.","w":"https://de.wikipedia.org/wiki/Schloss_Miromesnil"},"ch-Q1959841":{"c":"Schloss in Frankreich"},"ch-Q2241293":{"n":"Schloss Grimaldi","c":"Schloss in Frankreich","r":"Das Schloss Grimaldi ist eine zum Palast umgebaute alte Burg im mittelalterlichen Stadtteil Haut de Cagnes der südfranzösischen Stadt Cagnes-sur-Mer, die heute als Museum genutzt wird. Die französische Bezeichnung lautet Château-Musée Grimaldi.","h":"Die Burg wurde um 1300 im Auftrag des französischen Admirals Rainier Grimaldi, Seigneur de Cagnes, erbaut. Er gehörte zum Antibes-Zweig der Grimaldis und ist ein Vorfahr der heute bekannten Fürstenfamilie von Monaco. Die Burg diente Beobachtungs- und auch Verteidigungszwecken. Im Schutz der auf der Bergspitze gelegenen Burg entwickelte sich der Stadtteil Haut de Cagnes, der in seiner damaligen Struktur heute noch weitgehend erhalten ist. Um 1620 baute Baron Jean-Henri Grimaldi die Burg zu einem Wohnpalast um. Im Innenhof entstanden ein schattiger Patio, eine prachtvolle Treppe und zweigeschossige Galeriegänge. Die Innenräume wurden im barocken Stil ausgeschmückt. In diesem Zustand ist das Schloss bis heute noch im Wesentlichen erhalten. Während der Französischen Revolution wurde es an die Familie Gerbaud und 1873 an die Familie Gerecke verkauft. Im Jahre 1937 erwarb die Stadt Cagnes-sur-Mer das Gebäude.","w":"https://de.wikipedia.org/wiki/Schloss_Grimaldi"},"ch-Q2242003":{"n":"Schloss La Bussière","c":"Schloss in Frankreich","r":"Das Schloss La Bussière ist ein Wasserschloss am Rande der französischen Gemeinde La Bussière in der Region Centre-Val de Loire. Es steht etwa zehn Kilometer nordöstlich von Gien im Südosten des Départements Loiret in der Puisaye. Die Anlage zählt zu den Schlössern der Loire und liegt zugleich an der Route Jacques-Cœur. Einige Teile sind seit November 1993 als Monument historique in die französische Denkmalliste eingeschrieben, nachdem eine erste Unterschutzstellung aus dem Februar 1982 annulliert worden war. Im Mai 1995 wurden weitere Partien des Schlosses, das sich in Privatbesitz befindet, als Monument historique klassifiziert.","h":"Das heutige Schloss geht auf eine mittelalterliche Gründung der Seigneurs de Feins im 12. Jahrhundert zurück, von denen Étienne de Feins als erstes Familienmitglied 1208 urkundlich genannt wurde. Die damalige Burg sollte die Île-de-France gegen die Burgunder sichern und war Bestandteil eines ganzen Burgengürtels entlang der Grenze dieser beiden Territorien. Zudem kontrollierte die Befestigung die wichtige Handelsstraße zwischen Paris und Lyon. La Bussière war damit eine der wichtigsten Herrschaften der Region. Per Erbschaft kam der Besitz an das Haus Sancerre, ehe es Étienne Fromont, unter Ludwig XII. Erster Präsident des Parlements von Paris, erbte. Im Jahr 1518 kam das Anwesen schließlich an Jean du Tillet, dessen Familie die folgenden fast 300 Jahre Besitzerin blieb. 1567 flüchteten sich während der Religionskriege 15 katholische Geistliche aus Gien in die Burg von La Bussière, die daraufhin von hugenottischen Truppen belagert wurde. Die Burgbesatzung musste sich schließlich ergeben. Die Geistlichen wurden geköpft und die Burg durch hugenottische Soldaten fast vollständig zerstört. Jean II. du Tillet ließ die zerstörte Anlage noch im 16. Jahrhundert mit veränderter Gestaltung wieder aufbauen. Dabei wurde die einstige Burg zu einem Schloss umgewandelt. Charles du Tillet fügte ihm um 1680 die heutigen Wirtschaftsgebäude hinzu. Sein Nachfahre Jean-Baptiste du Tillet war ein einflussreicher Höfling am Hofe des Sonnenkönigs Ludwig XIV. Unter anderem war er Vorsitzender des Großen Rats (französisch: Grand Conseil). Während seiner Herrschaft wurde La Bussière zum Marquisat erhoben. Anlässlich eines Besuchs der Grande Mademoiselle, Anne Marie Louise d’Orléans, duchesse de Montpensier, ließ er sein Schloss aus- und umbauen.","w":"https://de.wikipedia.org/wiki/Schloss_La_Bussi%C3%A8re"},"ch-Q1822513":{"n":"Palais Rohan","c":"Rathaus in Bordeaux, Frankreich"},"ch-Q2240202":{"n":"Schloss Baugé","c":"Schloss in Frankreich","r":"Schloss Baugé ist ein zwischen 1454 und 1465 von René I., Graf von Anjou, errichtetes Jagdschloss. Es steht in der französischen Kleinstadt Baugé im Département Maine-et-Loire in der Region Pays de la Loire.","w":"https://de.wikipedia.org/wiki/Schloss_Baug%C3%A9"},"ch-Q2969865":{"c":"Burg in Frankreich"},"ch-Q2738641":{"n":"Schloss Tourelles","c":"Burg in Frankreich","r":"Schloss Tourelles ist ein mittelalterlicher Donjon in Vernon im Département Eure in der Region Normandie. Das um 1200 errichtete Bauwerk gehört zu den bedeutenden königlichen Brücken- und Wehrbauten an der Seine und steht seit dem 12. Januar 1945 als monument historique unter Denkmalschutz.","h":"Die mittelalterliche Brücke über die Seine und das Ensemble des Vieux-Moulin bilden den historischen Kontext des späteren Donjons der Tourelles. Die Anlage liegt in einem seit dem 22. November 1943 geschützten Naturbereich. Ein gemeinsames Projekt von Département Eure und den Städten Vernon und Giverny ermöglichte ab 2013 die Öffnung des gesamten Uferabschnitts für Fußgänger und Radfahrer. Die erste Erwähnung eines Brückenturms erscheint 1203 in einem königlichen Register. Bereits zuvor existierten hölzerne Brückenkonstruktionen mit Mühlen, Lagerräumen und Zollstellen, deren Pfeiler und Pfahlgründungen sowohl die Brücke als auch die Nutzung des Flusswassers trugen. Bis ins 19. Jahrhundert blieb der Standort nahezu unverändert und war eng in die Stadtbefestigung integriert. Am 14. Januar 1189 ließ König Philipp II. August die bestehende Brücke zerstören, um einen möglichen Vorstoß Richard Löwenherz’ zu erschweren. Die Engländer errichteten anschließend eine eigene Holzbrücke und ein befestigtes Torhaus, dessen Fundamente bis heute sichtbar sind. Nach der Rückeroberung von Vernon im Jahr 1196 ließ Philipp II. August die Befestigungen des rechten Seineufers neu anlegen. Der Donjon der Tourelles ersetzte wahrscheinlich eine ältere, möglicherweise unter Heinrich I. von Normandie entstandene Anlage. Die neue Befestigung diente der Sicherung der Brücke und der Kontrolle des Verkehrs auf dem Fluss. Die erste Erwähnung erscheint 1202/1203 als „tour du pont“ („Brückenturm“). Am 30. Mai 1760 überließ Marschall de Belle-Isle das Schloss M. Le Moine de Belle-Isle. Dieser leitete eine umfassende Restaurierung ein, wie eine lateinische Inschrift von 1763 („Restauratum anno domini 1763“) auf der Westfassade belegt.","w":"https://de.wikipedia.org/wiki/Schloss_Tourelles"},"ch-Q2970548":{"n":"Burg Saint-Malo","c":"Burg im Département Ille-et-Vilaine, Frankreich","r":"Das Schloss oder die Burg Saint-Malo ist ein Gebäudekomplex, der zwischen dem 15. und 18. Jahrhundert erbaut wurde und sich nordöstlich der Stadtmauer von Saint-Malo in der Bretagne befindet. Als Bauherren fungierten die Herzöge der Bretagne, um ihre Vormundschaft über die Stadt Saint-Malo zu gewährleisten und einen Schutz gegen etwaige britische Eroberer bieten zu können.","h":"Die Burg entstand auf Veranlassung der Herzöge der Bretagne durch Anbau an die im 14. und 15. Jahrhundert wieder aufgebaute frühere Stadtmauer, die aus behauenen Feldsteinen bestand. Sie ließen auf vorhergehenden Grundmauern einen großen Bergfried errichten, der den einzigen Zugang vom Festland zu der Stadt Saint-Malo bildete, die sich auf einer Insel entwickelt hatte. Die hohe Stadtmauer und die Burgbauwerke wurden im 16. Jahrhundert zu einer Verteidigungsanlage zusammengefasst, außerdem wurde an die Ostseite der Burg die Galère angebaut. Der Festungsbaumeister Vauban verstärkte diese Galerie später zu einer dreieckigen Anlage um den Innenhof, deren Gestalt sich an einem Schiffsrumpf orientierte. Bei diesen Umbauarbeiten erhielt auch die Stadtmauer zwei weitere Türme, sie heißen Tour des Remparts, Tour Bidouane (Pulverturm, 15. Jhd.) und weitere zwei flankieren die Grande Porte. An den Ecken entstanden dann ab Anfang des 17. Jahrhunderts Bastionen. Die erhaltenen Bastionen der Stadtbefestigung tragen die Bezeichnungen Bastion St-Louis (1716–1721), Bastion St-Philippe (1714) und Bastion de la Hollande (1674). Acht Stadttore bilden den Zugang zur inneren Stadt, der Ville close. 1695 ließ Ludwig XIV. die Burg verstärken: Die vier Türme wurden nivelliert und mit einer Plattform für die Aufstellung von Artilleriegeschützen verbunden. Im Folgejahr, 1696 entstand eine Kapelle, 1698 erfolgte der Bau einer Kaserne. Der Baumeister Simon Garrangeau erhielt zu Beginn des 18. Jahrhunderts den Auftrag, die Wallanlagen zu überprüfen und zu verstärken. Nach der Revolutionszeit zog eine Ingenieurgarnison in die Burg ein und veranlasste die Errichtung weiterer Gebäude innerhalb der Ringmauern. Die Armee nutzte diese Bauten des Burgensembles bis 1921.","w":"https://de.wikipedia.org/wiki/Burg_Saint-Malo"},"ch-Q3361032":{"c":"Gerichtsgebäude in Frankreich"},"ch-Q3361183":{"c":"Palast in Frankreich"},"ch-Q2969479":{"c":"Schloss in Frankreich"},"ch-Q2969508":{"n":"Château de Kériolet","c":"Schloss in Frankreich","r":"Das Schloss Kériolet, auch Keriolet geschrieben, ist ein bretonisches Schloss in Concarneau im französischen Département Finistère.","h":"Das ursprüngliche Herrenhaus Kériolet wurde im frühen 13. Jahrhundert errichtet. 1862 erwarb die russische Hofdame Sinaida Iwanowna Jussupowa das Schloss für ihren Ehemann Charles Chauveau und ließ es ab dem folgenden Jahr in neogotischem Stil ausbauen. Die Arbeiten wurden von dem französischen Architekten Joseph Bigot geleitet. Sinaida Iwanowna Jussupowa hielt sich nur im Sommer in Kériolet auf, im Winter lebte sie in Paris. Charles Chauveau lebte ganzjährig in Kériolet. Er starb 1889 und vererbte das Schloss an seine Schwester. Sinaida Jussupowa kaufte Kériolet zurück und schenkte es dem Département Finistère mit der Auflage, ein Museum einzurichten und nichts zu verändern. Da diese Auflagen nicht vollständig eingehalten wurden, klagte der im französischen Exil lebende Rasputin-Attentäter Felix Jussupow, der Urenkel von Sinaida Jussupowa, auf Rückgabe des Schlosses und war damit schließlich erfolgreich. 1971 wurde Kériolet an die Stadt Concarneau verkauft. Seit 1988 ist Christophe Lévèque der Eigentümer und lässt das Schloss schrittweise restaurieren. Das Schloss steht seit dem 21. Dezember 1984 unter Denkmalschutz (Monument historique).","w":"https://de.wikipedia.org/wiki/Schloss_K%C3%A9riolet"},"ch-Q2680279":{"c":"Burg in Frankreich"},"ch-Q2422758":{"n":"Schloss Chavaniac","c":"Burg in Chavaniac-Lafayette, Département Haute-Loire, Auvergne-Rhône-Alpes, Frankreich","r":"Das Schloss Chavaniac ist ein denkmalgeschütztes Schloss in der französischen Gemeinde Chavaniac-Lafayette im Département Haute-Loire. Das im Kern auf eine mittelalterliche Feste des 14. Jahrhunderts zurückgehende Gebäude ist als Geburtsort des Generals Marquis de La Fayette – einem Helden des Amerikanischen Unabhängigkeitskrieges, Mitgestalter der Französischen Revolution und einem der wenigen Ehrenbürger der Vereinigten Staaten – eine historisch bedeutende nationale und internationale Gedenkstätte.","h":"Die Ursprünge des Anwesens liegen in einer gallo-römischen Siedlung, die sich im Mittelalter zu einer eigenständigen Grundherrschaft entwickelte. Im 14. Jahrhundert befand sich der Besitz in Händen der bürgerlichen Familie Suat aus Langeac, die hier ein befestigtes Herrenhaus (maison forte) errichtete. Im Jahr 1697 wurde diese mittelalterliche Festung durch einen verheerenden Großbrand fast vollständig zerstört. Auf den verbliebenen Fundamenten und den Überresten der dicken Außenmauern ließen die Suat das Gebäude im Jahr 1701 neu aufführen. Dabei wurde der Neubau erheblich vergrößert, in einer schlichteren, wohnlicheren Form neu strukturiert und zu einem repräsentativen Schloss ausgebaut. Durch die Heirat von Édouard Motier de La Fayette (dem Großvater des späteren Generals) mit Marie Catherine Suat de Chavaniac im Jahr 1708 (andere Quellen nennen das Jahr 1711) gelangte das Schloss in den Besitz der Familie Motier de La Fayette. Am 6. September 1757 wurde hier Gilbert du Motier, Marquis de La Fayette, geboren. Nach dem frühen Tod seines Vaters in der Schlacht bei Hastenbeck (1757) und dem Tod seiner Mutter in Paris wuchs der junge La Fayette auf Chavaniac unter der Obhut seiner Großmutter Marie-Catherine und seiner Tanten in der ländlichen Isolation der Auvergne auf. Diese prägenden Jugendjahre beeinflussten zeitlebens seine enge Bindung an die Region. Weltweite Berühmtheit erlangte er später durch sein militärisches Eingreifen im Amerikanischen Unabhängigkeitskrieg (1775–1783) sowie durch seine führende Rolle in den französischen Revolutionen von 1789 und 1830. Aufgrund dieses bleibenden Beitrags zu den demokratischen Bewegungen auf beiden Seiten des Atlantiks erhielt das Schloss den Beinamen „Manoir des deux mondes“ (Herrenhaus der zwei Welten).","w":"https://de.wikipedia.org/wiki/Schloss_Chavaniac"},"ch-Q2968329":{"n":"Schloss Osthoffen","c":"Schloss in Frankreich","r":"Das Schloss Osthoffen ist ein Schloss in der elsässischen Gemeinde Osthoffen im Département Bas-Rhin 15 Kilometer westlich von Straßburg. Seit dem 11. September 1963 ist es zum Teil als Monument historique registriert.","h":"Der Ursprung des Schlosses reicht zurück in die Zeit der römischen Eroberung 50 v. Chr. Es gehörte zum Verteidigungssystem des römischen Lagers auf dem Hügel Scharrach, fünf Kilometer westlich des Schlosses am Fuß der Vogesen. Der Wachturm, aus dem später das Schloss Osthoffen entstand, lag östlich des Römerlagers Scharrach. Hieraus leitet sich sein germanisierter Name ab (OST → Osten – HOFFEN → Hof oder Lager auf Deutsch). Sein Gegenstück westlich des Hauptlagers Scharrach ist das Dorf Westhoffen, das auf den Resten einer Befestigungsanlage aufgebaut ist und sich in gleicher Entfernung vom Hauptlager befindet. Ursprünglich lagen Schloss und Dorf Osthoffen nicht beieinander. Das Dorf lag zwei Kilometer östlich des Schlossbereichs in einem kleinen Tal nahe einer Quelle (an dieser Stelle wurden Tonscherben gefunden). Nach Kriegen und Zerstörungen suchte die Dorfbevölkerung im Lauf des ersten Jahrtausends Schutz in der Umgebung der Schlossmauern. Im 12. Jahrhundert wurde eine Burg auf dem Umriss und den Grundmauern des ehemaligen römischen Lagers aufgebaut. Ihre Gräben waren niemals mit Wasser gefüllt, sie war nie eine Wasserburg. Vom 12. bis zum 15. Jahrhundert diente sie als Wehranlage. Anfang des 15. Jahrhunderts wurde die Burg nach einem zehn Tage währenden Angriff durch den Bischof von Straßburg als Ruine hinterlassen. Dieser Zustand währte ein volles Jahrhundert, bis es Ende des 15. Jahrhunderts von dem Baumeister Jost von Seebach wieder aufgebaut wurde. Nun änderte sich die Bestimmung der Anlage: Ihre militärische Bedeutung ging zurück, sie wurde vor allem zum landwirtschaftlichen und religiösen Mittelpunkt. Schließlich wurde das Schloss Osthoffen dem Territorium der großen Abtei Marmoutier einverleibt, das bis Lothringen reichte.","w":"https://de.wikipedia.org/wiki/Schloss_Osthoffen"},"ch-Q2182818":{"c":"Burg in Frankreich"},"ch-Q2242766":{"n":"Schloss O","c":"Schloss in Frankreich","r":"Das Schloss O ist ein Wasserschloss in Mortrée, nördlich von Alençon im Département Orne, Region Normandie.","h":"Die Wurzeln des Schlosses liegen in einer befestigten Anlage des 11. Jahrhunderts, die von einer Familie erbaut wurde, die sich nach ihrem Besitz nannte. Erster urkundlich genannter Spross war Robert d’O, der Robert I., Herzog der Normandie, auf einer Pilgerreise in das Heilige Land begleitete. Die Stammburg seiner Familie wurde während des Hundertjährigen Krieges von englischen Truppen zerstört. Ab 1484 ließ Jean I. d’O, Kammerherr des französischen Königs Karl VIII., den Bau des heutigen Schlosses beginnen. Unter seiner Ägide wurde ab 1484 der heutige Torbau auf den Fundamenten der alten Burg errichtet. Der sich anschließende, südliche Galerieflügel wurde von Jeans Sohn Charles d’O erbaut. Ihm folgte als Schlossbesitzer und Seigneur von O sein Sohn Jean II., der es unter Franz I. bis zum Hauptmann der Schottischen Garde und Seneschall der Normandie brachte. Jean II. wurde von seinem Sohn François beerbt. Dieser war Surintendant des Finances und Mignon Heinrichs III. und interessierte sich mehr für seine Besitzungen im damaligen Fresne (heute Ecquevilly). Er starb 1594 völlig überschuldet, sodass Schloss O verkauft wurde, um seine immensen Schulden zu tilgen. Käufer war Jacques de La Guesle, Mitglied des Parlement de Paris, der es seinem Bruder Alexandre vererbte. Für diesen wurden das Schloss und die dazugehörigen Besitzungen 1616 zum Marquisat erhoben. Nach Alexandres kinderlosem Tod verkaufte seine Nichte den Besitz an den Herzog von Luynes, der es 1647 an die Familie Montaigu (auch Montagu geschrieben) veräußerte. Diese ließ vor allem im Inneren Veränderungen vornehmen und die Außenfassade des Südflügels um 1770 gemäß dem damaligen Zeitgeschmack umfassend verändern. 1795 erwarb Charles Valentin Roques die Anlage.","w":"https://de.wikipedia.org/wiki/Schloss_O"},"ch-Q2186251":{"c":"Burg in Frankreich"},"ch-Q2321914":{"n":"Schloss Courances","c":"Schloss in Courances, Frankreich","r":"Das Schloss Courances in der gleichnamigen französischen Gemeinde ist eine Schlossanlage aus dem 17. Jahrhundert, die vor allem für ihren Park mit Wasserspielen, Rasen- und Waldflächen bekannt ist. Er wurde im 16. Jahrhundert unter Cosme Clausse angelegt und von nachfolgenden Schlossherren mehrfach erweitert sowie umgestaltet. Nach einer schriftlichen Aufzeichnung aus dem 18. Jahrhundert soll der Name des Anwesens von den zahlreichen Quellen und kleinen Wasserläufen auf seinem Grundstück herrühren.","h":"Die Seigneurie Courances existierte schon im Mittelalter. Erstes namentlich bekanntes Mitglied einer gleichnamigen Familie war Jean de Courances, für das 13. Jahrhundert ist ein Henri de Courances, Marschall von Frankreich bezeugt. Die Familie starb gegen Ende des 14. Jahrhunderts aus. 1460 erwarb die aus Paris stammende Familie Lapite die Herrschaft und verkaufte sie 1552 mit 1500 Hektar Landbesitz für 15.000 Livres an Cosme (auch Côme) de Clausse. Dem Finanzsekretär Heinrichs II. gehörte bereits die benachbarte Herrschaft Fleury samt einem dort neugebauten Schloss. In Courances ließ er das vorhandene mittelalterliche Logis durch den Baumeister Gilles Le Breton vollständig umbauen. Auch der kleine ummauerte Garten aus dem Mittelalter wurde durch einen großzügigen Renaissancegarten ersetzt, in dem Wasser ein bestimmendes Gestaltungselement war. So ließ Clausse südwestlich des Schlosses den sogenannten Großen Kanal (französisch Grand Canal) anlegen, ein sehr langes und schmales Wasserbecken. Es war der zweite jemals in Frankreich gebaute Gartenkanal. Nur in Fleury gab es zu jener Zeit einen älteren. Als Cosmes 1558 starb, erbten zwei unmündige Söhne den Besitz. Die Herrschaft Fleury fiel an den älteren, während der zweitgeborene Pierre 1566 anlässlich seiner Hochzeit mit Marie Le Picard die Seigneurie Courances erhielt. Noch zu dessen Lebzeiten besuchte sie 1606 König Heinrich IV. zusammen mit dem Dauphin Ludwig und Gefolge. Ludwig kehrte noch viermal nach Courances zurück: 1631, 1633, 1634 und 1636. Allerdings gehörte das Anwesen zu jener Zeit schon nicht mehr der Familie Clausse, sondern den Gallards, denn Pierre Cosmes Sohn François hatte keine Nachkommen und verkaufte das Schloss deshalb am 13. Juli 1622 für 124.000 Livres an Claude I.","w":"https://de.wikipedia.org/wiki/Schloss_Courances"},"ch-Q2068180":{"c":"Schloss in Frankreich"},"ch-Q2579100":{"c":"Schloss in Frankreich"},"ch-Q2971195":{"n":"Schloss La Clayette","c":"Schloss in Frankreich","r":"Das Schloss La Clayette ist ein Wasserschloss in der gleichnamigen französischen Gemeinde des Arrondissement Charolles des Départements Saône-et-Loire in der Region Bourgogne-Franche-Comté.","h":"Das Schloss La Clayette war vom 14. Jahrhundert bis zur Französischen Revolution das Zentrum eines der größten Besitzungen in dieser Region. 1380 verwandelte Philibert de Lespinasse eine bereits bestehende Befestigung, die zum Zoll eintreiben genutzt wurde, in ein Schloss mit Rundtürmen. 1420 fiel das Schloss Louis de Chantemerle, dessen Familie zur Entourage der Herzöge von Burgund gehörte. Am 2. August 1524 verbrachte Franz I., der Ritterkönig, unterwegs in Richtung Lyon, eine Nacht im Schloss. 1632 fiel der Besitz mit dem Tod Alice-Éléonore de Chantemerles an ihren Ehemann Paul de Damas und somit an das Haus Damas. 1703 erbte mit dem Ableben von Jean-Léonard de Damas der Palatin de Dyo das Anwesen. In der Folgezeit wechselt das Schloss mehrmals den Besitzer. Am 4. November 1722 erwarb Bernard de Noblet La Clayette für den Preis von 160.000 Livres und 1800 Flaschen Wein. Bernard de Noblet wurde Baron von Clayette, sowie Baron von Tremont. 1736 wurde La Clayette zur Grafschaft erhoben und fortan blieb das Schloss in Besitz der gleichen Familie.","w":"https://de.wikipedia.org/wiki/Schloss_La_Clayette"},"ch-Q9393076":{"c":"Palast in Frankreich"},"ch-Q8822076":{"n":"Schloss Châteauneuf-du-Pape","c":"Schloss in Châteauneuf-du-Pape, Frankreich"},"ch-Q83713806":{"n":"Schloss Poseidon","r":"Château Poseidon, auch bekannt unter dem Namen Château de Laborde‚ ist ein im 19. Jahrhundert erbautes Schloss im Stil der Neorenaissance. Es steht in der Gemeinde Val-Fouzon im Departement Indre in der Region Centre-Val de Loire. Die Anlage steht im Privatbesitz.","h":"Das Schloss wurde von 1860 bis 1863 nach den Plänen des Architekten Alfred Dauvergne (1824–1885) erbaut, zur Zeit des Französischen Zweiten Kaiserreichs, einer Periode landwirtschaftlichen und industriellen Wohlstands für das Département Indre, das bereits seit 1847 an das Eisenbahnnetz angeschlossen war. Dauvergne wurde im 1851 zum Departementsarchitekten ernannt und realisierte mehrere Bauprojekte und öffentliche Bauvorhaben in Châteauroux und Umgebung, die ab 1857 dazu beitrugen, seinen Ruf in der Region zu festigen. Diese Erfolge brachten ihm zahlreiche private wie auch öffentliche Aufträge ein, wie aus seinen im Archiv des Departements Indre aufbewahrten Unterlagen hervorgeht. Der Bau erfolgte nach dem Abriss eines befestigten Bauernhofs, von dem ein einzelner Turm einige Dutzend Meter vor dem heutigen Gebäude erhalten geblieben ist. Die meisten anderen Teile dieses Bauernhofs sind verschwunden. Das Abbruchmaterial dieses ersten Gebäudes wurde für das Fundament und den Sockel des neuen Schlosses verwendet. Louis Gustave Boullet (Valençay, 7. August 1814 – 3. März 1867) und seine Ehefrau Gabrielle Picot d’Agard (1826–1905) ließen das Schloss Laborde errichten und waren dessen erste Bewohner. Er stammt aus einer Familie von Grundbesitzern und Kaufleuten. Das Paar hatte drei Kinder: Henry Augustin 'Louis' Boullet (1847–1907), Gabrielle Boullet (1851–1923) und Gustave Boullet (1863–1884). Louis Boullet übernahm nach dem Tod seiner Mutter das Anwesen Laborde. Er heiratete „Léonie“ Marie Louise Conilh de Beyssac (1858–1934) und sie hatten drei Kinder: Marthe Paillet-Boullet (1886–1963), Pierre Boullet (1889–1956) und Eugène Boullet (1890–1940).","w":"https://de.wikipedia.org/wiki/Schloss_Poseidon"},"ch-Q386009":{"c":"Burg in Frankreich"},"ch-Q541130":{"n":"Festung von Bertheaume","c":"Burg in Frankreich","r":"Das Fort Bertheaume liegt auf einer Insel vor der bretonischen Küste auf der Gemarkung von Plougonvelin. Sie diente zur Verteidigung der Meerenge von Brest und wurde von 1694 bis 1944 militärisch genutzt.","w":"https://de.wikipedia.org/wiki/Fort_Bertheaume"},"ch-Q511492":{"n":"Schloss Commarin","c":"Schloss in Frankreich","r":"Das Schloss Commarin ist ein französisches Wasserschloss im Stil des klassizistischen Barocks. Es steht im Herzen Burgunds in der Ortschaft Commarin, Département Côte-d’Or, etwa vier Kilometer nördlich von Châteauneuf-en-Auxois.","h":"Schloss Commarin geht vielleicht auf eine römische villa rustica zurück, eine urkundlich Erwähnung Commarins als festes Haus aus dem 12. Jahrhundert fand jedoch erst im Jahr 1214 statt, als mit Aubert de Commarin auch der erste namentlich bekannte Besitzer genannt wurde. 1346 übereignete Pierre de Commarin, der ohne männlichen Erben geblieben war, das befestigte Haus seinem Neffen Jean de Courtiamble, auch Courte Jambe geschrieben, was im Deutschen „kurzes Bein“ oder auch „Kurzbein“ bedeutet. Jeans Sohn Jacques war Kammerherr des burgundischen Herzogs Philippe le Hardi. Er baute das befestigte Anwesen zu Beginn des 15. Jahrhunderts zu einer Burg aus. Diese war von einem doppelten Wassergraben und einer viereckigen Ringmauer umgeben, deren Ecken von massiven Rundtürmen markiert wurden. Nordöstlich war ihr eine annähernd trapezförmige Vorburg vorgelagert, die vom Hauptgebäude durch einen Graben getrennt war. Zeugen dieser damaligen Anlage sind auch heute noch die Wassergräben, die Schlosskapelle und zwei massive Rundtürme. Zur Burg gehörten außerdem Nutz- und Ziergärten sowie Fischteiche. Jacques gab die Seigneurie Commarin samt der Burg seiner ältesten Tochter Agnès als Mitgift, als sie um die Mitte des 15. Jahrhunderts Jean de Dinteville, den Herrn von Chenet, heiratete. Über den Sohn Claude kam der Besitz 1477 an Jacques de Dinteville. Er war Ratgeber des Königs Ludwig XI. und Vertrauter von dessen Nachfolger Franz I., den er 1521 in Commarin als Gast empfing. Seine Erbtochter Bénigne brachte den Besitz durch ihre 1500 geschlossene Ehe mit Girard (auch Gérard) de Vienne, vicomte de Beaune, an diese Familie.","w":"https://de.wikipedia.org/wiki/Schloss_Commarin"},"ch-Q600832":{"c":"Burg in Frankreich"},"ch-Q688665":{"n":"Frankenburg","c":"Burg in Frankreich","r":"Die Frankenburg ist die Ruine einer Gipfelburg vom Beginn des 12. Jahrhunderts nahe Sélestat auf dem Gebiet von Neubois im Elsass. Die Burgruine steht als Monument historique unter Denkmalschutz.","h":"Die obere bzw. innerste der drei Mauern (mur supérieur oder mur franc) schließt unmittelbar westlich an die mittelalterliche Burg an. Ihre Zeitstellung ist unklar, vermutlich gehört sie zu einem Vorgängerbauwerk der Burg. Der mittlere Mauerzug (mur païen = Heidenmauer) umschließt eine Fläche von 1,7 ha und wurde in seinem Ostteil durch die mittelalterliche Burg überbaut. Sie wurde spätestens im 4. Jahrhundert errichtet. Die Heidenmauer wurde 1990 als Monument historique eingetragen. Der erhaltene Abschnitt des unteren bzw. äußeren Mauerzugs (mur inférieur) liegt unmittelbar am Pass zwischen dem Schlossberg im Osten und dem Altenberg im Westen. Falls die Mauer den Schlossberg auf gleichbleibendem Höhenniveau umschlossen hat, umfasste sie eine Fläche von sieben bis acht Hektar. Bei Grabungen im Jahr 2014 wurden hier Reste einer Pfostenschlitzmauer gefunden und unter anderem drei Nauheimer Fibeln sowie keltische und römische Münzen geborgen. Da die Fibeln, die für die Spätlatènezeit typisch sind, unterhalb des Mauersockels gefunden wurden, definieren sie einen terminus post quem. Die äußere Mauer kann deshalb frühestens in der zweiten Hälfte des 1. Jahrhunderts v. Chr. errichtet worden sein. Wohl legendär ist der Bericht von Daniel Specklin aus dem 16. Jahrhundert, die Frankenburg sei vom Merowinger Chlodwig I. nach der Eroberungen des Elsass erbaut worden. Die Burg entstand vermutlich am Anfang des 12. Jahrhunderts, möglicherweise am Ort einer älteren Anlage. Sie wurde erstmals 1143 als Eigentum der Grafen von Frankenburg erwähnt, einer Nebenlinie der Grafen von Saarbrücken, die sich ab 1189 Grafen von Werd nannten und ab kurz nach 1196 die Landgrafen im Unterelsass stellten. Heinrich II. Sigebert von Werd (1239–1278) ließ im dritten Viertel des 13.","w":"https://de.wikipedia.org/wiki/Frankenburg_(Elsass)"},"ch-Q1012796":{"n":"Burg La Hunaudaye","c":"Burg in Frankreich","r":"Die Ruine der Burg La Hunaudaye steht auf dem Gebiet der französischen Gemeinde Plédéliac im bretonischen Département Côtes-d’Armor. Sie kann von Anfang April bis Anfang November gegen Entgelt besichtigt werden.","h":"Olivier (de) Tournemine errichtete mit Erlaubnis des Herzogs Pierre Mauclerc im Jahr 1220 eine erste Burganlage an der heutigen Stelle. Sie sollte die östliche Grenze der Grafschaft Penthièvre gegen die Grafschaft Dinan sichern. Von dieser ersten Anlage sind heute nur noch wenige Reste vorhanden, denn sie wurde während des bretonischen Erbfolgekriegs 1341 von englischen Soldaten und Truppen Jean de Montforts angegriffen und fast vollkommen zerstört. Pierre (de) Tournemine begann Ende des 14. oder Anfang des 15. Jahrhunderts mit einem Wiederaufbau, bei dem die Reste zweier noch vorhandener Türme durch drei neue Wehrtürme ergänzt und mit neuen Kurtinen zu einer Ringmauer verbunden wurden. An drei der Mauern schlossen sich an der Innenseite Wohn- und Wirtschaftsgebäude an. Von den Kämpfen und den damit verbundenen Schäden während der französischen Religionskriege blieb La Hunaudaye im Gegensatz zu vielen anderen Burgen und Schlössern verschont, weil die gegnerischen Parteien eine Neutralität der Burg anerkannten und sie nicht angriffen. Zu Beginn des 17. Jahrhunderts ließ der damalige Besitzer Sébastien de Rosmadec einen Teil des heute noch sichtbaren Logis’ im Stil der Renaissance errichten. Davon zeugt noch die Ruine eines Treppenhauses, das die verschiedenen Geschosse des Gebäudes miteinander verband. Diese Bauarbeiten waren die letzten, die an der Anlage vorgenommen wurden, danach wurde sie immer mehr vernachlässigt. Im Jahr 1631 kam sie an die Familie Rieux und 1783 an die Familie La Moussaye-Carcouët, die sie schon ein Jahr später an die Grafen von Talhouët weiterverkaufte.","w":"https://de.wikipedia.org/wiki/Burg_La_Hunaudaye"},"ch-Q1012838":{"n":"Burg Landsberg (Elsass)","c":"Burg in Frankreich","r":"Die Ruine der Burg Landsberg im Elsass steht auf einem südlichen Ausläufer des Odilienbergmassivs rund 30 Kilometer südwestlich von Straßburg. In einer Höhe von 580 Metern über NN auf einem Bergsporn liegend, dominiert sie die Ortschaft Heiligenstein im Département Bas-Rhin.","h":"Eine erste schriftliche Erwähnung der Burg fand in einer Urkunde vom 23. Juni 1200 statt, mit der die Äbtissin des Klosters Niedermünster dem Ritter Conrad von Vienhege (auch Finhey, Vigenhegen und Vienhenne) ein Grundstück überließ, auf dem sich seine gerade entstandene Burg befand. Der Burgherr nannte sich nachfolgend nach seinem neuen Besitz „von Landsberg“. Die in älteren Publikationen oft zu lesende Behauptung, die Herren von Landsberg seien bereits 1144 urkundlich genannt worden, gilt mittlerweile ebenso als widerlegt wie die Annahme, die durch den Hortus Deliciarum bekannt gewordene Äbtissin Herrad von Landsberg sei ein Mitglied dieser Adelsfamilie gewesen. Burg Landsberg entstand zur Sicherung von staufischen Besitzungen um Barr, Andlau und des unter staufischem Schutz stehenden Klosters Hohenburg, dessen Ministeriale die Landsberger waren, doch schon 1232 wechselten diese ihren Lehnsherrn und schlugen sich auf die Seite des Straßburger Bischofs, dessen Truppen nachfolgend die regionalen staufischen Güter bedrohten. Der Schultheiß von Hagenau, Wölfelin, begann nach den Aufzeichnungen des Chronisten Richer von Senones deshalb in jener Zeit nahe Andlau mit der Errichtung einer Burg namens Landeshaoite. Eine Hypothese lautet dahingehend, dass es sich bei Landeshaoite um die Landsberger Burg gehandelt haben könnte, die Wölfelin an sich gebracht und anschließend aufwändig aus- und umgebaut haben könnte, sodass von einem Neubau die Rede war. 1237 fiel Wölfelin allerdings bei Kaiser Friedrich II. in Ungnade, und die Burg könnte wieder an die Herren von Landsberg zurückgefallen sein.","w":"https://de.wikipedia.org/wiki/Burg_Landsberg_(Elsass)"},"ch-Q1014269":{"n":"Burg Tonquédec","c":"Burg in Frankreich","r":"Burg Tonquédec ist die Ruine einer Höhenburg in der Bretagne. Sie liegt wenige Kilometer nordwestlich der Ortschaft Tonquédec über dem Tal des Flusses Léguer. Die Burg ist mit ihren neun Türmen und zwei Bergfrieden eine der meistbesuchten Touristenattraktionen im Département Côtes-d’Armor.","h":"Die heutige Burganlage entstand im 15. Jahrhundert anstelle einer vorherigen Festungsanlage aus dem 12. Jahrhundert. Diese wurde im Auftrag der Familie Coëtmen-Penthièvre erbaut. Die Burgherren Rolland II. und Rolland III. de Coëtmen waren mit Olivier V. de Clisson verbündet, der auf der Seite Karls V. stand und daher mit Johann IV., Herzog der Bretagne in Streit lag. 1395 wurde daher die alte Burg auf Befehl Johanns teilweise geschleift. Roland IV. de Coëtmen ließ die Burg zwischen 1406 und 1460 wieder aufbauen. Zwischen 1470 und 1500 folgte eine zweite Ausbauphase, bedingt durch den Versuch des Königreichs Frankreich, die Autonomie der Bretagne zu untergraben. In den folgenden Jahren wechselte die Anlage mehrfach den Besitzer. Während der Hugenottenkriege ließ der protestantische Eigentümer Gouyon de La Moussaye die Burg in den Jahren 1570 bis 1598 modernisieren und zu einer mit Artillerie bestückten Festung ausbauen. Die Burg wurde zeitweilig zum Zufluchtsort für Hugenotten. Auf Befehl Richelieus wurde die Burg 1626 geschleift.","w":"https://de.wikipedia.org/wiki/Burg_Tonqu%C3%A9dec"},"ch-Q1014396":{"n":"Burg Villerouge-Termenès","c":"Burg in Frankreich","r":"Die Burg Villerouge-Termenès ist eine mittelalterliche Burg inmitten des Dorfes Villerouge-Termenès am Ostrand des Bergmassivs der Corbières im heutigen Département Aude in der französischen Region Okzitanien. Sie liegt damit in etwa 310 Metern Höhe und etwa 44 Kilometer (Fahrtstrecke) südwestlich von Narbonne bzw. 50 Kilometer südöstlich von Carcassonne. Die Anlage ist seit dem 6. Oktober 1976 als Monument historique klassifiziert.","h":"Eine Burg wird bereits im Jahr 1110 erwähnt. Sie gehörte – ebenso wie die Dörfer in der Umgebung – zum Besitz des Erzbistums Narbonne. Dieses war genötigt, seinen Landbesitz gegen Übergriffe anderer regionaler Usurpatoren sowie räuberischer Banden zu verteidigen. Im 13. Jahrhundert kam als Aufgabe der Schutz des katholischen Glaubens gegen die Katharer- oder Albigenserbewegung hinzu. Als mittelalterlicher Grundherr musste man auch dafür Sorge tragen, dass die Abgaben der Bauern (Zehntsteuer) pünktlich und in voller Höhe entrichtet wurde. Zu diesem Zweck wurden Verwaltungsbeamte, sogenannte baillies, eingesetzt. Die Burg von Villerouge war der Sitz einer von elf baillages des Erzbistums Narbonne.","w":"https://de.wikipedia.org/wiki/Burg_Villerouge-Termen%C3%A8s"},"ch-Q1014739":{"n":"Burg Étampes","c":"Burg in Frankreich","r":"Die Burg Étampes war eine königliche Festung in Étampes. Von der Höhenburg existiert nur noch die Ruine des Donjon, genannt Tour de Guinette. Sie stand auf dem Plateau de Guinette im Nordwesten der Stadt und überragte die Täler der Louette, der Chalouette und der Juine.","h":"Eine erste Burg wurde im Auftrag des Königs Robert II. (996–1031) gebaut. Der heutige Donjon stammt aus der Zeit zwischen 1130 und 1150. Ende des 12. Jahrhunderts wurden die Umfassungsmauern angefügt. Von 1201 bis 1213 war die Königin Ingeborg hier inhaftiert. 1589 erlaubte Heinrich IV. den Bürgern von Étampes, die Steine der Burg für den Hausbau zu verwenden. Während der Revolution wurde das Gelände verkauft, der neue Eigentümer ließ die letzten Gebäude abreißen und machte aus dem Turm einen Steinbruch. 1821, nach der Restauration, verkaufte der Herzog von Orléans die Burg. 1859 erwarb die Stadt Étampes den Donjon, der 1862 zum Monument historique erklärt wurde.","w":"https://de.wikipedia.org/wiki/Burg_%C3%89tampes"},"ch-Q1090616":{"n":"Château Pape-Clément","r":"Das Château Pape Clément ist ein sehr bekanntes Weingut in Pessac am Stadtrand von Bordeaux. Das Weingut gehört zur Appellation Pessac-Léognan, zu dem auch alle unmittelbar im Stadtgebiet von Bordeaux liegenden Weingüter gehören wie auch die bekannten Güter Château Haut-Brion und Château La Mission Haut-Brion.","h":"Château Pape Clément wurde vor Jahrhunderten in einer alten bordelaiser Winzer-Familie auf den Sohn Bertrand de Got vererbt, der Bischof wurde, später in Rom Kurienkardinal wurde und zum Papst Klemens gewählt wurde. Seit 1305 trägt das Gut seinen Namen. Klemens überließ das Gut in der Folge dem Bistum Bordeaux, das daraus ein Mustergut machte. 1791 wurden alle Besitztümer der Kirche aufgrund der französischen Revolution beschlagnahmt und verkauft. Der Bankmann Charles Peixotto erwarb das Gut. Château Pape Clément wechselte in der Folge häufig den Besitzer und hatte insbesondere unter Jean-Baptiste Clerc eine Blütezeit. Er vergrößerte das Gut erheblich und baute das Château. Nach der Reblaus-Katastrophe und den neuen Pilzkrankheiten wie der Echte und Falsche Mehltau wurde Bordeaux 1937 von schweren Hagelschauern heimgesucht. Ein Großteil der Weinfelder wurde zerstört. Nach den überaus schlechten Jahrgängen von 1935 und 1936 bedeutete dies das Aus für viele Weingüter der Region. Château Pape Clément wurde 1939 von Paul Montagne aufgekauft. Unter Mithilfe des Önologen Émile Peynaud baute er das Weingut wieder auf. Seine Qualitätsbemühungen wurden 1959 belohnt, als sein Gut zum Cru Classé des Gebiets Graves ernannt wurde. Heute wird Château Pape Clément von Bernard Magrez geleitet und ist innerhalb der Magrez-Gruppe das Flaggschiff.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Pape_Cl%C3%A9ment"},"ch-Q1117166":{"n":"Schloss Haroué","c":"Burg in Frankreich","r":"Das Schloss Haroué, auch Château de Craon genannt, ist ein Schloss aus dem 18. Jahrhundert in einem kleinen Tal in der Mitte des französischen Dorfes Haroué im Saintois, südlich von Nancy. Es wurde zwischen 1720 und 1729 von Germain Boffrand für Marc de Beauvau, Connétable von Lothringen und später Vizekönig der Toskana, erbaut.","w":"https://de.wikipedia.org/wiki/Schloss_Harou%C3%A9"},"ch-Q1090652":{"n":"Château Rauzan-Ségla","c":"Schloss in Frankreich","r":"Château Rauzan-Ségla ist ein Deuxième Cru Classé im Weinbaugebiet Margaux im Bordeaux. Das Gut umfasst eine Größe von 66 Hektar, wovon 52 ha mit Reben bestockt sind.","h":"Am 7. September 1661 erwarb Pierre des Mesures de Rausan, ein bedeutender Händler der Region, das Weingut von der Familie de Gassies. Die Familie de Gassies stand den Lehnsherren der Seigneurie de Margaux nah. Dieses Weingut war der Ursprung der heute bekannten Château Rauzan-Gassies, Château Rauzan-Ségla, Château Desmirail und Château Marquis de Terme. Pierre des Mesures de Rausan war auch Pächter von Château Margaux (seit 1661) und Château Latour (seit 1679). Aus dieser Zeit stammt auch der jetzt noch existierende Weinkeller. Als Pierre des Mesures de Rausan am 10. Mai 1692 starb, erbte seine Tochter Thérèse Rebflächen in Pauillac (die späteren Weingüter Château Pichon-Longueville-Baron und Château Pichon-Longueville-Comtesse de Lalande). Ihre 3 Brüder Simon, Jude-Jean und Simon-Jude verwalteten indes den Rozan Besitz in Margaux. Durch die Hochzeit von Fräulein Rauzan du Ribail mit Jean Desmirail sowie eines anderen Familienmitglieds mit Seigneur de Peguilhan wurden Château Desmirail und Château Marquis de Terme aus dem großen Margaux-Besitz der Brüder abgespalten. Die offizielle Trennung von Rauzan-Gassies und Rauzan-Ségla erfolgte am 24. April 1763. Die Urkunde wurde von Jean Baptiste de Rauzan (für den Ségla-Anteil) und Jean Roulier (für den Gassies-Anteil) unterzeichnet. Marie-Anne de Briet heiratete Philippe Simon de Rauzan (Jean-Baptiste’s Sohn), trennten sich jedoch 10 Jahre später. Mit Hilfe ihrer ehemaligen Schwiegereltern übernahm sie im Jahr 1778 die Leitung des Ségla-Anteils. Anlässlich eines Besuchs im Jahr 1787 in Bordeaux besichtigte der spätere US-Präsident Thomas Jefferson (1743–1826) das Weingut (Jefferson beschrieb das Gut unter dem Namen Rozan) und stufte es in die zweite Kategorie ein.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Rauzan-S%C3%A9gla"},"ch-Q1125842":{"n":"Schloss La Verrerie","c":"Schloss in Frankreich","r":"Das Schloss La Verrerie liegt in der Gemeinde Oizon im französischen Département Cher, in der Nähe von Aubigny-sur-Nère. Das Gebäude ist seit dem 27. Januar 1987 als Monument historique klassifiziert. Der Name „La Verrerie“ (Glas) taucht erst im 16. Jahrhundert auf und weist auf die Existenz einer kleinen Glasfabrik in der damaligen Zeit hin, die bis Anfang des 19. Jahrhunderts belegt ist.","h":"Im Jahr 1422 überließ Karl VII. die Grafschaft Aubigny dem Schotten John Stewart, Lord Darnley. Der König bedankte sich auf diese Weise für die im Rahmen der Auld Alliance zwischen Frankreich und Schottland im Hundertjährigen Krieg geleistete Unterstützung. John Stuarts Sohn Béraud ließ Ende des 15. Jahrhunderts das Schloss errichten. Die Nachkommen John von Darnleys bewohnten das Schloss bis zum Jahr 1670. Zu diesem Zeitpunkt wurde Karl II. von England, ein direkter Nachfahre John Stuarts, Erbe der Seigneurie. Aber Ludwig XIV. erkannte diese Erbfolge nicht an und unterstellte Aubigny der Krone. Allerdings stimmte er 1673 zu, das zum Herzogtum erhobene Aubigny einer der Mätressen Karls II. von England, Louise de Kérouaille, Herzogin von Portsmouth, zu überlassen. Nach dem Tod König Karls lebte Louise de Kérouaille bis zu ihrem Tod in La Verrerie. 1734 ging das Herzogtum Aubigny auf ihren und Karls II. Sohn, Charles Lennox, Herzog von Lennox und Richmond, über. Dessen Nachkommen hatten das Schloss bis zum Anfang des 19. Jahrhunderts in ihrem Besitz. 1842 erwarb der Graf Léonce de Vogüé das Anwesen für seine große Familie, die noch heute im Schloss wohnt. 1965 machte Graf Antoine de Vogüé das Schloss Besuchern zugänglich. Seine Frau eröffnete 1982 im Schloss einen Hotelbetrieb und richtet im Schlosspark einen Restaurantbetrieb im Cottage „maison d’hélène“ ein. Aktueller Besitzer des Zwölf-Zimmer-Hotels und des angeschlossenen Restaurants ist der Sohn des Ehepaares.","w":"https://de.wikipedia.org/wiki/Schloss_La_Verrerie_(Oizon)"},"ch-Q905650":{"n":"Schloss Oiron","c":"Kunstmuseum in Frankreich","r":"Das Schloss Oiron befindet sich in Oiron im Département Deux-Sèvres in den Regionen Poitou und Nouvelle-Aquitaine.","h":"Die Herrschaft Oiron gehörte zunächst einer lokalen Familie (vgl. Aimery d‘Oiron, Kanoniker an Saint-Laon de Thouars im 12. Jahrhundert), dann dem Haus Thouars (mindestens seit Vicomte Hugues II. († 1333) im Jahr 1325; die letzten Damen von Oiron aus dem Haus Thouars waren die beiden Schwestern Péronnelle († 1397) und Isabeau, Töchter von Louis de Thouars), und den Amboise (Isabeau hatte 1356 Ingelger d‘Amboise, den ältesten Sohn von Pierre I. d‘Amboise, geheiratet; dann ihre Söhne und Enkel Pierre II. († 1426) und Louis d’Amboise († 1469)). Doch schon 1446 verkaufte Louis d'Amboise Oiron für 7000 Écu an Pierre Bérart (Maître d’Hôtel du Roi, Trésorier de France, Seigneur de Chizé) und Jacques Charrier. Dann, im Jahr 1448, kaufte Jean de Xaincoins/Saincoins, Steuereinnehmer im Poitou, das Anwesen. Er war mit Jacques Cœur verbunden und fiel um 1449 in Ungnade, noch bevor der Argentier Karls VII. 1451 stürzte: zum Tode verurteilt, rettete er seinen Kopf, aber sein Besitz wurde von der Krone beschlagnahmt. Das Schloss Oiron ist das Werk der Familie Gouffier: Guillaume Gouffier († 1495) erhielt das Land 1449 von Karl VII. Er war in zweiter Ehe mit Philippine de Montmorency verheiratet, der Tochter von Jean II. de Montmorency und Tante des Connétable Anne de Montmorency. Sein Sohn Artus Gouffier de Boisy (1474–1519; Sohn von Philippine de Montmorency) folgte Karl VIII. und Ludwig XII. in die Italienischen Kriege, wodurch er das Land Caravaggio erhielt – ein Titel, der in Charles Perraults Der gestiefelte Kater zum Marquisat de Carabas wurde. Er interessierte sich für die Kunst dieses Landes und konnte mit dem Aufbau der bedeutenden Kunstsammlung der Familie beginnen. In dieser Zeit wurde ihm die Erziehung des zukünftigen Königs Franz I.","w":"https://de.wikipedia.org/wiki/Schloss_Oiron"},"ch-Q948136":{"n":"Burg Rambures","c":"Burg in Frankreich","r":"Die Burg Rambures in der gleichnamigen Ortschaft ist eine der seltenen gut erhaltenen Burganlagen des Mittelalters in Frankreich. Erbaut wurde sie im 15. Jahrhundert aus Ziegelstein und gilt als Meisterwerk der mittelalterlichen Verteidigungsarchitektur. Sie wurde mehrmals belagert, aber nie eingenommen. Ihre Außenmauern sind noch im Originalzustand erhalten. Die Anlage steht seit dem 23. Februar 1927 als Monument historique unter Denkmalschutz und ist die meistbesuchte Burg im Département Somme.","h":"Die Geschichte der Burg Rambures und ihrer Besitzer ist eng mit der Geschichte des Hundertjährigen Krieges und der Eroberung der Picardie durch den Herzog von Burgund verbunden. David de Rambures fand mit dreien seiner Söhne in der Schlacht von Azincourt 1415 den Tod und wird als Lord Rambures sogar in Shakespeares Drama Heinrich V. erwähnt. Die Schlacht überlebte allein André de Rambures (um 1395–1449), der mit dem Dauphin, dem späteren Karl VII., weiterhin die Engländer bekämpfte. Im Jahr 1423, drei Jahre nach dem Abkommen von Troyes, eroberte Philipp der Gute, Herzog von Burgund, mit Hilfe der Engländer die Burg Rambures. André de Rambures wurde 1430 nach der erfolgreichen Belagerung Aumales durch den Grafen von Suffolk als Hauptmann der dortigen Burg gefangen genommen. Er blieb zehn Jahre in der Gefangenschaft der Engländer, die er in England verbrachte. Während dieser Zeit eroberte Charles Desmarets, ein militärischer Befehlshaber des Königs von Frankreich, die Burg Rambures von den Engländern zurück und machte sie zur Ausgangsbasis für weitere Angriffe auf die Engländer in Dieppe. Gegen Lösegeld kam André de Rambures 1440 aus englischer Gefangenschaft frei und beteiligte sich weiterhin am Kampf gegen die Engländer. Die Burg in ihrer heutigen Form entstand zur Zeit André de Rambures’ und seines Sohnes Jacques, der 1461 von Ludwig XI. zum Sprecher bei Karl dem Kühnen ernannt wurde. Die Fertigstellung der Anlage wird auf 1470 datiert. 1472 unterwarf sich Jacques de Rambures dem burgundischen Herzog Karl, der drei Monate in Rambures verweilte. Die Herrschaft Rambures wurde durch Erbe und Heirat seit dem 11. Jahrhundert unter den Nachfahren der Familie de Rambures weitergereicht. Die Liste der Besitzer von Rambures lautet wie folgt: Seigneurs de Rambures Asson (11.","w":"https://de.wikipedia.org/wiki/Burg_Rambures"},"ch-Q992215":{"n":"Burg Landskron","c":"Burgruine im Oberelsass, Frankreich","r":"Die Ruine der Burg Landskron steht im Oberelsass auf dem Landskronberg an der Schweizer Grenze in der französischen Gemeinde Leymen.","h":"1273 hatte das Interregnum im Heiligen Römischen Reich mit der Wahl des Habsburger Grafen Rudolf zum römisch-deutschen König geendet. Mit seiner Wahl beendete Rudolf seine Fehde gegen den Bischof von Basel, Heinrich von Neuenburg. In dieser Fehde standen die Edelfreien von Rötteln und die Münch im Lager der Adelsgesellschaft der Psitticher, die den Bischof unterstützte. Die Vitztum gehörten zur Adelsgesellschaft der Sterner, die den Habsburger unterstützte, die Stellung der Grafen von Pfirt ist umstritten. Nach der Wahl Rudolfs zum deutschen König wurde Otto von Rötteln dessen Gefolgsmann. Als Rudolf starb, wählten die Kurfürsten nicht dessen Sohn, Albrecht zum König, sondern Adolf von Nassau. Als Adolf 1298 wieder abgesetzt worden war, wurde Albrecht am 23. Juni 1298 als sein Nachfolger zum deutschen König gewählt. In der Ritterschlacht von Göllheim (Schlacht am Hasenbühel) am 2. Juli 1298 fiel Adolf im Kampf gegen den Habsburger. Am 27. Juli 1298 wurde Albrecht ein zweites Mal gewählt und dann am 24. August 1298 in Aachen zum König gekrönt. Otto von Rötteln unterstützte Albrecht in seinem Kampf gegen Adolf von Nassau, und einer aus dem Geschlecht der Münch fiel in der Schlacht von Göllheim für Albrecht. Die Grafen von Pfirt und die Vitztum standen dagegen auf der Seite Adolfs. Der Röttler erhielt von König Albrecht unter anderem die Ämter des Burggrafen von Rheinfelden und des Reichsvogtes von Basel. 1297 beabsichtigten sowohl die Vitztum als auch die Münch auf dem Landskronberg eine Burg zu errichten und es kam zur Fehde zwischen den beiden Geschlechtern. Die Brüder und Ritter Burkard und Bertold Vitztum von Basel übergaben zu Ostern 1297 ihr Eigentum, das Burgstall ob Rheineck im Leimtal und den Berg Horn ob Rheineck, mit allen Rechten dem Grafen Tiebalt von Pfirt.","w":"https://de.wikipedia.org/wiki/Burg_Landskron_(Oberelsass)"},"ch-Q951768":{"n":"Schloss Vizille","c":"Schloss in Frankreich","r":"Das Schloss Vizille ist eines der bedeutendsten und prestigereichsten Schlösser der Dauphiné, dem traditionellen Stammland des französischen Thronfolgers bis zur Französischen Revolution. Es steht in der Gemeinde Vizille im Département Isère.","w":"https://de.wikipedia.org/wiki/Schloss_Vizille"},"ch-Q1011019":{"n":"Burg Bilstein","c":"Burgruine im Elsass","r":"Die Burg Bilstein ist eine bei Riquewihr im Elsass gelegene Ruine einer Spornburg. Sie liegt westlich von Ribeauvillé in den Vogesen auf dem 757 Meter hohen Gipfelkamm des Schlossbergs. Um sie von der nahe gelegenen gleichnamigen, früher lothringischen Burg Bilstein bei Urbeis (Bilstein lorrain) zu unterscheiden, wird sie auch Bilstein-Aubure oder Bilstein alsacien genannt.","h":"Das genaue Gründungsdatum der Burg ist nicht bekannt. Bergfried und Mantelmauer wurden spätestens zu Beginn des 13. Jahrhunderts errichtet, stammen aber möglicherweise schon aus dem 12. Jahrhundert. In der Chronik Gesta Senoniensis ecclesiae des Mönchs Richer von Senones zum Jahr 1217 wird die Burg erwähnt. In jenem Jahr flüchtete sich der im Jahr 1206 abgesetzte Elekt von Toul, Mathieu de Lorraine, vor dem Zorn seines Neffen, des lothringischen Herzogs Theobald I., auf die Burg Bilstein. Mathieu hatte seinem bischöflichen Nachfolger Rainald von Senlis auflauern lassen, und in dem sich daraufhin entwickelnden Kampf war Rainald tödlich verletzt worden. Richer erwähnt in seinen Aufzeichnungen, dass sich die Burg zu jener Zeit im Besitz der Herren von Horburg befunden hat. Später war die Anlage ein Lehen der Herzöge von Lothringen, die sie gemeinsam mit der dazugehörigen Herrschaft Riquewihr wieder an die Horburger gaben, die auch schon im Besitz der benachbarten Burg Reichenstein waren. 1324 verkauften die seinerzeit kinderlosen Brüder Walther und Burchhard von Horburg die Besitzungen an ihren Onkel mütterlicherseits, den nachmaligen Grafen Ulrich III. von Württemberg. Das Haus Württemberg ließ die Anlage durch einen Burgvogt verwalten, der zugleich auch das Amt des Oberforstmeisters bekleidete. Die Burg wurde somit auch als Forsthaus genutzt. Der Bergfried diente bis ins Jahr 1489 zudem als Gefängnis. Noch im 14. Jahrhundert ließen die Württemberger die Burg umbauen und erweitern. Der Hocheingang des Bergfrieds stammt ebenso aus dieser Zeit wie die heute erhaltenen Reste der doppelten Ringmauer im Süden des Burgareals.","w":"https://de.wikipedia.org/wiki/Burg_Bilstein_(Haut-Rhin)"},"ch-Q1011203":{"n":"Burg Brie-Comte-Robert","c":"Burg in Frankreich","r":"Die Burg von Brie-Comte-Robert, einer französischen Gemeinde im Département Seine-et-Marne in der Region Île-de-France, wurde Ende des 12. Jahrhunderts errichtet. Sie ist die Ruine einer Wasserburg und seit 1925 ein geschütztes Baudenkmal.","h":"Im Jahr 1152 erhielt Robert I., Comte de Dreux, als Apanage von seinem Vater Ludwig VI. Dreux und Brie-Comte-Robert. Er ließ die rechteckige Burg errichten, die eine gleiche Seitenlänge von jeweils 55 Metern besitzt. Sie ist von einem Wassergraben umgeben und war mit vier Ecktürmen und vier weiteren Türmen an den Zugängen und an der Ost- und Westmauer versehen (siehe Rekonstruktionszeichnung). Im 14. Jahrhundert lebte Johanna von Évreux, die Witwe von Karl IV., in der Burg, wo sie 1371 starb. Sie ließ die Burg vergrößern und im Turm Saint-Jean eine Kapelle einrichten. Danach wohnte Louis de Valois, der Bruder des französischen Königs Karl VI., in der Burg. Während des Hundertjährigen Krieges wurde die Burg mehrmals von den Engländern belagert und eingenommen. Ab dem 15. Jahrhundert wohnten verdiente Adelige in der Burg, die zur Krondomäne gehörte. Im 18. Jahrhundert wurde die Burg nur noch teilweise genutzt und verfiel immer mehr. Nachdem im 19. Jahrhundert in der Burg moderne Einbauten errichtet wurden, kaufte die Gemeinde 1923 das gesamte Anwesen und der Staat stellte es unter Denkmalschutz.","w":"https://de.wikipedia.org/wiki/Burg_Brie-Comte-Robert"},"ch-Q1011343":{"n":"Burg Castelbouc","c":"Burg in Frankreich","r":"Die Burg Castelbouc ist die Ruine einer Felsenburg in der französischen Gemeinde Sainte-Enimie im Département Lozère der Region Okzitanien. Sie liegt im zugehörigen kleinen Dorf Castelbouc in den Gorges du Tarn und überragt sowohl die Ansiedlung als auch den passierenden Fluss durch ihre Positionierung auf einem exponierten Felsen.","h":"Erstmalige Erwähnung fand die Burg im 12. Jahrhundert, als sie sich im Besitz von Etienne de Castelbouc, einem Vasallen von Elie de Montbrun, befand. Letzterer war Kommandant des Templerordens in Larzac. In der zweiten Hälfte des 16. Jahrhunderts beschlossen die einzelnen Baronien des Gévaudan die Zerstörung zahlreicher Schlösser und Burgen in der Region – mutmaßlich, damit sich im Zuge der Hugenottenkriege flüchtende Protestanten dort nicht verstecken konnten. 1592 wurde auch die Burg Castelbouc geschleift.","w":"https://de.wikipedia.org/wiki/Burg_Castelbouc"},"ch-Q1011407":{"n":"Burg Culan","c":"Burg in Frankreich"},"ch-Q1405143":{"n":"Château de Ham","c":"Schloss"},"ch-Q1633116":{"n":"Schloss Guermantes","c":"Schloss in Frankreich","r":"Das Schloss Guermantes ist eine französische Schlossanlage in Guermantes im Département Seine-et-Marne, Region Île-de-France. Der barocke Bau, der nur zwei Kilometer von Eurodisney entfernt liegt, ist seit dem 9. August 1944 ein französisches Kulturdenkmal.","h":"Die Herrschaft hieß ursprünglich Le Chemin (der Weg, lateinisch via) und gehörte im Mittelalter einer Adelsfamilie, die sich nach ihr du Chemin benannte. In einer Urkunde der Pariser Abtei Sainte-Geneviève aus dem 14. Jahrhundert werden die dortigen Ländereien auch als „in via de Guermant“ bezeichnet. Durch die Heirat der Witwe Jacqueline du Chemin kam der Besitz 1362 an den königlichen Sekretär Pierre Blanchet. Zwanzig Jahre später war die Herrschaft aufgeteilt, ein Teil kam an die Abtei Malnoue, ein Teil an den Schildknappen Jean Motelin, der Hauptteil vermutlich an den Knappen Etienne Boulart, der 1397 in der Kirche von Guermantes bestattet wurde. Im 15. Jahrhundert gehörten die Lehen Le Chemin und Roquemont dem Advokaten und Rat des Parlement (1477) Pierre Poignant, der auch die Herrschaften Athis, Aigremont, Tillières und Archères besaß. Erbin von Le Chemin wurde eine seiner Schwestern, die den Rechnungskammerrat Nicolas Viole geheiratet hatte. Der 1638 verstorbene Claude Viole ließ das Schloss im Stil des Frühbarock errichten. Als Claude Violes Sohn Pierre († 1667), einstiger Präsident des Parlement de Paris, zum Seigneur de Guermantes ci-devant Le Chemin (Herr von Guermantes, zuvor Le Chemin) erhoben wurde, kam auch das Gut einschließlich des darauf befindlichen Dorfes endgültig zu seinem offiziellen Namen Guermantes. Im Jahre 1698 wurde das Anwesen von Paulin Pondre (1650–1723), der als Steuereintreiber von Lyon zu einem der einflussreichsten Financier zur Zeit Ludwigs XIV. aufgestiegen war, erworben. Er berief Jules Hardouin-Mansart für die Restaurierung des Gebäudes, die im Jahre 1710 abgeschlossen wurde. André Le Nôtre unterstand die Gestaltung des Parks. Damit prägten die Baumeister von Schloss Versailles auch diesen kleinen Landsitz.","w":"https://de.wikipedia.org/wiki/Schloss_Guermantes"},"ch-Q2242004":{"n":"Schloss La Possonnière","c":"Schloss in Frankreich","r":"Das Schloss La Possonnière, auch Schloss Ronsard genannt, gehört zur französischen Gemeinde Vallée-de-Ronsard im Département Loir-et-Cher. Es gehört zu den kleineren Schlössern der Loire und steht schon seit 1862 als Monument historique unter Denkmalschutz.","h":"Anfang des 16. Jahrhunderts kehrte Louis de Ronsard, der Vater des Dichters Pierre de Ronsard, aus dem Italienfeldzug zurück. Die Eindrücke, die die italienische Renaissance-Architektur bei ihm hinterlassen hatte, waren so nachhaltig, dass er als einer der ersten in Frankreich beschloss, seinen Landsitz in diesem Stil umzubauen. Die um 1510 durchgeführten Veränderungen sind deutlich zu erkennen, obwohl dabei nur Zwischenwände versetzt sowie Laibungen und Kamine umgestaltet wurden. Das verwendete originelle Dekor stellt eine Mischung gotischer und italianisierender Formen dar und ist damit Teil der Ornamentik der frühen französischen Renaissance. Die Kreuzstockfenster im Untergeschoss der Vorderfront des Herrenhauses stammen aus der Zeit Ludwigs XII., im Obergeschoss haben sie zum Teil Renaissance-Rahmungen. An vielen der Fenster fallen die angebrachten lateinischen Inschriften ins Auge. Das vorspringende Treppentürmchen auf der Rückseite des Gebäudes hat ein elegantes Portal mit Frontispiz und Büste. Oben am Türmchen ist auf dem Giebel des Dacherkers das Wappen der Ronsard zu erkennen: „In Blau drei silberne Fische“. Zwischen Wohntrakt und zwei in derselben Flucht liegenden großen Scheunen befindet sich ein Durchgang, der die beiden Höfe klar trennt. Die Wirtschaftsgebäude sind teilweise in den Hang hinter dem Hof gegraben. Der 1524 auf Schloss La Possonnière geborene Pierre de Ronsard verbrachte hier seine Kindheit.","w":"https://de.wikipedia.org/wiki/Schloss_La_Possonni%C3%A8re"},"ch-Q2242009":{"n":"Schloss La Motte-Tilly","c":"Schloss in Frankreich","r":"Das Schloss La Motte-Tilly steht südöstlich von Paris im gleichnamigen Ort La Motte-Tilly nahe der Gemeinde Nogent-sur-Seine. Das Anwesen kann besichtigt werden.","h":"La Motte-Tilly wurde 1748 von den Gebrüdern Terray erworben. Der ältere, Abbé Joseph Marie Terray, wurde 1769 zum letzten Steueraufseher Ludwigs XV. ernannt. 1755 begannen die Brüder, das bisherige herrschaftliche Gebäude auf den Anhöhen oberhalb der Seine abzureißen und ein Schloss zu errichten. Architekt war François Nicolas Lancret. Während der Französischen Revolution wurde es teilweise zerstört. 1910 erwarb der Graf von Rohan-Chabot das Anwesen und restaurierte es. Den Park ließ er nach französischem Vorbild umgestalten. Seine Tochter, die Marquise von Maillé, vollendete das Werk mit der Möblierung und Innenausstattung. Da sie keine Erben hatte, vermachte sie ihr Lebenswerk dem französischen Denkmalschutzamt. Der durch seine ausgewogenen Proportionen bestechende Bau aus Sandstein und Ziegeln besitzt ein hohes Schieferdach. Die Terrassen an der Nordfassade fallen sanft gestuft zu einem großen Wasserspiegel hinab, der durch zwei Arme mit der Seine verbunden ist. 1985 wurden im Schloss Szenen der deutsch-schweizerische Fernsehserie Ich, Christian Hahn gedreht. Einige Jahre später diente das Feldschloss dem Filmregisseur Miloš Forman als Drehort für Szenen seines Films Valmont, der 1989 in den Kinos kam.","w":"https://de.wikipedia.org/wiki/Schloss_La_Motte-Tilly"},"ch-Q2242114":{"n":"Schloss Le Champ de Bataille","c":"Schloss in Frankreich","r":"Das Schloss Le Champ-de-Bataille steht zwischen Le Neubourg und Sainte-Opportune-du-Bosc im Département Eure in der Normandie im Norden Frankreichs, inmitten der sogenannten Campagne du Neubourg, die im Westen durch den Fluss Risle und im Osten durch den Fluss Iton begrenzt wird.","h":"Bernhard der Däne gilt als der Stammvater des Hauses Harcourt, er war ein Gefolgsmann von Wilhelm Langschwert, dem Sohn Rollos. Viele Quellen behaupten, dass er an der Schlacht bei Sainte-Opportune-du-Bosc teilnahm, in der 935 Wilhelm Langschwert gegen Robert den Dänen kämpfte und die Champ-de-Bataille seinen Namen gab. Das ist jedoch historisch unwahrscheinlich, da Robert der Däne 1037 gestorben ist und somit 935 entweder sehr jung oder aber insgesamt weit über 100 Jahre alt geworden wäre. Deshalb gehen andere Quellen davon aus, dass diese Legende erfunden wurde und der Platz Champ-de-Bataille heißt, weil er einmal einem Herrn namens Bataille gehört hat. Als die Mitglieder der Fronde 1650 von Jules Mazarin verhaftet oder in die Provinz geschickt wurden, war Graf Alexandre von Créquy-Bernieulle (1628–1703), einer der Freunde des Fürsten von Condé die in die Provinz geschickt wurden. Er ließ das Schloss Le Champ-de-Bataille zwischen 1653 und 1665 erbauen. Nach dem Tode von Alexandre von Créquy-Bernieulle erbte dessen Neffe Gabriel-René, Marquis von Mailloc das Schloss. Er heiratete im Juli 1720 Claude-Lydie d’Harcourt, und nach seinem Tod 1724 fiel das Anwesen an seinen Neffen Anne-François d’Harcourt, Herzog von Beuvron (1727–1797). Während der Französischen Revolution wurde das Schloss geplündert. 1802 war das Schloss noch im Besitz des Zweiges Beuvron der Familie Harcourt. Thomas Thornton schrieb damals über das Schloss, es sei schön und es sei ihm zum Kauf angeboten worden, aber es habe keine Wasserversorgung und deshalb wolle er es nicht. 1805 wurde es verkauft. 1903 wurde es vom Grafen Harcourt, dem direkten Nachfahren des Herzogs von Beuvron zurückgekauft. 1936 wurde es schon wieder verkauft und als Waisenhaus genutzt.","w":"https://de.wikipedia.org/wiki/Schloss_Le_Champ-de-Bataille"},"ch-Q1648101":{"n":"Schloss Brézé","c":"Schloss in Frankreich","r":"Schloss Brézé ist ein Schloss nahe der ehemaligen Gemeinde Brézé im französischen Département Maine-et-Loire.","w":"https://de.wikipedia.org/wiki/Schloss_Br%C3%A9z%C3%A9"},"ch-Q1670612":{"n":"Rohan-Schloss","c":"Schloss in Zabern (frz.: Saverne) im Elsass, Frankreich","r":"Das Rohan-Schloss ist ein klassizistischer und historistischer Monumentalbau in Zabern im Elsass mit einer 140 Meter breiten Parkfassade aus rotem Vogesensandstein.","h":"Zabern gehörte zum Hochstift Straßburg, dessen „Hauptstadt“ es war und dessen Landesherr, der Bischof von Straßburg, aufgrund der politischen Rivalitäten zwischen ihm und dem Bürgertum der Stadt Straßburg ab dem 13. Jahrhundert oft hier residierte. Die damalige Residenz, eine mittelalterliche Burg, bezog die nördliche Ecke des ehemaligen römischen Kastells mit ein. Über diese Anlage ist wenig bekannt, da sie bereits Anfang des 15. Jahrhunderts durch das „Oberschloss“ an anderer Stelle, in unmittelbarer Nähe des Stiftskirche Notre-Dame-de-la-Nativité, ersetzt wurde. Unter Bischof Albrecht von Pfalz-Mosbach (1478–1506) wurde diese Residenz weiter ausgebaut. In einer nächsten Bauphase entstand ein Renaissance-Schloss, das im Bauernkrieg 1525 schwer beschädigt und anschließend wieder aufgebaut wurde. Anfang des 17. Jahrhunderts wurde das Gebäude längere Zeit von den Bischöfen nicht genutzt und gepflegt. Hinzu kamen zwei Belagerungen der Stadt während des Dreißigjährigen Kriegs 1622 und 1636. Was Bischof Franz Egon von Fürstenberg-Heiligenberg (1663–1682) dann vorfand, ließ er abreißen und von 1667 bis 1670 durch eine Vier-Flügel-Anlage auf annähernd quadratischem Grundriss ersetzen. Kaum war das fertiggestellt, begeisterte sich der Bischof für eine Erweiterung: Der nordöstliche Flügel des Gebäude-Karrees wurde durch einen 110 m langen neuen Flügel ersetzt, der im Südosten weit über den quadratischen Grundriss des Schlosses hinausragte. Der Architekt ist nicht bekannt. An der Ausstattung waren beteiligt Antoine Coysevox und Claude Audran der Jüngere. Auch die ersten der vier im 18. Jahrhundert aufeinander folgenden Bischöfe aus der Familie Rohan Armand I. Gaston Maximilien de Rohan-Soubise (1704–1749) Armand II.","w":"https://de.wikipedia.org/wiki/Rohan-Schloss"},"ch-Q2240222":{"n":"Schloss Beaumesnil","c":"Schloss in Frankreich","r":"Das Schloss Beaumesnil wurde in Beaumesnil von 1631 bis 1640 im Barockstil Louis XIII. erbaut. Es ist als Monument historique klassifiziert. Zu dem Schloss gehört ein 50 Hektar großer Park mit einer Gartenanlage à la française. In dem möblierten Schloss befindet sich ein Buchbindereimuseum.","h":"Jacques le Conte, Marquis de Nonant und Baron de Beaumesnil, ließ das Schloss für seine Frau Marie Dauvet Desmaret auf dem Platz einer mittelalterlichen Motte erbauen. Die Burg war etwa um 1250 von Richard d’Harcourt gegründet worden. Teile des mit Buchsbaum bedeckten Donjons existieren immer noch. Marie Dauvet Desmaret war die Enkelin von Nicolas Brûlart de Sillery (1544–1624), der Kanzler von Frankreich gewesen war. Sie setzte nach dem Tod ihres Mannes die Bauarbeiten fort. Am Bau wirkten 1631 Martin und Toussaint Laflèche mit, zwei Maurermeister aus Feucherolles (im Département Yvelines), die nach Zeichnungen des Marquis de Nonant arbeiteten. Ebenfalls 1631 verrichtete der Zimmerer Jean Loiseau sämtliche Zimmerarbeiten am Mauerwerk und fertigte die Fußböden. Der Maurermeister Jean Gaillard aus Rouen ließ im selben Jahr die Fassade auf der Hofseite errichten und leitete die Maurerarbeiten zu jener Zeit. Er ließ Baptiste Bastard und Jean Beauroulles, Maurermeister aus Saint-Pierre-de-Cernières, die Maurerarbeiten an der Terrassenseite verrichten. 1633 traf sich Jean Gaillard mit dem Marquis de Nonant, um die Größe der Steine im ersten Stock zu besprechen. 1638 wurde ein Dachdecker namens Gervais Lemarinier erwähnt. Jacques-François Leclerc Skulpteur und Brunnenbauer (Fontainier) hatte im Juni 1639 die Arbeiten an den Skulpturen noch nicht beendet. Der einzige Sohn Jacques Le Conte de Nonants starb 1654 im Alter von 20 Jahren. Seine Schwester Catherine erbte daraufhin Beaumesnil. Sie heiratete sechs Jahre später Hérard Bouton, Comte de Chamilly und Gouverneur von Dijon († 1672). Pferdestall und Kutschenschuppen wurden 1706 erbaut. Durch Heirat gelangte das Schloss in den Besitz der Familie Martel de Graville.","w":"https://de.wikipedia.org/wiki/Schloss_Beaumesnil"},"ch-Q2970156":{"c":"Burg in Frankreich"},"ch-Q2152653":{"n":"Schloss Campagne","c":"Schloss in Frankreich","r":"Das Schloss Campagne liegt in der Nähe der Vézère in der Ortschaft Campagne im Département Dordogne des französischen Périgord.","w":"https://de.wikipedia.org/wiki/Schloss_Campagne"},"ch-Q2968565":{"c":"Burg in Frankreich"},"ch-Q2968629":{"n":"Burg Bourbon-l’Archambault","c":"Burg in Frankreich","r":"Die Burg Bourbon-l’Archambault ist eine mehrfach umgebaute Festung aus dem 13. Jahrhundert in Bourbon-l’Archambault in Zentrum Frankreichs. Sie wurde 1862 als Monument historique eingestuft.","h":"Bereits in der Antike war die Gegend besiedelt, wobei sich die damalige Stadt Aquae Bormonis im Siedlungsgebiet der Biturigen befand. Ab dem 10. Jahrhundert war Bourbon-l’Archambault Sitz einer Viguerie in der Provinz Berry und wurde zur Hauptstadt der Region Bourbonnais. Die Herzöge von Bourbon nahmen den Namen ihrer Hauptstadt an und beließen ihr im Gegenzug den Namen Archambault oder Archambaud, den neun von ihnen zwischen dem zehnten und zwölften Jahrhundert trugen. Ein erstes Castrum in Bourbon wird in der Chronik von Frédégaire erwähnt, die von der Zerstörung durch Pippin den Jüngeren im Jahr 761 im Kampf mit dem Herzog von Aquitanien um den Besitz von Narbonne berichtet. Im Jahr 947 wurde erneut eine hölzerne Burg erwähnt. Diese Burg wurde durch die Herzöge von Bourbon erbaut. Diese Adligen bauten durch ein Bündnis mit Cluny ab dem 12. Jahrhundert ein wichtiges feudales Herzogtum an den Grenzen dreier großer Herrschaftsgebiete (Berry, Autunois, Auvergne) auf. Der Herr von Bourbon Aimon II. tritt in die direkte Vasallenschaft des französischen Königs Ludwig VI. ein. Dieses Bauwerk wurde mehrmals umgebaut und erweitert, ab dem 12. Jahrhundert dann aus Stein. Ein Mauerstück aus dieser Zeit ist in der Nähe des „Admiral Tower“ erhalten geblieben. Unter Philippe Auguste wurde die Burg erweitert und vermutlich von Archambaud VIII. von Bourbon in der ersten Hälfte des 13. Jahrhunderts mit runden Ecktürmen flankiert. Nachdem Mathilde I. von Bourbon Guy II. de Dampierre heiratete, geriet die Burg in den Besitz des Adelsgeschlechtes Dampierre. Zwischen dem 13. und 14. Jahrhundert wurde die Burg zu einer mächtigen Festung ausgebaut. Zu dieser Zeit bestand sie aus fünfzehn Türmen. Aus dieser Bauphase sind bis heute die runden Ecktürme erhalten.","w":"https://de.wikipedia.org/wiki/Burg_Bourbon-l%E2%80%99Archambault"},"ch-Q2969584":{"n":"Schloss La Rochefoucauld","c":"Schloss in Frankreich","r":"Das Schloss La Rochefoucauld in La Rochefoucauld im Département Charente ist ein Renaissanceschloss, das größtenteils um 1520 an der Stelle einer Burg errichtet wurde, deren erste Erwähnung aus dem Jahr 1026 stammt und von der die Türme erhalten geblieben sind.","h":"Im Jahr 1019 trat Foucauld, Seigneur de La Roche (1019/37 bezeugt), in einer Urkunde des Kopialbuchs des Klosters Uzerche auf: Er nahm zusammen mit seinen Söhnen, seiner Tochter Ava und seinem Schwiegersohn Aimery Ostafranc (1010/19 bezeugt), dem Stammvater der Familie Rochechouart, an einer Schenkung des Vicomte Adémar I. von Limoges (Haus Limoges) der Kirche von Nieuil an das Kloster Uzerche teil. In einem Dokument der Abtei Saint-Cybard in Angoulême aus dem Jahr 1026 wird Foucauld als sehr edler Herr der Burg La Roche bezeichnet: „vir nobilissimus Fulcaudus de castrum qui vocatur Rocha“. Dies ist die älteste bekannte Erwähnung des ehemaligen Burg, die heute nicht mehr existiert. Der Bau des Donjon ist zweifellos Foucauld zu verdanken. Er war damals 16 m hoch. Seine Mauern, die eine Fläche von 11,78 × 12,06 m einnehmen, haben eine Dicke zwischen 2,30 und 2,50 m. Sie sind mit flachen, 80 cm breiten Strebepfeilern in der Mitte der Seiten und in den Ecken versehen. Die Verbindungsfuge zwischen den beiden Bauabschnitten des Donjons ist auf der Innenseite der Burg noch sichtbar. Dieser Donjon ähnelt in seiner Struktur denen, die zur gleichen Zeit vom Grafen von Anjou, Fulko Nerra (972–1040), erbaut wurden: Langeais im Jahr 994, Loches um 1030. Der Donjon umfasste in seinem ursprünglichen Zustand zwei Stockwerke: ein erstes, etwa 10 m hohes Stockwerk ohne Fenster, dessen einziger Zugang eine Falltür im Gewölbe war; ein zweites, 5,40 m hohes Stockwerk, das als Wohnraum diente und über ein Fenster auf der Ostseite und eine Tür auf der Nordseite verfügte, jedoch zum Zeitpunkt der Errichtung keinen Kamin hatte. Um 1050 wurden die Güter der Vizegrafschaft Limoges aufgeteilt. Die Nachkommen von Foucauld wurden wahrscheinlich zu dieser Zeit zu Herren der Burg La Roche.","w":"https://de.wikipedia.org/wiki/Schloss_La_Rochefoucauld"},"ch-Q2970867":{"c":"Burg in Frankreich"},"ch-Q2190858":{"c":"Burg in Frankreich"},"ch-Q2740328":{"n":"Burg Montbrun","c":"Burg in Frankreich","r":"Die Burg Monbrun ist eine im Gemeindegebiet von Dournazac gelegene Burg des 12. und 15. Jahrhunderts.","h":"Der Platz, auf dem jetzt die Burg steht, war seit dem 11. Jahrhundert besiedelt. Dies belegt eine hohe, direkt neben der heutigen Burg gelegene Motte. Pierre Brun, damaliger Herr von Montbrun, befehligte im Jahr 1199 zusammen mit dem Ritter Pierre Basile die Garnison von Châlus, als diese von Richard Löwenherz belagert wurde – der aber hierbei den Tod fand. Im 12. Jahrhundert wurde eine Burg aus Natursteinen errichtet, deren romanischer Donjon noch erhalten ist. Diese Anlage wurde niedergebrannt und später im 15. Jahrhundert fast vollständig wiederaufgebaut. Während der Französischen Revolution wurde die Burg eingenommen und geplündert, jedoch im folgenden 19. Jahrhundert erneut restauriert. Nach einem nochmaligen Brand im Jahr 1917 wurde die Burg dann von Grund auf wiederhergestellt. Seit 1995 wird sie Burganlage von dem Niederländer Maarten Joost Lamers bewohnt und steht seit 2009 zum Verkauf. Das Innere der Burg ist seit dem 20. September 1946 als Monument historique eingeschrieben, am 10. April 1990 folgten dann der Außenbereich mit den dazugehörigen Parzellen.","w":"https://de.wikipedia.org/wiki/Burg_Montbrun_(Dournazac)"},"ch-Q2744196":{"c":"Burg in Frankreich"},"ch-Q2856283":{"n":"Burg Alleuze","c":"Burg im Département Cantal, Frankreich","r":"Die Burg Alleuze ist eine mittelalterliche Burg, deren Geschichte bis ins 12. Jahrhundert zurückreicht. Sie befindet sich in der französischen Gemeinde Alleuze im Département Cantal in der Region Auvergne-Rhône-Alpes.","h":"Im 12. Jahrhundert war die Burg im Besitz von Béraud VIII de Mercœur, dem Herrn von Aubijoux und Alleuze. Später ging die Burg in den Besitz des Bischofs von Clermont über. Zu dieser Zeit diente die Burg als ein Vorposten der Zitadelle von Saint-Flour. Der Vorgängerbau der heutigen Burg entstand zwischen 1267 und 1285. Während des Hundertjährigen Krieges, 1383, wurde die Burg durch Bernard de Galan, der aus der Bretagne kam, jedoch auf der Seite der Engländer stand, erobert. Die Garnison bestand nur aus drei Männern. Galan soll Schrecken in der ganzen Region verbreitet haben und nur durch das Freikaufen gelang es, ihn zu vertreiben. Verhandelt wurde das Freikaufen 1390 durch Jean de Blaisy im Namen von Karl VI. von Frankreich. Um zu verhindern, dass das Schloss erneut von den Engländern eingenommen wurde, brannten es die Einwohner von Saint-Flour 1405 nieder. Nach einigen Gerichtsprozessen zwang Monsignore de la Tour, der damalige Besitzer des Schlosses, die Einwohner von Saint-Flour 1411, es wieder aufzubauen. Im Jahr 1536 wurde das Schloss restauriert. Die Türme der Burg wurden 1575 von den Hugenotten eingenommen und vom Bischof von Clermont als Gefängnis genutzt. Ende des 16. Jahrhunderts wurde die Burg dann vom Bischof von Clermont an Jean de Lastic-Sieujac verkauft. Schließlich wurde das Schloss an dessen Nachkommen vererbt, die das Schloss verfallen ließen, so dass es zur Ruine wurde.","w":"https://de.wikipedia.org/wiki/Burg_Alleuze"},"ch-Q2749729":{"n":"Burg Blain","c":"Burg im Département Loire-Atlantique, Frankreich","r":"Die Burg Blain oder Burg La Groulais ist eine mittelalterliche Festung, die im 13. Jahrhundert gebaut und im 16. Jahrhundert stark umgebaut wurde. Sie befindet sich in der Gemeinde Blain im französischen Département Loire-Atlantique. Zusammen mit den Städten und Burgen Vitré, Fougères, Châteaubriant, Ancenis und Clisson war sie Teil der bretonischen Grenzverteidigung.","h":"Die erste Burg wurde um 1108 im Auftrag von Alain IV., Herzog der Bretagne, errichtet. Durch Heirat ging die Festung 1225 an die Familie Clisson über. Nach dem Aufstand von Olivier I. de Clisson gegen den Herzog wurde die Burg 1260 geschleift. Der Sohn von Olivier I., Olivier II., erhielt vom Herzog die Erlaubnis, die Burg wiederaufzubauen. Die Clissons bauten die Burg im 14. Jahrhundert nach und nach aus. Im Jahr 1407 ging die Burg in den Besitz des Hauses Rohan über. Louis de Rohan-Chabot, Herzog von Rohan, wurde hier bestattet. Während der Hugenottenkriege wurde die Burg belagert und 1591 während der Kämpfe zwischen dem Herzog von Mercœur und Jean de Montauban, genannt Le Goust, in Brand gesetzt. Sie wurde von Catherine de Parthenay wiederhergestellt, die sich dort mit ihren Kindern niederließ. Nachdem Henri II., Herzog von Rohan, zum Anführer der protestantischen Fürsten geworden war, ordnete Kardinal Richelieu 1628 den Abriss der Befestigungsanlagen der Burg an, wodurch sie ihre militärische Bedeutung verlor. Weitere schwere Schäden erlitt die Burg während der Französischen Revolution. Sie wurde geplündert und niedergebrannt, ebenso wie das Archiv der Familie Rohan. Sie diente danach als Kaserne und später als Gefängnis. Die Burg ging in die Hände mehrerer Besitzer über, darunter auch Marie Bonaparte im Jahr 1918. Diese Besitzer bauten den Nordflügel (Logis du Roy) und den Mühlenturm (Tour du Moulin) um.","w":"https://de.wikipedia.org/wiki/Burg_Blain"},"ch-Q2243758":{"n":"Schloss Tournon","c":"Schloss in Frankreich","r":"Im Schloss Tournon in Tournon-sur-Rhône starb im Jahr 1536 der französische Thronfolger François de France, Dauphin von Viennois und Herzog von Bretagne. Es beherbergt heute ein Museum und steht teilweise unter Denkmalschutz.","h":"Spuren einer ersten Burg, die der Nachfolger eines Wachtturms aus gallorömischer Zeit war, stammen aus dem 10. Jahrhundert. Sie sind noch rechts vom Eingang des heutigen Ehrenhofs zu sehen. Die Burg wurde von den Königen Frankreichs genutzt, um auf ihren Reisen zu übernachten. Ludwig IX. hielt sich hier auf, als er zum Kreuzzug aufbrach, Franz I. und Heinrich II. machten auf dem Weg zu den Kriegen in Italien in Tournon Station. Herzog Franz III. von Bretagne, der älteste Sohn des Königs Franz I. und Bruder Heinrichs II., starb am 10. August 1536 auf Schloss Tournon, nachdem er ein Glas Wasser getrunken hatte. Graf Montecuccoli, der Sekretär des Herzogs, wurde angeklagt, im Dienst Kaiser Karls V. gestanden zu haben, denn bei einer Durchsuchung seines Quartiers wurden verschiedene Gifte gefunden. Unter der Folter gestand Montecuccoli die Ermordung des Herzogs. In der modernen Wissenschaft ist die These vom Gifttod jedoch umstritten. Im 16. Jahrhundert wurden neben einer Kapelle neue Wohnräume im Renaissancestil angebaut, darunter die Gebäude, die heute ein Museum beherbergen. Des Weiteren ist im Schloss das nachgebaute Zimmer der Hélène de Tournon zu sehen, die aus Liebeskummer starb. Pierre de Ronsard, der dies als zwölfjähriger Page miterlebte, schrieb für sie später seine Ode à Hélène.","w":"https://de.wikipedia.org/wiki/Schloss_Tournon"},"ch-Q2941212":{"n":"Schloss Ételan","c":"Schloss in Frankreich","r":"Das Schloss Ételan ist eine Schlossanlage in der nordfranzösischen Gemeinde Saint-Maurice-d’Ételan etwa sechs Kilometer südöstlich von Lillebonne in der Region Normandie. Das Hauptgebäude stammt vom Ende des 15. Jahrhunderts und war eines der ersten Gebäude in der Normandie, das teilweise im Stil der Renaissance errichtet wurde.","h":"Im 14. Jahrhundert stand am Ort des heutigen Schlosses eine befestigte Burg, deren erster bekannter Eigentümer Pierre Picart dʼE(s)telan war. 1383 gehörte sie Guillaume Picart dʼE(s)telan. Für das Jahr 1475 ist überliefert, dass der damalige Burgherr, der ebenfalls Guillaume Picart hieß, dort den französischen König Ludwig XI. empfing. Dieser gab noch im 15. Jahrhundert aus unbekanntem Grund den Befehl, die Anlage niederzulegen. Guillaumes Sohn Louis war ein Freund des Kardinals Georges d’Amboise und Rat sowie Kammerherr Ludwigs XII. Als dieser 1494 noch Herzog von Orléans war, gab er Louis de Picart 700 Livres tournois, damit er sich ein neues Schloss errichten konnte. Die Arbeiten daran dauerten bis zum Jahr 1514. Louis vermachte den Neubau seinem Sohn François, dessen Tochter Madelaine Jean dʼEsquetot heiratete und das Schloss ihrer gemeinsamen Tochter Charlotte hinterließ. Diese brachte den Besitz in die Ehe mit dem Marschall Charles I. de Cossé. Er empfing im August 1563 auf seinem Schloss die Regentin Katharina von Medici samt ihrer Entourage, darunter ihr seinerzeit noch unmündiger Sohn Karl IX. und dessen Bruder Heinrich sowie seine Schwester Margarete und der mit dem Königshaus verwandte Heinrich von Navarra. In jenen Tagen hielten sich damit vier künftige Könige und Königinnen von Frankreich im Schloss auf. Aus Charlottes und Charlesʼ Ehe ging neben zwei Söhnen die Tochter Jeanne hervor, die im Februar 1578 François d’Espinay de Saint-Luc heiratete und das Schloss an dessen Familie brachte. Für ihren Mann wurde Ételan zur Grafschaft erhoben. Durch den Tod François III. dʼEspinay de Saint-Lucs im Jahr 1694 erbte sein einziges Kind aus der Ehe mit Marie de Pompadour, die Tochter Marie Anne Henriette, den Besitz.","w":"https://de.wikipedia.org/wiki/Schloss_%C3%89telan"},"ch-Q2970324":{"n":"Schloss Puyguilhem","c":"Schloss in Frankreich","r":"Das Schloss Puyguilhem liegt in der Nähe der Gemeinde Villars im Département Dordogne des französischen Périgords. Das Renaissanceschloss wurde Anfang des 16. Jahrhunderts errichtet und weist die gleichen baulichen Merkmale auf wie die Loire-Schlösser aus der Zeit Franz I. Das Schloss wird seit 1881 mit einer kurzen Unterbrechung in der Liste der historischen Baudenkmäler Frankreichs aufgeführt.","w":"https://de.wikipedia.org/wiki/Schloss_Puyguilhem"},"ch-Q2970406":{"n":"Schloss Rochechouart","c":"Burg in Frankreich","r":"Das Schloss Rochechouart oberhalb des Zusammenflusses von Graine und Vayres in der Gemeinde Rochechouart stammt aus dem 13. Jahrhundert und weist noch Teile aus dem 15. Jahrhundert auf. Die Familie der Vicomtes de Rochechouart aus dem Haus Rochechouart war bis zu seinem Verkauf an den französischen Staat im 19. Jahrhundert Eigentümer der Anlage. Das Schloss Rochechouart beherbergt heute das Museum für zeitgenössische Kunst des Département Haute-Vienne.","w":"https://de.wikipedia.org/wiki/Schloss_Rochechouart"},"ch-Q2968528":{"n":"Schloss Bellegarde (Loiret)","c":"Burg in Frankreich","r":"Das Schloss Bellegarde, auch Château des l'Hospital genannt, ist ein französisches Schloss, Sitz eines kurzlebigen Herzogtums Bellegarde (1646) und später des Marquisats Bellegarde. Es befindet sich in der Gemeinde Bellegarde im Département Loiret.","h":"Im 14. Jahrhundert, zwischen 1355 und 1376, ließ Nicolas Braque, Trésorier de France, den heutigen Donjon der Burg auf quadratischem Grundriss mit vier Erkertürmchen mit Kragbögen errichten. Die Fundamente des Bergfrieds scheinen jedoch aus dem 12. Jahrhundert zu stammen, wie drei Bogenelemente belegen (Erdgeschoss). Das Schloss der Familie L’Hospital (in weiblicher Linie von den Braques abstammend) verändert seine Physiognomie unter Heinrich IV. und Ludwig XIII. durch das Wirken von Jacques de L’Hospital (1578–1635; aus dem älteren Zweig der L’Hospital, während Marschall Nicolas aus dem jüngeren Zweig stammt), dem letzten Comte und ersten Marquis de Choisy-aux-Loges. Zu dieser Zeit zeichnete Claude Chastillon das Schloss und Dom Morin beschrieb es. Jacques de l’Hospital ließ insbesondere an den westlichen Donjon den Pavillon des Ondes anbauen, der eine schöne Treppe mit schmiedeeisernem Geländer erhielt. Im oberen Hof oder Ehrenhof (dem heutigen Cour d’Antin) befindet sich der von Jacques de L’Hospital errichtete Kapitänsturm, der zunächst einen Taubenschlag beherbergte. Er wurde dann von Chastillon (1564–1606) graviert. Unter Ludwig XV. wurde der Turm dann von Gautier, Sieur de Besigny, dem vorletzten Marquis de Bellegarde, zu einem Wohnhaus umgebaut. Der Ursprung seines Namens ist hier zu finden: Gauthier de Besigny soll in diesem Gebäude den Concierge untergebracht haben, den man damals Capitaine nannte. Roger II. de Saint-Lary erwarb Choisy und wurde 1646 Duc de Bellegarde in Choisy-aux-Loges (er war seit 1619 Duc de Bellegarde in Seurre). Im Laufe des 17. Jahrhunderts errichten die letzten L’Hospital zu einem unbekannten Zeitpunkt die Scheunen des unteren Hofes, deren strahlenförmige Backsteintüren noch erhalten sind.","w":"https://de.wikipedia.org/wiki/Schloss_Bellegarde_(Loiret)"},"ch-Q2968472":{"n":"Burg Beaufort (Goudet)","c":"Burg im Département Haute-Loire, Auvergne-Rhône-Alpes, Frankreich","r":"Die Burg Beaufort ist eine Burgruine mit zugehörigem Wohngebäude in Goudet im Département Haute-Loire in der Region Auvergne-Rhône-Alpes. Flussabwärts entlang der Loire ist es nach der Burg von Arlempdes die zweite Burg, auf die man trifft.","h":"Die Burg wurde um das Jahr 1200 errichtet. Sie wurde mehrfach belagert, insbesondere von den Engländern während des Hundertjährigen Krieges. In dieser Zeit sowie während der Hugenottenkriege spielte sie eine bedeutende militärische Rolle. Als Besitz der ehemaligen Herren von Beaufort liegt sie an den Ufern der Loire und des Bachs Fouragette. Sie erhebt sich auf einem Felssporn, der die vier Täler beherrscht. Dadurch standen sämtliche Zugangswege nach Goudet unter ihrer Kontrolle. Zu der Burg mit quadratischem Grundriss und einem Wohngebäude an der Südseite des Hofes ließ Antoine de la Tour im 16. Jahrhundert mehrere Ergänzungen vornehmen: einen massiven hufeisenförmigen Turm an der südwestlichen Ecke, einen Turm an der nordwestlichen Ecke sowie eine niedrige Vorbefestigung (Fausse-Braie) mit Eckturm. Der Turm war innen durch eine Verstärkungsmauer gesichert und mit Schießscharten für Pfeile und Feuerwaffen versehen. Das heute als Burg Goudet bekannte Bauwerk trug bis zur Französischen Revolution den Namen Burg Beaufort. Noch im 18. Jahrhundert bewohnte eine Dame von Beaufort dieses Anwesen, das Anfang des 19. Jahrhunderts zur Ruine wurde.","w":"https://de.wikipedia.org/wiki/Burg_Beaufort_(Goudet)"},"ch-Q2967937":{"c":"Schloss in Frankreich"},"ch-Q2968405":{"c":"Schloss in Frankreich"},"ch-Q2969067":{"c":"Schloss in Frankreich"},"ch-Q2969314":{"c":"Burg in Frankreich"},"ch-Q2969088":{"n":"Schloss Creully","c":"Schloss in Frankreich","r":"Das Schloss Creully steht in der gleichnamigen französischen Gemeinde, im Kanton Bayeux des Département Calvados, welches zur Region Normandie gehört.","h":"Die Anfänge des Schlosses reichen bis ins Jahr 1047 zurück. Zu dieser Zeit herrschte Haimo von Creully (französisch Hamon le Dentu) als starker Baron über Creully, Thaon, d'Evrecy und Torigni. Er war Mitanführer der Rebellion gegen seinen Lehnsherrn den jungen Wilhelm der Bastard, den späteren Wilhelm I. von England und fällt in der Schlacht von Val-ès-Dunes, die den Machterhalt Wilhelms sichert. Sein Nachfolger Robert Fitz Haimon errichtet eine Festung aus Stein. Durch Heirat seiner Tochter und Erbin Mabille wechselt das Schloss und Titel 1107 in die Hände von Robert von Caen, seinerseits Graf von Gloucester und illegitimer Sohn des englischen Königs Heinrich von Beauclerc. Sein Nachkomme Richard I. von Creully macht das Schloss zu seiner Hauptresidenz um 1147. Chreully wird als Wohnsitz im Stil eines Herrschers von hohem Rang im 12. Jahrhundert ausgebaut, zugehörig zu der damaligen Elite der normannischen Herrschaft über England. Diesen anglo-normannischen Stil findet man auch drei andren Stellen der Normandie nämlich in Beaumont-le-Richard, Bricquebec, und Barneville-la-Bertran. Bis 1682 war das Schloss im Besitz der gleichen Familie. Insgesamt residierten 22 Barone nacheinander in diesem Anwesen. Hochverschuldet verkaufte der letzte Baron von Creully, Antoine V Sillans sein Schloss an Jean-Baptiste Colbert, Finanzminister im Dienste von Ludwig dem XIV. Bis zur französischen Revolution blieb das Schloss im Besitz der Nachkommen Colberts. Danach wurde das Schloss konfisziert und anschließend Besitz reicher Eigentümer. Seit 1946 wurde das Hauptgebäude des Schlosses Besitz der Gemeinde Creully. Die Nebengebäude befinden sich in Privatbesitz.","w":"https://de.wikipedia.org/wiki/Schloss_Creully"},"ch-Q3077976":{"c":"Burg in Frankreich"},"ch-Q3078019":{"c":"Burg in Frankreich"},"ch-Q2176795":{"c":"Burg in Frankreich"},"ch-Q3146116":{"c":"Schloss in Frankreich"},"ch-Q2269885":{"c":"Burg in Frankreich"},"ch-Q2970802":{"c":"Burg in Frankreich"},"ch-Q1987156":{"c":"Burg in Frankreich"},"ch-Q2242266":{"n":"Schloss Losse","c":"Schloss in Frankreich","r":"Das Schloss Losse ist ein Bauwerk aus dem 16./17. Jahrhundert in der Nähe der Ortschaft Thonac im französischen Périgord. Schloss und Gärten wurden im Jahr 2007, mit Ausnahme des Bodens und einzelner Gebäude, als Monuments historiques anerkannt, was vorherige Anerkennungen ersetzte, die es seit dem Jahr 1928 mehrfach für Teile des Schlosses gegeben hatte.","h":"Die Familie von Losse kam im 11. Jahrhundert aus Flandern und errichtete am Fluss eine Zitadelle. Von dieser Zeit an gehörten die Familienmitglieder zur Feudalhierarchie und schworen später dem König von Frankreich ewige Treue. Jean II., der Marquis de Losse, war Soldat und seine unbedingte Loyalität zur Krone stärkte sowohl seine militärische als auch seine gesellschaftliche Position. Zuerst war er Page von Franz I., diente später allen Söhnen von Katharina von Medici und wurde schließlich Privatlehrer Heinrichs IV. Als überzeugter Katholik war Jean II. ein entschiedener Gegner des Hugenottengenerals Geoffroy de Vivans, und er musste sich in der Zeit der Religionskriege oft vor seinen Feinden verschanzen. Aus diesem Grund trägt das Renaissance-Schlösschen mit seinem Schutzgraben, seinen Mauern, Zinnen und Pechnasen sowie dem Wehrgang unterhalb des Dachansatzes ausgesprochen wehrhafte Züge. Am Ende seiner Karriere kehrte Jean II. de Losse als Gouverneur von Limousin und Guyenne in das Périgord zurück und begann, Schloss Losse im Geschmack der Zeit umzugestalten, bewahrte dabei aber dessen Nüchternheit als Landsitz. Ursprung des heutigen großen Renaissance-Wohntraktes war ein von ihm innerhalb der Festung errichteter Saalbau. Hinzu kam die Verbesserung der Verteidigungsanlagen des Schlosses in Hinblick auf den Gebrauch von Musketen und Kanonen. Das lässt sich an den verschiedenen Öffnungen in der Umfassungsmauer und der Barbakane nachvollziehen.","w":"https://de.wikipedia.org/wiki/Schloss_Losse"},"ch-Q2242322":{"n":"Schloss L’Herm","c":"Schloss in Frankreich","r":"Das Schloss L’Herm liegt in der französischen Gemeinde Rouffignac-Saint-Cernin-de-Reilhac im Département Dordogne. Die Ursprünge des Bauwerkes gehen auf den Anfang des 14. Jahrhunderts zurück. Die übrig gebliebene Ruine ist in letzter Zeit Gegenstand historischer und archäologischer Untersuchungen und steht inzwischen auch Besuchern offen. Seit 2018 hat der neue Besitzer erhebliche Renovierungsarbeiten durchgeführt.","h":"Genaue Angaben über die erste Befestigung fehlen. Burg und Wall mit darauf stehendem Bergfried wurden wahrscheinlich um 1300 errichtet. Dem Schutz dieser Baulichkeiten dienten 5 bis 6 m tiefe Gräben sowie in der ersten Zeit ein Holzzaun. Es wird davon ausgegangen, dass L’Herm anfänglich ein Lehnsgut und später Adelssitz war. Der Titel der Herren von L’Herm erscheint zum ersten Mal um 1400 im Schrifttum, als Hélie la Roque den Lehnseid ablegte. Die Burg blieb bis 1438 im Besitz dieser Familie und ging danach auf die Familie Lacropte über. Im Jahr 1500 wurde das Anwesen an Jean de Calvimont, Herr von Tursac, verkauft. Nach Ende des Hundertjährigen Krieges begann der in dieser Zeit übliche Umbau zu einem wohnlichen Schlösschen. Die Familie Calvimont widmete sich dieser Aufgabe, bis 1586 der letzte Träger des Namens, Jean IV., verstarb. In der Folge entwickelte sich im Streit um das Besitzrecht eine Familientragödie, in deren Verlauf die Akteure auch vor Mord nicht zurückschreckten. Als die tatsächlichen Besitzverhältnisse schließlich nicht mehr zu klären waren, kam es am 16. Juni 1679 zur Versteigerung in Paris. Für 40.000 Pfund ging die gesamte Lehnsherrschaft, gelegen in den Pfarreien Rouffignac, Milhac und Plazac, samt der hohen, mittleren und niederen Gerichtsbarkeit sowie den lehnsherrlichen Rechten an Marie de Hautefort, Nichte der Herzogin Schomberg. Ab 1714 galt das Schloss L’Herm als unbewohnt und dem Verfall überlassen. Beim Tod der Herzogin fiel das Schloss an den Markgrafen Emmanuel de Hautefort, und das Land wurde aufgeteilt. Ende des 19. Jahrhunderts gelangte die Ruine des Schlosses L’Herm noch einmal zu Ruhm, indem sie dem Schriftsteller Eugène Le Roy als Kulisse für seinen Roman Jacquou le Croquant diente.","w":"https://de.wikipedia.org/wiki/Schloss_L%E2%80%99Herm"},"ch-Q2242401":{"n":"Schloss Mehun-sur-Yèvre","c":"Schloss in Frankreich","r":"Schloss Mehun-sur-Yèvre gehört zur französischen Gemeinde Mehun-sur-Yèvre im Département Cher in der Region Centre-Val de Loire; in aktuellen französischen Broschüren und in örtlichen Hinweisen wird die Bezeichnung Château Charles VII verwendet. Die Schlossruine steht seit 1840 als Monument historique unter Denkmalschutz.","w":"https://de.wikipedia.org/wiki/Schloss_Mehun-sur-Y%C3%A8vre"},"ch-Q2496002":{"n":"Schloss Valmer","c":"Französische Schlossanlage im Tal der Loire","r":"Das Schloss Valmer ist eine Schlossanlage nordöstlich von Chançay, einer französischen Gemeinde im Département Indre-et-Loire der Region Centre-Val de Loire. Es entstand ab 1524 durch Umbau einer mittelalterlichen Burg der Familie Binet und wurde in der zweiten Hälfte des 17. Jahrhunderts umgestaltet und erweitert. Nach zahlreichen weiteren Veränderungen und Instandsetzungen während des 19. und 20. Jahrhunderts wurde das Hauptgebäude durch ein Feuer im Jahr 1948 fast vollständig zerstört. Die Reste der Anlage im Stil der Neorenaissance gehören zu den zahlreichen Schlössern im Loiretal und stehen gemeinsam mit dem dazugehörigen terrassierten Barockgarten seit dem 1.","h":"Im Jahr 1434 wurde Valmer das erste Mal genannt. Zu jener Zeit war es im Besitz von Catherine de Bueil, die somit die erste namentlich bekannte Besitzerin der Domäne war. Am 23. Juli 1461 kaufte diese Jacques Binet. Dessen Sohn Macé wurde im Jahr 1500 als Eigentümer aufgeführt. Aus seiner Ehe mit Jeanne Briçonnet stammte der Sohn Jean, Maître dʼhôtel des Königs und der Königin von Navarra. Er ließ die bis dahin bestehende mittelalterliche Burg in der Zeit von 1524 bis 1529 umfassend verändern und zu einem wohnlicheren Schloss gestalten. Zeitgleich wurde in den Tufffelsen, auf dem das Schloss steht, eine Schlosskapelle gehauen, die am 28. November 1529 durch den Bischof von Autun eingesegnet und am 13. März 1535 geweiht wurde. Als während der Hugenottenkriege 1562 protestantische Soldaten das Schloss plünderten, gehörte es Jean Coustely, dem Bürgermeister von Tours. Um an das auf dem Schlossareal vermutete Geldversteck der Familie zu kommen, schreckten die Plünderer nicht davor zurück, Jeans Tochter zu foltern und ihr die Fußsohlen zu verbrennen. Jeans Nachfahre Claude Coustely verkaufte Valmer am 23. Mai 1640 an einen Berater Ludwigs XIII., Thomas Bonneau, der umfassende Umgestaltungen und Erweiterungen an der Schlossanlage vornahm. Die Innenräume des Schlosses wurden im Stil Louis-treize überarbeitet, und nordöstlich des Schlossgebäudes ließ Bonneau 1646 bis 1647 einen Pavillonbau im gleichen Stil als Unterkunft des Schlossverwalters errichten. Weil der neue Schlossherr die alte Felsenkapelle als zu dunkel und zu feucht empfand, entstand an der Westseite des Petit Valmer genannten Verwalterhauses eine neue Kapelle, die am 25. Oktober 1647 gesegnet wurde.","w":"https://de.wikipedia.org/wiki/Schloss_Valmer"},"ch-Q12258310":{"c":"Schloss in Frankreich"},"ch-Q15943913":{"n":"Schloss Châteauneuf-sur-Loire","c":"Schloss mit Schlossgarten und ägyptischen Sphingen in Frankreich","r":"Das Schloss Châteauneuf-sur-Loire war ein Schloss aus dem 17. und 18. Jahrhundert, dessen Reste sich in Châteauneuf-sur-Loire im französischen Département Loiret befinden, da von dem Ensemble aufgrund der Revolution kaum noch etwas erhalten geblieben ist.","h":"An diesem Ort gab es nacheinander mindestens drei Burgen oder Schlösser, die den architektonischen Moden der Zeit folgten, bevor sie abgerissen und durch ein neues Gebäude ersetzt wurden. Die erste Burg aus dem 11. Jahrhundert war eine massive Festung mit vier Türmen, die von König Heinrich I. errichtet wurde; es war zu dieser Zeit das jüngste der königlichen Schlösser und erhielt deshalb den Namen „Château Neuf“, also „Neues Schloss“. Später wohnten hier zeitweise die französischen Könige von Ludwig VI. der Dicke, Ludwig VII. der Jüngere, Ludwig IX. der Heilige und Karl IV. der Schöne; 1328 wurde hier Karls Tochter Blanche geboren, 1343 Jeanne, die Tochter des König Johann II. der Gute; Blanche heiratete später Philippe de Valois, Duc d’Orléans, der sich hier ebenso aufhielt wie sein Nachfolger Charles (1403). Ludwig XII. schenkte es seiner Ehefrau Jeanne de Valois, nachdem er sie 1498 verstoßen hatte. Im späteren Teil des zweiten Viertel des 16. Jahrhunderts gehörte Châteauneuf dem 1529 aus Italien geflohenen, 1544 zum Marschall von Frankreich ernannte und 1550 gestorbenen Giovanni Caracciolo geschenkt, in den Jahrzehnten danach offenbar seinen Kindern, von denen drei auf dem Schloss starben (1555, 1569 und 1586). Im Jahr 1644 gehörte es dann dem Surintendant des Finances Michel Particelli († 1650) und anschließend seiner Tochter Marie († 1670), die 1635 Louis I. Phélypeaux de La Vrillière geheiratet hatte, zum Marquis de Châteauneuf ernannt wurde und 1681 in einem Mausoleum in der Kirche des Ortes ruht. Das als Zentrum des Marquisats anzusehende Schloss wurde Ende des 17. Jahrhunderts an der Stelle des königlichen Vorgängerbaus errichtet.","w":"https://de.wikipedia.org/wiki/Schloss_Ch%C3%A2teauneuf-sur-Loire"},"ch-Q8592":{"n":"Schloss Pierre-Scize","c":"Schloss in Lyon, Frankreich","r":"Die heute abgegangene Burg Pierre Scize befand sich in der Stadt Lyon.","h":"Der Ort war zur Zeit des Römischen Reiches sicherlich besiedelt: Arbeiter, die am Fuße der Burg die Erde abtrugen, fanden Überreste von Grablampen, Medaillen und anderen antiken Gegenständen. Die Beweise für ihre Existenz beginnen jedoch erst im 12. Jahrhundert. Die Lage des Ortes ist jedoch zu günstig, als dass sie nicht schon vor diesem Jahrhundert genutzt worden wäre. Laut Poullin de Lumina soll Erzbischof Hugo hier im Jahr 1099 ein Konzil der Bischöfe seiner Provinz versammelt haben. Erzbischof Heraclius (1153–1163), flüchtete sich bei seinen Auseinandersetzungen mit den benachbarten Baronen mehrmals dorthin; er war der erste, der die Burg zur Festung der Lyoner Erzbischöfe machte. Die Burg wurde in der Folgezeit zu einer der größten Festungen in Frankreich. Nach Zeiten der Unruhen fügte der Erzbischof Renaud de Forez (1193–1226) dickere Mauern hinzu, verschönerte das Innere und machte die Festung zu einem erzbischöflichen Palast. Seine Nachfolger ließen sich in der Burg nieder. Als Papst Innozenz IV., der sich mit Kaiser Friedrich II. angelegt hatte, 1244 in Lyon weilte, zog sich Bischof Aimeric in die Burg Pierre Scize zurück (er resignierte gleich nach dem Ersten Konzil von Lyon 1245). Nachdem Lyon von französischen Truppen besetzt worden war, verlor Erzbischof Peter von Savoyen durch den Vertrag vom 10. April 1312 mit Philipp dem Schönen die Gerichtsbarkeit über Lyon an die französische Krone, behielt sich jedoch die weltliche Gerichtsbarkeit über die Burg Pierre Scize mit seinen Nebengebäuden vor. Im Jahr 1330 wurden dem Kastellan der Burg zwölf Waffenknechte unterstellt; im Jahr 1335 war dies der Herr von Iseron, der für sein Amt 50 Vienner Sous pro Woche erhielt, während die Waffenknechte jeweils 8 Gulden pro Monat verdienten.","w":"https://de.wikipedia.org/wiki/Burg_Pierre_Scize"},"ch-Q75401":{"n":"Hohenburg","c":"Burg in Frankreich","r":"Die Hohenburg ist die Ruine einer Felsenburg im nördlichen Elsass (Frankreich) nahe der Grenze zu Deutschland. Sie erhebt sich in 551 m Höhe auf dem Schlossberg.","h":"Die Burg wurde wahrscheinlich im frühen 13. Jahrhundert errichtet. Es wird vermutet, dass Gottfried Puller (später Gottfried von Fleckenstein), der 1236 für Kaiser Friedrich II. in Italien Dienste tat und deswegen die Burg bauen durfte, der erste Vertreter der Hohenburger Familie war. Die Burg wird im Jahr 1262 erstmals im Besitz von Konrad und Heinrich von Hohenburg urkundlich erwähnt. Von 1273 bis 1289 gab es Zwist zwischen den Fleckensteinern und den Hohenburgern, der mit der Eroberung der Belagerungsburgen Löwenstein und des Felsens unterhalb der Wegelnburg durch Landvogt Otto von Ochsenstein endete. Nach dem Tod von Wilrich I. überschrieb dessen Witwe Vye von Wasigenstein 1389 die Burg an den pfälzischen Kurfürsten Ruprecht I., und Ruprecht III. wiederum verlieh die Burg 1401 an Konrad Puller von Hohenburg. Wilrich II. von Hohenburg überschrieb die Burg 1434 an seine Ehefrau Jutta von Schöneck. Ihr Sohn Richard hatte Streitigkeiten mit dem Pfälzer Kurfürsten, die zur Einnahme der Burg durch den Kurfürsten führten. Richard wurde 1482 unter dem Vorwurf der Sodomie in Zürich, wo er zuerst Asyl und Bürgerrecht bekommen hatte, verbrannt. Swicker VIII. von Sickingen aus dem Geschlecht der Sickinger hatte bereits 1475 Richards Schwester geheiratet und gelangte so nach dessen Tod an die Burg. Franz von Sickingen ließ die Burg 1504 neu befestigen. 1523 wurde sie jedoch größtenteils zerstört, als verbündete Truppen des Kurfürsten Ludwig V., des Erzbischofs Richard von Trier und des Landgrafen Philipp I. von Hessen sie einnahmen. Erst einige Jahre später, 1542, wurde die Burg durch die Sickinger im Renaissancestil wiederaufgebaut.","w":"https://de.wikipedia.org/wiki/Hohenburg_(Elsass)"},"ch-Q125814":{"n":"Schloss Germolles","c":"Schloss im Département Saône-et-Loire, Frankreich","r":"Das Schloss Germolles steht in der französischen Gemeinde Mellecey im burgundischen Département Saône-et-Loire.","h":"Der Name des Schlosses geht auf die Herren von Germolles zurück. Guigon von Germolles wurde 1257 wegen eines Verfahrens gegen seinen Nachbarn Guillaume von Montaigu vor dem Kirchengericht von Chalon-sur-Saône namentlich erwähnt. Unter den Nachkommen Geoffroys errangen die lokalen Feudalherren in der ersten Hälfte des 14. Jahrhunderts die Herrschaft über die umliegenden Gemeinden Saint-Martin-sous-Montaigu, Mellecey, Dracy-le-Fort, Corcelles und Chastenoy. Germolles war ab dem 13. Jahrhundert eine gut ausgebaute Burganlage, und der Sohn Jean Guillaumes II. konnte dank der Heirat 1363 mit Philiberte von Montaigu den alten Nachbarschaftsstreit beilegen und an Macht hinzugewinnen. Nach 1375 wendete sich jedoch das Blatt gegen die Herren von Germolles, die mit 1800 Gulden verschuldet waren. Innerhalb von zwei Jahren verlor Guillaume das Landwesen der Germolles an den Herzog von Burgund: Am 11. Dezember 1380 konfiszierte Philipp der Kühne, der erste Herzog von Burgund aus der königlichen Dynastie der Valois, den Besitz. Am 7. Juni 1381 erschien Guillaume von Germolles mit dem herzoglichen Verwalter Philibert Paillart vor dem Vogt von Chalon, um den Besitzübergang auf den Herzog zu bestätigen. Über das Aussehen der Burg der Herren von Germolles ist wenig bekannt. Gewiss war es ein massiver Bau mit Türmen und wenigen, kleinen Fenstern. Vom ursprünglichen Gebäude bleibt heute einzig die untere Kapelle und der Weinkeller. 1381 schenkte der Herzog den Besitz seiner Frau, die Herzogin Margarete von Flandern. Wichtige und teure bauliche Veränderungen wurden sofort durchgeführt. Sie dauerten ein Jahrzehnt von 1382 bis 1402. Das Ziel der Herzogin war, die strenge und archaische Anlage des 13. Jahrhunderts in ein Landgut zu verwandeln.","w":"https://de.wikipedia.org/wiki/Schloss_Germolles"},"ch-Q388174":{"n":"Château Palmer","c":"Schloss in Frankreich","r":"Das Château Palmer ist eines der berühmtesten Weingüter von Bordeaux. Seit der Klassifikation von 1855 ist das Weingut als Troisième Grand Cru Classé eingestuft, der dritthöchsten Stufe der Klassifikation. Das Gut steht mit seinen hervorragenden Erzeugnissen jedoch regelmäßig im Qualitätswettbewerb mit den Premiers und Deuxièmes Crus und folglich oft auch an der Spitze der Preise aller Nicht-Premier-Weine. Der Wein dieses Gutes gilt mindestens gleich viel wie die sogenannten „Super Seconds“ Château Léoville-las-Cases, Château Cos d’Estournel und Château Pichon-Longueville-Comtesse de Lalande.","h":"In der Folge des Ersten Weltkriegs und der Weltwirtschaftskrise in den 1930er Jahren mussten sich die Brüder Pereire von Château Palmer trennen, im Jahr 1938 übernahm ein Konsortium der Weinhandelsfamilien Fernand Ginestet, der Brüder Miailhe, Mähler-Besse und Sichel (dessen bekanntester Vertreter Peter Sichel war). Im Jahr 1950 überhamen die Familien Sichel und Mähler-Besse die Anteile der beiden anderen Familien.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Palmer"},"ch-Q388478":{"n":"Château Cos d’Estournel","c":"Schloss in Frankreich","r":"Das Château Cos d’Estournel ist eines der berühmtesten Weingüter von Bordeaux. Seit der Klassifikation von 1855 ist das Weingut als „Deuxième Grand Cru Classé“ eingestuft, in der zweithöchsten der Klassifikation von 1855.","h":"Gegründet wurde das Gut im 19. Jahrhundert von dem Weinkaufmann Louis-Gaspard Estournel, dessen Spezialität der Pferdehandel aus Arabien und der Weinhandel nach Arabien und Indien sozusagen im Pendelverkehr war. Estournel setzte sich zum Ziel, in Nachbarschaft des hochangesehenen Gutes Château Lafite-Rothschild in Pauillac, auf der anderen Seite des kleinen Grabens Jalle de Breuil, den besten Wein der Erde herzustellen. Hierzu kaufte er die Kieshöhen nördlich oberhalb von Lafite und begann eine ausgedehnte Bauaktivität. Bei seinen Handelsaktivitäten stellte er fest, dass der aus Indien zurückgekehrte, nicht verkaufte Wein besser war als der gleiche, im Château verbliebene Wein. Dies veranlasste ihn, alle seine Weine vor dem Verkauf auf Schiffsreise zu senden, da er die Qualitätsverbesserung der Kostenerhöhung vorzog. Die Weine jener Jahre markierte er mit einem „R“: Retour des Indes, zurück aus Indien, als Qualitätsmerkmal. Sie wurden ihm zunächst förmlich aus den Händen gerissen. Diese aufwendigen Maßnahmen des Bauens und Schiffstransportes jedoch ruinierten ihn mittelfristig; er musste sein Gut 1852 an seinen fast ebenso weinverrückten Londoner Bankier Martyns verkaufen. Estournel blieb ledig und kinderlos. Er starb ein Jahr später mit 91 Jahren als armer Mann, kurz bevor sein Lebenswerk 1855 durch die Einstufung als „Deuxieme Grand Cru“ internationale Anerkennung erlangte. Der große Fasslagerkeller wurde von Estournel in der Art einer chinesischen Pagode mit mehreren geschwungenen Dächern gebaut. Die Giebelseite schmückt eine beeindruckend mit Schnitzarbeiten verzierte dunkle Doppelflügeltür, die angeblich aus dem Harembereich des Sultanpalastes von Sansibar stammt und im Handel gegen Wein erstanden wurde.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Cos_d%E2%80%99Estournel"},"ch-Q428854":{"n":"Château de la Roche Courbon","c":"Burg in Frankreich"},"ch-Q841527":{"c":"Burg in Frankreich"},"ch-Q842932":{"n":"Burg Ortenberg","c":"Burg in Frankreich","r":"Die Burg Ortenberg ist eine mittelalterliche Burgruine bei Scherwiller im Elsass, etwa sieben Kilometer nordwestlich von Sélestat.","h":"Ortenberg wird im Jahr 1166 erstmals urkundlich erwähnt. Die Burg wurde von Rudolf von Habsburg im Interregnum neu errichtet. Im Jahr 1265 war die Burg bewohnbar, da ein Brief Rudolfs von dort überliefert ist. 1293 belagerte Landvogt Otto III. von Ochsenstein Ortenberg von der benachbarten Burg Ramstein aus. 1314 verkauften die Habsburger Burg und Dorf Scherweiler an die Straßburger Familie Müllenheim. 1374 wurde die Burg von lothringischen Truppen beschädigt. Im 15. Jahrhundert war Ortenberg zunächst Zankapfel zahlreicher Ganerben und sank in der Folge zum Raubritternest herab. Peter von Hagenbach, der Landvogt Karls des Kühnen, brachte die Burg 1470 an sich, doch wurde sie 1474 von den Straßburgern zurückerobert. 1562 wohnte ein Burgvogt des Nikolaus von Bollweiler, der die Burg 1551 erworben hatte, auf Ortenberg. 1633, im Dreißigjährigen Krieg, wurde die Burg von den Schweden zerstört.","w":"https://de.wikipedia.org/wiki/Burg_Ortenberg_(Elsass)"},"ch-Q488269":{"n":"Burg Klein-Arnsberg","c":"Burg in Frankreich","r":"Die Ruine der Burg Klein-Arnsberg befindet sich auf einem Berg nördlich der Gemeinde Obersteinbach im Département Bas-Rhin, in Frankreich.","h":"Die Burg ist urkundlich erst seit dem 14. Jahrhundert nachweisbar, die Architektur spricht aber für eine Entstehung in spätstaufischer Zeit, spätestens Mitte des 13. Jahrhunderts. Auf der Burg saßen die Herren von Wasigenstein, die die Burg als Lehen der Abtei Weißenburg in Besitz hatten. 1335 wurde die Burg als Versteck des Raubritters Friedrich von Wasigenstein belagert und erobert. Von 1360 an ist sie im Besitz der Herren von Ochsenstein und wechselt in der Folge mehrfach die Besitzer. Um 1400 besitzen die Herren von Dahn (Than) die Burg als Lehen. Friedrich von Dahn verkauft 1420 seine Hälfte der Burg an Ludwig V. von Lichtenberg. Um 1483 besitzen die Herren von Adelsheim die Burg als Lehen. Nach 1485 kommt die Burg im Erbgang an die Grafen von Zweibrücken-Bitsch. Diese lassen die Burg ab 1494 umfassend renovieren. Die Burg war nun dem Amt Lemberg der Grafschaft Zweibrücken-Bitsch zugeordnet. Sie war ein Lehen des Kurfürsten von Mainz. 1570 verstarb Graf Jakob von Zweibrücken-Bitsch (* 1510; † 1570) als letztes männliches Mitglied seiner Familie. Das Amt Lemberg erbte seine Tochter, Ludovica Margaretha von Zweibrücken-Bitsch, die mit dem (Erb-)Grafen Philipp (V.) von Hanau-Lichtenberg verheiratet war. Ihr Schwiegervater, Graf Philipp IV. von Hanau-Lichtenberg, gab durch die sofortige Einführung des lutherischen Bekenntnisses dem streng römisch-katholischen Herzog Karl III. von Lothringen Gelegenheit, militärisch zu intervenieren, da dieser die Lehnshoheit über die ebenfalls zum Erbe gehörende Herrschaft Bitsch besaß. Im Juli 1572 besetzten lothringische Truppen die Grafschaft. Da Philipp IV. der lothringischen Übermacht nicht gewachsen war, wählte er den Rechtsweg.","w":"https://de.wikipedia.org/wiki/Burg_Klein-Arnsberg"},"ch-Q441039":{"n":"Burg Wineck","c":"Burg in Frankreich","r":"Die Burg Wineck, ursprünglich Windeck genannt, ist die Ruine einer kleinen mittelalterlichen Höhenburganlage oberhalb des Winecker Tales bei Dambach im Elsass und gehört zum Typus der Felsenburgen.","h":"Nach archäologischen Erkenntnissen wurde die Burg im 13. Jahrhundert errichtet. Die Burg wird 1338 erstmals urkundlich als Hauß Windecken im Besitz des Ritter Johann Marsilius von Saarbrücken, erwähnt. Im Jahr 1517 erhielt Wolf Eckbrecht von Dürckheim die Burg zusammen mit Burg Schöneck zu Lehen. Die Burg wurde wahrscheinlich 1680 zusammen mit Burg Schöneck zerstört. Seit dem 30. Dezember 1985 steht sie als Monument historique unter Denkmalschutz.","w":"https://de.wikipedia.org/wiki/Burg_Wineck_(Dambach)"},"ch-Q691089":{"n":"Burg Bernstein","c":"Burg in Frankreich","r":"Die Burg Bernstein ist die Ruine einer mittelalterlichen Höhenburg nahe der Gemeinde Dambach-la-Ville im Unterelsass. Ihr Name rührt gemäß einer Sage von „Bärenstein“ und nicht etwa von der Bezeichnung für fossiles Harz. Ein nahegelegener Felsen heißt Falkenstein.","w":"https://de.wikipedia.org/wiki/Burg_Bernstein_(Elsass)"},"ch-Q1014264":{"n":"Burg Tournoël","c":"Burg in Frankreich","r":"Die Burg Tournoël ist die Ruine einer Spornburg in der Nähe von Volvic in der Auvergne auf einem Felssporn auf halber Höhe eines Vulkankegels. Die schon 1889 unter Denkmalschutz gestellte Anlage bietet einen guten Ausblick auf die Limagne.","h":"Im Zusammenhang mit einem Bertrand de Tournoël wurde der Name Tournoël erstmals im 10. Jahrhundert erwähnt. Die Dokumente geben aber keine Auskunft über die Burg zu jener Zeit; eventuell handelte es sich um einen Wachtturm aus Holz. Gesicherte Erkenntnisse über die Geschichte der Burg liegen erst ab dem Beginn des 13. Jahrhunderts vor. Um 1200 war sie im Besitz von Guy II. de la Tour, comte d’Auvergne, einem Mitglied der mächtigen auvergnatischen Grafenfamilie La Tour d’Auvergne. Die ständigen Auseinandersetzungen mit seinem Bruder Robert d’Auvergne, dem Bischof von Clermont, veranlassten den französischen König Philipp II. dazu, die Wehranlagen der Region anzugreifen, um sie unter seine Kontrolle zu bringen. 1210 belagerten königliche Truppen erfolgreich die Burg, die zu jener Zeit lediglich aus einem quadratischen Donjon bestand, und nahmen sie ein. Das Gebäude wurde dabei fast vollständig zerstört. Tournoël blieb in königlichem Besitz, bis es Philipp II. 1306 mit der Familie von Maumont gegen Châlucet im Limousin eintauschte. Den Maumonts folgten als Besitzer die Familien d’Apchon und de la Roche. Im 14. Jahrhundert begann Hugues de la Roche damit, die Burg wieder aufzubauen und gleichzeitig zu erweitern. Mitte des 15. Jahrhunderts erneuerte sein Nachfahr Antoine de la Roche die alte Wehranlage im Stil der Renaissance und gestaltete sie komfortabler. Im Laufe der Zeit wechselte die Burg dann noch mehrmals den Besitzer: Den de la Roche folgten die Familien d’Albon, d’Apchon, de Montvallat und de Naucaze. Während der Hugenottenkriege beschädigten Kanonentreffer die Anlage stark. Ihre dabei zerstörte Schildmauer wurde nicht wieder aufgebaut. Im 17. Jahrhundert noch bewohnt, verfiel die Burg im 18. Jahrhundert immer mehr zu einer Ruine und wurde im 19.","w":"https://de.wikipedia.org/wiki/Burg_Tourno%C3%ABl"},"ch-Q1014374":{"n":"Burg Vendôme","c":"Burg in Frankreich","r":"Die Ruine der Burg Vendôme steht in der französischen Kleinstadt Vendôme im Département Loir-et-Cher der Region Centre-Val de Loire. Sie steht seit 1840 als Monument historique unter Denkmalschutz.","h":"Die Stadt Vendôme und ihre Burg waren häufig umkämpft. Im 12. Jahrhundert wurde das Vendômois Austragungsort des Machtkampfes zwischen dem Haus Plantagenet und der französischen Krone. Im Jahr 1188 nahm König Philipp II. von Frankreich die Burg von Vendôme ein. Jedoch schon wenig später eroberte Richard Löwenherz sie wieder zurück. 1194 besetzte Philipp die Stadt erneut und belagerte wiederum die Burg. Schließlich trafen die beiden Kontrahenten am 3. Juli des Jahres nordöstlich von Vendôme in der Schlacht bei Fréteval aufeinander, in der Richard Löwenherz die Franzosen besiegen konnte. Im 1515 wurde Vendôme von König Franz I. zugunsten Charles’ de Bourbon zum Herzogtum erhoben und mit der Pairswürde ausgestattet. 1562 wurde Charles’ Enkel Heinrich, der spätere König Heinrich IV., Herzog von Vendôme. Als Protestant in einem überwiegend katholischen Herzogtum, musste er zusehen, wie sich die Stadt mehr und mehr der Katholischen Liga annäherte. Heinrich war deshalb 1589, jetzt als König und Lehnsherr, gezwungen, Vendôme mit Waffengewalt unter seine Herrschaft zu bringen, wobei mehrere Burgen, darunter die von Vendôme und Lavardin, zerstört wurden. Im Jahr 1598 machte Heinrich IV. seinen Sohn César zum Herzog von Vendôme. Der Ränkeschmied hielt sich oft auf dem Lehnsgut auf. Er ließ die Zugangsrampe bauen, das Südtor „Porte de Beauce“ öffnen und an der Ostseite ein zusätzliches Gebäude errichten. Aus dem Festungsbau wurde ein Palast für Begegnungen und Festlichkeiten. Nach dem Tod Césars de Bourbon im Jahr 1665 blieb die Anlage unbewohnt, und die Französische Revolution wirkte sich verhängnisvoll für die Baulichkeiten aus.","w":"https://de.wikipedia.org/wiki/Burg_Vend%C3%B4me"},"ch-Q1090383":{"n":"Château Cantenac-Brown","c":"französische Weingut","r":"Château Cantenac-Brown ist ein französisches Weingut in der Appellation Margaux, auf der Halbinsel Médoc. Das 48 Hektar große Gut im Ortsteil Cantenac erhielt 1855 im Rahmen der Bordeauxwein-Klassifikation den Rang eines 3ième Grand Cru.","h":"Am 11. August 1754 kaufte der irischstämmige Jacques Boyd Rebflächen von der Familie de Sainvincens und gründete damit das Weingut. Am 28. August 1806 ging das Gut an John Lewis Brown (Onkel des gleichnamigen Malers John Lewis Brown) über, der in die Familie Boyd eingeheiratet hatte. Den größeren Teil nannte er Château Cantenac-Brown. Für diesen Teil entwarf er das sehenswerte Gebäude im Tudorstil. Im Jahre 1843 verkaufte er das Château an einen Bankier namens Gromard. Später wurde es im Jahre 1860 vom reichen Weinhändler Armand Lalande gekauft, der auch das Château Léoville-Poyferré besaß. Dieser bepflanzte die Rebflächen neu und modernisierte die Keller. Frau Edouard Lawton (eine geborene Lalande) vermachte den Besitz ihrem Sohn Jean, der das Gut 1968 in sehr schlechtem Zustand an die Familie du Vivier übergab. 1989 ging das Gut in Besitz der Versicherungs-Gruppe AXA über. Seit 2006 ist es im Besitz der Familie Halabi.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Cantenac-Brown"},"ch-Q1090464":{"n":"Château Gruaud-Larose","c":"Weingut im Raum Bordeaux in Frankreich","r":"Das Château Gruaud-Larose ist ein Weingut im Raum Bordeaux in Frankreich. Es befindet sich westlich von Saint-Julien und wird von einem gut gepflegten Garten mit englischem Rasen, Blumen und weißen Kieswegen umgeben.","h":"1757 kaufte der Pfarrer Gruaud drei kleine benachbarte Parzellen auf dem Hochplateau von Saint-Julien-Beychevelle auf und vereinte sie zum Château Gruaud. Sein Neffe, Sébastien Larose, taufte es schließlich in Château Gruaud-Larose um. Nach Gruauds Tod wurde das Gut in zwei Einheiten aufgeteilt, Gruaud-Larose-Sarget und Gruaud-Larose-Faure. 1934 vereinte Désiré Cordier die beiden Güter wieder durch Ankauf. Das 82 Hektar große Gut war jahrzehntelang das Flaggschiff der Weinhandelsgruppe Cordier in Bordeaux. Es wurde jedoch infolge wirtschaftlicher Probleme dieser Gruppe 1997 an die Gruppe von Bernard Taillan verkauft. Das Weingut wird vom Önologen Georges Pauli betreut. Die Weinberge sind derzeit zu 55 % mit der Rebsorte Cabernet Sauvignon, 31 % Merlot, 10 % Cabernet Franc 2 % Petit Verdot und 2 % Malbec besetzt.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Gruaud-Larose"},"ch-Q1088203":{"n":"Château de Pourtalès","c":"Schloss in Frankreich","r":"Das Schloss Pourtalès ist ein Schloss in Straßburg. Es steht seit 1984 als Monument historique unter Denkmalschutz.","h":"Das ursprüngliche Landgut im Norden des Stadtteils Robertsau wurde 1750 von dem königlichen Festungsbaumeister Joseph Guérault erbaut, der auch den Ausbau der Stadtbefestigungen des 18. Jahrhunderts in Straßburg leitete. 1784 erwarb der Baron de Coehorn das Gut Robertsau. 1802 kaufte der Bankier Athanase Paul Renouard de Bussière den Landsitz. Sein Sohn Baron Alfred Renouard de Bussière (1804–1887) war mit Sophie Mélanie de Coehoorn verheiratet. Um 1840 ließ er einen Park im englischen Gartenbaustil anlegen, 1844 wurde das Gebäude umgebaut und im Louis-seize-Stil eingerichtet. Ihnen folgte als Alleinerbin die Tochter Mélanie Renouard de Bussière. Verheiratet war sie seit 1857 mit dem Bankier Graf Edmond de Pourtalès (1828–1895), Sohn des James Alexander de Pourtalès-Gorgier, einem Finanzier aus dem Schweizer Neuchâtel, wohin sich die ursprünglich südfranzösische Familie de Pourtalès unter Ludwig XIV. als Hugenotten geflüchtet hatte. Der Park wurde von Gräfin Mélanie und Graf Edmond weiter ausgebaut, die dem Schloss auch seinen jetzigen Namen gaben. Sie entschlossen sich, das Gebäude erneut umbauen zu lassen und im großen Stil zu modernisieren. So ließen sie ab 1887 das Schloss vom Architekten Charles-Jules Breffendille umgestalten und Nebengebäude herstellen. Das Innere wurde zum Teil im Louis-seize- und Napoleon-III.-Stil ausgestattet. 1907 wurde von den Straßburger Architekten Gustave Krafft und Jules Berninger Anbauten errichtet, in dessen Räumen eine holzvertäfelte Bibliothek einrichtete. Comtesse Mélanie lud regelmäßig zu gesellschaftlichen Anlässen, den sogenannten Salons ein. Das Schloss wurde bald zum beliebten Treffpunkt des europäischen Hochadel, der Politik und Gesellschaft. Zu den Besuchern des Schlosses gehörten König Ludwig II.","w":"https://de.wikipedia.org/wiki/Schloss_Pourtal%C3%A8s"},"ch-Q1090603":{"n":"Château Olivier","c":"Schloss in Frankreich","r":"Das Château Olivier ist ein 220 ha großes Bordeaux-Weingut in der französischen Gemeinde Léognan im Département Gironde in Frankreich. Der Rot- und Weißwein ist als AOC Pessac-Léognan im Graves klassifiziert. Das Weingut befindet sich in Besitz der Bordelaiser Familie Bethmann und wird von Jean-Jacques de Bethmann bewirtschaftet.","h":"Die Geschichte dieses prachtvollen Châteaus geht bis ins Mittelalter zurück. Im später 15. Jahrhundert gehörte es einem lokalen Adligen namens Rostand d'Olivey. Der Schwarze Prinz soll auf dem Schloss ebenso zu Gast gewesen sein, wie Bertrand du Guesclin. Nach zahlreichen Besitzerwechseln gehört es sein Anfang des 20. Jahrhunderts der Familie de Bethmann, die ihr Weingut in den letzten Jahren der Führung von Laurent Lebrun anvertraut hat. Der Wein vom Château Olivier wurde 1953 klassifiziert, sowohl der rote als auch der weiße.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Olivier"},"ch-Q1090716":{"n":"Château de Rayne-Vigneau","c":"Schloss in Frankreich","r":"Das Château de Rayne-Vigneau ist ein Weingut in der Gemeinde Bommes, einem Teil der Appellation d’Origine Contrôlée Sauternes in der Weinbauregion Bordeaux. Bei der Bordeauxwein-Klassifizierung von 1855 wurde es als „Premier Cru Classé“ klassifiziert. Das Gut verfügt über 80 Hektar Fläche, die ausschließlich dem Weinbau gewidmet sind. Die Rebflächen liegen nur unweit von den Weingütern Château Sigalas-Rabaud, Château Rabaud-Promis sowie Château Lafaurie-Peyraguey entfernt.","h":"Die Geschichte des Guts lässt sich bis in das späte 17. Jahrhundert zurückverfolgen, als das Weingut Gabriel de Vigneau gehörte. 1681 übernahm dessen Sohn Étienne die Geschicke des Guts. Er heiratete Jeanne Sauvage, Tochter des Eigners von Château d’Yquem. Danach verliert sich die Geschichte des Guts während einiger Jahrzehnte. Bekannt ist, dass die Weinhändler-Familie Duffour das Gut spätestens ab dem Jahr 1742 besaß. Nach dem Tod von Jean Duffour im Jahr 1750 verwaltete dessen Witwe Jeanne Tuffereau den Besitz bis 1774. Ihr Sohn übernahm das Gut, verstarb aber bereits im Sommer 1775, so dass dessen Bruder Bruno Duffour die Geschicke bis 1817 leitete. Nach dessen Tod erbten vier Neffen Château de Rayne-Vigneau. Im Jahr 1834 kaufte Catherine de Rayne das Weingut. Ihre Ehe blieb kinderlos, so dass ihr Besitz an ihren Bruder Vicomte Gabriel de Pontac überging. Er benannte das Weingut um in Vigneau-Pontac, aber sein Neffe Albert de Pontac änderte den Namen im Jahr 1892 in Château Rayne-Vigneau. Nach Alberts Tod am 19. August 1922 leitete sein Schwiegersohn Gabriel Vicomte de Roton zusammen mit seiner Frau Alexandrine de Pontac die Geschicke von Rayne-Vigneau. Deren Sohn Francois Vicomte de Roton besitzt weiterhin noch das Gebäude. Die Rebflächen kaufte Georges Raoux im Jahr 1961. Da sich Süßweine dieser Region in den 1960er Jahren schlecht verkauften, musste Raoux sich bereits zehn Jahre später von dem Weingut trennen; der Preis belief sich auf 3 Millionen Francs. Die Weinhändlerfamilie Mestrezat-Preller, auch Eigentümer des Rotweingutes Château Grand-Puy-Ducasse, war während einiger Jahrzehnte Besitzer, veräußerte das Gut jedoch im Jahr 2004 an die Bank Crédit Agricole.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_de_Rayne-Vigneau"},"ch-Q1157384":{"n":"Dagsburg","c":"Burg im Elsass, Frankreich","r":"Die Dagsburg im Elsass ist die Ruine einer Höhenburg im Nordosten von Frankreich und die jüngere von zwei Anlagen dieses Namens, die knapp 70 km voneinander entfernt sind. Die ältere ist die Dagsburg im heutigen Lothringen.","h":"Die Drei Exen wurden im 11. und 12. Jahrhundert in großer räumlicher Nähe zueinander erbaut, die Dagsburg, die jüngste der drei Burgen, um das Jahr 1150. Sie erhielt ihren Namen zur Erinnerung an die gegen Ende des 10. Jahrhunderts erfolgte Heirat zwischen Hugo VI. (960–1049), Graf im Nordgau und Graf von Egisheim, sowie Gräfin Heilwig (964–1046) von der gleichnamigen älteren Dagsburg im heutigen Lothringen. Ein 1002 – auf der damals den Egisheimern noch als Residenz dienenden Wahlenburg – nachgeborener Sohn des Ehepaars, Bruno von Egisheim-Dagsburg, wurde 1048 in Worms als Leo IX. zum Papst gewählt und amtierte bis zu seinem Tod 1054. Nachdem die Hauptlinie der elsässischen Adelsfamilie im 13. Jahrhundert ausgestorben war, gelangte die jüngere Dagsburg an das Bistum Straßburg. In dessen Eigentum verblieb sie bis ins 15. Jahrhundert. Dann kam die Burg wieder in den Besitz eines Egisheimers, nämlich des Ritters Peter von Egisheim. Dieser war über eine Nebenlinie Nachfahr von Graf Hugo VI., dem Vater von Papst Leo IX. Peter von Egisheim geriet in den Verdacht, sich als Raubritter zu betätigen. Zudem nahm er im Frühjahr 1466 auf der Dagsburg Hermann Klee auf, einen Müller aus der 35 km südlich gelegenen Stadt Mülhausen, der mit dieser wegen einer eigentlich geringen Geldforderung im Streit lag. Die Asylgewährung bildete den Anlass zum Sechs-Plappert-Krieg. In dessen Verlauf wurde die Dagsburg durch Truppen Mülhausens angegriffen, am Fronleichnamstag 1466 erobert und anschließend zerstört. Ritter Peter konnte fliehen, doch der Müller und einige seiner Freunde wurden gefangen genommen und hingerichtet. Seitdem ist die Burg Ruine.","w":"https://de.wikipedia.org/wiki/Dagsburg_(Elsass)"},"ch-Q1129728":{"n":"Pflixburg","c":"Burg in Frankreich","r":"Die Pflixburg ist die Ruine einer mittelalterlichen Höhenburg bei Wintzenheim im Département Haut-Rhin im Elsass, gut acht Kilometer westlich von Colmar.","h":"Der Burgberg war möglicherweise schon in der Bronzezeit besiedelt. Die Burg, die zum Reichslehen Plixburg des Heiligen Römischen Reichs gehörte, wurde zwischen 1212 und 1219 im Auftrag Kaiser Friedrichs II. als staufischer Stützpunkt am Oberrhein errichtet. Erstmals erwähnt wird sie als Blickisberc am 7. Mai 1220 in einer Schenkungsurkunde des Reichsministerialen Friedrich von Schauenburg. 1276 war die Pflixburg Hauptsitz des Oberelsässer Landvogts Konrad Werner III. von Hattstatt. König Adolf von Nassau verpfändete die Burg 1298 an die Üsenberger. Weitere Verpfändungen der nun zunehmend an Bedeutung verlierenden Burg erfolgten 1316 an Otto IV. von Ochsenstein, 1330 an König Johann von Böhmen und 1375 an die Herren von Hus. 1430 schenkte sie König Sigismund seinem Vizekanzler Kaspar Schlick, der sie 1434 an Maximin I. Smassmann von Rappoltstein verkaufte. Die Burg war in der Folge mit ein Anlass für eine Fehde zwischen den Hattstattern und Rappoltsteinern, doch wurde sie offenbar nicht zerstört, sondern von den Rappoltsteinern aufgegeben. In den Jahren 1864, 1983 und 2006 fanden Sanierungen an der Ruine statt, die seit 1968 als Monument historique unter Denkmalschutz steht.","w":"https://de.wikipedia.org/wiki/Pflixburg"},"ch-Q1264866":{"n":"Schloss La Ferté-Saint-Aubin","c":"Schloss in Frankreich","r":"Schloss La Ferté-Saint-Aubin ist ein Loire-Schloss in der Gemeinde La Ferté-Saint-Aubin im Département Loiret der Region Centre-Val de Loire in Frankreich. Es liegt am Ufer des Flusses Cosson.","w":"https://de.wikipedia.org/wiki/Schloss_La_Fert%C3%A9-Saint-Aubin"},"ch-Q835740":{"n":"Burg Pierre-Percée","c":"Burg in Frankreich","r":"Die Burg Pierre-Percée ist eine Burgruine in Pierre-Percée in Frankreich.","w":"https://de.wikipedia.org/wiki/Burg_Pierre-Perc%C3%A9e"},"ch-Q939256":{"n":"Château Lascombes","c":"Schloss in Frankreich","r":"Château Lascombes ist ein als Deuxième Cru Classé klassifiziertes Weingut in der Gemeinde Margaux im Bordeaux. Das Gut hat eine Größe von 100 Hektar, von denen 84 Hektar mit Wein bestockt sind.","h":"Erste Besitzer waren Mitglieder der Familie Durfort de Duras, die ab dem 12. Jahrhundert in Margaux wohnten. Die Familie führte das Weingut jahrhundertelang, nachdem die ersten Weinflächen im 15. Jahrhundert angelegt wurden, und führte es an die Spitze der Weingüter von Bordeaux. Der Familie gehörte zu jener Zeit auch Château Durfort-Vivens; die Flächen von Lascombes gehörten ursprünglich zu Durfort-Vivens. Es ist nicht überliefert, auf welchem Weg der 1625 geborene Antoine de Lascombes in den Besitz der Rebflächen kam. Das Weingut ging später an Jean-François de Lascombes, Berater des Parlement de Bordeaux und Mitglied der Académie de Bordeaux über, und kurz darauf an dessen Schwester Anne. Insbesondere Jean-François führte es an die Spitze der Weingüter von Bordeaux. So kann man in der Ausgabe vom 4. April 1838 des Magazins Le Producteur nachlesen, dass die Weine denen des Château Margaux ebenbürtig sind. Da Anne kinderlos starb, verlor die Familie den Einfluss über das Gut, und in der Folge der Französischen Revolution ging das Gut in Staatsbesitz über. Zuerst übernahm der Weinhändler Nathaniel Johnston das Gut, überließ es jedoch kurz später Fabre. Fabre verkaufte es an die Familie Loraique, die das Gut im Jahr 1844 für 90.000 Francs an Mademoiselle Hué veräußerten. Nach etlichen Jahrzehnten konnte die Familie Hué dem Gut durch kleinere Investitionen neue Impulse verleihen. Bei der Bewertung der Weingüter von Bordeaux anlässlich der Weltausstellung in Paris 1855 wurde die herausragende Stellung von Lascombes mit dem Rang eines Deuxième Cru Classé gekrönt. Frau Hués Schwiegersohn verkaufte das Gut an den bekannten Pariser Juristen Gustave Chaix-d’Est-Ange.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Lascombes"},"ch-Q956061":{"n":"Schloss Montceaux","c":"Schloss in Frankreich","r":"Die Ruinen des Schlosses Montceaux, auch Château des Reines genannt, stehen in der Gemeinde Montceaux-lès-Meaux im Département Seine-et-Marne. Das Schloss wurde im 16. Jahrhundert von der französischen Königin und Königinmutter Caterina de’ Medici erworben, die es entsprechend ihren Bedürfnissen im Stil der Renaissance umbauen ließ. Sie beauftragte den Architekten Philibert Delorme mit den Arbeiten, Handwerker und Künstler wie Jacques I. Androuet du Cerceau, Francesco Primaticcio waren dort tätig. Salomon de Brosse arbeitete erst ab 1601 am Schloss, also nach dem Abschluss der wichtigsten Umbauten.","w":"https://de.wikipedia.org/wiki/Schloss_Montceaux"},"ch-Q1011058":{"n":"Burg Blandy-les-Tours","c":"Burg in Frankreich","r":"Die Burg Blandy-les-Tours ist eine mittelalterliche Burg in der Gemeinde Blandy im französischen Département Seine-et-Marne der Region Île-de-France. Die Anlage steht bereits seit 1889 als klassifiziertes Monument historique unter Denkmalschutz.","w":"https://de.wikipedia.org/wiki/Burg_Blandy-les-Tours"},"ch-Q1011395":{"n":"Burg Crest","c":"Burg in Frankreich","r":"Die Burg Crest ist die Ruine einer Höhenburg oberhalb der südfranzösischen Gemeinde Crest im Département Drôme. Ihr erhaltener Donjon ist mit 52 Metern Höhe wahrscheinlich der höchste in Frankreich und steht seit Juni 1877 als Monument historique unter Denkmalschutz.","w":"https://de.wikipedia.org/wiki/Burg_Crest"},"ch-Q1661220":{"n":"Schloss Val","c":"Schloss in Frankreich","r":"Das Schloss Val steht in der französischen Gemeinde Lanobre des Kantons Ydes, der eine Untergliederung des Arrondissements Mauriac im Département Cantal in der Region Auvergne-Rhône-Alpes ist.","h":"Die ursprüngliche Burg Val war die Hauptresidenz der Familie Thynières (auch Tinières geschrieben). Sie wurde von Guillaume de Thynières an Guillot d’Estaing verkauft, der 1440 das heutige Schloss auf den Grundmauern der ursprünglichen Anlage erbauen ließ. Über die Jahrhunderte hin verkam das Schloss und wurde Mitte des 20. Jahrhunderts durch den Stausee zu einer Art Wasserschloss, das 1953 in den Besitz der Stadt Bort-les-Orgues überging. 1960 wurde dort der Film Mein Schwert für den König (Le capitan) unter der Regie von André Hunebelle gedreht.","w":"https://de.wikipedia.org/wiki/Schloss_Val"},"ch-Q1666762":{"n":"Schloss Lanquais","c":"Schloss in Frankreich","r":"Das Schloss Lanquais liegt im Département Dordogne des französischen Périgord nahe dem Ort Lanquais.","w":"https://de.wikipedia.org/wiki/Schloss_Lanquais"},"ch-Q2241998":{"n":"Schloss La Roque","c":"Schloss in Frankreich","r":"Das privat bewohnte Schloss La Roque steht hoch über der D 25, drei Kilometer nordöstlich der Ortschaft Saint-Cyprien auf dem Gebiet der Gemeinde Meyrals im Département Dordogne des französischen Périgord.","w":"https://de.wikipedia.org/wiki/Schloss_La_Roque"},"ch-Q2242017":{"n":"Burg La Rochepot","c":"Burg in Frankreich","r":"Die Burg La Rochepot ist eine Burganlage im französischen Département Côte-d’Or der Region Burgund. Sie liegt auf einem Kalkfelsen nördlich des Ortes La Rochepot etwa 15 Kilometer südwestlich von Beaune und steht seit dem 3. April 2013 als Monument historique unter Denkmalschutz.","h":"Der Felsen, auf dem die heutige Anlage steht, war wahrscheinlich schon in römischer Zeit besiedelt. Zumindest legen dies Funde von Münzen aus dem 2. Jahrhundert nahe. In älteren Publikationen wird oft Alexander von Burgund (1170–1205), Sohn des burgundischen Herzogs Hugo II., als Bauherr einer ersten Burg etwas oberhalb des heutigen Standorts angegeben, jedoch erwähnt schon eine Urkunde aus der Zeit von 1112 bis 1140 ein castrum de Rocha und eine Burgkapelle an diesem Ort. Überreste dieser ersten Anlage sind heute noch erhalten und wurden um 1910 restauriert. Die Burg bestand aus mindestens zwei Gebäuden, die von einer Ringmauer umgeben und durch einen tiefen Graben an der Nordseite geschützt waren. Untersuchungen an dem Mauerwerk im Jahr 2005 ergaben, dass es aus dem 12./13. Jahrhundert stammen könnte. Diese Datierung wurde durch Keramikfunde bestätigt. Die erste Anlage wurde Ende des 13. Jahrhunderts, vielleicht wegen Wassermangels, aufgegeben und durch einen Neubau am heutigen Standort ersetzt. Zu jener Zeit waren Burg und dazugehörige Seigneurie in den Händen der Familie de La Roche. Von ihr gelangten sie durch Heirat an die Familie de Thil. Marie de Thil brachte den Besitz an ihren Mann Édouard, sire de Beaujeu et de Dombes. Der gemeinsame Sohn Antoine starb 1374 kinderlos, sodass seine Schwester Marguerite Alleinerbin wurde. Deren Sohn Louis aus der Ehe mit Jacques de Savoie, Herr von Piemont, verkaufte die Herrschaft samt Burg 1403 an Régnier Pot. Der neue Burgherr stammte aus einem alten Adelsgeschlecht aus dem Berry und war Kammerherr des burgundischen Herzogs Philipp der Kühne sowie Ritter des Ordens vom Goldenen Vlies seit dessen Gründung im Jahr 1429.","w":"https://de.wikipedia.org/wiki/Burg_La_Rochepot"},"ch-Q1720411":{"n":"Château Rothschild","c":"teilweise öffentliche Parkanlage und Schloss am Stadtrand von Paris","r":"Der Park Edmond de Rothschild in Boulogne-Billancourt ist eine teilweise öffentliche Parkanlage am Stadtrand von Paris.","h":"Der Besitz in der Pariser Vorortgemeinde wurde 1817 vom damals 26-jährigen Bankier Jakob Rothschild geerbt. Dieser ließ den Besitz um 1850 auf 30 Hektar vergrößern und darauf 1856 bis 1861 von dem Architekten Joseph-Armand Berthelin und dem Maler Louis-Eugène Lami ein Palais im neobarocken Stil errichten. Der Park war damals in einen Landschaftsgarten und einen im streng regelmäßig-geometrischen Stil der französischen Barockparks gestalteten Teil gegliedert. Der regelmäßige Gartenteil entstand nach Entwurf von Louis-Eugène Lami. Schöpfer des Landschaftsgartens war um 1860 Joseph Paxton, dessen Entwurf von dem Landschaftsarchitekten Paul Loyre überarbeitet wurde. Zwischen 1900 und 1930 wurde als dritter Teil ein Japanischer Garten von einem japanischen Gärtner namens Hatta erstellt. 1924 wurde ein weiterer Parkteil mit Steingärten und Wasserbecken, Routin genannt, von einem Gestalter namens Gaucher angelegt. Durch ihn verläuft ein Fließgewässer, der sogenannte Blaue Fluss. Nach dem Tod des Barons 1935 begann der Niedergang von Schloss und Park. Im Zweiten Weltkrieg wurde das Schloss von der deutschen Kriegsmarine requiriert und hatte unter der Besatzungsmacht zu leiden, nach 1945 wurde es zeitweilig von den Amerikanern besetzt. Die Familie Rothschild erhielt schließlich die Verfügung über das schwer beschädigte Gebäude zurück, benützte es jedoch nicht. 1975 diente es als Drehort für den französischen Film India Song nach einem Drehbuch von Marguerite Duras mit Delphine Seyrig, Michel Lonsdale und Mathieu Carrière. Das verfallende Schloss kam in anderen Privatbesitz, derzeit soll es im Besitz eines Mitglieds der saudi-arabischen Königsfamilie stehen. Durch den 1969 erfolgten Bau des Krankenhauses Ambroise Paré wurde der im regelmäßigen Stil angelegte Parkteil zerstört.","w":"https://de.wikipedia.org/wiki/Park_Rothschild_(Boulogne-Billancourt)"},"ch-Q1834237":{"c":"Burg in Frankreich"},"ch-Q2240680":{"n":"Schloss Dunois","c":"Schloss in Frankreich","r":"Das Schloss Dunois steht im Zentrum der französischen Gemeinde Beaugency im Département Loiret der Region Centre-Val de Loire, rund 20 Kilometer (Luftlinie) westlich von Orléans. Das Bauwerk wurde im Jahre 1925 als Monument historique eingestuft.","h":"Zu den vielen historischen, öffentlichen und kirchlichen Gebäuden von Beaugency gehört die imposante, aus einem 36 Meter hohen Donjon bestehende mittelalterliche Burg. In nur geringer Entfernung zum aus dem 11. Jahrhundert stammenden Festungsbauwerk ließ Jean de Dunois, der ehemalige Waffengefährte Jeanne d’Arcs und häufig der Bastard von Orléans (französisch Bâtard d’Orléans) genannt, das nach ihm benannte Schloss errichten, nachdem er durch seine Heirat mit Marie d’Harcourt Burgherr von Beaugency geworden war. Er lebte von 1440 bis 1457 im Schloss, bevor er Châteaudun zu seiner Residenz machte. Bis 1789 gehörte das Schloss der Familie Dunois-Longueville, danach stand es leer.","w":"https://de.wikipedia.org/wiki/Schloss_Dunois"},"ch-Q2969846":{"n":"Château de Maulnes","c":"Schloss im Burgund (département Yonne), Frankreich; 16. Jahrhundert.","r":"Das Château de Maulnes ist ein im 16. Jahrhundert erbautes Jagdschloss bei Cruzy-le-Châtel im französischen Departement de l’Yonne (Burgund). Es ist eines der wenigen noch erhaltenen Schlösser aus der Zeit Caterina de’ Medicis und ist innerhalb der Renaissance dem Manierismus zuzuordnen. Besonderheiten des Schlosses sind der Grundriss in Form eines Pentagons mit einer zentralen Wendeltreppe, die Platzierung der Fundamente über drei Quellen und ein von den Quellen gespeistes Nymphäum. Das Schloss wurde nie architektonisch verändert, es wurde aber schon bald nach seiner Erbauung vernachlässigt, und ab Mitte des 19. Jahrhunderts dem Verfall preisgegeben.","h":"Das Château de Maulnes ist eines von 30 in Jacques I. Androuet du Cerceaus Les Plus Excellents Bastiments de France beschriebenen Schlössern. Es entstand in den Wirren der Hugenottenkriege zu Lebzeiten von Caterina de’ Medici. Der Architekt ist nicht mit Sicherheit bekannt. Bauherren sind Antoine de Crussol (1528–1573) und seine Frau Louise de Clermont-Tallard (1504–1596), die zum Zeitpunkt der Eheschließung 52 Jahre alt war, 24 Jahre älter als ihr Mann. 1566 wurde Antoine zum Herzog von Uzès ernannt. Am 7. Mai 1566 schloss er in Tonnerre einen Vertrag mit zwei örtlichen Handwerkern über den Bau eines Schlosses ab, und im selben Jahr begannen die Bauarbeiten. Errichtet wurde das Schloss in einem ausgedehnten Waldgebiet in unmittelbarer Nähe eines mittelalterlichen, befestigten Hauses der Familie Clermont-Tonnerre, von dem allerdings keine Spuren mehr erhalten sind. Es kann angenommen werden, dass die Erdarbeiten schon früher begonnen hatten, da davon in den Verträgen keine Rede ist. Von 1570 bis 1572 wurden die Nebengebäude errichtet. 1572 wurde Antoine de Crussol zum Pair de France ernannt. Im August 1573 starb er an den Folgen einer Krankheit, die er sich bei der Belagerung von La Rochelle zugezogen hatte. Zu diesem Zeitpunkt war der Bau des Schlosses selbst weitgehend abgeschlossen. Louise starb 1596 ohne direkten Erben, und ohne ihren Nachlass geregelt zu haben. 1609 fiel der Besitz an ihren Großneffen Charles-Henri de Clermont-Tonnerre, der gleichzeitig den Herzogstitel erhielt, und der den Innenausbau des Schlosses vorantrieb. Mitte des 17. Jahrhunderts gelangte das Schloss in die Hand von Roger, Marquis von Cruzy, der einige bauliche Veränderungen vornahm und Reparaturen veranlasste.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_de_Maulnes"},"ch-Q2971710":{"n":"Burg Le Guildo","c":"Burg in Frankreich","r":"Die Burg Le Guildo befindet sich in der Gemeinde Créhen, an der Grenze zu den Gemeinden Saint-Jacut-de-la-Mer und Trégon. Es handelt sich um einen Burghof mit einer Fläche von ca. 3200 Quadratmeter, der 20 Meter über dem Arguenon liegt, an dessen Mündung er sich befindet. Die Burg liegt sich auf einem Felsvorsprung aus Glimmerschiefer, der von einer Doleritbank durchzogen ist. Sie wird im Norden und Westen vom Arguenon und im Osten von einem steilen Talweg begrenzt.","h":"Für die ältesten Zeiträume ist eine Besiedlung ab dem 12. Jahrhundert belegt. Die genaue Art dieser Besiedlung ist jedoch unklar. Der Grundriss eines großflächigen Mischhauses konnte freigelegt werden, das zum Teil aus Stein und zum Teil aus vergänglichen Materialien errichtet wurde. Die Entdeckung von Reitausrüstung lässt vermuten, dass an diesem Ort Reiter und damit wahrscheinlich auch Adlige anwesend waren. Die Verwendung von Mauerwerk beim Bau des Westgiebels ist ebenfalls ein Zeichen für relativen Reichtum. Derzeit können jedoch keine Verteidigungsstrukturen mit Sicherheit dieser ersten Phase zugeordnet werden, deren räumliche Organisation unbekannt ist. In der nächsten Phase wurde die erste Steinburg errichtet, von der teilweise noch die Überreste eines an die Nordkurtine angelehnten Wohnhauses erhalten sind. Es lassen sich drei Ausbaustufen unterscheiden, die alle vor dem letzten Drittel des 13. Jahrhunderts entstanden sind. Die Qualität des Baus, der Reichtum der freigelegten Malereien und der allgemeine Grundriss der Burg, der sich an den königlichen Bauten in Frankreich orientiert, lassen auf einen hochrangigen Auftraggeber schließen, der wahrscheinlich aus dem Umkreis der ersten Herzöge aus der Familie der Kapetinger stammt. Die dritte Phase folgt auf die Zerstörung der Burg in der Mitte des 14. Jahrhunderts, wahrscheinlich während des Bretonischen Erbfolgekriegs (1341–1364). Nachdem sie eine Zeit lang verlassen war, wurde die Burg vermutlich im letzten Viertel des 14. Jahrhunderts wieder aufgebaut. An der Nordfront wurde ein neues Wohnhaus errichtet, wobei teilweise die Überreste der vorherigen Bauten wiederverwendet wurden. Das Gebäude besteht aus einem großen, niedrigen Saal und einer Reihe von dreistöckigen Wohnungen, die im Osten liegen.","w":"https://de.wikipedia.org/wiki/Burg_Le_Guildo"},"ch-Q2971702":{"n":"Schloss Le Grand Jardin","c":"Schloss im Département Haute-Marne, Frankreich","r":"Das Schloss Le Grand Jardin war ein Lustschloss, das an die Residenz von Claude de Lorraine, Duc de Guise, in Joinville (Haute-Marne) angebaut war. Er ließ es zwischen 1533 und 1546 als großen Pavillon für Feste und Veranstaltungen errichten. Das Château d'en-bas, wie es zunächst genannt wurde, bildete einen Anbau an die mittelalterliche Schlossfestung oberhalb von Joinville, eine Hochburg des Hauses Guise, die während der Französischen Revolution zerstört wurde.","w":"https://de.wikipedia.org/wiki/Schloss_Le_Grand_Jardin"},"ch-Q2971734":{"c":"Burg in Frankreich"},"ch-Q3292683":{"c":"Palast in Frankreich"},"ch-Q2968561":{"c":"Burg in Frankreich"},"ch-Q2970060":{"c":"Burg in Frankreich"},"ch-Q2969586":{"c":"Burg in Frankreich"},"ch-Q2969576":{"n":"Burg Lützelstein","c":"Burg im Elsass (Frankreich)"},"ch-Q2969647":{"n":"Burg Landreville","c":"Burg in Frankreich","r":"Die Burg Landreville ist eine Wasserburg in der Gemeinde Bayonville im Département Ardennes in Frankreich. Sie ist ein Zeugnis der Militärarchitektur der Ardennen im 16. Jahrhundert und ein seltenes Beispiel für einen noch praktisch intakten Herrschaftssitz aus der Vorrenaissance.","h":"Auf dem Gelände eines Schlosses aus dem 12. Jahrhundert wurde die Burg zu Beginn des 13. Jahrhunderts erbaut und Mitte des 16. Jahrhunderts umgestaltet. Die in der Region Argonne Ardennaise liegende Burg ist ein rechteckiges „maison forte“ (Festes Haus), das von vier zylindrischen Türmen mit „Pfefferschoten“-Dächern flankiert wird, umgeben von wassergefüllten Gräben, mit einem sechs Hektar großen Park, Stallungen und zwei Pavillons. Die Burg wurde am 12. August 2006 vom französischen Kulturministerium als historisches Denkmal eingestuft. In seiner 800-jährigen Geschichte hat Landreville die Geschichte zahlreicher Familien miterlebt, darunter die Landrevilles, Grandprés, Chennerys, Beauvais, Maillarts und Meixmorons. Das Porträt von Claude François de Maillart, Seigneur et Marquis de Landreville, wurde um 1735 von Nicolas de Largillière gemalt. Burg Landreville ist weiterhin Privatbesitz.","w":"https://de.wikipedia.org/wiki/Burg_Landreville"},"ch-Q2968764":{"n":"Schloss Cany","c":"Schloss in Frankreich","r":"Das Schloss Cany ist eine Schlossanlage in der französischen Gemeinde Cany-Barville im Département Seine-Maritime. Es wurde am Ende der Regierungszeit König Ludwigs XIII. von Pierre Le Marinier als Familienwohnsitz errichtet und in der Folgezeit nur wenig verändert. Sogar die Französische Revolution überstand das Anwesen unbeschadet. Unter der Familie Montmorency-Luxembourg um das Jahr 1830 erneuert und zum Teil verändert, gelangte die Anlage durch Heirat an die Grafen von Hunolstein und schließlich im ersten Viertel des 20. Jahrhunderts in den Besitz der Familie de Dreux-Brézé. Deren Nachfahren sind noch heute die Schlossherren.","h":"Das Land, auf dem das Schloss im 17. Jahrhundert errichtet wurde, gehörte früher zur Seigneurie Barville, die sich seit Ende des 16. Jahrhunderts im Besitz der Familie Le Marinier befand. Nachdem Pierre Le Marinier 1626 neuer Herr von Barville geworden war, kaufte er am 18. August 1634 Adrien de Breauté die benachbarte Seigneurie Cany ab und vereinigte die beiden Herrschaften zur neuen Seigneurie Cany. Ab 1640 begann er mit dem Neubau eines Schlosses im Stil Louis-treize, das zwar auf dem Land der ehemaligen Seigneurie Barville errichtet wurde, seinen Namen aber nach der Seigneurie Cany erhielt. Es ersetzte den bisherigen, weniger repräsentativen und bescheideneren Wohnsitz der Familie in der Ortschaft Barville, bestehend aus Wohnhaus, Pferdestall, Kuhstall, Remise, Scheunen, Taubenhaus, Holzschuppen, Kelter und weiteren Gebäuden. Eine Beschreibung aus dem Jahr 1700 zeugt davon, dass die Vorgängeranlage zu Beginn des 18. Jahrhunderts noch existierte. Das neue Schloss wurde binnen sechs Jahren fertiggestellt. Welcher Architekt die Pläne für den Neubau lieferte, ist nicht bekannt. Möglicherweise war es François Mansart, jedoch ist dies bisher nicht bewiesen. Das Ende der Bauarbeiten ist durch einen Bericht überliefert, der von einem Besuch Nicolas de Parisʼ, des Generalvikars von François II. de Harlays, dem damaligen Erzbischofs von Rouen, 1646 in der Kapelle in Barville erzählt. Nach Fertigstellung des Hauptgebäudes (Logis) kaufte Pierre Le Marinier am 13. Mai 1648 für 16.500 Livres von Jacques de La Taille auch noch die benachbarte Baronie Caniel, sodass sein Sohn Balthazar nach Pierres Tod 1662 neben dem Schloss auch viel Landbesitz erbte. Balthazar heiratete 1663 Geneviève de Becdelièvre und veräußerte Schloss und Seigneurie Cany (ohne die Baronie Caniel) am 3.","w":"https://de.wikipedia.org/wiki/Schloss_Cany"},"ch-Q2226645":{"n":"Burg Dreistein","c":"Burg in Frankreich","r":"Die Ruinen der Burg Dreistein, gelegentlich auch Dreystein geschrieben, stehen auf 628 Meter Höhe auf einem Felssporn der mittleren Vogesen etwa einen Kilometer westlich des Klosters Hohenburg auf dem Odilienberg. Die Anlage liegt auf dem Gebiet der elsässischen Gemeinde Ottrott im Département Bas-Rhin und gehört zu einer Gruppe von insgesamt neun Burgen in einem Bereich von wenigen Quadratkilometern rund um den Odilienberg, darunter Burg Birkenfels, das Hagelschloss und die Burg Kagenfels. Seit dem 9. März 1990 steht die Burg als eingeschriebenes Monument historique (inscrit) unter Denkmalschutz. Die Burgruine befindet sich zwar in Privatbesitz, ist aber jederzeit frei zugänglich.","h":"Die gesicherte Geschichte der Anlage ist bisher sehr lückenhaft, denn es sind kaum Quellen zu Dreistein vorhanden. Die Spornburg ist vermutlich eine Gründung des 13. Jahrhunderts. Möglicherweise wurde sie gebaut, um die mächtige Abtei Hohenburg zu schützen. Entsprechend war sie anfänglich vielleicht der Sitz eines Hohenburger Ministerialen. 1432 wurde die Anlage als „schloss zu den drey Steinen“ erstmals urkundlich erwähnt. Zu jener Zeit befand sie sich im Besitz der Familie von Rathsamhausen, der Kaiser Friedrich III. die Burg im Jahr 1435 als Reichslehen zusprach. 1550 bestätigte Kaiser Karl V. den Rathsamhausen-Ehenweyer dieses Lehen noch einmal. Um 1670 wurde die Burganlage als zerstört beschrieben. Wie es dazu kam, ist jedoch unbekannt. Möglicherweise wurde der östliche Teil von Dreistein schon um 1400 aufgegeben. Die Familie von Rathsamhausen blieb bis zur Französischen Revolution Eigentümerin der Anlage. Dann konfisziert und als Nationaleigentum an einen Herrn Rohmer verkauft, kam die Burg über einen Herrn Fuchs schließlich an die Familie des Fabrikanten Schäfer aus Oberehnheim. Im Jahr 1866 wurden Konsolidierungsarbeiten an den Ruinen durchgeführt, wovon eine Jahreszahl in einem zu jener Zeit rekonstruierten Gewände kündet.","w":"https://de.wikipedia.org/wiki/Burg_Dreistein"},"ch-Q2221500":{"c":"Burg in Frankreich"},"ch-Q2970500":{"c":"Burg in Frankreich"},"ch-Q2628194":{"c":"Burg in Frankreich"},"ch-Q2744194":{"n":"Schloss Aulteribe","c":"Burg in Sermentizon, Département Puy-de-Dôme, Auvergne-Rhône-Alpes, Frankreich","r":"Das Schloss Aulteribe ist eine als Monument historique klassifizierte Burg- und Schlossanlage in der französischen Gemeinde Sermentizon im Département Puy-de-Dôme der Region Auvergne-Rhône-Alpes. Das Schloss liegt an den ersten Ausläufern der Monts du Livradois innerhalb des Regionalen Naturparks Livradois-Forez. In römischer Zeit verlief die Via Agrippa, die Lyon mit Saintes verband, ganz in der Nähe des heutigen Schlossgeländes. Es steht seit dem 30. März 1949 als Monument historique unter Denkmalschutz.","h":"Die Anfänge der Anlage reichen mindestens in das 13. Jahrhundert zurück. In einer Urkunde wird sie erstmals erwähnt: «La première mention remonte à la seconde moitié du XIIIe siècle, Odinet Cholet est alors ‹damoiseau› d’Aulteribe.» („Die erste Erwähnung stammt aus der zweiten Hälfte des 13. Jahrhunderts, als Odinet Cholet ‚Damoiseau‘ (Junker) von Aulteribe ist.“). Als die ersten namentlich bekannten Grundherren von Aulteribe im 15. Jahrhundert werden die Familie d’Harcourt und nachfolgend die Chauley (auch *Cholet*) genannt, auf die wohl der Kern des aktuellen Bauwerks zurückgeht. Im Jahr 1400 erhielt Pierre Chauley den Titel des Herrn von Aulteribe. Durch die Heirat seiner Tochter Catherine gelangte der Besitz an Charles Motier de La Fayette aus einer einflussreichen auvergnatischen Adelsfamilie. Um 1467 ließ Charles Motier de La Fayette die Burg mit Schießscharten und Kanoniersplätzen militärisch befestigen. Zu dieser Zeit wies das Schloss einen dreieckigen Grundriss mit runden Ecktürmen auf und behielt trotz späterer Umbauten seine wehrhafte Gesamterscheinung bei. An drei Seiten war das Areal durch eine natürliche Schlucht geschützt. Die verletzliche Südseite wurde durch eine Ringmauer, zusätzliche Türme, ein Torhaus (Châtelet) und eine Zugbrücke gesichert. Im 17. Jahrhundert wurde die Anlage architektonisch leicht geöffnet, indem zahlreiche neue Fensteröffnungen in die massiven Mauern gebrochen wurden, um Licht und Wohnkomfort zu erhöhen. Nach den Familien de Montboissier und Beaufort-Montboissier (bis 1662) ging die Herrschaft durch die Heirat von Anne Gabrielle de Beaufort-Montboissier de Canillac an die Familie de Montagu über. Diese besaß das Landgut fast ein Jahrhundert lang, bewohnte das Schloss jedoch kaum, weshalb die Anlage zusehends verfiel.","w":"https://de.wikipedia.org/wiki/Schloss_Aulteribe"},"ch-Q2749538":{"c":"Burg in Frankreich"},"ch-Q2749738":{"c":"Burg in Frankreich"},"ch-Q2970343":{"c":"Schloss in Frankreich"},"ch-Q2968803":{"c":"Schloss in Frankreich"},"ch-Q2970385":{"n":"Burg Robert Le Diable","c":"Burg in Frankreich","r":"Die Burg Robert Le Diable ist eine mittelalterliche Burganlage aus der Zeit der historischen Provinz Normandie im Norden Frankreichs. Die Überreste der Burg befinden sich in der Region Normandie oberhalb einer Schleife der Seine in der Gemeinde Moulineaux, die zum Département Seine-Maritime gehört. Diese liegt direkt neben der Autobahn A13 von Rouen nach Caen. Die Burg wurde 1935 als Monument historique klassifiziert und unter Denkmalschutz gestellt.","w":"https://de.wikipedia.org/wiki/Burg_Robert_Le_Diable"},"ch-Q2970557":{"c":"Burg in der südfranzösischen Region Okzitanien","r":"Saint-Martin de Toques, auch St Martin de Toques, ist der Name einer Burg auf dem Gebiet der südfranzösischen Gemeinde Bizanet in der Region Okzitanien. Die Burg liegt am Nordrand der Corbières, knapp 4 km südlich der Gemeinde, und knapp 2,5 km Luftline westlich der Abtei de Fontfroide.","h":"Ein „Castellum Sancti Martini“ wurde erstmals im Jahr 978 urkundlich erwähnt. Das gesamte Mittelalter hindurch unterstand die Burg den Vizegrafen von Narbonne und wurde von lokalen Herren verwaltet. Sie diente als Schutz für die Straße von Narbonne in die Corbièren. Die heute vorhandene Gebäude wurden vom 12. bis zum 17. Jahrhundert errichtet. Die Kapelle wurde erstmals 1360 erwähnt, scheint aber älter zu sein. Auch die nordöstlichen achteckigen und runden Türme sind aus dem Mittelalter, während Wohnräume Wachstube und Eingang vermutlich aus der Renaissance stammen. Um 1300 hatte das um die Burg herum wachsende Dorf etwa 200 Einwohner. Um 1579 wurde die Burg mit den dazugehörigen Ländereien von der Narbonner Familie Castillon erworben, reiche Kaufleute und auch Stadtoberhäupter (Consul) von Narbonne, die in den lokalen Adel aufstiegen und die Burg restaurieren ließen. Das zugehörige Dorf verfiel im Laufe der Zeit und war im 18. Jahrhundert vollständig verschwunden. Schon 1709 gab es außerhalb der Burg nur noch 6 Haushalte. In diesem Jahrhundert kam es zu zahlreichen Gebietskonflikten, besonders mit der Nachbargemeinde Saint-André-de-Roquelongue und ebenso zu mehreren Besitzerwechseln. Es scheint, dass auch die Burg in diesem Jahrhundert als Wohnsitz aufgegeben wurde. Die Pfarrei wurde in der französischen Revolution aufgelöst. Die Burg verfiel zunehmend. Anfang des 19. Jahrhunderts wurden sogar Steine und Fenster verkauft. Ab den 1880er Jahren wurden die Ländereien in unabhängige Weingüter aufgeteilt und verkauft. Stand 2026 gehören noch 45 Hektar Grund zum Anwesen. Die Weinpreise waren in den 1880ern hoch, so dass eine Aufteilung wirtschaftlich lohnend war. 1926 wurde die „Ruinen der Burg Saint-Martin de Toques“ als „Monument historique“ unter Denkmalschutz gestellt.","w":"https://de.wikipedia.org/wiki/Saint-Martin_de_Toques"},"ch-Q2968129":{"n":"Burg Arques-la-Bataille","c":"Burg in Frankreich","r":"Die Burg Arques-la-Bataille ist eine Ruine in der französischen Gemeinde Arques-la-Bataille im Département Seine-Maritime in der Region Normandie. Die Reste einer mittelalterlichen Höhenburg liegen auf einem steilen Felsvorsprung eines schmalen Kreidefelsens oberhalb des Zusammenflusses der Flüsse Béthune, Varenne und Arques. Sie zählt zu den bedeutendsten Wehrbauten der Normandie und steht seit 1875 unter Denkmalschutz. Heute gehört sie zum Staatseigentum Frankreichs. Das Innere der Burg ist seit den 2000er-Jahren für die Öffentlichkeit gesperrt. Eine Besichtigung von außen ist möglich.","h":"Wilhelm von Talou (Guillaume de Talou), ein Onkel Wilhelms des Eroberers ließ die Burg zwischen 1040 und 1053 errichten. Der Sohn Wilhelm des Eroberers, Henry Beauclerc ließ die Burg im 12. Jahrhundert ausbauen. Weitere Ausbauten erfolgten unter Johann Ohneland am Ende des 12. Jahrhunderts. Im 15. und 16. Jahrhundert wurde sie nochmals an neuen Waffentechnologien wie Kanonen angepasst. Nach 1668 wurde die Burg dem Verfall preisgegeben, 1688 schließlich auch militärisch aufgegeben. In der Folge nutzen die Bewohner von Arques die Burg als Steinbruch. Nach mehreren Eigentümerwechseln übernahm der Staat die Burg im 19. Jahrhundert und stellte ihre Reste unter Denkmalschutz.","w":"https://de.wikipedia.org/wiki/Burg_Arques-la-Bataille"},"ch-Q2968243":{"c":"Schloss in Frankreich"},"ch-Q2968153":{"c":"Schloss in Frankreich"},"ch-Q3361198":{"c":"Schloss in Frankreich"},"ch-Q2243297":{"n":"Schloss Saint-Germain-de-Livet","c":"Schloss in Frankreich","r":"Das Schloss Saint-Germain-de-Livet ist eine Schlossanlage in der französischen Ortschaft Saint-Germain-de-Livet etwa sechs Kilometer südlich von Lisieux im Département Calvados der Region Normandie. Der Graben des Wasserschlosses wird von einem kleinen Zufluss der Touques gespeist.","h":"Die ersten namentlich bekannten Herren der Seigneurie Livet entstammten der Familie Tyrel und sind seit dem 12. Jahrhundert greifbar. Nicole Tyrel brachte den Besitz im 14. Jahrhundert an ihren Mann Ancel Louvet. Die heutigen Schlossgebäude gehen auf die Familie Tournebu zurück. Eine Nachfahrin Nicoles und Ancels, Jeanne Louvet, heiratete 1462 Pierre de Tournebu, wodurch dieser Seigneur von Livet wurde. Er begann im letzten Viertel des 15. Jahrhunderts mit der Errichtung eines Wohnhauses in Fachwerkbauweise. Sein Nachkomme Jean de Tournebu und dessen Frau Marguerite de Croismare ließen in der zweiten Hälfte des 16. Jahrhunderts ein befestigtes Torhaus mit einem sich anschließenden Gebäudeflügel aus Stein sowie einen wehrhaften Rundturm errichten. Davon zeugen die beiden Jahreszahlen 1584 und 1588 an den Fassaden der steinernen Gebäude. Während der Französischen Revolution konfisziert, kam das Schloss nach Ende der Revolution zurück in Familienbesitz. 1806 war Marie de Tournebu, verwitwete de Janville, Eigentümerin des Anwesens. Sie starb trotz zweier Ehen 1810 kinderlos, sodass ihre beiden Nichten aus dem Haus Foucault Saint-Germain-de-Livet erbten. Mitte des 19. Jahrhunderts ließen sie einen Teil der Anlage abreißen und die übrigen Gebäude erneuern. 1879 erwarb sie die Familie Gobley, ehe die Anlage 1920 oder 1922 an Julien Pillaut kam, der ein Nachkomme des bekannten Kunsttischlers Johann Heinrich Riesener war. Nachdem das Ehepaar Pillaut das Schloss in der ersten Hälfte des 20. Jahrhunderts hatte restaurieren lassen, schenkte es die Witwe 1957/58 der Stadt Lisieux.","w":"https://de.wikipedia.org/wiki/Schloss_Saint-Germain-de-Livet"},"ch-Q2970226":{"c":"Burg in Frankreich"},"ch-Q2967959":{"n":"Château Nairac","c":"Schloss in Frankreich","r":"Das Weingut Château Nairac liegt nahe der Route nationale 113 in der Gemeinde Barsac im Département Gironde in der Region Aquitanien in Frankreich. Es wurde bei der Bordeaux-Klassifizierung im Jahre 1855 als „Deuxième Cru Classé“ klassifiziert. Das Château liegt relativ niedrig, nahe der Garonne, die bei Hochwasser das Gelände fluten kann, was 1981 der Fall war.","h":"Das Gebäude lässt sich auf das Jahr 1777 datieren, die Ursprünge des Weinbaus liegen aber bereits in der Mitte des 17. Jahrhunderts unter André Duranceau. Nach mehreren Besitzerwechseln erwarb Élysée Nairac das Grundstück; das direkt anschließend gebaute Château besteht in dieser Form bis heute (2014). Zwei unverheiratete Töchter Nairacs führten den Besitz weiter bis in die 1840er Jahre. Bernard Capdeville, gleichzeitig Besitzer von Château Broustet, war der nächste Besitzer bis zu seinem Tod 1861. Broustet und Nairac wurden danach getrennt geführt. Es gab nach 1861 eine Reihe von Besitzerwechseln, und durch Vernachlässigung drohte das Château zu verfallen. Die Weinstöcke wurden nach Frostschäden im Februar 1956 neu gepflanzt. 1971 wurde Nairac von einem jungen US-amerikanischen Ehepaar namens Heeter erworben, das Château Giscours befindet sich im Besitz der Familie der Ehefrau. Mit großem Aufwand wurden Weinberg und Kellertechnik modernisiert. Hierbei stand der Önologe Émile Peynaud als Berater zur Seite. Seitdem werden die Eichenfässer jedes Jahr erneuert. 1986 wurde die Ehe geschieden, und die Leitung vom Sohn Nicolas Tari-Heeter übernommen. Im Archiv des Château werden die Jahrgänge 1798 und 1811 als herausragend aufgeführt. Der kleine Johnson 2010 listet die Jahrgänge 1997, 2002 und 2004 als „bevorzugt zu genießen.“","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Nairac"},"ch-Q2967945":{"c":"Schloss in Frankreich"},"ch-Q2969355":{"c":"Burg in Frankreich"},"ch-Q2969210":{"n":"Schloss Voltaires","c":"Schloss Voltaires in Ferney-Voltaire (Frankreich","r":"Schloss Voltaire befindet sich in der Gemeinde Ferney-Voltaire im Département Ain in der französischen Region Auvergne-Rhône-Alpes. Es liegt nahe der Schweizer Grenze und der Stadt Genf. Von 1761 bis zu seinem Tod 1778 war es der Wohnsitz des Philosophen Voltaire. Das Anwesen wurde 1958 als historisches Denkmal eingetragen und 1999 vom französischen Staat erworben.","h":"An der Stelle des heutigen Schlosses befand sich bereits im 14. Jahrhundert ein kleiner Herrensitz. Im 15. Jahrhundert gründete der Herzog von Savoyen hier eine Seigneurie. Das Gut ging später durch mehrere Genfer Familien, darunter 1594 an die Familie Chevallier und 1674 an die Familie Budé. Voltaire, der 1755 zunächst ein Anwesen in Genf (Les Délices) erworben hatte, suchte bald nach einem sichereren Wohnsitz außerhalb der Genfer Republik. Nach Streitigkeiten über die Veröffentlichung des Artikels „Genève“ in der Encyclopédie beschloss er, sich in Ferney niederzulassen – nahe genug, um Kontakt zu seinen Ärzten und Druckern in Genf zu halten, aber außerhalb der dortigen Jurisdiktion. Er erwarb das Gut 1758 über seine Nichte Marie Louise Mignot (Mme Denis) aus steuerlichen Gründen von Guillaume de Budé. Gemeinsam mit dem Genfer Architekten Jean-Michel Billon ließ er das alte Gebäude abreißen und errichtete den Kern des heutigen Schlosses, das er 1761 bezog. 1766 beauftragte er den Architekten Léonard Racle, zwei Seitenflügel anzubauen und damit den heutigen Grundriss zu vollenden. Das Erdgeschoss beherbergte die Wohnräume: im Süden das Vorzimmer, das Wohnzimmer, Voltaires Schlafzimmer und eine Bibliothek mit fast 7000 Bänden; im Norden, hinter dem großen Salon, die kleine Gemäldekammer und die Räume von Mme Denis. Im Gartengeschoss lagen Küche und Vorratsräume, im ersten Stock die Gästezimmer, darüber die Kammern der Bediensteten, im dritten Stock der Dachboden.","w":"https://de.wikipedia.org/wiki/Schloss_Voltaire"},"ch-Q2969972":{"n":"Schloss Montbéliard","c":"Schloss in Bourgogne-Franche-Comté, Frankreich","r":"Das Schloss Montbéliard oder Schloss der Herzöge von Württemberg ist eine Burg aus dem 13. Jahrhundert der Grafschaft Mömpelgard und später des Fürstentums Montbéliard im Stil der Renaissance, die auf einem Felsriegel über dem Stadtzentrum der französischen Gemeinde Montbéliard im Département Doubs in der Region Bourgogne-Franche-Comté liegt.","w":"https://de.wikipedia.org/wiki/Schloss_Montb%C3%A9liard"},"ch-Q2968411":{"c":"Burg in Frankreich"},"ch-Q2970273":{"n":"Schloss Pontchartrain","c":"Burg in Frankreich","r":"Das Schloss Pontchartrain liegt hauptsächlich in der Gemeinde Jouars-Pontchartrain im Département Yvelines, im Westen der französischen Region Île-de-France.","h":"Das Herrenhaus wird um 1325 oder 1330 als Pontem Cartonencem erwähnt. Im 16. Jahrhundert wurde dieses Herrenhaus, das sich an der Stelle des rechten Flügels des Schlosses befunden haben könnte, wahrscheinlich den Bauern überlassen, während an der Stelle des heutigen linken Flügels ein neues Haus gebaut wurde. Im Jahr 1598 wurde das Anwesen von Antoine de Buade de Frontenac erworben, Capitaine des châteaux de Saint-Germain-en-Laye, Saint-James et La Muette. Antoine de Buade de Frontenac verkaufte Pontchartrain 1609 an Paul Phélypeaux (1569–1621), den Sekretär der Königin Maria de’ Medici. 1613 heiratete Frontenacs Sohn Henri de Buade Anne Phélypeaux, die Tochter von Paul Phélypeauxs Bruder Raymond Phélypeaux. Ihr Sohn Louis de Buade de Frontenac wurde Lieutenant-général der Kolonie Neufrankreich in Nordamerika werden. Paul Phélypeaux war 1610 Berater des Königs und Begründer des Pontchartrain-Zweiges der Familie Phélypeaux, die das Schloss bis 1802 im Rahmen eines kontrollierten Verkaufs während der Französischen Revolution behielt. Sein Sohn Louis I. Phélypeaux ließ zwischen 1633 und 1662 das Hauptgebäude errichten, dessen Zuschreibung zu François Mansart unbegründet ist. Jean-Baptiste Phélypeaux (1646–1711), Louis’ jüngerer Sohn, Intendant von Paris von 1690 bis 1709, war ein Kunde des Kunsttischlers André-Charles Boulle. Louis II. Phélypeaux de Pontchartrain, der ältere Bruder von Jean-Baptiste, wurde 1689 Contrôleur général des finances und 1699 Kanzler von Frankreich. Er übernahm den Namen des Anwesens und beauftragte François Romain und André Le Nôtre mit dem Ausbau des Schlosses und 1693 mit der Gestaltung eines prächtigen Parks. Nach dem Tod seiner Frau 1714 legte er alle seine Ämter nieder, zog sich nach Pontchartrain zurück, wo er starb.","w":"https://de.wikipedia.org/wiki/Schloss_Pontchartrain"},"ch-Q3077955":{"c":"Burg in Frankreich"},"ch-Q2969404":{"n":"Burg Hohenstein","c":"Burg in Frankreich","r":"Die Burg Hohenstein ist die Ruine einer Höhenburg und liegt auf 440 Metern Höhe nordwestlich des elsässischen Ortes Oberhaslach im Département Bas-Rhin in Sichtweite der Burgen Klein- und Groß-Ringelstein und etwa einen Kilometer Luftlinie von der Ruine Nideck entfernt. Die Burg steht seit dem 6. Dezember 1898 als Monument historique unter Denkmalschutz und befindet sich im Eigentum des französischen Staats sowie des Office national des forêts, einer Abteilung des französischen Landwirtschaftsministeriums.","h":"Mit den Brüdern Heinrich und Albert von Hohenstein wurden 1226 erstmals Mitglieder der Familie und damit indirekt auch ihre Burg genannt. Die oft angeführte frühere Erwähnung von Hohenstein in einer Urkunde aus dem Jahr 1217 beruht auf der Fehldeutung von Hossenstein, mit dem Ochsenstein gemeint ist. Die Hohensteiner gehörten wahrscheinlich zu den wichtigsten Dienstmannen der 1225 ausgestorbenen Grafen von Dagsburg, und der Straßburger Bischof Berthold I. von Teck schaffte es wohl, sie bei seinem Versuch, das Dagsburger Erbe an sich zu bringen, auf seine Seite zu ziehen, indem er die Hohensteiner mit der Burg belehnte oder ihnen erlaubte, diese erst überhaupt zu errichten. Als bischöfliches Lehen ist die Anlage seit dem frühen 14. Jahrhundert belegt. 1251 oder früher wurde die Burg belagert, aber weder das genaue Datum noch der Anlass dafür oder der Ausgang der Belagerung sind bekannt. Möglicherweise hatten sich die Hohensteiner auf die gegen den Bischof Heinrich III. von Stahleck kämpfende Seite der Staufer geschlagen, worauf dieser ihre Burg belagern ließ. Dies wäre nicht das letzte Mal gewesen, dass sich Mitglieder der Familie gegen ihren Territorialherrn auflehnten. 1262 kämpften sie zum Beispiel in der Schlacht von Hausbergen gegen den Bischof Walter von Geroldseck auf Seiten der Stadt Straßburg. Allerdings verpfändete der Ritter Burchard von Hohenstein im Jahr 1279 seinen Teil an der Burg gegen die Zahlung von 220 Silbermark an Bischof Konrad III. von Lichtenberg. Offenbar nutzten die Hohensteiner aber den Wechsel von Konrad zu seinem Nachfolger Friedrich I. von Lichtenberg, um die bischöfliche Besatzung der Burg zu vertreiben, was für die Familie aber scheinbar ohne Folgen blieb, denn am 27. September 1299 schloss Friedrich I.","w":"https://de.wikipedia.org/wiki/Burg_Hohenstein_(Elsass)"},"ch-Q3078351":{"n":"Fort du Guesclin","c":"Schloss in Frankreich","r":"Das Fort du Guesclin liegt auf der strandnahen Gezeiteninsel Île du Guesclin nordöstlich von Saint-Coulomb, zwischen Saint-Malo und Cancale im Département Ille-et-Vilaine in der Bretagne in Frankreich.","w":"https://de.wikipedia.org/wiki/Fort_du_Guesclin"},"ch-Q2693243":{"c":"Burg in Frankreich"},"ch-Q2968956":{"n":"Schloss Châteaubriant","c":"Burg in Frankreich","r":"Das Schloss Châteaubriant ist eine aus dem Mittelalter stammende Burg, die während der Renaissance zum Schloss umgebaut wurde. Es liegt in der Gemeinde Châteaubriant im französischen Département Loire-Atlantique. Die ursprüngliche Burg wurde im 11. Jahrhundert an der Ostgrenze der Bretagne gegründet und diente, wie die Festungen in Vitré, Fougères, Ancenis und Clisson, der Verteidigung des Herzogtums gegen Anjou und das Königreich Frankreich.","h":"Die Burg wird erstmals zwischen 1030 und 1042 erwähnt. Sie wurde zunächst von Brient, einem Gesandten des Grafen von Rennes, errichtet, um einen Vorposten im Pays de la Mée zu schaffen. Diese Region um Châteaubriant war damals eine Pufferzone zwischen den Grafschaften Rennes, Nantes und Angers, aber auch ein Ort des Handels. Der Markt von Béré wurde zum Beispiel 1049 in einem Vorort der Stadt gegründet. Brient ist auch für den Bau der Kirche und des Priorats von Béré verantwortlich, zwei wichtige Wahrzeichen des mittelalterlichen Châteaubriant. Die erste Burg war eine hölzerne Motte. Sie beherrschte den Fluss Chère und den Rollard und hatte zwei konzentrische Gräben. Der eine war trocken, der andere mit Wasser gefüllt. Außerdem besaß sie einen großen quadratischen Bergfried, der um 1100 aus Stein errichtet wurde. Im 12. Jahrhundert wurden zwei Säle und eine Kapelle hinzugefügt, wobei letztere erst im 13. Jahrhundert fertiggestellt wurden. Im gleichen Zeitraum entwickelte sich Châteaubriant zu einer Stadt am Ufer des Rollard. Die Stadtmauern wurden zwischen dem 13. und dem 15. Jahrhundert errichtet. Das obere Torhaus, die Kurtine und die meisten Türme wurden im 13. Jahrhundert errichtet. Zum Torhaus gehören noch die beiden Türme, die ursprünglich 25 Meter hoch waren. Die Säle und der Bergfried wurden im 14. Jahrhundert umgebaut, und das untere Torhaus wurde vor 1400 fertiggestellt. Das frühe Haus Châteaubriant, dessen Gründer Brient war, starb 1383 aus. Die Baronie Châteaubriant wurde daraufhin vom Haus Dinan, einem anderen bretonischen Adelsgeschlecht, geerbt. Die Dinan blieben 1444 ohne männliche Nachkommen, 1486 stellte sich die Baronin von Châteaubriant, Françoise de Dinan, die letzte ihrer Familie, gegen Herzog Franz II. von Bretagne.","w":"https://de.wikipedia.org/wiki/Schloss_Ch%C3%A2teaubriant"},"ch-Q2729041":{"c":"Burg in Frankreich"},"ch-Q2356811":{"n":"Château royal de Collioure","c":"Festung aus dem 17. Jahrhundert in Collioure, Region Okzitanien, Frankreich"},"ch-Q2971213":{"n":"Château de la Croë","c":"Burg in Frankreich","r":"Das Château de la Croë ist eine große freistehende Villa auf einem acht Hektar großen Gelände auf der Halbinsel Cap d’Antibes an der Côte d’Azur im südfranzösischen Département Alpes-Maritimes. Das Château im klassizistischen Stil wurde von dem Architekten Armand-Albert Rateau entworfen und 1927 für Sir William Pomeroy Burton, den Generaldirektor von Associated Newspapers, gebaut.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_de_la_Cro%C3%AB"},"ch-Q2971917":{"c":"Burg in Frankreich"},"ch-Q2968250":{"c":"Burg in Frankreich"},"ch-Q2378450":{"c":"Burg in Frankreich"},"ch-Q2374744":{"n":"Burg Berzé-le-Châtel","c":"Burg im Département Saône-et-Loire, Frankreich","r":"Die Burg Berzé-le-Châtel, oder auch die Befestigung von Berzé-le-Châtel, geht auf ein Castrum zurück, das im Jahr 991 in einem Chartular des Klosters Cluny erwähnt wurde. Sie gehört zur Ortschaft Berzé-le-Châtel im französischen Département Saône-et-Loire in der 2016 zusammengeschlossenen großen Region Bourgogne-Franche-Comté. Die Burg besteht aus einer Kernburg und einer Unterburg mit insgesamt 14 Türmen.","w":"https://de.wikipedia.org/wiki/Burg_Berz%C3%A9-le-Ch%C3%A2tel"},"ch-Q2968318":{"n":"Château d'Oricourt","c":"Burg in Frankreich"},"ch-Q2968350":{"n":"Burg Usson","c":"Burgruine in Frankreich","r":"Die Burg Usson ist eine Burgruine im Département Ariège in der südfranzösischen Region Okzitanien. Sie ist die südlichste der Katharerburgen im Süden Frankreichs und seit 1978 als Monument historique anerkannt.","h":"Die erstmalige Erwähnung der Burg stammt aus dem Jahr 1035, doch reichen ihre Ursprünge wahrscheinlich bis ins 10. oder frühe 11. Jahrhundert zurück; im 12. Jahrhundert bildete sie die östliche Grenze der Grafschaft Foix und gehörte den Familien So und Alion. In den Jahren nach dem Ende des Albigenserkreuzzugs (1209–1229) soll sich der Katharerbischof Guilhabert de Castres zeitweilig hier aufgehalten haben, in den frühen 1240er Jahren bildete sie den letzten Rückhalt der in die Burg Montségur geflüchteten Katharer, die von hier mit Waffen und Lebensmitteln versorgt wurden. Am 15. März 1244, also einen Tag bevor auf dem Montségur der Scheiterhaufen angezündet wurde, entkamen sechs Katharer nach Usson, wohin bereits einige Monate zuvor der angebliche Schatz verbracht worden sein soll. Bernard d’Alion, der letzte Burgherr, wurde im Jahr 1257 oder 1258 gefangen genommen und nach einem Inquisitionsprozess in Perpignan verbrannt. Später spielte die Burg eine Rolle als Grenzfestung in den anhaltenden territorialen Auseinandersetzungen zwischen Frankreich und Spanien, die jedoch mit dem Pyrenäenfrieden (1659) und der Hochzeit Ludwigs XIV. mit Maria Teresa von Spanien (1660) ein Ende fanden.","w":"https://de.wikipedia.org/wiki/Burg_Usson"},"ch-Q2255651":{"c":"Burg in Frankreich"},"ch-Q2341945":{"n":"Schloss Le Barroux","c":"Schloss in Frankreich","r":"Das Schloss Le Barroux ist eine ehemalige mittelalterliche Burg in der französischen Gemeinde Le Barroux. Es ist seit 1920 als Monument historique eingeschrieben.","h":"Die Burg der Herren von Les Baux wurde im 12. Jahrhundert erbaut und im 16. Jahrhundert in ein Renaissance-Schloss umgewandelt. 1563 wurde es während der Hugenottenkriege den Protestanten überlassen. 1929 wurde das Schloss in ruinösem Zustand von einer Privatperson erworben und restauriert, aber 1944 von deutschen Truppen in Brand gesetzt und wieder zerstört. Die zweite Restaurierung ist mittlerweile abgeschlossen.","w":"https://de.wikipedia.org/wiki/Schloss_Le_Barroux"},"ch-Q2185929":{"n":"Schloss Esclimont","c":"Schloss in Frankreich","r":"Das Schloss Esclimont ist ein ehemaliger Adelssitz in der Gemeinde Auneau-Bleury-Saint-Symphorien im französischen Département Eure-et-Loir in der Region Centre-Val de Loire. Es geht auf eine Holzburg aus dem 7. oder 8. Jahrhundert zurück. 1097 wurde sie von Jean Germont, dem Seigneur d’Esclimont, in eine Steinburg mit rechteckigem Bergfried umgebaut.","h":"Das heutige Schloss ist der Nachfolger einer alten feudalen Festung, die im Laufe der Zeit mehrmals umgebaut wurde. Es wurde ab 1543 für Étienne Poncher, den Erzbischof von Tours, gebaut. Es ging in den Besitz der Familie seines Vetters Philippe Hurault de Cheverny (1528–1599) über, der Siegelbewahrer von König Heinrich III. und später Kanzler von König Heinrich IV. war. Das Anwesen wurde 1639 von Claude de Bullion für die Familie Bullion erworben. Sein Enkel, Charles Denis de Bullion, ließ zahlreiche Umbauten vornehmen. Nach dem Aussterben der Familie de Bullion ging das Gut durch Heirat in die Hände der Familie Montmorency-Laval und später in die der Familie Albert de Luynes über. Im 19. Jahrhundert erbte es Sosthènes de La Rochefoucauld, Duc de Doudeauville (1785–1864), der es dann an seinen Sohn Sosthène II. de La Rochefoucauld (1825–1908) weitergab, der dort zahlreiche Arbeiten durchführen ließ. Er wiederum übergab das Anwesen an seinen Sohn Édouard de La Rochefoucauld, Herzog von Bisaccia (1874–1968). 1958 zeigt ein illustrierter Artikel des Historikers Ernest de Ganay ein Schloss, das noch immer reich möbliert ist, insbesondere mit mehreren alten Wandteppichen (einige aus dem 18. Jahrhundert, aus der Serie über das Leben Heinrichs IV.) Kunstgegenständen, Büchern und zahlreichen Familienporträts. Am 21. Juli 1981 verkaufte Laure-Suzanne-Marie Maingard, geborene Mailly-Nesle d’Orange, Enkelin und Erbin von Édouard de La Rochefoucauld, das Anwesen an René Traversac, den Präsidenten der Hotelkette Grandes Étapes Françaises. Im Januar 2015 wurde die Domäne von Pierre Traversac, dem Sohn des Vorgängers, an die chinesische Gruppe Tianci Hot Spring für 35 Millionen Euro verkauft.","w":"https://de.wikipedia.org/wiki/Schloss_Esclimont"},"ch-Q2081177":{"n":"Palais Ducal","c":"Gebäude in Nancy, Frankreich"},"ch-Q2242231":{"n":"Schloss Lignières","c":"Schloss in Frankreich","r":"Das Schloss Lignières liegt in der Gemeinde Lignières im französischen Département Cher.","w":"https://de.wikipedia.org/wiki/Schloss_Ligni%C3%A8res"},"ch-Q2242272":{"n":"Schloss Lourmarin","c":"Schloss in Frankreich","r":"Das Schloss Lourmarin ist ein Renaissanceschloss im französischen Ort Lourmarin im Département Vaucluse der Region Provence-Alpes-Côte d’Azur.","w":"https://de.wikipedia.org/wiki/Schloss_Lourmarin"},"ch-Q2625767":{"c":"Schloss in Frankreich"},"ch-Q5118715":{"c":"Burg in Frankreich"},"ch-Q5118761":{"n":"Burg Clermont (Isère)","c":"Burg in Frankreich","r":"Die Burg Clermont ist eine ehemalige Motte aus dem 11. Jahrhundert, die im 13. Jahrhundert neu gebaut und im 17. Jahrhundert geschleift wurde. Die Ruinen der Burg stehen in der Gemeinde Chirens im Département Isère in der Region Auvergne-Rhône-Alpes. Sie war der Hauptort des Mandements von Chirens und das Zentrum der Herrschaft Clermont-en-Viennois. Die Burg war seit dem 11. Jahrhundert der Stammsitz des später bedeutenden Hauses Clermont.","h":"Die Burg Clermont und das Mandement wurden 1107 bei der Aufteilung der Grafschaft Sermorens erstmals als solche erwähnt; sie war die Wiege der Familie Clermont, die Ende des 11. Jahrhunderts in den Schriftstücken auftaucht. Die Ausgrabungen von 1991 ergaben eine erste Siedlung ab der zweiten Hälfte des 11. Jahrhunderts, deren Grundriss nicht genau bekannt ist. Im 12. Jahrhundert stand ein Steinturm auf dem Gelände. Im 13. Jahrhundert wurde alles abgerissen und eine Motte mit einem polygonalen Turm errichtet. Die Ausgrabungen förderten auch die Überreste der Burgkapelle Notre-Dame zutage, die im 12. Jahrhundert nachgewiesen wurde und bereits im 11. Jahrhundert existiert haben könnte. Die Herren von Clermont, die bis dahin unabhängig waren, huldigten 1203 mit Guillaume de Clermont für ihre Ländereien Clermont, Saint-Geoire und Crépol dem Bischof von Vienne. 1330 wird erstmals die Ortschaft Villa Nova Di Chiroyen erwähnt. Es handelt sich um eine neue Stadt, die von den Herren von Clermont mit ermäßigten Steuersätzen gegründet wurde, um die Wirtschaftstätigkeit zu fördern. Im Jahr 1317 huldigte der Herr von Clermont dem Dauphin Jean II. de Viennois. Die Burg befand sich zu diesem Zeitpunkt im Grenzgebiet zu den États de Savoie, die eine Enklave im Süden, in Richtung Voiron, besaßen. Die Herrschaft wurde zur ersten Baronie der Dauphiné. Die Familie Clermont sah ihre Ländereien im 14. Jahrhundert zur Vicomté erhoben. 1547 wurde Antoine III. de Clermont vom französischen König Heinrich II. zum Grafen von Clermont en Viennois ernannt. Anscheinend wurde die Burg zu Beginn des 16. Jahrhunderts aufgegeben und 1626 auf königlichen Befehl, hinter dem der Kardinal Richelieu stand, geschleift, wie andere Burgen, die nicht mehr zur Verteidigung Frankreichs dienten.","w":"https://de.wikipedia.org/wiki/Burg_Clermont_(Is%C3%A8re)"},"ch-Q15940508":{"c":"Burg in Frankreich"},"ch-Q22987961":{"n":"Château de Paluel","c":"Schloss in Frankreich","r":"Das Château de Paluel ist die Ruine eines Schlosses aus dem 15. Jahrhundert in der Region Périgord Noir im Südosten des Départements Dordogne in Frankreich. Es liegt auf einem Felsvorsprung oberhalb des Tals der Enéa zwei Kilometer südlich von Saint-Vincent-le-Paluel. Das Schloss ist seit 1927 im Ergänzungsverzeichnis historischer Denkmäler aufgeführt und wurde 1944 während des Zweiten Weltkriegs durch einen Brand zur Ruine.","h":"Mitte des 15. Jahrhunderts erbte ein unehelicher Sohn der Familie Gimel die Herrschaft Paluel. Er und seine Nachkommen erbauten die Burg. Zu Beginn des 20. Jahrhunderts erwarb Prinz Louis de Croÿ die beiden verfallenen Schlösser Château de Paluel und Château de Commarque, um letzteres als Steinbruch für die Renovierung von Paluel zu nutzen. Im Zuge des Wiederaufbaus fügte er einen Anbau im zeitgenössischen Stil hinzu. In den 1930er-Jahren gestattete Prinz von Croÿ der Cagoule, einer rechtsextremen Terrorgruppe, ein Waffenlager in den unterirdischen Gängen der Burg anzulegen. Als im Zweiten Weltkrieg deutsche Truppen im Rahmen der Unternehmens Anton 1942 das unbesetzte Frankreich einnahmen, übergab der Prinz das Waffenlager den Behörden in Sarlat-la-Canéda. Die Waffen seien schließlich von der Résistance verwendet worden. Das Gebäude blieb bis Kriegsende in gutem Zustand. Am 28. Juni 1944 wurde es von der Einheiten der Waffen-SS in Brand gesetzt, nachdem sie am Fuße des Schlosses einen bewaffneten Widerstandskämpfer erschossen hatten. Eine Stele am Fuße des Schlosses erinnert an das Ereignis. Das Schloss wurde nicht wieder aufgebaut und von der Vegetation überwuchert. Das Anwesen gehörte anschließend Professor Jean Lassner, einem Pionier der Anästhesie. 1980 wurde die Leiche eines Drogenhändlers aus Bordeaux am Grund des Brunnens gefunden. 1999 verursachte ein schwerer Sturm weitere Schäden an der Bausubstanz. Nach dem Tod von Jean Lassner im Juli 2007 boten seine Kinder das Anwesen zum Verkauf an. 2010 ließ der neue britische Besitzer, Kevin Cartledge, das Gelände vollständig räumen: Das Schloss bot wieder einen freieren Ausblick und war für eine Restaurierung geeignet.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_de_Paluel"},"ch-Q388409":{"n":"Château Léoville-Barton","c":"Schloss in Frankreich","r":"Das Château Léoville-Barton ist eines der berühmtesten Weingüter von Bordeaux. Seit der Klassifikation von 1855 ist das Weingut als Deuxième Grand Cru Classé eingestuft; das ist die zweithöchste Stufe der Klassifikationen.","h":"Die Rebflächen des Château sind Teil des ehemals großen Besitzes von Léoville: Anfang des 17. Jahrhunderts gehörten die Ländereien entlang der Gironde zur Seigneurie de Lamarque. Es war ein Verdienst der Holländer, die Feuchtflächen entlang des Flusses trockengelegt zu haben. Auf einer frühzeitig trockengelegten Fläche auf einer höher gelegenen Kieskuppe wurden im Jahr 1638 erste Nutzflächen angelegt. Es war die Familie de Moytié, die ab der zweiten Hälfte des 17. Jahrhunderts hier mit dem Weinanbau begann. Später erhielt die Kieskuppe den Namen Mont Moytié. Im Jahr 1707 übernahm der Politiker und Präsident des Parlaments von Bordeaux den Besitz und vermachte ihn später an seine beiden Töchter. Eine der Frauen heiratete den einflussreichen Blaise Antoine Alexandre de Gasq, Seigneur von Léoville und ebenfalls Mitglied des Parlaments von Bordeaux. Nach einer Erbstreiterei der Töchter Moytiés gelang es de Gasq, die getrennten Besitztümer wieder zu vereinen. Die Flächen reichten von Château Beychevelle im Süden bis an das Château Latour in Pauillac im Norden. De Gasq verstarb 1769 kinderlos und der Léoville-Besitz ging in die Erbgemeinschaft von vier Neffen unter dem Vorsitz von Marquis de Las Cases Beauvoir auf. Verwaltet wurde der Besitz noch von Jean-Pierre d'Abbadie sowie von Bernard und Jean-Joseph d’Alozier. Während der Wirren der französischen Revolution musste der Marquis außer Landes fliehen. Ihm gelang es jedoch, seinen Besitz nicht als Gemeingut (Bien national) zu verlieren. Er trennte sich lediglich von einem knappen Viertel der Flächen, die später von Hugh Barton zu Château Léoville-Barton geformt wurden. Der Sohn des Marquis, Pierre-Jean de Las Cases, Maréchal de Camps, leitete die Geschicke des verbleibenden Guts ab 1815.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_L%C3%A9oville-Barton"},"ch-Q388536":{"n":"Château Pichon-Longueville-Baron","c":"Schloss in Frankreich","r":"Das Château Pichon Longueville-Baron ist eines der berühmtesten Weingüter von Bordeaux. Seit der Bordeauxwein-Klassifikation von 1855 ist das Weingut als Deuxième Grand Cru Classé eingestuft, zweithöchste der Klassifikationen.","h":"Diese beiden Güter waren früher bis vor rund 180 Jahren eines, Château Pichon-Longueville. Die Flächen wurden von Pierre de Mazure de Rauzan ab 1660 erworben. Ihm gehörte auch das später geteilte Château Rauzan in Margaux. Im 17. Jahrhundert begann man im Médoc erst, die weitläufigen Sümpfe trockenzulegen und Weinbau zu betreiben. Die Tochter von de Rauzan heiratete im Jahr 1694 Jacques de Pichon, Baron de Longueville, der erster Präsident des Parlaments von Bordeaux war. Das Weingut wurde in „Château Pichon-Longueville“ umbenannt. Mitte des 19. Jahrhunderts wurde der Besitz aufgeteilt. Während der bisherige Besitzer, Baron Joseph de Pichon-Longueville 2/5 des Besitzes behielt, erhielten seine 3 Töchter (Sophie de Pichon, die Vicomtesse de Lavaur sowie die Comtesse de Lalande) drei Fünftel des Guts. Später übernahm ein männlicher Nachkomme namens Raul den kleineren Teil des Barons; daraus wurde das heutige Gut Château Pichon-Longueville Baron. Das Weingut ist seit den 1980er Jahren in Besitz der Firma AXA Millésimes, ein Tochterunternehmen des Versicherungskonzerns AXA. Dieser veranstaltete kurz nach der Übernahme einen Architektur-Preiswettbewerb zur Renovierung des Weinkellers, dessen Sieger-Entwurf dann zu dem neuen, komplett in Edelstahl ausgerüsteten Gärkeller führte. Der Lichtkuppel-Turm ist eine schwebende Ringfundament-Konstruktion auf Schrägsäulen, ein überraschendes Bild.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Pichon-Longueville-Baron"},"ch-Q773649":{"n":"Schloss Monbazillac","c":"Schloss in Frankreich","r":"Schloss Monbazillac liegt zentral im Weinbaugebiet nahe der Ortschaft Monbazillac, sieben Kilometer südlich von Bergerac im Département Dordogne des französischen Périgord.","w":"https://de.wikipedia.org/wiki/Schloss_Monbazillac"},"ch-Q841639":{"n":"Château Guiraud","c":"Schloss und Wenigut in Frankreich","r":"Das Weingut Château Guiraud liegt in der Gemeinde Sauternes, einem Teil der Appellation d’Origine Contrôlée Sauternes in der Weinbauregion Bordeaux. Bei der Bordeauxwein-Klassifizierung von 1855 wurde es als „Premier Cru Classé“ klassifiziert. Das Gut verfügt über 128 Hektar Grundbesitz, von denen 100 Hektar dem Weinbau gewidmet sind.","h":"Die frühe Geschichte des Guts ist unbekannt. Das Gut war zu Anfang unter dem Namen La Maison Noble du Blaye bekannt. Erste Aufzeichnungen berichten von Eignern aus der Familie Essenault, denen auch Ländereien gehörten, aus denen Château d’Issan hervorgehen sollte. In Erbfolge ging das Maison Noble du Blaye von Catherine Essenhaut auf ihre Tochter Marie-Angélique und später an deren Bruder Joseph Chevalier de Mons. Joseph vermachte den Besitz an seinen Neffen Léonard-Joseph de Mons de Saint Poly. Am 22. Februar 1766 verkaufte er das Gut für 53.000 Pfund an Pierre Guiraud, einen Händler aus Bordeaux. Im Jahr 1799 vermachte Pierre das Anwesen an seinen Sohn Louis Guiraud, der Größe und Ansehen des Guts beträchtlich erweiterte. Im Jahr 1837 übernahm sein Sohn Pierre-Aman Guiraud die Leitung des Guts. Da er jedoch im Zuge der Erbteilung zu Gunsten seiner Schwester eine erhebliche Ausgleichszahlung leisten musste, war das Gut für ihn auf Dauer nicht haltbar und er musste es am 17. Juli 1846 an einen Konkursverwalter abtreten. Am 7. September 1846 übernahmen J. B. Dupons, A. Coutereau, C. Caubet, J. A. Depons und A. Ardusset das Gut. Seit dem 20. Juli 2006 gehört Château Guiraud Robert Peugeot, Olivier Bernard, Stephan von Neipperg und Xavier Planty. Mit der Übernahme von Château de Malle durch Luc und Clémence Planty im Jahr 2024 verließen beide das Weingut. Die Nachfolge am Château Guiraud trat die Önologin Sandrine Garbay an, die zuvor 28 Jahre lang bei Château d’Yquem gearbeitet hatte.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Guiraud"},"ch-Q842895":{"n":"Burg Kintzheim","c":"Burg in Frankreich","r":"Burg Kintzheim ist die Ruine einer mittelalterlichen Spornburg in den elsässischen Vogesen. Sie gehört zur Gemeinde Kintzheim im Département Bas-Rhin.","h":"Burg Kintzheim wird 1270 erstmals urkundlich als castrum Kunegesheim erwähnt. Die frühgotischen Maßwerkfenster deuten auf eine Erbauung um 1250 hin. Sie gehörte zunächst den Herren von Rathsamhausen. Nach mehreren Besitzerwechseln (Ausbau um 1480 durch Caspar von Mörsberg) fiel sie 1492 an die Stadt Schlettstadt. Die im Dreißigjährigen Krieg beschädigte Burg gelangte 1649 wieder in Privatbesitz. Um 1740 wurde sie von einem Einsiedler bewohnt. Nach der Französischen Revolution setzte ihr Verfall ein. 1876 fanden größere Sanierungen statt, doch erst 1965 wurde die Burgruine unter Denkmalschutz gestellt.","w":"https://de.wikipedia.org/wiki/Burg_Kintzheim"},"ch-Q866181":{"n":"Bischofspalast (Lauterbourg)","c":"Burg in Frankreich","r":"Der ehemalige Bischofspalast in Lauterbourg im Elsass war eine Residenz der Speyrer Bischöfe. Das Gebäude ist als Baudenkmal geschützt.","w":"https://de.wikipedia.org/wiki/Bischofspalast_(Lauterbourg)"},"ch-Q441301":{"n":"Frönsburg","c":"Burg in Frankreich","r":"Die Frönsburg ist die Ruine einer mittelalterlichen Felsenburg bei Niedersteinbach im Elsass.","h":"1269 wurde die Burg erstmals als Besitz derer von Frönsburg erwähnt. Im Jahr 1349 gelangte sie zur Hälfte in den Besitz von Ludwig von Frundsperg, zu je einem Viertel in den von Siegfried von Löwenstein und Reinhard von Sickingen. 1358 wurde dann Pfalzgraf Ruprecht I. Lehnsherr der drei. Ein Jahr darauf wurde die Burg wegen Landfriedensbruch der Inhaber von Johann von Lichtenberg eingenommen und zerstört. Der Wiederaufbau wurde durch Kaiser Karl IV. verboten. Ende des 15. Jahrhunderts ging die damalige Ruine an die Herren von Fleckenstein, um 1481 wiederhergestellt zu werden. Im Jahr 1677 wurde die Burg von den Franzosen geschleift.","w":"https://de.wikipedia.org/wiki/Fr%C3%B6nsburg"},"ch-Q441306":{"n":"Burgruine Löwenstein","c":"Burg in Frankreich","r":"Burg Löwenstein ist die Ruine einer mittelalterlichen Felsenburg bei Wingen im Elsass. Sie befindet sich in rund 530 Metern Höhe auf einem Südausläufer des Schlossberges in unmittelbarer Nachbarschaft der Hohenburg, der Wegelnburg und des Fleckensteins. Die Burg ist unter der Nummer PA00085241 als historisches Denkmal (Monument historique) klassifiziert.","h":"Die Burg wurde erstmals im 13. Jahrhundert als Reichslehen des Wolfram von Löwenstein erwähnt. Im Jahre 1283 wurde sie vom römisch-deutschen König Rudolf von Habsburg an Johann Ochsenstein verliehen. 1380 wurde die Burg mit Hensel Streif von Landenberg geteilt und 1383 zur Hälfte an Johannes (Hanemann) I. von Bitsch verpfändet. Schon drei Jahre später, 1386, wurde die Burg wegen Raubritterei durch Reichsvikar Johann von Lichtenberg zerstört. Wahrscheinlich wurde sie nicht wieder aufgebaut. Die Ruine befand sich später im Besitz der Puller von Hohenburg (1482), der Grafen von Zweibrücken-Bitsch (1485), der Grafen von Hanau-Lichtenberg (1570) und der Landgrafschaft Hessen-Darmstadt (1736). Was noch übrig war, wurde 1676/1677 von französischen Truppen unter General Monclar zerstört.","w":"https://de.wikipedia.org/wiki/Burgruine_L%C3%B6wenstein"},"ch-Q458595":{"n":"Château Dauzac","c":"Schloss in Frankreich","r":"Château Dauzac ist ein französisches Weingut in der Appellation Margaux, auf der Halbinsel Médoc. Von 120 Hektar Gesamtfläche sind rund 45 Hektar mit Weinreben bestockt. Es erhielt 1855 im Rahmen der Bordeauxwein-Klassifikation den Rang eines 5ième Grand Cru.","h":"Die ersten Rebflächen wurden schon im 12. Jahrhundert durch Angehörige des Klosters von Sainte-Croix de Bordeaux angelegt; das eigentliche Weingut wird jedoch erst ab 1740 mit Graf Thomas Michel Lynch sowie dessen Sohn J.B. Lynch gegründet. Der 1669 in Galway geborene John Lynch kam im Rahmen der Flucht der Wild Geese nach Frankreich. Die Flucht der Wild Geese bezieht sich auf die Emigration einer irischen jakobinischen Armee unter dem Kommando von Patrick Sarsfield aus Irland nach Frankreich wie es im Vertrag von Limerick am 3. Oktober 1691 vereinbart wurde. In Bordeaux ließ sich John Lynch als Händler von Textilen, Wolle und Leder nieder und heiratete Guillemette Constant. Im Jahr 1710 wurde John Lynch als Franzose naturalisiert und nannte sich Jean Lynch. Sein Sohn Thomas-Michel heiratete im Jahr 1740 Elisabeth Drouillard. Als der Vater von Elisabeth, Pierre Drouillard im Jahr 1749 verstarb, erbte seine Tochter die Hälfte des Landbesitzes Bourdieu de BATGES und zahlte der Witwe von Pierre die Summe von 42.000 livres, um in den Alleinbesitz zu kommen. Dieses Jahr repräsentiert die Gründung des Château Lynch. Später erwarb er sowohl Ländereien zur Erweiterung von Château Lynch. Auch Château Dauzac gehörte zum Besitz der Familie Lynch. Im Jahr 1855 wurde es in den Stand eines fünften Gewächses in der damals neu eingeführten Klassifikation von Bordeauxweinen erhoben. Im Jahr 1865 erwarb Nathanial Johnston das Gut, nachdem er bereits im Jahr 1840 Mitinhaber an Château Latour wurde und später auch Château Ducru-Beaucaillou kaufte. Der Aufschwung des Guts wurde jedoch jäh von der Reblauskatastrophe und von dem wenig später auftretenden Falschen Mehltau unterbrochen. Die Erträge fielen auf unter 50 % eines normalen Durchschnittsjahres.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Dauzac"},"ch-Q464240":{"n":"Château La Tour Blanche","c":"Schloss in Frankreich","r":"Das Weingut Château La Tour Blanche liegt in der Gemeinde Bommes, einem Teil der Appellation Sauternes in der Weinbauregion Bordeaux. Bei der Bordeauxwein-Klassifizierung von 1855 wurde es als „Premier Cru Classé“ klassifiziert und damals auf den zweiten Platz hinter Château d’Yquem eingestuft. Das 70 Hektar große Gut verfügt über 40 Hektar Rebfläche sowie ausgedehnte Pappel und Pinienbestände. Die Fläche fällt im Westen hin zum Fluss Ciron ab.","h":"Im letzten Viertel des 18. Jahrhunderts wurde das Gut von Herrn Latour Blanche gegründet, der dem Gut seinen Namen gab und ebenfalls das heute noch bekannte Gutsgebäude bauen ließ. Wegen der Französischen Revolution wurde das Weingut an Pierre Pécherie überschrieben. Der Legende nach war es noch vor dem Château d’Yquem das erste Weingut in Sauternes, das edelsüße Weine herstellte. Der damalige deutschstämmige Besitzer Frederic Focke, der das Gut im Jahr 1815 erwarb, soll ab 1836 mit dem Verfahren der Beerenauslese experimentiert haben, so wie er es von den großen Gewächsen vom Rhein her kannte. Durch die berühmten Weinverkostungen von Hardy Rodenstock in den Jahren 1985 und 1987 wurde suggeriert, dass die Jahrgänge 1784 und wahrscheinlich auch schon der Jahrgang 1747 von Château d’Yquem edelsüße Weine waren. Die Echtheit dieser Flaschen wird jedoch angezweifelt. Ab 1862 wurde das Gut von Fockes Erbe Maître de Bordeaux sowie dessen Geschäftspartner Mermann, einem Weinhändler verwaltet. Der spätere Eigentümer Daniel Iffla, auch Osiris genannt (dieser Name steht heute noch auf dem Etikett), vermachte das Weingut 1909 dem französischen Staat unter der Bedingung, dass der Staat auf diesem Gelände eine Weinbaufachhochschule, die École de Viticulture et d’Œnologie de la Tour Blanche errichtet. Das Gut steht noch heute unter der Verwaltung des Landwirtschafts-Ministeriums.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_La_Tour_Blanche"},"ch-Q577444":{"n":"Schloss Champlâtreux","c":"Schloss im Département Val-d’Oise, Frankreich","r":"Das Schloss Champlâtreux wurde zwischen 1751 und 1757 vom Architekten Jean-Michel Chevotet erbaut. Es befindet sich in Épinay-Champlâtreux und war der Landsitz der Familie Molé, einer illustren Pariser Parlamentarierfamilie. Seit dem 19. Jahrhundert ist es der Wohnsitz der Familie Noailles.","h":"Das Land Champlâtreux wurde 1567 von Édouard Molé (1540–1614) erworben, der ab 1602 Président à mortier am Parlement von Paris war, und blieb seitdem in seiner Nachkommenschaft. Die Familie wird seitdem manchmal als „Molé de Champlâtreux“ bezeichnet, da das Land Champlâtreux für Édouard Molé (1609–1652), Sohn von Mathieu Molé (1584–1656), Erster Präsident des Parlements von Paris und Siegelbewahrer von Frankreich, zum Marquisat erhoben wurde. Mathieu-François Molé (1705–1793), Präsident des Pariser Parlaments, verwendete einen Teil des riesigen Vermögens seiner Frau Bonne-Félicité Bernard, Tochter des Finanziers Samuel Bernard, um das bescheidene Haus im Louis-treize-Stil, das er von seinen Vorfahren geerbt hatte und das 1750 abgerissen wurde, in einem viel größeren Maß wieder aufzubauen. In den Jahren von 1735 bis 1740 waren die beiden von der D 316 aus sichtbaren Wachpavillons bereits nach den Plänen des Architekten Jean-Michel Chevotet errichtet worden. Die französischen Gärten und die Demi-lune vor dem Eingang wurden ebenfalls von diesem Architekten in dieser Zeit entworfen; von 1751 bis 1757 leitete er den Bau des Schlosses, der Ställe und der Orangerie, die in einem sehr kurzen Zeitraum fertiggestellt wurden. Die Bauarbeiten kosteten die relativ angemessene Summe von 513.507 Livres, wenn man die Pracht des Anwesens bedenkt. Um die Kosten einhalten zu können, hatte Chevotet eine Ziegelei gegenüber dem Schloss errichtet, Gipsstein, der auf dem Grundstück gefunden wurde, für die Herstellung von Gips verwendet, Holz aus den umliegenden Wäldern geholt und Stein aus den Steinbrüchen von Luzarches, Gascourt und Saint-Maximin bezogen.","w":"https://de.wikipedia.org/wiki/Schloss_Champl%C3%A2treux"},"ch-Q1011487":{"n":"Burg Dourdan","c":"Burg in Frankreich","r":"Die Burg Dourdan in der Stadt Dourdan zwischen Paris und Chartres ist eine typische Befestigung vom Beginn des 13. Jahrhunderts. Sie wurde im Auftrag König Philipp II. gebaut, um eine hölzerne Befestigung zu ersetzen. Der Burggraben wurde ähnlich wie beim Louvre angelegt.","w":"https://de.wikipedia.org/wiki/Burg_Dourdan"},"ch-Q577783":{"c":"Schloss in Frankreich"},"ch-Q1011967":{"n":"Burg Girsberg","c":"Burg in Frankreich","r":"Die Burg Girsberg ist die Ruine einer Spornburg auf dem Gebiet der französischen Gemeinde Ribeauvillé im Elsass. 1288 erstmals in Urkunden erwähnt, erhielt die kleine Burg ihren heutigen Namen von ihren Besitzern im 14. und 15. Jahrhundert: den Herren von Girsberg.","h":"Die Entstehungszeit der ersten Burganlage ist nicht genau datierbar. Die aus dieser Bauphase noch erhaltenen architektonischen Merkmale deuten auf eine Errichtung in der ersten Hälfte des 13. Jahrhunderts hin. Demnach erbaute wohl ein Zweig der Herren von Rappoltstein die Burg als Wohnsitz. Infolge eines Blitzeinschlags am 10. Juli 1288 brannte ein Großteil der damaligen Burg ab, wurde jedoch anschließend wieder aufgebaut. Nachdem sie 1298 durch Erbteilung an Anselm II. von Rappoltstein gekommen war, tauschte dieser sie 1304 unter anderem gegen den Stammsitz der Herren von Girsberg nahe Soultzbach-les-Bains im Münstertal. Die Rappoltsteiner behielten als Lehnsherren jedoch sowohl das Vorkaufs- als auch das Öffnungsrecht für den Stein. Die Girsberger erneuerten die Burg, die fortan nach ihnen benannt wurde. Ihre Herrschaft endete am 11. Juni 1422, als Hans Wilhelm von Girsberg mit Maximin I. Smassmann von Rappoltstein in Fehde lag. Der Rappoltsteiner belagerte sie gemeinsam mit dem Grafen Hans von Lupfen, konnte sie einnehmen und steckte die Anlage in Brand. Hans Wilhelm von Girsberg wurde dabei erschossen. Da er kinderlos war, fiel Burg Girsberg als erledigtes Lehen zurück an die Herren von Rappoltstein, die sie ab 1458 durch einen Burgvogt verwalten ließen. Während des 15. Jahrhunderts fand ein umfassender Neubau statt, bei dem die Kernburg vergrößert wurde. Neben der Erhöhung des Bergfrieds ließen die Rappoltsteiner in dieser Zeit wahrscheinlich auch den romanischen Wohnbau aufstocken. Sein oberstes Geschoss datiert in die zweite Hälfte des 15. Jahrhunderts. Zu Beginn des 16. Jahrhunderts war die Burg noch bewohnt, wurde dann aber verlassen, sodass anschließend ein allmählicher Verfall einsetzte.","w":"https://de.wikipedia.org/wiki/Burg_Girsberg"},"ch-Q1012467":{"n":"Burg Hohrappoltstein","c":"Burg in Frankreich","r":"Die Burg Hohrappoltstein ist die Ruine einer Höhenburg nordwestlich von Ribeauvillé im elsässischen Département Haut-Rhin. Sie gehört mit den Burgen St. Ulrich und Girsberg zu den drei nahe beieinanderliegenden Rappoltsteiner Burgen, welche die Stadt überragen.","h":"Die Burg wurde zwar erst 1254 erstmals urkundlich erwähnt, ihr Standort war aber schon in der Bronze- und Hallstattzeit besiedelt, was Funde von entsprechend datierten Keramikscherben beweisen. Zusätzlich wurden auf dem heutigen Burgareal oder in dessen Umgebung Scherben aus der Eisenzeit und römische Münzen gefunden, die eine lange Tradition der Besiedelung belegen. Etwa im 9. bis 11. Jahrhundert entstand eine durch mehrere Wälle und Gräben gesicherte Vorgängeranlage der heutigen Burg. Von dieser etwa 150 × 80 Meter messenden Befestigung sind Reste der nördlichen Hälfte erhalten. Ihr südlicher Teil wurde in der ersten Hälfte des 13. Jahrhunderts mit der heutigen Anlage überbaut. Die 1254 genannten Herren von Altenkastel waren wahrscheinlich Niederadelige aus dem Gefolge der Rappoltsteiner, die Burgmannen von Hohrappoltstein waren. Die Burg war anfänglich ein Lehen des Bischofs von Bamberg, doch dieser verlor die Hoheit über die Anlage im Laufe der Zeit an das Bistum Basel. Wie das Bamberger Bistum in den Besitz dieser weit entfernt gelegenen Anlage kam, ist unklar. Möglicherweise war sie anfänglich Reichsbesitz, den König Heinrich II. dem Bistum 1007 bei seiner Gründung schenkte. Schon 1268 erkannten die Rappoltsteiner den Basler Bischof als Lehnsherrn ihrer Burg Hohrappoltstein an, doch noch im 14. Jahrhundert reklamierte Bamberg die Lehnshoheit für sich. Für 1288 ist Anselm von Rappoltstein als Besitzer belegt, denn ihm fiel in jenem Jahr neben der benachbarten Burg St. Ulrich bei einer Teilung der Rappoltsteiner Güter auch die Burg Hohrappoltstein zu. 1368 wurde Bruno I. von Rappoltstein Burgherr. Er trat 1369 in den Dienst des burgundischen Herzogs Philipps des Kühnen und kämpfte gemeinsam mit französischen Soldaten im Hundertjährigen Krieg gegen die Engländer.","w":"https://de.wikipedia.org/wiki/Burg_Hohrappoltstein"},"ch-Q1012510":{"n":"Burg Hugstein","c":"Burg in Frankreich","r":"Burg Hugstein ist heute eine Ruine. Die Hangburg beherrschte den Eingang zum Tal des Murbachs. Sie erhielt den Namen von ihrem Erbauer, Hugo von Rothenburg, Abt des nahe gelegenen Klosters Murbach, der sie als Residenz sowie zur Kontrolle Gebweilers und des Lauchtals errichten ließ. Die Ruine ist als Monument historique klassifiziert und steht seit dem 6. Dezember 1898 unter Denkmalschutz. Eigentümerin ist die Gemeinde Buhl.","h":"Johann Paulus Deck gibt in seiner Beschreibung der Stadt Gebweiler (Gebweiler vor der grossen Revolution) das Jahr 1227 als Gründungsdatum der Burg Hugstein an, ohne allerdings seine Quellen für diese Angabe zu benennen. Die Chronik des Klosters Murbach berichtet hingegen davon, dass Abt Hugo von Rothenburg die Anlage erst 1230 errichten ließ, sodass nur dieses Datum als gesichert gelten kann. Sie ist damit die älteste urkundlich gesicherte Burg eines Klosters im Elsass. Sie diente den Murbacher Äbten seit ihrer Erbauung als Wohnsitz. Unter dem Abt Konrad von Stauffenberg wurde Hugsteins Burgkapelle 1313 dem heiligen Benedikt und dem heiligen Kreuz geweiht. Bartholomäus von Andlau, der von 1447 bis 1476 Abt von Murbach war, ließ diverse Instandsetzungsarbeiten an der Burg durchführen und wahrscheinlich auch den Torturm errichten. Zudem ließ er die Anlage durch zwei Türme und eine zusätzliche Umfassungsmauer verstärken. Anfang des 16. Jahrhunderts diente sie unter Georg von Masmünster als Gefängnis für Häretiker, das heißt für Protestanten und Hexen. Im Jahr 1542 musste sich Burg Hugstein in einem Nachfolgestreit das einzige Mal in ihrer Historie militärisch bewähren. Als der Murbacher Dekan Heinrich von Istetten mit der Wahl von Rudolf Stoer von Stoerenberg zum neuen Abt nicht einverstanden war, weil er dessen Position für sich beanspruchte, besetzte er die Burg kurzerhand. Als er von seinem Widersacher jedoch belagert wurde, gab er auf und wurde im „grossen thurm“ gefangen gesetzt. Die Burg wurde noch im gleichen Jahr möglicherweise vom Murbacher Abt selbst zerstört. Nach der Zerstörung wurde sie verlassen und 1598 durch einen Blitzschlag weiter beschädigt.","w":"https://de.wikipedia.org/wiki/Burg_Hugstein"},"ch-Q1013802":{"n":"Burg Sagonne","c":"Burg in Frankreich","r":"Die Burg Sagonne liegt in der Gemeinde Sagonne im französischen Département Cher. Teile der Anlage stehen bereits seit Mai 1914 als Monument historique unter Denkmalschutz.","h":"Der Ursprung der Anlage von Sagonne ist gallo-römisch. Der erste bekannte Besitzer war Wicfried, Graf von Bourges, der das Anwesen 832 seiner Tochter Agarve als Mitgift gab. Deren Nachkommen besaßen die Burg bis in das 16. Jahrhundert. Im 14. Jahrhundert hielt die um 1300 erneuerte Befestigung den Angriffen der Engländer und der Grandes Compagnies stand, die dafür das umliegende Land verwüsteten. Der Connétable Louis de Sancerre richtete in Sagonne 1383 vier jährliche Märkte sowie einen samstäglichen Wochenmarkt ein. Im 15. Jahrhundert heiratete Pierre d’Amboise die Erbin des Anwesens, Anne de Bueil, und nahm als Seigneur von Sagonne bedeutende Umbauten vor. Sein Sohn Charles, zugleich Herr von Meillant und von Chaumont-sur-Loire, ein Vertrauter Ludwigs XII., setzte den begonnenen Umbau fort. 1542 wurde die Burg an Jean Babou verkauft. Als Großvogt der Touraine, Gouverneur von Gien und Brest und als außerordentlicher Botschafter in Rom erhielt Jean Babou von König Karl IX. das Amt des Artilleriebefehlshabers. Für den jüngsten Sohn von Jean Babou, der ebenfalls Jean hieß, erhob Heinrich III. die Baronie Sagonne zur Grafschaft. 1631 gelangte die Burg in den Besitz von Charles de L’Aubespine. 1699 wurde dann Jules Hardouin-Mansart der Besitzer und erhielt als Architekt Ludwigs XIV. auch noch den Grafentitel. Mansart bemühte sich, die feudale Burg der neuen Zeit anzupassen. Er ließ einen Teil der Ringmauer abreißen, im Osten entlang der Gräben Terrassen einrichten und eine breite Allee anlegen. Außerdem wurde der Burgeingang an die Seite der Teiche verlegt. Auf der Nordseite kam ein großes Gebäude und eine ausgedehnte, von Mauern umschlossene Gartenanlage im französischen Stil hinzu.","w":"https://de.wikipedia.org/wiki/Burg_Sagonne"},"ch-Q1013408":{"n":"Burg Ochsenstein","c":"Burg in Frankreich","r":"Die Burg Ochsenstein ist eine elsässische Felsenburg, die sich in der Gemeinde Reinhardsmunster befindet. Sie besteht aus den drei unmittelbar benachbarten Anlagen Groß-Ochsenstein, Klein-Ochsenstein und Wachelheim. Die Burg war der Stammsitz des gleichnamigen elsässischen Adelsgeschlechts, das im Mittelalter die Herrschaft Ochsenstein begründete.","h":"Der Burgberg war schon in prähistorischer Zeit besiedelt, doch erst im Jahr 1186 erscheint der Name „Ochsenstein“ mit Otto I. von Ochsenstein, Sohn Ottos von Geroldseck, erstmals schriftlich. Wegen der Nennung des Familiennamens kann davon ausgegangen werden, dass die Burg Ochsenstein zu jener Zeit schon existierte und von der Familie von Geroldseck erbaut worden war. Als Otto I. 1217 erkrankt war, regelte er seinen Nachlass und teilte den Besitz unter seinen drei Söhnen auf. Durch die entsprechende Urkunde ist belegt, dass es zu jener Zeit schon mehr als eine Anlage auf dem Burgberg gab. Ottos ältester, Otto II., erhielt den südlichen Felsen und das darauf stehende Groß-Ochsenstein. Der Sohn Eberhard bekam das Burghaus (domus) der Vögte von Wasselnheim zugesprochen, das sich vermutlich auf dem mittleren Felsen befand. Eberhard nutzte dies jedoch nie als Wohnsitz, sondern bezog nach dem wohl baldigen Tod seines jüngsten Bruders Conrad dessen Burg Greifenstein, die sechs Kilometer weiter nördlich bei Saverne liegt. Als Otto II. um 1240 Kunigunde von Habsburg, die Schwester des späteren Königs Rudolf I., heiratete, begann der Aufstieg der Ochsensteiner zu einem der bedeutendsten Adelsgeschlechter des Unterelsass. Ottos II. und Kunigundes erstgeborener Sohn Otto III. begleitete seinen königlichen Onkel auf Kriegszügen und Unternehmungen vor allem in Böhmen. Als Dank für seine Loyalität und Treue ernannte ihn Rudolf I. zum Landvogt (französisch bailli provincial) im Elsass und Breisgau. 1284 wurde ein Teil der Burg belagert, eingenommen und zerstört. Mit Gewissheit handelte es sich dabei um Klein-Ochsenstein und möglicherweise auch um den Nordteil der Anlage.","w":"https://de.wikipedia.org/wiki/Burg_Ochsenstein"},"ch-Q1013503":{"n":"Burg Pirou","c":"Burg in Frankreich","r":"Die Burg Pirou steht unweit von Lessay auf der Halbinsel Cotentin in der Normandie in Frankreich. Die inmitten eines künstlichen Sees gelegene Niederungsburg ist eine Befestigung aus dem 12. Jahrhundert und wurde im 17. Jahrhundert schlossartig umgestaltet.","w":"https://de.wikipedia.org/wiki/Burg_Pirou"},"ch-Q1090442":{"n":"Château Filhot","r":"Das Weingut Château Filhot liegt in der Gemeinde Sauternes, einem Teil der Appellation d’Origine Contrôlée Sauternes in der Weinbauregion Bordeaux. Bei der Bordeauxwein-Klassifizierung von 1855 wurde es als „Deuxième Cru Classé“ klassifiziert. Das Gut verfügt über einen Grundbesitz von 350 ha, wovon 62 Hektar Fläche mit Weinreben bepflanzt sind. Die Rebflächen liegen nordwestlich des Gutsgebäudes. Durch eine tiefe Krise konnte das Weingut im 20. Jahrhundert die hohe Qualitätseinstufung nur sehr selten bestätigen.","h":"Im Jahr 1709 erwarb Romain de Filhot (1641–1710), Mitglied des Parlements von Bordeaux und späterer Gründer der Appellation Sauternes, in der südlich ausgerichteten Gemarkung vins de Langon einige Rebflächen. Es wird angenommen, dass die Rebflächen in den Jahren 1630–1650 angelegt wurden. Während nahezu eines Jahrhunderts blieb das Weingut im Besitz der Familie. Die Leitung des Gutes ging von Romain de Filhot auf seinen Sohn Jean-Jacques und später auf seinen Enkel Jean François-Xavier über. Beide waren ebenfalls Mitglieder des Parlements. In vierter Generation leitete Gabriel Barthélémy Romain de Filhot (25. Februar 1746 – 11. Juli 1794) das Gut. Der Präsident des Parlements führte das Gut zu seiner Blüte. In einem Schreiben vom Mai 1787 bescheinigt Thomas Jefferson den Weinen den Rang eines erstklassigen Sauternes, die die gleichen Preise wie Château d’Yquem erreichten. Im Jahr 1788 erwarb Gabriel Barthélémy Romain de Filhot das Château Coutet. Nur sechs Jahre später wurde er im Rahmen der französischen Revolution hingerichtet. Seine einzige Tochter Marie Geneviève Françoise Joséphine de Filhot war zu diesem Zeitpunkt noch sehr jung. Durch ihre Hochzeit im Jahr 1807 mit Antoine Marie Henry Amédée de Lur-Saluces gehörten Château d’Yquem, Château Coutet, Château de Malle, Château de Fargues sowie Château Filhot der gleichen Familie. Der Sohn Romain Bertrand de Lur-Saluces erweiterte im Jahr 1840 Château Filhot noch durch den Zukauf des Weingutes Pineau de Rey. Fünf Jahre später ließ er das noch heute existierende Gutsgebäude nach dem Vorbild des Lustschlosses Petit Trianon errichten. Die Parkanlage wurde Louis-Bernard Fischer gestaltet. Im Jahr 1855 wurde das Weingut als „Deuxième Cru Classé“ klassifiziert und wurde in der Folge als Château Sauternes vermarktet.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Filhot"},"ch-Q1090622":{"n":"Château Pontet-Canet","c":"Schloss in Frankreich","r":"Château Pontet-Canet ist ein französisches Weingut innerhalb der Appellation Pauillac auf der Halbinsel Médoc bei Bordeaux.","h":"Die Besitzverhältnisse der landwirtschaftlichen Nutzflächen lassen sich bis in das frühe 14. Jahrhundert zurückverfolgen. Im Jahr 1311 gehörten die Flächen dem Lehnsherrn Pons de Castillon. In der Folge wurde der Besitz in der Familie weitervererbt. Im 15. Jahrhundert kamen die Ländereien an Humphrey, Duke of Gloucester, den jüngeren Bruder von Heinrich V. Nach der englischen Niederlage im Hundertjährigen Krieg ging der vormals englische Besitz in französische Hände über. Über die Familie Foix kam ein kleiner Teil des Besitzes an den Notar Jacques de Ségur. Damals gehörten nicht nur kleinere Parzellen des heutigen Châteaus zu den Ländereien. Jacques de Ségur legte auch ab 1670 die ersten Rebflächen auf dem Gelände des heutigen Château Lafite-Rothschild an. Sein Sohn Alexandre heiratete im Jahr 1695 die Erbin von Château Latour. Aus dieser Ehe ging der Sohn Nicolas-Alexandre de Ségur (1697–1755) hervor. Nachdem Nicolas-Alexandre den Besitz von Mouton im Jahr 1717 erweiterte und Château Calon-Ségur kaufte, verkaufte er Mouton bereits 1720 (andere Quellen nennen das Jahr 1725) an Joseph de Brane und leitete damit die Trennung von Mouton und Lafite ein. Ein vorhandenes Gutsgebäude sowie der mittlere Teil der Ländereien ging an Dominique Armailhacq und bildeten den Beginn von Château d’Armailhac. François de Pontet, Gouverneur des Médoc, kaufte den südlichsten Teil des Landbesitzes einige 100 m oberhalb der Gironde. Seine Nachkommen fügten 1757 dem Besitz durch den Ankauf das Flurstück namens Canet hinzu, auf dem sich auch ein Haus gleichen Namens befand. Seit dieser Zeit wurde der dort erzeugte Wein unter der Bezeichnung Pontet-Canet gehandelt.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Pontet-Canet"},"ch-Q1090719":{"n":"Fort du Hâ","c":"Burg in Bordeaux, Frankreich","r":"Die Burg Le Hâ war eine Zwingburg zur Kontrolle von Bordeaux, von der nur mehr geringe Teile erhalten sind. Die Anlage ist seit dem Jahr 1965 in Teilen als Monument historique eingestuft.","h":"König Charles VII ließ nach dem Ende des Hundertjährigen Kriegs und seiner Eroberung von Bordeaux zwei Festungen errichten, die die permanente Kontrolle über die Stadt sichern sollten: das Château Trompette und das Château du Far (später Hâ). Für letzteres wurde der Grundstein am 24. Januar 1456 gesetzt. In der Folge residierte hier Charles de Valois, der Bruder Ludwigs XI. Im Oktober 1572 diente es als Zufluchtsstätte für Protestanten nach der Bartholomäusnacht. 1650 zur Zeit der Fronde war hier eine Verteidigungsstellung gegen die Bordeaux belagernden königlichen Truppen. Ab 1731 diente die Anlage hauptsächlich als Gefängnis. Mehrfache Pläne, es abzureißen, scheiterten an den Zeitumständen. 1835 begann allerdings die tatsächliche Demolierung, mit Ausnahme zweier noch heute erhaltener Türme. Diese wurden am 14. August 1845 als Monument historique unter Denkmalschutz gestellt. Am 19. November 1846 wurde der neue Gefängnisbau eröffnet (Architekt war Joseph Thiac). Während der Deutschen Besetzung Frankreichs im Zweiten Weltkrieg diente der Turm als politisches Gefängnis, unter anderem für Édouard Daladier, Georges Mandel und den bonapartistischen Prätendenten Napoléon Louis Bonaparte. Auch Widerstandskämpfer wurden in der Burg Le Hâ interniert. Einige wurden von dort in KZs deportiert, andere im Camp du Souge erschossen. Nach der Befreiung wurde die Festung auch für die Inhaftierung von Kollaborateuren und weiteren Gefangenen benutzt, beispielsweise des Deutschen Friedrich-Wilhelm Dohse, der in Bordeaux die Leitung der Gestapo mitzuverantworten hatte. Eine Gedenktafel trägt die Inschrift: „Nach Errichtung eines neuen Gefängnisses wurde der Bau aus dem 19. Jahrhundert demoliert und an seiner Stelle eine Verwaltungshochschule errichtet.“","w":"https://de.wikipedia.org/wiki/Burg_Le_H%C3%A2"},"ch-Q1090725":{"n":"Château d’Issan","c":"Schloss in Frankreich","r":"Das Château d’Issan ist eines der bekannten Weingüter von Bordeaux. Seit der Klassifikation von 1855 ist das Weingut als Troisieme Grand Cru Classé eingestuft, dritthöchste Stufe der Klassifikationen.","h":"Seit spätestens dem 14. Jahrhundert ist die Gemarkung des heutigen Landbesitzes bereits als Teoban bekannt; aber es wird berichtet, dass bei der Hochzeit von Henry Plantaget und Eleonore von Aquitanien im Jahr 1152 bereits Weine von Teobon gereicht wurden. Ab dem 15. Jahrhundert befand sich mit dem ehemaligen Château Teobon eines der befestigten Gebäude entlang der Gironde, die während der englisch-französischen Auseinandersetzungen errichtet wurden. Das Gebäude wurde erst im Jahr 1453 von den englischen Soldaten aufgegeben. Noalhan ist die erste namentlich bekannte Familie, die als Seigneurs von La Motte de Ludon und Cantenac den Landbesitz verwaltete. Später ging das Landrecht auf die Familie Meyrac über. Von Thomas de Meyrac (gestorben 1464) ging das Erbe an seinen Sohn Jean de Meyrac und im Jahr 1507 an Isabeau de Meyrac. Isabeau hatte im Jahr 1475 Giron de Ségur geheiratet. Das Gut ging folglich in den Besitz der Familie de Ségur über, die zwischenzeitlich die Weingüter Lafite, Latour und kurzzeitig Mouton besaß. Mit der Heirat der Enkelin von Isabeau, Catherine de Ségur de Théobon, mit Hélie de Salignac im Jahr 1510 (andere Quellen sprechen vom Jahr 1527) ging das Gut an die Familie de Salignac. In der Erbfolge ging es Anfang des 17. Jahrhunderts an Mademoiselle La Ferrière und ca. vierzig Jahre später an Marguerite de Lalanne. Marguerite heiratete Sarran François d’Essenault. Später riss Pierre d’Essenault das vorhandene Gutsgebäude ab und errichtete das heute noch existierende Château. Durch eine Verballhornung des Namens Essenault entstand der Name Issan. Bis zum Jahr 1760 blieb Château d’Issan im Besitz der Familie d’Essenault, bevor es an die beiden Vettern Bernard de Candale de Foix und Joseph de Castelnau d’Essenault ging.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_d%E2%80%99Issan"},"ch-Q1230965":{"n":"Schloss La Roche-Guyon","c":"Schloss in Frankreich","r":"Das Schloss La Roche-Guyon ist der Nachfolgebau einer mittelalterlichen Burg, die auf einem Kalksteinfelsen im Seinebogen oberhalb des Ortes La Roche-Guyon etwa 65 km nordwestlich von Paris im heutigen Département Val-d’Oise errichtet worden war.","w":"https://de.wikipedia.org/wiki/Schloss_La_Roche-Guyon"},"ch-Q1256985":{"n":"Drei Exen","c":"Burg in Frankreich","r":"Die Drei Exen sind eine Höhenburgen­gruppe in den Vogesen im Oberen Elsass. Die Gruppe besteht aus Dagsburg, Wahlenburg und Burg Weckmund.","h":"Bereits um 1016 wird in der Biographie Papst Leos IX., der vor seinem papalen Amt Bruno von Egisheim hieß, eine Burg auf dem Schlossberg erwähnt, die nach derzeitigem Stand der archäologischen Grabungen aus dem 10. oder frühen 11. Jahrhundert stammt und damit älter war als jede der drei Burgen, deren Ruinen heute noch stehen. Zu dieser ursprünglichen Burg gehörten die Pankratius­kapelle und zumindest ein großer Ringwall, deren Reste sich in der Nordwest- und der Südwestecke des Plateaus nachweisen lassen; sie muss deutlich größer gewesen sein als die spätere Gesamtanlage. 1144 fiel nach dem Aussterben der Grafen von Egisheim der Nordteil des Plateaus den Grafen von Dagsburg zu, die sich fortan Grafen von Dagsburg-Egisheim nannten. Sie erbauten auf den bestehenden Mauern oder Mauerresten die Nordburg der drei Exen, die sie ebenfalls Dagsburg tauften. Der Bau der südlichen Burganlage erfolgte kurze Zeit später und vermutlich als Reaktion auf die Errichtung der Dagsburg. Erst um 1200 wurde die Südburg noch einmal geteilt und ein zweiter Bergfried gebaut. Im Jahre 1225 starb das Geschlecht der Grafen von Dagsburg-Egisheim, die eines der mächtigsten Adelshäuser des Elsass geworden waren, aus. Daraufhin bemächtigten sich die Bischöfe von Straßburg eines großen Teils der Hinterlassenschaft, unter anderem der Dagsburg auf dem Schlossberg.","w":"https://de.wikipedia.org/wiki/Drei_Exen"},"ch-Q628587":{"c":"Schloss in Frankreich"},"ch-Q665265":{"n":"Schloss Ambleville","c":"Schloss in Frankreich","r":"Das Schloss in Ambleville, einer Gemeinde im Département Val-d’Oise in der französischen Region Île-de-France, wurde Anfang des 16. Jahrhunderts errichtet. Seit 1926 steht das Schloss als Monument historique auf der Liste der Baudenkmäler in Frankreich. Es liegt rund 65 Kilometer nordwestlich von Paris.","h":"Das Schloss wurde Anfang des 16. Jahrhunderts an der Stelle einer Festung (seit dem 11. Jahrhundert nachgewiesen) errichtet, die die Grenze zur Normandie verteidigte. Der Architekt Jean Grappin schuf diesen Bau für Louis de Mornay. Im 18. Jahrhundert wurde das Schloss im Stil des Klassizismus umgebaut. 1893 kaufte es der reiche Kunsthändler Charles Sedelmeyer und ließ es mit großem Aufwand restaurieren. Hinter dem Schloss ließ die Marquise de Villefranche, die neue Besitzerin, ab 1928 einen terrassenartigen Park, der heute zu den Jardin remarquable zählt, nach italienischem Vorbild anlegen.","w":"https://de.wikipedia.org/wiki/Schloss_Ambleville"},"ch-Q785590":{"c":"Schloss in Frankreich"},"ch-Q787703":{"c":"Burg in Frankreich"},"ch-Q928663":{"c":"Schloss in Frankreich"},"ch-Q937188":{"n":"Château Doisy-Védrines","c":"Schloss in Frankreich","r":"Das Weingut Château Doisy-Védrines liegt in der Gemeinde Barsac, einem Teil der Appellation d’Origine Contrôlée Barsac in der Weinbauregion Bordeaux. Die Weine werden jedoch unter dem wesentlich bekannteren Namen Sauternes vermarktet. Bei der Bordeauxwein-Klassifizierung von 1855 wurde es als „Deuxième Cru Classé“ klassifiziert. Das Gut verfügt über 27 Hektar Fläche. Die Rebflächen liegen nur unweit von den ehemaligen Schwestergütern Château Doisy Daëne und Château Doisy-Dubroca sowie von Château Climens und Château Coutet entfernt. Der älteste Teil des Gutsgebäudes ist ein runder Turm aus dem 16. Jahrhundert.","h":"Die Geschichte des Guts lässt sich bis in das 17. Jahrhundert zurückverfolgen, als Jean Raymond im Februar 1677 ein Gut namens Doisic übernahm. Die Familie Védrines kam am 5. Juni 1704 durch die Hochzeit von Jean-Baptiste Védrines mit der Enkelin von Jean, Marie Raymond in den Besitz des Anwesens und der landwirtschaftlichen Nutzflächen im Weiler La Pinesse. Die ersten Rebflächen wurden vermutlich erst von den Nachkommen von Jean-Baptiste und Marie angelegt. Nach 1794 erwarben die Eigentümer eine Parzelle von Château Coutet. Eine erste lobende Erwähnung eines Weinguts findet sich in dem 1832 erschienenen Werk Topographie de tous les vignobles connus von André Jullien. Unbekannt ist, wann die historische Einheit Doisy geteilt wurde. Im Jahr 1850 gehörte der größte Teil des Anwesens noch Madame Dubosq, die vermutlich eine direkte Nachfahrin der Védrines-Familie war. Im Jahr 1851 verkaufte Madame Dubosq das Weingut an die Familie Boireau. Diese Einheit wurde später als Château Doisy-Védrines bekannt. Die Familie Faux übernahm einen zum Verkauf anstehenden Teil, der als Château Doisy-Dubroca heute noch bekannt ist. Der Weinhändler Jean Jacques Emmanuel Daëne erwarb die zweite verkäufliche Parzelle, die später unter dem Namen Château Doisy Daëne geführt wurde. Im Jahr 1855 wurde allen drei Gütern anlässlich der Bordeaux-Klassifizierung ein Rang eines Deuxième Cru Classé zugesprochen. Das Weingut Doisy-Védrines blieb lange in den Händen der Familie Boireau, den direkten Vorfahren der Familie Castéja. Erst mit 94 Jahren überließ Madame Teyssonneau die Leitung ihrem Enkel Pierre Castéja. Heute leitet Olivier Castéja die Geschicke des Guts.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Doisy-V%C3%A9drines"},"ch-Q955839":{"n":"Schloss Cons-la-Grandville","c":"Schloss in Frankreich","r":"Das Schloss Cons-la-Grandville ist eine Schlossanlage im lothringischen Département Meurthe-et-Moselle. Es befindet sich im Ortskern von Cons-la-Grandville rund sieben Kilometer südwestlich von Longwy und gilt als „eines der schönsten Renaissancebauwerke Lothringens“.","h":"Bereits Ende des 11. Jahrhunderts stand am Ort des heutigen Schlosses eine Burg, die zu jener Zeit Dudon de Cons, einem Weggefährten Gottfried von Bouillons während des ersten Kreuzzugs, gehörte. Er wurde im Jahr 1088 erstmals urkundlich erwähnt, als er mit seiner Frau Hadwige, einer Tochter des Grafen von Chiny, ein Priorat neben seiner Burg stiftete. Diese erste Burganlage wurde vor 1248 für Jacques de Cons umgebaut und vergrößert. Von dieser Anlage sind heute noch ein runder Eckturm im Vorburgbereich und ein Teil der Ostmauer erhalten. Im Laufe ihrer Geschichte wurde die Seigneurie Lagrandville immer wieder geteilt, sodass sie schon im 13. Jahrhundert zersplittert war. Jacqueline de Cons brachte einen Teil der Burg und Herrschaft an ihren Mann Renaud de Neufchâteal de Varize. Andere Erbtöchter der Familie heirateten Theobald de Custine und Robert de Housse. Ein Viertel der Herrschaft gelangte 1430 durch Heirat an Heinrich von Hagen (de la Haye) aus einem saarländischen Adelsgeschlecht. Der Familie Custine gelang es nach und nach, den gesamten Besitz an sich zu bringen und vereinte damit um 1520 wieder alles in einer Hand. Martin de Custine ließ ab 1572 auf den Grundmauern der alten Burg einen Neubau im Stil der Renaissance errichten. Daran erinnert eine Inschrift an der Außenfassade des Schlosses. Marguerite de Custines, Tochter von Jean-Baptiste de Custine und seiner Frau Dorothée de Ligniville, heiratete 1641 den Grafen Jean de Lambertye und brachte das Schloss als Mitgift in die Ehe. Es ist noch heute Eigentum der Familie de Lambertye. Im Dreißigjährigen Krieg wurde die Anlage durch schwedische Truppen stark beschädigt. Erste Reparaturen fanden 1688 statt. Ein Wiederaufbau erfolgte erst ab 1730 unter Marguerites Enkel Nicolas-François der Lambertye.","w":"https://de.wikipedia.org/wiki/Schloss_Cons-la-Grandville"},"ch-Q1011211":{"n":"Burg Brosse","c":"Burg in Frankreich","r":"Die Burg Brosse ist eine Burgruine auf dem Gebiet der Gemeinde Chaillac im Département Indre gelegen, südöstlich des eigentlichen Ortes.","w":"https://de.wikipedia.org/wiki/Burg_Brosse"},"ch-Q1333377":{"n":"Schloss Cordès","c":"Schloss in Frankreich","r":"Das Schloss Cordès steht 900 m hoch in der Gemeinde Orcival im Département Puy-de-Dôme in der französischen Region Auvergne-Rhône-Alpes. Es steht seit Juli 1926 als Monument historique unter Denkmalschutz.","h":"Im Jahre 1268 gehörte die damalige Burg zum Besitz von Wilhelm von Chalus (französisch Guillaume de Chalus). Fast 400 Jahre lang blieb sie im Besitz seiner Familie. Im Jahre 1659 wurde die Anlage an Emmanuel d’Allègre verkauft. Sein Sohn Yves d’Allègre, marquis de Tourzel, wurde 1724 Marschall von Frankreich. Unter seiner Herrschaft wurden die Gebäude renoviert, zu einem Schloss ausgebaut und erhielten ihr heutiges Aussehen. Die Gartenanlage wurde im Jahr 1695 von André Le Nôtre gestaltet. Als oberster Gartenarchitekt Ludwigs XIV. konzipierte er den Stil des französischen Barockgartens. Schloss Cordès ist Schauplatz des Romans Le démon de midi von Paul Bourget aus dem Jahr 1914.","w":"https://de.wikipedia.org/wiki/Schloss_Cord%C3%A8s"},"ch-Q1333422":{"n":"Schloss Ravel","c":"Schloss in Frankreich","r":"Das Schloss Ravel steht in der Gemeinde Ravel, im auvergnatischen Département Puy-de-Dôme. Es geht auf eine mittelalterliche Burg aus dem 12. Jahrhundert zurück. Im 18. Jahrhundert wurde es erweitert, ohne den gotischen Kern zu zerstören. Zusätzlich wurde es durch eine Gartenanlage von André Le Nôtre ergänzt. Es diente als Kulisse für den Film Die Kinder des Monsieur Mathieu.","h":"Der Bau des Schlosses wurde im Jahr 1171 von Bernard de Revel begonnen. Im Jahr 1283 verkaufte Chatard de Ravel die Anlage an König Philipp III. von Frankreich. Die Burg wurde im Jahr 1294 von Philipp dem Schönen an Pierre Flote, den Kanzler von Frankreich, als Lohn für seine Dienste weitergereicht. Pierre Flote spielte eine Schlüsselrolle in den schweren Konflikten der Krone mit Papst Bonifatius VIII. Er war maßgeblich an der Ausarbeitung der Anklageschrift gegen Bernard Saisset, den Bischof von Pamiers, beteiligt und verfasste eine scharfe Erwiderung auf die päpstliche Bulle Ausculta fili. Der Papst reagierte mit heftigen Schmähungen gegen den einäugigen Kanzler und nannte ihn blind an Geist und Körper. Flote fiel am 11. Juli 1302 in der Sporenschlacht bei Kortrijk. Sein Sohn Guillaume Flote übernahm ebenfalls das Amt des Kanzlers von Frankreich unter König Philipp VI. und zeichnete sich durch eine kompromisslose Justiz aus. Da Guillaume Flote in dritter Generation keine männlichen Nachkommen hinterließ, ging Ravel nach dem Tod seines Enkelsohns im Jahr 1431 durch die Heirat von Jeanne Flote mit Jean de Bueil an die Familie de Bueil über, ehe es 1460 durch eine Allianz an Antoine d’Amboise gelangte. Nach heirats- und erbschaftsbedingten Wechseln in den Besitzverhältnissen gelangte das Schloss im Jahr 1647 in den Besitz von Jean IV. d’Estaing, Erbe einer alten Adelslinie aus dem Rouergue, die bereits seit dem 10. Jahrhundert in der Auvergne Fuß gefasst hatte. Ein berühmter Ahnherr, Diédat (genannt Tristan), Baron d’Estaing, hatte 1214 in der Schlacht von Bouvines König Philipp II. August das Leben gerettet, indem er ihm im Kampf sein eigenes Pferd überließ.","w":"https://de.wikipedia.org/wiki/Schloss_Ravel"},"ch-Q1484371":{"n":"Schloss Le Sart","c":"Schloss in Frankreich","r":"Das Schloss Le Sart steht im Viertel Le Sart-Babylone der französischen Stadt Villeneuve-d’Ascq im Département Nord. Das Wasserschloss ist ein Gebäude im klassizistischen Stil aus rotem Backstein und weißem Kalkstein.","h":"Das Schloss wurde 1740 erbaut, aber nur selten von seinen Eigentümern, den Herren von Fourmestraux, bewohnt. Es beherbergte die sehr umfangreiche Bibliothek Van Der Cruisse de Waziers, die während des Ersten Weltkrieges von deutschen Truppen zerstört wurde. Im Hof der einstigen Wirtschaftsgebäude des Schlosses steht ein polygonaler Taubenturm, der 1761 errichtet wurde und seit Dezember 1988 als Monument historique unter Denkmalschutz steht. Seit der Schlosspark zu einem Golfplatz mit 18 Löchern umgebaut worden ist, dient das Schlossgebäude als Clubhaus für den dort ansässigen Golfclub.","w":"https://de.wikipedia.org/wiki/Schloss_Le_Sart"},"ch-Q1493082":{"n":"Schloss Auzers","c":"Schloss in Frankreich","r":"Das Schloss Auzers steht in der gleichnamigen französischen Gemeinde Auzers im Département Cantal der Region Auvergne.","h":"Die Herrschaft über Schloss und Gemeinde Auzers geht auf das Jahr 1364 zurück. Bernard von Marlat vererbte den Besitz seiner Tochter Blanche, die 1402 Blandin Bompart heiratete. Das Erbe ging anschließend auf ihren Sohn Blandin Bompar über. Er war Herr über Auzers sowie ab 1469 auch über Cussac. Blandin Bompar diente dem Grafen von Boulogne und später seinem Nachfolger Gilbert de Chabannes, für den er den Bau des Schlosses in Madic überwachte. Er heiratete Helen Fontages, mit der er eine Tochter, Alix, hatte, die nacheinander zwei Brüder heiratete. 1470 ehelichte sie Antoine de Douhet, Rechtsgelehrten und Kanzler von Jean, Graf von Boulogne und der Auvergne. Sie hatten zehn gemeinsame Kinder. In einer zweiten Ehe heiratete Alix den Bruder ihres verstorbenen Mannes, Jacques de Douhet. Mit ihm hatte sie drei weitere Kinder. Den Besitz erbte Gabriel de Douhet d’Auzers, Herr über Auzers und königlicher Statthalter in der Auvergne. Er baute das Schloss in seiner heutigen Form wieder auf.","w":"https://de.wikipedia.org/wiki/Schloss_Auzers"},"ch-Q1519303":{"n":"Burg Nideck","c":"Burg in Frankreich","r":"Die Burg Nideck ist die Ruine einer mittelalterlichen Höhenburg in den elsässischen Vogesen. Sie gehört zur Gemeinde Oberhaslach im Département Bas-Rhin.","h":"Nideck wird erstmals auf Siegeln des Burggrafen Günther, eines Gefolgsmanns des Bischofs von Straßburg, aus dem Jahr 1262 erwähnt (Purcravii Guntheri de Nideke). Eine Urkunde von 1264 nennt einen Herren „Burchardi de Nidecke“. In der ersten Hälfte des 14. Jahrhunderts hatten die Grafen von Leiningen Anteil an der Burg, gegen Ende des 14. Jahrhunderts war sie Ganerbenburg mehrerer Straßburger Niederadliger. 1454 wurde Nideck als Raubritternest von Ludwig von Lichtenberg erobert. Danach verschwindet die Burg aus den Quellen, vermutlich wurde sie noch im 15. Jahrhundert wegen ihrer Abgelegenheit aufgegeben.","w":"https://de.wikipedia.org/wiki/Burg_Nideck"},"ch-Q1869481":{"c":"Burg in Frankreich"},"ch-Q1870948":{"c":"Schloss in Frankreich"},"ch-Q1885888":{"n":"Maison de George Sand","c":"Museum in Frankreich","r":"Das Haus George Sand ist ein Anwesen in Nohant-Vic, Frankreich. Es wurde im 18. Jahrhundert für den Gouverneur von Vierzon auf den Überresten eines mittelalterlichen Herrenhauses erbaut. Im Jahr 1793 erwarb die Großmutter der Schriftstellerin George Sand (1804–1876), Madame Dupin de Francueil, das Anwesen. Sand verbrachte hier ihre Kindheit und Jugend und schrieb in Nohant einen Großteil ihres Werkes. 1953 vermachte ihre Enkelin Aurore Sand dem Staat den Landsitz, der heute der nationalen Denkmalsverwaltung untersteht.","w":"https://de.wikipedia.org/wiki/Haus_George_Sand"},"ch-Q1980181":{"c":"Burg in Frankreich"},"ch-Q1929031":{"n":"Schloss Lormont","c":"Schloss im Département Gironde, Frankreich","r":"Das Schloss Lormont ist die ehemalige Sommerresidenz der Erzbischöfe von Bordeaux in der französischen Stadt Lormont im Département Gironde. Sie ist auch als „Schloss der Erzbischöfe“ und als „Burg des schwarzen Prinzen“ bekannt. Die letztere Bezeichnung rührt daher, dass Edward of Woodstock, der auch der schwarze Prinz genannt wurde, nach lokalen Überlieferungen im 14. Jahrhundert einen Teil seines Lebens in einer Vorgängerburg verbracht haben soll.","h":"Keramikscherben, die bei einer Ausgrabung am Standort des Schlosses im Jahr 1975 gefunden wurden, beweisen, dass das Schlossareal schon in gallo-römischer Zeit besiedelt war. Allerdings stammen Angaben über eine hochmittelalterliche Herzogsburg an diesem Ort ursprünglich von einigen Lokalhistorikern des 19. Jahrhunderts, die aufgrund von Ereignissen, die mit der aquitanischen Herzogsfamilie und Lormont zusammenhängen, auf die Existenz einer Burganlage schlossen. Es fehlen jedoch sowohl archäologische als auch archivalische Beweise für diese Annahme, die im Laufe der vergangenen 150 Jahre von diversen Autoren in Publikationen nicht mehr als Hypothese, sondern als Fakt dargestellt wurde. Die erste gesicherte Nennung eines herrschaftlichen Sitzes stammt erst aus dem Jahr 1330 und führt den Erzbischof von Bordeaux als Eigentümer auf. Über diese Anlage ist nichts weiter bekannt, als dass sie eine eigene Kapelle besaß und in den französischen Religionskriegen zerstört worden sein könnte. Ab 1626 ließ der Kardinal und Erzbischof François de Sourdis auf den mittelalterlichen Fundamenten des zerstörten Vorgängerbaus durch den Baumeister Henri Roche einen Neubau als Sommerresidenz seiner Diözese errichten. Bei seinem Tod 1628 waren noch nicht alle Gebäude fertiggestellt. Die Hauptarbeiten fanden gegen 1630 ein Ende, und erst Françoisʼ Neffe Henry de Béthune beendete in der Zeit zwischen 1654 und 1662 eines der beiden Logis. Die Erzbischöfe von Bordeaux nutzten das Schloss bis zur Französischen Revolution als Landsitz und Sommerresidenz. Während der Fronde von königlichen Truppen eingenommen und verwüstet, wurde es schon kurz darauf (bis etwa 1670) wiederhergestellt. Nach 1744 folgten noch einmal Reparaturen an der Anlage.","w":"https://de.wikipedia.org/wiki/Schloss_Lormont"},"ch-Q1601882":{"n":"Schloss Costaérès","c":"neugotisches Schloss auf der Insel Costaérès in der Bretagne, Frankreich","r":"Das Schloss Costaérès ist ein in den 1890er Jahren im neugotischen Stil errichtetes Herrenhaus. Es entstand im Auftrag des litauisch-polnischen Mathematikers, Elektroingenieurs und Erfinders Bruno Abdank-Abakanowicz auf einer bis dahin unbewohnten Insel gleichen Namens. Wegen seiner prachtvollen architektonischen Gestaltung wird es auch als Schloss bezeichnet.","h":"Der repräsentative Bau wurde 1892–1896 als Wohnsitz des reich gewordenen litauisch-polnischen Wissenschaftlers Bruno Abakanowicz im neugotischen Stil des Historismus nach dem Vorbild mittelalterlicher Burgen errichtet. Abakanowicz erwarb das Baugrundstück mit einer Fläche von etwa einem Hektar im Jahr 1892 vom französischen Zöllner René Le Brozec, dem es als landwirtschaftliche Nutzfläche gedient hatte, für 25 Centime/Quadratmeter, der Kaufpreis betrug also 2500 fFr. Die Baupläne lieferte der Bauingenieur Lanmoniez, die Bauarbeiten erfolgten unter Leitung des Bauunternehmers Pierre Le Tensorer aus Lannion. Die Innenausstattung des herrschaftlichen Hauses soll aus dem Holz eines gestrandeten Schiffes gefertigt worden sein. Bereits im Jahr 1900 starb Abakanowicz, und der Besitz, damals noch nicht ganz fertig, wurde an die Tochter Sophia Poray geb. Abakanowicz, vererbt. Sie ließ es vollenden, einen Westflügel an der Rückseite anbauen und zog mit ihrer Familie hier ein. Das Schloss entwickelte sich zu Beginn des 20. Jahrhunderts zum Treffpunkt vieler polnischer Emigranten wie Aleksander Gierymski, Leon Wyczółkowski und des polnischen Literaturnobelpreisträgers Henryk Sienkiewicz. Sienkiewicz war eng mit Abakanowicz befreundet; sein 1895 erschienener Roman Quo Vadis entstand auf Schloss Costaérès. Während des Zweiten Weltkriegs beschlagnahmte die deutsche Armee das Anwesen und nutzte es als kleinen Militärstützpunkt. Das führte letztendlich im Inneren zu einigen Schäden. Nach Dacharbeiten zerstörte am 6. September 1990 ein Brand einen Teil des Innenbereichs des Gebäudes, er konnte aber wieder hergestellt werden. Seit Anfang des Jahres 2025 steht das Anwesen auf der französischen Insel zum Verkauf.","w":"https://de.wikipedia.org/wiki/Schloss_Costa%C3%A9r%C3%A8s"},"ch-Q1668992":{"n":"Schloss Moret-sur-Loing","c":"Schloss in Frankreich","r":"Das Schloss Moret-sur-Loing war ein Schloss in Moret-Loing-et-Orvanne, einer Stadt im Département Seine-et-Marne der Region Île-de-France, das auf eine mittelalterliche Burg zurückging. Das Bauwerk in der Rue du Donjon Nr. 15 ist als Monument historique geschützt.","w":"https://de.wikipedia.org/wiki/Schloss_Moret-sur-Loing"},"ch-Q1652308":{"n":"Hüneburg","c":"Burg in Frankreich","r":"Die Hüneburg liegt im Nordwesten von Dossenheim-sur-Zinsel im französischen Département Bas-Rhin auf einem 425 Meter hohen Sandsteinfelsen. Die Felsenburg ist vom Tal der Südlichen Zinsel her zugänglich.","h":"Die Burg war ursprünglich ganz oder zur Hälfte Reichsgut, aber auch der Bischof von Straßburg besaß hier Rechte, ebenso die Kurpfalz. Die wahrscheinlich aus einer Nebenlinie der Grafen von Dagsburg-Metz stammenden Grafen von Hüneburg werden 1125 in Dokumenten erwähnt, die die Existenz der Burg und der beiden ersten Grafen Theoderic und Folmar belegen. Diese Familie starb am Ende des 12. Jahrhunderts aus. Die Burg befand sich in der Folgezeit im Besitz eines Rittergeschlechtes, das sich ebenfalls nach der Burg „von Hüneburg“ nannte. Diese Familie, die die Burg in der Folgezeit bewohnte, übte auch die Schirmherrschaft über die Kloster Neuwiller und Honau aus. Das bekannteste Mitglied der Familie war Konrad von Hüneburg, Bischof von Straßburg in der Zeit von 1190 bis 1202. Ende des 13. Jahrhunderts war der Besitz an der Burg zwischen der ritterlichen Familie derer von Hüneburg und den Herren von Lichtenberg geteilt. 1288 kaufte Johann I. von Lichtenberg dem Walter von Hüneburg dessen Anteil ab und trug ihn ihm dann als Lehen auf. Dadurch wurde die Burg Bestandteil des Lichtenberger Territoriums. Die Herren von Lichtenberg ordneten die Burg ihrem Amt Buchsweiler zu. 1335 wurde eine Landesteilung zwischen der mittleren und der jüngeren Linie des Hauses Lichtenberg durchgeführt. Die Burg fiel dabei an Ludwig III. von Lichtenberg, der die jüngere Linie des Hauses begründete. Dies war auch Anlass für eine neue interne Organisation der Herrschaft Lichtenberg: Das Amt Ingweiler wurde aus dem Amt Buchsweiler ausgegliedert. Die Hüneburg kam dabei zum Amt Ingweiler. 1466 wurde das der Kurpfalz zustehende ¼ an der Burg den Herren von Lichtenberg als Lehen aufgetragen. Zum baulichen Zustand der Burg gibt es seit Mitte des 15. Jahrhunderts keine verlässlichen Quellen.","w":"https://de.wikipedia.org/wiki/H%C3%BCneburg_(Elsass)"},"ch-Q1676223":{"n":"Schloss Montigny-le-Gannelon","c":"Schloss in Frankreich","r":"Das Schloss Montigny-le-Gannelon befindet sich in der Gemeinde Montigny-le-Gannelon im Département Eure-et-Loir der Region Centre-Val de Loire in Frankreich. Es blickt von hoch oben auf den Loir herab.","w":"https://de.wikipedia.org/wiki/Schloss_Montigny-le-Gannelon"},"ch-Q1800368":{"c":"Burg in Frankreich"},"ch-Q1808663":{"c":"Burg in Frankreich"},"ch-Q1821831":{"n":"Schloss Pesteils","c":"Schloss in Polminhac, Département Cantal, Frankreich","r":"Das Schloss Pesteils steht in der französischen Gemeinde Polminhac im Département Cantal der Region Auvergne-Rhône-Alpes.","w":"https://de.wikipedia.org/wiki/Schloss_Pesteils"},"ch-Q2128921":{"c":"Burg in Frankreich"},"ch-Q2142824":{"n":"Burgruine Rotenberg","c":"Burg in Frankreich","r":"Die Burgruine Rotenberg oder Burg Rotenberg, franz. Château de Rougemont ist die Ruine einer Höhenburg bei Rougemont-le-Château im Territoire de Belfort auf einem Plateau am Südfuß der Vogesen im Sundgau.","h":"Die Burg wurde von den Grafen von Pfirt erbaut und kam nach Erlöschen dieser 1324 an die Habsburger. Mit dem Tod Johann IV. (Habsburg-Laufenburg) kam die Herrschaft Rotenberg und Burg an die Grafen von Sulz. Die Burg wurde um 1375 vermutlich durch Truppen des Enguerrand VII. de Coucy zerstört.","w":"https://de.wikipedia.org/wiki/Burgruine_Rotenberg"},"ch-Q2240167":{"n":"Schloss Bailleul","c":"Schloss in Frankreich","r":"Das Schloss Bailleul wurde um die Mitte des 16. Jahrhunderts im Stil der italienischen Hochrenaissance erbaut und steht in der französischen Gemeinde Angerville-Bailleul im Département Seine-Maritime in der Normandie. Das Schlossgebäude wurde im Juli 2010 als Monument historique klassifiziert, während der Schlosspark samt Umfassungsmauer bereits im Jahr 2005 in die französische Denkmalliste aufgenommen worden war. Sich in Privatbesitz befindend, kann das Gebäude nicht besichtigt werden, aber der dazugehörige Landschaftspark steht Besuchern offen.","h":"Bertrand de Bailleul kaufte im Jahr 1534 die Ländereien rund um die Ortschaft Angerville und fügte dem Besitz seinen Namen an. Er stammte aus einer der ältesten Familien der Normandie und ließ um die Zeit zwischen 1550 und 1560 auf dem Grund und Boden ein Schloss errichten, wobei der Bau möglicherweise auch erst während der Regierungszeit König Karls IX. stattgefunden hat und stark von seinem Vorbild Schloss Challeau (heute Schloss Saint-Ange genannt) beeinflusst wurde. In der zweiten Hälfte des 18. Jahrhunderts erfolgten tiefgreifende Umbauten am Gebäude und seinem zugehörigen Ensemble. 1850 ließen die markgräflichen Schlossherren den heutigen Landschaftspark anlegen. Zwischen 1870 und 1890 wurde das Schloss umfassend restauriert, und weitere konstruktive Änderungen verliehen dem Gebäude und seinem Park sein heutiges Aussehen. Das Schloss Bailleul wurde in seiner Geschichte niemals verkauft und befindet sich heute noch im Besitz der Nachfahren des Erbauers Bertrand de Bailleul.","w":"https://de.wikipedia.org/wiki/Schloss_Bailleul"},"ch-Q2240085":{"n":"Schloss Argy","c":"Schloss in Frankreich","r":"Das Schloss Argy gehört zur französischen Gemeinde Argy im Département Indre in der Region Centre-Val de Loire.","h":"Ein Herr von Argy wird erstmals 1115 anlässlich der Gründung der Abtei Notre-Dame du Landais erwähnt. Seine Nachkommen in männlicher Linie besaßen den Ort bis zum Ende des 13. Jahrhunderts. Durch Heirat ging Argy dann an den Herrn von Prungé, dessen Tochter den Ort an die Familie Brillac vererbte, die 1585 ausstarb. Deren Erben aus der Familie Crevant verkauften Argy 1636 an Jean Philippeaux, Herrn von Buzançais († 1660). Anfang des 19. Jahrhunderts geht das Schloss und die Domaine an die Familie Lamotte über.","w":"https://de.wikipedia.org/wiki/Schloss_Argy"},"ch-Q2240171":{"n":"Schloss Bannes","c":"Schloss in Frankreich","r":"Die Burg Bannes liegt im Département Dordogne des französischen Périgord nahe dem Ort Beaumont.","w":"https://de.wikipedia.org/wiki/Burg_Bannes"},"ch-Q2240361":{"n":"Schloss Boucard","c":"Schloss in Frankreich","r":"Das Schloss Boucard liegt in der Gemeinde Le Noyer im französischen Département Cher. Das Gebäude ist von einem Park umgeben und ist jedes Jahr Schauplatz eines Musikfestivals. Das Anwesen steht seit Juli 1995 als Monument historique unter Denkmalschutz.","w":"https://de.wikipedia.org/wiki/Schloss_Boucard"},"ch-Q2240551":{"n":"Schloss Cirey","c":"Schloss in Frankreich","r":"Das Schloss Cirey ist ein Schloss in Cirey-sur-Blaise im französischen Département Haute-Marne. Es ist nicht zu verwechseln mit dem gelegentlich ebenfalls Schloss Cirey genannten Kloster Bellevaux im Département Haute-Saône. Bekannt ist das Schloss, weil es 15 Jahre lang von 1734 bis 1749 für teils kürzere, teils längere Zeitabschnitte der gemeinsame Lebensmittelpunkt von Émilie Le Tonnelier de Breteuil, marquise de Châtelet, und Voltaire war.","h":"Im 17. Jahrhundert war die Seigneurie Cirey im Besitz des aus einer einflussreichen Lothringer Familie stammenden Louis-Jules du Châtelet. Er bekleidete ein Amt am königlichen Hof (officier du roi) und war Gouverneur von Aigues-Mortes. Als er sich im Machtkampf zwischen dem französischen König Ludwig XIII. und dessen Bruder Gaston d’Orléans für den intriganten Königsbruder entschied, fiel er in Ungnade und wurde wegen Verrats zum Tode durch Vierteilen verurteilt. Zugleich wurden alle seine Besitzungen konfisziert. Louis-Jules flüchtete, um dem Tod zu entgehen. Seine Frau Christine de Gleiseneuve ging zwar erfolgreich gegen die Beschlagnahmung der Seigneurie an und erhielt sie zurück, jedoch konnte sie nicht verhindern, dass die aus dem 11. Jahrhundert stammende Burg in Cirey 1633 geschleift wurde. Als sich Ludwig XIII. und sein Bruder 1634 versöhnten, profitierte auch Louis-Jules davon und wurde als Folge einer Amnestie auf freien Fuß gesetzt. 1642 begann er auf den Fundamenten der alten Burg mit dem Neubau eines Schlosses im Stil des Barocks. Jedoch waren von der geplanten Dreiflügelanlage mit vier Pavillontürmen an den Ecken nur ein Turm mit Anbau realisiert, ehe der Bauherr 1671 starb. Bekannt wurde das Schloss im zweiten Viertel des 18. Jahrhunderts, als es im Besitz des Marquis Florent-Claude du Châtelet, Graf von Lemout, Seigneur von Cirey, war. Er war Generalleutnant der königlichen Armee Ludwigs XV. und hatte 1724 die seinerzeit 18-jährige Émilie Le Tonnelier de Breteuil geheiratet. Das Paar hatte drei gemeinsame Kinder bekommen, ehe Émilie 1733 in Paris den 39-jährigen Voltaire kennenlernte und ein Verhältnis mit ihm begann. Dieses galt als eine der großen intellektuellen und romantischen Beziehungen des 18. Jahrhunderts.","w":"https://de.wikipedia.org/wiki/Schloss_Cirey"},"ch-Q2240557":{"n":"Schloss Cognac","c":"Schloss in Frankreich","r":"Das Schloss Cognac ist eine seit dem 10. Jahrhundert existierende und mehrfach wiederaufgebaute Burganlage in Cognac. Seit dem Jahr 1925 ist das Bauwerk als Monument historique anerkannt.","h":"Die Burg besteht seit 950, als Hélie de Villebois, erster Herr von Cognac, ein castrum errichten ließ. Um das Jahr 1000 ließen sich Itier und Arnaud de Villebois hier nieder und gründeten ihre Dynastie. Dieser Bau ist durch ein Dokument aus dem Jahr 1030 sowie Urkunden der Kirche Saint-Léger aus dem Jahr 1031 bekannt. Um diese damalige Burg, von der nichts erhalten ist, bildete sich eine Siedlung, die spätere Stadt Cognac. Um 1200 wurde die Burg an gleicher Stelle in Stein neu gebaut, gleichzeitig mit einer ersten Mauer um den Ort. Durch Erbschaft kam Cognac an das Haus Plantagenet, als der englische König Richard Löwenherz seinen Sohn Philipp mit der Erbin Amélie de Cognac verheiratete, der wiederum Cognac an seinen Onkel Johann Ohneland verkaufte. Dessen Witwe, Isabella von Angoulême, heiratete Hugo X. von Lusignan, der Cognac trotz seiner Exkommunikation behaupten konnte. König Philipp IV. brachte Cognac an die französische Krone. Von 1366 bis 1370 war die Burg, neben der Burg Angoulême, eine der Residenzen von Edward of Woodstock, dem „Schwarzen Prinzen“. Während des Hundertjährigen Kriegs (1337–1453) sah die Burg wechselnde Besitzer, je nach Kriegs- oder Vertragslage. Erst die Rückkehr von Jean de Valois nach seiner 25-jährigen Gefangenschaft in England (1415–1440) brachte wieder eine Zeit des Friedens. Er fand eine verlassene Burg in schlechtem baulichen Zustand vor und begann um das Jahr 1450 mit dem Wiederaufbau. Sein Sohn Charles und dessen Ehefrau Luise von Savoyen machten aus Cognac ein Zentrum der Wissenschaft und der Kunst. Ihre Tochter Margarete von Navarra und ihr Sohn François, der spätere König Franz I., der hier 1494 geboren wurde, vergaßen den Ort nicht: um 1517 ließ Franz I. die nüchterne Renaissancefassade entlang des Flussufers erbauen.","w":"https://de.wikipedia.org/wiki/Schloss_Cognac"},"ch-Q2969794":{"n":"Schloss Marbeaumont","c":"Burg in Frankreich","r":"Das Schloss Marbeaumont in Bar-le-Duc, einer französischen Stadt im Département Meuse in Lothringen, wurde von 1903 bis 1905 errichtet. Das Schloss an der Rue Saint-Mihiel Nr. 74 wurde 1980 als Monument historique in die Liste der Baudenkmäler in Frankreich aufgenommen.","w":"https://de.wikipedia.org/wiki/Schloss_Marbeaumont"},"ch-Q2969843":{"c":"Burg in Frankreich"},"ch-Q2969856":{"c":"Burg in Frankreich"},"ch-Q2969896":{"c":"Burg in Frankreich"},"ch-Q2971716":{"n":"Schloss Hamel","c":"Schloss in Frankreich","r":"Das Schloss Le Hamel ist ein Schloss in Castets-en-Dorthe, einem Ortsteil der französischen Gemeinde Castets et Castillon im Département Gironde der Region Nouvelle-Aquitaine. Es wurde ursprünglich 1313/14 erbaut und Ende des 17. Jahrhunderts neu errichtet. Das Schloss ist namensgebend für die Gemeinde Castets und seit 1963 als Monument historique klassifiziert.","h":"Die Herren von Castets-en-Dorthe sind seit dem 12. Jahrhundert überliefert. Der englische König Eduard II. erlaubte den Bau des Schlosses, das 1327 von französischen Truppen eingenommen wurde. Im Laufe des Hundertjährigen Krieges wurde es 1442 von den Engländern zurückerobert. 1572 wurde Jean de Fabas, Herr von Arès und Castet, Besitzer des Schlosses. Als Protestant beteiligte er sich an den Hugenottenkriegen und ließ das Schloss befestigen. Die Anlage wurde in den Auseinandersetzungen belagert und zerstört. Ab 1697 erfolgte der Wiederaufbau durch den neuen Besitzer Charles du Hamel unter Einbeziehung des östlichen Donjons des alten Schlosses. Das neue, nach Nordwesten offene Gebäude in Form des Buchstabens „U“ wird von den ehemaligen Pferdeställen an der Nord- und Westseite geschlossen. Das Gebäudeensemble umschließt damit einen wesentlich größeren Innenbereich, als dieser durch die beiden Seitenflügel des Schlosses gebildet würden.","w":"https://de.wikipedia.org/wiki/Schloss_Le_Hamel"},"ch-Q2971725":{"c":"Schloss in Frankreich"},"ch-Q2971771":{"n":"Burg Klein-Ringelstein","c":"Burg im Département Bas-Rhin, Frankreich","r":"Die Burg Klein-Ringelstein ist die Ruine einer Höhenburg auf dem 640 m hohen Petit Ringelsberg in den elsässischen Vogesen in Frankreich. Die Entstehung der Befestigung ist ungeklärt; sie wird dem Baubefund nach auf das 10. oder 11. Jahrhundert datiert. Sie ist älter als die benachbarte Burg Groß-Ringelstein, deren Vorgängerbau sie möglicherweise ist. Von den Bewohnern der Burg ist urkundlich ein Anselmus de Ringelstein aus dem Jahr 1137 genannt, welcher die Bewohner von Haslach geheilt haben soll.","w":"https://de.wikipedia.org/wiki/Burg_Klein-Ringelstein"},"ch-Q2970127":{"c":"Burghügel in Nizza"},"ch-Q2968560":{"n":"Schloss Bizy","c":"Schloss in Frankreich","r":"Das Schloss Bizy ist eine Schlossanlage am südlichen Rand der französischen Stadt Vernon in der Region Normandie. Wegen seiner Ähnlichkeit zum Königspalast in Versailles wurde es im 18. Jahrhundert Klein-Versailles genannt.","h":"Im Mittelalter gehörte Bizy den Herren von Blaru, ab dem 14. Jahrhundert war es Besitz der Familie Jubert. 1675 wurde dieser für Michel-André Jubert de Bouville zum Marquisat erhoben. Schon zu jener Zeit war ein kleines Schloss Mittelpunkt der Domäne. Der langgestreckte, niedrige Bau besaß ein Schieferdach und an beiden Enden zwei etwas höhere Pavillons. Nicolas André Jubert de Bouville verkaufte ihn mitsamt der dazugehörigen Ländereien im Jahr 1718/1721 an Charles Louis Auguste Fouquet, den Grafen und späteren Herzog von Belle-Isle. Er war ein Enkel Nicolas Fouquets und veranstaltete in Bizy – wie sein Großvater schon ein Jahrhundert zuvor auf Schloss Vaux-le-Vicomte – rauschende Feste. Zu einem dieser Anlässe waren am 21. September 1749 auch König Ludwig XV. und seine Maitresse en tître, Madame de Pompadour, auf Bizy zu Gast. Das Anwesen ließ Fouquet grundlegend verändern. Den bisherigen Schlossbau ersetzte er ab 1728 durch einen prächtigen und größeren Neubau und fügte ihm 1742 einen großzügigen Marstall hinzu. Die Entwürfe für die neuen Gebäude lieferte Pierre Contant d’Ivry, Architekt des Königs und später des Regenten Philippe II. de Bourbon, duc d’Orléans. Schon ab 1723 ließ der neue Schlossherr den bereits vorhandenen Schlosspark vergrößern und verändern. In der Zeit von 1723 bis 1724 wurde die Avenue des Capucins, eine über 1,5 Kilometer lange, gerade Ulmenallee, angelegt, die das Schloss mit dem Ort Vernon verband und bis zur Seine reichte. Die neue Gestaltung des Gartens und des Parks erfolgte nach Plänen von Jean Charles Garnier d’Isle und Claude Desgots, dem Neffen André Le Nôtres. Sie hatten einen prächtigen französischen Garten entworfen, der statuenbesetzte Parterres, Brunnen, Fontänen, und Wasserspiele sowie Kaskaden besaß.","w":"https://de.wikipedia.org/wiki/Schloss_Bizy"},"ch-Q2968583":{"c":"Burg in Frankreich"},"ch-Q2968626":{"c":"Burg in Frankreich"},"ch-Q2968646":{"c":"Burg in Frankreich"},"ch-Q2968661":{"c":"Burg in Frankreich"},"ch-Q2968669":{"c":"Schloss in Frankreich"},"ch-Q2969553":{"n":"Schloss Lagrange","c":"Schloss in Frankreich"},"ch-Q2969620":{"n":"Burg Lacoste","c":"Burg in Lacoste, Département Vaucluse, Frankreich"},"ch-Q2970893":{"c":"Burg in Frankreich"},"ch-Q2970953":{"c":"Burg in Frankreich"},"ch-Q2970932":{"c":"Burg in Frankreich"},"ch-Q2970978":{"c":"Schloss in Frankreich"},"ch-Q2968014":{"c":"Burg in Frankreich"},"ch-Q2970979":{"n":"Schloss Vigny","c":"Schloss im Département Val-dʼOise, Frankreich","r":"Das Schloss Vigny ist eine neugotische Schlossanlage in der französischen Gemeinde Vigny des Départements Val-dʼOise. Sie ging aus einem Herrenhaus des 14. Jahrhunderts hervor, das zu Beginn des 16. Jahrhunderts von Georges d’Amboise durch ein Renaissanceschloss ersetzt wurde.","h":"Eine Seigneurie Vigny existierte bereits im 13. Jahrhundert, aber erst für 1337 ist auch ein dortiges Herrenhaus verbürgt. In jenem Jahr verzichtete Éloi (auch Eloit) de Loudon, genannt Souillart, Sohn und Erbe der Jeanne la Crespelle, auf seine Rechte am Manoir in Vigny. Später war die Seigneurie im Besitz der Familie Courcelles. Alten Chroniken zufolge soll sie während des Hundertjährigen Krieges dann an Richard Marbury, einen Gefolgsmann von John of Lancaster, erstem Herzog von Bedford, gekommen sein. Seine Kinder aus der Ehe mit Jeanne de La Croix verkauften den Besitz 1501 an Louis de Hédouville, Seigneur von Sandricourt und 1495 Bailli sowie Gouverneur von Blois. Nach dessen Tod veräußerte seine Witwe Françoise de Rouvray Manoir und Land am 16. November 1504 an Kardinal Georges d’Amboise weiter. Der erste Minister Ludwigs XII. ließ in Vigny ein Schloss errichten, das in seiner Grunddisposition als geschlossene Vierflügelanlage noch an mittelalterliche Wehranlagen erinnerte, doch zugleich schon erste Elemente der französischen Renaissance zeigte. Dabei ist nicht sicher, ob Georges d’Amboise ein bestehendes Gebäude aus- bzw. umbauen oder einen kompletten Neubau errichten ließ. Möglicherweise war der Schlossbau schon, kurz bevor der Kardinal neuer Seigneur wurde, begonnen worden. Bekannt ist, dass er sich gerne nach Vigny zurückzog, um Abstand von den politischen Geschäften und dem französischen Königshof zu gewinnen. Zur selben Zeit vollendete Georgesʼ Neffe Charles II. d’Amboise den Neubau des Schlosses Chaumont an der Loire, das vermutlich Modell für die Anlage in Vigny gestanden hat, denn die beiden Schlösser weisen große Ähnlichkeiten auf.","w":"https://de.wikipedia.org/wiki/Schloss_Vigny"},"ch-Q2968043":{"c":"Burg in Frankreich"},"ch-Q2968093":{"c":"Burg in Frankreich"},"ch-Q2970463":{"c":"Burg in Frankreich"},"ch-Q2970521":{"c":"Burg in Frankreich"},"ch-Q2200119":{"n":"Schloss Bosmelet","c":"Schloss in Frankreich","r":"Das Schloss Bosmelet ist ein Schloss auf dem Gebiet der Gemeinde Val-de-Scie in der Normandie. Der Bau aus der ersten Hälfte des 17. Jahrhunderts ist seit dem Jahr 1931 als Monument historique anerkannt. Im Jahre 1994 wurde auch der Park unter Schutz gestellt. Das Schloss liegt etwa zwei Kilometer südöstlich der Ortschaft Auffay im Département Seine-Maritime.","h":"Bauherr des Schlosses war Gilles Beuzelin, Mitglied des Regionalparlaments von Rouen. Später war es im Besitz des Herzogs von la Force, dem Gouverneur der Normandie. 1940 wurde der Bau von deutschen Truppen besetzt, die im Schlosspark eine V1-Abschussrampe installierten. Da der Widerstandskämpfer Michel Hollard die Position dieser Anlage den Alliierten verriet, wurde Bosmelet bei insgesamt 28 Bombenangriffen zwischen Dezember 1943 und Juni 1944 schwer beschädigt. Das Schloss ist heute in Privatbesitz und wird noch immer von Angehörigen der Familie Bosmelet bewohnt. Teile des Erdgeschosses können für Veranstaltungen gemietet werden. Im Obergeschoss ist zusätzlich eine Ferienwohnung eingerichtet worden.","w":"https://de.wikipedia.org/wiki/Schloss_Bosmelet"},"ch-Q2243096":{"n":"Schloss Ravalet","c":"Schloss in Frankreich","r":"Das Schloss Les Ravalet ist ein ab 1562 entstandenes Renaissance-Schloss im Département Manche in der Normandie. Es ist im Besitz der Gemeinde Cherbourg-Octeville, befindet sich aber auf dem Gebiet der Gemeinde Tourlaville. Vor dem Schloss liegt ein im 19. Jahrhundert entstandener Park.","h":"Die damalige Burg gehörte zur königlichen Domäne und wurde von König Franz I. an Jean II. de Raval aus Tourlaville verkauft. Dieser ließ 1562 ein Renaissance-Schloss errichten, lediglich der Bergfried blieb in Teilen bestehen. Nach finanziellen Problemen verkauften die Herren von Raval 1653 das Schloss an Charles de Franquetot, der insbesondere das Innere renovieren ließ. Nach dessen Ermordung hatte die Anlage mehrere Besitzer, darunter die Boudets aus Crosville und die Fouquets aus Reville. 1661 wurde es als Bauernhof genutzt. Clérel Hervé de Tocqueville nahm es 1777 in Besitz. Dessen Enkel René de Tocqueville, Oberbürgermeister der Stadt, veranlasste die Renovierung der Gebäude und Gärten und baute ein großes Gewächshaus. Im Jahr 1906 musste er es jedoch verkaufen. Im Ersten Weltkrieg dienten die Gebäude als Lazarett. Schon 1930 war das Schloss als Monument historique im Katalog aufgeführt. Die Stadt Cherbourg erwarb das Anwesen im Jahr 1935. Während des Zweiten Weltkrieges war es von der deutschen Armee und nach der Befreiung von amerikanischer Truppen besetzt. Während der Park das ganze Jahr über öffentlich zugänglich ist, ist das Schloss nur während der Tage des offenen Denkmals (Journées du patrimoine) zu besichtigen. Park und Gewächshaus stehen gemeinsam mit dem Schlossbau seit März 1996 unter Denkmalschutz.","w":"https://de.wikipedia.org/wiki/Schloss_Les_Ravalet"},"ch-Q2640864":{"c":"Burg in Frankreich"},"ch-Q2748605":{"c":"Burg in Frankreich"},"ch-Q2749741":{"c":"Burg in Frankreich"},"ch-Q2243666":{"n":"Schloss Sully","c":"Schloss in Sully, Saône-et-Loire, Frankreich","r":"Das Schloss Sully ist ein Wasserschloss im burgundischen Ort Sully, Département Saône-et-Loire, etwa 14 Kilometer nordöstlich von Autun am linken Ufer der Drée.","h":"Sully gehörte im Hochmittelalter dem Haus Sully. Gauthier de Sully erbaute im 12. Jahrhundert eine wehrhafte Burg mit acht Ecktürmen, Gräben und einer Zugbrücke. Davon sind heute noch ein Turm und einige Grundmauern erhalten. Als die Familie Sully Mitte des 13. Jahrhunderts ausstarb, wurde sie von einem Zweig der Herren von Couches, der Familie Bauffremont, beerbt. Ende des 13. Jahrhunderts heiratete Marie de Bauffremont Etienne I. de Bourgogne-Montagu und brachte sowohl die Herrschaft als auch die Burg mit in die Ehe. Für mehr als 150 Jahre blieb Sully im Besitz dieser Familie. Als ihr letzter männlicher Vertreter, Claude de Montaigu, 1471 in der Schlacht bei Buxy starb, beerbte ihn seine einzige Tochter Jeanne, die 1461 Hugues de Rabutin, Seigneur von Épiry, geheiratet hatte. Die Burg Sully hatte Claude de Montaigue allerdings bereits zwei Jahre vor seinem Tod am 20. Dezember 1469 an den Mann seiner Tochter übertragen. Die Rabutins ließen die alte einflügelige Anlage durch drei weitere Gebäudeflügel noch im 15. Jahrhundert erweitern. Christophe de Rabutin veräußerte den Besitz im Jahr 1515 an Jean de Saulx. Dessen Sohn, der Marschall Gaspard de Saulx-Tavannes, ließ die alten Gebäude niederlegen und um 1570 auf den Grundmauern der alten Anlage mit dem Neubau eines Schlosses im Stil der Renaissance beginnen. Die Pläne dazu werden Nicolas Ribonnier zugeschrieben, auch wenn er nicht urkundlich als Architekt des Schlosses nachgewiesen ist. Da er für die Familie jedoch auch das Schloss La Pailly erbaute, ist er als Architekt für Sully zumindest wahrscheinlich. Nach dem Tod des Marschalls 1573 setzte seine Witwe Françoise de La Beaume de Montrevel den Neubau weiter fort.","w":"https://de.wikipedia.org/wiki/Schloss_Sully"},"ch-Q2970389":{"n":"Château de Rochebrune","c":"Schloß in Frankreich","r":"Das Château de Rochebrune ist ein in der französischen Gemeinde Étagnac befindliches Wasserschloss aus dem 11. Jahrhundert. Es bildet den Beginn der Tourismusstraße Richard Löwenherz.","h":"Während der ersten Kreuzzüge war das Château de Rochebrune ein wichtiger befestigter Platz von strategischer Bedeutung, der an der Kreuzung der Straßen von Limoges, Angoulême und Niort lag. Jourdain I. de Chabanais ließ vor seiner Abreise nach Jerusalem – wo er 1099 verstarb – den ersten Turm errichten. Die restlichen drei Türme folgten erst ein Jahrhundert später. Die Mauerstärke beträgt zwei Meter. Die Mauern sind so mit Schießscharten versehen, dass es für die Verteidiger keine toten Winkel gab. Die Nachkommen von Jourdain I. erweiterten das Bauwerk dann sukzessiv bis auf seine heutigen Ausmaße. Während der Hugenottenkriege fiel das Château de Rochebrune im Jahr 1561 an den Katholiken und Erzrivalen der Protestanten Blaise de Monluc. Das Schloss bildete damals zusammen mit Chabanais und Confolens eine Verteidigungslinie gegen die von Süden heranrückenden Protestanten. Nach einer Brandschatzung durch die Protestanten im Jahr 1569 ließ die Schwiegertochter von Blaise de Montluc Fensteröffnungen in die Mauern einbauen, um das Bauwerk aufzuhellen und richtig bewohnbar zu machen. Das Mauerwerk trug damals noch einen die vier Ecktürme verbindenden Rundweg für das Wachpersonal. Das Schloss ging sodann durch Heirat an die Familie Escoubleau de Sourdis. In der nächsten Generation heiratete Angélique Charlotte d’Escoubleau de Sourdis aus Chabanais den Marquis de Saint-Pouange François Gilbert Colbert (1676–1719). Anlässlich des Heiratsvertrags erhob Ludwig XIV. im Jahr 1702 die Ländereien um Chabanais zu einem Marquisat. Die Colbert-Chabanais ließen dann noch weitaus größere Fenster einsetzen. Um das Schloss zugänglicher zu machen, wurde im 18. Jahrhundert die einstige Zugbrücke durch die heutige breite Brücke ersetzt.","w":"https://de.wikipedia.org/wiki/Schloss_Rochebrune"},"ch-Q2967793":{"c":"Burg in Frankreich"},"ch-Q2967839":{"c":"Burg in Frankreich"},"ch-Q2968830":{"c":"Burg in Frankreich"},"ch-Q2968157":{"c":"Schloss in Frankreich"},"ch-Q2968138":{"n":"Château d’Asnières","c":"Schloss in Frankreich","r":"Das Château d’Asnières ist ein Palast in Asnières-sur-Seine im Département Hauts-de-Seine.","h":"Das Schloss von Asnières wurde im 17. Jahrhundert auf dem Gelände eines früheren Gebäudes (plan massé) von Antoine Lemoyne, einem Professor der Sorbonne errichtet und während der Régence im gleichnamigen Stil erbaut. Er war ein Favorit der Comtesse de Parabère, einer Maîtresse des Regenten, die ihn oft dort besuchte. Das Schloss zusammen mit den direkt angrenzenden Stallungen und Weiden, mit einer Kapazität von bis zu 120 Pferden, diente als „Stützpunkt der Gestüte von Asnières“ (entrepôt général des haras d’Asnières) und war in der Mitte des 18. Jahrhunderts eine der schönsten Domänen in der Umgebung von Paris. Es spricht für die künstlerischen Ambitionen von Marc René d’Argenson, Marquis de Voyer, dass er versuchte, dort die bedeutendsten Künstler seiner Zeit zu versammeln: Jacques Hardouin-Mansart de Sagonne als Architekt, Nicolas Pineau für die Ausstattung, Guillaume II Coustou für Skulpturen, die Brunettis und Jean-Baptiste Marie Pierre für die Malerei, Jacques Caffieri für vergoldete Bronzen. Die Galerie verfügt über eine bedeutende Sammlung flämischer und holländischer Maler der damaligen Zeit, sowie eine Sammlung der besten Ebenholztischlereien. Der Marquis spekulierte nämlich darauf, den Platz des Marquis de Marigny einzunehmen, der damals „Directeur des Bâtiments, Arts et Manufactures du Roi“ (Direktor der Häuser, Künstler und Werkstätten des Königs) war und der Bruder von Madame de Pompadour. Argenson trat auch in Wettstreit mit den prachtvollen Anwesen in der Umgebung, unter anderem den Palästen des Duc de Richelieu in Gennevilliers, des Duc de Choiseul in Clichy, seines Vaters, des Comte d’Argenson in Neuilly-sur-Seine und der Marquise de Pompadour, einer Feindin der Familie, in Bellevue.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_d%E2%80%99Asni%C3%A8res"},"ch-Q2971071":{"c":"Burg in Frankreich"},"ch-Q2243291":{"n":"Schloss Saint-Fargeau","c":"Schloss in Frankreich","r":"Das Schloss Saint-Fargeau ist ein französisches Schloss in Saint-Fargeau im burgundischen Département Yonne.","h":"Die Anfänge des Schlosses gehen auf ein befestigtes Jagdhaus des Bischofs Héribert d’Auxerre zurück, das im Jahr 980 errichtet wurde. Der heutige Bau datiert jedoch von 1453 und den Folgejahren. 1652 wurde Anne Marie Louise d’Orléans, genannt La Grande Mademoiselle, dorthin verbannt. Sie ließ das Schloss durch François Le Vau, den Bruder von Louis Le Vau, in den Jahren von 1653 bis 1657 renovieren und modernisieren. 1713 erwarb die Familie Le Pelletier den Besitz. Jean d’Ormesson verbrachte hier seine Kindheit und schrieb darüber den Roman Au plaisir de Dieu, der 1976 für das Fernsehen verfilmt wurde. 1979 wurde das baufällig gewordene Schloss von Michel Guyot erworben und in der Folge mit den Einnahmen aus einem jährlich aufgeführten historischen Sommerspektakel mit etwa 600 Akteuren, 60 Reitern und etwa 20 historischen amerikanischen Militärfahrzeugen restauriert. Die Vorstellungen finden jeweils am Wochenende statt und orientieren sich an der tausendjährigen Geschichte des Spielortes. Das Schloss Saint-Fargeau, ein unregelmäßiges Fünfeck mit imposanten Ecktürmen, ist seit dem 5. Mai 1949 als Monument historique klassifiziert.","w":"https://de.wikipedia.org/wiki/Schloss_Saint-Fargeau"},"ch-Q2967867":{"n":"Château Deganne","c":"Schloss in Arcachon, Frankreich, heute Casino und Kongresszentrum"},"ch-Q2967918":{"n":"Château Lamothe-Guignard","c":"Schloss in Frankreich","r":"Château Lamothe-Guignard ist der Name eines Weinguts im Weinbaugebiet Sauternes innerhalb der gleichnamigen Gemeinde Sauternes in der französischen Region Nouvelle-Aquitaine. Seit 1855 ist es nach der Bordeaux-Klassifizierung, an der nie Veränderungen im Bereich des Sauternes vorgenommen wurden, als Deuxième Cru Classé eingestuft.","h":"Das Château Lamothe-Guignard firmierte bis 1814 unter dem Namen Lamothe d’Assault. Der ca. 45 mal 55 m große Baukörper mit vier Rundtürmen an den jeweiligen Gebäudeecken soll aus merowingischer Zeit stammen. In den darauf folgenden eineinhalb Jahrhunderten erlebte das Anwesen viele Besitzerwechsel und wurde mehrfach aufgeteilt, doch beide heute noch produzierende Teile wurden 1855 in die Bordeaux-Klassifikation einbezogen, was für die zu diesem Zeitpunkt vorhandene Qualität spricht. Während der südliche, 7,48 ha große Teil des Anwesens 1961 an die Familie Despujols verkauft wurde und weiterhin unter dem Namen Château Lamothe wirtschaftet, wurde der größte dieser Teile 1981 von den Brüdern Philippe und Jacques Guignard erworben, die zu dieser Zeit Anfang zwanzig Jahre alt waren. Sie konsolidierten den verbliebenen Besitz und gründeten am 11. März 1982 in der Rechtsform der Groupement agricole d'exploitation en commun (GAEC) eine Gesellschaft zur Produktion und dem Vertrieb von Wein. Das Weingut baut zu 90 % Sémillon, 5 % Sauvignon und 5 % Muscadelle an. Die Stockdichte beträgt 6600. Daraus wird Dessertwein hergestellt. Im Jahr produziert der Betrieb ca. 36.000 Flaschen.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Lamothe-Guignard"},"ch-Q2967913":{"n":"Château Lamothe","c":"Schloss in Frankreich","r":"Das Château Lamothe ist ein Weingut im Weinbaugebiet Sauternes, das nach der Bordeaux-Klassifizierung als Deuxième Cru Classé eingestuft ist. Es befindet sich unmittelbar südlich des Château Lamothe-Guignard in der Gemeinde Sauternes in der französischen Region Nouvelle-Aquitaine.","h":"Das Anwesen geht auf eine merowingische Befestigungsanlage aus dem 8. Jahrhundert zurück, von der noch einige Grundmauern zu sehen sind. Der heutige Baukörper stammt aus dem 16. Jahrhundert, als hier für die Herren Budos und Fragues ein Herrenhaus errichtet wurde. 1814 ging der Besitz von Jean-François de Borie (1765–1806) an den britischen Cognac-Händler James Dowling, der bereits 1820 an Jean und Simon Baptiste weiterverkaufte. Bis zur Bordeaux-Klassifizierung 1855 ging der Besitz durch vier weitere Hände, doch war er immer noch innerhalb der Familie Baptiste. Unmittelbar danach – im Zeitraum zwischen 1855 und 1868, man vermutet, nach dem Tod der Witwe Baptiste und begründet durch Familienkonflikte – wurde das Weingut in zwei Teile geteilt und es gab nun einen Cru de Lamothe (oder Lamothe-Massieux), der Monsieur Massieux gehörte, und einen Cru de Lamothe, der Monsieur Dietz gehörte, laut Edouard Féret (1844–1910) das heutige Château Lamothe-Guignard. In der langen Reihe von Grundbesitzern standen auch die Eigentümer von Château d’Arche der Familie Bastit-St-Martin zu der auch der Politiker Armand Bastit-St-Martin (1900–1984) gehörte, der in den langen und schwierigen Zeiten 1934 bis 1971 Bürgermeister der Gemeinde war. 1961 verkaufte Bastit-St-Martin das Weingut und einen Großteil der Weinberge an Jean Despujols, behielt aber einen Teil, den er von dem Nachbarbetrieb Lamothe-Guignard bewirtschaften ließ, bis er diesen 1981 verkaufte und an sie überging. 1989 übernahm Sohn Guy den Betrieb und die Qualität wird von Johnson als „einer der Schwächeren, jung zu trinken“ klassifiziert, und auch Brook befindet:","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Lamothe"},"ch-Q2970222":{"n":"Château de Pierreclos","c":"Burg in Frankreich","r":"Das Château de Pierreclos ist eine romanische Schlossanlage in der französischen Gemeinde Pierreclos im Département Saône-et-Loire in der Region Bourgogne-Franche-Comté.","h":"Erstmals urkundlich erwähnt ist eine Kapelle im Jahr 1091. Im 13. Jahrhundert erfolgte der Ausbau zur Schlossanlage. In den folgenden Jahrhunderten musste das Schloss einige kriegerische Auseinandersetzungen und die Französische Revolution überstehen. Belagerungen, Kämpfe und Erbstreitigkeiten führten zu häufigen Besitzerwechseln. Das Schloss ist seit dem 21. Dezember 1984 als historisches Denkmal in der Base Mérimée, der Datenbank des französischen Kulturministeriums eingetragen.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_de_Pierreclos"},"ch-Q2968420":{"c":"Burg in Frankreich"},"ch-Q2969230":{"c":"Schloss in Frankreich"},"ch-Q2969262":{"n":"Château de Françon","c":"Schloss in Frankreich","r":"Biarritz ist eine französische Gemeinde im Département Pyrénées-Atlantiques in der Region Nouvelle-Aquitaine.","h":"An der Küste leben einige Basken ärmlich vom Fischfang. Das schöne junge Mädchen Miarritze hat einen Traum: Gott verspricht ihr, die Seele seines Dieners Martin in ihr entlegenes Land zu schicken. Er werde als bunter Vogel erscheinen, der einen Fisch mit goldenen Schuppen im Schnabel trägt, als Zeichen des Reichtums, der den armen Leuten an der Küste geschenkt werde. Die Bewohner finden einige Tage später tatsächlich einen Eisvogel (frz. Martin-pêcheur, „Martinsfischer“). Durch Miarritze veranlasst bauen sie Schiffe, um auf Walfang zu gehen. Eines Tages strandet ein Schiff, Miarritze nimmt die Seefahrer, die sich Biarrins nennen und aus der Gascogne kommen, auf. Sie wird die Frau des Anführers und daraus entsteht der Name der Stadt Biarritz. Im Mittelalter war Biarritz als Walfängerhafen bekannt, Wale traten in großer Zahl im Golf von Biskaya auf. Das Walfett wurde zu Lampenöl verarbeitet, aus den Knochen baute man Zäune, aus der Haut fertigte man Hüte und die Bespannung von Sesseln. Der Fischerhafen lag geschützt an einem Fels, bei Hochwasser konnte man die Wale an den flachen Strand ziehen und sie bei Ebbe zerteilen. Die Walzunge galt als besondere Kostbarkeit. Im 17. Jahrhundert waren die Wale ausgerottet und der Walfang endete. Danach war Biarritz (ältere Schreibung: Bearrits) bis in die Mitte des 19. Jahrhunderts ein eher unbedeutendes Fischerdorf. Um 1800 zählte es rund 200 Einwohner. Die Situation änderte sich, als 1854 Kaiserin Eugénie, die Ehefrau von Napoléon III., für zwei Monate nach Biarritz kam und der Kaiser ihr daraufhin eine Residenz bauen ließ, die das Paar danach regelmäßig im Sommer besuchte. Die Residenz dient heute als Hotel.","w":"https://de.wikipedia.org/wiki/Biarritz"},"ch-Q2969236":{"n":"Schloss Fontaine-Henry","c":"Schloss in Frankreich","r":"Das Schloss Fontaine-Henry ist ein Renaissance-Schloss in der französischen Gemeinde Fontaine-Henry in der Normandie.","h":"Das Schloss Fontaine-Henry ist seit zehn Jahrhunderten in Familienbesitz ohne jemals verkauft worden zu sein. Dennoch wechselten die Familien mehrmals den Namen, da das Schloss immer wieder auf Frauen übertragen wurde. Durch Vererbung gehörte es abwechselnd zu den Familien Tilly, Harcourt, Morais, Boutier de Château d’Assy, Montécler, Marguerie, Carbonnel, Cornulier und Oilliamson. Anfang des 11. Jahrhunderts existierte an der Stelle eine mittelalterliche Festung, die die Familie Tilly zwischen 1200 und 1220 durch ein neues Schloss ersetzen ließ. Aus dieser Zeit sind vor allem die Kapelle und die Kellergewölbe erhalten, die damals das Erdgeschoss des Wohngebäudes bildeten. 1374 heiratete Jeanne de Tilly Philippe d’Harcourt und gab ihm als Mitgift unter anderem dieses Herrenschloss. Die Familie Harcourt begann nach dem Hundertjährigen Krieg mit dem Wiederaufbau des Gebäudes. Die Arbeiten erstreckten sich, vom Ende des 15. Jahrhunderts bis in die 1560er Jahre hinein, beinahe über ein ganzes Jahrhundert.","w":"https://de.wikipedia.org/wiki/Schloss_Fontaine-Henry"},"ch-Q2969372":{"n":"Schloss Guiry","c":"Schloss in Frankreich","r":"Das Schloss Guiry in Guiry-en-Vexin, einer französischen Gemeinde im Département Val-d’Oise in der Region Île-de-France, wurde um 1665 errichtet. Seit 1942 steht das Schloss mit Park und seinen Nebengebäuden als Monument historique auf der Liste der Baudenkmäler in Frankreich.","h":"Das Schloss wurde für André, Marquis de Guiry, nach den Plänen des Architekten François Mansart erbaut. Es wurde auf den Fundamenten eines Vorgängerbaus aus dem 16. Jahrhundert errichtet, der durch einen Brand zerstört wurde. Da der Architekt bereits 1666 starb, wurde der Bau von seinem Neffen Jules Hardouin-Mansart vollendet. Das Schloss befindet sich seither ununterbrochen im Besitz der gleichen Familie.","w":"https://de.wikipedia.org/wiki/Schloss_Guiry"},"ch-Q2969360":{"n":"Burg Grizac","c":"Schloss in Pont-de-Montvert-Sud-Mont-Lozère, Département Lozère, Frankreich","r":"Die Burg Grizac liegt unterhalb des gleichnamigen Dorfes in der Gemeinde Le Pont-de-Montvert im Département Lozère in Frankreich. Sie befindet sich in Privatbesitz und beherbergt ganzjährig eine Ausstellung über den Papst Urban V.","h":"Die Burg Grizac soll im 13. Jahrhundert von Guillaume Grimoard erbaut worden sein, dessen Status als Chevalier und Bauer ihm einen solchen Bau erlaubte. Seine Frau, Amphélise de Montferrand, brachte dort ihre sechs Kinder zur Welt. Im Jahr 1310 wurde hier ihr Sohn, ebenfalls mit dem Vornamen Guillaume, der spätere Papst Urban V., geboren, wenige Jahre später dessen Bruder, der spätere Kardinal Anglic Grimoard, die hier einen großen Teil ihrer Kindheit verbrachten. Im gleichen Jahrhundert wurde Grizac zum Marquisat erhoben. Der Großteil der mittelalterlichen Gebäude muss Mitte des 14. Jahrhunderts errichtet worden sein und wurde wahrscheinlich im 15. Jahrhundert erweitert. Die Burg wurde Ende des 15. Jahrhunderts dann aufgegeben. Vom 17. bis 19. Jahrhundert wurden umfangreiche Umbauten vorgenommen und im 19. Jahrhundert wurde das Anwesen in einen landwirtschaftlichen Betrieb und eine Gemeindeschule umgewandelt. Die Hauptteil des Gebäudes hat einen rechteckigen Grundriss und weist folgende Teile auf: die Überreste eines Wachturms, ein teilweise eingestürzter Zentralbau, ein als Wohnhaus ausgebautes Gebäude im Osten; eine Terrasse und Überreste von Gebäuden im Süden; ein großer Wirtschaftshof im Norden, der von kleinen neueren landwirtschaftlichen Gebäuden begrenzt wird, eine zweigeschossige Scheune im Westen und eine weitere im Osten. Um diesen Komplex herum können Überreste von Verteidigungsanlagen erkannt werden. Die Burg war im Besitz von Renaud Mouchet de Battefort de Laubespin, Marquis de Laubespin (* 1927), der mit Arlette de Garnier des Garets verheiratet war und aus den alten Ruinen jenes Wohnhaus machte, das man heute sehen kann. Am 21.","w":"https://de.wikipedia.org/wiki/Burg_Grizac"},"ch-Q2969963":{"c":"Burg in Frankreich"},"ch-Q2969397":{"c":"Burg in Frankreich"},"ch-Q3078149":{"c":"Burg in Frankreich"},"ch-Q2970280":{"n":"Schloss Posanges","c":"Befestigtes Schloss in Posanges, Burgund","r":"Das Schloss Posanges ist eine befestigte Schlossanlage in Posanges, etwa zweieinhalb Kilometer nördlich von Vitteaux im Département Côte-d’Or der Region Bourgogne-Franche-Comté. Die Anlage wurde im 15. Jahrhundert von einem Günstling des Herzogs Philipps des Guten errichtet und wirkt sehr burgartig, denn bei ihrem Bau wurde noch auf mittelalterliche Bauformen zurückgegriffen. Militärisch war Schloss Posanges jedoch unbedeutend, denn es beschützte weder einen wichtigen Teil des Herzogtums, noch überwachte es eine wichtige Straße oder einen bedeutenden Wasserweg.","h":"1299 war die Seigneurie Posanges im Besitz von Eudes de Frolois, der sie als Lehen von dem burgundischen Herzog Robert II. erhalten hatte. Zu jenem Zeitpunkt existierte dort bereits ein Festes Haus, jedoch nicht am Ort des heutigen Schlosses. Für das Jahr 1391 ist Erard de Lézigne als Besitzer eines Teils von Posanges überliefert. In der ersten Hälfte des 15. Jahrhunderts kam der Besitz an Guillaume du Bois (auch Dubois geschrieben), dem bailli des Auxois und maître d’hotel Philipps des Guten. Guillaume stammte aus dem Berry und hatte dort all seine Besitzungen verloren, weil diese im Zuge des Bürgerkriegs der Armagnacs und Bourguignons von den Armagnaken eingenommen worden waren. Du Bois brachte nach und nach die verstreuten Teile der Seigneurie in seinen Besitz und ließ ab 1437 die heutige, repräsentative Anlage errichten. Bei seinem Tod am 6. November 1453 war der Neubau noch nicht vollständig fertiggestellt. Erst Guillaumes Sohn Antoine vollendete das Werk 1490 mit der Ausstattung des Logis. Außerdem ließ er zwei Treppentürme zur Erschließung der Nordtürme errichten. Die Familie du Bois blieb bis 1561 im Besitz der befestigten Anlage. In jenem Jahr war Joachim du Bois gezwungen, sie an Arvier de Cléron zu verkaufen. Joachim war für schuldig befunden worden, gemeinsam mit zwei weiteren Männern Antoine de La Perrière umgebracht zu haben. Bereits zum Tode verurteilt, wurde er aber begnadigt, musste im Gegenzug jedoch der Mutter seines Opfers eine hohe Entschädigung zahlen. Um diese Auflage erfüllen zu können, war er gezwungen, die Seigneurie Posanges mitsamt dem Schloss zu verkaufen. Die Familie de Cléron residierte jedoch nicht mehr selbst in der Anlage, sondern ließ sie von Pächter bewirtschaften und bewohnen.","w":"https://de.wikipedia.org/wiki/Schloss_Posanges"},"ch-Q2969538":{"c":"Schloss in Frankreich"},"ch-Q2680235":{"c":"Burg in Frankreich"},"ch-Q2715327":{"c":"Burg in Frankreich"},"ch-Q2968938":{"c":"Burg in Frankreich"},"ch-Q2969692":{"c":"Burg in Frankreich"},"ch-Q2971844":{"n":"Schloss Le Vert-Bois","c":"Schloss in Frankreich","r":"Das Schloss Le Vert-Bois ist ein Schloss im Stil des klassizistischen Barocks auf dem Gebiet der nordfranzösischen Stadt Bondues an der Grenze zu Belgien. Es wurde 1743 von einem Mitglied der Industriellenfamilie Prouvost im Stil eines Lustschlosses am Standort einer Vorgängeranlage aus den 1660er Jahren errichtet.","h":"Erster bekannter Herr von Vert-Bois war 1389 Roger Boutelin, dessen Nachkommen das Land bis 1576 besaßen. In jenem Jahr verkaufte Hélène de Heulle den Besitz an Guillaume Deliot, Schöffe in Lille. Dessen Tochter Jeanne heiratete 1602 André de Fourmestraux und brachte Vert-Bois mit in die Ehe. 1610 erwarb André die Seigneurie Wazières, weswegen der Sohn des Paars, Jean-André, 1662/1663 den Namen de Wazières annahm. Gemeinhin wird angenommen, dass er es war, der in den 1660er Jahren ein erstes Schloss auf den Ländereien errichtete. Es gibt jedoch keine stichhaltigen Beweise für diese Annahme. Jean-Andrés Urenkel André Joseph Druon de Wazières ließ 1743 nicht nur den bestehenden Torbau der Anlage verändern, sondern errichtete auch ein neues Hauptgebäude im Stil des klassizistischen Barocks und vererbte den Neubau seinem jüngeren Bruder Dominique-Joseph. Nach dem Tod Louis-Edmond de Wazièresʼ 1856 und seiner Frau Élisa-Flavie Buffin 1860 wurde der Besitz unter deren zwei Söhnen aufgeteilt. Das Schloss fiel dem älteren Gaston-Louis zu. Er war zu jener Zeit aber erst neun Jahre alt, und so verpachtete sein Vormund die Anlage samt den dazugehörenden Ländereien an Louis Duchochois. Dieser beendete im Jahr 1869 das Pachtverhältnis zugunsten seines Verwandten Eugène Devémy, der mit Marguerite Duchochois verheiratet war. Derweil hatte Gaston-Louis de Wazières viel Geld in den Spielsalons von Paris verloren und musste das Schloss am 19. April 1876 an seinen Kreditgeber Devémy verkaufen, um seine immensen Schulden begleichen zu können. Drei Jahre nach dem Kauf brachte Devémys Tochter Marthe das Schloss 1879 durch Heirat an ihren Mann Albert-Félix Prouvost.","w":"https://de.wikipedia.org/wiki/Schloss_Le_Vert-Bois"},"ch-Q2971914":{"c":"Burg in Frankreich"},"ch-Q3036702":{"c":"Burg in Frankreich"},"ch-Q2405390":{"n":"Burg Montrond (Saint-Amand-Montrond)","c":"Burg in Frankreich","r":"Die Burg Montrond in der Gemeinde Saint-Amand-Montrond im Département Cher, Region Centre-Val de Loire, war eine Burg des 13. Jahrhunderts, erbaut für Renaud de Montfaucon. Erste Spuren einer Befestigung konnten auf um das Jahr 1225 datiert werden.","w":"https://de.wikipedia.org/wiki/Burg_Montrond_(Saint-Amand-Montrond)"},"ch-Q2412975":{"c":"Burg in Frankreich"},"ch-Q2971270":{"n":"Château de la Guignardière","c":"Renaissance-Schloss bei Avrillé in der Vendée","r":"Das Schloss La Guignardière ist ein Renaissanceschloss bei Avrillé im Herzen der Vendée. Sein Bau wurde um das Jahr 1555 von Jean Girard begonnen, blieb aber unvollendet. Im 18. Jahrhundert wurde das Gebäude von seinem damaligen Eigentümer minimal verändert, erfuhr aber keine weiteren tiefgreifenden Umgestaltungen, sodass es heute eines der seltenen Renaissancebauwerke im westlichen Poitou (Bas-Poitou) ist. Ein zweigeschossiger Flügel mit Eckpavillon und markanten Kaminen sowie ein kurzer Seitentrakt sind erhalten. Anfang des 19.","h":"Um 1555 begann Jean Girard, Brotmeister des französischen Königs Heinrich II., mit dem Bau eines Schlosses im Stil der Renaissance. Geplant war ein Corps de Logis mit zwei rechtwinkelig anschließenden Seitenflügeln und viereckigen Pavillonbauten an den Eckpunkten. Das dreiflügelige Gebäude in U-Form sollte einen Ehrenhof umschließen. Als der Bauherr 1563 während der französischen Religionskriege getötet wurde, war das Schloss aber noch nicht fertiggestellt. Die Baustelle wurde geschlossen, und das Gebäude blieb unvollendet. Im 18. Jahrhundert kam das Anwesen durch Heirat von Marie Françoise Renée Marin an ihren Mann, den Grafen Sylvestre François du Chaffault. Durch ihn wurde das Schlossgebäude ein wenig verändert. Davon zeugen sein Wappen und die Jahreszahl 1773 an einem Fenster. Außerdem ließ er den Großen Teich (französisch Grand étang) südlich des Schlosses ausheben. Als bekennender Royalist musste er nach der Verhaftung Ludwigs XVI. in der Französischen Revolution außer Landes fliehen. Als er später nach Frankreich zurückkehrte, war sein Schloss von Revolutionären geplündert und viele Familienmitglieder erschossen worden. Zu Beginn des 19. Jahrhunderts war La Guignardière Eigentum von Louis Barbe Juchereau, dem Marquis de Saint-Denis. Er ließ im Geschmack der Zeit die französischen Gärten des Anwesens in einen englischen Landschaftsgarten umgestalten. Viele der heutigen Bäume im Schlosspark wurden von ihm gepflanzt. Nach dem Marquis war die Familie Luce de Tremont Eigentümerin der Anlage. In ihre Zeit fällt die Nutzung der Pferdeställe im 19. Jahrhundert durch das Französische Nationalgestüt.","w":"https://de.wikipedia.org/wiki/Schloss_La_Guignardi%C3%A8re"},"ch-Q2429145":{"c":"Burg in Frankreich"},"ch-Q2971368":{"c":"Burg in Frankreich"},"ch-Q2971334":{"c":"Burg in Frankreich"},"ch-Q2360459":{"c":"Burg in Frankreich"},"ch-Q2366170":{"n":"Château de la Pommerie","c":"Schloss in Frankreich"},"ch-Q2968317":{"n":"Château d’Orion","c":"Schloss in Frankreich","r":"Das Château d’Orion wurde im 17. Jahrhundert errichtet und ist heute ein Kultur-, Gäste- und Veranstaltungshaus in der Gemeinde Orion im Département Pyrénées-Atlantiques im Südwesten von Frankreich.","h":"Das typische Béarnaiser Landschloss wurde über die Jahrhunderte hinweg laufend erweitert. Bis heute ist die ursprüngliche Innenausstattung weitgehend erhalten geblieben, teilweise befindet sie sich sogar noch im Originalzustand. Die Familie Casamayor war der erste Besitzer des Anwesens. Bis zur Französischen Revolution betreuten sie die naheliegende Kirche. Nach der Restauration in Frankreich kaufte die Familie Jean-Ninon Larrouy, die dank dem Handel mit dem begehrten Bayonner Schinken zu Reichtum und Wohlstand gekommen war, das Gut im 19. Jahrhundert. Über die Erben Louis und anschließend Henriette Larrouy kam das Haus in den Besitz des berühmten französischen Chirurgen Paul Reclus. Dieser experimentierte in Paris mit Kokain als Narkosemittel und erfand die Wundsalbe Pommade de Reclus. Dessen begehrter Tochter Madeleine Reclus widmete Henri de Régnier, der Dichter und Freund André Gides, ein eigenes Sonett, in dem es heißt: „Ich liebe ihr Haus, das den Namen eines Sterns trägt, den ihre Augen erhellen …“. Zwei der insgesamt fünf Brüder von Paul Reclus waren ebenfalls zu ihrer Zeit bekannte Persönlichkeiten. Élisée Reclus war einer der bekanntesten Anarchisten Frankreichs sowie ein weltberühmter Geograph und Armand Reclus wirkte als Ingenieur am Bau des Panamakanals mit. Sein Nachfahre, Jean Labbé, heiratete in den 1950er Jahren Marguerite Bérard, die Tochter des ehemaligen französischen Erziehungs- und Justizministers Léon Bérard. 2003 verkaufte sie das Schloss an die Familie Premauer aus München, die dem Haus mit der Restaurierung das Leben als kulturelle Begegnungsstätte zurückgab. Marguerite Labbé lebt noch heute (Stand: Februar 2012) in ihrem Zimmer auf Schloss Orion.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_d%E2%80%99Orion"},"ch-Q2968385":{"c":"Burg in Frankreich"},"ch-Q2283058":{"n":"Schloss Excideuil","c":"Schloss in Frankreich","r":"Das Schloss Excideuil ist eine französische Schlossanlage in der Dordogne. Sie steht auf einem flachen Felsplateau am südlichen Rand der Gemeinde Excideuil, die in der Region Nouvelle-Aquitaine liegt. Die Anlage war im 12. bis 14. Jahrhundert der Hauptsitz der Vizegrafen von Limoges und steht in ihrer Gesamtheit als Monument historique (classé) seit dem 11. Juli 2014 unter Denkmalschutz. Als Besonderheit besitzt sie einen der seltenen Doppel-Donjons.","h":"Schon im 11. und 12. Jahrhundert war der heutige Schlossplatz von den Vizegrafen von Limoges durch Mauern und einen Donjon befestigt worden, denn seine strategisch günstige Lage erlaubt es, die Straße zwischen Limoges und Périgueux zu überwachen. Die Anlage wurde urkundlich erstmals im Rahmen einer Schenkung des Vizegrafen Adémar III. an die Abtei Uzerche um 1100 erwähnt. Im Konflikt der regionalen Ritterschaft mit den Herzögen von Aquitanien aus dem Haus Plantagenet, die seit 1152 im Besitz der Region waren, wurde die damalige Burg mehrmals belagert. Im April und Juni des Jahres 1182 sowie 1184 versuchten Soldaten Richard Löwenherzʼ vergeblich, die Anlage einzunehmen. Als Vizegraf Adémar V. 1199 auf die Seite des englischen Königs gewechselt war, nahm Johann Ohneland im Gegenzug Excideuil und einige andere Burgen der Vizegrafen ein. Erst um das Jahr 1211 gelang es Adémars Sohn Guido V., wieder in den Besitz der Wehranlagen zu kommen. Unter ihm oder seinem Nachfolger Guido VI. wurde die Burg Excideuil Mitte des 13. Jahrhunderts erneuert und weiter verstärkt. Guidos Erbtochter Marie heiratete den späteren Herzog der Bretagne, Arthur II., und brachte Excideuil an dessen Familie, deren Besitz sie bis zur Mitte des 15. Jahrhunderts blieb. Im Hundertjährigen Krieg konnten englischen Truppen die Burg nach einem ersten erfolglosen Angriff im Jahr 1346 schließlich 1351 erobern. Zwar gelangte sie 1356 wieder in französische Hände, musste aber nach dem Frieden von Brétigny wieder den Engländern übergeben werden, ehe Bertrand du Guesclin die Anlage 1370 ein weiteres Mal für die Franzosen zurückeroberte. Ein letzter Angriff englischer Truppen 1419/1420 blieb erfolglos. Durch die Heirat der Françoise de Bretagne mit Alain dʼAlbret gelangte die Burg an dessen Familie.","w":"https://de.wikipedia.org/wiki/Schloss_Excideuil"},"ch-Q2306676":{"c":"Burg in Frankreich"},"ch-Q2393265":{"c":"Burg in Frankreich"},"ch-Q2971155":{"c":"Schloss in Frankreich"},"ch-Q2970737":{"c":"Burg in Frankreich"},"ch-Q2970769":{"c":"Burg in Frankreich"},"ch-Q2970755":{"c":"Burg in Frankreich"},"ch-Q2970796":{"n":"Schloss Thoiry","c":"Schloss in Frankreich","r":"Das Schloss von Thoiry ist eine 150 Hektar große Schlossanlage mit Zoo und botanischem Garten, gelegen im Dorf Thoiry im Département Yvelines in Frankreich, die seit 1965 für die Öffentlichkeit zugänglich ist. Der Komplex befindet sich etwa 48 Kilometer westlich von Paris. 1974 wurden 280.000 Besucher gezählt, seitdem ist die Popularität gewachsen.","h":"Das Schloss wurde in den Jahren 1559 bis 1580 nach Plänen des Architekten Olivier Ymbert erbaut. Erster Besitzer war Raoul Moreau († 1583), der als Schatzmeister von König Heinrich II. sehr vermögend geworden war.","w":"https://de.wikipedia.org/wiki/Schloss_Thoiry"},"ch-Q2021453":{"n":"Château d’Aubenas","c":"ehemalige mittelalterliche Burganlage in Aubenas, Frankreich","r":"Das Schloss Aubenas, auch als Château de Montlaur bekannt, befindet sich in Aubenas und ist eine ehemalige mittelalterliche Burganlage, die ursprünglich komplett von einem Graben umgeben war. Im Laufe der Jahrhunderte entstand aus der Kernburg eine ausgedehnte Festungsanlage. Rundtürme und Wehrgänge sind fast durchgängig mit Maschikuli versehen. Der Bergfried stammt angeblich noch aus dem 11. Jahrhundert.","w":"https://de.wikipedia.org/wiki/Schloss_Aubenas"},"ch-Q2090110":{"c":"Burg in Frankreich"},"ch-Q2056655":{"n":"Château de Blérancourt","c":"Schloss in Frankreich"},"ch-Q2085869":{"c":"Schloss in Frankreich"},"ch-Q2523683":{"c":"Hotel in Frankreich"},"ch-Q2578045":{"c":"Schloss in Frankreich"},"ch-Q2971579":{"n":"Schloss Thouars","c":"Burg in Frankreich","r":"Das Schloss Thouars befindet sich in Thouars im Département Deux-Sèvres.","h":"Ursprünglich befand sich auf dem Gelände eine erste Motte, die 762 von Pippin dem Jüngeren geschleift wurde. Im Mittelalter wurde sie durch eine Burg ersetzt, die während des Hundertjährigen Krieges die wichtige Festung Thouars verteidigte. Die Burg wurde insbesondere von Bertrand du Guesclin im Jahr 1372 erobert. Die Vizegrafschaft Thouars ging in die Hände der Familie Amboise über und wurde der königlichen Domäne angegliedert, bevor sie von Ludwig XI. an die Erben der Familie Amboise, die La Trémoille, zurückgegeben wurde. Diese bedeutende französische Adelsfamilie erwirkte bei König Karl IX. die Erhebung der Vizegrafschaft zum Herzogtum Thouars, das unter Heinrich IV. mit der Pairie einherging. Das Herzogtum blieb bis zur Französischen Revolution in den Händen dieser Familie. In der ersten Hälfte des 17. Jahrhunderts hielt es Marie de La Tour d’Auvergne (1601–1665), seit 1619 Ehefrau von Henri III de La Trémoille, Herzog von Thouars, nicht mehr aus, in diesem kalten und ungemütlichen Schloss zu wohnen. Sie drohte damit, Thouars zu verlassen, falls nichts unternommen werde, um ihr ein angenehmeres Zuhause zu bauen. Ursprünglich war das Projekt relativ bescheiden: Man begann mit dem Bau eines kleinen Pavillons, der sich an das alte Schloss anlehnte (dieses Gebäude mit trapezförmigem Grundriss existiert noch heute). Im Jahr 1638 riet der Architekt Jacques Lemercier der Herzogin jedoch, nichts von den alten Gebäuden zu erhalten. Sie beschloss daraufhin, die alten mittelalterlichen Bauten abzureißen und das Material wiederzuverwenden, um einen Flügel zu bauen, der den neuen Pavillon mit der Stiftskirche Notre-Dame verband.","w":"https://de.wikipedia.org/wiki/Schloss_Thouars"},"ch-Q3533155":{"c":"Burg in Frankreich"},"ch-Q5118662":{"n":"Schloss Citran","c":"Schloss im Département Gironde, Frankreich","r":"Das Schloss Citran in Avensan, einer französischen Gemeinde im Département Gironde in der Region Nouvelle-Aquitaine, wurde von 1861 bis 1864 auf den Fundamenten eines Vorgängerbaus aus dem Mittelalter errichtet. Im Jahr 2012 wurde das Schloss als Monument historique in die Liste der Baudenkmäler in Frankreich aufgenommen.","w":"https://de.wikipedia.org/wiki/Schloss_Citran"},"ch-Q5118748":{"n":"Burg Bucheneck","c":"Burg in Frankreich","r":"Die Burg Bucheneck ist eine ehemalige Wasserburg bei Soultz-Haut-Rhin im Elsass. Sie steht als Monument historique unter Denkmalschutz.","h":"Der Bischof von Straßburg ließ Anfang des 13. Jahrhunderts im Norden von Soultz (seit 1079 Eigentum des Straßburger Bischofs) anstelle eines Herrenhauses eine kleine Burg errichten. 1249 wurde Soultz zur Stadt erhoben und Sitz des bischöflichen Vogts. Ab 1251 war die Burg Lehensgut und wurde in diesem Zusammenhang erstmals urkundlich erwähnt. Lehnsherren waren die Herren zu Pfaffenheim. Aber schon 1289 gelangte sie in den Besitz des Bischofs zurück. Der ließ die Burg befestigen, um die nördlichen Vororte von Soultz schützen zu können. Im 16. Jahrhundert wurde die Burg umgestaltet. Im Dreißigjährigen Krieg wurde sie bei Plünderungen der Stadt durch die Truppen von Maximilian I. schwer beschädigt und erst Anfang des 18. Jahrhunderts saniert, obwohl Bischof Armand I. Gaston Maximilien de Rohan-Soubise 1719 beschlossen hatte, die Burg niederzulegen. Die Französische Revolution beendete die Herrschaft der Bischöfe über die Stadt Soultz. Damit war auch das Ende der Burg als Dienstsitz des Vogtes gekommen. In das Gebäude zogen Werkstätten ein. Noch Anfang des 20. Jahrhunderts war in der Burg eine Fabrik untergebracht. 1969 funktionierte man das Gebäude zum Wohnhaus um. 1976 kaufte die Stadt die Burg und begann im folgenden Jahr, das Gebäude zu restaurieren. Seit 1990 ist es Sitz des Stadtmuseums.","w":"https://de.wikipedia.org/wiki/Burg_Bucheneck"},"ch-Q5118781":{"n":"Burg Hohnack","c":"Burg im Département Bas-Rhin, Frankreich","r":"Burg Hohnack ist die Ruine einer Höhenburg in den Vogesen unweit der französischen Stadt Colmar im Elsass.","h":"In einer späteren Chronik wird der Hohnack für das Jahr 1079 als Besitz der Grafen von Egisheim erwähnt, doch gilt diese Angabe als zweifelhaft. Eine Familie von Hohnack erscheint in der Mitte des 12. Jahrhunderts; sie hielt die Burg als Lehen der Grafen von Pfirt. Diese trugen die Burg ab 1251 dem Straßburger Bischof zu Lehen auf. Bald darauf entstanden Besitzstreitigkeiten mit den Rappoltsteinern, die die Burg später als Mitgift an die von Saarwerden (1361) und – zusammen mit der 10 km entfernten Gutenburg – an Johann I. von Lupfen-Stühlingen abtraten; 1438 fiel die Burg an die Rappoltsteiner zurück, die sie in der Folge ausbauten. Im Dreißigjährigen Krieg wurde Hohnack 1635 an die Franzosen übergeben und durch den Gouverneur von Colmar zerstört. Im Westfälischen Frieden zurückgegeben, ließ Ludwig XIV. die Burg ab November 1655 endgültig schleifen. Während der Französischen Revolution wurde Hohnack als Nationaleigentum verkauft. Die Ruine wurde 1886 von der Familie Golbéry der Gesellschaft zur Erhaltung historischer Denkmäler des Elsass geschenkt. Schließlich ging sie in den Besitz der Gemeinde Labaroche über.","w":"https://de.wikipedia.org/wiki/Burg_Hohnack"},"ch-Q15943705":{"n":"Burg Sailhant","c":"Schloss in Andelat, Département Cantal, Auvergne-Rhône-Alpes, Frankreich","r":"Château du Sailhant ist eine denkmalgeschützte, in ihren Ursprüngen auf das frühe 11. Jahrhundert zurückgehende Spornburg im französischen Département Cantal in der Region Auvergne-Rhône-Alpes. Sie liegt in der Gemeinde Andelat, etwa sechs Kilometer nordwestlich von Saint-Flour auf einem dreieckigen Basaltsporn der Hochebene Planèze.","h":"Im Gegensatz zu den meisten mittelalterlichen Befestigungen der Region besaß das Sailhant über Jahrhunderte hinweg den seltenen Status eines Allods (Freieigen) und war kein Lehnsgut (Fief). Die Besitzer waren somit keinem Lehnsherrn zu Feudaleid und Huldigung (foi et hommage) verpflichtet, was die relative Armut an frühen feudalen Urkunden erklärt. Noch im Jahr 1503 protestierte der damalige Herr, Guyon d’Amboise, gegen entsprechende Huldigungsforderungen. Die früheste urkundliche Erwähnung eines Ritters Guigonis de Salhens datiert auf den Beginn des 11. Jahrhunderts im Zuge der Gründung des Priorats von Saint-Flour durch den Abt Odilo von Cluny. Nach einer urkundlichen Lücke von über 150 Jahren ging die Herrschaft um 1300 durch die Heirat einer Erbtochter der Familie de Saillans an Bertrand I. de Rochefort d'Aurouze über. Im Jahr 1364 wird der Komplex unter Bernard de Rochefort erstmals explizit als „Château et châtellenie“ erwähnt. Durch Erbfolge gelangte die Burg 1383 an die Familie Dauphin de Saint-Ilpize (eine jüngere Linie der Dauphins d’Auvergne) und 1436 weiter an die Familie de Lespinasse. Wegen seiner strategisch exponierten Lage nahe der Stadt Saint-Flour diente das Sailhant im Hundertjährigen Krieg wiederholt als militärischt-taktischer Stützpunkt wechselnder Kriegsparteien und Raubritter, während die rechtmäßigen Besitzer meist vertrieben wurden. Zwischen 1359 und 1439 war die Festung insgesamt viermal für eine Gesamtdauer von fast zehn Jahren besetzt: 1359–1364: Erste Besetzung durch englische Truppen unter dem Truppenführer Robert Knolles. 1380–1384: Einnahme durch die englisch-gascognische Kompanie unter Pierre de Galard und dem „Bastard von Garlan“.","w":"https://de.wikipedia.org/wiki/Burg_Sailhant"},"ch-Q15940040":{"n":"Burg Benauge","c":"Burg in Nouvelle-Aquitaine, Frankreich","r":"Die Burg Benauge in Arbis, einem Ortsteil der französischen Gemeinde Porte-de-Benauge im Département Gironde in der Region Nouvelle-Aquitaine, wurde im 13. bis 14. Jahrhundert errichtet. Im Jahr 1995 wurde die Höhenburg als Monument historique in die Liste der Baudenkmäler in Frankreich aufgenommen.","w":"https://de.wikipedia.org/wiki/Burg_Benauge"},"ch-Q15940146":{"c":"Burg in Frankreich"},"ch-Q15940046":{"c":"Schloss in Frankreich"},"ch-Q15940178":{"n":"Burg Hageneck","c":"Burgruine im Elsass","r":"Die Ruine der Burg Hageneck steht auf einem Granitfelsen westlich der elsässischen Ortschaft Wettolsheim im Département Haut-Rhin. Die Höhenburg wurde in der Vergangenheit häufig mit der nahe gelegenen, heute nur noch in geringen Resten vorhandenen Burg Haneck über Soultzbach-les-Bains verwechselt, sodass urkundliche Nachrichten über die beiden Burganlagen oft vermengt wurden.","h":"Die Burg dürfte im sehr frühen 13. Jahrhundert entstanden sein, wofür das Fehlen jeglicher gotischer Formen und in das erste Viertel des 13. Jahrhunderts deutende archäologische Befunde Indizien sind. Eine Familie, die sich nach der Burg benannte, wurde 1263 mit Burkhard von Hageneck, einem Vasallen des Bischofs von Straßburg, erstmals urkundlich erwähnt. Die Anlage war gemeinsam mit der Herrschaft Rufach ein bischöfliches Lehen und fungierte vermutlich als deren nördlicher Grenzpunkt. Nach den Angaben in den Colmarer Annalen (Annales Colmarienses minores et maiores) des Colmarer Dominikanerchronisten war die Familie von Hageneck auch Erbauer der Burg. Wahrscheinlich war sie identisch mit den Herren von Wettolsheim, wofür nicht nur die Nähe zur Burg Wettolsheim spricht, sondern auch das gemeinsame Wappen mit einem gerauteten Schild. 1300 erfolgte der Verkauf des castrum de Haguinecke an die Familie von Laubgassen (auch Lobgassen), die 1294 ihren Stammsitz, die Burg Laubeck, verloren hatte. In einer Fehde gegen die Familie von Hattstatt und die mit ihnen verbündeten Herren von Hus wurde die Burg 1304 schwer beschädigt, danach aber wiederaufgebaut und sogar noch erweitert. Die Nachricht über die Beschädigung wurde von einigen Forschern auf die Burg Haneck bezogen, doch es ist wesentlich wahrscheinlicher, dass es sich dabei um Hageneck handelte. Im 15. Jahrhundert war die kleine Anlage in der Hand verschiedener Besitzer, unter anderem der Herren von Rappoltstein, die sie von den Habsburgern zu Lehen trugen. Wilhelm I. von Rappoltstein vergab ein Drittel von Hageneck 1478 als Afterlehen an Johann von Wettolsheim. Andere Besitzer waren die Familien Zorn und Landenberg sowie Ulrich Stör und die Herren von Rust, eine Adelsfamilie aus Colmar.","w":"https://de.wikipedia.org/wiki/Burg_Hageneck"},"ch-Q15940213":{"n":"Domaine de la Léonardsau","c":"Schloss in Frankreich","r":"Die Domaine de la Leonardsau ist ein historisches Monument zwischen den Gemeinden Bœrsch und Obernai (Elsass). Der Ortsteil wird Saint-Léonard genannt. Das Anwesen steht auf der Denkmalschutzliste.","h":"Die Wiesen, auf denen später die Domaine de la Léonardsau entstehen sollten, gehörten bis zur Französischen Revolution zum Kloster Saint Léonard. Zu Beginn des 19. Jahrhunderts gab es dort eine Wäscherei, die die Wiesen zum Bleichen der Wäsche nutzte. François-Joseph Bisch (1756–1831) kaufte das Gelände zusammen mit seinem Sohn Xavier André, die beide in der Blankwaffenmanufaktur in Klingenthal arbeiteten. 1869 wurde die Wäscherei geschlossen und das Gelände an die Société Couleaux et Cie verkauft, eine Nachfolgerin der Waffenfabrik von Klingenthal. 1896 verkaufte die Firma den Besitz an den Baron Albert Louis Eugène de Dietrich (1861–1956). Dieser baute in den Jahren 1896 bis 1950 die Domaine de la Léonardsau als Herrenhaus in ihrer heutigen Form. Er selbst wohnte nicht permanent in diesem Gut, da er noch zwei herrschaftliche Häuser in Straßburg und Paris und eine Villa an der Côte d’Azur besaß. De Dietrich war mit den Künstlern des nahegelegenen Cercle de Saint-Léonard befreundet. 1950 zog er sich an die Côte d’Azur zurück und verkaufte die Léonardsau an den französischen General Gruss, den früheren Kommandanten von Straßburg. Im Jahr 1970 kaufte die Gemeinde Obernai das Anwesen, seitdem ist der Park der Öffentlichkeit zugänglich. Ende 2022 veröffentlichte die Gemeinde Obernai einen Plan, die Domaine grundlegend zu renovieren und zu modernisieren und einen Teil des Parks in einen Parkplatz umzuwandeln.","w":"https://de.wikipedia.org/wiki/Domaine_de_la_L%C3%A9onardsau"},"ch-Q15940222":{"n":"Château de Reichenberg","c":"Burg in Frankreich"},"ch-Q15940228":{"c":"Burg in Frankreich"},"ch-Q15944452":{"c":"Schloss in Frankreich"},"ch-Q15944523":{"n":"Château d'Uriage","c":"Burg im Departement Isère, Frankreich","r":"Das Château d’Uriage, oder Schloss Uriage, ist ein befestigtes Schloss aus dem 11. Jahrhundert, das im 13., 16. und 19. Jahrhundert umfassend umgebaut wurde. Es befindet sich in der Gemeinde Saint-Martin-d’Uriage im französischen Département Isère in der Region Auvergne-Rhône-Alpes.","h":"Seit Ende des 10. Jahrhunderts befindet sich das Schloss im Besitz einer Familie aus Dauphiné, den Alleman („Deutschen“). Im Jahr 1630 trat der letzte Baron d’Uriage die Burg an Thomas Boffin ab. 19. Jahrhundert (1828): Louis de Saint-Ferriol erbte von seiner Tante, der Marquise Madeleine Françoise de Gauteron, mehrere Schlösser, darunter das von Uriage. In der Folge beherbergte es unter anderem die École nationale des cadres unter dem Vichy-Regime (1940–1942), (1943–1944) Schule der Milice francaise.","w":"https://de.wikipedia.org/wiki/Schloss_Uriage"},"ch-Q20717322":{"c":"Schloss in Frankreich"},"ch-Q22949563":{"c":"Schloss in Frankreich"},"ch-Q19753121":{"n":"Bischofspalast von Castres","c":"Palast in Castres, Département Tarn, Frankreich","r":"Der Bischofspalast von Castres wurde im Jahr 1673 im Auftrag von Bischof Michel Tubeuf von Jules Hardouin-Mansart, dem späteren Hofarchitekten Ludwigs XIV., in der südfranzösischen Stadt Castres entworfen. Er diente als Residenz des Bischofs von Castres.","h":"Am 13. Juli 1317 gründete Papst Johannes XXII. das Bistum Castres, das seit 1817 zum Bistum Albi, Castres und Lavaur gehört. Eine Residenz des Bischofs wurde kurz nach Gründung nahe der Maison consulaire der Stadt errichtet und erfuhr im Laufe der Zeit einige Modifikationen. Um 1669 ließ Michel de Tubœuf, der Bischof von Castres, einen neuen Palast zwischen dem Fluss und dem romanischen Turm Saint-Benoît, Überbleibsel einer ehemaligen Benediktinerabtei aus dem 12. Jahrhundert, erbauen. Architekt war Jules Hardouin-Mansart, der spätere Generalintendant der Königlichen Bauten. Bischofspalast und Turm bilden heute ein kompaktes Bauensemble. 1794 fiel das Anwesen an die Kommune. Nach der Revolution wurden wegen der Erweiterung der Rue Henri IV. große Teile des Palastes abgerissen. Erhalten blieb der Innenhof und die Fassade auf die Rue des Capitouls, die heute unter Denkmalschutz steht. Untergebracht im Palast wurden nacheinander die Sous-Préfecture, dann das Hôtel de Ville. Ab 1840 wurden einige Räume als Museum genutzt. Heute ist der Palast Sitz des Goya-Museums, das inzwischen auch den romanischen Turm für seine Bibliothek nutzt.","w":"https://de.wikipedia.org/wiki/Bischofspalast_von_Castres"},"ch-Q22956936":{"n":"Château de Purnon","c":"Schloss im Département Vienne, Frankreich","r":"Das zwischen 1771 und 1785 erbaute Château de Purnon ist ein ehemaliges Jagdschloss im französischen Département Vienne und gehört zu der 400 Einwohner zählenden Gemeinde Verrue. Wahrscheinlich stand an dieser Stelle zuvor eine andere Schlossanlage. Es steht zusammen mit den beiden wichtigsten Nebengebäuden, dem trockenen Graben, den Terrassen und dem nördlichen Eingangstor seit 1995 unter Denkmalschutz. Andere Teile des Anwesens wurden bereits 1992 unter Denkmalschutz Monument historique Inscrit MH gestellt. Das Gesamtensemble wird von privater Hand umfassend renoviert.","h":"Das Schloss wurde im Auftrag von Antoine-Charles Achard, Marquis de la Haye (1737–1816) aus hellem Sandstein errichtet. Er war Ritter des Ordre royal et militaire de Saint-Louis, 1773 Kavalleriehauptmann, dann Feldmarschall und Generalstabsadjutant der Armee der Prinzen. In einem Protokoll vom 13. Germinal II (2. April 1795) wurde festgehalten, dass das Land und der Meierhof, auf dem das bereits abgerissene Schloss Petit-Brisay gestanden hatte und dessen Herrschaft 1608 ausgestorben war, an neue Besitzer verkauft und das „Material für den Wiederaufbau des Schlosses Purnon verwendet“ worden war. Besonderes Gepräge verleiht der aufwendig gestaltete Dachstuhl in Form eines umgedrehten Schiffsrumpfes im Stil Philibert de l’Ormes, der mit Schiefer eingedeckt ist. 105 Räume dienten neben der Familie und ihren Bediensteten auch größeren Jagdgesellschaften, die im Wald von Scévolles gute Bedingungen vorfanden. Bereits aus dem 17. Jahrhundert ist die zum Besitz gehörende, Moulin Bijard genannte Mühle, der ein Gemüsegarten vorgelagert ist. An seiner Seite steht die 1900 in der Nachfolge Auguste Bollées von E. Lebert errichtete Éolienne, eine Windpumpe, die zur Bewässerung von Schloss und Gemüsegarten diente. Der Windrotor ruht auf einer gusseisernen, zentralen Säule, die über eine spindelförmige Wendeltreppe bis zu ihrer fast 15 Meter hohen Spitze zugänglich ist. Der ganz oben angebrachte Rotor „treibt drei Kolbenpumpengehäuse an, die sich in einer runden Ädikula am Fuß des Bauwerks befinden. Die Pumpen saugen und fördern das Wasser“, das in einen 9000 Liter fassenden Tank des benachbarten, gemauerten Turms gepumpt wurde. Diese Anlage steht seit Dezember 1992 unter Denkmalschutz.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_de_Purnon"},"ch-Q22943820":{"c":"Schloss in Frankreich"},"ch-Q19152931":{"n":"Château de Cornod","c":"Burg in Frankreich"},"ch-Q22940359":{"c":"Schloss in Frankreich"},"ch-Q30742624":{"c":"Schloss in Frankreich"},"ch-Q113277891":{"n":"Dieppe Burg","r":"Die Burg Dieppe ist eine Höhenburg in der Stadt Dieppe im Département Seine-Maritime, die in der Normandie im Norden Frankreichs liegt. Die heutige Anlage wurde im Jahr 1435 30 Meter über den Klippen der Ärmelkanalküste zum Schutz der Stadt Dieppe durch Charles des Marets auf den Überresten einer alten Burg gebaut.","w":"https://de.wikipedia.org/wiki/Burg_Dieppe"},"ch-Q179549":{"n":"Rothenburg","c":"Burg in Frankreich","r":"Die Rothenburg ist die Ruine einer mittelalterlichen Felsenburg in der Nähe der Gemeinde Philippsbourg im Département Moselle. Seitdem sie im 14. Jahrhundert zerstört wurde, ist sie eine Ruine. Die Burg befindet sich auf einem Sandsteinfelsen in 400 Meter Höhe auf einem Ausläufer des Rothenbergs. Von der Burg sind nur noch geringe Mauerreste, Kammern und Geländespuren, wie Zisterne und Burggraben, erhalten.","h":"Erbaut wurde die Burg angeblich schon im 10. Jahrhundert durch den Bischof von Straßburg. Ihre erste urkundliche Erwähnung geschah allerdings erst im 12. Jahrhundert, als sie als Lehen des Straßburger Bischofs genannt wird. Sie wurde zu diesem Zeitpunkt an Lothringen und Zweibrücken-Bitsch übergeben. Da sich der Burgherr Harnach von Weißkirchen als Straßenräuber schuldig machte, wurde die Burg 1309, 1360 oder 1369 durch Straßburger Truppen zerstört und nicht wieder aufgebaut.","w":"https://de.wikipedia.org/wiki/Rothenburg_(Lothringen)"},"ch-Q202249":{"n":"Burg Rocher","c":"Burg in Frankreich","r":"Die Ruine der Burg Rocher, auf Französisch als Château Rocher oder Château de Blot-le-Rocher bezeichnet, ist die Ruine einer Höhenburg in der französischen Auvergne auf dem Gebiet der Gemeinde Saint-Rémy-de-Blot. Seit dem 20. Januar 1913 steht sie als Monument historique unter Denkmalschutz.","w":"https://de.wikipedia.org/wiki/Burg_Rocher"},"ch-Q159147":{"n":"Burg Aubeterre","c":"Burg in Frankreich","r":"Die Burg Aubeterre in Aubeterre-sur-Dronne im Département Charente war eine wichtige Festung, die von der Unterstadt umgeben war, während die Oberstadt um die Abtei herum errichtet wurde.","h":"Die Burg wurde auf dem Hügel errichtet, in den die monolithische Kirche Saint-Jean gegraben worden war. Sie war von Wassergräben und befestigten Esplanaden umgeben, die heute nicht mehr vorhanden sind. Während des Hundertjährigen Krieges wurde die Burg aufgrund ihrer strategischen Lage mehrmals eingenommen und zurückerobert, zuletzt im Jahr 1453. Zu Beginn des 15. Jahrhunderts war die Burg in den Besitz der Familie Bouchard übergegangen, darunter François Bouchard, Baron d’Aubeterre, der zwischen 1476 und 1491 Berater und Kammerherr des Königs und zwischen 1481 und 1491 Seneschall von Angoumois war, die Herrschaft wieder aufbaute und seine Unabhängigkeit vom Abt von Aubeterre und dem Grafen von Angoulême markierte. Im November 1574 wurde Pierre de Bourdeille, besser bekannt als Brantôme, als Nachfolger des Sieur de Chamberlanne zum Verantwortlichen für das Burg ernannt. Die Religionskriege spalteten die Familie Bouchard. Später kehrte David Bouchard, Vicomte d'Aubeterre, zum Katholizismus zurück und wurde ein treuer Anhänger der Könige Heinrich III. und Heinrich IV. Über seine Tochter Hippolyte Bouchard ging das Burg an den Marschall Aubeterre, François d’Esparbès de Lussan († 1628) über; die Herrschaft befand sich nun auf ihrem Höhepunkt. Dessen Nachkommen setzten dem Wohlstand des Ortes durch ihre Streitigkeiten ein Ende. Im 18. Jahrhundert wurde die Burg verlassen. Im Jahr 1810 kam Aubeterre an den Chevalier de Bourbon-Conti, der sie 1817 zerstörte, zerstückelte und verkaufte. Die Burg sah eine Reihe berühmter Personen: Ein Angehöriger der Brémond d'Ars wurde hier enthauptet, Franz I. kam vorbei, Jean Calvin hielt sich hier auf, Heinrich IV.","w":"https://de.wikipedia.org/wiki/Burg_Aubeterre"},"ch-Q374565":{"n":"Château de Kerguéhennec","c":"Burg in Frankreich (Bretagne)","r":"Das Schloss Kerguéhennec ist ein Schloss aus dem 18. Jahrhundert in Bignan. Es beherbergt heute ein Zentrum für zeitgenössische Kunst und ein kulturelles Begegnungszentrum. Das Schloss ist seit Oktober 1988 als historisches Denkmal klassifiziert und eingetragen.","h":"Das etwa 20 km nördlich von Vannes gelegene Schloss Kerguéhennec wurde 1710 vom Architekten Olivier Delourme für zwei reiche Schweizer Finanziers aus St. Gallen, die sich in Paris niedergelassen hatten, die Brüder Hogguer, Aktionäre der Indien-Kompanie, erbaut. Im Jahr 1732 erwarb Guy-Auguste de Rohan-Chabot (1683–1760), Comte de Maillé-Seizplouë, die Domäne als landwirtschaftliches und forstwirtschaftliches Nutzland, der aber dort nicht wohnte. Sein Sohn, Louis-Antoine de Rohan-Chabot (1733–1807), Duc de Rohan, musste sich während der Französischen Revolution von dem Anwesen trennen. Es wurde 1802 vom Comte Louis de Janzé (1784–1869) erworben. Dessen Enkel, Comte Louis Albert Henri de Janzé, verkaufte es 1872 an seinen Vetter Paul-Henri de Lanjuinais, Comte de Lanjuinais (1834–1916), Abgeordneter und später Präsident des Generalrats des Departements Morbihan, ließ es von dem Pariser Architekten Ernest Trilhe prächtig restaurieren. Es war auch Graf Lanjuinais, der 1872 den 170 Hektar großen Park von dem Schweizer Landschaftsarchitekten Denis Bühler anlegen ließ, der 1857 zusammen mit seinem Bruder Eugène den Parc de la Tête d’Or in Lyon entworfen hatte. Die Umgebung des Schlosses wurde à la française gestaltet, während der Norden der Domäne im englischen Stil angelegt wurde. Er beherbergt auch ein Arboretum. Danach ging das Gut durch Erbschaft an Marie Louise Marguerite Lanjuinais, Tochter von Paul Henri Lanjuinais und Ehefrau von Arthur Espivent de La Villeboisnet, über. Schließlich erbte am 12. Juli 1943 die älteste Tochter der beiden, Elisabeth Anne Marie Espivent de la Villesboisnet, die 1933 Graf Pierre d'Humières geheiratet hatte, das Anwesen aus einer ungeteilten Erbengemeinschaft heraus. Sie war es auch, die am 19.","w":"https://de.wikipedia.org/wiki/Schloss_Kergu%C3%A9hennec"},"ch-Q425789":{"c":"Burg in Frankreich"},"ch-Q429529":{"c":"Burg in Frankreich"},"ch-Q775852":{"n":"Château Sigalas-Rabaud","c":"Schloss in Frankreich","r":"Das Weingut Château Sigalas-Rabaud liegt in der Gemeinde Bommes, einem Teil der AOC Sauternes in der Weinbauregion Bordeaux. Bei der Bordeauxwein-Klassifizierung von 1855 wurde es als „Premier Cru Classé“ klassifiziert. Das Gut verfügt über 14 Hektar Fläche, die dem Weinbau gewidmet sind und ist damit das kleinste der Premier-Cru-Güter von Sauternes. Die Rebflächen liegen nur unweit vom ehemaligen Schwestergut Château Rabaud-Promis sowie von Château de Rayne-Vigneau.","h":"Die Geschichte des Gutes lässt sich bis in das Jahr 1660 zurückverfolgen, als die Familie Cazeau durch die Hochzeit von Arnaud de Cazeau mit Marie Peyronne de Rabaud in den Besitz des damaligen Château Rabaud kam. Nachdem die Familie de Cazeau das Weingut mehr als 150 Jahre innegehabt hatte, verkaufte Pierre-Hubert de Cazeau im Jahr 1819 den Besitz an Gabriel Deyme. Die Weine hatten in der Folge einen guten Ruf und folgerichtig wurde das Gut anlässlich der Weltausstellung im Jahr 1855 in den Rang eines Premier Cru Classé eingestuft. Im Jahr 1864 verkaufte Deyme sein Gut an Henri Drouilhet de Sigalas. Henri kaufte in der Folge noch das ehemalige Château Pexoto auf und integrierte die Flächen dieses Deuxième Cru Classé (ein zweites Gewächs) in Château Rabaud, ohne dessen Status als Premier Cru Classé zu verlieren. Sein Sohn trennte sich jedoch im Jahr 1903 von einem Teil des Anwesens und verkaufte ihn an Adrien Promis, der den angekauften Anteil Château Rabaud-Promis nannte. Der verbleibende Anteil der Sigalas Familie erhielt den Namen Château Sigalas-Rabaud. Während der nächsten 26 Jahre wurden die Weine beider Schwestergüter getrennt ausgebaut und der Anteil von Sigalas wurde von Pierre Drouilhet de Sigalas verwaltet. Im Jahr 1929 erbte sein Sohn Gérard Sigalas-Rabaud das Gut und vermachte es später seiner Tochter, die den Marquis René de Lambert de Granges heiratete. De Lambert de Granges engagierte Pierre Ginestet als Geschäftsführer, der bereits Rabaud-Promis besaß. Bis in das Jahr 1949 wurden beide Weine getrennt vermarktet, aber von der gleichen Mannschaft ausgebaut. Diese vorübergehende Annäherung der beiden Güter endete erst mit einem Besitzerwechsel bei Rabaud-Promis.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Sigalas-Rabaud"},"ch-Q542693":{"c":"Schloss in Frankreich"},"ch-Q584950":{"c":"Burg in Frankreich"},"ch-Q465045":{"n":"Château La Tour-Carnet","c":"Schloss in Frankreich","r":"Das Château La Tour-Carnet ist ein bekanntes Weingut von Bordeaux. Seit der Klassifikation von 1855 ist das Weingut als Quatrième Grand Cru Classé eingestuft.","h":"Ursprünglich wurde der Landbesitz Château de Saint-Laurent genannt. Einen großen Schub erhielt Bordeaux im Jahr 1152: Durch die Heirat von Henry Plantagenet, des späteren Königs Heinrich II. von England, mit Eleonore, der Erbin von Aquitanien, geriet ein großer Teil Westfrankreichs unter britische Herrschaft. Das befestigte Anwesen gehörte ab dem 12. Jahrhundert den Engländern. Bereits im 13. Jahrhundert lag die Gemeinde Saint-Laurent im Einflussgebiet des Hauses Foix. Bei der Unterwerfung Bordeaux durch die französische Krone im Jahr 1451 lehnte Jean de Foix und sein Rittmeister Carnet eine Unterwerfung ab. Nach dem Tod von Jean de Foix verwaltete der Rittmeister Carnet das Anwesen ab 1486, konnte aber seine Zerstörung nicht verhindern. Château de Saint-Laurent gehörte anschließend einer Fülle von Besitzern, unter anderem Thibault de Carmaing, Schwager von Michel de Montaigne. Der im Jahr 1685 eingewanderte deutsche Kaufmann Heinrich Luetkens begann kaum 10 Jahre später mit dem Erwerb landwirtschaftlicher Nutzflächen im Bereich des Médoc. Nach der französischen Revolution erwarb dessen Enkel Charles Luetkens (1744–1801) Château de Saint-Laurent. Charles war bereits conseiller du Roi (königlicher Rat) und Rittmeister und kam durch den Erwerb in den Genuss des Titels eines Seigneurs de Tour-Carnet. Ihm gehörten bereits Teile des heutigen Château Saint-Pierre. Zur Zeit der Bordeaux-Klassifizierung stand Château La Tour-Carnet unter der Leitung von Angélique Raymond, der Ehefrau von Jean-Jacques Luetkens. Jean-Jacques, Sohn von Charles, galt als der reichste der Deutschen in Bordeaux. Ab 1861 führte Charles-Oscar de Luetkens die Geschicke des Weinguts. Durch die Reblauskatastrophe, den Echten Mehltau sowie die beiden Weltkriege geriet das Gut in eine tiefe Krise.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_La_Tour-Carnet"},"ch-Q1013622":{"n":"Burg Regnéville","c":"Burg in Frankreich","r":"Die Burg Regnéville ist die Ruine einer Niederungsburg aus dem 14. Jahrhundert in der Gemeinde Regnéville-sur-Mer im französischen Département Manche. Errichtet an der Mündung des Flusses Sienne, sollte sie vom Mittelalter bis zum 17. Jahrhundert den Trockenhafen von Regnéville-sur-Mer, einem der wichtigsten auf der Halbinsel Cotentin, schützen. Gegen Ende des Hundertjährigen Krieges zwischen England und Frankreich teilweise abgebrochen, wurde die Anlage während des 17. und 18. Jahrhunderts zum Teil wieder aufgebaut.","h":"Die Besatzungen, welche die Burg Regnéville verteidigten, waren immer recht klein: durchschnittlich fünf oder sechs bewaffnete Männer und 15 Bogen- oder Armbrustschützen, die unter dem Kommando eines Hauptmanns (französisch: capitain) standen. Die zahlenmäßige Schwäche dieser Truppe lässt Rückschlüsse auf das Verteidigungssystem dieser Anlage zu: eine starke Verteidigung durch umlaufende Wehrgänge auf der Ringmauer. Zwischen dem jeweiligen Landessouverän und den Festungskommandanten wurden Verträge geschlossen. Der Sold für die Besatzung wurde auf diese Weise durch den König von Navarra, den französischen oder den englischen König garantiert. Die Anlage, deren Vorgängerbauten aus dem 11. Jahrhundert stammen, wurde in der Mitte des 14. Jahrhunderts errichtet. Sie bestand unter anderem aus einer Kernburg im Osten, deren Fundamente während Ausgrabungen zwischen 1991 und 1993 freigelegt wurden. Der große Turm, von dem nur zwei seiner vier Seiten teilweise erhalten blieben, befand sich im Nordwesten der Kernburg. Im Westen gegenüber dem Hafen befand sich die Vorburg, ursprünglich der königliche Wohnsitz Karls des Bösen. Nach den Kämpfen im Hundertjährigen Krieg verblieb die damalige Burg in einem traurigen Zustand. Im Jahr 1336 gelangte das Lehen von Regnéville in die Hände des Hauses Navarra. 1349 übernahm Karl der Böse, König von Navarra, den normannischen Besitz seines Vaters Philipp III., Graf von Évreux. Wahrscheinlich wurde die heutige Anlage zu dieser Zeit errichtet. 1364 bestieg Karl V. den französischen Thron. Die Anhänger Karls des Bösen, die mit den Engländern verbündet waren, konnten die Normandie halten und sich dabei auf die zahlreichen befestigten Burgen in der Region stützen. Auch an Regnéville wurden die Befestigungsanlagen verstärkt.","w":"https://de.wikipedia.org/wiki/Burg_Regn%C3%A9ville"},"ch-Q1014045":{"n":"Burg St. Pierre","c":"Burg in Frankreich","r":"Die Burg Saint-Pierre ist die Ruine einer mittelalterlichen Höhenburg auf einer Anhöhe direkt neben dem kleinen Dorf Fenouillet im Département Pyrénées-Orientales. Die Anlage wurde treppenförmig an den Berghang gebaut. Erhalten sind Teile der Außenmauern, ein Gewölbekeller im Inneren der Burg, sowie Mauerreste der Innengebäude.","w":"https://de.wikipedia.org/wiki/Burg_Saint-Pierre_(Aude)"},"ch-Q1013727":{"n":"Burg Roquebrune-Cap-Martin","c":"Burg in Frankreich","r":"Die Burg Roquebrune-Cap-Martin, die nach ihren ehemaligen monegassischen Besitzern auch Château Grimaldi genannt wird, wurde bereits Ende des 10. Jahrhunderts von Conrad I., Graf von Ventimiglia, in Roquebrune-Cap-Martin errichtet. Sie sollte das neuerliche Fußfassen der Sarazenen, die zuvor hier fast zwei Jahrhunderte gewütet hatten, verhindern. Die Höhenburg befindet sich auf dem höchsten Punkt der Gemeinde, die bis heute ihren mittelalterlichen Charakter bewahrt hat.","h":"Nach den Grafen von Ventimiglia ging die Anlage in den Besitz der Grafen der Provence über. Danach gehörte die Burg der Republik Genua, um anschließend mehrere Jahrhunderte den monegassischen Grimaldi zu dienen. Diese gestalteten die Anlage um und legten Artillerie zur Verteidigung in die Burg. Zu Beginn war die Burg eine festungsartige Anlage, die auch das damalige Dorf mit einer schützenden Mauer mit sechs Toren umgab. Im 15. Jahrhundert übernahm der Donjon die Bezeichnung der Burg. Den Rest der befestigten Anlage füllte nach und nach das heutige Dorf mit Wohnbauten aus. 1808 kam die Burg in Privatbesitz, als sie von fünf Bürgern des Ortes gekauft wurde, ehe sie 1911 der Brite Sir William Ingram erwarb. Dieser schenkte die Anlage 1921 der Gemeinde.","w":"https://de.wikipedia.org/wiki/Burg_Roquebrune-Cap-Martin"},"ch-Q1028251":{"n":"Schloss Grosbois","c":"Schloss in Boissy-Saint-Léger, Département Val-de-Marne, Frankreich","r":"Das Schloss Grosbois befindet sich in Boissy-Saint-Léger.","h":"Im Jahr 1190 tauschte Philipp II. von Frankreich mit der Abtei Saint-Victor in Paris die Ländereien von Grosbois gegen andere im Bois de Vincennes. Im Jahr 1226 wurde es als königliche Domäne erwähnt, zu der Johann II. der Gute zur Jagd kam. Die Ländereien wurden 1563 an Raoul Moreau, Trésorier de l’Épargne († 1583), abgetreten, der das Corps de Logis des heutigen Schlosses (1580) errichten ließ, das später von seinem Schwiegersohn Nicolas de Harlay de Sancy († 1629), dem reichen Surintendant des Finances und Surintendant des Bâtiments, erweitert wurde. 1616 wurde das unvollendete Schloss an Charles de Valois (1573–1650) verkauft, Graf von Auvergne und später Herzog von Angoulême (1619), unehelicher Sohn von Karl IX. und Marie Touchet. Anlässlich seiner Wiederverheiratung (1644) mit der 23-jährigen Françoise de Nargonne gab er bei dem Graveur Abraham Bosse eine Wanddekoration für das sogenannte Ehrengemach des Schlosses in Form von großen Kompositionen in Auftrag, die die Zeremonie unter einer „französischen“ Decke zeigen, die mit Kartuschen bemalt war, die mit der Hochzeitschiffre geschmückt waren. Dieses Dekor wurde 1910 zufällig unter mehreren Schichten Tapete wiederentdeckt. Die Zuschreibung der Wandmalereien an Horace Le Blanc ist unter Fachleuten umstritten. Charles d’Angoulême ließ das Schloss um 1640 fertigstellen. Er ließ insbesondere die Umfassungsmauer (1623) und die beiden Flügel errichten, die den Ehrenhof begrenzen. In ihren Memoiren erwähnt Catherine de la Guette mehrere Aufenthalte im Schloss Grosbois, insbesondere um ihre Schwester Marie Meurdrac oder die Herzogin von Angoulême zu besuchen. Nach Charles’ Tod im Jahr 1650 ging das vergrößerte Anwesen an seine Enkelin Françoise de Valois, die Herzogin von Joyeuse († 1696), über.","w":"https://de.wikipedia.org/wiki/Schloss_Grosbois"},"ch-Q1090345":{"n":"Château Branaire-Ducru","c":"Schloss in Frankreich","r":"Das Château Branaire ist ein bekanntes Weingut von Bordeaux. Seit der Klassifikation von 1855 ist das Weingut als „Quatrième Grand Cru Classé“ eingestuft, also in der vierten Stufe der Klassifikation.","h":"Die frühe Geschichte des Guts ist mit der von Château Beychevelle identisch; der Landbesitz war ursprünglich Teil der Seigneurie de Lamarque. Das Land von Beychevelle wurde mindestens seit dem frühen 14. Jahrhundert bebaut. Im späten 14. Jahrhundert erbaute man eine Anlage mit befestigtem Donjon in der Nähe der Gironde, um die Mündung gegen Angriffe im „Hundertjährigen Krieg“ verteidigen zu können. Ende des 14. Jahrhunderts gehörte der Besitz Archambaud de Grailly. Archambaud heiratete im Jahr 1381 Isabelle de Foix, so dass der Besitz im Rahmen der Erbteilung des Besitzes aus dem Haus Grailly in das Haus Foix-Candale überging. Als Jean Louis de Nogaret de La Valette im Jahr 1587 mit Marguerite de Foix-Candale die Alleinerbin des Guts heiratete, ging das unter dem Namen Château de Médoc bekannte Anwesen in den Besitz der Herzöge von Épernon. Jean Louis de Nogaret de La Valette galt zu seiner Zeit als einer der mächtigsten Männer Frankreichs. Jean Louis’ Sohn Bernard de Nogaret de La Valette zeigte ähnlich wie sein Vater nur geringes Interesse an diesem Anwesen, und als er am 25. Juli 1661 starb, hinterließ er einen hohen Schuldenberg. Zur Tilgung der Schulden ging Beychevelle kurzzeitig an das Königshaus und wurde schließlich an die Familie Abbadie verkauft. Unter der Regie der Familie Abbadie wurde der Besitz von Beychevelle aufgeteilt, und im Jahr 1680 kaufte Jean-Baptiste Braneyre einen Teil dessen, der heute unter dem Namen Branaire-Ducru bekannt ist. Jean-Baptistes Tochter Marie heiratete Pierre du Luc, sodass der Besitz in die Familie du Luc überging. Später erbte ihr 1730 geborener Sohn Laurent du Luc das Gut. Laurent heiratete im Jahr 1779 Marie de Chillaud des Fieux de Larenchère, Tochter eines Offiziers.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Branaire-Ducru"},"ch-Q1090324":{"n":"Château Batailley","c":"Weingut in Bordeaux","r":"Das Château Batailley ist ein bekanntes Weingut von Bordeaux. Seit der Klassifikation von 1855 ist das Weingut als Cinquième Grand Cru Classé eingestuft.","h":"Die Ursprünge von Château Batailley sind ungewiss; zum Namen gibt es mehrere Vermutungen. Die Nähe des Namens zum französischen Wort bataille (Schlacht) nährt die plausible These, dass die Nutzfläche des Châteaus zum Verteidigungsring von Bordeaux während des Hundertjährigen Kriegs gehörte. Von diversen Weingütern der Region wie zum Beispiel dem nahe gelegenen Château Latour ist eine entsprechende Nutzung bekannt. Eine alternative Erklärung spricht von einem Winzer oder Händler namens Batailley, der eine Rolle in der Geschichte des Gutes gespielt haben solle. Im 18. Jahrhundert finden sich schriftliche Erwähnungen zum Weingut. Château Batailley gehörte damals der Familie Saint-Martin. Zu Ende des Jahrhunderts ging der Besitz durch Erbteilung an die drei Kinder der Familie über. Die beiden Töchter Marianne und Marthe Saint-Martin verkauften ihren Anteil im Jahr 1791 an Jean-Guillaume Pécholier. Als Pécholier im Jahr 1816 starb, ging ein großer Teil des Gutes bei einem öffentlichen Verkauf an Daniel Guestier vom Handelshaus Barton & Guestier (siehe auch die Geschichte von Château Léoville-Barton). Es ist überliefert, dass Admiral Jaques de Bédout nach seiner Dienstfreistellung bis zu seinem Tod im Jahr 1818 auf Château Batailley lebte. Guestier kaufte im Laufe der Zeit kleinere Parzellen hinzu und investierte in die Nutzflächen, in den Weinkeller sowie in das Wohnhaus. Als er im Jahr 1847 starb, hatte das Gut bereits einen guten Ruf; der Grundstein für das gute Abschneiden bei der Klassifikation von 1855 war gelegt.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Batailley"},"ch-Q1090428":{"n":"Château Ducru-Beaucaillou","r":"Das Château Ducru-Beaucaillou ist eines der berühmtesten Weingüter von Bordeaux. Seit der Klassifikation von 1855 ist das Weingut als Deuxième Grand Cru Classé eingestuft, der zweithöchsten Stufe der Klassifikation.","h":"Ursprünglich entstand das Gut aus einer Aufteilung der Baronie Beychevelle. 1795 wurde das Château von Bertrand Ducru erworben. Angeblich ist die Klassifizierung als Deuxième Cru 1855 der Tatsache zu verdanken, dass während der Sitzungen des Klassifizierungskomitees ständig Ducru-Beaucaillou ausgeschenkt wurde. 1866 wurde der Besitz um eine Million Franc von der Familie Johnson erworben, die ihn 1928 an Desbartes de Burke veräußerte. 1941 ging das Gut an die Familie Borie.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Ducru-Beaucaillou"},"ch-Q1090441":{"n":"Château Figeac","c":"Weingut in der Region Bordeux","r":"Das Château Figeac ist eines der bedeutendsten und traditionsreichsten Weingüter der französischen Gemeinde Saint-Émilion in der Region von Bordeaux. In der Hierarchie der Rotweine von Saint-Émilion gehört es seit dem Jahr 2022 als Premier Grand Cru Classé A der höchsten Stufe an. Das Château befindet sich seit 1892 im Eigentum der Familie Manoncourt.","h":"Die Ursprünge des Gutes liegen wohl in römischer Zeit, zumindest wird sein Name auf eine gallo-römische Villa des 2. Jahrhunderts namens Figeacus zurückgeführt. Der Besitz bestand das ganze Mittelalter hindurch und gehörte nacheinander verschiedenen führenden Familien der Region. Die ältesten Partien des Schlossgebäudes stammen aus dem 15. Jahrhundert. Im 17. Jahrhundert kam es an die Familie Carle, deren Mitglied François de Carle von Ludwig XIV. zum Bürgermeister von Saint-Émilion auf Lebenszeit ernannt wurde. Im 18. Jahrhundert baute Élie de Carle das Château Figeac zum großen Weingut aus. Er ließ auch das Schloss erneuern. Damals umfasste das Gut 250 Hektar Weinberge, Wälder und Weideland. Der Wein wurde an begüterte Kunden in ganz Europa geliefert. Nach seinem Tod brachte der aufwändige Lebensstil seiner Witwe das Gut jedoch in wirtschaftliche Schwierigkeiten. Nach und nach wurden Teile verkauft, aus denen dann später selbst berühmte Weingüter hervorgingen. Das restliche Gut wechselte im 19. Jahrhundert mehrmals den Besitzer. 1892 kaufte es André Villepigue und seine Frau Henriette de Chèvremont, die Großeltern von Thierry Manoncourt. Sein Sohn, Robert Villepigue, Agraringenieur, hat 1906 das berühmte Etikett kreiert. Thierry, der ein junger Agraringenieur war, begann nach seinem Studium im Jahr 1947, auf Château Figeac zu arbeiten. Seine beharrliche, wissenschaftlich untermauerte Arbeit an Weinbergen und Keller brachte Château Figeac wieder seinen früheren Rang zurück. Thierry Manoncourts Priorität war zunächst nicht der Weinbau, sondern das Verständnis über die Gegebenheiten der Böden, besonders der drei mit Kiesboden bedeckten Kuppen aus der Günzeiszeit, die im Herzen des Terroirs von Figeac stehen.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Figeac"},"ch-Q1090500":{"n":"Château La Lagune","c":"Weingüter von Bordeaux","r":"Das Château La Lagune ist eines der bekannten Weingüter von Bordeaux. Seit der Klassifikation von 1855 ist das Weingut als Troisième Grand Cru Classé eingestuft.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_La_Lagune"},"ch-Q1090516":{"n":"Château Lafaurie-Peyraguey","c":"Weingut in Frankreich","r":"Château Lafaurie-Peyraguey ist eines der bekanntesten Weingüter für die Herstellung des Süßweins von Sauternes. Das Weingut liegt in unmittelbarer Nachbarschaft zu Château d’Yquem, in der Nähe der höchsten Stelle des Ortsteils Bommes gelegen.","h":"Die Ursprünge des Guts liegen im Dunkeln. Bekannt ist lediglich, das ab 1618 der Bürger Raymond Peyraguey ein Anwesen und umfangreiche Ländereien in Bommes besaß. Château Peyraguey wurde am 17. Juli 1742 von Baron Nicolas-Pierre de Pichard, dem damaligen Präsidenten des lokalen Parlement von Bordeaux aufgekauft. De Pichard war später auch Besitzer der Weingüter Coutet und Lafite. Während der Französischen Revolution wurde de Pichard am 30. Juni 1794 hingerichtet und das Gut in Staatseigentum überführt. Während nahezu 2 Jahren wurde das unter dem Namen Château Pichard-Peyraguey bekannte Weingut an einen lokalen Winzer namens Vignon verpachtet. Am 22. Juni 1796 erwarb Herr Lafaurie das Weingut mit seinen Ländereien für die Summe von 79.500 Francs. Lafaurie verhalf dem Weingut zu Ansehen. Im Jahr 1837 vermachte Lafaurie seinen beiden Söhnen das Weingut. Im Jahr 1860 heiratete eine Witwe Lafaurie den Journalisten und Schriftsteller Jean Saint-Rieul-Dupouy. Er machte das Weingut auch am spanischen Königshof bekannt und trug zur steigenden Bekanntheit der Weine von Peyraguey bei. König Alfons XII von Spanien galt als großer Verehrer der Weine von Château Pichard-Peyraguey. Das Ehepaar verkaufte das Weingut jedoch im Jahr 1865 an Charles Marie Tanneguy Duchâtel, einen ehemaligen Innenminister von Ludwig Philipp I. und Mitglied der Académie des sciences morales et politiques sowie Eigner von Château Lagrange. Duchâtel investierte erhebliche Summen in das Anwesen und die Weinberge. Das heutige Aussehen der Gutsgebäude von Lafaurie-Peyraguey geht im Wesentlichen auf diese Investitionen zurück. Nach dessen Tod 1879 ging Château Pichard-Peyraguey an seine Enkelin Charlotte de Trémoille und wurde kurz darauf aufgeteilt.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Lafaurie-Peyraguey"},"ch-Q1090564":{"n":"Château Malescot Saint-Exupéry","c":"französisches Weingut","r":"Château Malescot Saint-Exupéry ist ein französisches Weingut in der Appellation Margaux, auf der Halbinsel Médoc. Das 23,5 Hektar große Gut erhielt 1855 im Rahmen der Bordeaux-Klassifizierung den Rang eines Troisième Grand Cru.","h":"Die ersten Rebflächen wurden im 16. Jahrhundert durch die Familie Escoussé angelegt; die einzelnen Parzellen trugen die Namen La Dame, Curton, Lalongua, Puch-Sam-Peyre, Ourmatan, Lacoste. Am 1. August 1697 verkaufte Louise Escoussé den Familienbesitz an Simon Malescot. Dessen Familie führte das Weingut in eine erste Blüte. Als am 5. Februar 1827 Jean-Baptiste de Saint-Exupéry (der Urgroßvater des Schriftstellers Antoine de Saint-Exupéry) das Gut kaufte und dem Gut noch die Parzelle Loyac hinzufügte, gehörte das Château zu den besten Weinproduzenten im Bordelais. Der Nachfolgebesitzer M. Fourcade ließ das heute bekannte Anwesen sowie den Weinkeller anlegen. Nach zahlreichen Übernahmen – zwischen 1880 und 1955 hatte das Weingut insgesamt fünf Besitzer, die durch Reblauskatastrophe, Mehltau und Kriege entmutigt aufgaben – gelangte es in Besitz der englischen Familie W. H. Chaplin. Diese verkaufte es gemeinsam mit dem Château Marquis d’Alesme-Becker im Jahre 1955 an die Familie Zuger. Vom Château Malescot Saint-Exupéry waren nur noch sieben Hektar Rebfläche übrig geblieben und das Anwesen in sehr schlechtem Zustand. Die beiden Güter wurden bis zum Jahre 1979 gemeinsam betrieben und wieder zu alter Qualität geführt. Château Malescot Saint-Exupéry wird derzeit von Roger Zuger geleitet, Château Marquis d’Alesme-Becker von Jean-Claude Zuger.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Malescot_Saint-Exup%C3%A9ry"},"ch-Q1090575":{"n":"Château Marquis de Terme","c":"Weingut","r":"Das Château Marquis de Terme ist ein recht bekanntes Weingut von Bordeaux. Seit der Klassifikation von 1855 ist das Weingut als Quatrième Grand Cru Classé eingestuft.","h":"Am 7. September 1661 erwarb Pierre des Mesures de Rausan, ein bedeutender Händler der Region, das Weingut von der Familie de Gassies. Die Familie de Gassies stand den Lehnsherren der Seigneurie de Margaux nah. Dieses Weingut war der Ursprung der heute bekannten Château Rauzan-Gassies, Château Rauzan-Ségla, Château Desmirail und Château Marquis de Terme. Pierre des Mesures de Rausan war seit 1661 auch Pächter von Château Margaux und seit 1679 Pächter von Château Latour. Aus dem im Jahr 1661 erworbenen Landbesitz entstanden die noch heute bekannten Château Rauzan-Gassies, Château Rausan-Ségla, Château Desmirail und Château Marquis de Terme. Der Name „Marquis de Terme“ taucht erstmals im Jahr 1762 mit der Hochzeit von Ledoulx d’Emplet mit dem Marquis de Terme, François de Peguilhan de Larboust, auf. Das Ehepaar verfügte über 30 Hektar Grundbesitz, und der Wein erfreute sich eines guten Rufs. Während seines Bordeaux-Besuchs vom 24. bis zum 28. Mai 1787 stattete der damalige Botschafter in Frankreich, Thomas Jefferson, dem Gut einen Besuch ab. Nach dem Tod von François de Peguilhan erwarb der Weinhändler Halvarous Sollberg im Jahr 1809 das Gut. Sollberg war schwedischer Herkunft und hatte sich in ein wohlhabendes französisches Haus eingeheiratet. Sollberg tätigte in der Folge eine Reihe von Ankäufen diverser Landparzellen und türmte dabei einen erheblichen Schuldenberg auf. In der Folge seiner nicht nachgekommenen finanziellen Verpflichtungen musste er 1834 Frankreich verlassen, konnte das Gut aber im Jahr 1845 zurückgewinnen. Anlässlich der Weltausstellung im Jahr 1855 erhielt das Weingut den Rang eines vierten Gewächses. Zu dieser Zeit führte Halvarous Sohn Oscar bereits das Gut.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Marquis_de_Terme"},"ch-Q1090681":{"n":"Château Suduiraut","c":"Schloss in Frankreich","r":"Das Weingut Château Suduiraut liegt im Süden der Gemeinde Preignac, einem Teil der Appellation d’Origine Contrôlée Sauternes in der Weinbauregion Bordeaux. Bei der Bordeauxwein-Klassifizierung von 1855 wurde es als „Premier Cru Classé“ klassifiziert. Das Gut verfügt über fast 200 Hektar Grundbesitz, von denen 92 Hektar dem Weinbau gewidmet sind. Die Rebflächen liegen unweit des berühmten Château d’Yquem.","h":"Die Geschichte des Weinguts beginnt im Jahr 1580, als Léonard de Suduiraut, Mitglied des Parlements von Bordeaux Nicole d’Allard heiratet. Nicole war Alleinerbin der Ländereien, auf denen das heutige Gut errichtet wurde. Während fast 50 Jahren konnte die Familie de Suduiraut das Gut ungestört entwickeln. Zur Zeit der Fronde überwarf sich die Familie jedoch mit dem königstreuen Bernard de Nogaret de La Valette d’Épernon. In der Folge wurde das Gut zwischen 1648 und 1649 geplündert und gebranntschatzt. Léonards Enkel, der Graf Blaise de Suduiraut errichtete zwischen 1665 und 1675 eines der herrschaftlichsten Gutshäuser des Bordeaux und ließ die Gartenanlage von André Le Nôtre anlegen. Nach dem Tod von Blaise de Suduiraut, der mit Gabrielle Angélique de Pontac verheiratet war, ging das Anwesen zuerst an seine Tochter Marie-Anne und später an den Neffen von Marie-Anne, Joseph du Roy (Sohn von Cathérine de Suduiraut und Jean du Roy). Joseph benannte das Gut in Ancien Cru du Roy um. Nach dem Tod von Joseph ging der Besitz erst an seinen Sohn Jean und später an Louis-Guillaume du Roy. Dessen Nachname auch häufig Duroi oder Duroy geschrieben wurde. Seine Ehe mit Marie-Rose blieb offensichtlich kinderlos, den sie vermachte das Gut nach dem Tod von Louis-Guillaume an den Angestellten Nicolas Edme Guillot. Unter seinem Wirken nahm das Gut einen großen Aufschwung. In den Familienarchiven der Familie Guillot de Suduiraut ist noch die Korrespondenz von Nicolas mit seinem Neffen Dominique Doutreleau erhalten, der sich als Weinhändler auf Guadeloupe niederließ und die Weine von Suduiraut importierte. Nicolas Edme Guillot kaufte im Jahr 1831 das nachbarschaftliche Gut von Castelnau und weitete seinen Besitz damit erheblich aus. Der Name des Zweitweins des Guts erinnert an diese Zeit.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Suduiraut"},"ch-Q608624":{"n":"Schloss Courtanvaux","c":"Burg in Frankreich","r":"Das Schloss Courtanvaux befindet sich in der Gemeinde Bessé-sur-Braye im Département Sarthe.","h":"Vorgängerbauten gehen auf das 14. Jahrhundert zurück, als die Herren von Bessé ein Herrenhaus errichten ließen, das auch der Bevölkerung im Konfliktfall als Zufluchtsort dienen sollte. Das Herrenhaus hatte jedoch nur einen geringen strategischen Wert. Erst ein Jahrhundert später gewann Courtanvaux an Bedeutung. So wurde Mitte des 15. Jahrhunderts Jacques Berziau, Secrétaire général des Königs, zum Besitzer. Er unternahm zahlreiche Umbauten und vergrößerte das Anwesen zwischen 1450 und 1490 um eine Kapelle, ein Petit Château, einen Taubenschlag und vor allem um das Hauptgebäude. Das Schloss Courtanvaux wurde durch Erbschaft oder Heirat weitergegeben, und drei Familien folgten einander und bauten das Anwesen immer weiter aus, bis es 1978 an die Gemeinde Bessé-sur-Braye verkauft wurde. Die Familie Souvré war von 1500 bis 1661 Eigentümer des Ortes und verlieh den Gebäuden einen Hauch von Renaissance, der durch die unter Denkmalschutz stehende Poterne aus dem Jahr 1582 symbolisiert wird. Gilles de Souvré, Marschall von Frankreich, Gouverneur von Touraine, Grand-maître de la Garde-robe Heinrichs IV. und Hauslehrer von Ludwig XIII. ließ das Eingangstor errichten. Heinrich IV. erhob Courtanvaux in den Rang einer Markgrafschaft. Souvrés Nachkommen setzten sein Werk bis zur Heirat seiner Enkelin Anne de Souvré mit François Michel Le Tellier, Marquis de Louvois und Kriegsminister unter Ludwig XIV., fort. Als beide Eheleute gestorben waren, verloren die Erben der Familie Le Tellier de Louvois das Interesse an Courtanvaux, so dass das Schloss von 1691 bis 1815 unbewohnt blieb. 1780 heiratete Louise Charlotte Françoise Le Tellier, die Erbin der Domäne, den Grafen Pierre de Montesquiou-Fezensac.","w":"https://de.wikipedia.org/wiki/Schloss_Courtanvaux"},"ch-Q628389":{"c":"Burg in Frankreich"},"ch-Q671459":{"n":"Burg Falkenstein","c":"Burg bei Philippsburg in Lothringen","r":"Burg Falkenstein ist die Ruine einer Felsenburg aus dem 12. Jahrhundert in der Nähe der Gemeinde Philippsbourg im Département Moselle (Lothringen). Seitdem sie im 17. Jahrhundert zerstört wurde, ist sie eine Ruine. Sie befindet sich auf einem 120 Meter langen, etwa 22 Meter hohen und drei bis acht Meter breiten Sandsteinfelsen in 386 Meter Höhe. Etwa hundert Meter entfernt, am östlichen Ende des Berges, befindet sich die Ruine der Burg Helfenstein.","h":"Das Falkensteiner Tal gehörte im 11. Jahrhundert zur Grafschaft Lützelburg. Die Burg wurde 1127 von Graf Peter von Lützelburg als Schutz gegen das Vordringen der Staufer nach Westen errichtet. Die Lützelburger starben im Laufe des Jahrhunderts aus, und es folgte ein Erbstreit zwischen den Grafen Montbéliard und den Grafen von Saarwerden. Kaiser Friedrich Barbarossa griff 1143 in den Streit ein und gab die Burg an Graf Volmar von Saarwerden. Die Ministerialen der Burg trugen 1205 ihr Amt als Lehen der Grafen von Saarwerden. In jenem Jahr wurde auch der erste bekannte Falkensteiner, Jacob von Falkenstein, genannt. Die Falkensteiner verbündeten sich 1316 mit Ludwig dem Bayern gegen Friedrich den Schönen. Ab 1328 war die Burg im Besitz von Graf Friedrich II. von Saarwerden. Dieser gab seinen Teil 1334 an Graf Wilhelm von Windstein ab. Ein Jahr später herrschte Burgfrieden zwischen den Falkensteinern und den Grafen von Saarwerden. 1377 wurde die Burg durch die Herren von Lichtenberg belagert, erobert und war nun Allod der Herren von Lichtenberg. Die Burg wurde aber anschließend den Falkensteinern als Lehen wieder gegeben. Formal war sie nun dem Amt Ingweiler der Herrschaft Lichtenberg und später den Erben der Herren von Lichtenberg, ab 1480 der Grafschaft Zweibrücken-Bitsch, ab 1570 der Grafschaft Hanau-Lichtenberg und ab 1736 der Landgrafschaft Hessen-Darmstadt, zugeordnet. Als vergebenes Lehen war die Burg aber eine Einheit, die weitgehend außerhalb der Zuständigkeit der Amtsverwaltung in Ingweiler durch die Falkensteiner verwaltet wurde. Die Herren von Finstingen-Brakenkopf bekamen 1414 den saarwerdischen Anteil. 60 Jahre später, also 1474, starb Wilhelm von Falkenstein, woraufhin seine Söhne Gottfried, Ortlieb und Wilhelm die Burg erbten und bewohnten.","w":"https://de.wikipedia.org/wiki/Burg_Falkenstein_(Philippsbourg)"},"ch-Q897692":{"n":"Burg Brancion","c":"Burg im Département Saône-et-Loire, Frankreich","r":"Die Burg Brancion ist die Ruine einer mittelalterlichen Höhenburg im französischen Dorf Brancion, das zur burgundischen Gemeinde Martailly-lès-Brancion im Département Saône-et-Loire gehört.","h":"Einer Legende zufolge soll der Felsen, auf dem die Burg steht, bereits zur Zeit der Burgunderkönige befestigt gewesen sein. Die früheste wissenschaftlich nachweisbare Nutzung des Burgareals datiert indessen erst in den Zeitraum von 850 bis 900. Dies beweisen Grabungsfunde, deren Alter mittels der C14-Methode bestimmt wurde. Erste urkundliche Erwähnung fand Brancion 926 in einer Urkunde der Abtei Cluny, erster gesicherter Grundherr war der 927 verstorbene Warulf de Brancion. Dessen Sohn Liébaud folgte ihm als Herr von Brancion nach. Um das Jahr 1100 gelangten Burg und Seigneurie an Bernard, den Herrn der benachbarten Seigneurie Uxelles, der beide Herrschaften vereinte. Die daraus entstandene Seigneurie war seinerzeit sehr bedeutend und die Herren von Brancion entsprechend mächtig, was sie zum Ausdruck brachten, indem sie diverse Generationen lang den Beinamen „der Große“ (französisch Gros, lateinisch Grossus) trugen. Josserand III. de Brancion nahm im Gefolge des Grafen von Toulouse, Alfons von Poitiers, am Sechsten Kreuzzug teil und starb 1250 in der Schlacht von al-Mansura. Eine Wandmalerei im Donjon der Burg erinnert an ihn und seine Kreuzzugsteilnahme. Josserands Sohn Henri III. verkaufte Burg und Seigneurie 1259 wegen finanzieller Probleme an Hugo IV. von Burgund. Die Herzogsfamilie nutzte die Anlage nicht selbst, sondern ließ sie durch Kastellane verwalten. Im Zuge der Feindseligkeiten zwischen den Armagnacs und Bourguignons stationierte Herzog Johann Ohnefurcht 1409 Soldaten im gut befestigten Brancion. Burg und Ort wurden im anschließenden Bürgerkrieg der Armagnacs und Bourguignons mehrfach belagert, sogar noch nach dem 1435 geschlossenen Vertrag von Arras, der die jahrelang schwelenden Konflikte offiziell beilegte.","w":"https://de.wikipedia.org/wiki/Burg_Brancion"},"ch-Q931820":{"n":"Château Boyd-Cantenac","c":"Schloss in Frankreich","r":"Château Boyd-Cantenac ist ein französisches Weingut in der Appellation Margaux, auf der Halbinsel Médoc. Das 17 Hektar große Gut im Ortsteil Cantenac erhielt 1855 im Rahmen der Bordeauxwein-Klassifikation den Rang eines 3ième Grand Cru.","h":"Am 11. August 1754 kaufte der irischstämmige Jacques Boyd Rebflächen von der Familie Bernard de Sainvincens und gründete damit das Weingut. Am 28. August 1806 ging das Gut an John Lewis Brown (Onkel des gleichnamigen Malers John Lewis Brown) über, der in die Familie Boyd eingeheiratet hatte und Jacques Boyd Schwiegersohn war. Den größeren Teil nannte er Château Cantenac-Brown. Brown ging im Jahre 1840 in Konkurs und musste seinen ganzen Rebbesitz unter dem Namen Boyd an einen Bankier abgeben. Im Jahre 1860 wurde der kleinere Besitzteil von Armand Lalande gekauft und unter dem endgültigen Namen Château Boyd-Cantenac betrieben. Zwischenzeitlich gehörte das Weingut der Familie Ginestet. Diese Familie war zu jener Zeit auch Inhaber von Château Margaux. 1932 übernahm die Familie Guillemet das Weingut, die das Weingut bis heute (Stand 2005) neben Château Pouget betreibt.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Boyd-Cantenac"},"ch-Q939432":{"n":"Burg Helfenstein","c":"Burg bei Philippsburg in Lothringen","r":"Burg Helfenstein, vor 1928 auch Wachtfels genannt, ist die frei zugängliche Ruine einer mittelalterlichen Felsenburg im französischen Département Moselle nahe der Grenze zum Département Bas-Rhin und zu Rheinland-Pfalz.","h":"1225 wird ein Ruodegerus de Helphenstein lacius genannt. Es ist aber nicht klar, ob dieser sich auf die Burg bezieht. Sicher ist, dass der Helfenstein zu Beginn des 14. Jahrhunderts den Herzögen von Lothringen gehörte. Diese gaben sie den Vögten von Wasselnheim zu Lehen. Wahrscheinlich wurde Helfenstein um 1435 in einer Fehde zerstört. Im Jahre 1938 wurden die Ruinen Helfensteins und Falkensteins von französischen Artilleristen genutzt. Heute befindet sich die Burg in französischem Staatsbesitz.","w":"https://de.wikipedia.org/wiki/Burg_Helfenstein_(Lothringen)"},"ch-Q941308":{"n":"Schloss Touffou","c":"Schloss in Frankreich","r":"Das Schloss Touffou ist ein Schloss auf dem Gebiet der französischen Gemeinde Bonnes im Département Vienne und steht somit in der Region Nouvelle-Aquitaine. Es steht seit 1923 als Monument historique unter Denkmalschutz.","w":"https://de.wikipedia.org/wiki/Schloss_Touffou"},"ch-Q947416":{"n":"Burg Mörsberg","c":"Burg in Frankreich","r":"Die Burg Mörsberg ist die Ruine einer Höhenburg im südlichen Elsass (Sundgau), die zwischen den französischen Gemeinden Oberlarg und Levoncourt im französisch-schweizerischen Grenzgebiet liegt. Seit dem 1. Oktober 1841 steht sie als Monument historique unter Denkmalschutz.","h":"Der genaue Entstehungszeitpunkt der Burg ist nicht bekannt. Höchstwahrscheinlich begann der Burgenbau ab Mitte des 12. Jahrhunderts durch Adalbert von Mörsberg, einem Angehörigen eines lokalen Adelsgeschlechtes, das als Ministerialen im Dienste der Grafen von Pfirt stand und sich fortan nach ihrem Stammsitz von Mörsberg nannte. Die Existenz einer älteren Anlage, die bereits im 8. Jahrhundert auf dem Gebiet entstanden sein soll, wird vermutet, kann jedoch nicht eindeutig belegt werden. Die erste gesicherte urkundliche Erwähnung der Herren von Mörsberg stammt aus dem Jahr 1183, als der Bischof von Basel einen Rechtsstreit zwischen Lütfried von Pfirt, Ulrich von Butingen und Heinricus und Walterus de Morsberc entschied. Die Burg selbst wird in Urkunden aus den Jahren 1241 und 1243 zum ersten Mal als pfirtisches Lehen erwähnt. Aus dem Jahr 1271 findet sich eine weitere Erwähnung in den Quellen, als die Herrschaft Pfirts an den Bischof von Basel verkauft wurde. Neue Lehnsherren fanden die Herren von Morimont mit dem Tod des letzten Grafen von Pfirt im Jahr 1324, dessen Erbe, darunter auch Burg Morimont an die Habsburger überging. Dieses Lehen wurde fortan bis in das 16. Jahrhundert erneuert. 1356 wurde Mörsberg, wie viele andere Burganlagen in der Region, beim Erdbeben von Basel schwer beschädigt und musste neu aufgebaut werden. Weitere verheerende Zerstörungen erfolgten durch eidgenössische Truppen in den Feldzügen von 1445 und 1468 durch den Sundgau, als sich Peter von Mörsberg auf österreichischer Seite gegen die Schweizer stellte. Ab Mitte des 15. Jahrhunderts erlangten die Herren von Mörsberg durch verpfändete Lehen beträchtlichen finanziellen Wohlstand und stiegen als vorderösterreichische, später als kaiserliche Landvögte und durch Heiratspolitik auch politisch auf.","w":"https://de.wikipedia.org/wiki/Burg_M%C3%B6rsberg"},"ch-Q943636":{"c":"Burg in Frankreich"},"ch-Q952229":{"c":"Burg in Frankreich"},"ch-Q967293":{"n":"Château de Lussac","c":"Schloss in Frankreich","r":"Château de Lussac ist ein Weingut von 30 Hektar Größe im gleichnamigen Ort Lussac im französischen Anbaugebiet Lussac-Saint-Émilion. Das Schloss steht in dem 2000-Einwohner-Dorf gleich neben der Kirche und wurde im Jahr 1876 von dem leidenschaftlichen Winzer Gaston Montouroy (1855–1903) erbaut, der das Gebäude an seinen Schwiegersohn, den Marquis de Sercey, übertrug. Bis in die 1980er Jahre verblieb das Anwesen in der Familie. Nach einer 15 Jahre währenden Verpachtung an Olivier Roussel ging die Immobilie an das Ehepaar Griet und Hervé Laviale aus Bordeaux, die das Weingut in wenigen Jahren zum Flaggschiff dieser Region machen konnten.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_de_Lussac"},"ch-Q961377":{"c":"Burg in Frankreich"},"ch-Q1011384":{"n":"Burg Couzan","c":"Burg in Frankreich","r":"Die Burg Couzan ist die Ruine einer mittelalterlichen Burganlage oberhalb der französischen Ortschaft Sail-sous-Couzan im Département Loire. Sie ist ein typisches Beispiel für die mittelalterliche Wehrarchitektur des Forez und geht auf eine Gründung des 11. Jahrhunderts zurück. Sie war Stammsitz der Familie Damas, einer Nebenlinie des Hauses Semur, die sie im 13. bis 15. Jahrhundert immer weiter ausbaute und vergrößerte. Im 15. Jahrhundert an die Familie Lévis gelangt, begann der allmähliche Niedergang der Anlage, die fortan nicht mehr als Wohnsitz genutzt wurde. Schon im 17. Jahrhundert war sie eine Ruine.","h":"Die Anfänge der Burg liegen im 11. Jahrhundert, doch das genaue Baudatum sowie der Bauherr sind unbekannt. Die Gründung muss aber vor 1075/1076 erfolgt sein, denn in einer Urkunde aus jener Zeit wird bereits eine Burgkapelle in castro Cosan erwähnt. Mittels der Radiokarbonmethode konnte die älteste erhaltene Bausubstanz der ersten Burganlage zudem in den Zeitraum zwischen 1025 und 1084 datiert werden. Eine Ausgrabung im Jahr 2016 lieferte Beweise dafür, dass der Burghügel allerdings schon in karolingischer Zeit besiedelt war. Die Burg gehörte anfangs dem Haus Semur, später einer Nebenlinie dieser burgundischen Adelsfamilie, dem Haus Damas-en-Forez. Mitte des 12. Jahrhunderts war Hugues de Damas Herr von Couzan. Seine Familie konnte lange Zeit ihre Unabhängigkeit gegenüber den mächtigen Grafen von Forez behaupten, aber 1229 musste Renaud de Damas die Lehnshoheit der gräflichen Familie über Couzan endgültig anerkennen. Ungefähr in jenem Jahr war die Burg Streitobjekt zwischen der Familie von Beaujeu und den Grafen von Forez. Humbert V. de Beaujeu belagerte Couzan und erhielt seine Rechte darüber sogar vom französischen König Ludwig IX. bestätigt, Graf Guigues IV. von Forez zwang ihn aber zur Aufgabe seiner Ansprüche. Im 13. Jahrhundert erhielt der einfache romanische Herrschaftssitz einen neuen Saalbau (um 1279) und wurde durch den Bau eines runden Bergfrieds verstärkt. Die Familie der Burgherren geriet Ende des 13. Jahrhunderts in finanzielle Probleme, die erst im Jahr 1326 durch die Hochzeit Hugues de Damasʼ mit Alice de La Perrière ein Ende fanden, denn die Braut brachte die immense Mitgift von 2000 Livre tournois in die Ehe. Bereits 1320 hatten die Herren von Couzan von König Philipp VI.","w":"https://de.wikipedia.org/wiki/Burg_Couzan"},"ch-Q1569125":{"n":"Schloss Baronville","c":"Schloss in Frankreich","r":"Baronville ist ein Schloss in Frankreich, rund 70 Kilometer westlich von Paris. Es liegt etwa auf halber Strecke zwischen den Gemeinden Béville-le-Comte und Oinville-sous-Auneau im Kanton Auneau und befindet sich heute im Besitz der Familie von Rougé d’Aligre. Das Gebäude steht seit dem 20. Dezember 1985 als Monument historique unter Denkmalschutz.","h":"Der Name des Schlosses leitet sich von der ehemaligen römischen Gemarkung Baronis Villa ab. Im Mittelalter wurde eine Burg errichtet, von der noch die Wassergräben und Kelleranlagen erhalten sind. Zwischen 1620 und 1623 wurde das erste Schloss errichtet. 1738 erwarb die Familie von Aligre die Grafschaft Baronville. Etienne François, der Marquis d’Aligre bis 1798, legte neue Gärten im französischen Stil an. Er pflegte einen freundschaftlichen Umgang zu den Bauern. Dies zeigte sich darin, dass einige von ihnen Baronville während der Revolutionsjahre erwarben und es seinem Sohn zurückgaben, als dieser Jahre später aus dem Exil zurückkehrte. Daher waren auch die Schäden nur unbedeutend. Der Sohn, Etienne V., zeigte sich dankbar, indem er die Bauern mit Höfen beschenkte und erste soziale Einrichtungen in der Grafschaft errichtete. 1867 wurde das alte Schloss abgerissen und das heutige Baronville innerhalb eines Jahres von Léon de Sanges errichtet. Auch die Gartenanlagen wurden mit einem englischen Stil versehen. Anschließend begann die wechselhafte Geschichte des Schlosses im Zuge der kommenden Kriege. Schon 1870 quartierten sich bayerische Soldaten während des Deutsch-Französischen Kriegs ein. Ab 1914 beherbergte das Schloss ein Militärkrankenhaus während des Ersten Weltkrieges. Im Zweiten Weltkrieg diente es General Friedrich Paulus kurzfristig als Hauptquartier. Im Anschluss daran nutzte ein deutscher Funktrupp das Schloss, um die Verbindung von Schlachtkreuzern vor Brest nach Berlin aufrechtzuerhalten. 1944 wurden die Kinder eines Waisenhauses aus Chartres aufgenommen, bevor im Juni des Jahres die deutsche Luftwaffe Baronville besetzte und eine Flugzeugstaffel stationierte, die später bei der Invasion der Alliierten in der Normandie zum Einsatz kam.","w":"https://de.wikipedia.org/wiki/Schloss_Baronville"},"ch-Q1847415":{"n":"Schloss von Berny","c":"Burg in Frankreich","r":"Das Schloss von Berny ist eine Schlossruine, die im heutigen Département Val-de-Marne in Fresnes an der Grenze zu Antony und dem Département Hauts-de-Seine an der Straße von Paris nach Orléans steht. Hier befindet sich auch die Kreuzung Croix de Berny, der das Schloss seinen Namen verdankt.","h":"Das Lehnsgut Berny wird zum ersten Mal 1422 erwähnt, als es an den Pariser Bürger Jehan Sac übergeht. Über die Entwicklung bis ins frühe 16. Jahrhundert ist jedoch nichts weiter bekannt. Im Jahr 1520 tauchen schließlich die Brûlart, eine Familie von Parlamentariern, als Besitzer auf. Pierre III Brûlart, Berater im Parlament von Paris, wird als Herr von Berny bezeichnet, während seine Frau Marie Cauchon als Dame von Sillery gilt. Das Anwesen wurde in der Familie vererbt, sodass es im späten 16. Jahrhundert in den Besitz von Nicolas Brûlart de Sillery, Kanzler von Frankreich wechselte. Dieser ließ kleinere Umbauten vollziehen, die zum Teil von dem berühmten Architekten Clément Métezeau geleitet wurden, der unter anderem den Richelieu-Damm entwarf, welcher 1628 den Hafen von La Rochelle während der von Ludwig XIII. begonnenen Belagerung blockierte. Im Jahr 1623 beauftragte Pierre Brûlart de Sillery, Sohn von Nicolas, Vikar von Puiseux, Markgraf von Sillery und Baron Grand-Pressignys den jungen François Mansart, damals ein noch unbekannter Architekt, mit dem grundlegenden Umbau des Schlosses. Die Arbeiten wurden um 1635 abgeschlossen, wobei die Kunst Mansarts sogar den Dichter Isaac de Benserade dazu veranlasste, dem Schloss eigene Zeilen zu widmen. Danach gingen das Schloss und die Ländereien an Pomponne II von Bellièvre, den ersten Präsidenten des Parlaments von Paris über, der das Anwesen berühmt machte, indem er dort zwischen 1648 und 1649 heimlich die Verschwörer der Fronde empfing. Im Jahr 1653 ging das Schloss in den Besitz von Hugues de Lionne über, einem geschickten Diplomaten, der 1659 zum Staatsminister ernannt wurde und als erster die Titel Baron von Fresne und Marquis von Berny trug.","w":"https://de.wikipedia.org/wiki/Schloss_von_Berny"},"ch-Q1876458":{"c":"Burg in Frankreich"},"ch-Q1870261":{"n":"Schloss Bazouges","c":"Schloss in Frankreich","r":"Schloss Bazouges liegt direkt am Ufer des Loir in der Stadt Bazouges-sur-le-Loir im Département Sarthe in der französischen Region Pays de la Loire.","w":"https://de.wikipedia.org/wiki/Schloss_Bazouges"},"ch-Q1884446":{"c":"Schloss in Frankreich"},"ch-Q1895555":{"c":"Burg in Frankreich"},"ch-Q2240956":{"n":"Schloss Fayrac","c":"Schloss in Frankreich","r":"Das Schloss Fayrac liegt an der Dordogne in der französischen Gemeinde Castelnaud-la-Chapelle im Département Dordogne. Von Castelnaud aus ist es nur einen Kilometer bis zu der Anlage aus dem 15. und 16. Jahrhundert, die im Hundertjährigen Krieg der Gegenpart zur Burg Beynac auf der anderen Flussseite war. Das Schloss ist in Privathand und kann nicht besichtigt werden. Zusammen mit Burg Beynac, Castelnaud, Château les Milandes und Marqueyssac ist es aber Teil eines touristischen Ensembles, das als Vallée des six châteaux bezeichnet wird.","h":"Anfänge Der Name Fayrac erscheint in kirchlichen Inventaren des 13. Jahrhunderts, oft unter der Schreibweise Afayrac oder Affeyrac. Es handelte sich damals um ein bescheidenes Festes Haus, von dem im heutigen Schloss lediglich der Gewölbekeller und der Rundturm zu finden sind. Im 14. Jahrhundert gehörte das Schloss den Seigneurs von Castelnaud, der Familie Caumont, und wurde als tours de Fayrac bezeichnet. 1342 gab Raoul de Caumont, der Bruder von Bertrand de Caumont, seiner Tochter das Schloss als Mitgift. Während des Hundertjährigen Krieges war es der Vorposten der englischen Burg Castelnaud und diente zur Beobachtung der gegenüberliegenden Burg Beynac. Am Ende des Krieges kam das Schloss 1459 in den Besitz von Léonard de Prouhet, der ein Knappe des Grafen von Périgord, Jean de L'Aigle († 1454), war. Der Graf, der Prouhet für seine Tapferkeit belohnen wollte, machte ihn zum don de terres à la Treille d'Affeyrac, und Prouhet wurde mit der Erbin des Schlosses verheiratet. Ein Torhaus mit Zugbrücke, das den Zugang zum Innenhof ermöglicht, wurde noch im 15. Jahrhundert errichtet. In den Chroniken des Kanonikers Jean Tarde findet sich für 1529 ein Raymond de Prouhet du Puy, Seigneur de Feyrac, Lieutenant-général der Sénéchaussée von Sarlat. Etwa zu dieser Zeit wurden das Torhaus und das Schloss verschönert und ein Logis im Stil der italienischen Renaissance hinzugefügt, vielleicht unter dem Einfluss des damaligen Bischofs von Sarlat, Niccolò Gaddi (1499–1552). Besitz der Blancher de Feyrac Die Erbin des Schlosses, Gabrielle du Puy, heiratete Jean de Blancher, den Sohn eines Notars Jehan Blancher aus Sarlat. Die Familie Blancher hatte Posten in Verwaltung und Militär inne und erwarb zu dieser Zeit einige Güter im Périgord.","w":"https://de.wikipedia.org/wiki/Schloss_Fayrac"},"ch-Q2241284":{"n":"Schloss Gratot","c":"Schlossruine in der Gemeinde Gratot im Département Manche der französischen Region Normandie","r":"Das Schloss Gratot ist eine Schlossruine in der Gemeinde Gratot im Département Manche der französischen Region Normandie. Sie befindet sich ungefähr vier Kilometer nordwestlich der Stadt Coutances und etwa sieben Kilometer von der französischen Kanalküste entfernt.","h":"Die Anlage wurde im 13. Jahrhundert als Wasserburg errichtet und in den Jahrhunderten ihrer Geschichte mehrmals umgebaut und erweitert. Sie zeigt daher eine Vielzahl architektonischer Stile und ist vollständig von Wassergräben umgeben. Erbauer war die Familie von Argouges, Barone von Gratot. Sie besaß umfangreichen Grundbesitz im Gebiet des heutigen Départements Manche, seit 1230 unter anderem die Stadt Granville. Die Gratot war von 1251 bis 1777 im Besitz der Familie. Im 19. Jahrhundert erlebte die Anlage eine Reihe von Eigentümern, die sie stark vernachlässigten. Einheimische Bauern nutzten die Gebäude als Scheune und Lagerhaus. Zu Beginn des 20. Jahrhunderts wurde das Schloss endgültig aufgegeben.","w":"https://de.wikipedia.org/wiki/Schloss_Gratot"},"ch-Q2242110":{"n":"Schloss Le Plessis-Macé","c":"Schloss in Frankreich","r":"Das Schloss Le Plessis-Macé befindet sich in der gleichnamigen französischen Stadt Le Plessis-Macé im Département Maine-et-Loire in der Nähe von Angers.","w":"https://de.wikipedia.org/wiki/Schloss_Le_Plessis-Mac%C3%A9"},"ch-Q1656973":{"n":"Schloss Les Aygues","c":"Schloss in Frankreich","r":"Das Schloss Les Aygues wurde während des 19. Jahrhunderts im Stil Louis-treize erbaut und diente seinen Bewohnern als repräsentative Sommerresidenz am Meer. Das Schloss steht im französischen Seebad Étretat im Département Seine-Maritime in der Normandie und kann im Rahmen einer Führung besichtigt werden. Seit August 1997 sind Teile des Gebäudes, das an der historischen Elfenbein- und Gewürzstraße liegt, als Monument historique in die französische Denkmalliste eingeschrieben.","h":"Amédée Boyer, der vermögende Inhaber eines Unternehmens, das Karmelitengeist herstellte, ließ 1866 durch den französischen Architekten Théodore Huchon die schlossartige Villa als Sommerfrische erbauen. Das symmetrische Gebäude entsprach dem damaligen Zeitgeschmack des Zweiten Kaiserreiches unter Kaiser Napoleon III. Jean-Charles Alphand und Gabriel Davioud, die Schöpfer des Pariser Parc des Buttes-Chaumont, entwarfen den dazugehörigen, ein Hektar großen Schlosspark mit vielen verschiedenen Baumarten, einem Gewächshaus, einem Eiskeller und einem Gartenpavillon. Nachfolgend übernahmen die Boyers Erbin Angélique de la Houssaye und ihr Mann, der Groß-Kammerherr des russischen Kaisers Nikolaus I., Fürst Joseph Lubomirski aus dem polnischen Hochadelsgeschlecht Lubomirski, das Schloss. Später wurde es als Ferienresidenz der spanischen Königinnen Maria Christina von Neapel-Sizilien und Isabella II. von Spanien genutzt. Zu den bekanntesten Gästen des Schlosses gehörten Jacques Offenbach und Alexandre Dumas.","w":"https://de.wikipedia.org/wiki/Schloss_Les_Aygues"},"ch-Q1814732":{"c":"Burg in Frankreich"},"ch-Q2240525":{"n":"Schloss Charleval","c":"Schloss in Frankreich","r":"Das Schloss Charleval in der französischen Gemeinde Charleval im Département Eure der Region Normandie wurde ab 1570 als Jagdschloss für König Karl IX. von dem Architekten Baptiste Androuet du Cerceau unter Mitwirkung von Jean Gallia, Hieronymus Corda, André Cuarda und Guillaume Marchant errichtet, jedoch wurde der Bau nach dem Tod des Königs 1574 unterbrochen.","w":"https://de.wikipedia.org/wiki/Schloss_Charleval"},"ch-Q2969799":{"c":"Burg in Frankreich"},"ch-Q2969820":{"n":"Schloss Martainville","c":"Schloss im Département Seine-Maritime, Frankreich","r":"Das Schloss Martainville ist ein französisches Landschloss am südlichen Rand der normannischen Gemeinde Martainville-Épreville etwa elf Kilometer östlich von Rouen im Département Seine-Maritime.","h":"Die Seigneurie Martainville gehörte im 13. Jahrhundert der Abtei Saint-Ouen in Rouen, die sie im Jahr 1291 an Guillaume de Martainville vergab. Im 15. Jahrhundert war Martainville im Besitz der Familie Floques, welche die seinerzeit 25 Hektar große Seigneurie 1481 dem reichen Kaufmann Jacques Le Pelletier verkaufte. Dessen Familie war von König Ludwig XI. in den Adelsstand erhoben worden, und ihr Oberhaupt wollte sich nun einen standesgemäßen Wohnsitz zulegen. Er ließ von 1485 bis 1495 auf den Grundmauern einer alten Burg einen Neubau ausführen, der zwar schon einen schlossähnlichen Charakter aufwies, aber immer noch sehr wehrhaft war. Bei seinem Tod im Jahr 1510 vererbte der Schlossherr den Besitz an seinen gleichnamigen Neffen, der das Logis modernisieren und wohnlicher gestalten ließ. Der direkt an das Gebäude grenzende Wassergraben wurde verfüllt und durch einen neuen, weiter entfernten Graben mit umgebender niedriger Mauer und vier runden Ecktürmen ersetzt. Die derweil funktionslose Zugbrücke ließ Jacques II. abreißen und den Haupteingang als Portal neu gestalten. Zudem erhielten die Räume größere Fenster, die mehr Licht ins Innere ließen. Die bis heute erhaltene Schlosskapelle stammt ebenfalls von diesen Veränderungen am Haupthaus. Zusätzlich ließ Jacques II. einen großen Wirtschaftshof mit zwei Gebäudeflügeln und einem großen Taubenturm anlegen. Dann schoben seine Vormünder weiteren Umbauten einen Riegel vor, weil sie der Meinung waren, er würde damit Geld verschwenden, und so starb er 1545, ohne alle beabsichtigten Umgestaltungen durchgeführt zu haben. Noch heute zeugen die Gewölbeansätze im Obergeschoss davon, was dort geplant war, aber nicht mehr umgesetzt wurde. Jacques’ II. Sohn und Erbe Richard erhielt am 16.","w":"https://de.wikipedia.org/wiki/Schloss_Martainville"},"ch-Q2969817":{"c":"Burg in Frankreich"},"ch-Q2969837":{"c":"Burg in Frankreich"},"ch-Q2969852":{"c":"Burg in Frankreich"},"ch-Q2969900":{"c":"Schloss in Frankreich"},"ch-Q2971738":{"n":"Château du Mirail","c":"Schloss in Frankreich","r":"Das Château du Mirail in Brouqueyran, einer französischen Gemeinde im Département Gironde in der Region Nouvelle-Aquitaine, wurde ursprünglich im 17. Jahrhundert errichtet und im 19. Jahrhundert umgebaut. Die Kapelle des Schlosses steht seit 1990 als Monument historique auf der Liste der Baudenkmäler in Frankreich.","h":"Die Herren von Mirail sind seit dem 13. Jahrhundert überliefert. Im Jahr 1348 erhielt Jean de la Tour, Grundherr von Brouqueyran, vom englischen König die Erlaubnis, eine befestigte Anlage zu errichten. Im 16. Jahrhundert ließ die Familie Larroque ein Schloss mit vier Türmen errichten, das im 17. Jahrhundert vergrößert wurde. Während der Revolution wurde das Schloss geplündert und 1793 wurden die Turmspitzen abgetragen. Im Schloss sind noch viele historische Ausstattungsstücke wie Wandverkleidungen, Kamine und Supraporten erhalten.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_du_Mirail"},"ch-Q3360868":{"n":"Palais Granvelle","c":"Palast in Besançon, Frankreich"},"ch-Q3360910":{"n":"Palais Rihour","c":"PAlais Rihour","r":"Das Palais Rihour an der Place Rihour in Lille, im Département Nord in der französischen Region Hauts-de-France, wurde im 15. Jahrhundert als Residenz der burgundischen Herzöge errichtet. Von der Mitte des 17. Jahrhunderts bis ins frühe 20. Jahrhundert diente das Gebäude als Rathaus. Durch mehrere Brände wurden große Teile des Palastes zerstört. Heute sind noch die Salle des Gardes, die Kapelle und die Ehrentreppe erhalten. In der Sakristei, die wie die Kapelle trotz der Brände erhalten geblieben ist, befinden sich Bleiglasfenster mit Fragmenten aus dem 15. und 16. Jahrhundert.","h":"Nachdem im Jahr 1451 das Palais de la Salle, der alte Palast der Grafen von Flandern, zum großen Teil durch einen Brand zerstört worden war, erwarb der burgundische Herzog Philipp der Gute 1453 ein inmitten der Arme der Deûle gelegenes Grundstück, in der Nähe der heutigen Grand’Place in Lille, um dort seine neue Residenz zu errichten. Im Jahr 1664 wurde das Gebäude verkauft und das Rathaus in den einstigen Herzogspalast verlegt, in dessen Nordflügel die Ratsherren tagten. Als dieser im Jahr 1700 durch einen Brand zerstört wurde, baute man die Kapelle zum Sitzungssaal um. 1756 richtete ein weiterer Brand großen Schaden vor allem am Westflügel an. Im Jahr 1847 wurde der Architekt Charles-César Benvignat mit dem Neubau des Rathauses beauftragt. Er ließ mit Ausnahme der Kapelle, des Treppenturms und der Ehrentreppe sämtliche alten Bauten abreißen. Ein Brand im Jahr 1916 zerstörte auch diesen Rathausneubau. Nach dem Ersten Weltkrieg wurde das heutige Rathaus an der Place Roger Salengro neu errichtet. Im Erdgeschoss des Palais Rihour ist heute die Touristeninformation (Office de Tourisme) untergebracht.","w":"https://de.wikipedia.org/wiki/Palais_Rihour"},"ch-Q2967977":{"c":"Burg in Frankreich"},"ch-Q2970080":{"c":"Schloss in Frankreich"},"ch-Q2970100":{"c":"Burg in Frankreich"},"ch-Q2970162":{"c":"Burg in Frankreich"},"ch-Q2970089":{"n":"Schloss Médavy","c":"Burg in Frankreich","r":"Das Schloss Médavy ist eine barocke Schlossanlage am nordöstlichen Rand der normannischen Gemeinde Médavy im Département Orne. Es liegt unmittelbar am linken Ufer des Flusses Orne, der den Schlossgraben speist.","h":"Am heutigen Standort existierte bereits im 11. Jahrhundert ein erstes festes Haus, das die Überfahrt über die Orne überwachte. Sein erster namentlich bekannter Besitzer war der Gouverneur von Alençon, Hugues de Médavy, der im Jahr 1113 urkundlich erwähnt wurde. 1137 gehörte das Haus Robert de Médavy. Die erste wehrhafte Anlage wurde vielleicht zwischen 1417 und 1449 im Hundertjährigen Krieg zerstört. Sicher ist, dass sie irgendwann vor dem 16. Jahrhundert durch eine größere Burg ersetzt wurde. Danach bestand die Anlage aus einem viereckigen, von einer Ringmauer und einem Wassergraben umgebenen Areal, dessen vier Ecken von wuchtigen Rundtürmen bewacht wurden. Im Schutze der Ringmauer standen innerhalb des Gevierts ein Wohnbau, ein Bergfried und eine Burgkapelle, die zugleich Begräbnisstätte der Burgherren war. Die Burg Médavy gelangte durch die Heirat der Erbtochter Marie Larçonneur, dame de Médavy, im Jahr 1424 mit dem Gouverneur von Argenton und Mundschenk des Herzogs von Alençon, Jean Rouxel, an dessen Familie. Diese nannte sich nachfolgend Rouxel de Médavy und blieb fast 300 Jahre lang Eigentümerin der Anlage, deren Landbesitz sie durch Zukäufe vergrößerte. Ab der zweiten Hälfte des 16. Jahrhunderts stieg die Familie durch militärische Taten ihrer männlichen Mitglieder am Pariser Hof zu Ruhm und Ehre auf und wusste durch vorteilhafte Heiraten Einfluss und Reichtum zu mehren. So heiratete Pierre de Médavy 1588 Françoise de Hautemer, die Tochter des späteren französischen Marschalls Guillaume de Hautemer, Graf von Grancey, nach dessen Tod der Grafentitel an die Familie Rouxel überging. Für den Bräutigam erhob König Heinrich III. die Seigneurie 1596 zur Baronie.","w":"https://de.wikipedia.org/wiki/Schloss_M%C3%A9davy"},"ch-Q2968555":{"c":"Schloss in Frankreich"},"ch-Q2968575":{"c":"Burg in Frankreich"},"ch-Q2968592":{"n":"Schloss Bonnelles","c":"Burg in Frankreich","r":"Das Schloss Bonnelles befindet sich in der Gemeinde Bonnelles in der Nähe von Saint-Arnoult-en-Yvelines im Département Yvelines in Frankreich.","h":"Diese alte Domäne liegt an der Grenze zwischen des Hurepoix und der Beauce. Ein erstes Schloss wurde hier gegen Ende des 15. oder Anfang des 16. Jahrhunderts vermutlich von der Familie La Villeneuve errichtet. Mitte des 16. Jahrhunderts wurde es durch einen neuen Flügel erweitert, und gegen Ende des 16. oder Anfang des 17. Jahrhunderts wurde ein neuer Flügel im rechten Winkel zum vorherigen gebaut. Im 16. Jahrhundert ging das Land Bonnelles durch die Heirat (1591) von Henriette de Lamoignon, der Tochter von Chrétien de Lamoignon, mit Charles de La Villeneuve († 1592 oder 1602) kurzzeitig an die Familie Lamoignon über. Als Witwe, die ihren einzigen Sohn verloren hatte, vermachte sie Bonnelles ihrem Neffen Claude de Bullion (1568–1640), dem Sohn ihrer älteren Schwester Charlotte, der Surintendant des Finances unter Ludwig XIII. war. Das erste Schloss, das 1724 durch einen Brand beschädigt worden war, wurde 1764 abgerissen und an seiner Stelle wurde ein neues Schloss errichtet. 1769 wurde das Schloss von Auguste-Léon de Bullion, Marquis de Bonnelles, Oberst der Dragoner, Lieutenant-général au Gouvernement de Guyenne, seinem Neffen François Emmanuel de Crussol (1728–1802), dem 9. Herzog von Uzès, vermacht, der es 1771 tatsächlich erbte. Damit ging das Anwesen in den Besitz des Hauses Crussol über. Dieses zweite Schloss mit rechteckigem Grundriss wurde 1782 verdoppelt, gleichzeitig wurden im Garten auch einige Fabriques de jardin errichtet. Das als Emigrantengut beschlagnahmte Schloss wurde Ende des 18. Jahrhunderts abgerissen und das Anwesen lag für einige Zeit verlassen. Nach seiner Rückkehr aus der Emigration gelang es dem 10. Herzog, Marie François Emmanuel de Crussol (1756–1843), die Rückgabe des Anwesens zu erwirken, das er dann erheblich vergrößerte.","w":"https://de.wikipedia.org/wiki/Schloss_Bonnelles"},"ch-Q2968675":{"c":"Schloss in Frankreich"},"ch-Q2968631":{"c":"Schloss in Frankreich"},"ch-Q2969565":{"n":"Château de La Motte","c":"Burg in Lyon, Frankreich"},"ch-Q2969600":{"n":"Schloss La Vigne","c":"Burg in Ally, Département Cantal, Auvergne-Rhône-Alpes, Frankreich","r":"Das Schloss La Vigne ist eine bedeutende mittelalterliche Burg- und Schlossanlage in der französischen Gemeinde Ally im Département Cantal der Region Auvergne-Rhône-Alpes. Das Anwesen und seine Umgebung sind seit 1944 als Landschaftsschutzgebiet erfasst. Die Gebäude und historischen Innenräume stehen seit dem 30. September 1991 als Monument historique unter Denkmalschutz.","h":"Die historischen Wurzeln der Befestigung an diesem Ort reichen bis in das Frühmittelalter zurück. Bereits im 8. Jahrhundert existierte etwa 300 Meter unterhalb des heutigen Standorts ein merowingerzeitliches Lager, das *Castrum Scoralium*, auf einem Felssporn über dem Auze-Tal. Im Jahr 767 eroberte Pippin der Jüngere in Begleitung seines Sohnes Charlemagne diese Festung, die bis dahin vom aquitanischen Herzog Waifre gehalten worden war. Im 11. Jahrhundert errichtete die Familie de Scorailles eine neue feudale Burg im nahegelegenen Dorf Escorailles, welche ihr für fast fünf Jahrhunderte als Stammsitz diente. Gegen Ende des Hundertjährigen Krieges war die alte Stammburg der Scorailles durch die anhaltenden militärischen Konflikte und mangelnde Instandhaltung unbewohnbar geworden. Um 1440 entschied Louis II. de Scorailles, Senator (*Sénéchal*) des Berry und Limousin sowie Kammerherr von König Karl VII., eine neue Residenz zu errichten. Das Schloss La Vigne entstand auf dem Gelände eines ehemaligen Wirtschaftshofs (nach anderen Quellen eines Jagdpavillons) der alten Burg. Zwischen 1470 und 1485 stellte sein Enkel, Marquès de Scorailles, den Bau fertig, woraufhin die Familie ihren Wohnsitz endgültig hierher verlegte. Im Jahr 1503 ging das Anwesen an François de Scorailles über. Durch seine Teilnahme an den Italienischen Kriegen an der Seite von König Franz I. brachte er neue architektonische Einflüsse der Renaissance in die Auvergne, die sich noch heute in den Malereien des Schlosses wiederfinden. Am 14. Mai 1650 war das Schloss Schauplatz der französischen Hochpolitik während der Aufstände der Fronde. Jean de Scorailles gewährte Claire-Clémence de Maillé, der Prinzessin von Condé, und ihrem jungen Sohn, dem Herzog von Enghien, Unterschlupf.","w":"https://de.wikipedia.org/wiki/Schloss_La_Vigne"},"ch-Q2969604":{"c":"Burg in Frankreich"},"ch-Q2971813":{"n":"Château du Roc (Saint-André-d’Allas)","c":"Burg in Frankreich","r":"Das Château du Roc, auch Schloss du Roc oder Schloss du Roch genannt, ist ein französisches Schloss in der Ortschaft Le Roch in der Gemeinde Saint-André-d’Allas im Département Dordogne in der Region Nouvelle-Aquitaine.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_du_Roc_(Saint-Andr%C3%A9-d%E2%80%99Allas)"},"ch-Q2968726":{"c":"Schloss in Frankreich"},"ch-Q2971583":{"c":"Burg in Frankreich"},"ch-Q2970903":{"c":"Burg in Frankreich"},"ch-Q2970908":{"c":"Burg in Frankreich"},"ch-Q2969660":{"c":"Schloss in Frankreich"},"ch-Q2969663":{"c":"Schloss in Frankreich"},"ch-Q2968000":{"c":"Schloss in Frankreich"},"ch-Q2968050":{"c":"Burg in Frankreich"},"ch-Q2968100":{"n":"Schloss Arcelot","c":"Schloss in Frankreich","r":"Das Schloss Arcelot steht in der französischen Gemeinde Arceau im Kanton Mirebeau sur Bèze des Départements Côte-d’Or, das zur Region Bourgogne-Franche-Comté gehört.","h":"Die Anfänge des Schlosses reichen ins Jahr 1217 zurück. Aus dieser Zeit stammt die Kapelle, die zum Schloss gehört. Die ersten Arbeiten am Schloss in der heutigen Form wurden unter Philibert I. von Verchère, zwischen 1711 und 1720 ausgeführt. Es handelte sich um ein Gebäude mit zwei Pavillons. Sein Enkel Philibert II., Marquis von Arcelot, seinerzeit Rat des Parlements von Burgund, ließ das heutige Schloss vom Architekten Thomas Dumorey zwischen 1761 und 1764 errichten. Es war das erste Schloss im neoklassischen Stil im Burgund. Das Schloss wurde bis 1870 in direkter Linie weitervererbt. In jenem Jahr verstarb Guillaume Verchère ohne Nachkommen. Deshalb ging das Erbe an den Sohn seiner Schwester, die 1801 Antoine-Bernard Carrelet de Loisy geheiratet hatte. Seit Ernest Carrelet de Loisy ist das Schloss im Besitz dieser Familie.","w":"https://de.wikipedia.org/wiki/Schloss_Arcelot"},"ch-Q2968102":{"n":"Schloss Arcis-sur-Aube","c":"Burg in Frankreich","r":"Das Schloss in Arcis-sur-Aube, einer französischen Gemeinde im Département Aube in der Region Grand Est, wurde in der ersten Hälfte des 18. Jahrhunderts errichtet. Das Schloss am Place des Héros ist seit 1983 als Monument historique klassifiziert. Das Schlossgebäude wird heute als Hôtel de Ville genutzt.","w":"https://de.wikipedia.org/wiki/Schloss_Arcis-sur-Aube"},"ch-Q2968103":{"n":"Château d’Arche","c":"Weingut in Frankreich","r":"Das Château d’Arche ist ein Weingut und zählt zu den höchstgelegenen in der französischen Weinbauregion Sauternes. Es gehört zur 1855 von Napoleon III. initiierten Deuxième-Cru-Classé-Bordeaux-Klassifizierung. 40 ha stehen unter Ertrag, davon 27 ha als Deuxième-Cru.","h":"Die ursprüngliche Nutzung der Gebäudestruktur war für eine Kartause bestimmt, die hier seit dem 16. Jahrhundert nachweisbar ist. Château d’Arche ist nach dem Grafen d’Arche benannt, der das Anwesen von 1733 bis 1789 besaß. Andere Quellen sprechen davon, dass der Präsident des Bordelaiser Parlaments, Graf d’Arche, dieses Anwesen 1727 gekauft hätte. In der Französischen Revolution wurde es erneut verkauft und in wesentlichen Teilen niedergebrochen. Im 19. und der ersten Hälfte des 20. Jahrhunderts wird die Besitzgeschichte äußerst kompliziert. Ausführliche beschreibt Clive Coates die Umstände in seinem Fachmagazin The vine, Nr. 93. Seit 1981 steht das Gut in Pacht vom INAO-Präsidenten Pierre Perromat. Bis 1996 verblieb der Besitz in den Händen dieser Familie, als es an eine irische Familie verkauft wurde. Bis 2003 führte Perromats Schwiegersohn, Jérôme Cosson, die Geschäfte. Ab 2005 war das Weingut vollständig in privater Hand. Die langgestreckten, eingeschossigen Gebäude bilden sowohl einen gartenartigen, als auch einen Wirtschaftshof und wurden zuletzt im Stil des Klassizismus modernisiert. Teile diese Gebäudestrukturen sind bis in die Mitte der 2020er Jahre zu neun Chambres d’hôtes genutzt worden. Seit 2025 wird an einem neuen Hotelkomplex gearbeitet, der diese alten Strukturen mit einbezieht. Auf der gegenüberliegenden Straßenseite ist um 2020 ein Verkostungs- und Präsentationsbereich über dem Weinkeller entstanden, der große Reisegruppen anziehen soll.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_d%E2%80%99Arche"},"ch-Q2970460":{"c":"Burg in Frankreich"},"ch-Q2970468":{"c":"Burg in Frankreich"},"ch-Q2970472":{"c":"Burg in Frankreich"},"ch-Q2970473":{"c":"Burg in Frankreich"},"ch-Q2970496":{"c":"Burg in Frankreich"},"ch-Q2970497":{"c":"Schloss in Frankreich"},"ch-Q2970508":{"c":"Schloss in Frankreich"},"ch-Q2970519":{"c":"Schloss in Frankreich"},"ch-Q2187991":{"n":"Château de la Reynarde","c":"Schloss in Marseille, Frankreich","r":"Das Château de la Reynarde ist ein denkmalgeschütztes Schloss im französischen Marseille.","h":"Das Gebäude ist eine ehemalige mittelalterliche Festung, die im 18. Jahrhundert in ein Schloss umgebaut wurde. Das Schloss gehörte zum damaligen Zeitpunkt der französischen Adelsfamilie de Félix. 1868 wurde es vom Kaufmann und Reeder Louis Régis gekauft. Régis ließ das Schloss nach dem Kauf und bis Ende des 19. Jahrhunderts renovieren. Das Schloss und der Park sind seit dem 17. Juli 1996 als Monument historique eingestuft. Château de la Reynarde beherbergt heutzutage ein Betreuungszentrum für etwa 70 sozial gefährdete Kinder, Jugendliche und junge Erwachsene.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_de_la_Reynarde"},"ch-Q2970533":{"c":"Burg in Frankreich"},"ch-Q2194736":{"c":"Burg in Frankreich"},"ch-Q2218826":{"c":"Burg in Frankreich"},"ch-Q2221609":{"c":"Burg in Frankreich"},"ch-Q2243074":{"n":"Schloss Ratilly","c":"Schloss im Département Yonne, Frankreich","r":"Das Schloss Ratilly liegt im Département Yonne in der Region Burgund, in der dicht bewaldeten Landschaft Puisaye und circa 25 Kilometer südwestlich von Auxerre. Es war ursprünglich eine Wasserburg.","h":"Der Name „Ratilly“ ist wahrscheinlich abgeleitet von ratel (franz. = die Egge, das Fallgatter einer Burg). Ratilly wurde mit dem Ritter Renaud de Ratilly zum ersten Mal in einer Urkunde von 1160 erwähnt. Schon im 11. Jahrhundert, als das Feudalsystem im Puisaye eingerichtet wurde, hatte man an diesem Ort eine Burg gebaut. Um 1270 ließ Mathieu de Ratilly diese Burg bis auf die Glacis abreißen und eine neue Wasserburg errichten, die bis auf die späteren baulichen Korrekturen, mit dem heutigen Bauwerk weitgehend übereinstimmte. Die Festung gehörte während des Hundertjährigen Krieges zwischen 1357 und 1380 dem Herrn Guy de Vallery, der hier eine Bande bretonischer Abenteurer versorgte, die die Region ausraubten. So setzten sie etwa das Kloster Moustier in Brand. 1485 war der Ritter Jean de Candiou Seigneur von Treigny in Ratilly. Nach seinem Tod im Jahr 1530 heiratete seine Tochter Anne Jean de la Menu, der bourbonischen Ursprungs war. 1567, zu Beginn der Religionskriege, ergriffen die Hugenotten von Ratilly Besitz und machten es zu ihrem Hauptstandort im Auxerrois. Von hier aus begingen sie zahlreiche „Plünderungen, Diebereien, Morde und Verwüstungen“. Mit der Thronbesteigung von Henri IV 1589 trat in Ratilly erneut Ruhe ein. Mary de Puy, Gutsherr von Igny bei Paleiseau (südlich Paris), restaurierte Ratilly, wie etwa die Fenster zum Innenhof, und den Kamin im Saal der Wache, der heute unter Denkmalschutz steht, und bezog die Burg 1587. Seine zweite Tochter Jeanne heiratete 1616 Louis de Menou, Gouverneur des Herzogtums Saint Fargeau. Dieser restaurierte die südliche Frontseite der Burg, wobei er die beiden Türme rückseitig miteinander verband sowie die heute nicht mehr existierende Kapelle Saint Anne errichtete.","w":"https://de.wikipedia.org/wiki/Schloss_Ratilly"},"ch-Q2751516":{"n":"Schloss Montjeu","c":"Schloss in Frankreich","r":"Das Schloss Montjeu ist eine Schlossanlage auf dem Gebiet der französischen Gemeinde Broye im Département Saône-et-Loire der Region Bourgogne-Franche-Comté. Das Schloss steht auf einem Berg oberhalb der Stadt Autun.","h":"Die Familien von Riveau und Ostun waren im Mittelalter die Herren von Montjeu. Im Jahr 1586 erwarb es Pierre Jeannin Autunois, Präsident des Parlements von Dijon und Berater von Heinrich IV. Er begann im Jahr 1606 mit dem Bau des Schlosses. Nach seinem Tod 1623 baute sein Schwiegersohn Pierre de Castille die großen Treppen des Parks und vollendete die Ausschmückung der Kapelle. Sein Enkel Nicolas Jeannin von Kastilien (gestorben 1691) baute den Südflügel des Schlosses und realisierte die französischen Gärten. 1734 nahm Voltaire in der Kapelle an der Hochzeit von Élisabeth Sophie de Lorraine mit Marschall de Richelieu teil. Im darauf folgenden Jahr beschädigte ein Brand das Hauptgebäude. 1749 wurde Montjeu von Anne Catherine de Bauldry de Villaines, der Witwe des Präsidenten d’Aligre erworben, welche die Zugbrücken vor und hinter dem Schloss durch gemauerte Brücken ersetzte. Das Anwesen ging an ihren Enkel, Le Peletier de Saint-Fargeau, der 1893 starb. Willy Manchot, Schlosseigentümer ab Ende der 1950er Jahre, ließ die Anlage nach einem schweren Brand im November 1963 reparieren. Das Feuer hatte das gesamte Innere des Hauptgebäudes, insbesondere die Galerie im ersten Geschoss, zerstört und den Nordflügel beschädigt. In den späten 1980er Jahren wurde das Schloss vom Milliardär James Goldsmith gekauft. Er begann mit der Innen- und Außenrestaurierung sowie der Rekonstruktion der französischen Gärten und Springbrunnen, die sich in einem erbärmlichen Zustand befanden.","w":"https://de.wikipedia.org/wiki/Schloss_Montjeu"},"ch-Q2636044":{"c":"Schloss in Frankreich"},"ch-Q2763009":{"c":"Schloss in Frankreich"},"ch-Q2763769":{"n":"Schloss Ray-sur-Saône","c":"Schloss im Département Haute-Saône, Frankreich","r":"Das Schloss Ray-sur-Saône ist eine Schlossanlage in der gleichnamigen französischen Gemeinde im Département Haute-Saône der Region Bourgogne-Franche-Comté rund 40 Kilometer nördlich von Besançon. Es geht auf eine mittelalterliche Burg der Herren von Ray zurück, die während des Schwedisch-Französischen Kriegs fast vollständig zerstört und Ende des 17. sowie im ersten Viertel des 18. Jahrhunderts von den damaligen Eigentümern, der Familie von Merode, wieder aufgebaut wurde. Durch Veränderungen im klassizistischen Stil während des 18. Jahrhunderts durch die Familie de Marmier erhielt es seine heutige äußere Gestalt.","h":"1098 fand mit Guy de Ray ein örtlicher Herrscher Erwähnung, dessen Sohn Sev(u)in in jenem Jahr als Zeuge in einer Urkunde erscheint. Die Familie de Ray hatte das Land als Lehen der Abtei Saint-Vincent in Chalon-sur-Saône erhalten, der es schon im 10. Jahrhundert gehörte, und dort eine Burg errichtet. Im Jahr 1172 wurde diese befestigte Anlage (lateinisch castrum) erstmals urkundlich genannt, als Stephan II., Graf von Auxonne, den Besitz von der Abtei erwarb. Der Burgplatz war gut gewählt: Die Anlage stand auf einem Felsen in der Nähe einer Furt über die Saône, auf dem sich früher ein gallo-römisches Oppidum befunden haben soll. Bei Grabungen gefundenen Objekte zeigen aber, dass dieser Felsen auch schon in der späten Bronzezeit besiedelt war. Von der ersten Wehranlage ist heute nichts mehr erhalten. Die ältesten Teile des heutigen Schlosses gehen auf einen Donjon zurück, den Otto de la Roche erbaut haben soll. Er war durch die Heirat mit seiner Cousine Isabelle de Ray, dem letzten Mitglied dieses Zweigs der Familie und damit Alleinerbin, Herr von Ray geworden, und sein Sohn gleichen Namens erhielt die Seigneurie 1236 vom Haus Burgund-Ivrea zu Eigen. Ottos Donjon war von einer Ringmauer mit 14 Türmen und Gräben geschützt und umfasste einen fünf Hektar großen Bereich, in dem sich bis zum Anfang des 14. Jahrhunderts ein Burgflecken bildete. Im Untergeschoss des Wohnturms befand sich ein etwa 50 Meter tiefer Brunnen, der heute noch existiert. Ende des 15. oder Anfang des 16. Jahrhunderts erweiterte die Familie de Ray den alten Donjon um einen Nord- und Südflügel. Die Familie de Ray blieb bis 1636 Eigentümerin der Anlage.","w":"https://de.wikipedia.org/wiki/Schloss_Ray-sur-Sa%C3%B4ne"},"ch-Q2794879":{"c":"Burg in Frankreich"},"ch-Q2795493":{"c":"Burg in Frankreich"},"ch-Q2796619":{"c":"Burg in Frankreich"},"ch-Q2969143":{"c":"Burg in Frankreich"},"ch-Q2969161":{"c":"Schloss in Frankreich"},"ch-Q2969166":{"c":"Burg in Frankreich"},"ch-Q2970346":{"c":"Schloss in Frankreich"},"ch-Q2970349":{"c":"Burg in Frankreich"},"ch-Q2968777":{"c":"Burg in Frankreich"},"ch-Q2970396":{"c":"Burg in Frankreich"},"ch-Q2968778":{"n":"Schloss Castagnac","c":"Burg in Frankreich","r":"Das Schloss in Castagnac, einer französischen Gemeinde im Département Haute-Garonne in der Region Okzitanien, wurde ursprünglich im 15. Jahrhundert errichtet und im 18./19. Jahrhundert verändert. Das Schloss steht seit 2003 als Monument historique auf der Liste der Baudenkmäler in Frankreich.","w":"https://de.wikipedia.org/wiki/Schloss_Castagnac"},"ch-Q2968793":{"c":"Schloss in Frankreich"},"ch-Q2971613":{"c":"Burg in Frankreich"},"ch-Q2971630":{"c":"Burg in Frankreich"},"ch-Q2971632":{"c":"Burg in Frankreich"},"ch-Q2971673":{"c":"Mittelalterliche Burg aus dem 13. Jahrhundert in Échiré, Frankreich."},"ch-Q2970631":{"c":"Burg in Frankreich"},"ch-Q2970666":{"c":"Schloss in Frankreich"},"ch-Q2968829":{"c":"Schloss in Frankreich"},"ch-Q2968823":{"c":"Burg in Frankreich"},"ch-Q2968895":{"c":"Schloss in Frankreich"},"ch-Q2968141":{"c":"Burg in Frankreich"},"ch-Q2968202":{"c":"Burg in Frankreich"},"ch-Q2968876":{"c":"Schloss in Frankreich"},"ch-Q3361185":{"c":"Palast in Frankreich"},"ch-Q2971048":{"c":"Schloss in Frankreich"},"ch-Q2968236":{"c":"Schloss in Frankreich"},"ch-Q2968497":{"n":"Château de Beauregard","c":"Burg in Seyssinet-Pariset, Frankreich"},"ch-Q2968230":{"n":"Schloss Estaing","c":"Burg in Estaing, Département Aveyron, Okzitanien, Frankreich","r":"Das Schloss Estaing ist eine Schloss- und Burganlage aus dem 11., 15., 16. und 17. Jahrhundert in der französischen Gemeinde Estaing im Département Aveyron der Region Okzitanien. Das Schloss thront auf einem Felsvorsprung an der Mündung der Coussane in den Lot und dominiert das Ortsbild. Das Hauptgebäude und die Terrassen stehen seit dem 6. Januar 1945 als Monument historique unter Denkmalschutz, die im 20. Jahrhundert hinzugefügte Kapelle wurde 2018 zusätzlich eingeschrieben.","h":"Die Baronie d'Estaing ist bereits für das Jahr 1028 urkundlich belegt. Das Schloss unterstand den Grafen von Rouergue und bildete den Stammsitz der weitverzweigten Familie d’Estaing, die zahlreiche einflussreiche Militärs und Kirchenfürsten in der Geschichte des Rouergue und Frankreichs hervorbrachte. Unter anderem wurden der Kardinal Pierre d'Estaing sowie François d'Estaing, der spätere Bischof von Rodez, auf der Festung geboren. Joachim d'Estaing, Herr von Enval und Murol, der 1657 nach dem Tod seines Vaters den Titel des Vizegrafen von Estaing übernahm, war vermutlich das letzte Familienmitglied, das die Anlage dauerhaft bewohnte. Er zog sich um 1660 nach seinen Diensten in der königlichen Armee dorthin zurück, betrieb genealogische Studien und verfasste 1673 sein Testament. Mit dem kinderlosen Tod von Charles François d'Estaing am 10. September 1729 im Alter von nur 36 Jahren erlosch die ältere Hauptlinie der Familie d'Estaing. Im Jahr 1732 wurden die Archive und Räume des Schlosses amtlich versiegelt. Das Eigentum an der Anlage und der Vizegrafschaft ging an seinen Cousin Charles-François d'Estaing (1683–1746), den Vizegrafen von Ravel, über. In seinen Anmerkungen zur Neuauflage der Histoire générale du Languedoc berichtete Alexandre Dumège, Inspektor für Altertümer in Toulouse, von einem Vorfall im Jahr 1750: Bei der offiziellen Entsiegelung der Schlossarchive nach dem Tod von Charles-François d'Estaing wurde im Beisein von dessen Sohn ein metallener Koffer entdeckt. Dieser enthielt fünf geschickt gefälschte Pergamente, welche die vermeintlich glorreiche und weitreichende Antike des Hauses Estaing belegen sollten: Das erste Pergament war ein angeblicher Ehevertrag von 1192 zwischen Raimund VI.","w":"https://de.wikipedia.org/wiki/Schloss_Estaing"},"ch-Q2968228":{"c":"Burg in Frankreich"},"ch-Q2969046":{"c":"Burg in Frankreich"},"ch-Q2968523":{"c":"Schloss in Frankreich"},"ch-Q2969060":{"n":"Schloss Courtalain","c":"Burg in Frankreich","r":"Das Schloss Courtalain ist ein französisches Schloss aus dem 15. Jahrhundert in Courtalain, an der Grenze zwischen Le Perche und Dunois.","h":"Das Schloss wurde 1483 von Guillaume d’Avaugour erbaut, dem Ehemann von Perette de Baif, deren Grab sich in der Kirche von Courtalain befindet. 1553 gelangte das Schloss durch die Heirat von Jacqueline d’Avaugour mit Pierre I. de Montmorency-Fosseux in den Besitz des Hauses Montmorency, bei dem es neun Generationen lang blieb. Während der Revolution überließ die Verwaltung das Schloss einem Hufschmied und einem Metzger, die sich dort niederließen, bis sie wieder vertrieben wurden, als die Besitzer während der Restauration zurückkehrten. Courtalain gelangte 1862 nach der Heirat von Felicie de Bauffremont-Courtenay (1820–1912), der Nichte von Anne Louis Raoul Victor de Montmorency (1790–1862), dem letzten Herzog von Montmorency aus der Familie Montmorency, mit Louis de Gontaut-Biron (1813–1897) in den Besitz des Hauses Gontaut-Biron. Heute wird das Schloss von ihren direkten Nachkommen bewohnt. Während des Zweiten Weltkriegs wurde das Schloss in ein wichtiges Depot für Kunstwerke des Louvre-Museums umgewandelt. Vom 31. August bis zum 6. September 1939 brachten zahlreiche Lastwagen die transportabelsten ägyptischen Antiquitäten des Louvre, aber auch Wandteppiche aus dem Museum Saint-Germain-en-Laye und die napoleonischen Sammlungen aus dem Schloss Malmaison. Anfang Juni 1940, als die Deutschen näher kamen und das Schloss nicht mehr sicher genug war, schlug der Marquis de Gontaut-Biron vor, die Werke in seinem anderen Besitz, der Burg Saint-Blancard, unterzubringen. Das Schloss und seine Nebengebäude sind seit 1928, 1981 bzw. 1997 als historische Denkmäler eingetragen.","w":"https://de.wikipedia.org/wiki/Schloss_Courtalain"},"ch-Q2969064":{"c":"Schloss in Frankreich"},"ch-Q2967943":{"c":"Burg in Frankreich"},"ch-Q2967855":{"n":"Château Canon (Saint-Émilion)","c":"Schloss in Frankreich","r":"Château Canon ist eines der bedeutenden und traditionsreichsten Weingüter der französischen Gemeinde Saint-Émilion in der Region von Bordeaux. In der Hierarchie der Rotweine von Saint-Émilion gehört es als Premier Grand Cru classé B , der zweithöchsten Stufe an. Der seit 1986 produzierte Zweitwein heißt seit 2012 Croix Canon .Der Name des Weinguts leitet sich vom ehemaligen Besitzer Jacques Kanon ab. Das Weingut ist Mitglied der 1973 gegründeten Union des Grands Crus de Bordeaux.","h":"Die ersten bekannten Besitzer des ehemaligen „Bourdieu Saint-Martin“ waren die Mitglieder der Familie Biès. Am 2. oder 11. April 1760 (variiert je nach Quelle) verkaufte Jean Biès der Ältere, ein ehemaliger Leibwächter des französischen Königs in der Schottische Garde des Ancien Régime, aufgrund einer undurchsichtigen Familienangelegenheit den Bourdieu Saint-Martin für 40.400 Livres an einen aus Blaye stammenden Fregattenleutnant und Korsaren namens Jacques Kanon (1726–1800). Mit dieser Summe kaufte Jean Biès der Ältere ab Juni 1760 das Gut Château Les Rochers in Preignac. Zum Zeitpunkt des Kaufs bestand das Anwesen aus einem 13 Hektar großen, von einer Mauer umgebenen Clos und war- für damalige Verhältnisse ungewöhnlich – bereits vollständig dem Weinanbau gewidmet. Jacques Kanon investierte große Geldsummen (historische Quellen sprechen von 20.000 Livres) in sein Anwesen und vergrößerte es, indem er sieben kleine Parzellen neben dem ummauerten Weinberg kaufte. Auf diesen Parzellen ließ er neue Weinkeller und das Gutsgebäude errichten, das 1767 fertiggestellt wurde. Am 4. Dezember 1770 verkaufte Jacques Kanon das Anwesen „Bourdieu Saint-Martin“ für 80.000 Livres an Raymond Fontémoing, Händler und Besitzer des Château Canon de Fronsac. Fontémoing benannte den Besitz in Clos Saint-Martin um. Jacque Kanon emigrierte nach Haiti und erwarb mit dem Verkaufserlös eine Zuckerrohrplantage bei Jérémie. Nach dem Tod von Raymond Fontémoing im Jahr 1800 erbte sein letztgeborener Sohn Jean-Raymond Clos Saint-Martin. Nach dessen Tod 7 Jahre später übernahm seine Schwester Jeanne de Tranchère, Witwe des ehemaligen Verwalters des Departements Gironde Arnaud-Valentin de Tranchère, die Leitung des Weinguts. 1815 heiratete sie in zweiter Ehe Ferdinand Auguste Joseph Hovyn (1780–1859).","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_Canon_(Saint-%C3%89milion)"},"ch-Q2970227":{"c":"Burg in Frankreich"},"ch-Q2970236":{"c":"Burg in Frankreich"},"ch-Q2968413":{"c":"Burg in Frankreich"},"ch-Q2969214":{"n":"Burg Hohenpfirt","c":"Burg im Département Haut-Rhin, Frankreich","r":"Die Burg Hohenpfirt bzw. Burg Ferrette ist die Ruine einer Höhenburg in Ferrette in Frankreich im elsässischen Jura. Die Burg wird erstmals im Jahr 1100 erwähnt und zählt somit zu den ältesten Burgen des Elsass. Die Herren der Burg waren die Grafen von Pfirt, bis das Geschlecht in siebter Generation im Jahr 1324 in männlicher Linie ausstarb und durch Johanna von Pfirt an den Habsburger Albrecht II. ging. Fortan war die Hohenpfirt vorderösterreichische Vogtsresidenz.","w":"https://de.wikipedia.org/wiki/Burg_Hohenpfirt"},"ch-Q2969357":{"c":"Schloss in Frankreich"},"ch-Q2969362":{"n":"Schloss Grignon","c":"Schloss im Département Yvelines, Frankreich","r":"Das im 17. Jahrhundert erbaute Schloss Grignon befindet sich in der französischen Gemeinde Thiverval-Grignon im Département Yvelines. Es ist derzeit im Besitz von AgroParisTech.","h":"Pomponne de Bellièvre (1529–1607), Président à mortier des Parlement de Paris und anschließend bis zu seinem Tod Kanzler von Frankreich, kaufte das Anwesen 1582 von Diane de Poitiers, ebenso wie das Anwesen Buc. Zu dieser Zeit stand auf dem Lehnsgut Buc seit dem 12. Jahrhundert ein Herrenhaus. Im 17. Jahrhundert (1636) und während der französischen Renaissance (von der Krönung Ludwigs XIII. 1610 bis 1684) ließ sein Sohn Nicolas de Bellièvre (1583–1650), Herr von Neauphle-le-Château, das heutige Schloss Grignon errichten und schaffte es 1651, dass Grignon zum Marquisat erhoben wurde. 1674 wurde das Gut Grignon durch einen Landtausch mit der Kirche von Thiverval vergrößert. Ein Teil der Häuser von Thiverval wurde geopfert und das Dorf weiter nach Westen verlegt. Am 12. Mai 1682 verkaufte Pierre de Bellièvre das Marquisat Grignon und die Herrschaft Saint-Germain-de-la-Grange an André Potier, Chevalier, Herr von Novion, Conseiller au Parlement. Am 1. September 1693 starb hier Nicolas IV. Potier de Novion Während der Französischen Revolution ging das Anwesen nach der letzten Marquise von Grignon, Madame de Brassac, in den Besitz von Monsieur Auguie über, dessen Tochter 1802 den Marschall Michel Ney heiratete. Die Hochzeit wurde in Thiverval im Haus des Bürgermeisters (später Schloss Thiverval genannt) gefeiert.","w":"https://de.wikipedia.org/wiki/Schloss_Grignon"},"ch-Q2969386":{"c":"Burg in Frankreich"},"ch-Q2969100":{"c":"Burg in Frankreich"},"ch-Q2969937":{"c":"Burg in Frankreich"},"ch-Q2969276":{"c":"Schloss in Frankreich"},"ch-Q2969305":{"c":"Burg in Frankreich"},"ch-Q2969321":{"c":"Burg in Frankreich"},"ch-Q2969993":{"n":"Château de Montferrand","c":"Burg in Frankreich","r":"Das Château de Montferrand ist eine mittelalterliche Festungsruine aus dem 12. Jahrhundert auf dem Gebiet der Gemeinde Saint-Mathieu-de-Tréviers im Département Hérault in der Region Okzitanien in Frankreich. Eigentümer waren u. a. die Grafen von Melgueil. Die Burg diente nie als Wohnburg, sondern war immer Bestandteil des Verteidigungssystems zur Sicherung der Herrschaft ihrer jeweiligen Besitzer.","h":"Die Burg wurde erstmals Anfang des 12. Jahrhunderts urkundlich genannt. Schon 1132 wurde erwähnt, dass die Burg zu den Grafen von Melgueil gehört. Der Graf von Toulouse, Alphonse Jourdain, beanspruchte seine Rechte an der Burg Montferrand und einem Teil der Grafschaft Melgueil, die dem Osten des Departements Hérault entsprach. Die Grafschaft Melgueil ist in zwei Bezirke unterteilt: Melgueil (jetzt Mauguio, deren Feudalburg völlig verschwunden ist) und die von Montferrand. 1215 wurde die Burg vom Grafen von Toulouse, Raymond VI. Burg Mornas im Zusammenhang mit dem Albigenserkreuzzugs beschlagnahmt, und vom Papst an den Bischof von Maguelone als Lehen vergeben, der damit Graf von Melgueil und Montferrand wurde. Im Jahr 1536 wurde der Sitz der Diözese Maguelone nach Montpellier verlegt und die Burg wurde in Kriegshandlungen während der Religionskriege verwickelt. 1574 eroberten die Protestanten die Burg. 1584 übernahm Antoine de Cambous die Burg, die damit wieder katholisch wurde. 1611 wurden unter Bischof Pierre de Fenouillet die Befestigungen ausgebaut, um dem Beschuss durch Artillerie besser Stand zu halten. Die protestantischen Truppen des Herzogs von Rohan belagerten die Burg ohne Erfolg. Während der Hugenottenaufstände 1622 wurde die Burg vergeblich von den katholischen Truppen des Herzogs Heinrich de Montmorency belagert. Im folgenden Jahr, nachdem der Herzog die Stadt Montpellier für die katholische Partei erobert hatte, wurde Jacques Valat von Bischof Pierre de Fenouillet zum Herrn der Burg ernannt. Nach seinem Tod 1659 verfiel die Burg, Nach dem Ende der Religionskriege ließ Ludwig XIV. durch Colbert die Festung schleifen. Die Steine wurden demjenigen als Lohn angeboten, der sich bereit erklärte, mit dem Abriss fortzufahren.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_de_Montferrand_(H%C3%A9rault)"},"ch-Q2970021":{"c":"Burg in Frankreich"},"ch-Q2970026":{"c":"Burg in Frankreich"},"ch-Q3075968":{"c":"Siedlung in Frankreich"},"ch-Q3078423":{"c":"Burg in Frankreich"},"ch-Q3146182":{"c":"Burg in Frankreich"},"ch-Q2969530":{"n":"Château de La Caze","c":"Schloss in Frankreich"},"ch-Q2689530":{"c":"Burg in Frankreich"},"ch-Q2701702":{"c":"Schloss in Frankreich"},"ch-Q2968925":{"c":"Schloss in Frankreich"},"ch-Q2968948":{"c":"Schloss in Frankreich"},"ch-Q2968949":{"c":"Burg in Frankreich"},"ch-Q2968909":{"c":"Burg in Frankreich"},"ch-Q2968966":{"c":"Burg in Frankreich"},"ch-Q2969673":{"c":"Burg in Frankreich"},"ch-Q2969704":{"c":"Burg in Frankreich"},"ch-Q3034430":{"c":"Schloss in Frankreich"},"ch-Q2971921":{"n":"Châteaux d'Oberhof","c":"Burg in Frankreich"},"ch-Q3424607":{"c":"Burg in Frankreich"},"ch-Q3485404":{"n":"Schloss Lorentzen","c":"Schloss in Frankreich"},"ch-Q2415426":{"c":"Burg in Frankreich"},"ch-Q2421853":{"c":"Burg in Frankreich"},"ch-Q2416166":{"c":"Burg in Frankreich"},"ch-Q2427552":{"c":"Burg in Frankreich"},"ch-Q2434153":{"c":"Burg in Frankreich"},"ch-Q2971221":{"c":"Burg in Frankreich"},"ch-Q2441338":{"c":"Burg in Frankreich"},"ch-Q2971245":{"c":"Burg in Frankreich"},"ch-Q2971239":{"n":"Schloss La Fresnaye","c":"Schloss in Falaise, Département Calvados, Normandie, Frankreich","r":"Das Schloss La Fresnaye ist ein ursprüngliches Renaissance-Schloss in der französischen Gemeinde Falaise in der Normandie.","h":"Das Gebäude wurde im 16. Jahrhundert errichtet. Im Juli 1640 wurde das Land „La Fresnaye“ mit einem „Herrenhaus und anderen Gebäuden“ an Nicolas Vauquelin, den Herrn von Nécy, verkauft. Nach einem weiteren Kauf an die Familie André aus dem Jahr 1678 werden für die Anlage La Fresnaye drei Gebäude genannt. 1750 wurde das Gebäude von der Familie André umgebaut. Die heutige Fassade stammt aus dem Jahre 1779. Im 20. Jahrhundert wurde das Gebäude im Osten erweitert. Umgeben war das Schloss von einem Park im englischen Stil von insgesamt vierzehn Hektar. Dieser Park ist heute nicht mehr vorhanden. 1985/1986 wurde das Gebäude von der Stadt Falaise übernommen. Die Empfangsräume, Salons, Speisesäle und Schlafzimmer haben einen Teil ihrer ursprünglichen Dekoration bewahrt und werden heute für Ausstellungen genutzt.","w":"https://de.wikipedia.org/wiki/Schloss_La_Fresnaye"},"ch-Q2971255":{"c":"Burg in Frankreich"},"ch-Q2971278":{"c":"Burg in Frankreich"},"ch-Q2971302":{"c":"Burg in Frankreich"},"ch-Q2968256":{"c":"Burg in Frankreich"},"ch-Q2968321":{"c":"Burg in Frankreich"},"ch-Q2968323":{"n":"Château d'Orschwihr","c":"Burg in Frankreich"},"ch-Q2968327":{"c":"Burg in Frankreich"},"ch-Q2968341":{"c":"Burg in Frankreich"},"ch-Q2968388":{"c":"Burg in Frankreich"},"ch-Q2176659":{"c":"Burg in Frankreich"},"ch-Q2184056":{"n":"Château Régis","c":"Schloss in Marseille, Frankreich","r":"Das Château Régis ist ein denkmalgeschütztes Schloss im französischen Marseille.","h":"Das Gebäude aus dem 19. Jahrhundert wurde von den Marseiller Architekten Sixte Rey und Vaud für den Kaufmann und Reeder Louis Régis projektiert, der gleichzeitig der Namensgeber von Château Régis ist. Es wurde zwischen 1860 und 1865 errichtet und ist eine Nachahmung des Schlosses Chenonceau. Für die äußerliche Gestaltung zeichnet der Bildhauer Émile Aldebert verantwortlich. Das Schloss, der Bergfried und der Park sind seit dem 3. Oktober 1996 als Monument historique eingestuft. Auf dem Gelände fanden ab 26. und 27. Dezember 2008 für einige Jahre die administrativen und technischen Abnahmen des Africa Eco Race statt. Château Régis beherbergt heutzutage eine private katholische Schule, das College Notre-Dame de la Jeunesse.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_R%C3%A9gis"},"ch-Q2971435":{"c":"Burg in Frankreich"},"ch-Q2971440":{"c":"Burg in Frankreich"},"ch-Q2971475":{"c":"Schloss in Frankreich"},"ch-Q2971528":{"c":"Schloss in Frankreich"},"ch-Q2248951":{"c":"Burg in Frankreich"},"ch-Q2283624":{"c":"Schloss in Frankreich"},"ch-Q2276937":{"c":"Burg in Frankreich"},"ch-Q2328537":{"c":"Burg in Frankreich"},"ch-Q2969756":{"c":"Burg in Frankreich"},"ch-Q2333115":{"c":"Schloss in Frankreich"},"ch-Q2969776":{"c":"Schloss in Frankreich"},"ch-Q2383887":{"c":"Schloss in Frankreich"},"ch-Q2384333":{"c":"Burg in Frankreich"},"ch-Q2400209":{"c":"Burg in Frankreich"},"ch-Q2398623":{"c":"Burg in Frankreich"},"ch-Q2971083":{"c":"Burg in Frankreich"},"ch-Q2971090":{"c":"Burg in Frankreich"},"ch-Q2971124":{"n":"Burg La Barben","c":"französische befestigte Burg, Stammsitz der Adelsfamilie Forbin la Barben"},"ch-Q2971101":{"n":"Burg L’Hermine","c":"Burg in Vannes, Frankreich","r":"Die Burg L’Hermine war eine kleine Burg, die in die Stadtmauer von Vannes integriert war. Die Burg war zwischen dem Ende des 14. und dem 15. Jahrhundert die Hauptresidenz der Herzöge der Bretagne. Als Ruine wurde sie abgerissen und im Lauf des 18. Jahrhunderts durch ein Hôtel particulier, das Hôtel Lagorce, ersetzt, das nach seinem Besitzer benannt wurde; im Volksmund wird auch dies als Château de l’Hermine bezeichnet, da die Erinnerung an die ehemalige Festung der Herzöge im Gedächtnis der Bewohner von Vannes fest verankert ist.","h":"Die Burg L’Hermine war ein Verteidigungs- und Wohngebäude. Es wurde von Herzog Johann V. errichtet, der eine Residenz in einer Stadt haben wollte, die ihm während des Bretonischen Erbfolgekriegs (1341–1364) loyal gewesen war. Er ließ sein Schloss in die neuen Stadtmauern integrieren, die er im Süden der Stadt errichten ließ, wodurch sich die Fläche der Stadt verdoppelte (von 5 auf 12 Hektar), in einem Gebiet, das größtenteils den Gezeiten unterworfen war. Er benannte die Burg nach dem Hauptmotiv seines Wappens und dem Ritterorden, den er 1381 gegründet hatte. Die Burg wurde zwischen 1380 und 1385 erbaut; weitere Bauarbeiten erfolgten bis zur Mitte des 15. Jahrhunderts. Die Dienststellen des Hôtel des Herzogs fanden im Unterhof Platz: die Chambre des comptes (untergebracht im Hôtel de Cleiss, das von Monsieur de Largouët gekauft wurde), die später zum Rathaus wurde, die Münzwerkstatt, das Ofenhaus, das Jeu de paume sowie die herzoglichen Stallungen, die in den 1440er Jahren gebaut wurden. Das Ausmaß dieser Stallungen wurde durch Ausgrabungen im Jahr 2000 enthüllt. Der Bau der Moulin des Lices und der Chapelle des Lices zwischen 1420 und 1425 rundeten das Ganze ab. Die Burg war Schauplatz eines bedeutenden Ereignisses während der Herrschaft von Herzog Johann V.: der Verhaftung von Olivier V. de Clisson (1336–1407), einem mächtigen bretonischen Adligen, Nachfahre der Barone von Clisson und Held des Bretonischen Erbfolgekriegs. Als Gefährte des Herzogs wechselte er 1369 die Seiten und schloss sich der gegnerischen Partei der Herzogin Jeanne de Penthièvre an.","w":"https://de.wikipedia.org/wiki/Burg_L%E2%80%99Hermine"},"ch-Q2971140":{"c":"Burg in Frankreich"},"ch-Q2971148":{"c":"Schloss in Frankreich"},"ch-Q2971151":{"c":"Burg in Frankreich"},"ch-Q2971174":{"c":"Burg in Frankreich"},"ch-Q2970772":{"c":"Burg in Frankreich"},"ch-Q2970780":{"c":"Burg in Frankreich"},"ch-Q1996196":{"c":"Burg in Frankreich"},"ch-Q2008408":{"c":"Burg in Frankreich"},"ch-Q2062506":{"c":"Burg in Frankreich"},"ch-Q2097589":{"c":"Schloss in Frankreich"},"ch-Q2090800":{"n":"Schloss Yville","c":"Schloss in der Normandie","r":"Das Schloss Yville ist ein barockes Schloss in der nordöstlichen Normandie ca. 16 Kilometer südwestlich von Rouen. Sein Bau wurde 1708 von François Le Menu de La Noë begonnen, der dafür einen älteren Vorgängerbau abreißen ließ. Der Bauherr hatte sich aber finanziell übernommen, und so musste er den noch unfertigen Neubau versteigern lassen. 1720 erwarb ihn der Chef der Banque Royale, John Law, aber auch er vollendete den Schlossbau nicht. Erst nach einer mehrjährigen Bauunterbrechung wurde er 1735 von Prosper Goujon, Marquis von Gasville, fertiggestellt.","h":"Das Land um Yville wurde im Jahr 1066 erstmals genannt. Zu jener Zeit gehörte es Hugues de Wiville. Für das Jahr 1238 ist Guillaume de La Houssaye als Besitzer überliefert. Danach kam Yville an die Familie de Mortemer (Mortimer). Guillaume de Mortemers Erbtochter Jeanne brachte den Besitz durch Heirat im 13. Jahrhundert an die Familie Crespin de Bec-Crespin. Guillaume de Crespin heiratete Angès de Trie (auch Trye geschrieben). Über diese Verbindung gelangte die damalige Seigneurie an diese Familie, der sie im Jahr 1407 gehörte. In jenem Jahr zählte neben dem Landbesitz ein Herrenhaus mit Taubenturm, Scheunen, Ställe und Gärten dazu. 1418, während des Hundertjährigen Kriegs, von den Engländern konfisziert und an William Arlyngton verlehnt, wurde Yville gegen 1450 seinem vormaligen Herrn, Jacques de Trie, auf königlichen Geheiß wieder zurückgegeben. Seine Tochter Jeanne heiratete Martin Pillavoine und brachte die Seigneurie an seine Familie, die 1497 als Eigentümerin erschien. Sie veräußerte Yville an Charlotte Lhuillier, deren Tochter Madeleine (verheiratete dʼEsquetot) den Besitz 1540 erbte. Durch die Heirat von Madeleines Tochter Charlotte mit Charles I. de Cossé, comte de Brissac, dem Marschall von Frankreich, wechselte das Anwesen erneut den Eigentümer. Der Sohn des Paars, Charles II. de Cossé, duc de Brissac, hinterließ es bei seinem Tod 1601 seinem Neffen Timoléon d’Espinay, dem Sohn seiner Schwester Jeanne. Über François III. d’Espinay gelangte Yville an dessen Tochter Marie-Anne, die 1696 als Eigentümerin verzeichnet war und es am 6. März 1708 für 60.000 Livres an François Le Menu de La Noë, einen Rat und Sekretär des französischen Königs, verkaufte. Der neue Seigneur ließ den vorhandenen Herrensitz niederlegen und begann mit dem Bau eines neuen Schlosses.","w":"https://de.wikipedia.org/wiki/Schloss_Yville"},"ch-Q2457103":{"c":"Schloss in Frankreich"},"ch-Q2480350":{"c":"Burg in Frankreich"},"ch-Q2482855":{"n":"Schloss der Herzöge von Bourbon in Montluçon","c":"Burg in Frankreich"},"ch-Q2483849":{"n":"Schloss Assier","c":"Schloss in Frankreich","r":"Das Schloss Assier ist eine französische Schlossruine im Département Lot im Norden der Region Okzitanien. Sie liegt im Ort Assier in der Kulturlandschaft des Quercy.","h":"Assier war in der ersten Hälfte des 15. Jahrhunderts im Besitz der Familie de Bosc (auch Bosq). Durch Heirat der Erbtochter Catherine mit dem aus niederem Adel stammenden Jean de Genouillac kam Assier 1469 an dessen Familie. Catherines Sohn Jacques machte am französischen Königshof eine steile Karriere und avanciert zu einem der höchsten Würdenträger Frankreichs. Er war ein Favorit Karls VIII. und bekleidete unter ihm den Posten des Großstallmeisters des Dauphins (französisch grand écuyer du Dauphin). Von seinem Onkel väterlicherseits erbte er 1512 während der Regierung Ludwigs XII. das Amt des Königlichen Großmeisters der Artillerie französisch maître d’artillérie du roi, das er auch unter Franz I. innehatte. Dieser ernannte ihn 1517 außerdem zum Seneschall des Quercy, ehe er ihn 1526 mit dem Amt des Großstallmeisters von Frankreich betraute und ihn in den Michaelsorden aufnahm. Weitere Posten, die Jacques Ricard de Genouillac im Laufe seines Lebens bekleiden sollte, waren Lieutenant général in der Guyenne und ab 1546 Gouverneur des Languedoc. Durch seine zahlreichen Ämter am Hof hatte Galiot de Genouillac schon früh ein ordentliches Vermögen angesammelt. Deshalb dachte er ab etwa 1523, vielleicht aber auch schon seit seiner Ernennung zum Seneschall des Quercy 1517, daran, die von seiner Mutter geerbte, alte Burganlage – Tour du Sal genannt – durch einen Neubau zu ersetzen, der seinem gehobenen Stand angemessener war. Nach dem teilweisen Abriss seines Geburtshauses ließ Jacques de Genouillac am gleichen Ort nach Plänen des Toulouser Architekten Nicolas Bachelier bis 1535 ein Schloss im Stil der Renaissance errichten, das von den Neubauten Franz I. im Bois de Boulogne (Schloss Madrid) und in Fontainebleau inspiriert war.","w":"https://de.wikipedia.org/wiki/Schloss_Assier"},"ch-Q2520602":{"n":"Schloss Flers","c":"Schloss in Flers, Frankreich","r":"Das Schloss Flers ist ein Schloss in der französischen Gemeinde Flers im Département Orne. In mehreren Generationen bewohnten die Grafen von Flers das Gebäude, dessen älteste Teile aus dem 16. Jahrhundert stammen. Nach der Französischen Revolution gelangte es zunächst in Privatbesitz, bevor es 1901 die Stadt Flers erwarb, die im Schloss ein Museum für Kunst und Regionalgeschichte untergebracht hat.","h":"Das Schloss liegt am Ortsrand von Flers in einem sieben Hektar großen Park, der teilweise als Vogelschutzgebiet ausgewiesen ist. Das Gebäude ist an drei Seiten von Wasser umgeben. In Norden und Osten grenzt ein Schlossgraben an das Gebäude, westlich liegt der Schlossteich. An der Stelle des heutigen Schlosses stand zuvor eine Burg, die im 12. Jahrhundert von der Familie Aunou errichtet wurde. Im 13. und 14. Jahrhundert lebten hier die Grafen von Harcourt. Nicolas de Grosparmy, Baron de Flers, ließ an der Stelle der alten Burg von 1527 bis 1541 den heutigen Ostflügel des Schlosses errichten. Markant sind die beiden an der Schlossgrabenseite gelegenen runden Ecktürme, die mit Glockenhauben versehen sind. Durch Erbschaft gelangte das Schloss in den Besitz der Familien de Pellevé und de La Motte-Ango. Diese ließen an den bestehenden Schlossteil nach Westen im rechten Winkel den Nordflügel anfügen und bauten das Schloss im 17. und 18. Jahrhundert mehrfach um. Unter Ange Hyacinthe de La Motte Ango erhielt der Nordflügel 1764 seine Fassade im klassizistischen Stil. François Paul de La Motte Ango unterstützte während der Französischen Revolution die Chouans aus der Normandie, eine Gruppe königstreuer Katholiken. Deren Anführer, Louis de Frotté, nutzte das Schloss Flers zeitweilig als sein Hauptquartier. 1800 wurde das Gebäude von republikanischen Truppen niedergebrannt. 1806 erwarb es der deutsche Graf Sigismund Ehrenreich Johann von Redern. 1820 erwarb Antoine Schnetz, der Vater des Malers Jean-Victor Schnetz, das Schloss und bewohnte mit seiner Familie fortan das Anwesen. Seit 1901 ist das Schloss im Besitz der Stadt Flers, die im Gebäude das bereits 1874 gegründete städtische Museum untergebracht hat. Das Schloss ist seit 1907 als Monument historique denkmalgeschützt.","w":"https://de.wikipedia.org/wiki/Schloss_Flers_(Flers)"},"ch-Q2608510":{"c":"Burg in Frankreich"},"ch-Q2612600":{"n":"Schloss der Grafen von Bar","c":"Schloss in Bar-le-Duc, Frankreich","r":"Das Schloss der Herzöge von Bar in Bar-le-Duc, einer französischen Stadt im Département Meuse in Lothringen, wurde ursprünglich gegen Ende des 10. Jahrhunderts errichtet. Das Schloss an der Rue François-de-Guise Nr. 6 wurde 1981 als Monument historique in die Liste der Baudenkmäler in Frankreich aufgenommen.","w":"https://de.wikipedia.org/wiki/Schloss_der_Herz%C3%B6ge_von_Bar"},"ch-Q2677480":{"n":"Burg Le Vivier","c":"Burg in Frankreich","r":"Die Ruine der Burg Le Vivier befinden sich in Fontenay-Trésigny im Département Seine-et-Marne. Die Ruine sowie der zugehörige Grund sind seit dem 31. Oktober 1996 als Monument historique geschützt.","h":"Das Land, auf dem die Burg gebaut wurde, gehörte zur Seigneurie Tournan-en-Brie und war im 13. Jahrhundert im Besitz der Familie Garlande. Jean II. de Garlande, Seigneur von Tournan, verkaufte den Besitz im Mai 1293 an Pierre de Chambly, den Testamentsvollstrecker des Königs Philipp III. und Kämmerer des Königs Philipp IV. Pierre de Chambly wiederum trat die Herrschaft Tournan im Oktober des gleichen Jahres an Charles de Valois ab, der den Besitz durch Zukäufe und Geschenke seines Bruders Philipp IV. erweitern konnte. Auf Charles de Valois geht die Burg zurück, obwohl bereits im Jahr 1260 hier ein Herrenhaus (französisch Hôtel seigneurial) erwähnt wird. Der Hofmaler Évrard d’Orléans gestaltete im Jahr 1308 Säle und Galerien von Le Vivier. Philipp IV. hielt sich mehrfach hier auf, sein Sohn Philipp V. in den Jahren 1319 und 1320, er erließ hier die Ordonnanzen zur Cour des comptes und zum Parlement. Papst Johannes XXII. genehmigte 1316 durch eine Päpstliche Bulle den Bau einer Thomas Becket geweihten Kapelle. König Philipp VI., der älteste Sohn von Charles de Valois, fügte eine Ludwig dem Heiligen geweihte Kapelle hinzu. 1352 wurde in Le Vivier die Hochzeit von Jeanne de France, der Tochter des Königs Johann II., mit Karl II. von Navarra gefeiert; die Kapelle wurde zu diesem Anlass zu einer Stiftskirche erhoben. 1368 gab König Karl V. der Stiftskirche eine Kreuzreliquie zur Aufbewahrung, wodurch die Stiftskirche zur Sainte-Chapelle wurde. Vermutlich wurde in dieser Zeit auch der Torturm der Burg gebaut, der älter als derjenige des Schlosses Vincennes zu sein scheint. König Karl VI. kam in den Jahren 1380 und 1381 nach Le Vivier und wurde dann nach dem Ausbruch seiner Krankheit 1392 häufiger hergebracht.","w":"https://de.wikipedia.org/wiki/Burg_Le_Vivier"},"ch-Q2971554":{"c":"Schloss in Frankreich"},"ch-Q2971558":{"c":"Burg in Frankreich"},"ch-Q5118794":{"c":"Burg in Frankreich"},"ch-Q5118800":{"c":"Burg in Frankreich"},"ch-Q5118801":{"n":"Lützelburg (Ottrott)","c":"Burgruine im Département Bas-Rhin","r":"Die Lützelburg, auch als Vorder-Lützelburg bezeichnet, ist die Ruine einer Höhenburg bei Ottrott im Département Bas-Rhin im Elsass. Sie ist Teil der Ottrotter Schlösser.","h":"Die Burg stammt wohl aus der ersten Hälfte des 13. Jahrhunderts. Im Jahr 1372 wurde sie eventuell durch Enguerrand VII. de Coucy zerstört. 1392 war der „Burgstall“ als Reichslehen im Besitz der von Andlau, gefolgt von den Rathsamhausen-Ehnweier 1393. Im Jahr 1570 war sie zumindest in Teilen wieder Ruine, 1856/57 wurde die Burg restauriert.","w":"https://de.wikipedia.org/wiki/L%C3%BCtzelburg_(Ottrott)"},"ch-Q5118816":{"c":"Burg in Frankreich"},"ch-Q5118834":{"c":"Burg in Frankreich"},"ch-Q5118840":{"n":"Château de Saint-Ilpize","c":"Burg in Frankreich"},"ch-Q5118850":{"c":"Schloss in Frankreich"},"ch-Q5118852":{"c":"Burg in Frankreich"},"ch-Q5118871":{"c":"Schloss in Frankreich"},"ch-Q5118864":{"c":"Burg in Frankreich"},"ch-Q5118732":{"c":"Burg in Frankreich"},"ch-Q5118724":{"c":"Burg in Frankreich"},"ch-Q5118733":{"c":"Burg in Frankreich"},"ch-Q5118721":{"c":"Schloss in Frankreich"},"ch-Q5118741":{"c":"Schloss in Frankreich"},"ch-Q5118747":{"c":"Burg in Frankreich"},"ch-Q5118752":{"c":"Burg in Frankreich"},"ch-Q5118749":{"c":"Burg in Frankreich"},"ch-Q5118772":{"c":"Burg in Frankreich"},"ch-Q5118778":{"c":"Burg in Frankreich"},"ch-Q5118753":{"c":"Burg in Frankreich"},"ch-Q5118780":{"c":"Burg in Frankreich"},"ch-Q15940265":{"c":"Burg in Frankreich"},"ch-Q5118790":{"c":"Burg in Frankreich"},"ch-Q15940302":{"c":"Burg in Frankreich"},"ch-Q15940263":{"c":"Burg in Frankreich"},"ch-Q15940321":{"c":"Burg in Frankreich"},"ch-Q15940377":{"c":"Burg in Frankreich"},"ch-Q15940482":{"c":"Burg in Frankreich"},"ch-Q15940346":{"c":"Burg in Frankreich"},"ch-Q15940485":{"c":"Burg in Frankreich"},"ch-Q15940049":{"n":"Burg Bilstein","c":"Schloss in Frankreich","r":"Die Burg Bilstein ist die bei Urbeis im Unterelsass gelegene Ruine einer Höhenburg. Um sie von der nahe gelegenen gleichnamigen Burg Bilstein bei Riquewihr zu unterscheiden, wird die Wachtfeste auch Bilstein lorrain genannt, weil sie einen wichtigen Gebirgspass nach Lothringen beherrschte und zeitweise wohl auch in lothringischem Besitz war.","h":"Eine erste Erwähnung fand die Burg Bilstein 1256 mit der Nennung eines Ritters von Bilstein, der auch 1273 noch einmal urkundlich genannt wurde. Zwar existiert eine auf das Jahr 1095 datierte Urkunde, in welcher der Bann von „Bilesteen“ erwähnt wird, aber dieses Dokument ist eine Fälschung aus der Zeit zwischen 1205 und 1232. Bisher ist nicht geklärt, ob Bilstein eine eigene Herrschaft war, oder ob es zur Herrschaft Ortenberg gehörte. Ebenso ist unklar, ob der als Ritter von Bilstein Betitelte der Burgbesitzer war oder nur ein eingesetzter Burgvogt. Im Jahr 1262 war wahrscheinlich Rudolf von Habsburg Eigentümer der Anlage. Spätesten 1293 war sie dann verbürgtes Eigentum der Habsburger. In jenem Jahr gab König Adolf von Nassau die Burg an Albrecht von Hohenberg, einen Vertreter des Hauses Habsburg, zurück, nachdem er sie zuvor hatte konfiszieren lassen. Für 1303 ist mit Johann von Amoltern ein Burgmann Bilsteins belegt. Nach seinem Tod kommt das Burglehn 1310 an Heinrich Waffler von Eckerich und 1329 an dessen Schwiegersohn Werner von Hattstatt. Das „Bilsteiner Niederhaus“ („nider huse ze Bilstein“) blieb bis zum Aussterben der Familie 1585 in deren Besitz. Schon am Ende des Jahres 1314 hatte Albrecht von Habsburg die Anlage für 3000 Silbermark an den Straßburger Bischof Johann I. verkauft. Er und seine Nachfolger versetzten und verlehnten die Anlage während des 14. und 15. Jahrhunderts mehrfach. Gleichzeitig scheinen auch die Herzöge von Lothringen ein Anteil an der Burg besessen zu haben, denn 1422 gab Karl II. von Lothringen die Baillage der Vogesen – und damit wohl auch Bilstein – seiner Tochter Katharina als Mitgift in ihre Ehe mit dem späteren Markgrafen Jakob I. von Baden. Karl I., der Sohn des Paars, belehnte 1459 die Marx von Eckweckersheim mit der Burg.","w":"https://de.wikipedia.org/wiki/Burg_Bilstein_(Bas-Rhin)"},"ch-Q15940574":{"c":"Burg in Frankreich"},"ch-Q15943898":{"n":"Schloss Jallanges","c":"Renaissanceschloss in Frankreich","r":"Das Schloss Jallanges ist eine Schlossanlage im Herzen der Touraine. Sie steht rund 2,5 Kilometer nordwestlich von Vernou-sur-Brenne, einem Ort im Département Indre-et-Loire der französischen Region Centre-Val de Loire. Die Anlage im Stil der Renaissance gehört zu den Schlössern der Loire und steht seit dem 22. Juni 1946 als Monument historique in Teilen unter Denkmalschutz. Sie zählt pro Jahr rund 24.000 Besucher.","h":"Schon für das Jahr 1213 ist für diese Stelle ein Festes Haus verbürgt, das sich im Besitz von René de Perray befand. 1462 gehörte es Jean Gaudin, dessen Nachfahr Collas Gaudin es 1471 an Jean Lopin verkaufte. Wahrscheinlich ab 1460 erfolgte ein kompletter Neubau der Anlage, der bis etwa 1480 dauerte. Im letzten Drittel des 15. Jahrhunderts gehörte Jallanges gleichzeitig mehreren eng miteinander verwandten Familien. Zu diesen zählten neben den Gaudins die Familien de Saint-Pol, Houdan des Landes und de Sainte-Marthe. Am 27. Juli 1502 erwarb Nicolas Gaudin, Händler aus Tours, Schatzmeister der Anne de Bretagne und Claude de France sowie Notar und Sekretär Ludwigs XII., das gesamte Anwesen. Bis zu seinem Tod 1517 ließ er es im Stil des Flamboyants weiter ausbauen, weshalb die Anlage Ähnlichkeit zu den beiden Schlössern Plessis-lès-Tours und Les Réaux hat, deren Errichtung etwa zur gleichen Zeit erfolgte wie die beiden Bauphasen von Jallanges. Gaudin hatte keine Kinder aus seinen beiden Ehen, und so erbte die Familie Ruzé den Besitz. Über Jehanne de Ruzé kam das Schloss an deren Mann Guillaume Barthelemy. Nur wenig später wurde es durch Heirat 1520 Eigentum Philbert Babous, Oberintendant der Finanzen unter Franz I. und Urgroßvater Gabrielle d’Estrées’, der Mätresse des französischen Königs Heinrich IV. Philbert tauschte Jallanges mit François de Blanchefort am 17. Dezember 1522 gegen die Seigneurie Thuisseau. 1552 kam es erneut zu einem Eigentümerwechsel. Nach dem Tod Jeanne de Brancourts hatten René de Fontaine, Martin de Beaune und Michel Pelle das Schloss geerbt, das sie in jenem Jahr an Michel de Bouillon veräußerten. Dessen Enkel François musste es 1625 versteigern lassen. Den Zuschlag erhielt Michel Le Loyer für 32.000 Livres tournois.","w":"https://de.wikipedia.org/wiki/Schloss_Jallanges"},"ch-Q15940103":{"c":"Burg in Frankreich"},"ch-Q15940154":{"n":"Château de Freundstein","c":"Burg in Frankreich"},"ch-Q15940158":{"c":"Burg in Frankreich"},"ch-Q15940142":{"c":"Burg in Frankreich"},"ch-Q15940164":{"c":"Burg in Frankreich"},"ch-Q15940160":{"c":"Burg in Frankreich"},"ch-Q15940174":{"c":"Burg in Frankreich"},"ch-Q10988605":{"c":"Schloss in Frankreich"},"ch-Q15940231":{"c":"Burg in Frankreich"},"ch-Q15944161":{"c":"Burg in Frankreich"},"ch-Q17346989":{"c":"Schloss in Frankreich"},"ch-Q17346995":{"c":"Burg in Frankreich"},"ch-Q13220453":{"n":"Burg Egisheim","c":"Burg in Frankreich","r":"Die Burg Egisheim ist eine Burg in der Ortsmitte der elsässischen Ortschaft Egisheim im Oberelsass, rund sechs Kilometer südlich von Colmar. Die umgangssprachlich falsch als Pfalz bezeichnete Anlage sticht aus den zahlreichen Burgen im Elsass durch ihren oktogonalen Grundriss mit zentralem, ebenfalls achteckigen Bergfried hervor, der in dieser Region nur noch von Wangen und Gebweiler bekannt ist. Die genaue Entstehungszeit der Burg ist bisher ungeklärt, als mögliche Erbauer kommen die Grafen von Dagsburg oder das Bistum Straßburg infrage. Forschungen in den letzten Jahrzehnten haben allerdings ergeben, dass die seit dem 19.","h":"Die Etichonen, deren Nachkommen die späteren Grafen von Egisheim waren, hatten wohl schon früh Besitz in Egisheim, doch die Annahme, die dortige Stadtburg sei im 8. Jahrhundert durch Graf Eberhard, den Enkel des Herzogs Eticho, erbaut worden, ist unglaubwürdig. Diese früher oft gemachte Aussage fußt auf der erst im 12. Jahrhundert entstandenen Ebermünsterer Chronik, in der zu lesen ist, dass der 747 verstorbene Graf Eberhard auf der von ihm erbauten Burg Egisheim gewohnt habe. Neben dem Fakt, dass die Klostergeschichte erst vier Jahrhunderte nach dem eigentlichen Geschehen aufgezeichnet wurde und deren Richtigkeit deshalb eher zweifelhaft ist, wäre im Übrigen die nahe gelegene Burg Hoh-Egisheim ein viel wahrscheinlicherer Wohnsitz für den Grafen Eberhard gewesen. Alle urkundlichen Erwähnungen eines castrums Egisheim in der Zeit vom 11. bis Mitte des 13. Jahrhunderts beziehen sich auf diese Höhenburg über dem Ort, der nach dem Aussterben der Grafen von Egisheim 1144 durch Erbschaft an die Grafen von Dagsburg kam. Mit dem Tod Gertrudes von Dagsburg, Tochter des Grafen Albert II., im Jahr 1225 starb auch dieses Geschlecht aus, und mehrere Parteien erhoben Ansprüche auf seine Nachfolge. Zu diesen zählten neben den Leiningern die Markgrafen von Baden, die Grafen von Pfirt und das Bistum Straßburg. Es entspann sich ein Erbfolgekrieg zwischen ihnen, der möglicherweise Anlass für den Bau der Stadtburg gewesen ist. Zumindest gelten die Grafen von Dagsburg oder ihre direkten Nachfolger als Erbauer der Anlage. Am 2. November 1226 kaufte der Straßburger Bischof Berthold von Teck den Markgrafen von Baden die beanspruchten Rechte auf Egisheim ab.","w":"https://de.wikipedia.org/wiki/Burg_Egisheim"},"ch-Q17624846":{"c":"Schloss in Frankreich"},"ch-Q13360318":{"n":"Château de la Grange Fort","c":"Schloss in Frankreich","r":"Das Schloss La Grange Fort, auch Grangefort geschrieben, ist ein französisches Schloss in der auvergnatischen Ortschaft Les Pradeaux im Département Puy-de-Dôme. Die Anlage im Stil der Neugotik steht am östlichen Ufer des Allie etwa sieben Kilometer südöstlich von Issoire. Ihre Wurzeln sind in einer Burg des 14. Jahrhunderts zu suchen.","h":"Das Schloss La Grange Fort ging im Mittelalter aus einem Zehntlager der etwas weiter südlich liegenden Burg Nonette hervor. Darauf deutet auch sein Name hin, denn grange fort bezeichnet eine befestigte Scheune. Nonette war Teil der Apanage des Herzogs von Berry, Jean de Valois. Von ihm erwarb die auvergnatische Adelsfamilie Ambillon um das Jahr 1370 einen Teil des Landbesitzes samt der Scheune und ließ dort eine Burg errichten. Erster namentlich bekannter Besitzer war Jacques d’Ambillon. Die von seiner Familie erworbenen Ländereien wurden zu einer eigenständigen Seigneurie erhoben, mit der sowohl die niedrige als auch hohe Gerichtsbarkeit sowie Fischerei- und Jagdrechte verbunden waren. 1445 veräußerte der damalige Burgbesitzer die Anlage für 2000 Goldécu an Hugues de Pons. Einer seiner Enkel, Gilbert de Pons, Seigneur von Tallende und Roquet, gehörte zum Gefolge des Marschalls Artus de Cossé, comte de Secondigny, und war unter anderem für die Festung von Usson verantwortlich. Während der Hugenottenkriege konnte die Burg Nonette unter seiner Führung einer Belagerung durch Truppen der Katholischen Liga standhalten. Er konnte jedoch nicht verhindern, dass die Ligisten 1592 unter dem Kommando des Herzogs von Nemours seine Burg La Grange Fort plünderten und niederbrannten. Die Anlage wurde aber kurze Zeit später, während der Regierungszeit Heinrichs IV. von Frankreich, wiederaufgebaut. Während der Französischen Revolution teilte das Schloss das Schicksal so vieler Adelssitze: Es wurde zum Teil zerstört, nur die Fundamente sowie eine Partie des Erdgeschosses blieben unversehrt.","w":"https://de.wikipedia.org/wiki/Schloss_La_Grange_Fort"},"ch-Q15214745":{"c":"Burg in Frankreich"},"ch-Q22829617":{"n":"Burg Auray","c":"Burg in Frankreich","r":"Die Burg Auray ist eine abgegangene Burg, die sich in der Stadt Auray im Département Morbihan in der Bretagne befand.","h":"Die erste Burg von Auray, deren Existenz 1096 erwähnt wird, schützte eine Furt über den Loc'h und den Hafen von Saint-Goustan. 1201 wurde die Burg für Arthur I. von Bretagne († 1203) erneuert. Während des Bretonischen Erbfolgekriegs (1341–1364) wurde die Burg nacheinander von der englischen und der französischen Partei eingenommen. Am 29. September 1364 belagerte Johann von Montfort die Burg im Rahmen der Schlacht von Auray und beendete die Ansprüche seines Rivalen Charles de Blois auf das Herzogtum der Bretagne, der dabei getötet wurde. Der Ort seines Todes, Kerblois en Brech, ist durch einen Kalvarienberg gekennzeichnet. Die Burg war danach der Aufenthaltsort mehrerer bretonischen Herzöge. Franz I. heiratete hier am 30. Oktober 1422 Isabelle Stewart. Danach wurde die Burg nicht mehr instand gehalten und verfiel. Ihre Gräben wurden nach 1546 versteigert, nachdem König Franz I. beschlossen hatte, alle brachliegenden Ländereien der Domaine de Bretagne abzugeben. König Heinrich II. verfügte den Abriss der Ruine, doch der Procureur du Roi setzte durch, dass die Mauer auf der Flussseite erhalten blieb, und sie existiert noch heute. Die Steine der Burg wurden 1558 vom König den Geistlichen der Abtei Sainte-Croix de Quimperlé, die die Belle-Île besaß, für den Bau des Forts von Le Palais zum Schutz vor englischen Piraten geschenkt; das restliche Material wurde 1559 versteigert. Das Grundstück wurden 1560 verkauft. Am 6. September 1560 wurde eine „Rue Neuve“ auf dem nördlichen Burggraben angelegt. Einige Jahre später war die Straße vollständig von Häusern gesäumt und wurde „Rue du Château“ genannt. Neben einigen Fachwerkhäusern ist die Straße von stabileren Häusern gesäumt, die Kalkstein verwendeten, ein Material, das im 17. und 18. Jahrhundert in Mode war.","w":"https://de.wikipedia.org/wiki/Burg_Auray"},"ch-Q22915889":{"n":"Hôtel de Ville (Épinay-sur-Seine)","c":"Schloss in Frankreich","r":"Das Hôtel de Ville in Épinay-sur-Seine, einer französischen Stadt im Département Seine-Saint-Denis in der Region Île-de-France, wurde von 1756 bis 1760 errichtet. Das Hôtel de Ville an der Rue Quétigny, mit Blick von der Gartenseite zur Seine, steht seit 1987 als Monument historique auf der Liste der Baudenkmäler in Frankreich.","w":"https://de.wikipedia.org/wiki/H%C3%B4tel_de_Ville_(%C3%89pinay-sur-Seine)"},"ch-Q15944317":{"n":"Schloss Thorey-Lyautey","c":"Schloss in Frankreich","r":"Das Schloss Thorey-Lyautey ist ein Schloss in der Gemeinde Thorey-Lyautey im Département Meurthe-et-Moselle. Ursprünglich von Maréchal Lyautey bewohnt, ist es heute ein dem Maréchal gewidmetes Museum. Es firmiert unter dem Namen Maison des Illustres. Das Schloss, inklusive des Parks und seiner Statuen sind seit dem 7. Juli 1980 als Monument historique gelistet.","w":"https://de.wikipedia.org/wiki/Schloss_Thorey-Lyautey"},"ch-Q21948560":{"n":"Schloss Dampierre (Aube)","c":"Schloss in Frankreich","r":"Das Schloss in Dampierre, einer französischen Gemeinde im Département Aube in der Region Grand Est, wurde im dritten Viertel des 17. Jahrhunderts errichtet. Das Schloss ist seit 1929 als Monument historique klassifiziert.","w":"https://de.wikipedia.org/wiki/Schloss_Dampierre_(Aube)"},"ch-Q18347680":{"c":"Schloss in Frankreich"},"ch-Q20724462":{"c":"Schloss in Frankreich"},"ch-Q18736776":{"c":"Palast in Frankreich"},"ch-Q22963851":{"c":"Schloss in Frankreich"},"ch-Q22963900":{"n":"Schloss Fervaques","c":"Schloss in Frankreich","r":"Das Schloss Fervaques, auch Domaine de Fervaques oder Château le Kinnor genannt, ist ein Schloss in den ehemaligen französischen Gemeinden Fervaques und Cheffreville-Tonnencourt im Département Calvados in der Region Normandie. Es wurde hauptsächlich im 16. und 17. Jahrhundert erbaut und im 19. Jahrhundert umgebaut.","h":"Das heutige Schloss stammt aus dem 16. und frühen 17. Jahrhundert. Es wurde auf Initiative von Guillaume de Hautemer in der Nähe des alten gotischen Herrenhauses seiner Vorfahren, dessen Wohnhaus teilweise erhalten ist, von François Gabriel, Maurermeister und Ahnherr der Gabriel-Familie, erbaut. Die Eleganz des erhaltenen Ensembles verleiht dem Anwesen eine Rolle als „Zeugnis einer Baukunst in der Normandie, in den Anfängen des klassischen Zeitalters“. Guillaume de Hautemer, ein Waffengefährte Heinrichs IV. und späterer Marschall von Frankreich und Duc de Grancey, kam durch seine Heirat, seine Ämter und auch durch Plünderungen zu Vermögen und konnte einen bereits bekannten Architekten mit dem Bau beauftragen, der von 1595 bis 1602 fertiggestellt wurde. François Gabriel hatte bereits insbesondere am Schloss Carrouges gearbeitet. Das Schloss ging später an die Familien Prie und Bullion über und wurde 1803 von Delphine de Sabran, Witwe des Marquis de Custine, auf Anraten von François-René de Chateaubriand, dem sie sehr nahe stand und der sich später dort aufhielt, erworben. In der Nacht vom 19. auf den 20. September 1934 wurde im Schloss eingebrochen, es wurde Tafelsilber im Wert von 15.000 Francs entwendet.","w":"https://de.wikipedia.org/wiki/Schloss_Fervaques"},"ch-Q22964040":{"c":"Schloss in Frankreich"},"ch-Q22329669":{"c":"Schloss in Frankreich"},"ch-Q22987812":{"c":"Schloss in Frankreich"},"ch-Q22953710":{"n":"Burg Uzès","c":"Schloss in Frankreich","r":"Die Burg Uzès, genannt Le Duché, ist eine Burg aus dem 11. Jahrhundert in der mittelalterlichen Stadt Uzès im Département Gard. Sie ist seit 1934 als historisches Monument eingetragen und seit 1889 teilweise klassifiziert.","h":"Bereits in gallorömischer Zeit bestand ein Römisches Militärlager (Castrum) auf dem höchsten Punkt von Uzès (Ucetia) Die Herrschaft Uzès wurde im 11. Jahrhundert, zu Beginn des Feudalismus, von Elzéart d’Uzès gegründet. Die befestigte Stadt und ihre Burg wurden dann an der Stelle des vorherigen Castrum errichtet (und im Laufe der Zeit umgebaut), mit seinen Wällen, Ecktürmen und seinem 42 Meter hohen Donjon (Tour Bermonde), der von Bermond I. von Uzès im 12. Jahrhundert errichtet wurde, mit seinem herrschaftlichen Wohnhaus (mit Renaissancefassade aus dem 16. Jahrhundert), seinen tausendjährigen Kellern und seiner flamboyant-gotischen Burgkapelle aus dem 16. Jahrhundert (mit einem Dach aus burgundischen Glasurziegeln und dem Wappen des ersten Herzogs von Uzès Antoine de Crussol aus dem Haus Crussol). Der Bischof von Uzès, Jean de Saint-Gelais, bekehrte die mächtige Diözese Uzès 1566 zum Protestantismus. Die Stadt, die größtenteils protestantisch war, ergriff daraufhin Partei für die Reformation und wurde durch die Religionskriege stark in Mitleidenschaft gezogen. Während der protestantische Vicomte d’Uzès, Antoine de Crussol, versuchte, Katholiken und Protestanten in Südfrankreich zu versöhnen, erhob König Karl IX. Uzès 1565 zum Herzogtum und ernannte ihn zum 1. Herzog von Uzès und im Februar 1572 zum Herzog und Pair von Frankreich, vor dem Massaker der Bartholomäusnacht (24. August) in Paris und dem Übertritt des Herzogs zum Katholizismus. Während der Französischen Revolution wurde die Burg als Nationalgut verkauft und in ein Collège umgewandelt. Der 10.","w":"https://de.wikipedia.org/wiki/Burg_Uz%C3%A8s"},"ch-Q22943186":{"n":"Schloss La Ferté-Imbault","c":"Schloss im Département Loir-et-Cher, Frankreich","r":"Das Schloss La Ferté-Imbault, eine Festung aus dem Mittelalter, die in der Renaissance wieder aufgebaut wurde, ist das größte Ziegelsteinschloss der Sologne und eines der ältesten. Es war vier Jahrhunderte lang der Sitz der Familie Estampes.","h":"Eine erste Festung wurde um 980 von Humbold (oder Humbault, Imbault) Le Tortu, dem Herrn von Vierzon, errichtet, der in der Überlieferung als Schwiegersohn von Theobald I., Graf von Blois, angegeben wird. Der nahe gelegene Fluss Sauldre versorgt den Burggraben mit Wasser. Die Grundmauern der beiden Haupttürme sind bis heute erhalten geblieben, ebenso wie der ehemalige Waffensaal. Hervé I., Herr von Vierzon und Nachfahre Humbolds, ließ nach seiner Rückkehr vom Kreuzzug eine Stiftskirche zu Ehren des heiligen Taurin errichten. Diese kirchliche Präsenz und die Notwendigkeit, die Festung zu versorgen, begünstigten die Entstehung des Dorfes La Ferté-Imbault, das um die Festung herum gebaut wurde. 1280 heiratete Jeanne de Vierzon, Erbin von La Ferté-Imbault, Gottfried von Brabant, Herr von Aarschot, Sohn des Herzogs Heinrich III. von Brabant und Adelheid von Burgund. Gottfried von Brabant war der Schwager des französischen Königs Philipp III., da er der Bruder der Königin Maria von Brabant war. Alix von Brabant, die Tochter Gottfrieds, heiratete 1302 Jean III. d’Harcourt – diese Heirat, die ihm die Herrschaft La Ferté-Imbault einbrachte, machte Jean d'Harcourt zu einem nahen Verwandten der Herzöge von Brabant und der Könige von Frankreich. Jean IV., erster Graf von Harcourt, der Sohn von Jean III. d'Harcourt und Alix de Brabant, heiratete Isabeau, die Tochter von Jean I. de Parthenay, Dame de Vibraye, de Montfort et de Bonnétable.","w":"https://de.wikipedia.org/wiki/Schloss_La_Fert%C3%A9-Imbault"},"ch-Q22996403":{"c":"Schloss in Frankreich"},"ch-Q19362031":{"n":"Rathaus Clichy-sous-Bois","c":"Schloss in Frankreich","r":"Das Rathaus in Clichy-sous-Bois, einer französischen Gemeinde im Département Seine-Saint-Denis in der Region Île-de-France, wurde im 18. Jahrhundert errichtet. Das Rathaus an der Place du 11 Novembre 1918 steht seit 1972 als Monument historique auf der Liste der Baudenkmäler in Frankreich.","w":"https://de.wikipedia.org/wiki/Rathaus_Clichy-sous-Bois"},"ch-Q16972444":{"c":"Schloss in Frankreich"},"ch-Q20065183":{"c":"Schloss in Frankreich"},"ch-Q22988117":{"c":"Schloss in Frankreich"},"ch-Q22966949":{"c":"Schloss in Frankreich"},"ch-Q22965265":{"n":"Schloss Menou","c":"französisches Schloss in Menou","r":"Das Schloss Menou ist ein französisches Schloss im Stil des Louis-treize, das in der Gemeinde Menou rund 40 Kilometer nordöstlich von Nevers im burgundischen Département Nièvre steht. Es wurde in der zweiten Hälfte des 17. Jahrhunderts von Armand-François de Menou als Nachfolger eines abgebrannten Herrenhauses erbaut. Von der Familie Menou kam es über eine Tochter 1764 an die Familie von Damas-Crux und von dieser nach 1846 an die Herzöge von Blacas.","h":"Das Gebiet um Menou hieß früher Nanvignes und war eine eigenständige Seigneurie. Durch Erbteilungen war sie zu Beginn des 16. Jahrhunderts im Besitz von vier Parteien, von denen eine die Familie Tenon war. Sie kaufte den anderen Besitzern ihre Anteile an der Seigneurie nach und nach ab und vereinte diese im 17. Jahrhundert schließlich wieder in einer Hand. Guillaume IV. Tenon starb kinderlos. Seine Witwe Marie Brisson heiratete 1625 in dritter Ehe François de Menou, Seigneur von Charnizay, und brachte ihm den Besitz zu. Für den Sohn des Paares, Armand-François, erhob Ludwig XIV. Nanvignes unter dem Namen Menou in Anerkennung für geleistete Verdienste im Militär im Juni 1697 zum Marquisat. Armand-François nutzte das Schloss seit 1671 und hatte zwischen 1672 und 1684 ein neues Schloss nach den Plänen des Architekten Barthélemy Le Blanc errichten lassen, weil das alte Herrenhaus durch ein Feuer im Jahr 1672 zerstört worden war. Die Kosten für den Neubau beliefen sich auf etwa 30.000 Livres. Nach dem Tod des ersten Marquis im Jahr 1703 erbte seine Witwe Françoise-Marie de Clère das Schloss, ehe sie es 1719 ihrem ältesten Sohn François-Charles de Menou überließ. Dessen zweite Tochter Marie-Louise erhielt den Besitz 1764 nach dem Tod ihrer älteren Schwester. Sie hatte 1734 Louis-Alexandre de Damas, den Grafen von Crux, geheiratet und brachte das Schloss an dessen Familie. Das Paar nutzte die Anlage zwar regelmäßig, jedoch nicht als Hauptwohnsitz. Dieser war das Schloss in Crux-la-Ville. 1763 zog sich die verwitwete Marie-Louise nach Menou zurück und verhinderte trotz ihres hohen Alters während der Französischen Revolution durch ihre Anwesenheit Übergriffe auf das Schloss.","w":"https://de.wikipedia.org/wiki/Schloss_Menou"},"ch-Q22962887":{"c":"Schloss in Frankreich"},"ch-Q28040794":{"n":"Schloss Pompadour","c":"Schloss in Frankreich","r":"Das Schloss Pompadour ist ein Schloss in der französischen Gemeinde Arnac-Pompadour im Département Corrèze in der Region Nouvelle-Aquitaine.","h":"Das Gebiet Arnac-Pompadour liegt auf einer alten galloromanischen Siedlung. Vom ursprünglichen Castrum des Guy de Lastours, Sire de Pompadour, erbaut um das Jahr 1000 auf einer strategischen Achse zwischen Brive und Limoges, blieben keine Reste. Die alte Festung, die von den örtlichen adeligen Herren begehrt wurde, widerstand seit 1026 zwar diversen Angriffen, wurde jedoch während der Unruhen nach dem Tod des Königs Richard Löwenherz im Burg Châlus-Chabrol im Jahre 1199 vollständig zerstört. Bis ins 13. Jahrhundert wurde die Herrschaft Pompadour als Coseigneurie geführt und unterstand so den Baronen von Pierre-Buffière und der Familie de Hélie (Vasallen des Vizegrafen von Limoges) mit Wohnsitz bei der nahegelegenen Burg Ségur. Letztere wurden durch geschickte Ehepolitik zum alleinigen Besitzer, kopierten das Wappen der Lastours, und nahmen in den Jahren um 1500 auch den Namen de Pompadour an. Im 15. Jahrhundert wurden die baulichen Überreste der einstigen Festung von Bischof Geoffroy Hélie de Pompadour zum Schloss ausgebaut. Zwischen den verschwägerten Familien der Pierre-Buffière und Pompadour herrschte jahrhundertelang Rivalität, zurückgehend auf die Heiraten von Herren jeder der Familien mit jeweils einer letzten Erbin des mächtigen Hauses der Vicomtes de Comborn. Von da ab standen sich die Familien feindselig in Prozessen, Duellen und Schlachten (der Religionskriege und der Fronde) gegenüber. So wurde um 1567 François de Pierrebuffière-Châteauneuf, Marquis von Chamberet, vom Katholiken Jean de Pompadour in einem Duell getötet.","w":"https://de.wikipedia.org/wiki/Schloss_Pompadour"},"ch-Q28099935":{"c":"Schloss in Frankreich"},"ch-Q23410571":{"n":"Château des Rohan","c":"Museum in Frankreich"},"ch-Q33232359":{"n":"Hôtel de Ville (Gagny)","c":"Rathaus in Frankreich","r":"Das Hôtel de Ville in Gagny, einer französischen Stadt im Département Seine-Saint-Denis in der Region Île-de-France, wurde in den 1750er Jahren errichtet. Das Hôtel de Ville steht an der Place Foch.","w":"https://de.wikipedia.org/wiki/H%C3%B4tel_de_Ville_(Gagny)"},"ch-Q27961933":{"n":"Château d'Urville","c":"Schloss in Frankreich","r":"Das Château d’Urville ist ein Schloss in der historischen Landschaft Lothringen. Bekannt ist es vor allem, weil es von 1890 bis 1918 Kaiser Wilhelm II. gehörte.","h":"Im 12. Jahrhundert gehörte der Ort zur Grafschaft Kriechingen und den Herren von Rollingen. Damals eine Burg, stellte die Anlage einen vorgeschobenen Posten an der Grenze von Lothringen dar. Aufgrund ihrer strategisch bedeutsamen Lage zu Metz wurde sie 1444 von einer Abteilung der französischen Armee überfallen, das damals Krieg gegen die Stadt Metz führte. Die Burg Urville wurde 1588 während des Durchzugs der katholischen Truppen von Henri I. de Guise zerstört. Aus der Zeit vor der Zerstörung sind heute nur noch zwei Zeugnisse erhalten: ein auf Arkaden gebauter Taubenschlag mit kleinen Schießscharten und eine Kaminplatte mit dem Wappen der Herren von Rollingen. Ende des 16. Jahrhunderts kaufte Nicolas Houillon, ein Bürger von Metz, die Anlage und baute sie als Schloss wieder auf. Bis 1680 blieb sie im Besitz der Familie, wurde dann an Esther Domangin, Witwe des Herrn von Vigy, verkauft. 1754 ging das Schloss an Guillaume Othon, einen ehemaligen Oberst der Kavallerie und Kammerherrn der Herzöge von Lothringen über. 1764 wechselte es erneut den Besitzer: François-Louis Durant, Major aus Metz, war der neue Eigentümer. Ihm folgte François-Louis-Benoit-Charles-Pantaléon Durand, Generalanwalt im Parlement von Metz und Bürgermeister. Er war es wahrscheinlich, der den großen Schlosspark anlegte, der seit 1926 unter Denkmalschutz steht. 1808 musste er das Schloss aufgrund wirtschaftlicher Not an General Jean-Baptiste Semellé, Baron des Kaiserreichs Frankreich, verkaufen, der dort am 25. Januar 1839 starb. 1813 diente das Schloss Prinz Wilhelm von Preußen als Hauptquartier. 1847 wurde es von Baron Louis Sers erheblich verändert. Er fügte den polygonalen Risalit auf der Rückseite und die Terrasse mit Balustrade auf der Vorderseite hinzu.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_d%E2%80%99Urville"},"ch-Q38251110":{"c":"Burg in Frankreich"},"ch-Q259910":{"c":"Schloss und Weingut in Frankreich"},"ch-Q169369":{"c":"Museum in Frankreich"},"ch-Q186575":{"n":"Schloss Filières","c":"Schloss in Frankreich","r":"Das Schloss Filières stammt in weiten Teilen aus der zweiten Hälfte des 18. Jahrhunderts und steht in der französischen Gemeinde Gommerville im Département Seine-Maritime in der Normandie. Seit dem 31. Mai 1946 ist es als Monument historique in die französische Denkmalliste eingeschrieben. Einige seiner Räume sind mit ihrer Innenausstattung aus dem 18. Jahrhundert seit dem 13. Dezember 1947 sogar als Monument historique klassifiziert. Sie können im Rahmen einer Führung besichtigt werden.","h":"Am Ort des heutigen Schlosses Filières stand im Mittelalter ein von Wassergräben umgebenes festes Haus, das der Adelsfamilie Filières gehörte und während des Hundertjährigen Krieges zerstört wurde. Über Erbtöchter kam der Besitz über die Familien Le Canu de Froiderue und Le Terrier schließlich an die Familie Chardon, die sich nachfolgend Chardon de Filières nannte. Sie ließ das ruinöse Gebäude während der Herrschaftszeit Heinrichs IV. durch einen Neubau im Stil der Renaissance ersetzen. Louise Chardon de Filières heiratete 1732 Jacques Eudes de Catteville, Marquis von Mirville, und brachte die Anlage an ihren Mann. Er begann in der zweiten Hälfte des 18. Jahrhunderts damit, das damalige Logis nach den Plänen des französischen Architekten Victor Louis durch ein repräsentatives Schloss zu ersetzen. Louis hatte zuvor das Große Theater in Bordeaux errichtet. Da das Bauvorhaben durch die Französische Revolution unterbrochen wurde, weist das heutige Schloss in seiner Gesamtkonstruktion zwei unterschiedliche Baustile auf: Der jüngere, westliche Teil des heutigen Herrenhauses präsentiert sich im Louis-seize-Stil, während der Ostteil noch die Merkmale der französischen Renaissance-Architektur zeigt. Nach dem Tod Jacques Eudes de Cattevilles erbte sein Sohn Alexandre den Besitz. Dessen Urenkelin Blanche heiratete den Grafen Henri Hocquart de Turtot. Heute wird das Schloss vom Marquis und der Marquise de Persan bewohnt. Die Schlossherrin ist eine geborene Hocquart de Turtot. Gemeinsam mit ihrem Mann ließ sie 2007 die südöstliche Schlossfassade restaurieren, ehe 2011 die Nordwestseite folgte. Anschließend wurde drei Jahre lang die Orangerie renoviert. Letzte Baumaßnahme war ab 2015 die Wiederherstellung der in den 1960er Jahren teilweise eingestürzten Schlosskapelle.","w":"https://de.wikipedia.org/wiki/Schloss_Fili%C3%A8res"},"ch-Q338711":{"c":"Burg in Frankreich"},"ch-Q371491":{"n":"Burg Pusignan","c":"Burg in der Gemeinde Pusignan, Frankreich","r":"Die Burg Pusignan ist eine mittelalterliche Festung, die im 12. Jahrhundert auf den Ruinen eines römischen Lagers errichtet wurde. Ihre Ruinen bilden das wichtigste Baudenkmal der französischen Gemeinde Pusignan im Département Rhône.","h":"Die römische Befestigung stammt aus der Zeit der Eroberung Galliens durch die Römer unter Julius Caesar. Sie lag an der Straße vom römischen Lugdunum nach Cremiacum. Nach dem Zusammenbruch des Römischen Reichs lag Pusignan im Siedlungsgebiet der Burgunden. Im Frühmittelalter entstand im Bereich des ehemaligen Römerlagers eine Motte mit einfachen Holzgebäuden. Im 12. Jahrhundert begannen die Herren von Moifond, ein regionales Adelsgeschlecht, mit dem Bau einer größeren Burg. Die aus Stein gebaute Anlage besaß eine weite Ringmauer. Im Jahr 1430 war die Burg von Pusignan Schauplatz einer kriegerischen Auseinandersetzung. Die Schlacht von Anthon war ein bedeutendes Ereignis im Konflikt zwischen der Dauphiné und dem Fürsten von Orange, Ludwig von Chalon. Der wollte die beiden Herrschaften zusammenführen und dazu die dazwischenliegenden Gebiete an der Rhone einnehmen. Die Burg Pusignan erhielt eine Besatzung aus Orange. Der Gouverneur der Dauphiné, Raoul de Gaucourt, wollte den Ort zurückerobern und engagierte dazu den Freischärler Rodrigue de Villandrando. Mit dessen Verstärkung eroberten die Truppen der Dauphiné mehrere Burgen in der Region zurück und schlugen am 7. Juni 1430 vor der Burg Pusignan ihr Lager auf. Die Festung fiel schon am 9. Juni in ihre Hände. Zwei Tage später geriet das Heer Ludwigs von Cahlon zwischen Anthon und Colombier-Saugnieu in einen Hinterhalt und wurde vom viel kleineren Aufgebot aus der Dauphiné in die Flucht geschlagen. Viele Flüchtende sollen in der Rhône ertrunken sein. König Karl VII. zog die Burg Pusignan ein und verlieh sie anschließend an Rodriguez von Villandrando. 1450 erwarb Aymar von Poisieu, ein ehemaliger Gefolgsmann Jeanne d’Arcs, die Burg. Als Vertrauter des Dauphins und späteren Königs von Frankreich Ludwig XI.","w":"https://de.wikipedia.org/wiki/Burg_Pusignan"},"ch-Q740652":{"n":"Burg Niort-de-Sault","c":"Burg in Frankreich","r":"Die Burg Niort-de-Sault ist die Ruine einer mittelalterlichen Höhenburg im Bergland des Pays de Sault im heutigen Département Aude in der französischen Region Okzitanien. Von der kleinen Gemeinde Niort-de-Sault führt ein etwa ein Kilometer langer Fußweg bis zur Burgruine auf 950 Metern Höhe.","h":"Bereits in westgotischer Zeit soll hier eine Höhenfestung (castrum) gestanden haben; für das 9. Jahrhundert ist jedenfalls eine Festungsanlage (Burg?) urkundlich belegt, die als Apanage Bera, dem Sohn des Grafen von Razès, zugesprochen wurde, der daraufhin den Titel Baron de Niort annahm. Bernard d’Alion, einer seiner Nachfahren, erhielt im Jahr 1047 die Vizegrafschaft Sault. Durch die Ehe Guillaume d’Alions mit Brandinière de Foix aus der Familie der Grafen von Foix im Jahr 1132 stiegen die Barone von Niort in höchste regionale Adelskreise auf. Durch die um 1175 erfolgte Eheschließung Guillaume de Niorts (Sohn von Guillaume d’Alion) mit Esclarmonde de Montréal-Laurac, deren Mutter Blanche de Laurac eine Anhängerin des Katharerglaubens war, kam das Haus Niort in engen Kontakt mit führenden Persönlichkeiten der Sekte. Doch blieben Niort und seine Burg aufgrund ihrer abgelegenen Lage inmitten von Bergen, Schluchten und reißenden Bächen während des Albigenserkreuzzugs (1209–1229) unangetastet. Unabhängig davon kämpften die Söhne von Guillaume und Esclarmonde (Géraud de Niort, Bernard-Othon de Niort, Guillaume Bernard und Raymond de Roquefeuille) zeitweise auf Seiten der Kreuzritter und nicht auf Seiten ihrer Glaubensgenossen – so z. B. in der Schlacht bei Muret (1213). Im Jahre 1240 übergab Géraud de Niort in einer symbolisch gemeinten Geste und als Ausdruck seines guten Willens seinen gesamten Besitz an König Ludwig IX. Üblicherweise hätte der König diesen unverzüglich als Lehen zurückgeben müssen, doch – angesichts der nicht enden wollenden Auseinandersetzungen mit den Katharern, speziell mit dem Haus Niort – konfiszierte er ihn zugunsten der Krone.","w":"https://de.wikipedia.org/wiki/Burg_Niort-de-Sault"},"ch-Q773139":{"c":"Burg in Frankreich"},"ch-Q778084":{"c":"Burg in Frankreich"},"ch-Q509632":{"n":"Schloss Montjalin","c":"Schloss in Frankreich","r":"Das Schloss Montjalin ist ein klassizistisches Schloss im Ortsteil Montjalin der burgundischen Gemeinde Sauvigny-le-Bois, rund 5,5 Kilometer nordöstlich von Avallon. Es entstand in der zweiten Hälfte des 18. Jahrhunderts im Auftrag der Familie Fresne anstelle einer mittelalterlichen Burg. Im Zweiten Weltkrieg durch deutsche Soldaten stark beschädigt, verfiel das Gebäude nach Kriegsende zusehends, ehe Olivier Delafon das heruntergekommene Anwesen im Jahr 1987 erwarb und restaurierte. Das Schloss steht seit dem 20. Mai 1988 als eingeschriebenes Denkmal unter Denkmalschutz.","h":"Im Mittelalter gehörte Montjalin einer gleichnamigen Adelsfamilie. Eines ihrer Mitglieder, Hérard der Montjalin, errichtete im Jahr 1147 eine wehrhafte Burg auf seinem Besitz. Diese Anlage ließ César de Fresne 1766 oder 1768 abreißen und am gleichen Ort ein Schloss im Stil des Louis-seize errichten. Als später die Französische Revolution ausbrach, beschädigten Revolutionäre das Gebäude, indem sie die Wappen der Familie de Fresne von den Fassaden abschlugen. Den übrigen Skulpturenschmuck ließen sie aber unangetastet. Im Zweiten Weltkrieg wurde Schloss Montjalin von deutschen Soldaten schwer beschädigt. Nach Ende des Krieges kaufte ein Landwirt das Anwesen, sorgte aber nicht für die Reparatur und Instandsetzung. 1987 kaufte Olivier Delafon, ein ehemaliger Hedgefonds-Manager, die heruntergekommene Anlage, die zu jener Zeit weder Fenster noch ein Dach besaß. Der Kaufpreis betrug seinerzeit nur 120.000 Euro, allerdings musste der neue Schlossherr gemeinsam mit seiner Frau noch einmal vier Millionen Euro für die Restaurierung und Instandsetzung des Schlosses investieren. Die Arbeiten dazu wurden 1991 beendet. Dabei erhielt das Hauptgebäude eine neue, aber an historische Vorbilder angelehnte Inneneinrichtung, beginnend bei gemusterten Tapeten über Damastvorhänge bis hin zu Möbeln aus der Bauzeit des Schlosses. Im Jahr 2000 eröffnete der Schlossherr, der ein passionierter Autosammler ist, in den einstigen Pferdeställen des Schlosses das kurios-interessante Museum für Staatskarossen (Musée des Voitures de Chefs d’Etat). Hauptattraktionen unter den rund 30 Exponaten der ständigen Ausstellung waren der Lincoln von US-Präsident John F. Kennedy, das Papamobil von Papst Paul VI. und der Citroën DS 23 von Frankreichs Staatspräsident Valéry Giscard d’Estaing.","w":"https://de.wikipedia.org/wiki/Schloss_Montjalin"},"ch-Q530673":{"c":"Burg in Frankreich"},"ch-Q539485":{"n":"Roquemartine","c":"Burg in Frankreich","r":"Roquemartine ist eine Burgruine auf dem Gebiet der südfranzösischen Gemeinde Eyguières. Außerdem war Roquemartine der Name einer bis 1830 eigenständigen Gemeinde.","w":"https://de.wikipedia.org/wiki/Roquemartine"},"ch-Q440579":{"n":"Clos de Vougeot","c":"Schloss in Frankreich"},"ch-Q574056":{"n":"Schloss Cormatin","c":"Schloss in Frankreich","r":"Das Schloss Cormatin ist ein Schloss in der Gemeinde Cormatin im Département Saône-et-Loire der französischen Region Bourgogne-Franche-Comté. Es befindet sich auf einer Insel im Fluss Grosne.","h":"Erbaut wurde Schloss Cormatin ab 1605 von Antoine du Blé d’Huxelles, einem Kleinadligen, der als Heerführer in den Hugenottenkriegen zu Reichtum gekommen und zum Militärgouverneur von Chalon-sur-Saône ernannt worden war. Das Schloss wurde im Stil der Renaissance auf den Fundamenten eines mittelalterlichen Vorgängerbaus aus dem 13. Jahrhundert errichtet, mit bestimmten militärarchitektonischen Besonderheiten, wie zum Beispiel Ecktürmen und Schießscharten, als Ausdruck der neuen Stellung des Erbauers. Antoines Sohn Jacques du Blé vollendete den Innenausbau im Jahr 1625. Im Laufe seiner Geschichte empfing das Schloss schon mehrere hochgestellte Gäste: Staatsmänner wie Ludwig XIII., Richelieu oder François Mitterrand besuchten die Anlage und übernachteten dort.","w":"https://de.wikipedia.org/wiki/Schloss_Cormatin"},"ch-Q582885":{"c":"Burg in Frankreich"},"ch-Q1014308":{"n":"Burg Turquestein","c":"Burg in Frankreich","r":"Die Burg Turquestein ist die Ruine einer Höhenburg bei Turquestein-Blancrupt in den Vogesen im französischen Département Moselle der Region Grand Est.","h":"Das befestigte Schloss wurde zwischen 900 und 1000 erbaut. Ein genaues Erbauungsdatum ist nicht bekannt. 1002 übertrugen die Bischöfe von Toul die Burg als Lehen an die Freiherren von Blâmont. Der Metzer Fürstbischof Johannes I. von Apremont (1224–1238), vorher Bischof von Verdun, hatte bald nach seinem Amtsantritt eine blutige Fehde mit Simon von Leiningen wegen der dessen verstorbener Gemahlin Gertrud von Dagsburg-Metz und ihrem ersten Gemahl Theobald von Lothringen übertragenen bischöflichen Lehen. Im Friedensschluss von 1227 behielt das Bistum Metz die Grafschaft und Vogtei Metz mit den dazu gehörigen Schlössern Saarburg, Türkstein usw., übergab aber dem Grafen Simon die Grafschaft Dagsburg als Lehen. Bischof Johannes ließ die Mauern des Schlosses Türkstein anschließend wieder herstellen. 1252 wurde Burg Türkstein durch Bischof Jakob von Lothringen (1239–1260) neu befestigt. Die Burg war Sitz der Herrschaft Türkstein, deren Gebiet, das um 1305 bis zur Vezouze reichte, die Ortschaften an der Weißen und Roten Saar umfasste, an der Roten Saar mit Ausnahme derjenigen Orte, die zur Grafschaft Dagsburg gehörten. Zur Herrschaft zählten u. a. Aspach, Frackelfingen, Hattigny (vormals Hittingen), Landangen, Lascemborn, Lörchingen, Neuwiller, Niederhofen und Wasperwiller. 1634 wurde die Burg auf Befehl Kardinal Richelieus geschleift und ist seither Ruine. Noch im späten 19. Jahrhundert diente sie als Försterwohnung.","w":"https://de.wikipedia.org/wiki/Burg_Turquestein"},"ch-Q1090588":{"n":"Château Nozet","c":"Schloss in Frankreich","r":"Schloss Le Nozet ist ein Schloss und Weingut in Pouilly-sur-Loire, das besonders für seinen Pouilly-Fumé bekannt ist.","h":"1787 erwarb der aus einer reichen Bankiersfamilie stammende Comte Edmond Lafond von Madame Sophie, der illegitimen Tochter Ludwigs XV. das größte Weingut in Pouilly-sur-Loire. Eine Anekdote besagt, dass die Weißweine dieses Weingutes zu den bevorzugtesten von Napoleon gehörten. 1937 erhielten sie die Ursprungsbezeichnung Appellation d’Origine Contrôlée (AOC). 1972 übernahm ein Abkömmling des Comte Lafond, Baron Patrick de Ladoucette das Gut. Als erster hauptberuflicher und voll ausgebildeter Winzer seiner Familie war er innerhalb kürzester Zeit nicht nur in der Lage, die Weine seines Hauses zu Weltruf zu führen und die Pouilly-Fumés für jeden Gourmettempel praktisch unentbehrlich zu machen, sondern auch das Weingut um andere Spitzenprodukte zu bereichern. So erwarb er 1980 die Domaine Marc Brédif de Vouvray in der Nähe von Tours, 1985 die Domaine Régnard im Chablis und 1994 den Weinberg La Poussie bei Sancerre und brachte auch dort die Weinerzeugung auf den neuesten Stand. Somit produziert das Gut neben den Pouilly-Fumés seither auch großartige Chablis, Sancerres, Vouvrays and Chinons, von denen einige zu den besten ihrer Art gezählt werden.","w":"https://de.wikipedia.org/wiki/Schloss_Le_Nozet"},"ch-Q1236468":{"n":"Schloss Sassenage","c":"Schloss in Frankreich","r":"Das Schloss Sassenage steht unweit von Grenoble in der französischen Gemeinde Sassenage im Département Isère.","h":"Das Schloss wurde von 1662 bis 1669 durch Laurent Sommaire im Auftrag von Charles Louis Alphonse de Sassenage erbaut. Es handelt sich um den letzten Bau des Geschlechtes der Sassenage. Schloss und Gärten wurden im Jahr 1942 als Monument historique unter Denkmalschutz gestellt.","w":"https://de.wikipedia.org/wiki/Schloss_Sassenage"},"ch-Q1105327":{"c":"Burg in Frankreich"},"ch-Q608801":{"n":"Château de la Roche","c":"Schloss in Frankreich"},"ch-Q647668":{"c":"Burg in Frankreich"},"ch-Q947479":{"c":"Burg in Frankreich"},"ch-Q924311":{"c":"Burg in Frankreich"},"ch-Q949411":{"n":"Château de Grézan Art & Culture Centre","c":"Burg in Frankreich"},"ch-Q949543":{"c":"Burg in Frankreich"},"ch-Q971529":{"c":"Burg in Frankreich"},"ch-Q975321":{"c":"Burg in Frankreich"},"ch-Q976230":{"c":"Burg in Frankreich"},"ch-Q1531552":{"n":"Schloss Le Grand-Pressigny","c":"Schloss in Frankreich","r":"Das Schloss Le Grand-Pressigny gehört zur französischen Gemeinde Le Grand-Pressigny im Département Indre-et-Loire in der Region Centre-Val de Loire. Die Ortschaft liegt am Zusammenfluss von Claise und Aigronne und wurde einst von der am Uferhang aufragenden, von Guillaume de Pressigny erbauten Burg beschützt. Teile der heutigen Schlossanlage wurden im Juli 1889 als Monument historique in die französische Denkmalliste aufgenommen.","w":"https://de.wikipedia.org/wiki/Schloss_Le_Grand-Pressigny"},"ch-Q979709":{"c":"Burg in Frankreich"},"ch-Q1560769":{"n":"Schloss Thaumiers","c":"Schloss in Frankreich","r":"Das Schloss Thaumiers steht in der Gemeinde Thaumiers im französischen Département Cher.","w":"https://de.wikipedia.org/wiki/Schloss_Thaumiers"},"ch-Q1561049":{"n":"Schloss Bouteville","c":"Schloss in Frankreich","r":"Das Schloss Bouteville ist eine Schlossruine im französischen Ort Bouteville im Département Charente in der Region Nouvelle-Aquitaine. Es geht zurück auf eine gegen die Normannen errichtete Burg, die nach mehrfachen Zerstörungen und Wiederaufbauten seit der Französischen Revolution weitgehend dem Verfall preisgegeben ist. Die Anlage steht auf einem Hügel in der Nähe der bereits zur Zeit der Römer bestehenden Straße von Saintes nach Périgueux, von dem aus die Stadtmauern von Angoulême zu sehen waren. Seit Februar 1984 steht sie als Monument historique unter Denkmalschutz.","h":"Eine erste primitive Burg wurde zur Zeit der Normanneneinfälle von den Grafen von Angoulême auf den Resten einer gallorömischen Villa errichtet. Einige Jahre nach dem Ende der normannischen Invasionen kamen Burg und Herrschaft Bouteville in den Besitz von Maynard le Riche („dem Reichen“), Seigneur d’Archiac. Über dessen Tochter Pétronille und deren Heirat kam sie aber wieder zurück in den Besitz der Grafen von Angoulême, die dort eine ihrer bevorzugten Residenzen hatten. Am 16. November 1140 starb dort Graf Vulgrin II. Mit der Grafschaft Angoulême kam auch die Burg Bouteville in den Besitz des Hauses Lusignan, ehe sie 1308 an die französische Krone ging. Weitere Besitzer von Bouteville waren Königin Johanna II. von Navarra und Aimery III. de La Rochefoucauld, der Bouteville von Jean de Valois, duc de Berry als Belohnung für seine Dienste im Kampf gegen die Engländer erhielt. Während des Hundertjährigen Kriegs war die Burg Bouteville ab 1360 von den Engländern besetzt, die hier eine Garnison unterhielten. Erst 1392 konnten die Franzosen die Burg als Ruine wieder endgültig an sich bringen. 1400 war Bouteville Teil der Apanage, die Louis de Valois als neuer Graf von Angoulême erhielt. Dessen Sohn Jean begann nach seiner Freilassung aus englischer Gefangenschaft 1444 mit dem Wiederaufbau der Burg. Sein Sohn Charles d’Orléans und dessen Ehefrau Luise von Savoyen bewohnten häufig die Anlage. Nach dem Tod Luises von Savoyen 1531 wurde Bouteville an Claude de Montmorency, Seigneur de Fosseux, verkauft, um die Staatskasse in den Kriegen gegen Kaiser Karl V. zu entlasten. Sein Sohn François I. de Montmorency nahm hier seinen Wohnsitz.","w":"https://de.wikipedia.org/wiki/Schloss_Bouteville"},"ch-Q1624468":{"n":"Schloss Vaussieux","c":"Schloss in Frankreich","r":"Das Schloss Vaussieux ist eine Schlossanlage in Vaux-sur-Seulles, einer französischen Ortschaft in der Normandie. Die Anlage steht seit Juli 1970 als Monument historique unter Denkmalschutz. Besonders bekannt wurde das Schloss als Namensgeber einer französischen Militäroperation, die mit camp de Vaussieux bezeichnet wird, und bei welcher der französische Marschall de Broglie im Schloss sein Hauptquartier bezog.","h":"Schon 1056 gehörte Vaussieux einer gleichnamigen Familie, deren erstes namentlich bekanntes Mitglied Hugon de Vaussieux war. Der Besitz kam im 13. Jahrhundert an Guillaume de Taillebois. Im Jahr 1413 verkaufte Catherine de La Luzerne die Seigneurie an Germaine de Longchamps. Von dieser Familie kam die Herrschaft durch Heirat an die Grimonvilles, die sie 1605 an die Familie de Thioult veräußerten. Marthe Marie Le Héricy, verwitwete de Thioult, vermachte das Anwesen ihrem Verwandten, dem Marquis d’Héricy, Jacques-Philippe-Auguste Le Héricy, weil ihre Ehe mit Arthur Antoine de Thioult kinderlos geblieben war. Er ließ 1771 den Vorgängerbau aus der Zeit Heinrichs IV. durch das heutige Gebäude ersetzen und stellte es im August 1778 dem Marschall de Broglie als Hauptquartier für ein Militärmanöver in der Normandie zur Verfügung, das nach dem Schloss camp de Vaussieux genannt wird. Offiziellen Verlautbarungen zufolge sollten bei der rund 30.000 Mann umfassenden Operation zwei zu jener Zeit beliebte Taktiken miteinander verglichen werden, in Wahrheit ging es dem französischen König Ludwig XVI. aber vielmehr darum, die amerikanischen Soldaten in ihrem Unabhängigkeitskampf gegen England zu unterstützen. Durch die massive militärische Präsenz an der Küste Frankreichs waren die Engländer nämlich dazu gezwungen, einen Großteil ihrer Flotte nicht auslaufen zu lassen, obwohl diese dringend benötigten Nachschub und Truppen in die britischen Kolonien nach Amerika hätte bringen sollen. Im 19. Jahrhundert hießen die Besitzer Fournés. Die Marquise von Fournés hinterließ das Schloss ihrer Tochter, einer Baroness du Charmel. Diese ließ es in den ersten Jahren des 20.","w":"https://de.wikipedia.org/wiki/Schloss_Vaussieux"},"ch-Q1862379":{"c":"Burg in Frankreich"},"ch-Q1870453":{"c":"Burg in Frankreich"},"ch-Q1880497":{"n":"Lützelburg (Lothringen)","c":"Burg in Frankreich","r":"Die Lützelburg bei Lutzelbourg im französischen Département Moselle ist eine der bedeutendsten stauferzeitlichen Burgruinen im früher lothringischen Teil der Vogesen.","h":"Die Burg wurde Ende des 11. Jahrhunderts erbaut und befand sich zunächst im Besitz der dem Haus Scarponnois (väterlicherseits) bzw. dem Haus Savoyen (mütterlicherseits) entstammenden Grafen von Lützelburg, bis sie nach dem Tode von Reinard von Lützelburg († 1150) an die Bischöfe von Metz gelangte. 1163 ließen diese die Burg auf Veranlassung Friedrich Barbarossas neu befestigen. Die Lützelburg ist damit eine der wenigen urkundlich genau datierbaren stauferzeitlichen Burgenbauten. Durch Verpfändungen und Verkäufe entwickelte sich mit der Zeit eine Ganerbschaft, zu der seit 1504 auch Franz von Sickingen zählte. Nach dessen Tod 1523 ließ Kurfürst Ludwig V. von der Pfalz die Burg schleifen und die Herrschaft Lützelburg mit ihren Dörfern Haselburg, Hültenhausen, Wilsberg und Mittelbronn wurde mit der pfälzischen Grafschaft Lützelstein (La Petite-Pierre) vereinigt. Die militärische Funktion ging auf die 1570 gegründete Festung Pfalzburg über. 1840 verhinderte Adolf Germain, Notar aus Phalsbourg, den Abbruch der Burgruine, deren Steine zum Bau der Bahnlinie Straßburg-Metz bestimmt waren. Um 1900 erwarb der Straßburger Medizinprofessor Eugène Koeberlé die Ruine und errichtete sich einen neoromanischen Wohnbau.","w":"https://de.wikipedia.org/wiki/L%C3%BCtzelburg_(Lutzelbourg)"},"ch-Q1882287":{"c":"Burg in Frankreich"},"ch-Q1887201":{"c":"Burg in Frankreich"},"ch-Q1888542":{"c":"Burg in Frankreich"},"ch-Q1925837":{"c":"Burg in Frankreich"},"ch-Q1904744":{"c":"Burg in Frankreich"},"ch-Q1938340":{"c":"Burg in Frankreich"},"ch-Q1959175":{"c":"Burg in Frankreich"},"ch-Q1975803":{"c":"Burg in Frankreich"},"ch-Q1985816":{"c":"Burg in Frankreich"},"ch-Q2044804":{"c":"Burg in Frankreich"},"ch-Q1727902":{"n":"Schloss Abbans-Dessus","c":"Schloss in Frankreich","r":"Das Schloss Abbans-Dessus befindet sich in Abbans-Dessus, einer Gemeinde im französischen Département Doubs in der Region Bourgogne-Franche-Comté. Es wurde ab dem 12. Jahrhundert errichtet und ist seit 1992 als Monument historique geschützt.","h":"Seit dem 11. Jahrhundert war Abbans-Dessus der Mittelpunkt einer Herrschaft, die der Familie Jouffroy gehörte. Zusammen mit der Franche-Comté gelangte der Ort durch den Frieden von Nimwegen 1678 an Frankreich.","w":"https://de.wikipedia.org/wiki/Schloss_Abbans-Dessus"},"ch-Q2241090":{"n":"Schloss Fréfossé","c":"Schloss in Frankreich","r":"Das Schloss Fréfossé, seltener auch Schloss Le Tilleul genannt, steht etwa 1,5 Kilometer südlich von Étretat in der französischen Ortschaft Le Tilleul im Département Seine-Maritime in der Normandie. Seine Wurzeln sind in einer mittelalterlichen Burg des 14. Jahrhunderts zu suchen. Das Anwesen befindet sich seit 1998 in Privatbesitz und kann nicht besichtigt werden.","h":"Galehaut de Saâne errichtete 1374 am Ort des heutigen Schlosses die erste befestigte Burganlage der Region. Gegen Ende des Hundertjährigen Krieges kam sie gemeinsam mit der Seigneurie Fréfossé an die Familie de Pelletot. Für 1452 ist Jehan de Pelletot als Besitzer verzeichnet. 1494 war die Anlage unter dem Namen Clos de Saint-Louis bekannt. Francoise de Pelletot heiratete um 1611 Antoine Doullé, Seigneur de Gerpouville, und brachte die Burg an die Familie ihres Mannes. Als Anne Doullé Jacques Emar Compoinct, Seigneur de Boulhard, ehelichte, wechselte Fréfossé erneut den Besitzer. Die alte Burg wurde abgerissen und in den 1770er Jahren durch einen Neubau im Stil des klassizistischen Barocks ersetzt. Lediglich ein Taubenturm blieb von der Vorgängeranlage erhalten. Annes Tochter brachte das Schloss 1786 in ihre Ehe mit dem Vicomte Toussaint Hocquart. Während der Französischen Revolution wurde das Schloss 1789 von dem berühmt, berüchtigten Bataillon Montargis besetzt. Auch 1800 waren auf dem Areal – wie schon 1779 – Soldaten stationiert. Der letzte männliche Spross der Familie, der Baron Édouard Armand Hocquart, war nicht nur ab 1814 Bürgermeister von Le Tilleul, sondern auch Kammerherr der französischen Könige Ludwig XVIII. und Karl X. Er veräußerte das Schloss Fréfossé 1825, um mit dem Erlös den Kauf des Schlosses Valmont zu finanzieren. Neuer Eigentümer wurde Miximilien Fiquet, Bürgermeister von Criquetot-l’Esneval, von dem es 1849 Félix Val(l)ois erwarb, ein reicher Händler aus Rouen. Der neue Eigentümer ließ das damalige Gebäude zwischen 1850 und 1870 verändern und erhöhen. Nach seinem Tod kaufte es Ernest Dubosc, ein Industrieller aus Le Havre. Er ließ das Anwesen vor 1893 um zwei mächtige Rundtürme ergänzen. Seine Familie blieb bis in das 20.","w":"https://de.wikipedia.org/wiki/Schloss_Fr%C3%A9foss%C3%A9"},"ch-Q1747134":{"n":"Oedenburg","c":"Burg in Frankreich","r":"Die Oedenburg ist eine wenige hundert Meter westlich der Hohkönigsburg gelegene Ruine einer Höhenburg im elsässischen Orschwiller und bildet mit ihr gemeinsam eine Burgengruppe.","w":"https://de.wikipedia.org/wiki/Oedenburg_(Elsass)"},"ch-Q1764941":{"n":"Schloss Pange","c":"Schloss in Frankreich","r":"Schloss Pange ist ein Herrenhaus aus dem 18. Jahrhundert in der französischen Gemeinde Pange in Lothringen.","h":"Zwischen 1720 und 1756 errichtete Jean-Baptiste Thomas Marquis de Pange das Haus anstelle einer mittelalterlichen Festung. Bereits 1626 wurden seine Vorfahren von Karl IV. von Lothringen in den Adelsstand erhoben. 1766 wurde er schließlich von Stanislaus I. Leszczyński zum Markgrafen ernannt. Im Laufe seiner Geschichte beherbergte das Schloss bekannte Persönlichkeiten, darunter Napoleon III. und Wilhelm I. Nach dem Zweiten Weltkrieg wurde das Schloss zu einem Kinderheim, das jedoch 1983 geschlossen wurde. Die Familie de Pange erhielt das Schloss zurück und renovierte es umfassend. Große Teile des Schlosses stehen unter Denkmalschutz und wurden 1990 zum Monument historique erklärt.","w":"https://de.wikipedia.org/wiki/Schloss_Pange"},"ch-Q1819254":{"c":"Burg in Frankreich"},"ch-Q1818456":{"c":"Burg in Frankreich"},"ch-Q2137176":{"c":"Burg in Frankreich"},"ch-Q2121153":{"c":"Burg in Frankreich"},"ch-Q2132248":{"c":"Burg in Frankreich"},"ch-Q2150238":{"c":"Schloss in Frankreich"},"ch-Q2240520":{"n":"Schloss Champigny","c":"Schloss in Frankreich","r":"Das Schloss Champigny, von dem nur die Wirtschaftsgebäude und die Stiftskapelle erhalten sind, gehört zur französischen Gemeinde Champigny-sur-Veude im Département Indre-et-Loire in der Region Centre-Val de Loire. Nachdem die Kapelle bereits 1911 als Monument historique unter Denkmalschutz gestellt worden war, folgte im September 1945 die Aufnahme der Wirtschaftsgebäude in die französische Denkmalliste.","w":"https://de.wikipedia.org/wiki/Schloss_Champigny"},"ch-Q2240685":{"n":"Schloss Durtal","c":"Schloss in Frankreich","r":"Schloss Durtal liegt in der Stadt Durtal im Département Maine-et-Loire in der Region Pays de la Loire in Frankreich.","w":"https://de.wikipedia.org/wiki/Schloss_Durtal"},"ch-Q2240741":{"n":"Schloss Effiat","c":"Schloss in Frankreich","r":"Das Schloss Effiat befindet sich in der gleichnamigen Gemeinde Effiat im Département Puy-de-Dôme in der Region Auvergne-Rhône-Alpes. Die Anlage wurde am 16. April 1942, am 6. Juni 1980 und am 10. März 2004 als Monument historique eingestuft.","h":"1557 verkauften Antoine und Françoise de Neuville, Bruder und Schwester, an Gilbert I Coëffier (1510–1564) und Bonne Ruzé de Beaulieu († 1609), seine Ehefrau, ein von Gräben umgebenes Stück Land mit einem Turm, einem Haus und Pferdeställen aus dem 14. Jahrhundert. Die neuen Besitzer erbauten ein Herrenhaus, den weißverputzten heutigen Haupttrakt von Schloss Effiat. Ihr Enkel, Antoine Coëffier de Ruzé (ca. 1581–1632), späterer Marquis und Maréchal d’Effiat, erbte das Herrenhaus 1610, im Jahr seiner Heirat mit Marie de Fourcy († 1670). Als Antoine Coëffier de Ruzé, der ein Freund Kardinal Richelieus war, 1625 Finanzberater Ludwigs XIII. wurde, riss er mit Unterstützung seines Onkels Martin Ruzé und mit dessen Vermögen die meisten alten Strukturen ab und erweiterte das mit Schulden belastete Herrenhaus zu einem modernen Schloss, dessen Bauzeit zwischen 1626 und 1628 lag – die dafür abgerissene Kirche Saint-Blaise wurde zugleich an anderer Stelle wiedererrichtet. Für die später weithin berühmte Parkanlage kaufte Ruzé den umliegenden Bewohnern Land ab. Ruzé beauftragte die Architekten Jacques Lemercier und Clément Métezeau sowie den königlichen Gärtner André Mollet mit der Errichtung des Schlosses, des Gartens sowie der Siedlung Effiat. Noch während der Bauzeit stieg Ruzé politisch auf: im Jahr 1627 erhob Ludwig XIII. Ruzés Besitzungen zum Marquisat und ernannte ihn 1631 zum Marschall von Frankreich. 1627 ließ er auf seinem Grund ein Kolleg des erst 1611 von Pierre de Bérulle gegründeten Französischen Oratoriums eröffnen, in dem zwölf Edelmänner aus seinem Marquisat in der Ordensarbeit unterwiesen werden sollten. Ludwig XIV. bestätigte diese Gründung und sprach ihr zwölf Stipendien zu. Ludwig XVI.","w":"https://de.wikipedia.org/wiki/Schloss_Effiat"},"ch-Q2968537":{"c":"Burg in Frankreich"},"ch-Q2969801":{"c":"Burg in Frankreich"},"ch-Q2969802":{"c":"Schloss in Frankreich"},"ch-Q2968546":{"n":"Schloss Bessonies","c":"Schloss in Frankreich","r":"Das Schloss Bessonies ist ein kleines Schloss in der Gemeinde Bessonies im Département Lot der Region Okzitanien, 12 Kilometer vom Lac du Tolerme und 37 Kilometer von Figeac entfernt. Es besteht aus einem Logis mit zwei Rundtürmen an den südlichen Ecken und ist von einem zwei Hektar großen Park umgeben.","h":"Das Schloss wurde im Jahr 1555 erstmals erwähnt und war Stammsitz der Herren von Bessonies, einer Adelsfamilie, die neben der Seigneurie Bessonies noch zahlreiche weitere Güter in der Quercy und der Rouergue besaß. 1730 ließ René de Bessonies das Stammschloss seiner Ahnen instand setzen. Im Jahre 1789 befand es sich im Besitz von Jean Joseph René (I.) de Bessonies, königlichem Gouverneur von Figeac, der zur Hinrichtung unter der Guillotine verurteilt worden war, aber durch den Sturz von Robespierre der Enthauptung entkommen konnte. Sein Schloss war jedoch während seiner Haft geplündert und verwüstet worden. Jean Josephs Sohn Ambert war während der Französischen Revolution emigriert, um der Verfolgung durch Revolutionäre zu entgehen. Nach seiner Rückkehr nach Frankreich heiratete er die Cousine der Frau von Michel Ney, Maréchal d’Empire. Weil Ney während der Herrschaft der Hundert Tage wieder in Napoleons Dienste getreten war, wurde er nach dessen endgültiger Abdankung und der Rückkehr König Ludwigs XVIII. wegen Hochverrats gesucht und fand bei seinen Verwandten im Schloss Bessonies Zuflucht. Dort wurde er am 3. August 1815 verhaftet, zunächst darin festgesetzt und dann nach Paris gebracht, wo er letztendlich hingerichtet wurde. Ambert de Bessonies Sohn Jean Joseph René (II.) musste seinen Abschied aus königlichen Diensten nehmen und wurde auf seine Güter verbannt. Er starb kinderlos im Jahr 1871 und vermachte all seinen Besitz seinem Neffen Edgard d’Arnaldy-Destroa, einem Sohn seiner Schwester Marie Charlotte Louise. Schließlich erbte dessen älteste Tochter Eugénie Julie Aglaé den Besitz in Bessonies.","w":"https://de.wikipedia.org/wiki/Schloss_Bessonies"},"ch-Q2969839":{"n":"Schloss Maudétour","c":"Schloss in Frankreich","r":"Das Schloss Maudétour steht in Maudétour-en-Vexin, einer französischen Gemeinde im Département Val-d’Oise in der Region Île-de-France, 55 Kilometer nordwestlich von Paris. Es wurde im 17./18. Jahrhundert errichtet und steht seit dem 11. April 1947 als Monument historique auf der Liste der Baudenkmäler in Frankreich. Das Schloss ist von einem Park umgeben, der nach Plänen von André Le Nôtre angelegt wurde und ebenfalls als Monument historique klassifiziert ist.","h":"Der Bau des heutigen Schlossgebäudes begann im 17. Jahrhundert an der Stelle eines vollständig verschwundenen Vorgängerbaus, der Manoir des Rubentel genannt wurde. Auftraggeber für den Neubau waren Charles de Rancher und seine Frau Élisabeth de Blagny, die eine symmetrische Dreiflügelanlage errichten lassen wollten. Zunächst wurde aber nur der Südwestflügel des Schlosses realisiert. Ihm wurde im 18. Jahrhundert ein zweiter Trakt im Südosten angefügt, der später einmal der zentrale Teil des Schlosses werden sollte. Ein Nachfahre des Bauherrn, Antoine de Rancher, Ratgeber des Königs und Lieutenant des Berry, fügte der Anlage eine Schlosskapelle hinzu, die 1738 geweiht wurde. Sie diente lange Zeit auch als Pfarrkirche des Orts. Nach mehreren Besitzerwechseln im 20. Jahrhundert, kam die Anlage an ihre heutigen Besitzer, die von 2006 bis 2009 umfangreiche Renovierungsarbeiten durchführen ließen, um anschließend im Schlossgebäude Gästezimmer einzurichten. Zusätzlich können Räume in den ehemaligen Wirtschaftsgebäuden für Feiern und Veranstaltungen gemietet werden.","w":"https://de.wikipedia.org/wiki/Schloss_Maud%C3%A9tour"},"ch-Q2969848":{"c":"Schloss in Frankreich"},"ch-Q2969868":{"c":"Burg in Frankreich"},"ch-Q2969863":{"c":"Burg in Frankreich"},"ch-Q2969876":{"n":"Schloss Messilhac","c":"Schloss in Raulhac, Département Cantal, Auvergne-Rhône-Alpes, Frankreich","r":"Das Schloss Messilhac ist eine als Monument historique klassifizierte Burg- und Schlossanlage in der französischen Gemeinde Raulhac im Département Cantal der Region Auvergne-Rhône-Alpes. Das Schloss liegt in der historischen Region des Carladès auf einem bewaldeten, isolierten Felsvorsprung inmitten eines Bergkranzes oberhalb des Goul-Tals. Es steht seit dem 16. März 1921 unter Denkmalschutz.","h":"Die Anlage wurde gegen Ende des 13. Jahrhunderts von einem Mitglied der Familie Bénavent auf einem strategisch günstigen Felsplateau als erste feste Wohnburg (maison forte) errichtet, um das Goul-Tal zu überwachen. Dieses Tal stellte im Mittelalter einen wichtigen Durchgangsweg in die Haute-Auvergne von Süden her dar. Das Anwesen wurde als Mitgift von Marguerite de Bénavent-Rodez in ihre Ehe mit Jean de Montamat eingebracht. Zu dieser Zeit bestand die Burg im Wesentlichen aus einem wehrhaften, romanischen Donjon (dem heutigen Westturm), der von einer Ringmauer mit fünf bis sieben Verteidigungstürmen und einem trockenen Burggraben umgeben war. Im Jahr 1414 verwüstete Renaud de Murat, der im Konflikt mit Bernard VII. d’Armagnac lag und diesem die Gefolgschaft als Vizegraf von Carlat verweigerte, das Carladès. Dabei nahm er die Burgen Messilhac, Polminhac und Montamat ein und griff die Festung Carlat an. Nach seinem Tod im Jahr 1418 wurden die Besitztümer wieder zurückgegeben. Im 15. Jahrhundert folgten bedeutende Erweiterungen: Es entstand der markante Ostturm im Stil der Gotik mit prägenden Kreuzgewölben, im Gegensatz zu den Flachdecken des älteren Westturms. Auch der zentrale Mitteltrakt wurde in dieser Epoche errichtet, war jedoch an seiner Südfassade zunächst nur von Schießscharten durchbrochen. Der Zugang zum Schloss erfolgte damals von der Nordseite aus auf mittlerer Etage, geschützt durch eine zinnenbewehrte Festungsmauer, die von kleinen Ecktürmen flankiert war und den Ehrenhof umschloss. Der Westturm wurde in dieser Zeit ebenfalls erhöht und mit Maschikulis ausgestattet, um die Symmetrie und Wehrhaftigkeit zu verbessern. Davon zeugt eine gotische Schlosskapelle im fünften Stockwerk des Turms. Als im 16.","w":"https://de.wikipedia.org/wiki/Schloss_Messilhac"},"ch-Q2969881":{"n":"Schloss Meursault","c":"Schloss im Département Côte-d’Or, Frankreich","r":"Das Schloss Meursault am südöstlichen Ortsrand von Meursault, einer französischen Gemeinde im Département Côte-d’Or in der Region Bourgogne-Franche-Comté, hat seinen Ursprung im 11. Jahrhundert. Das von einem Park umgebene Schloss besteht aus dem Hauptgebäude, links der Orangerie und rechts der Cuverie, dem Bottichraum. Vom 12. bis zum 16. Jahrhundert wechselte das Schloss während der Kämpfe zwischen den Herzögen von Burgund und den Königen von Frankreich häufig den Besitzer. Nach der Französischen Revolution hat das Schloss ebenso eine wechselhafte Epoche erlebt.","h":"Im Jahr 1645 wurde das Anwesen, Eigentum von Pierre Legoux de la Berchère der Seignierie von Mazeray, an Herrn la Rochepot verkauft. 1662 ging das Schloss in den Besitz von François de Raigecourt und seiner Frau Béatrice de Beaufremont über. 1666 kam es in die Hände von Pierre de Blancheton, Rechtsanwalt am burgundischen Parlament. Das Schloss verblieb bis zur Französischen Revolution im Besitz der Familie. Während dieser Zeit wurde das Schloss beschlagnahmt und an den Kaufmann Pierre Jobard aus Beaune verkauft. Seine Tochter Jeanne-Marie Philippine erbte das Anwesen und heiratete am 21. Juli 1818 Charles Serre, einen Nachkommen von Kaufleuten aus Châlon. Im 19. Jahrhundert wurde das Anwesen unter der Leitung der Familie Serr, mit großen architektonischen Veränderungen erweitert und das Weingut erheblich vergrößert. Durch Erbschaft ging das Schloss in den Besitz des Grafen von Moucheron über, das er seinem ältesten Sohn Etienne hinterließ. 1973 wurde das Anwesen restauriert und war im Besitz der Familie Boisseaux. Seit Dezember 2012 gehört das Schloss Meursault sowie das Schloss Marsannay-Côte de Nuits (mit 34 Hektar Rebfläche) der Familie Halley und steht unter der Leitung von Olivier Halley. Direktor des Anwesens ist Stéphane Follin-Arbelet. Das Château de Meursault, mitten in den Weinbergen gelegen, umfasst 65 Hektar Weinberge (Chardonnay für die Weißen und Pinot Noir für die Roten) in der Côte de Beaune. Seine berühmten Weine, sowie die sehr großen Weinkeller aus dem 12., 14. und 16. Jahrhundert machen das Schloss zu einem eindrucksvollen Weingut Burgunds. Unter dem Schloss, in dem von Mönchen aus Citeaux angelegten Kellergewölben, lagern unzählige Flaschen Grand Crus und Premier Crus, sowie eine Menge von Fässern des Marc de Bourgogne.","w":"https://de.wikipedia.org/wiki/Schloss_Meursault"},"ch-Q2969894":{"c":"Burg in Frankreich"},"ch-Q2970179":{"n":"Schloss Parentignat","c":"Schloss im Département Puy-de-Dôme, Auvergne-Rhône-Alpes, Frankreich","r":"Das Schloss Parentignat ist eine barocke Schlossanlage in der französischen Gemeinde Parentignat im Département Puy-de-Dôme der Region Auvergne-Rhône-Alpes. Aufgrund seiner architektonischen Pracht wird das Anwesen auch als das „kleine Versailles der Auvergne“ bezeichnet. Es beherbergt mit der Sammlung Georges de Lastic eine der bedeutendsten privaten Kollektionen französischer Meister des 17. und 18. Jahrhunderts. Das Bauwerk steht seit dem 5. Juni 1972 als Monument historique unter Denkmalschutz.","h":"In der Spätrenaissance war das damals noch Parentignac genannte Anwesen eine klassische, wehrhafte Festungsanlage am Rande des Dorfes. Der im ausgehenden 16. Jahrhundert von Claude Chastillon dokumentierte Bau präsentierte sich als ein geschlossenes Quadrilateral, das an den Ecken von vier massiven Wehrtürmen flankiert war. Die Wurzeln der vormaligen mittelalterlichen Festung reichen bis in das 11. Jahrhundert zurück, als die Anlage auf einem markanten Felssporn (piton rocheux) als Wiege der Herren von Lastic errichtet wurde. Am 23. Oktober 1707 erwarben Jean-Antoine de Lastic, Prior von Bredons sowie Vikar von Murat, und sein Neffe François II. de Lastic, Marquis de Sieujac und Graf von Sieujac, die damals stark vernachlässigte Anlage für 45.000 Livres von den Erben des Maximilien de Sommyèvre. François II. hatte zuvor im Spanischen Erbfolgekrieg gekämpft und 1706 eine Ehe mit einer vermögenden Dame de la Roche-Aymon geschlossen, deren Bruder später Erzbischof von Reims und Großalmosenier von Frankreich wurde. Nach dem Tod des Priors wurde Anne-François II. de Lastic zum alleinigen Eigentümer und leitete eine tiefgreifende Transformation ein. Zwischen 1710 und 1714 kaufte er systematisch das umliegende Dorf auf, das sich bis dahin dicht an die Burgmauern drängte, und schloss hierzu mehr als 170 Kaufverträge ab. Die ursprüngliche Burganlage aus dem 15. Jahrhundert wurde dabei stark modifiziert und in den linken Flügel des neuen Schlosses integriert, wobei zwei der vier alten Ecktürme erhalten blieben. Um die beiden entstehenden Seitenflügel symmetrisch miteinander zu verbinden, wurde zeitgleich an der Ostseite das zentrale Hauptgebäude (Corps de logis) errichtet, dessen Schaufassade von einem markanten Dreiecksgiebel bekrönt wird. Nach dem Tod von Anne-François II.","w":"https://de.wikipedia.org/wiki/Schloss_Parentignat"},"ch-Q2971704":{"c":"Schloss in Frankreich"},"ch-Q2971753":{"c":"Burg in Frankreich"},"ch-Q2971765":{"c":"Burg in Frankreich"},"ch-Q3286313":{"c":"Burg in Frankreich"},"ch-Q3286388":{"c":"Schloss in Frankreich"},"ch-Q3286396":{"c":"Schloss in Frankreich"},"ch-Q3325349":{"c":"Schloss in Frankreich"},"ch-Q3329784":{"n":"Musée de l’Armagnac","c":"Museum in Frankreich","r":"Das Musée de l’Armagnac ist ein Museum in Condom im französischen Département Gers. Es widmet sich überwiegend der Herstellung des Armagnac, der ältesten bekannten französischen Spirituose.","h":"Das 1848 gegründete Museum präsentierte ursprünglich eine von Napoleon III. gestiftete Gemäldesammlung und wurde sukzessive zu einem Mehrspartenhaus mit einer volkskundlichen und einer naturwissenschaftlichen Abteilung ausgebaut. Auf Initiative des Departements-Archivars Henri Polge wurde es 1954 im gotischen Kreuzgang der Kathedrale Saint-Pierre untergebracht und neu ausgerichtet. Seither liegt der Schwerpunkt auf der Geschichte der Produktion von und dem Handel mit Armagnac. Die Stadt Condom war seit der Schiffbarmachung der Baïse 1839 ein wichtiges Zentrum des Armagnac-Exports. Seit 1981 befindet sich das Museum in einem Nebengebäude des ehemaligen Bischofspalastes.","w":"https://de.wikipedia.org/wiki/Mus%C3%A9e_de_l%E2%80%99Armagnac"},"ch-Q3360841":{"n":"Palais Carnolès","c":"Palast in Menton (Alpes-Maritimes), Frankreich"},"ch-Q3360899":{"c":"Palast in Frankreich"},"ch-Q2967956":{"c":"Burg in Frankreich"},"ch-Q2967960":{"c":"Schloss in Frankreich"},"ch-Q2967965":{"c":"Burg in Frankreich"},"ch-Q2967987":{"c":"Burg in Frankreich"},"ch-Q2967992":{"c":"Schloss in Frankreich"},"ch-Q2970069":{"n":"Schloss Mortiercrolles","c":"Schloss in Frankreich","r":"Das Schloss Mortiercrolles in Saint-Quentin-les-Anges im Département Mayenne ist ein Gebäude im Stil Ludwigs XII und befindet sich einen Kilometer südöstlich des Ortes.","h":"Die Châtellenie wurde – einem Memorandum aus dem 18. Jahrhundert folgend –, zusammen mit der Châtellenie de l’Hôtellerie de Flée um 1500 von Ludwig XII. zur Baronie erhoben, obwohl der Titel Baronie erst Mitte des 17. Jahrhunderts auftaucht. Châtelais, Saint-Quentin, Mée und Le Bourgneuf ging es ebenso. Die Baronie unterstand dem König durch das Herzogtum Anjou. Maurice de Remefort, Seigneur de Remefort in Saint-Aignan-de-Gennes, ⚭ Agnès du Melle, Dame d’Angerville Isabeau de Remefort, Dame de Remefort et de Mortiercrolles, deren Tochter; ⚭ Amaury I. de Clisson, (X 1347 in der Schlacht von La Roche-Derrien (Haus Clisson)) Amaury II. de Clisson, 1382 bezeugt, Seigneur de Remefort, deren Sohn Isabeau de Clisson, 1413 bezeugt, dessen Schwester; ⚭ 1351 Renaud d’Ancenis († um 1384) Isabeau d’Ancenis, Dame de l’Isle-d’Aurillé et de Remefort, deren Tochter; ⚭ Bertrand du Guesclin, Seigneur de La Morelière, Vetter des Connétable Bertrand du Guesclin Catherine du Guesclin, Dame du Verger († nach 1461), deren Tochter; ⚭ 1405 Charles I. de Rohan († 1438), Seigneur de Guéméné (Haus Rohan) Louis I. de Rohan († 1457), Seigneur de Guéméné, deren Sohn; ⚭ Marie de Montauban, Dame de Montauban-de-Bretagne et de Landal Pierre I. de Rohan († 1513), Seigneur de Gié, Marschall von Frankreich, deren Sohn; ⚭ Françoise de Penhoët Charles de Rohan († 1528), Seigneur de Gié, deren Sohn; ⚭ Giovanna Sanseverino François de Rohan († 1559), Seigneur de Gié, deren Sohn; ⚭ Catherine de Silly, Comtesse de Rochefort Léonore de Rohan († 1583), Comtesse de Rochefort, deren Tochter; ⚭ Louis VI.","w":"https://de.wikipedia.org/wiki/Schloss_Mortiercrolles"},"ch-Q2970085":{"c":"Burg in Frankreich"},"ch-Q2970088":{"c":"Burg in Frankreich"},"ch-Q2970095":{"n":"Schloss Méry-sur-Oise","c":"Burg in Frankreich","r":"Das Schloss Méry-sur-Oise liegt im Département Val-d’Oise, 30 Kilometer nördlich von Paris und gegenüber dem Malerdorf Auvers-sur-Oise am gegenüberliegenden Ufer der Oise.","w":"https://de.wikipedia.org/wiki/Schloss_M%C3%A9ry-sur-Oise"},"ch-Q2970099":{"c":"Schloss in Frankreich"},"ch-Q2970092":{"c":"Burg in Frankreich"},"ch-Q2970109":{"c":"Schloss in Frankreich"},"ch-Q2970116":{"c":"Burg in Frankreich"},"ch-Q2970113":{"c":"Burg in Frankreich"},"ch-Q2970134":{"c":"Burg in Frankreich"},"ch-Q2968552":{"c":"Burg in Frankreich"},"ch-Q2968563":{"c":"Schloss in Frankreich"},"ch-Q2968564":{"c":"Burg in Frankreich"},"ch-Q2968569":{"c":"Schloss in Frankreich"},"ch-Q2968596":{"c":"Burg in Frankreich"},"ch-Q2968625":{"c":"Schloss in Frankreich"},"ch-Q2968630":{"c":"Burg in Frankreich"},"ch-Q2968632":{"c":"Burg in Frankreich"},"ch-Q2968638":{"c":"Schloss in Frankreich"},"ch-Q2968664":{"c":"Burg in Frankreich"},"ch-Q2968671":{"c":"Burg in Frankreich"},"ch-Q2969554":{"c":"Burg in Frankreich"},"ch-Q2969562":{"c":"Schloss in Frankreich"},"ch-Q2969579":{"c":"Burg in Frankreich"},"ch-Q2969580":{"c":"Burg in Frankreich"},"ch-Q2969594":{"n":"Schloss La Tremoliere","c":"Schloss in Anglards-de-Salers, Département Cantal, Auvergne-Rhône-Alpes, Frankreich","r":"Das Schloss La Trémolière ist ein Schlossbau aus dem späten 16. und 17. Jahrhundert in der französischen Gemeinde Anglards-de-Salers im Département Cantal der Region Auvergne-Rhône-Alpes. Das Anwesen, das im Inneren eine kunsthistorisch bedeutende Serie von Spätrenaissance-Tapisserien beherbergt, wurde am 14. Oktober 1963 in das Zusatzverzeichnis der Monuments historiques aufgenommen; die Fassaden, Dächer, der Treppenturm sowie die getäfelten Salons im ersten und zweiten Obergeschoss wurden am 2. März 1981 als Monument historique klassifiziert.","h":"Das Lehen (Fief) La Trémolière ist seit dem 15. Jahrhundert urkundlich belegt und befand sich ursprünglich im Besitz der Familie de Tournemire, den Herren von Leybros. Vor dem Jahr 1592 erwarb Antoine de Vigier, ein wohlhabender Bürger aus Salers und Sohn des Herrn von Retortillade, das Anwesen von den Tournemire, um dort einen standesgemäßen Sitz für seine Familie zu begründen. Sein Sohn, Jacques-Antoine de Vigier, Herr von Prades und Loupiac sowie Mitherr von Saint-Christophe-les-Gorges, diente 1597 als Waffenrockträger des Marschalls d’Albret und nahm 1635 am Adelsaufgebot (Ban) der Region teil. Es wird angenommen, dass Jacques-Antoine de Vigier den Bau des heutigen Schlosses in Auftrag gab. Durch die Hochzeit seiner Tochter Catherine de Vigier am 24. September 1640 mit Jean de Monclar gelangte das Schloss in den Besitz der Familie de Montclar (oft auch Monclar geschrieben). Jean-Antoine de Montclar, Herr von Fournols und La Trémolière, vermählte sich im 17. Jahrhundert mit seiner Cousine Gilberte de Montclar. Diese brachte eine kostbare Serie von zehn großen Bildteppichen (Tapisseries de verdure) in die Ehe ein, die sie von ihren Großeltern geerbt hatte. Das Schloss verblieb über Generationen in der Familie, bis die Erbin Angélique de Montclar im Jahr 1795 Alexis Planchard de Cussac, den Unterpräfekten von Mauriac, heiratete. Im Jahr 1855 verkaufte deren Nachkommin Stéphanie Rongier gemeinsam mit ihrem Ehemann Augustin de Courboulès de Montjoly das Schloss an die Gemeinde Anglards-de-Salers, die das Gebäude fortan als Presbyterium (Pfarrhaus) für die lokale Kirchengemeinde nutzte. Als im Jahr 1903 im Zuge der strikten Trennung von Kirche und Staat in Frankreich die Nutzung als Pfarrhaus endete, inspizierten Gemeindevertreter das Gebäude.","w":"https://de.wikipedia.org/wiki/Schloss_La_Tr%C3%A9moli%C3%A8re"},"ch-Q2969629":{"c":"Burg in Frankreich"},"ch-Q2969633":{"c":"Schloss in Frankreich"},"ch-Q2971815":{"c":"Schloss in Frankreich"},"ch-Q2968694":{"c":"Burg in Frankreich"},"ch-Q2968698":{"c":"Burg in Frankreich"},"ch-Q2968715":{"c":"Burg in Frankreich"},"ch-Q2968730":{"n":"Schloss Cadillac","c":"Burg in Cadillac-sur-Garonne, Departement Gironde, Nouvelle-Aquitaine, Frankreich","r":"Das Schloss Cadillac ist ein Ende des 16. Jahrhunderts, Anfang des 17. Jahrhunderts erbautes Schloss der Herzöge von Épernon bei Cadillac-sur-Garonne im französischen Departement de Gironde (Neuaquitanien). Es ist ein sehr gut erhaltenes Schloss aus der Zeit Heinrichs IV. und ist ein Bauwerk aus dem Übergang der Spätrenaissance in den klassizistischen Barock. Das Anwesen gehört dem französischen Staat und ist öffentlich zugänglich. Es wird heute als Museum genutzt. Schloss, Wassergräben und der Garten bzw. der Park sind seit 1862 als Monument historique gelistet und durch Verordnung von 1956 als historisches Denkmal eingestuft worden. Das Tor zum Garten wurde 1965 gelistet.","h":"Das Château de Cadillac wurde auf Veranlassung von Jean Louis de Nogaret de La Valette, dem ersten Herzog von Épernon, errichtet. Die Entwürfe lieferten Pierre Souffron, Gilles de La Touche, Aguesse, und Pierre Biard. Dafür wurde der nordwestliche Teil der Siedlung von Cadillac abgebrochen und dem Erdboden gleichgemacht. Das Schloss wurde als geschlossener Flügelbau mit Eckpavillons bis 1634 errichtet. Die Flügel, die Pavillons und die umgebende Mauer wurden bereits im 18. Jahrhundert abgebrochen. Während der Französischen Revolution wurde das Schloss beschlagnahmt. Im 19. Jahrhundert wurde ein Frauengefängnis im Schloss eingerichtet. Bei einem Brand 1928 wurde das Gebäude erheblich geschädigt. 1951 wurde die Einrichtung geschlossen und an das Kulturministerium übergeben.","w":"https://de.wikipedia.org/wiki/Schloss_Cadillac"},"ch-Q2968733":{"n":"Schloss Caillac","c":"Burg in Vézac, Département Cantal, Auvergne-Rhône-Alpes, Frankreich","r":"Das Schloss Caillac ist eine als Monument historique geschützte Schlossanlage in der französischen Gemeinde Vézac im Département Cantal der Region Auvergne-Rhône-Alpes. Das Anwesen liegt im Tal der Cère in der historischen Region der Haute-Auvergne. Die Schlossgebäude wurden am 10. November 1997 in das Verzeichnis der Monuments historiques aufgenommen; die historische Parkanlage ist zudem als „Bemerkenswerter Park“ erfasst.","h":"Die Ursprünge des Lehens gehen auf das Spätmittelalter zurück. Im Jahr 1302 ist Bertrand de Calhac als Herr des Ortes belegt, der Abgaben an das Kloster in Aurillac leistete. Nach einer Zwischenphase unter dem Kapitän Thomas d’Orbec ging das Gut im Jahr 1483 durch Kauf an François I. Chaumeil (auch *Chaumeilh* geschrieben) über. Er war der Sohn des Baillis der Vizegrafschaft Murat, besaß ein Lizentiat der Rechte, diente als Stellvertreter des Gouverneurs der Auvergne und wurde 1486 von König Karl VIII. in den Adelsstand erhoben. Da seine eigenen Kinder keine Nachkommen zeugten, erbte sein Neffe und Patenkind François II. Chaumeil das Schloss. Dieser diente 1574 als königlicher Hauptmann und Gouverneur von Boulogne-sur-Mer sowie des Boulonnais. Aus seiner Ehe mit Hélène de Montamat ging als einzige Erbin die Tochter Marguerite de Chaumeil hervor. Sie vermählte sich um 1570 mit Antoine de Buisson, dem Baron von Bournazel, Seneschall und Gouverneur des Rouergue, wodurch das Schloss an die Familie de Buisson de Bournazel gelangte. Ihr gemeinsamer Sohn François de Buisson de Bournazel, der ebenfalls als Seneschall des Rouergue amtierte, verkaufte im Jahr 1657 die Hälfte der Ländereien von Caillac, die nach mehreren Zwischenstationen an die Familie de Boschâtel übergingen. Gaspard-Joseph de Boschâtel, der Erste Präsident des Presidialgerichts von Aurillac und Sohn einer geborenen de Scorailles, erwarb schließlich die gesamte Herrschaft Caillac, verstarb jedoch im Jahr 1742 kinderlos. Die Familie führte als Wappen einen goldenen Schlossturm auf schwarzem Grund (de sable au château d'or) mit der Devise *Musis et Armis* (Den Musen und den Waffen).","w":"https://de.wikipedia.org/wiki/Schloss_Caillac"},"ch-Q2968735":{"c":"Schloss in Frankreich"},"ch-Q2968738":{"c":"Schloss in Frankreich"},"ch-Q2968761":{"c":"Burg in Frankreich"},"ch-Q2968762":{"c":"Schloss in Frankreich"},"ch-Q2968766":{"c":"Schloss in Frankreich"},"ch-Q2971592":{"n":"Château des Évêques-du-Puy","c":"Burg in Frankreich","r":"Das Château des Evêques (Bischofschloss) in Monistrol-sur-Loire, Frankreich, hat seinen Ursprung im 13. Jahrhundert. Heute ist das Schloss ein kultureller Treffpunkt und ein bedeutendes historisches Monument der Region Haute-Loire. Im Laufe der Jahre hat es sich von einer mittelalterlichen Festung zu einem Ausstellungsort entwickelt, der Besuchern aus der Region eine Mischung aus Geschichte und Kultur bietet.","h":"Im Jahr 1270 erwarben die Bischöfe von Le Puy das Château des Evêques, das zu diesem Zeitpunkt als ein einfaches Gebäude in der Bilhardschlucht gelegen war. Das Schloss wurde zunächst von den Bischöfen von Le Puy genutzt und im 14. Jahrhundert näher an die Stadt Monistrol verlegt. Dort errichteten sie eine „Neue Burg“, die später im 18. Jahrhundert umfangreiche Umbauten erlebte. Nach den Religionskriegen wurde das Schloss zunehmend als „Lusthaus“ genutzt und erlebte eine Verschönerung mit Gärten und Parkanlagen. Heute sind nur noch Überreste des ursprünglichen Gebäudes vorhanden, doch die Geschichte des Schlosses lässt sich in den noch bestehenden Teilen und der gesamten Architektur nachvollziehen. Besonders auffallend sind die Türme des Schlosses, die das Gebäude prägen und einen imposanten Anblick bieten.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_des_%C3%89v%C3%AAques-du-Puy"},"ch-Q2971593":{"c":"Burg in Frankreich"},"ch-Q2970879":{"c":"Burg in Frankreich"},"ch-Q2970891":{"c":"Burg in Frankreich"},"ch-Q2970894":{"c":"Burg in Frankreich"},"ch-Q2970919":{"c":"Schloss in Frankreich"},"ch-Q2970920":{"c":"Schloss in Frankreich"},"ch-Q2970924":{"c":"Burg in Frankreich"},"ch-Q2970938":{"c":"Burg in Frankreich"},"ch-Q2970939":{"c":"Burg in Frankreich"},"ch-Q2969649":{"c":"Schloss in Frankreich"},"ch-Q2969662":{"c":"Burg in Frankreich"},"ch-Q2969666":{"c":"Schloss in Frankreich"},"ch-Q2969655":{"n":"Burg Largentière","c":"Burg in Frankreich","r":"Die Burg Largentière erhebt sich am höchsten Punkt der einstigen Ringmauer von Largentière, einem Ort im französischen Département Ardèche. Die Burg diente im Mittelalter dazu, die Siedlung und eine nahe gelegene Silbermine zu schützen. Die ursprünglich nur aus einem Donjon bestehende Anlage wurde im Laufe der Zeit immer wieder erweitert und verändert, ehe der Marquis de Brison sie im 18. Jahrhundert zu einem komfortablen Wohnsitz für seine Familie umbauen ließ. Von 1850 bis 1995 beherbergte sie ein Hospital. Die Burg steht seit dem 31. Mai 1927 als Monument historique unter Denkmalschutz und ist mit Ausnahme einiger Wochen im Sommer nicht für Besucher geöffnet.","h":"Die Wurzeln der Burg liegen in einer Befestigung, die der Bischof von Viviers im 12. Jahrhundert errichtete, um eine Siedlung samt einer in direkter Nachbarschaft liegenden Silbermine zu schützen. Deshalb sind die Geschichte von Burg und Ort Largentière stark miteinander verwoben. Die unter dem Namen Baume de Viviers bekannte Mine gehörte schon seit 1146 dem Bistum Viviers, allerdings waren die Silbervorkommen in der Region ein ewiger Zankapfel zwischen dem Bischof, lokalen Herrschern und dem Grafen von Toulouse. Graf Raimund V. von Toulouse musste zwischen 1186 und 1193 nach einem Schiedsspruch des Erzbischofs von Vienne auf alle Rechte an der Mine zugunsten des Bischofs von Vienne verzichten, aber nach seinem Tod 1194 weigerte sich sein Sohn Raimund VI., die Vereinbarung anzuerkennen. Er schaffte es, im Juli 1198 eine neue Übereinkunft auszuhandeln, in der er zwar den Bischof von Vienne als obersten Lehnsherrn der Mine und Siedlung anerkannte, im Gegenzug aber mit der Hälfte des castrums von Largentière belehnt wurde. Von der übrigen Hälfte vergab der Bischof jeweils ein Drittel an Aymar (auch Adhémar) de Poitiers und ein Mitglied der Familie Bermond dʼAnduze. Für sich behielt der Bischof nur das restliche Sechstel. Er ließ innerhalb der Stadtumwehrung einen Donjon errichten, von dem jedoch nicht klar ist, ob er noch im 12. Jahrhundert oder erst zu Beginn des 13. Jahrhunderts erbaut worden ist. Seine Existenz ist jedenfalls erst für das Jahr 1210 verbürgt. Er bildete den Kern der heutigen Burganlage. Der Name des Argentia bzw. Argentière genannten Wohnturms ging anschließend auf die Ortschaft über. Anfang des 13. Jahrhunderts errichtete Raimund VI. direkt neben dem bischöflichen Donjon einen eigenen Wehrturm, der seinen Nachbarn um zwei Meter in der Höhe überragte.","w":"https://de.wikipedia.org/wiki/Burg_Largenti%C3%A8re"},"ch-Q2970960":{"c":"Burg in Frankreich"},"ch-Q2970982":{"c":"Schloss in Frankreich"},"ch-Q2970994":{"c":"Burg in Frankreich"},"ch-Q2971002":{"n":"Schloss Villemont","c":"Burg in Frankreich","r":"Das Schloss Villemont liegt am Ortsrand der französischen Gemeinde Vensat im Département Puy-de-Dôme der Region Auvergne-Rhône-Alpes. Seit einem Brand im Jahr 1958 präsentierte sich die aus dem 16. Jahrhundert stammende Schlossanlage lange Zeit als Ruine. Der Wiederaufbau mittels Spenden begann Mitte der 1990er Jahre.","h":"Villemont war ursprünglich ein Landschloss von bescheidenem Ausmaß. Lediglich die Innenausstattung war standesgemäß prunkvoll-herrschaftlich. Das Anwesen war ab 1557 über mehrere Generationen hinweg im Besitz der Familie Veyny. Die Reihe wird von Michel de Veyny (Schatzmeister der Marine) angeführt, der jedoch nicht als Erstbesitzer gilt. Unter seinem Nachfahren Gilbert de Veyny wurde das Schloss nach 1740 erweitert. Belegt sind Umbauten zwischen 1748 und 1757. Nach Plänen von Philibert de l’Orme entstand in dieser Zeit der geschlossene Innenhof und der Westflügel des Schlosses. Der Westturm wurde abgerissen und wenige Meter westlich vom alten Standort neu aufgebaut. Es existiert eine Zeichnung, die den Grundriss des Schlosses zwischen 1745 und 1748 – also noch vor der Erweiterung – erkennen lässt. Als Vorlage dafür diente der Atlas de Trudaine, der zwischen 1745 und 1780 herausgegeben wurde. Die Arbeiten endeten 1757 mit der Trockenlegung des Sumpflandes um das Schloss. Von 1865 bis 1885 erfolgte eine Restaurierung durch den Schlossherren L. J. Maisniel.","w":"https://de.wikipedia.org/wiki/Schloss_Villemont"},"ch-Q2971015":{"n":"Schlosses von Villers-Cotterêts","c":"Burg in Frankreich"},"ch-Q2971029":{"c":"Schloss in Frankreich"},"ch-Q2968009":{"c":"Burg in Frankreich"},"ch-Q2968027":{"c":"Schloss in Frankreich"},"ch-Q2968032":{"c":"Burg in Frankreich"},"ch-Q2968037":{"c":"Schloss in Frankreich"},"ch-Q2968040":{"c":"Schloss in Frankreich"},"ch-Q2968044":{"c":"Burg in Frankreich"},"ch-Q2968042":{"n":"Burgruine Aillas","c":"Burg in Frankreich","r":"Die Burgruine Aillas ist die Ruine einer Ende des 13. Jahrhunderts erbauten Höhenburg in Aillas, einer französischen Gemeinde im Département Gironde in der Region Nouvelle-Aquitaine. Die Burgruine steht seit 1886 als Monument historique auf der Liste der Baudenkmäler in Frankreich.","w":"https://de.wikipedia.org/wiki/Burgruine_Aillas"},"ch-Q2968054":{"c":"Burg in Frankreich"},"ch-Q2968096":{"c":"Burg in Frankreich"},"ch-Q2970437":{"n":"Schloss Rosny-sur-Seine","c":"Schloss in Frankreich"},"ch-Q2970442":{"n":"Burg Rouillac","c":"Schloss in Frankreich","r":"Die aus dem 14. Jahrhundert stammende Burg Rouillac liegt in der Gemeinde Gimbrède im französischen Département Gers. Sie ist eine Burg des sogenannten „gascognischen Typs“. Manchmal findet man auch die Schreibweisen Rouilhac oder Roulhac.","h":"Die Herrschaft Rouillac wird erstmals 1280 erwähnt. Die Burg wurde von Bertrand de Goth, dem Vicomte de Lomagne, zwischen 1311 und 1323 erbaut und blieb im Besitz der Familie Goth bis zu deren Aussterben. Sie war Zentrum der gleichnamigen Herrschaft, die um 1600 zu einem Marquisat erhoben wurde. Die Marquis de Rouillac erbten 1662 das Herzogtum Èpernon. Das Schloss wurde 1987 in das Inventaire général du patrimoine culturel aufgenommen. Eine der von Jean-François Bladé gesammelten Schelmengeschichten, Les deux Moines, spielt auf der Burg Rouillac.","w":"https://de.wikipedia.org/wiki/Burg_Rouillac"},"ch-Q2970488":{"c":"Burg in Frankreich"},"ch-Q2970415":{"n":"Château de Romefort","c":"Burg in Frankreich"},"ch-Q2970504":{"c":"Burg in Frankreich"},"ch-Q2970510":{"c":"Burg in Frankreich"},"ch-Q2970809":{"c":"Burg in Frankreich"},"ch-Q2970841":{"n":"Château de Triadou","c":"Burg in Frankreich"},"ch-Q2970848":{"c":"Schloss in Frankreich"},"ch-Q2970853":{"c":"Schloss in Frankreich"},"ch-Q2970859":{"n":"Schloss Trélon","c":"Schloss in Frankreich","r":"Das Schloss Trélon, auch Schloss Merode genannt, ist ein Schloss im Kern der gleichnamigen französischen Gemeinde des Départements Nord, Region Hauts-de-France. Die Anlage ist seit über 450 Jahren Privateigentum der Familie Merode, die im 16. Jahrhundert durch Heirat in ihren Besitz kam.","h":"Seit dem 12. Jahrhundert gehörte Trélon der Familie Avesnes. Schon im Jahr 1147 wird ein Donjon des Gauthier d’Avesnes erwähnt. Diesen brachte Marie dʼAvesnes, die spätere Gräfin von Blois, 1225 gemeinsam mit der gleichnamigen Seigneurie in ihre Ehe mit Hugo I. von Châtillon. Johann II. von Châtillon vererbte die Burg bei seinem Tod im Jahr 1381 seinem unehelichen Sohn Jean de Blois aus der Beziehung mit Isabeau d’Isberghes. Nach dem Bericht des Chronisten Jean Molinet überfielen Philipp von Kleve-Ravenstein und seine Soldaten, die während des Burgundischen Erbfolgekriegs auf Seiten Marias von Burgund standen, Trélon im Jahr 1478 und setzen den Burgherrn, der im Dienste des französischen Königs Ludwig XI. stand, in Mons fest. Er musste ein hohes Lösegeld zahlen, ehe er wieder freigelassen wurde. Dies blieb nicht der einzige Angriff, den die Anlage im 15. und 16. Jahrhundert erlebte: 1543 griffen Truppen des Königs Franz I. die Burg an, 1552 waren es Soldaten unter dem Kommando des Connétable von Frankreich, Anne de Montmorency. Nur zwei Jahre später belagerten Antoine de Bourbon, duc de Vendôme sowie der französische Marschall Jacques d’Albon, seigneur de Saint-André die Anlage 1554 und zerstörten sie teilweise, weil nach Ansicht der französischen Seite dort feindliche Soldaten untergebracht gewesen seien, die Franzosen überfielen und ausraubten (mettre à désolation un fort chasteau appelé Trélon, garny de grand nombre de soldats ennemis faisans maintes destrousses et volleries sur les Français). Die Familie de Blois starb im 16. Jahrhundert im Mannesstamm aus, und so brachte die Erbtochter Louise de Blois Seigneurie und Burg durch ihre Heirat 1562 mit Louis de Merode an die Familie ihres Mannes, welche die Anlage zu Beginn des 17. Jahrhunderts wiederaufbaute.","w":"https://de.wikipedia.org/wiki/Schloss_Tr%C3%A9lon"},"ch-Q2188774":{"c":"Burg in Frankreich"},"ch-Q2201602":{"c":"Burg in Frankreich"},"ch-Q2237070":{"c":"Burg in Frankreich"},"ch-Q2238952":{"c":"Schloss in Frankreich"},"ch-Q2242938":{"n":"Schloss Plaix","c":"Schloss in Frankreich","r":"Das Schloss Plaix gehört zur Gemeinde Saint-Hilaire-en-Lignières im französischen Département Cher und liegt nahe dem Arnon an der von Lignières kommenden D65. Das kleine Wasserschloss steht seit November 1995 in Teilen als Monument historique unter Denkmalschutz und beherbergt ein Volkskundemuseum, das in regelmäßigen Abständen Wechselausstellungen organisiert. Besitzer ist die „groupe folklorique des Thiaulins de Lignières“.","w":"https://de.wikipedia.org/wiki/Schloss_Plaix"},"ch-Q2633925":{"c":"Burg in Frankreich"},"ch-Q2740950":{"c":"Schloss in Frankreich"},"ch-Q2745671":{"c":"Burg in Frankreich"},"ch-Q2745725":{"c":"Schloss in Frankreich"},"ch-Q2784457":{"c":"Burg in Frankreich"},"ch-Q2795436":{"c":"Burg in Frankreich"},"ch-Q2803961":{"c":"Schloss in Anglards-de-Salers, Département Cantal, Auvergne-Rhône-Alpes, Frankreich"},"ch-Q2799806":{"n":"Schloss Arthies","c":"Schloss in Frankreich","r":"Das Schloss Arthies, auch Manoir des Tourelles oder Château des Tourelles genannt, steht in Arthies, einer französischen Gemeinde im Département Val-d’Oise in der Region Île-de-France. Das Bauwerk am Ortsausgang Richtung Mantes-la-Ville wurde in der ersten Hälfte des 15. Jahrhunderts errichtet und steht seit Januar 1948 als Monument historique auf der Liste der Baudenkmäler in Frankreich.","h":"Das Schloss erhielt seinen Namen von dem Waldgebiet Bois d’Arthies, das ein königliches Jagdrevier war. Entsprechend sind die Wurzeln des Schlosses auch in einem Jagdschloss zu finden. Das Gebiet gehörte zu einer Seigneurie, die im 14. und 15. Jahrhundert im Besitz der Familie Théméricourt war. Um 1430 ließ sie an der Stelle einer Burg ein neues Gebäude bauen. Die Erbin der Familie verkaufte den Besitz 1490 an Bertin de Silly de La Roche-Guyon, maître d’hôtel des französischen Königs Ludwig XI. Bertin ließ die Anlage Ende des 15. oder Anfang des 16. Jahrhunderts umbauen sowie erweitern und gab ihr damit im Wesentlichen die heutige Gestalt. Die Familie Silly wurde von der Familie La Rochefoucauld beerbt, deren Güterverwaltung sich bis zum Ende des Ancien Régimes im Schloss befand. In den 1950er Jahren und erneut in den 1980er Jahren führte die Besitzerfamilie White umfassende Restaurierungsmaßnahmen an der erhaltenen Bausubstanz durch. Die heutigen Eigentümer, Corinne und Hugues Flochel, öffnen ihr Schloss für Besuchergruppen und am Tag des offenen Denkmals.","w":"https://de.wikipedia.org/wiki/Schloss_Arthies"},"ch-Q2804460":{"c":"Burg in Frankreich"},"ch-Q2883480":{"c":"Burg in Frankreich"},"ch-Q2887167":{"c":"Schloss in Frankreich"},"ch-Q2900792":{"c":"Burg in Frankreich"},"ch-Q2913406":{"c":"Burg in Frankreich"},"ch-Q2969171":{"c":"Burg in Frankreich"},"ch-Q2243824":{"n":"Schloss Vault-de-Lugny","c":"Schloss in Frankreich","r":"Das Schloss Vault-de-Lugny ist ein Wasserschloss im Süden der französischen Gemeinde Vault-de-Lugny etwa 3,5 Kilometer westlich von Avallon in der Region Burgund.","h":"Archäologische Forschungen haben ergeben, dass der Standort des heutigen Schlosses bereits von den Galliern besiedelt wurde. Die Wurzeln der heutigen Anlage reichen jedoch nur bis in das Jahr 1120 zurück. An einer Furt des Flusses Cousin errichtete die Familie Jocelin d’Arcy während des 13. Jahrhunderts eine erste, einfache Wehranlage, die auf der einen Seite durch den Fluss geschützt und auf den anderen Seiten durch breite und tiefe Wassergräben umgeben war. Zusätzlichen Schutz bot eine Ringmauer, die in Teilen auch heute noch das Schlossareal umgibt. Die Burg kam um 1300 an die Familie de Toucy, die bis in die Mitte des 15. Jahrhunderts Besitzerin blieb. Sie errichtete den mehrgeschossigen Wohnturm, der heute noch existiert. Die damalige Anlage wurde während des Hundertjährigen Krieges fast vollständig zerstört. 1446 kam die Seigneurie samt der Burg durch Kauf an Guy de Jaucourt, dessen Familie während des 16. Jahrhunderts die heutige Schlossanlage errichten ließ. Mit dem Absolutismus kam der Niedergang der Burg als Verteidigungsanlage und Kontrollposten im Morvan. Fortan diente sie als schlossähnliche Sommerresidenz lokaler Adelsgeschlechter. Teile der Mauern wurden niedergelegt und an ihrem Standort ein 15 Hektar umfassender Landschaftsgarten mit heute altem Baumbestand angelegt. Nach der Französischen Revolution verfiel die Anlage zusehends. Der ehemalige Donjon steht seit März 1971 als Monument historique unter Denkmalschutz. Seit 1986 ist nach aufwändiger Restaurierung ein luxuriöses Hotel im Schloss untergebracht, das sich im Verband der französischen Gruppe „Châteaux & Hôtels de France“ befindet.","w":"https://de.wikipedia.org/wiki/Schloss_Vault-de-Lugny"},"ch-Q2970049":{"n":"Château de Montréal","c":"Burg in Frankreich","r":"Die Burg Montréal befindet sich im Département Ardèche im Herzen der ehemaligen Provinz Vivarais im Gemeindegebiet von Montréal. Sie steht in 289 Meter Höhe auf einem Felskegel und dominiert die Ortschaft unter sich. Von dieser Position erhielt die Höhenburg ihren Namen: Das lateinische Mons Regalis bedeutet Königsberg und bezeichnete im Mittelalter höher gelegene Positionen, von denen die Umgebung beherrscht werden konnte. Aus der lateinischen Bezeichnung entwickelte sich das französische Mont Royal und daraus das heutige Montréal.","h":"Die erste urkundliche Erwähnung der Burg Montréal erfolgte im Jahr 1206. Zu jener Zeit bestand sie nur aus einem durch die Familie Balazuc errichteten romanischen Wehrturm, von denen es insgesamt drei in Montréal gab. 1210 war dieser Balazuc-Turm im Besitz von Pierre de Vernon, einem Enkel Pons de Balazucs. Die nachfolgenden Turmbesitzer nannten sich „von Montréal“ und erweiterten die Wehranlage im 13. Jahrhundert um einen Wohnbau (Logis) sowie eine Ringmauer. Gemeinsam mit sieben anderen Burgen sollte sie die Silberbergwerke von Argentaria, dem heutigen Largentière sichern. Pelette de Montréal heiratete am 9. August 1343 Albert II. de Balazuc und brachte die Anlage an seine Familie. Die Balazucs waren im Mittelalter die mächtigste Familie im Niedervivarais. Sie blieb die nachfolgenden rund drei Jahrhunderte Besitzerin und erweiterte die Burg im gotischen Stil. Außerdem fügte sie den bestehenden Bauten um die Wende vom 15. zum 16. Jahrhundert ein Logis im Stil der Renaissance hinzu. Marie, die Erbtochter Jean de Balazucs, brachte Burg und zugehörige Seigneurie 1638 an ihren Ehemann Gabriel de Hautefort de Lestrange. Unter dem Paar wurde die Nordfassade des renaissancezeitlichen Wohnbaus verändert und dabei eine kleine Tourelle entfernt, ihre Konsole aber belassen. Sie ist heute noch an der Fassade erhalten. Über Charlotte de Hautefort kam die Anlage durch Heirat 1742 an die Familie Merle de Lagorce. Während ihrer Zeit als Burgherrin wurden 58 wertvolle Tapisserien aus Aubusson als Teil einer Mitgift von Montréal nach Vallon-Pont-d’Arc gebracht. Sie sind heute im dortigen Rathaus zu sehen. Charlotte und ihr Mann verkauften die Burg am 22.","w":"https://de.wikipedia.org/wiki/Burg_Montr%C3%A9al_(Ard%C3%A8che)"},"ch-Q2970057":{"c":"Schloss in Frankreich"},"ch-Q2970302":{"c":"Burg in Frankreich"},"ch-Q2970308":{"c":"Burg in Frankreich"},"ch-Q2970316":{"c":"Schloss in Frankreich"},"ch-Q2970337":{"n":"Schloss Rambuteau","c":"Schloss in Frankreich","r":"Das Schloss Rambuteau steht in der französischen Gemeinde Ozolles im Département Saône-et-Loire in der Region Bourgogne-Franche-Comté.","h":"Das Schloss in seiner heutigen Form entstand im Jahre 1840. Claude-Philibert Rambuteau ließ das Schloss im Stil des 18. Jahrhunderts mit Walmdächern und der zentralen Fassaden auf den Fundamenten eines Gebäudes von 1777 errichten. Es sind noch ältere Teile des Schlosses erhalten, nämlich ein Turm und eine Kapelle, die noch aus dem 16. Jahrhundert stammen. Im Innern des Schlosses befinden sich Salons mit Möbeln im Stil der Epochen Louis 16. Im 19. Jahrhundert wurde bei der Renovierung der alten Kapelle ein Park neu angelegt.","w":"https://de.wikipedia.org/wiki/Schloss_Rambuteau"},"ch-Q2970341":{"c":"Burg in Frankreich"},"ch-Q2970367":{"c":"Burg in Frankreich"},"ch-Q2970369":{"c":"Burg in Frankreich"},"ch-Q2970373":{"c":"Schloss in Frankreich"},"ch-Q2970398":{"c":"Burg in Frankreich"},"ch-Q2970409":{"c":"Burg in Frankreich"},"ch-Q2968781":{"c":"Burg in Frankreich"},"ch-Q2970402":{"n":"Schloss Rochefort","c":"Schlossruine in Asnières-en-Montagne","r":"Das Schloss Rochefort ist die Ruine eines Schlosses in Asnières-en-Montagne, einer Ortschaft im Département Côte-d’Or in der Region Bourgogne-Franche-Comté.","h":"Die Anlage wurde wahrscheinlich im 12. Jahrhundert auf älteren Befestigungsanlagen errichtet. Eine urkundliche Erwähnung unter dem Namen Rupes fortis datiert auf 1196, der Name des damaligen Herrschers wird mit Eymon angegeben. Aus dem 13. Jahrhundert finden sich Erwähnungen von Herren des Schlosses aus der Familie derer von Rochefort, bevor das Schloss auf Befehl von Johann Ohnefurcht (1371–1419) geschleift wurde. Jacques Coictier (1430–1506), Kammerherr und Leibarzt von Ludwig XI. (1423–1483), erwarb die Anlage und errichtete Ende des 15. Jahrhunderts das heute noch vorhandene Herrenhaus. 1501 kaufte die Familie Rochefort die Anlage zurück und erweitert sie möglicherweise nach Osten, unter anderem um eine Kapelle. Später erwarb Denis Languet die Anlage, Kammerprokurator des Parlement de Dijon. Im 17. Jahrhundert wurden das massive Torgebäude, die Hochterrasse und die Stützmauer mit Nischen ergänzt. Um 1789 erwarb die Familie La Guiche das Schloss. In den frühen 1970er Jahren mündeten Versuche, das Ensemble zu sichern, in der Verwilderung und dem sogar beschleunigten Verfall. 1974 wurden Teile der Anlage unter Denkmalschutz gestellt (Monument historique). 2002 gründete sich unter dem Namen Les clefs de Rochefort ein Verein, der sich als Teil der Union Rempart um die Sicherung und den Erhalt des Ensembles bemüht. Zur Finanzierung wurden unter anderem Konferenzen und ein jährlicher Mittelaltermarkt veranstaltet. 2015 verlangte der französische Staat von den Eigentümern wirksame Maßnahmen zum Erhalt der Schlossanlage. Nachdem die Familie Laguiche 2016 ihren Prozess gegen die staatlichen Auflagen verloren hatte, verkaufte sie das Schloss 2017 für einen symbolischen Euro an Les clefs de Rochefort.","w":"https://de.wikipedia.org/wiki/Schloss_Rochefort_(Asni%C3%A8res-en-Montagne)"},"ch-Q2971608":{"c":"Burg in Frankreich"},"ch-Q2968796":{"c":"Burg in Frankreich"},"ch-Q2971635":{"n":"Schloss Breuil","c":"Burg in Frankreich","r":"Das Schloss Le Breuil ist ein zu Anfang des 16. Jahrhunderts erbautes und vollständig erhaltenes Wasserschloss auf dem Gebiet der Gemeinde Bonneuil südwestlich von Cognac im französischen Département Charente. Seit dem 23. Juni 1952 ist es als Monument historique registriert. Es befindet sich in Privatbesitz und ist nicht öffentlich zugänglich. Die Wirtschaftsgebäude des zum Schloss gehörenden Weinguts befinden sich unmittelbar südwestlich des Schlossbaus.","h":"Der Adlige Philippe d'Ingrandes soll zwischen 1508 und 1532 im Château du Breuil gelebt haben, das er sich als Wohnsitz errichten ließ. Das Datum der Fertigstellung liegt zwischen dem Ende des 15. Jahrhunderts und 1535, genaueres konnte noch nicht ermittelt werden. Durch Erbschaft und mehrere Heiraten kam das Anwesen im Jahr 1716 an die begüterte und weit verzweigte Familie Leroy de Lenchères. (Die Lenchères besaßen auch die Tour du Breuil in Dignac). So blieb die Immobilie fast 200 Jahre, von 1729 bis 1919, im Familienbesitz. Am Besitz beteiligt war darüber hinaus auch die Adelsfamilie von Xant. François Leroy de Lenchères ließ den Bau nach Südwesten verlängern und die Fenster der Südfassade neu gestalten. Danach, um 1769, verlegte er seinen Wohnsitz von La Borde bei Saint-Amant de Bonnieure in das Schloss Le Breuil. Im Jahr 1919 verkaufte Madame de Rancourt de Mimérand das Schloss an Monsieur Castillon du Perron, der hier ein Weingut betrieb. In den 1960er Jahren gehörte das Schloss dem Arzt Brisset und seiner Frau.","w":"https://de.wikipedia.org/wiki/Schloss_Le_Breuil_(Bonneuil)"},"ch-Q2971636":{"c":"Burg in Frankreich"},"ch-Q2971645":{"n":"Château du Carpia","c":"Burg in Frankreich","r":"Das Château du Carpia in Castillon-de-Castets, einem Ort in der französischen Gemeinde Castets et Castillon im Département Gironde in der Region Nouvelle-Aquitaine, wurde ab Ende des 15. Jahrhunderts errichtet. Das Schloss, das sich circa zwei Kilometer südöstlich des Ortes befindet, steht seit 2004 als Monument historique auf der Liste der Baudenkmäler in Frankreich.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_du_Carpia"},"ch-Q2971664":{"c":"Burg in Frankreich"},"ch-Q2971677":{"c":"Burg in Frankreich"},"ch-Q2971682":{"c":"Burg in Frankreich"},"ch-Q2970537":{"c":"Burg in Frankreich"},"ch-Q2971693":{"c":"Burg in Frankreich"},"ch-Q2970552":{"n":"Schloss Saint-Maur","c":"Schloss in Frankreich","r":"Das Renaissance-Schloss Saint-Maur befand sich in Saint-Maur-des-Fossés und ist heute vollständig zerstört.","h":"Das Schloss Saint-Maur wurde direkt oberhalb der ehemaligen Abtei Saint-Maur errichtet, deren Geschichte bis ins frühe Mittelalter zurückreicht. Das Schloss wurde 1541 von Philibert Delorme begonnen und ist das erste bedeutende Werk dieses Architekten. Nach seinem Tod im Jahr 1570 soll Jean Bullant die Verantwortung für das Gebäude übernommen haben. Das Schloss wurde von Kardinal Jean du Bellay, Bischof von Paris und Berater des Königs, in Auftrag gegeben. Es wurde auf einer kleinen Landzunge mit Blick auf die Marne erbaut und überragte die ehemalige Abtei Saint-Maur, deren Abt der Kardinal war. François Rabelais, der eine Zeit lang Mönch in dieser Abtei war, hielt sich in der Burg auf und schrieb möglicherweise dort. Im Jahr 1547, nach dem Tod von König Franz I., fiel du Bellay, der in die Intrigen des Kardinals von Lothringen verwickelt war, in Ungnade, verlor seinen Rang und zog sich nach Rom zurück. Das Schloss bestand damals aus einem Corps de Logis und einem angrenzenden Hof. Die Bauarbeiten wurden bis 1563 unterbrochen, als die Königinmutter Caterina de’ Medici sie wieder aufnehmen ließ, nachdem sie das Schloss von Eustache du Bellay, dem Vetter und Erben von Jean und ebenfalls Bischof von Paris, gekauft hatte. Der Bau wurde durch neue Gebäude bereichert, die um 1570 von Delorme begonnen und nach dessen Tod um 1579 von Jacques I. Androuet du Cerceau umgestaltet wurden, der diese Erweiterungen in seinem Architekturbuch Les plus excellents bastiments de France darstellte. Zunächst handelte es sich um Konsolidierungen und Restaurierungen des bestehenden Gebäudes, dann um einige Erweiterungen. Es ist der Entwurf von Du Cerceau, der die Aufteilung weitgehend verändert, die Verzierungen übernimmt und der Fassade ihr Renaissanceaussehen verleiht. Am 23.","w":"https://de.wikipedia.org/wiki/Schloss_Saint-Maur"},"ch-Q2970587":{"c":"Burg in Frankreich"},"ch-Q2970593":{"c":"Burg in Frankreich"},"ch-Q2970595":{"c":"Burg in Frankreich"},"ch-Q2970608":{"c":"Burg in Frankreich"},"ch-Q2970622":{"n":"Château de Sandaucourt","c":"Schloss in Frankreich","r":"Das Schloss Sandaucourt, vormals ein Wasserschloss, befindet sich in der Gemeinde Sandaucourt im Westen des Départements Vosges in der Region Grand Est, Frankreich.","h":"Das Schloss wurde vermutlich von Aloff de Beauvau oder seinem Halbbruder Claude, dem Herrscher von Sandaucourt, von 1549 bis 1553 erbaut. Als dieser 1553 starb, teilten sich zwei seiner Schwiegersöhne, Claude de Reinach (Stadtrat und Kammerherr von Herzog Karl III. von Lothringen, Seneschall des Barrois) und Jean de Damas, das Eigentum am Schloss. Dieses gemeinsame Eigentum währte bis ins Jahr 1715 und rettete die Burg während des Dreißigjährigen Krieges. Denn als die französischen Truppen das Dorf im Jahr 1636 besetzten, verschonten sie das Schloss, weil die Fulligny-Damas Gefolgsleute Ludwigs XIII., des Königs von Frankreich waren. Dies war bezüglich des anderen Familienzweiges der Schlossbesitzer nicht der Fall, was an dem Enkel von Claude de Reinach, dem Obersten der Infanterie Jean-Jacques de Haraucourt (1600–1644), in Diensten des Herzogs Karl IV. von Lothringen, festgemacht werden kann. De Haraucourts Frau Alberte-Barbe d’Ernécourt (1607–1660), damals bekannt als die christliche Amazone, war jedoch anders als ihr Ehemann dem König von Frankreich treu geblieben. Mehrmals besuchte Kardinal de Retz (1613–1679) die damaligen mit ihm befreundeten Herren von Sandaucourt, Louis des Armoises und Jean Nicolas de Fulligny-Damas. So auch am 3. November 1672 zum Anlass der Taufe seines Patensohns Jean-François Paul de Fulligny-Damas, dem Sohn eines seiner Gastgeber. Im Jahr 1715 wurde das Schloss an den spanischen Marquis d’Amenzuaga de Riscal d’Alegre, Ehemann der Baronin Suzanne de Chauviray, verkauft. Dieser veräußerte das Anwesen 1735 an den Hauptzollpächter von Lothringen, Sigisbert Richard, der es seinerseits im Jahre 1770 an François de Saint-Ligier, einen von Ludwig XV. geadelten Maréchal de camp weiterreichte. Das Schloss wurde im 18.","w":"https://de.wikipedia.org/wiki/Schloss_Sandaucourt"},"ch-Q2970629":{"c":"Burg in Frankreich"},"ch-Q2970650":{"c":"Schloss in Frankreich"},"ch-Q2970652":{"c":"Schloss in Frankreich"},"ch-Q2971825":{"n":"Schlossberg (Forbach)","c":"Schloss in Frankreich","r":"Die Burg Schlossberg – mitunter auch nur Schlossberg genannt – ist der Überrest der abgegangen zur Festungsanlage ausgebauten Burg der französischen Stadt Forbach im Département Moselle und in der Région Grand Est. Die Burg auf dem gleichnamigen auch Kapellenberg genannten Hügel ist ein Wahrzeichen der Stadt.","h":"Erstmals erwähnt wurde eine Burganlage im Jahr 1257 durch Théoderich de Werde. Zu diesem Zeitpunkt befand sich unterhalb der Burg bereits seit dem 11. Jahrhundert eine Siedlung unterhalb des Schlossbergs, das heutige Forbach. Die Anlage entwickelte sich in mehreren Bauphasen: Ein frühgotischer Kern wurde unter Arnold VI. von Sierck, ein treuer Verbündeter von Herzog René von Anjou, in der Spätgotik erweitert. 1437 wurde der erste Turm errichtet. Mitte des 16. Jahrhunderts wurde ein Renaissancebau ergänzt. Kurz vor dem Dreißigjährigen Krieg erfuhr die Burg weitere bauliche Veränderungen, nach dem sie an die Grafen von Leiningen-Westerburg und Eberstein gefallen weiter. So entwickelte sich die Burg zur ovalen Festungsanlage. Dennoch wurde die Burg am 14. Dezember 1634 auf Befehl von Ludwig XIII. unter Marschall Jacques Nompar de Caumont La Force gesprengt, da er sie als Bedrohung für französische Interessen in Lothringen ansah. 1591 wurde die Burg von Truppen des Fürsten Christian von Anhalt eingenommen, gesprengt und nicht wieder vollständig aufgebaut. Dieser unterstützte den französischen König Heinrich IV. im Kampf gegen den damaligen Herzog von Lothringen. In den nachfolgenden Jahrhunderten zerfiel die Burg und diente spätestens ab 1795 auch sie als Steinbruch. Ab 1886 wurde mit archäologischen Ausgrabungen auf dem Burggelände begonnen. Dabei wurde 1891 der neogotische Aussichtsturm mit romantisierenden Zinnen und Pechnasen versehen. Federführend bei dieser Rekonstruktion war der Metzer Dombaumeister Paul Tornow. Heute sind nur noch dieser wiederhergestellte Bergfried und einige Mauerreste erhalten. Die Bauarbeiten wurden damals durch die lokale Industriefamilie Adt, insbesondere Gustave Adt, finanziert. Im Zweiten Weltkrieg wurde weite Teile der Burg zerstört.","w":"https://de.wikipedia.org/wiki/Schlossberg_(Forbach)"},"ch-Q2971827":{"c":"Schloss in Frankreich"},"ch-Q2942728":{"c":"Burg in Frankreich"},"ch-Q2967791":{"n":"Château-Gaillard","c":"Burg in Vannes, Frankreich"},"ch-Q2967797":{"c":"Burg in Frankreich"},"ch-Q2967807":{"c":"Burg in Frankreich"},"ch-Q2967838":{"c":"Schloss in Frankreich"},"ch-Q2968809":{"c":"Burg in Frankreich"},"ch-Q2967823":{"c":"Museum in Frankreich"},"ch-Q2968815":{"c":"Burg in Frankreich"},"ch-Q2968816":{"c":"Schloss in Frankreich"},"ch-Q2968821":{"c":"Burg in Frankreich"},"ch-Q2968835":{"c":"Burg in Frankreich"},"ch-Q2968838":{"c":"Burg in Frankreich"},"ch-Q2968850":{"c":"Burg in Frankreich"},"ch-Q2243875":{"n":"Schloss Villevêque","c":"Schloss in Frankreich","r":"Schloss Villevêque liegt in der französischen Ortschaft Villevêque, 15 Kilometer nordöstlich von Angers, im Département Maine-et-Loire in der Region Pays de la Loire.","w":"https://de.wikipedia.org/wiki/Schloss_Villev%C3%AAque"},"ch-Q2968112":{"c":"Burg in Frankreich"},"ch-Q2968124":{"n":"Schloss Arnouville","c":"Burg in Frankreich","r":"Das Schloss in Arnouville, einer französischen Gemeinde im Département Val-d’Oise in der Region Île-de-France, wurde von 1750 bis 1757 errichtet. Das Schloss steht seit 2000 als Monument historique auf der Liste der Baudenkmäler in Frankreich.","w":"https://de.wikipedia.org/wiki/Schloss_Arnouville"},"ch-Q2968122":{"n":"Schloss Arnicourt","c":"Burg in Frankreich","r":"Das Schloss in Arnicourt, einer französischen Gemeinde im Département Ardennes in der Region Grand Est, wurde im 18. Jahrhundert errichtet. Das Schloss ist seit 2001 als Monument historique eingetragen.","h":"Das zweigeschossige Gebäude mit Mansarddach wurde an der Stelle eines Vorgängerbaus für die Familie Rémont errichtet. Im Jahr 1837 kaufte es Gustave Le Bienvenu du Busc, der es in der Folgezeit umbauen ließ.","w":"https://de.wikipedia.org/wiki/Schloss_Arnicourt"},"ch-Q2968127":{"c":"Burg in Frankreich"},"ch-Q2968135":{"c":"Burg in Frankreich"},"ch-Q2968147":{"c":"Burg in Frankreich"},"ch-Q2968163":{"c":"Burg in Frankreich"},"ch-Q2968167":{"c":"Burg in Frankreich"},"ch-Q2968196":{"c":"Burg in Frankreich"},"ch-Q2971052":{"c":"Burg in Frankreich"},"ch-Q3360957":{"c":"Palast in Frankreich"},"ch-Q3361109":{"c":"Palast in Frankreich"},"ch-Q2968208":{"c":"Schloss in Frankreich"},"ch-Q3365503":{"c":"Palast in Frankreich"},"ch-Q2968213":{"c":"Burg in Frankreich"},"ch-Q2968220":{"n":"Schloss Esnes","c":"Schloss in Frankreich","r":"Das Schloss Esnes steht im Zentrum der französischen Gemeinde Esnes zehn Kilometer südöstlich von Cambrai im Département Nord, das zur Region Hauts-de-France gehört.","h":"Die Wurzeln des Schlosses reichen zurück bis in das Jahr 1007. Zu Beginn des 11. Jahrhunderts wurden die ersten Teile des Schlosses unter der Herrschaft von Alard d’Esnes erbaut. Die männliche Linie derer von Esnes endet 1105 mit Alard II. Seine Tochter heiratet Eustache de Landas, Herr von Eyne in Flandern, Sohn von Amaury VI. und Ermentrude de Béthune. Das Haus Esnes wechselt zur Familie Landas, und man nannte sich fortan Landas d’Esnes. Um 1260 heiratete Alix de Beauvoir den Erben Gérard de Landas d’Esnes. Ihre einzige Tochter brachte das Schloss in die Ehe mit Alard de Croisille ein, der den Namen d’Esnes weitertrug. Die Herren von Esnes waren Gefolgsleute des Grafen des Hennegaus und nahmen an verschiedenen Auseinandersetzungen mit den Herzogtümern von Brabant, Limburg und Flandern teil. Allerdings wechselte Jean I. von Esnes zu Beginn des Hundertjährigen Kriegs von der Seite des Hennegaus, Verbündeter der Engländer, auf die Seite des französischen Königs und fiel bei der Schlacht von Poitiers im Jahr 1356. In der Nachfolge waren die Herren von Esnes sowohl Vogt von Cambrai als auch von Amiens. Robert d’Esnes, genannt Mansart, war ein Gefolgsmann des Herzogs von Orléans. 1411 war er als Herr über Esnes, Grécourt, Wavrechin, Vire, Bétancourt und Beauvoir auch Gouverneur der Burg Coucy, die er drei Monate lang gegen die Belagerung durch Walram III., den Grafen von Saint-Pol, verteidigte. Walram stritt auf Seiten der Burgunder für Johann Ohnefurcht, Herzog von Burgund, dessen treuer Gefolgsmann er war. Seit der Französischen Revolution diente das Schloss als landwirtschaftliches Gut. Während des Ersten Weltkriegs diente es als deutsches Militärgefängnis für russische Kriegsgefangene.","w":"https://de.wikipedia.org/wiki/Schloss_Esnes"},"ch-Q2968454":{"c":"Burg in Frankreich"},"ch-Q2968478":{"c":"Burg in Frankreich"},"ch-Q2968487":{"c":"Schloss in Frankreich"},"ch-Q2968506":{"c":"Schloss in Frankreich"},"ch-Q2968507":{"c":"Burg in Frankreich"},"ch-Q2968509":{"c":"Schloss in Frankreich"},"ch-Q2968535":{"c":"Burg in Frankreich"},"ch-Q2243521":{"n":"Schloss Simiane-la-Rotonde","c":"Schloss in Frankreich","r":"Das Château de Simiane-la-Rotonde liegt in der französischen Gemeinde Simiane-la-Rotonde im Département Alpes-de-Haute-Provence in der Région Provence-Alpes-Côte d’Azur auf der Spitze eines kegelförmigen Felssporns, dessen Spitze von der Ruine des Châteaus mit seiner Rotunde bekrönt wird. Simiane-la-Rotonde ist ein typisches Beispiel eines „village perché“ (Bergdorf), zu dessen Füßen sich eine weitläufige Ebene ausbreitet.","w":"https://de.wikipedia.org/wiki/Schloss_Simiane-la-Rotonde"},"ch-Q2969049":{"c":"Burg in Frankreich"},"ch-Q2967871":{"c":"Schloss in Frankreich"},"ch-Q2967858":{"c":"Burg in Frankreich"},"ch-Q2967898":{"c":"Burg in Frankreich"},"ch-Q2967903":{"n":"Château La Louvière","c":"Schloss in Frankreich"},"ch-Q2967949":{"c":"Burg in Frankreich"},"ch-Q2970242":{"c":"Burg in Frankreich"},"ch-Q2970259":{"c":"Burg in Frankreich"},"ch-Q2968433":{"c":"Burg in Frankreich"},"ch-Q2970260":{"c":"Burg in Frankreich"},"ch-Q2969183":{"c":"Schloss in Frankreich"},"ch-Q2969191":{"c":"Schloss in Frankreich"},"ch-Q2969197":{"n":"Schloss Faulin","c":"Schloss in der Gemeinde Lichères-sur-Yonne, Departement Yonne, Region Bourgogne-Franche-Comté, Frankreich.","r":"Das Schloss Faulin ist ein Schloss in der Gemeinde Lichères-sur-Yonne im Département Yonne der französischen Region Bourgogne-Franche-Comté. Das Schloss liegt am Fuße eines bewaldeten Hügels im Tal des Flusses Yonne am Ufer des Canal du Nivernais.","h":"Die Anlage wurde erstmals im 13. Jahrhundert als Burg der Herren von Châtel-Censoir erwähnt. Im Jahr 1389 wurde sie von einem Zweig der Adelsfamilie de Bourgoing erworben, die im späten 15. Jahrhundert die heutigen Schlossgebäude errichtete. Als Bourgoing de Faulin besetzten Mitglieder der Familie wichtige Ämter am Hofe der Herzöge von Nevers. Bis zum 18. Jahrhundert blieb das Schloss im Besitz der Familie. Im frühen 19. Jahrhundert gelangten Schloss und Ländereien in den Besitz der Familie de Vogüé. Die landwirtschaftlichen Gebäude auf dem Gelände der Schlossanlage stammen aus dieser Zeit. Noch heute befindet sich die Anlage in Privatbesitz.","w":"https://de.wikipedia.org/wiki/Schloss_Faulin"},"ch-Q2969200":{"c":"Schloss in Frankreich"},"ch-Q2969249":{"c":"Burg in Frankreich"},"ch-Q2969254":{"c":"Burg in Frankreich"},"ch-Q2969257":{"n":"Château de Franconville-aux-Bois","c":"Schloss in Frankreich"},"ch-Q2969338":{"c":"Burg in Frankreich"},"ch-Q2969342":{"c":"Schloss in Frankreich"},"ch-Q2969366":{"c":"Schloss in Frankreich"},"ch-Q2969371":{"c":"Schloss in Frankreich"},"ch-Q2969374":{"c":"Burg in Frankreich"},"ch-Q2969070":{"c":"Burg in Frankreich"},"ch-Q2969109":{"c":"Schloss in Frankreich"},"ch-Q2969939":{"c":"Burg in Frankreich"},"ch-Q2969922":{"c":"Schloss in Frankreich"},"ch-Q2969953":{"c":"Schloss in Frankreich"},"ch-Q2969977":{"c":"Schloss in Frankreich"},"ch-Q2969267":{"c":"Burg in Frankreich"},"ch-Q2969986":{"c":"Burg in Frankreich"},"ch-Q2969270":{"c":"Schloss in Frankreich"},"ch-Q2969277":{"c":"Burg in Frankreich"},"ch-Q2969273":{"c":"Schloss in Frankreich"},"ch-Q2969281":{"c":"Schloss in Frankreich"},"ch-Q2969298":{"c":"Schloss in Frankreich"},"ch-Q2969303":{"c":"Schloss in Frankreich"},"ch-Q2969304":{"c":"Burg in Frankreich"},"ch-Q2969312":{"c":"Schloss in Frankreich"},"ch-Q2969317":{"c":"Burg in Frankreich"},"ch-Q2969324":{"c":"Burg in Frankreich"},"ch-Q2970000":{"n":"Château de Monthelie","c":"Burg in Frankreich","r":"Das Schloss Monthelie in Monthelie, einer französischen Gemeinde im Département Côte-d’Or in der Region Bourgogne-Franche-Comté, wurde ursprünglich im 16. Jahrhundert errichtet und im 18. Jahrhundert umgebaut. Das Schloss steht seit 1988 als Monument historique auf der Liste der Baudenkmäler in Frankreich.","w":"https://de.wikipedia.org/wiki/Schloss_Monthelie"},"ch-Q2970004":{"c":"Burg in Frankreich"},"ch-Q2970022":{"n":"Château de Montmorency","c":"Schloss in Montigny-en-Ostrevent, Frankreich"},"ch-Q2970038":{"c":"Burg in Frankreich"},"ch-Q2970039":{"c":"Schloss in Frankreich"},"ch-Q2970046":{"c":"Burg in Frankreich"},"ch-Q2969398":{"n":"Château de Hierges","c":"Burg in Frankreich"},"ch-Q2969422":{"c":"Burg in Frankreich"},"ch-Q2969425":{"c":"Schloss in Frankreich"},"ch-Q2969419":{"c":"Schloss in Frankreich"},"ch-Q2970261":{"c":"Burg in Frankreich"},"ch-Q2970268":{"c":"Burg in Frankreich"},"ch-Q2970281":{"n":"Schloss Potelle","c":"Burg im Département Nord, Frankreich","r":"Das Schloss Potelle ist ein Wasserschloss in der Gemeinde Potelle, das auf eine Wasserburg eines Zweigs der Familie de Mortagne aus dem 13. Jahrhundert zurückgeht. Burg und Ortschaft gehörten zur Grafschaft Hennegau, auf die seit dem späten Mittelalter verschiedene Parteien Anspruch erhoben. Entsprechend war das Gebiet lange Zeit hart umkämpft, und das Schloss wurde im Laufe der Geschichte mehrmals geplündert sowie gebrandschatzt, aber jedes Mal unter Beibehaltung der noch vorhandenen Bausubstanz wiederaufgebaut.","h":"Die Seigneurs von Potelle wurden schon im 12. Jahrhundert schriftlich erwähnt und waren Gefolgsleute des Grafen von Hennegau. Im Jahr 1203 fand Gérard de Potelles urkundlich Erwähnung. Entsprechend könnte es damals schon ein castrum im flachen und feuchten Tal der Rhonelle gegeben haben, das eine sehr einfache, von einer Wehrmauer umgebene Anlage, bestehend aus nur einem Logis und Wirtschaftsgebäuden, gewesen sein könnte. Um 1290 errichtete Willes (auch Gilles) de Mortagne, dessen Familie im 13. Jahrhundert in den Besitz der Segneurie gekommen war, eine neue Burg. Davon kündet das Teilstück seines Grabsteins, das in der Schlosskapelle zu sehen ist. Die erste Zeile der Inschrift lautet: Willes a fait construire cette maison (deutsch Willes hat dieses Haus errichtet). Willesʼ Familie nannte sich anstatt de Mortagne nachfolgend auch nach ihrer Burg „de Potelle(s)“. 1340 wurde die Anlage während des Hundertjährigen Krieges durch Truppen des damaligen Herzogs der Normandie und späteren französischen Königs Johann II. niedergebrannt. Der Burgherr kam bei den Kämpfen ums Leben. Anschließend wiederaufgebaut, blieb Burg Potelle mehr als 100 weitere Jahre Eigentum der Familie Mortagne. 1433 wurde Gilles II. de Mortagne wegen des Vorwurfs, ein Mordkomplott gegen den burgundischen Herzog Philipp III. geplant zu haben, verhaftet und hingerichtet. All seine Güter, darunter auch Potelle, wurden konfisziert und an den damaligen herzoglichen Günstling Antoine I. de Croÿ verkauft. Von ihm erwarb es Jeanne de Mortagne, die Schwester Gillesʼ II., 1436 zurück. Sie musste erleben, wie 1477 Truppen des französischen Königs Ludwig XI.","w":"https://de.wikipedia.org/wiki/Schloss_Potelle"},"ch-Q2970289":{"c":"Burg in Frankreich"},"ch-Q3146255":{"c":"Palast in Frankreich"},"ch-Q3210217":{"n":"La Mabilière"},"ch-Q2970295":{"c":"Burg in Frankreich"},"ch-Q3280193":{"c":"Schloss in Frankreich"},"ch-Q3286199":{"c":"Schloss in Frankreich"},"ch-Q2969445":{"n":"Burg Juis","c":"Burg in Savigneux, Département Ain, Frankreich","r":"Die Burg Juis ist eine ehemalige Burg aus dem 14. Jahrhundert, Zentrum der Herrschaft Juis, die zwei Kilometer südlich des Ortskerns der französischen Gemeinde Savigneux im Département Ain in der Region Auvergne-Rhône-Alpes liegt. Die Burg ist teilweise in die Liste der historischen Denkmäler eingetragen.","w":"https://de.wikipedia.org/wiki/Burg_Juis"},"ch-Q3286205":{"c":"Schloss in Frankreich"},"ch-Q2969466":{"c":"Burg in Frankreich"},"ch-Q2969476":{"c":"Schloss in Frankreich"},"ch-Q2969531":{"c":"Schloss in Frankreich"},"ch-Q2969529":{"c":"Burg in Frankreich"},"ch-Q2969535":{"c":"Schloss in Frankreich"},"ch-Q2686300":{"c":"Burg in Frankreich"},"ch-Q2693777":{"c":"Burg in Frankreich"},"ch-Q2711461":{"c":"Burg in Frankreich"},"ch-Q2968912":{"c":"Schloss in Frankreich"},"ch-Q2968932":{"c":"Schloss in Frankreich"},"ch-Q2968945":{"n":"Château de Châlus Maulmont","c":"Schloss in Frankreich","r":"Die Burg Châlus-Maulmont, auch als Tour du Fort bezeichnet, liegt im Stadtbereich der französischen Gemeinde Châlus im Département Haute-Vienne.","h":"Die Burg wurde zwischen 1275 und 1280 in der Unterstadt von Châlus von Géraud de Maulmont (auch Maumont) errichtet – dem Berater der Vizegräfin von Limoges Marguerite de Bourgogne. Die Ländereien gehörten damals noch zur Burg Chalucet. Zu Beginn der Französischen Revolution im Jahr 1789 waren der Nordwestturm und das Hauptaufenthaltsgebäude noch intakt, diese wurden aber zwischen 1794 und 1799 von den Einwohnern von Châlus schwer beschädigt, welche die Burg als Steinbruch benutzten. Der restliche erhaltene Teil der Burg diente bis 1820 als Gefängnis. Im selben Jahr wurde dieser dann dem Grafen von Bourbon Busset (dessen jüngere Nebenlinie Bourbon-Châlus lautet) zurückgegeben. Im Jahr 1888 unterzog der Archäologe und Architekt Jules Tixier auf Ersuchen des Grafen von Châlus die Burganlage einer rigorosen Untersuchung, da bereits zum damaligen Zeitpunkt schwerwiegende Einsturzgefahr herrschte. Im Jahr 1928 brach dann am Haupthaus der vernachlässigte Dachstuhl ein. Am 20. März 1994 ereignete sich der katastrophale Einsturz des übriggebliebenen Südostturms. Der Turm war 27,6 Meter hoch und hatte einen Durchmesser von 8,70 Meter, bei einer Mauerstärke von 2,50 Meter. Die Schuttmassen begruben zwei anliegende bewohnte Häuser, eine Scheune und einige Fahrzeuge – wie durch ein Wunder kam jedoch hierbei niemand zu Schaden. Mit finanzieller Hilfe der Brauerei Duplessi (und deren Marke Chevalier de Maulmont) konnte im Jahr 2005 die Restaurierung der Burg in Angriff genommen werden. Es bestehen ferner jetzt Pläne, die Burg Châlus-Maulmont in ein kulinarisches Viertel zu integrieren. Die Burg ist seit dem 25. März 1981 als Monument historique eingeschrieben und somit denkmalgeschützt.","w":"https://de.wikipedia.org/wiki/Burg_Ch%C3%A2lus-Maulmont"},"ch-Q2968957":{"n":"Burg Chateau-Thierry","c":"Schloss in Frankreich"},"ch-Q2968963":{"c":"Burg in Frankreich"},"ch-Q2968968":{"c":"Burg in Frankreich"},"ch-Q2968970":{"c":"Schloss in Frankreich"},"ch-Q2968982":{"c":"Burg in Frankreich"},"ch-Q2969680":{"c":"Burg in Frankreich"},"ch-Q2969688":{"c":"Schloss in Frankreich"},"ch-Q2969707":{"n":"Château de Lignières","c":"Wasserschloss in Frankreich","r":"Das Château de Lignières ist ein Wasserschloss in Lignières-Ambleville im Département Charente im Süden der Region Nouvelle-Aquitaine in Frankreich, etwa 20 Kilometer südöstlich der Stadt Cognac. Es beherbergt heute das Bürgermeisteramt und den Gemeindesaal.","h":"Das heutige Schloss stammt aus der Anfangszeit des 17. Jahrhunderts und wurde an der Stelle eines verfallenen mittelalterlichen Baus errichtet. Bauherr war Charles Poussard († 5. Februar 1731), dessen Geschlecht von 1475 bis 1709 u. a. die Herrschaft von Lignières innehatte. Baumeister war Jehan Cosset. Nach Charles Poussard war das Schloss von 1709 bis 1829 im Besitz der Herren de Plas, die es durch die Heirat von Charles Poussards ältester Tochter Marie Judith mit François Joseph de Plas am 10. November 1709 erwarben.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_de_Ligni%C3%A8res"},"ch-Q2969727":{"c":"Burg in Frankreich"},"ch-Q2971879":{"c":"Burg in Frankreich"},"ch-Q2971880":{"c":"Schloss in Frankreich"},"ch-Q3034583":{"c":"Park in Frankreich"},"ch-Q2405910":{"c":"Burg in Frankreich"},"ch-Q2408159":{"c":"Schloss in Frankreich"},"ch-Q2408797":{"c":"Burg in Frankreich"},"ch-Q2412699":{"c":"Burg in Frankreich"},"ch-Q2418810":{"c":"Schloss in Frankreich"},"ch-Q2424795":{"c":"Schloss in Frankreich"},"ch-Q2971214":{"c":"Burg in Frankreich"},"ch-Q2971220":{"c":"Burg in Frankreich"},"ch-Q2971228":{"c":"Burg in Frankreich"},"ch-Q2971232":{"c":"Schloss in Frankreich"},"ch-Q2971238":{"c":"Burg in Frankreich"},"ch-Q2971244":{"n":"Schloss La Gaubertie","c":"Schloss in Frankreich","r":"Das Schloss La Gaubertie ist ein französisches Schloss in der Gemeinde Saint-Martin-des-Combes in der Region Nouvelle-Aquitaine. Es stammt aus dem 15. Jahrhundert und wurde im 17. sowie 19. Jahrhundert mehrfach umgebaut.","h":"Gegenüber dem Schloss Clermont, auf der anderen Seite des vom Bach les Carbonnières durchflossenen Tales, existierte zunächst ein befestigtes Haus namens La Borie, das sich im Besitz der Herren von Clermont befand. An der Stelle dieses befestigten Bauernhauses wurde Ende des 15. Jahrhunderts das Schloss La Gaubertie errichtet. In den Hugenottenkriegen wurde es beschädigt und musste im 17. Jahrhundert restauriert werden. Eine Kapelle wurde dabei hinzugefügt. Ende des 19. Jahrhunderts renovierte man die Innenräume und die Nebengebäude. Der Philosoph Maine de Biran besuchte das Schloss mehrfach, ebenso Charles de Foucauld im Jahr 1913 während seines mehrmonatigen Aufenthalts in Frankreich.","w":"https://de.wikipedia.org/wiki/Schloss_La_Gaubertie"},"ch-Q2971247":{"c":"Schloss in Frankreich"},"ch-Q2971264":{"c":"Schloss in Frankreich"},"ch-Q2971274":{"c":"Schloss in Frankreich"},"ch-Q2971317":{"n":"Château de la Motte","c":"Burg in Frankreich","r":"Das Schloss La Motte ist ein Wasserschloss in Lorrez-le-Bocage-Préaux, einer französischen Gemeinde im Département Seine-et-Marne in der Region Île-de-France. Es steht seit dem 12. Mai 1975 als Monument historique unter Denkmalschutz. Das Anwesen befindet sich in Privatbesitz und steht Besuchern – von wenigen Ausnahmen bei besonderen Veranstaltungen abgesehen – nicht offen.","h":"1480 erwarb Aymard de Brisay die Seigneurie La Motte und Lorrez und ließ Ende des 15. Jahrhunderts ein Schloss am heutigen Standort bauen. Zuvor hatte dort eine von Wassergräben umgebene Befestigung gestanden. Im 16. und 17. Jahrhundert befand sich das Schloss im Besitz der Familie de Voisinlieu, die aus der Noblesse de robe stammte. Für das 18. Jahrhundert sind die Familien de Chamegnelles und Brayer als Besitzer bekannt. Während der Französischen Revolution wurde die Anlage konfisziert und anschließend als Staatseigentum versteigert. 1839 erwarb sie Amélie Greffulhe, verheiratete Gräfin von Ségur. Gemeinsam mit ihrem Mann Paul de Ségur ließ sie das Anwesen wieder instand setzen und verändern. So wurde der Ostflügel vergrößert und der bisherige französische Garten westlich des Hauptgebäudes (Logis) zu einem englischen Landschaftsgarten umgewandelt. Das Paar gab dem Schloss damit sein heutiges Aussehen. In ihrer Zeit als Schlosseigentümer fallen auch einige Besuche der französischen Schriftstellerin Sophie de Ségur, die eine nahe Verwandte der beiden war. Über Amélies und Pauls Tochter Juliette, kam der Besitz an die Familie ihres Mannes, den Grafen Roger de La Rochefoucauld. Die Tochter des Paars, Pauline Charlotte Josephine, brachte das Schloss in die Ehe mit Aumary Victorien Werner de Mérode. Deren gemeinsame Tochter Marguerite Juliette Charlotte heiratete Bernard Étienne Raymond Galard de Béarn, doch die Ehe blieb kinderlos. So vermachte Marguerite Juliette Charlotte das Anwesen bei ihrem Tod 1956/57 der Tochter ihres Bruders, Geneviève de Mérode, die mit Hubert de La Rochefoucauld einem Urenkel Juliette de Ségurs und Roger de La Rochefoucaulds heiratete. Seit 2007 ist ihr Sohn Bernard Eigentümer des Schlosses.","w":"https://de.wikipedia.org/wiki/Schloss_La_Motte_(Lorrez-le-Bocage-Pr%C3%A9aux)"},"ch-Q2971329":{"c":"Burg in Frankreich"},"ch-Q2971331":{"c":"Burg in Frankreich"},"ch-Q2971336":{"c":"Burg in Frankreich"},"ch-Q2971339":{"c":"Schloss in Frankreich"},"ch-Q2971348":{"c":"Burg in Frankreich"},"ch-Q2971358":{"c":"Schloss in Frankreich"},"ch-Q2971375":{"n":"Schloss La Rochefoucauld (Liancourt)","c":"Burg in Frankreich","r":"Das Schloss Liancourt, ab dem 18. Jahrhundert Schloss La Rochefoucauld, war ein Schloss in der Gemeinde Liancourt im Département Oise in der Region Hauts-de-France in Frankreich. Es ist zu unterscheiden vom wesentlich älteren Schloss La Rochefoucauld in der Charente, dem ursprünglichen Sitz der Familie La Rochefoucauld. Heute sind nur noch die Nebengebäude des Schlosses erhalten, die seit dem 3. Dezember 1930 unter Denkmalschutz stehen.","h":"Die Ländereien von Liancourt lagen im Tal der Brèche, auf halbem Weg zwischen Creil und Clermont, und waren auf mehrere Lehen aufgeteilt. Vom 12. bis zum 14. Jahrhundert trugen verschiedene Herren, darunter Mitglieder der mächtigen Familie Cressonsacq, den Namen Liancourt, ohne dass man weiß, ob sie damit den Namen der Gemeinde oder eines bestimmten Landesbesitzes meinten. Fest steht jedoch, dass Jean I. de Popincourt, Erster Präsident des Parlements von Paris, Ende des 14. Jahrhunderts bei seiner Heirat mit Claude de Cressonsacq den Titel „Sire de Liancourt“ annahm. Wahrscheinlich erhielt er bei dieser Gelegenheit das bescheidene Herrenhaus (8,40 m × 6 m), das die Cressonsacq in Liancourt erbaut hatten und von dem 1796 noch Spuren zwischen der Rue du Vieux-Château und der Rue de Compiègne (der späteren Rue de l'École des arts et métiers) zu sehen waren. Es war zweifellos auf Initiative Popincourts, der 1403 starb, dass gleichzeitig mit dem Kirchenschiff der heutigen Kirche (der Kirche Saint-Martin) das erste Schloss Liancourt erbaut wurde. Über dieses herrschaftliche Anwesen ist nicht viel bekannt, außer seinem Standort, der derselbe ist wie der der beiden Schlösser aus dem 16. und 17. Jahrhundert, die es ersetzt haben, inmitten der sumpfigen Wiesen zwischen Brêche und Béronnelle. Eine Skizze, die angeblich nach zeitgenössischen Dokumenten angefertigt wurde, vermittelt ein wenig überzeugendes Bild davon: ein schwerfälliges Gebäude, umgeben von einem Wassergraben und umschlossen von mächtigen Mauern.","w":"https://de.wikipedia.org/wiki/Schloss_La_Rochefoucauld_(Liancourt)"},"ch-Q2371103":{"c":"Schloss in Frankreich"},"ch-Q2971385":{"c":"Burg in Frankreich"},"ch-Q2377009":{"c":"Burg in Frankreich"},"ch-Q2968241":{"c":"Burg in Frankreich"},"ch-Q2968254":{"c":"Burg in Frankreich"},"ch-Q2968255":{"c":"Schloss in Frankreich"},"ch-Q2968263":{"c":"Burg in Frankreich"},"ch-Q2968275":{"c":"Schloss in Frankreich"},"ch-Q2968287":{"c":"Burg in Frankreich"},"ch-Q2968302":{"c":"Burg in Frankreich"},"ch-Q2968337":{"c":"Burg in Frankreich"},"ch-Q2968386":{"c":"Burg in Frankreich"},"ch-Q2968393":{"c":"Burg in Frankreich"},"ch-Q2968394":{"c":"Burg in Frankreich"},"ch-Q2968396":{"n":"Schloss Bagatelle","c":"Barockschloss in Frankreich","r":"Das Schloss Bagatelle ist ein kleines Landschloss im Süden der französischen Stadt Abbeville rund 30 Kilometer nordwestlich von Amiens in der Picardie. Durch einen reichen Tuchfabrikanten im 18. Jahrhundert errichtet, war es derart bekannt, dass ihm der französische Dichter Michel-Jean Sedaine 1770 ein langes Gedicht widmete.","h":"Abraham van Robais, der reiche Besitzer einer Tuchmanufaktur, ließ zwischen 1751 und 1754 im Faubourg Saint-Gilles einen kleinen Pavillonbau errichten, um dort wichtige Geschäftspartner empfangen zu können. Dazu hatte er am 30. August 1751 und am 28. Januar 1753 zwei Grundstücke erworben, denen er am 5. Januar 1754 ein drittes Grundstück hinzufügte, auf dem er einen Gartenpavillon bauen ließ. Damals handelte es sich um ein recht einfaches, eingeschossiges Landhaus mit nur vier Räumen. Abrahams Sohn ließ das Gebäude 1763 um ein Attikageschoss aufstocken, dessen Flachdach als Terrasse genutzt wurde. Diese war von einer mit kleinen Statuen besetzten Balustrade abgeschlossen. Kurz vor Ausbruch der Französischen Revolution wurde sie durch ein Mansarddach ersetzt, um Platz für drei zusätzliche Schlafzimmer zu gewinnen. Die Familie van Robais verließ Frankreich während der Revolutionsjahre, und ihr Schlösschen kam am 26. März 1793 an Pierre-François Rose (auch Roze geschrieben). Anschließend ging es durch mehrere Hände, ehe es der während der Revolutionsjahre emigrierte Gabriel-Auguste Warnier de Wailly am 22. März 1810 erwarb. Sein Enkel, der Komponist Paul de Wailly, ließ zu Beginn des 20. Jahrhunderts dem Schloss zwei niedrige Seitenflügel nach Plänen des Architekten Louis Parent anfügen und den Schlosspark sowie -garten in einfachen Formen wiederherstellen. Paul de Wailly veranstaltete im Schloss Konzerte und musikalische Soireen mit den bekanntesten Künstlern seiner Zeit, unter anderem César Franck, Camille Saint-Saëns und Vincent d’Indy. Im Zweiten Weltkrieg wurde das Gebäude 1944 von einer Granate getroffen und stark beschädigt. Sein Dachstuhl brannte völlig ab, und der wertvolle Bestand der Bibliothek ging verloren.","w":"https://de.wikipedia.org/wiki/Schloss_Bagatelle_(Abbeville)"},"ch-Q2154496":{"c":"Burg in Frankreich"},"ch-Q2156048":{"c":"Burg in Frankreich"},"ch-Q2157437":{"c":"Burg in Frankreich"},"ch-Q2166293":{"c":"Burg in Frankreich"},"ch-Q2172429":{"c":"Burg in Frankreich"},"ch-Q2969006":{"c":"Schloss in Frankreich"},"ch-Q2971432":{"c":"Schloss in Frankreich"},"ch-Q2971468":{"c":"Burg in Frankreich"},"ch-Q2971474":{"c":"Burg in Frankreich"},"ch-Q2971500":{"c":"Burg in Frankreich"},"ch-Q2971507":{"c":"Burg in Frankreich"},"ch-Q2971514":{"c":"Schloss in Frankreich"},"ch-Q2244370":{"n":"Schloss Étoges","c":"Schloss in Frankreich","r":"Das Schloss Étoges ist ein Wasserschloss in der gleichnamigen französischen Gemeinde im Département Marne der Region Grand Est. Es steht seit 1956 als Monument historique unter Denkmalschutz.","h":"Die Anfänge des Schlosses reichen ins 12. Jahrhundert zurück. Eustache III. de Conflans, seiner Zeit Marschall der Champagne und Berater des Königs, errichtete eine Befestigung am Rand eines Berghanges, vermutlich umgeben von einem Graben gespeist mit Wasser aus vorhandenen Quellen. Da Eustaches Kinder bereits in jungen Jahren verstarben, brachte seine Schwester Marguerite de Conflans das Anwesen von Étoges als Erbe in die Ehe mit Oger III d’Anglure ein, einem Ritter in den Diensten des Herzogs von Orléans. Im Jahr 1572 heiratete Antoinette d’Anglure den Kammerherrn des Herzogs von Alençon, Chretien de Savigny. Savigny war Herrscher über Châlons und Leutnant des Königs in der Champagne. Auch ihr Sohn Charles Saladin de Savigny (1573–1616) führte den Namen d’Anglure weiter. Sein Erbe, Antoine Saladin d’Anglure de Savigny, Baron von Rosne, empfing 1632 den französischen König Ludwig XIII. in Étoges. Er war Feldmarschall des Königs und wurde 1656 in den Grafenstand erhoben. Anlass genug, Schloss Étoges ab 1661 auf den mittelalterlichen Fundamenten neu zu gestalten. Im Schloss findet sich noch heute das Porträt seines Sohnes Marc Antoine Saladin d’Anglure du Bellay de Savigny, Graf von Étoges. Mit dessen Erbe Charles Nicolas endet die Linie der Herren aus dem Haus Anglure. 1718 wechselte die Grafschaft mit 1500 Hektar Grund und Wald den Besitzer. Der Sohn des Marschalls von Frankreich, Louis-François de Boufflers, wurde der neue Hausherr von Étoges. Bouffler verlegte den Schlosseingang in südliche Richtung. 1725 brach die alte Zugbrücke unter dem Gewicht der Kutsche der Königin Maria Leszczyńska zusammen. Bouffler ließ daraufhin eine neue Steinbrücke mit vier Bögen gestalten, die heute noch benutzt wird. Im 18. Jahrhundert wechselten die Besitzer in meist kurzer Folge.","w":"https://de.wikipedia.org/wiki/Schloss_%C3%89toges"},"ch-Q2247151":{"c":"Burg in Frankreich"},"ch-Q2248518":{"c":"Burg in Frankreich"},"ch-Q2249735":{"c":"Burg in Frankreich"},"ch-Q2265940":{"c":"Burg in Frankreich"},"ch-Q2270419":{"c":"Burg in Frankreich"},"ch-Q2278738":{"c":"Burg in Frankreich"},"ch-Q2291874":{"c":"Burg in Frankreich"},"ch-Q2304441":{"c":"Burg in Frankreich"},"ch-Q2342721":{"c":"Burg in Frankreich"},"ch-Q2969732":{"c":"Schloss in Frankreich"},"ch-Q2969730":{"n":"Wasserschloss Longpra","c":"Schloss in Frankreich"},"ch-Q2969737":{"c":"Burg in Frankreich"},"ch-Q2969743":{"n":"Schloss Louvois","c":"Schloss in Frankreich","r":"Das Schloss Louvois ist ein Schloss in Louvois in der Gemeinde Val de Livre im Département Marne.","h":"Eine erste Burg entstand in Louvois Anfang des 13. Jahrhunderts als einfache Grundherrschaft, die Gaucher V. de Châtillon und später der Familie de Cramaille gehörte. Aus dieser Zeit sind noch die Wassergräben, die Keller und das Gefängnis erhalten. Als Michel Le Tellier, Marquis de Barbezieux und Kriegsstaatssekretär des jungen Königs Ludwig XIV., das Anwesen erwarb, wurde es in ein Marquisat umgewandelt und gehörte später zusammen mit mehreren Hektar Weinbergen und zahlreichen Wäldern zur Hochzeitsausstattung seines Sohnes François Michel Le Tellier de Louvois. Als Koordinator des Baus des Versailler Schlosses nach Colberts Tod, ließ letzterer sich ein prächtiges Schloss nach Plänen von Mansart mit einem fünfzig Hektar großen Park bauen, der von Michel Le Bouteux, einem Schüler von Le Nôtre, entworfen wurden. Terrassierungen und drei Kilometer Rohrleitungen leiteten das Wasser vom Ortsteil Vertuelles und der Fontaine fraîche in das große obere Becken, das wiederum das 60-Fuß-Becken auf der Terrasse speiste; die vier seitlichen Becken wurden unter der Leitung von Sébastien Le Prestre de Vauban und der Schweizergarde als Arbeitskräften errichtet. Infolge von Schicksalsschlägen ging das Gut 1776 in den Besitz von Adélaide und Sophie de France über, zwei der Töchter des Königs Ludwig XV.; es wurde daraufhin zum Herzogtum und Pairie erhoben. Als das Schloss in dieser Zeit unter dem Namen Château des Dames de France bekannt war, wurde der Architekt Nicolas Durand für Arbeiten am Schloss herangezogen[3]. Während der Revolution wurde das Anwesen zerstört. Es blieben nur die Grundmauern, das Eingangstor, die Orangerie, die Gräben, das Tugendgadin, die Wasserleitung und die großen Teiche erhalten. An seiner Stelle wurde im 19.","w":"https://de.wikipedia.org/wiki/Schloss_Louvois"},"ch-Q2969782":{"c":"Schloss in Frankreich"},"ch-Q2969760":{"c":"Schloss in Frankreich"},"ch-Q2382970":{"n":"Palais de Charlemagne","c":"Palast in Frankreich","r":"Der Palais de Charlemagne in Attigny, einer französischen Gemeinde im Département Ardennes in der Region Grand Est, ist ein Bauwerk, das an der Stelle einer karolingischen Königspfalz im 16. Jahrhundert errichtet wurde.","w":"https://de.wikipedia.org/wiki/Palais_de_Charlemagne"},"ch-Q2383169":{"c":"Burg in Frankreich"},"ch-Q2971092":{"c":"Schloss in Frankreich"},"ch-Q2971073":{"c":"Burg in Frankreich"},"ch-Q2971136":{"n":"Schloss La Baume","c":"Schloss in Prinsuéjols-Malbouzon, Département Lozère, Okzitanien, Frankreich","r":"Das Schloss La Baume (Château de la Baume) liegt in der kleinen südfranzösischen Gemeinde Prinsuéjols im Département Lozère in der Region Okzitanien. Mit seiner Höhenlage von 1150 Metern auf dem Hochplateau des Aubrac im Zentralmassiv ist es eines der am höchsten gelegenen Schlösser Frankreichs.","w":"https://de.wikipedia.org/wiki/Schloss_La_Baume"},"ch-Q2971137":{"c":"Schloss in Frankreich"},"ch-Q2971164":{"c":"Schloss in Frankreich"},"ch-Q2971110":{"c":"Burg in Frankreich"},"ch-Q2971166":{"c":"Burg in Frankreich"},"ch-Q2971172":{"c":"Burg in Frankreich"},"ch-Q2970727":{"c":"Burg in Frankreich"},"ch-Q2970739":{"c":"Burg in Frankreich"},"ch-Q2970762":{"c":"Burg in Frankreich"},"ch-Q2970756":{"c":"Schloss in Frankreich"},"ch-Q2970811":{"c":"Burg in Frankreich"},"ch-Q1988879":{"c":"Burg in Frankreich"},"ch-Q1993975":{"c":"Burg in Frankreich"},"ch-Q1997741":{"c":"Burg in Frankreich"},"ch-Q2005028":{"c":"Burg in Frankreich"},"ch-Q2040732":{"c":"Burg in Frankreich"},"ch-Q2052946":{"c":"Schloss in Frankreich"},"ch-Q2060454":{"c":"Burg in Frankreich"},"ch-Q2068910":{"c":"Burg in Frankreich"},"ch-Q2072054":{"c":"Burg in Frankreich"},"ch-Q2075590":{"c":"Burg in Frankreich"},"ch-Q2084520":{"c":"Burg in Frankreich"},"ch-Q2085994":{"c":"Burg in Frankreich"},"ch-Q2090672":{"c":"Burg in Frankreich"},"ch-Q2093669":{"c":"Burg in Frankreich"},"ch-Q2094518":{"c":"Burg in Frankreich"},"ch-Q2242372":{"n":"Schloss Maupas","c":"Schloss in Frankreich","r":"Das Schloss Maupas liegt in der Gemeinde Morogues im französischen Département Cher inmitten eines Weinanbaugebietes. Erbaut wurde es im 15. Jahrhundert für den Gouverneur Berry und gelangte im 18. Jahrhundert in den Besitz der Familie Maupas: Antoine Agard, der zur Garde Ludwigs XV. gehörte, wurde 1725 vom König geadelt und trug seither den Titel Marquis de Maupas. Auch unter Napoleon zeichnete sich die Familie aus, die das Schloss noch heute bewohnt.","w":"https://de.wikipedia.org/wiki/Schloss_Maupas"},"ch-Q2242391":{"n":"Schloss Menetou-Couture","c":"Schloss in Frankreich","r":"Das Schloss Menetou-Couture gehört zur Gemeinde Menetou-Couture im französischen Département Cher und besteht aus einem mittelalterlichen Donjon aus dem Jahr 1460 sowie einem Wohngebäude aus dem späten 15. Jahrhundert. Die sonstigen Anbauten gehen auf die Mitte des 18. Jahrhunderts zurück.","w":"https://de.wikipedia.org/wiki/Schloss_Menetou-Couture"},"ch-Q2456478":{"c":"Burg in Frankreich"},"ch-Q2458579":{"c":"Burg in Frankreich"},"ch-Q2461512":{"c":"Burg in Frankreich"},"ch-Q2511495":{"c":"Burg in Frankreich"},"ch-Q2470077":{"c":"Burg in Frankreich"},"ch-Q2511903":{"n":"Château de Brécy","c":"Schloss im Departement Calvados in Frankreich"},"ch-Q2517770":{"c":"Burg in Frankreich"},"ch-Q2540016":{"c":"Burg in Frankreich"},"ch-Q2553023":{"c":"Burg in Frankreich"},"ch-Q2567187":{"c":"Burg in Frankreich"},"ch-Q2583763":{"c":"Burg in Frankreich"},"ch-Q2593302":{"c":"Burg in Frankreich"},"ch-Q2599121":{"c":"Burg in Frankreich"},"ch-Q2665983":{"c":"Burg in Frankreich"},"ch-Q2673929":{"c":"Burg in Frankreich"},"ch-Q2971541":{"c":"Burg in Frankreich"},"ch-Q2971549":{"n":"Kloster Les Rosiers","c":"Burg in Frankreich","r":"Das Kloster Les Rosiers war von 1241 bis 1791 zuerst eine Abtei der Zisterzienserinnen, ab 1389 ein Priorat der Zisterzienser in Séchault, Kanton Attigny, Arrondissement Vouziers, Département Ardennes in Frankreich.","h":"Südlich Monthois (zwischen den Dörfern Challerange und Séchault, am Bach Alin), unweit des Zisterzienserklosters Chéry, stiftete Balduin von Autry das Nonnenkloster Notre-Dame des Rosiers (auch: Roziers oder Rozières, von französisch roseau „Schilfrohr“), das zuerst mit Schwestern der Benediktinerinnenabtei Avenay besiedelt wurde und nachweislich ab 1241 zisterziensische Abtei war. 1244 gründete der Konvent bei Reims, wo er ein Haus besaß, das Kloster Clairmarais. 1389 wurde die Abtei durch ein Mönchskloster ersetzt, das als Priorat des Klosters Clairvaux bis zu seiner Auflösung durch die Französische Revolution bestand. Die noch verbliebenen gotischen Gebäudereste, darunter das 47 Meter lange Kirchenschiff, werden als „Schloss Roziers“ (Wohngebäude) privat genutzt und stehen seit 1956 unter Denkmalschutz.","w":"https://de.wikipedia.org/wiki/Kloster_Les_Rosiers"},"ch-Q2971574":{"c":"Schloss in Frankreich"},"ch-Q3662632":{"c":"Schloss in Frankreich"},"ch-Q2971187":{"c":"Schloss in Frankreich"},"ch-Q3533460":{"c":"Burg in Frankreich"},"ch-Q3535527":{"c":"Burg in Frankreich"},"ch-Q5118788":{"c":"Burg in Frankreich"},"ch-Q5118792":{"c":"Burg in Frankreich"},"ch-Q5118789":{"c":"Burg in Frankreich"},"ch-Q5118803":{"c":"Burg in Frankreich"},"ch-Q5118804":{"c":"Burg in Frankreich"},"ch-Q5118814":{"c":"Burg in Frankreich"},"ch-Q5118821":{"c":"Schloss in Frankreich"},"ch-Q5118853":{"c":"Schloss in Frankreich"},"ch-Q5118857":{"c":"Burg in Frankreich"},"ch-Q5118874":{"c":"Burg in Frankreich"},"ch-Q5118707":{"c":"Burg in Frankreich"},"ch-Q5118759":{"c":"Burg in Frankreich"},"ch-Q5118762":{"c":"Burg in Frankreich"},"ch-Q5118763":{"c":"Burg in Frankreich"},"ch-Q5118766":{"c":"Burg in Frankreich"},"ch-Q5118791":{"c":"Burg in Frankreich"},"ch-Q15940289":{"c":"Burg in Frankreich"},"ch-Q5118783":{"c":"Schloss in Frankreich"},"ch-Q15940291":{"c":"Burg in Frankreich"},"ch-Q15940331":{"c":"Burg in Frankreich"},"ch-Q15940436":{"c":"Burg in Frankreich"},"ch-Q15940488":{"c":"Burg in Frankreich"},"ch-Q15940474":{"n":"Château de Salveterra","c":"Burg in Frankreich"},"ch-Q15940494":{"c":"Burg in Frankreich"},"ch-Q15940501":{"c":"Burg in Frankreich"},"ch-Q15940548":{"c":"Schloss in Frankreich"},"ch-Q12257359":{"c":"Burg in Frankreich"},"ch-Q12258150":{"c":"Schloss in Frankreich"},"ch-Q12261996":{"c":"Burg in Frankreich"},"ch-Q6506698":{"c":"Schloss in Frankreich"},"ch-Q15940111":{"n":"Schloss Osthausen","c":"Wasserschloss im Stil der Renaissance in Osthouse, Bas-Rhin, Elsass, Frankreich","r":"Das Schloss Osthausen ist ein renaissancezeitliches Wasserschloss im elsässischen Ort Osthouse im Département Bas-Rhin.","h":"Osthouse gehörte im 14. Jahrhundert zum Territorium der Reichsritterschaft. Kaiser Sigismund verlieh eine Hälfte des Ortes im Jahr 1436 an Rudolf Zorn. Sechs Jahre später erhielt Nikolaus Zorn von Bulach die andere Hälfte von Kaiser Friedrich III. Schon zuvor besaß deren Familie dort Eigentum, denn am rechten Ufer der Ill existierte bis 1968 noch der Hügel einer hochmittelalterlichen Motte, die ein Allodial der Zorn von Bulach war. Die Familie entstammte ursprünglich dem Straßburger Patriziat und stellte dort zahlreiche Stadtmeister. Zwischen 1442 und 1457 begann sie mit dem Neubau eines Schlosses auf den Fundamenten einer Vorgängeranlage, die wahrscheinlich noch aus dem 14. Jahrhundert stammte. Nach Fertigstellung des Schlosses gaben die Zorn von Bulach ihre alte Turmhügelburg am gegenüberliegenden Flussufer im 15. Jahrhundert auf. Für 1457 ist nicht nur das Gebäude, sondern auch ein Fischergarten genannter Fischteich und ein Gemüsegarten verbürgt. Georg Zorn von Bulach, Kaiserlicher Rat unter Karl V., veränderte den Bau seiner Vorfahren 1558 und fügte ihm 1552 oder 1570 im rechten Winkel einen zweiten Gebäudeflügel an. Die Innenräume dieses zweiten Flügels wurden im 18. Jahrhundert unter Anton-Joseph Zorn von Bulach, dem diplomatischen Berater des Kardinals Louis René Édouard de Rohan-Guéméné, im damaligen Geschmack der Zeit modernisiert und erhielten ein neues Dach. Während des Zweiten Kaiserreichs war der Baron Zorn von Bulach Kammerherr des Kaisers Napoleon III. und empfing auf seinem Schloss Osthausen die Kaiserin Eugénie. Zu diesem Anlass schenkte er ihr als Andenken die bekannte Bronzestatue ihres Sohns Napoléon Eugène Louis mit seinem Hund Nero von Jean-Baptiste Carpeaux, die heute im Schloss Compiègne zu sehen ist.","w":"https://de.wikipedia.org/wiki/Schloss_Osthausen"},"ch-Q15940123":{"n":"Schloss Belbeuf","c":"Schloss in Frankreich","r":"Das Schloss Belbeuf ist eine Schlossanlage in der französischen Gemeinde Belbeuf im Département Seine-Maritime. Erbaut wurde es für Jean Pierre Prosper Godart de Belbeuf (1725–1811), Generalstaatsanwalt der Normandie.","h":"Das Gebäude wechselte im Eigentum an den Sohn Louis-Pierre-François Godart de Belbeuf († 1832) und nachfolgend an den Enkel Antoine-Louis-Pierre-Joseph Godart de Belbeuf. Durch Erbschaft gelangte dann an die Familie Mathan. Im Zweiten Weltkrieg wurde das Gebäude durch den Panzerkommandanten Michael Wittmann requiriert. Das Gebäude wurde während des Krieges schwer beschädigt und nach dem Krieg für die Unterbringung von Flüchtlingen genutzt. Es erfolgte ein Teileinsturz im Jahr 1956. 1957 wurde das Grundstück mit dem Schloss versteigert und von der Axa bzw. ihrem Rechtsvorgänger „Ancienne Mutuelle de Rouen“ erworben. 2020 erwarb der Unternehmer Paul Marius, der die Restaurierungsarbeiten fortsetzte. Seit 2024 kann das Schloss für Veranstaltungen gemietet werden.","w":"https://de.wikipedia.org/wiki/Schloss_Belbeuf"},"ch-Q15940135":{"c":"Burg in Frankreich"},"ch-Q15940143":{"n":"Château des Ternes","c":"Schloss in Frankreich"},"ch-Q15940171":{"c":"Schloss in Frankreich"},"ch-Q15940180":{"c":"Schloss in Frankreich"},"ch-Q15940219":{"n":"Château de Ménilmontant","c":"Schloss in Frankreich"},"ch-Q15940250":{"c":"Burg in Frankreich"},"ch-Q15944416":{"c":"Burg in Frankreich"},"ch-Q15944412":{"c":"Burg in Frankreich"},"ch-Q15944458":{"c":"Burg in Frankreich"},"ch-Q15944486":{"c":"Burg in Frankreich"},"ch-Q15945427":{"n":"Schloss Dampierre","c":"Schloss im Département Nord, Frankreich","r":"Das Schloss Dampierre in Anzin, einer französischen Stadt im Département Nord in der Region Hauts-de-France, wurde Ende des 19. Jahrhunderts errichtet. Das Schloss mit der Adresse 41 bis boulevard Dampierre wurde 2009 als Monument historique in die Liste der Baudenkmäler in Frankreich aufgenommen.","w":"https://de.wikipedia.org/wiki/Schloss_Dampierre_(Anzin)"},"ch-Q15944193":{"c":"Burg in Frankreich"},"ch-Q15944488":{"c":"Burg in Frankreich"},"ch-Q15944503":{"n":"Schloss La Tour-d’Aigues","c":"Schloss im Département Vaucluse, Frankreich","r":"Vom Schloss La Tour-d’Aigues in der französischen Gemeinde La Tour-d’Aigues in der Provence sind seit einem verheerenden Brand im Jahr 1780 nur noch Ruinen übrig. Es ist seit 1984 als Monument historique denkmalgeschützt.","w":"https://de.wikipedia.org/wiki/Schloss_La_Tour-d%E2%80%99Aigues"},"ch-Q17354299":{"n":"Schloss Belmont","c":"Schloss in Frankreich","r":"Das Schloss Belmont in Andilly, einer französischen Gemeinde im Département Val-d’Oise in der Region Île-de-France, wurde Ende des 16. Jahrhunderts errichtet.","h":"Das zweigeschossige Schloss mit Dachausbau an der Nr. 4 rue Aristide-Briand wechselte öfters den Besitzer und gehörte von 1817 bis 1824 der Herzogin Claire de Duras. Danach wurde es an Talleyrand verkauft, der es seiner Nichte und Mätresse Dorothée de Courlande überließ. Im Laufe des 19. Jahrhunderts wurde das Gebäude im Inneren wesentlich verändert. Nach 1945 diente es als Hotel und heute ist das ehemalige Schloss in mehrere Wohnungen unterteilt.","w":"https://de.wikipedia.org/wiki/Schloss_Belmont_(Andilly)"},"ch-Q17354301":{"c":"Schloss in Frankreich"},"ch-Q17102428":{"c":"Schloss in Frankreich"},"ch-Q17399996":{"c":"Schloss in Frankreich"},"ch-Q17402104":{"c":"Schloss in Frankreich"},"ch-Q17402098":{"n":"Burg Montmorin","c":"Burg im Département Puy-de-Dôme, Auvergne-Rhône-Alpes, Frankreich","r":"Die Burg Montmorin ist eine französische Festung, die im 12. und 13. Jahrhundert in der Gemeinde Montmorin erbaut wurde. Die Burgruine ist als historisches Denkmal gelistet und Erbe der Adelsfamilie Montmorin.","h":"Die spätromanische Burganlage wurde im 12./13. Jahrhundert errichtet und im Laufe der Jahrhunderte zu einer Verteidigungsanlage ausgebaut. Im Jahr 1634 wurde die Festung auf Befehl von Kardinal Richelieu, der als Staatsmann im Dienst der französischen Krone handelte, zerstört. Sie galt als Zentrum des Widerstands gegen die königliche Autorität in Frankreich. Heute ist die Burg Montmorin teilweise restauriert und steht seit 1985 unter Denkmalschutz. Sie stellt ein bedeutendes Kulturerbe der Familie Montmorin aus Saint-Hérem dar. Die Familie ist einer der einflussreichsten Adelsdynastien der Auvergne und nutzt einen Teil der Burg bis heute als private Residenz.","w":"https://de.wikipedia.org/wiki/Burg_Montmorin"},"ch-Q17624824":{"c":"Schloss in Frankreich"},"ch-Q17624872":{"n":"Schloss Le Breuil-en-Auge","c":"Schloss im Département Calvados, Frankreich","r":"Das Château du Breuil-en-Auge, ein Herrensitz aus dem 16. Jahrhundert, befindet sich in der Gemeinde Le Breuil-en-Auge im Département Calvados in der Region Normandie. In den früheren Wirtschaftsgebäuden wurde im 20. Jahrhundert eine Brennerei zur Verarbeitung der hier in der Umgebung angebauten speziellen Apfelzüchtungen eröffnet. Es ist seit 1933 als Monument Historique eingetragen.","h":"Die Adelsfamilie Bouquetot mit dem Ritter Jean dem Dritten Bouquetot wurde im 16. Jahrhundert erster Besitzer der Anlage von Breuil (und Rabu). Jean Bouquetot ließ ein dreiflügeliges mehretagiges Wohngebäude errichten. Als Nächstes erbte seine Tochter Suzanne das Anwesen, die den Grafen Gabriel (den zweiten) de Montgomery heiratete. Sie blieben von 1611 bis 1658 Eigentümer des Schlosses. Es folgten weitere Besitzer wie Tancrède de Rohan oder die Familie Bence (1696 bis 1734). Um das Jahr 1950 erwarb der Schweizer Konzern Diwisa die Schlossanlage und begann 1954 mit der Herstellung von Calvados. Im April 2020 kaufte eine französische Investorengruppe die gesamte Anlage und führte die Calvados-Herstellung intensiv weiter. Die Bewirtschaftung wurde der Familie Frédéric Dussart als CEO übertragen, der seinen Partner Roberto Montesano dazuholte.","w":"https://de.wikipedia.org/wiki/Schloss_Le_Breuil-en-Auge"},"ch-Q17624875":{"c":"Schloss in Frankreich"},"ch-Q15943950":{"n":"Schloss Beaujeu (Haute-Saône)","c":"Burg in Frankreich","r":"Die Burg Beaujeu ist der übriggebliebene Bergfried einer ehemaligen Höhenburg in Beaujeu-Saint-Vallier-Pierrejux-et-Quitteur im Département Haute-Saône (Franche-Comté).","w":"https://de.wikipedia.org/wiki/Burg_Beaujeu_(Haute-Sa%C3%B4ne)"},"ch-Q14401833":{"n":"Schloss Ansouis","c":"Schloss in der Provence","r":"Das Schloss Ansouis steht auf einem Felsen im Tal der Eygues im Herzen der Provence über der französischen Ortschaft Ansouis. Die Schlossanlage geht auf eine mittelalterliche Burg zurück, die über die Jahrhunderte ausgebaut und verändert wurde. Im 17. und 18. Jahrhundert erfolgte ihre Umgestaltung zu einer wohnlichen Residenz der Familie de Sabran. Sie steht seit dem 10. Mai 1948 als klassifiziertes Monument historique unter Denkmalschutz. Teile des Schlosses können von April bis Oktober im Rahmen einer Führung besichtigt werden, wovon rund 15.000 Besucher alljährlich Gebrauch machen.","h":"Eine Burg in Ansouis wurde als Castrum quae dicitur Ansoyse erstmals in einer von Boso II., Graf von der Provence, ausgestellten Urkunde aus dem Jahr 960 schriftlich erwähnt. Zu jener Zeit war sie Eigentum der Grafen von Forcalquier und bestand lediglich aus einem steinernen Wohnturm. Grabungsfunde zeigten allerdings, dass an diesem Ort schon zu römischer Zeit eine Befestigung existierte, die castrum de Ansoissis genannt wurde. Eine vier Kilometer lange Wasserleitung aus jener Zeit ist noch erhalten und versorgt heute noch das Schloss mit Wasser. Durch die Heirat Garsindes, der Erbtochter Guillaumes IV. de Forcalquier, mit Raymond I. de Sabran kam die Burg 1178 an die Familie des Bräutigams. Die Tochter des Paars heiratete Alfons II., Graf der Provence, und war die Großmutter von Margarete, Eleonore, Sancha und Beatrix von der Provence, die alle Könige heirateten. Über diese vier Frauen hatte die Familie de Sabran verwandtschaftliche Beziehungen zu vielen europäischen Königshäusern. Im Laufe des 11./12., 13. und 15. Jahrhunderts erweiterten die Burgherren ihre Anlage mit zusätzlichen Gebäuden, mit denen sie den Wohnturm umgaben, sodass die Burg schließlich einen viereckigen Grundriss besaß und an allen Ecken durch Wehrtürme gesichert war. 1285 kam dort Elzéar von Sabran zur Welt, der im noch jugendlichen Alter 1299 mit Delphine de Puy-Michel verheiratet wurde. Das fromme Paar gelobte sich ewige Keuschheit und vollbrachte viele gute Taten und Wunder in der Umgegend, sodass Elzéar 1371 heilig- und seine Frau seliggesprochen wurde. 1358 durch die Grandes Compagnies zerstört, wurde die Burg anschließend wieder aufgebaut. Während der französischen Religionskriege des 16. Jahrhunderts befand sich die Anlage abwechselnd in der Hand von Hugenotten und Katholiken.","w":"https://de.wikipedia.org/wiki/Schloss_Ansouis"},"ch-Q14420304":{"c":"Schloss in Frankreich"},"ch-Q15210487":{"c":"Burg in Frankreich"},"ch-Q15622256":{"c":"Burg in Frankreich"},"ch-Q15695629":{"n":"Rathaus Gournay-sur-Marne","c":"Rathaus im Département Seine-Saint-Denis, Frankreich","r":"Das Rathaus in Gournay-sur-Marne, einer französischen Gemeinde im Département Seine-Saint-Denis in der Region Île-de-France, wurde 1670 errichtet. Das Rathaus steht seit 1945 als Monument historique auf der Liste der Baudenkmäler in Frankreich.","w":"https://de.wikipedia.org/wiki/Rathaus_Gournay-sur-Marne"},"ch-Q15677956":{"n":"Schloss Les Caramans","c":"Schloss in Frankreich","r":"Das Schloss Les Caramans in Roissy-en-France, einer Gemeinde im Département Val-d’Oise in der französischen Region Île-de-France, wurde Anfang des 18. Jahrhunderts errichtet. Seit 1925 stehen die Reste des Schlosses an der Allée du Verger als Monument historique auf der Liste der Kulturdenkmäler in Frankreich.","h":"Das klassizistische Schloss wurde für Jean-Antoine de Mesmes, comte d’Avaux, nach den Plänen des schwedischen Architekten Nicodemus Tessin der Jüngere errichtet. Das ab 1703 begonnene Schloss steht an der Stelle eines Vorgängerbaus. Der zweigeschossige Bau mit Mansarddach bestand aus drei Pavillons, die durch Galerien miteinander verbunden waren. Während der Französischen Revolution wurde im Jahr 1794 das Schloss geplündert und zum größten Teil zerstört. Heute sind nur noch die Ostmauer und das südliche Portal der Orangerie vorhanden. Dieses wird von einem Giebeldreieck mit Relief, der auf Pilastern ruht, geschmückt.","w":"https://de.wikipedia.org/wiki/Schloss_Les_Caramans"},"ch-Q15844431":{"n":"Schloss Beaumont-du-Gâtinais","c":"Schloss in Frankreich","r":"Das Schloss von Beaumont-du-Gâtinais, einer Gemeinde im Département Seine-et-Marne in der französischen Region Île-de-France, wurde, vermutlich an der Stelle eines Vorgängerbaus aus dem späten 15. Jahrhundert, in der ersten Hälfte des 17. Jahrhunderts errichtet. Zu Beginn des 19. Jahrhunderts wurde es teilweise abgerissen. 1984 wurden die Überreste als Monument historique in die Liste der Baudenkmäler in Frankreich aufgenommen. Die Gebäude sind heute zum Teil in Privatbesitz und zum Teil im Besitz der Gemeinde.","h":"Im 15. Jahrhundert war Jacques Cœur, der Schatzkanzler des französischen Königs Karl VII., Grundherr von Beaumont. 1493 ging durch die Heirat seiner Enkelin mit Louis de Harlay die Grundherrschaft an die Familie de Harlay über. 1572 erbte sie Achille de Harlay, Erster Präsident des Parlements von Paris. Aus Dankbarkeit für seine Dienste erhob der französische König Heinrich IV. die Seigneurie Beaumont zur Grafschaft, was wohl den Ausschlag für den Bau des Schlosses gab. In der Folge der Französischen Revolution wurde das Schloss 1798 verkauft und 1804 teilweise abgerissen.","w":"https://de.wikipedia.org/wiki/Schloss_Beaumont-du-G%C3%A2tinais"},"ch-Q15840207":{"n":"Petit Château","c":"Schloss in Frankreich","r":"Das Petit Château in Eaubonne, einer Gemeinde im Département Val-d’Oise in der französischen Region Île-de-France, wurde von 1772 bis 1776 errichtet. Seit 1967 steht das Schloss am Boulevard du Petit-Château Nr. 14 als Monument historique auf der Liste der Kulturdenkmäler in Frankreich.","h":"Das Schloss wurde nach Plänen des Architekten Claude-Nicolas Ledoux (1736–1806) errichtet, der es in seinem 1804 erschienenen Werk L’Architecture considerée sous le rapport de l’art, des moeurs et de la législation beschrieb und die Pläne darin veröffentlichte. Im klassizistischen Schloss wohnten bekannte Persönlichkeiten wie Louis-Jérôme Gohier und Merlin de Thionville. Das Gebäude, das 1926 in mehrere Wohnungen aufgeteilt wurde, dient heute der Sécurité sociale (Sozialversicherung) als Büro.","w":"https://de.wikipedia.org/wiki/Petit_Ch%C3%A2teau_(Eaubonne)"},"ch-Q16008578":{"c":"Schloss in Frankreich"},"ch-Q22915915":{"c":"Schloss in Frankreich"},"ch-Q18578152":{"c":"Schloss in Frankreich"},"ch-Q22915821":{"c":"Schloss in Frankreich"},"ch-Q22922949":{"c":"Schloss in Frankreich"},"ch-Q15944299":{"n":"Château Porgès de Rochefort-en-Yvelines","c":"Schloss in Frankreich"},"ch-Q15944304":{"c":"Schloss in Frankreich"},"ch-Q22916450":{"n":"Burg Grimaud","c":"Schloss in Frankreich","r":"Die Burg Grimaud ist die Ruine einer mittelalterlichen Höhenburg in Frankreich. Sie erhebt sich auf einem Hügel, der den Ort Grimaud im Département Var etwas überragt.","h":"Der Standort der Burg war schon in der Antike besiedelt. Bereits im 11. Jahrhundert wurden Burg und Ortschaft als castri nomine Grimaldi et Grimaldo castello schriftlich erwähnt. Über den Erbauer der Anlage gibt es unterschiedliche Aussagen. Einige Publikationen geben den Ritter Gibelin de Grimaldi, möglicherweise aus einer Nebenlinien des heutigen monegassischen Fürstenhauses, als Bauherrn an, während andere Historiker den Erbauer in einem Lokalherrn namens Grimaldus sehen. Die Burg war seit jener Zeit Mittelpunkt eines Besitzes, der ein provencalisches Lehen war. Um 1246 kam die Burg an die Familie Pontevès, für die sie zur Baronie erhoben wurde. Unruhige Zeiten am Ende des 13. und zu Beginn des 14. Jahrhunderts machten es erforderlich, die Anlage und das sie umgebende Dorf stärker zu bewehren. Entsprechend wurde die heutige Ringmauer errichtet, für die zuvor einige Behausungen der Dörfler weichen mussten. Über die Familie Adorne, der im 14. Jahrhundert die Burg gehörte, kam diese im 15. Jahrhundert an die Familie Cossa, denn 1441 belehnte René I. von Anjou seinen Großseneschall Jean de Cossa mit der Anlage. Dieser ließ Veränderungen an ihr vornehmen. So wurde zum Beispiel das Erdgeschoss eines Wehrturms zu einer Zisterne mit 85 Kubikmetern Fassungsvermögen umgewandelt. 1485 vergab der französische König Karl VIII. Burg und Dorf an seinen Kammerherrn Étienne de Vesc, dessen Familie bis in das 16. Jahrhundert Besitzerin blieb. Jedoch nutzten sie die Anlage nur selten. Nach 1555 kamen Burg und Baronie an die Familie Agoult. Durch Heirat von Jeanne dʼAgoult-Montauban mit Claude François de La Baume, Graf von Montrevel, gelangte der Besitz 1602 an dessen Familie. Ihre Tochter Marie heiratete 1627 Esprit Allard, einen Günstling des Königs Ludwig XIII.","w":"https://de.wikipedia.org/wiki/Burg_Grimaud"},"ch-Q22924337":{"c":"Schloss in Frankreich"},"ch-Q22919211":{"c":"Schloss in Frankreich"},"ch-Q22924986":{"n":"Schloss Catuelan","c":"Schloss der Bretagne"},"ch-Q22951753":{"c":"Schloss in Frankreich"},"ch-Q22925193":{"c":"Schloss in Frankreich"},"ch-Q22951759":{"c":"Schloss in Frankreich"},"ch-Q22951875":{"c":"Schloss in Frankreich"},"ch-Q22951930":{"n":"Schloss Esneval","c":"Schloss in Frankreich","r":"Das Schloss Esneval ist eine Schlossanlage in der französischen Stadt Pavilly in der Normandie. Es geht auf eine Anlage zurück, die Robert de Dreux als Nachfolgerin einer im Hundertjährigen Krieg stark beschädigten Burg errichten ließ. Sein heutiges Aussehen erhielt das Schloss aber erst im 18. Jahrhundert unter Pierre-Robert Le Roux. Es steht als klassifiziertes Monument historique seit dem 2. März 1970 unter Denkmalschutz. Die Anlage ist in Privatbesitz und wird als Wohnsitz genutzt, sie kann deshalb nicht besichtigt werden. Die Schlosskapelle ist aber jedes Jahr während der Journées Européennes du Patrimoine für Besucher geöffnet.","h":"Im Mittelalter herrschten zwei Familien über das Gebiet der heutigen Ortschaft Pavilly: zum einen eine alteingesessene Familie, die sich nach dem Ort „de Pavilly“ nannte, und zum anderen die Familie dʼEsneval. Letztere trat erst ab dem 10. Jahrhundert in Erscheinung, nachdem der französische König Karl III. im Vertrag von Saint-Clair-sur-Epte die Gebiete der heutigen Haute-Normandie und des Pays d’Auge an den Normannen Rollo abgetreten hatte. Seit jener Zeit standen diese beiden Familien in Konkurrenz zueinander, die erst im Jahr 1280 beendet wurde, als Robert dʼEsneval Marguerite de Pavilly, die Letzte ihrer Familie, heiratete. Die Esneval errichteten im 13. Jahrhundert eine kleine Burg samt Kapelle und durften sie mit Genehmigung des Königs Karl V. während des Hundertjährigen Kriegs stärker befestigen. Die Maßnahme konnte jedoch nicht verhindern, dass die Anlage während des Krieges von englischen Truppen eingenommen wurde. Der Burgherr hielt sich zu jener Zeit im Gefolge des französischen Königs in Bourges auf, als die Engländer seine Seigneurie besetzten und dort einen Gefolgsmann Heinrichs IV. von England einsetzten. Erst nach der Rückeroberung der Normandie durch Karl VII. im Jahr 1449 erhielt der rechtmäßige Eigentümer seinen Besitz zurück. Das war zu jener Zeit aber schon nicht mehr die Familie Esneval, sondern Robert de Dreux, denn 1404 hatte die Erbtochter Jeanne dʼEsneval Roberts Vater Gauvain II. de Dreux geheiratet und die Seigneurie damit an seiner Familie gebracht. Allerdings war die Burg der Esneval im Krieg derart stark beschädigt worden, dass sie nicht mehr bewohnbar war, und so ließ Robert de Dreux zwischen 1469 und 1478 eine Nachfolgeanlage errichten. Diese bestand aus einem mehrgeschossigen Rechteckbau mit sechseckigen Türmen an den Ecken.","w":"https://de.wikipedia.org/wiki/Schloss_Esneval"},"ch-Q18214371":{"c":"Schloss in Frankreich"},"ch-Q18046588":{"c":"Burg in Frankreich"},"ch-Q18380013":{"c":"Schloss in Frankreich"},"ch-Q18386999":{"c":"Burg in Frankreich"},"ch-Q19607188":{"c":"Schloss in Frankreich"},"ch-Q19693160":{"c":"Schloss in Frankreich"},"ch-Q21619055":{"c":"Park in Frankreich"},"ch-Q20669749":{"n":"Taubenturm Dampierre","c":"Schloss in Frankreich","r":"Der Taubenturm in Dampierre, einem Dorf der französischen Gemeinde Val de Drôme im Département Calvados in der Region Normandie, wurde Anfang des 17. Jahrhunderts errichtet. Der Taubenturm steht als Teil des Schlosses seit 1928 als Monument historique auf der Liste der Baudenkmäler in Frankreich.","w":"https://de.wikipedia.org/wiki/Taubenturm_Dampierre_(Calvados)"},"ch-Q20751508":{"n":"Château de La Verdière","c":"Schloss La Verdière"},"ch-Q21294421":{"c":"Palast in Frankreich"},"ch-Q16257812":{"c":"Schloss in Frankreich"},"ch-Q18736777":{"n":"Synodalpalast","c":"Palast in Frankreich","r":"Der Synodalpalast in Sens, einer französischen Stadt im Département Yonne der historischen Region Burgund, wurde im 13. Jahrhundert errichtet. Das Gebäude direkt neben der Kathedrale von Sens ist seit 1862 als Monument historique klassifiziert.","h":"Der Hauptsaal, der für Synoden genutzt wurde, besitzt eine Grundfläche von 500 Quadratmetern und eine Raumhöhe von 12 Metern. Im 19. Jahrhundert erfolgte die Restaurierung des Gebäudes unter Eugène Viollet-le-Duc.","w":"https://de.wikipedia.org/wiki/Synodalpalast_(Sens)"},"ch-Q18736811":{"n":"Château Théobon","c":"Schloss in der Region Nouvelle-Aquitaine, Frankreich","r":"Das Château de Théobon ist ein Schloss, das im 17. Jahrhundert aus dem Umbau einer Burg des 14. Jahrhunderts hervorging. Das Schlossgelände liegt auf einem Hügel («pech») im Gebiet der Gemeinde Loubès-Bernac und erlaubt einen weiten Blick in alle Richtungen.","h":"Um 1291 wurde Gaubert de Mayrac, seigneur de Théobon, erwähnt. Die Burg, die eine militärische Festung in englisch-französischen Kriegen gewesen war, wird in einer Urkunde von 1327 aufgeführt, in welcher Gaubert de Mayrac sich als Gutsherr (Seigneur) von Théobon bezeichnet. 1406 schwor Gassion de Mayrac dem Captal de Puychagut für Théobon Gefolgschaft, und die Familie Ségur trat im Laufe der Zeit als Seigneurs de Puychagut in Erscheinung. Im Jahr 1475 heiratete Ysabeau de Mayrac, de Théobon, den Giron de Ségur, Captal de Puychagut, womit die Herrschaft (Seigneurie) Théobon zum Ende des 15. Jahrhunderts in den Besitz der Familie Ségur wechselte. Im frühen 16. Jahrhundert wurde der wohlhabende Gaston de Ségur zum Grand Echanson des Königs Franz I. ernannt. Gaston ließ die alte Festung Théobon abreißen und ein Schloss im Stil der Renaissance erbauen. Der Besitz am Schloss und der Seigneurie Théobon ging dann durch Heirat auf die Familie Pierre-Buffière über. Ende des 16. Jahrhunderts gehörte die Burg der Familie Rochefort de Saint-Angel, und zwar seit der Heirat des Charles I. de Rochefort, Baron von Saint-Angel und Chambon, Seigneur von Bellegarde, am 5. März 1551 mit Moreille de Châteauneuf, Dame de Théobon, Baronin von Chabane, Tochter des Louis de Pierre-Buffière de Châteauneuf und der Isabeau de Ségur, Dame von Génissac und Gaillat. Aus dieser Ehe hatte Charles zwei Söhne. Der Ältere, Louis, war Baron von Saint-Angel, der Jüngere, Jean, auch Charles genannt, war Baron von Théobon. Dessen zweiter Sohn, Jean I. de Rochefort, Baron von Théobon, Captal von Puychagut, nahm als Protestant an der Verteidigung von Castillon 1586 teil. Er verheiratete sich am 6.","w":"https://de.wikipedia.org/wiki/Schloss_Th%C3%A9obon"},"ch-Q19406870":{"c":"Schloss in Frankreich"},"ch-Q22950387":{"n":"Schloss Chambray","c":"Schloss im Département Eure, Region Normandie, Frankreich","r":"Das Schloss Chambray ist ein Landschloss der Spätrenaissance und des frühen 17. Jahrhunderts. Es befindet sich in der Gemeinde Gouville im Département Eure in Frankreich. Das Anwesen steht seit dem 29. Oktober 1971 als Monument historique unter Denkmalschutz.","h":"Das Gut Chambray geht auf die Baronie von La Ferté-Fresnel zurück, deren Seitenlinie sich im 12. Jahrhundert in Chambray und Blandé niederließ. Stammvater war Simon I. de Chambray († vor 1210), Sohn von Richard II. de La Ferté-Fresnel und Emmeline de L’Aigle aus der Familie der Herren von L’Aigle. Nach mittelalterlichen Quellen bestand hier zunächst eine Burganlage mit vier Türmen und einer umlaufenden Wehrmauer. Sie wurde vermutlich um 1096 von Amaury de Chambray errichtet, einem Gefolgsmann des Herzogs Robert II. von der Normandie. Im 12. Jahrhundert ließ Simon I. de Chambray die zerstörte Burg seiner Vorfahren wiederaufbauen. Er errichtete eine rechteckige Anlage mit vier Rundtürmen, von denen zwei bis in das 19. Jahrhundert erhalten blieben. Die Kapelle Saint-Laurent, ein harmonisches Bauwerk des 13. Jahrhunderts, wurde 1239 von Simon II. de Chambray und seiner Gemahlin Eustache de Lombelon des Essarts errichtet und dem Kloster du Désert übergeben. Im 16. Jahrhundert ließ Gabriel de Chambray (1541–1612), Kammerherr Heinrichs III. und Gefolgsmann unter Heinrichs IV. bei der Schlacht von Ivry, das heutige Schloss als Neubau errichten anlässlich seiner Vermählung mit Jeanne d’Angennes. Sein Nachkomme Nicolas-François de Chambray (1675–1750) wurde unter Ludwig XIV. und Ludwig XV. zum ersten Marquis erhoben. Im 19. Jahrhundert war der General Georges de Chambray (1783–1848), Marquis de Chambray, eine der bekanntesten Persönlichkeiten der Familie. Er trat 1801 in die École polytechnique ein und diente anschließend in der kaiserlichen Artillerie. Er nahm an den Feldzügen von Boulogne, Ulm und Austerlitz sowie 1806 und 1807 in Pommern und 1812 in Russland teil, wo er in Gefangenschaft geriet.","w":"https://de.wikipedia.org/wiki/Schloss_Chambray"},"ch-Q22932438":{"c":"Schloss in Frankreich"},"ch-Q22950863":{"c":"Schloss in Frankreich"},"ch-Q22951074":{"n":"Burg Comborn","c":"Schloss im Département Corrèze, Frankreich","r":"Die Burg Comborn ist ein französisches Château im Département Corrèze in der Region Nouvelle-Aquitaine. Es handelt sich um einen Profanbau aus dem 11., 14., 15. und 17. Jahrhundert, und seit 1985 ist die Burg als Monument historique klassifiziert.","h":"Angelegt in einer Biegung des Flusses Vézère, war das Gelände der Burg Comborn schon seit der Antike besiedelt, wie durch Ausgrabungen 2002 belegt wurde. Das Château de Comborn, basiert auf einem alten Oppidum aus dem 9. Jahrhundert, der Wiege der Vizegrafschaft Comborn, einer der vier Vizegrafschaften des Bas-Limousin im 10. Jahrhundert, und war Sitz der Vizegrafen von Limoges im 12. und 13. Jahrhundert. Noch vor dem Jahr 1000 wurde der Umbau der früheren, aus Holz erbauten Festung, von der in heutiger Zeit einige Überbleibsel ausgegraben wurden, zu einer klassischen feudalen Burg in dem architektonischen Stil begonnen, wie man ihn öfters im Limousin findet. Im 11. Jahrhundert erfolgte die erstmalige Errichtung des steinernen Bergfrieds mit vier Stockwerken, von denen bis heute nur das erste erhalten blieb. Zudem wurden ab dem 12. Jahrhundert drei unterirdische Hallen erbaut. Die Burg wurde im 13. und 14. Jahrhundert im Zuge des Hundertjährigen Kriegs zerstört. Ab 1436 ließ Jean I. († nach 1475), 1415 Vicomte von Comborn und Seigneur von Treignac, einen bedeutenden Herrschaftssitz erbauen, ebenso wie eine Kapelle, die 1455 der heiligen Magdalena geweiht wurde. Reste dieser Bauten sind noch heute erhalten. Am Beginn des 16. Jahrhunderts ging die Herrschaft Comborn durch Heiraten an die Familie Pompadour, sodann an die Seigneurs von Pierre-Buffière und ab 1649 an den Marquis du Saillant. In der Mitte des 18. Jahrhunderts fiel die Burg Comborn einem Feuer zum Opfer. Der Palas wurde 1753 durch den damaligen Eigentümer, den Marquis du Saillant, rekonstruiert.","w":"https://de.wikipedia.org/wiki/Burg_Comborn"},"ch-Q22963850":{"c":"Schloss in Frankreich"},"ch-Q22963916":{"c":"Schloss in Frankreich"},"ch-Q22963920":{"c":"Schloss in Frankreich"},"ch-Q22963935":{"c":"Schloss in Frankreich"},"ch-Q22964202":{"n":"Château de la Tour (Saint-Pierre-Canivet)","c":"Schloss in Frankreich","r":"Das Château de la Tour ist ein vorrevolutionär klassizistisches Schloss in der französischen Gemeinde Saint-Pierre-Canivet in der Normandie. Die Schlossanlage befindet sich ca. 2,5 Kilometer westsüdwestlich vom Ortszentrum von Saint-Pierre-Canivet und ist über die Route départementale 6 von Falaise nach Le Hom erreichbar.","h":"1769 wurde das Gebäude nach den Entwürfen von Antoine Matthieu Le Carpentier für den Grafen Louis-François-Anne de Séran und dessen Frau Adélaïde de Bullioud, Gräfin von Séran, eine Mätresse Ludwigs XV., errichtet. Die Gräfin von Séran richtete hier Zusammenkünfte von berühmten Schriftstellern der damaligen Zeit ein. Die Domäne de la Tour ist umgeben von Wald. Östlich des Schlosses befindet sich das Ferme de la Tour. Heute wird die Domäne zur Vermietung von Ferienwohnungen und für Veranstaltungen genutzt. Das gesamte Areal befindet sich in Privatbesitz und kann grundsätzlich nicht besichtigt werden. Die Aufnahme in die Liste der Monuments historiques umfasst vom Schloss die Fassaden und Dächer, den Innenhof, den Graben, der den Haupthof umgibt sowie die Inneneinrichtung des Esszimmers, des Wohnzimmers und des Schlafzimmers.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_de_la_Tour_(Saint-Pierre-Canivet)"},"ch-Q22964257":{"c":"Schloss in Frankreich"},"ch-Q22964278":{"c":"Schloss in Frankreich"},"ch-Q22997268":{"c":"Schloss in Frankreich"},"ch-Q20971753":{"n":"Schloss Nanteuil","c":"Schloss in Frankreich","r":"Das Schloss Nanteuil war ein Schloss aus dem Mittelalter und der Renaissance in der Gemeinde Nanteuil-le-Haudouin (Oise) an der Straße von Paris nach Soissons. Heute sind die Hauptgebäude zerstört. Die meisten der ehemaligen Wirtschaftsgebäude des Schlosses sowie zwei Pavillons im Garten sind jedoch erhalten geblieben.","h":"Besitzer des Schlosses waren Die Grafen von Ponthieu Die Grafen von Crépy Das Haus Pacy Das Haus Broyes Das Haus Guise (1556–1576) Das Haus Schomberg (1578–1658) Das Haus Estrées (ab 1658) Das Haus Condé Henri de Lenoncourt († 1552), Ehemann von Marguerite de Broyes, erreichte 1543, dass König Franz I. Nanteuil zur Grafschaft erhob. Franz I. und sein Sohn Heinrich II. hielten sich mehrmals in Nanteuil auf und unterzeichneten dort mehrere Urkunden. François de Lorraine, Duc de Guise, zwang die Witwe des Grafen, ihm das Land und die Grafschaft Nanteuil zu verkaufen, der Connétable Anne de Montmorency half dem Herzog beim Abschluss dieses Geschäfts. Der Vertrag über diesen Zwangsverkauf stammt aus dem Jahr 1556 und nennt als Abtretungspreis 260.000 Livres. Diese Summe entsprach jedoch kaum den Arbeiten, die Henri de Lenoncourt am Schloss in Auftrag gegeben hatte. Der Herzog wohnte gewöhnlich in Nanteuil und empfing hier häufig die Könige Heinrich II., der im Schloss auch Staatsratssitzungen abhielt, und dessen Sohn Franz II. Mit dem Tod Franz II. gegen Ende des Jahres 1560 sahen die Guise dann ihre ehrgeizigen Pläne scheitern und zogen sich vom Hof zurück; der Duc de Guise richtete als Angehöriger des Triumvirats im Schloss Nanteuil jedoch eine Art Sitz dieser Gruppe ein. Henri de Lorraine, Duc de Guise, genannt le Balafré, übergab 1576 dem König Heinrich III. das Land und das Schloss Nanteuil und bat ihn, darüber zu verfügen. Der König behielt es zwei Jahre lang und schenkte es dann dem Offizier Gaspard de Schomberg († 1599), der es zu seinem Wohnsitz machte und am Schloss, das bereits sehr groß und reich verziert war, einige Erweiterungen vornahm. Dessen Sohn Henri de Schomberg besaß danach die Grafschaft und starb 1632.","w":"https://de.wikipedia.org/wiki/Schloss_Nanteuil"},"ch-Q21032415":{"n":"Burg Pont-l’Abbé","c":"Schloss in Frankreich","r":"Die Burg Pont-l’Abbé ist eine Burganlage in der bretonischen Stadt Pont-l’Abbé im Département Finistère. Sie wurde zwischen dem 13. und 18. Jahrhundert erbaut, ist aber heute nur noch in wenigen Teilen erhalten, denn die Mehrheit der Bausubstanz wurde im 19. Jahrhundert niedergelegt. Gegründet von den Herren von Pont, ging sie im Laufe ihrer Geschichte durch zahlreiche Hände. Seit 1836 gehört der bauliche Restbestand der Stadt Pont-l’Abbé. Dieser wird heute als Rathaus sowie Museum genutzt und steht als eingeschriebenes Monument historique seit dem 2. Dezember 1926 unter Denkmalschutz. Eine Außenbesichtigung ist jederzeit kostenlos möglich.","h":"Das Land um Pont-l’Abbé gehörte im Hochmittelalter zur Abtei Loctudy und war wie die gesamt Bretagne mehrfach Ziel von Normannenüberfällen bzw. von diesen besetzt. Als Æthelstan die Normannen vertrieben hatte, fand eine Familie den Landstrich verlassen vor und errichtete eine Motte auf einer kleinen Insel im Fluss Rivière de Pont-l’Abbé, direkt am Kopf eine dort befindlichen Brücke. Nach dieser nannten sich die Burgbesitzer fortan seigneurs du Pont (deutsch Herren von Pont). Erstes namentlich bekanntes Mitglied dieses seit dem 13. Jahrhundert urkundlich bekannten Geschlechts war Juhel. In der nachfolgenden Zeit konnten die Herren von Pont ihren Landbesitz und damit ihren Einflussbereich beträchtlich mehren. Im 13. Jahrhundert war die Seigneurie eine der größten der Bretagne und ihre Herren entsprechend mächtig. Mit Einverständnis der Abtei Loctudy ersetzten sie ihre Motte Ende des 13. Jahrhunderts gegen eine wesentlich größere Burg aus Stein. Innerhalb der Ringmauer gründete Hervé IV. du Pont 1350 eine Kapelle aber einer seiner protestantischen Nachfolger, Charles de Quellenec, vertrieb die katholischen Geistlichen. Nachfolgend ungenutzt, verfiel der Kirchenbau in der Folgezeit. Die im 15. Jahrhundert erneuerte Anlage wurde während der Hugenottenkriege 1590 beschädigt. Sie war in den Händen der königstreuen Partei unter dem Kommando eines gewissen Trogoff, der sich nicht nur tyrannisch und rücksichtslos gegenüber den Einwohnern Pont-l’Abbés verhielt, sondern auch die Umgegend unsicher machte und verwüstete, sodass die Bewohner den Hauptmann (französisch capitaine) Lézonnet aus Concarneau zur Hilfe riefen. Der belagerte daraufhin mit seinen Mannen die Burg. Nachdem Trogoff durch einen Arkebusentreffer getötet worden war, ergab sich die Burgmannschaft den Belagerern.","w":"https://de.wikipedia.org/wiki/Burg_Pont-l%E2%80%99Abb%C3%A9"},"ch-Q22940848":{"c":"Schloss in Frankreich"},"ch-Q22248535":{"c":"Schloss in Frankreich"},"ch-Q22964864":{"c":"Schloss in Frankreich"},"ch-Q20083814":{"c":"Schloss in Frankreich"},"ch-Q20083816":{"c":"Schloss in Frankreich"},"ch-Q18006070":{"c":"Burg in Frankreich"},"ch-Q20311524":{"c":"Schloss in Frankreich"},"ch-Q22954304":{"c":"Schloss in Frankreich"},"ch-Q22955770":{"n":"Taubenturm Domaine de Beaulieu","c":"Schloss in Frankreich","r":"Der Taubenturm der Domaine de Beaulieu in Germignac, einer französischen Gemeinde im Département Charente-Maritime in der Region Nouvelle-Aquitaine, wurde 1595 errichtet. Der Taubenturm steht seit 1992 als Teil der Domaine de Beaulieu als Monument historique auf der Liste der Baudenkmäler in Frankreich.","w":"https://de.wikipedia.org/wiki/Taubenturm_Domaine_de_Beaulieu_(Germignac)"},"ch-Q22994771":{"c":"Schloss in Frankreich"},"ch-Q22941130":{"c":"Schloss in Frankreich"},"ch-Q22986039":{"c":"Palast in Frankreich"},"ch-Q22986479":{"c":"Schloss in Frankreich"},"ch-Q22986541":{"c":"Schloss in Frankreich"},"ch-Q22986669":{"c":"Schloss in Frankreich"},"ch-Q22987651":{"c":"Schloss in Frankreich"},"ch-Q22987874":{"c":"Schloss in Frankreich"},"ch-Q22986672":{"c":"Schloss in Frankreich"},"ch-Q20971005":{"c":"Schloss in Frankreich"},"ch-Q20948764":{"n":"Schloss Montbras","c":"Renaissanceschloss in Lothringen","r":"Das Schloss Montbras ist ein französisches Schloss in der lothringischen Gemeinde Montbras. Die Anlage im Stil der Renaissance steht auf einem Felsplateau am linken Ufer der Maas. Von Claude de Verrières Ende des 16. Jahrhunderts begonnen, sind von der einst vierflügeligen Anlage heute nur noch eineinhalb Gebäudetrakte übrig. Diese stehen seit dem 28. Juni 1974 als klassifiziertes Monument historique unter Denkmalschutz.","h":"Ein 300 Meter vom heutigen Schloss entfernter Vorgängerbau wurde zu Beginn des 14. Jahrhunderts erstmals urkundlich erwähnt, als das feste Haus von Bras (französisch fors maison de Bras, später L’Isle-en-Bras genannt) Opfer eines Feuers wurde. Danach wieder aufgebaut, kam es am 24. August 1353 bei einer Erbteilung der Brüder Pierre, Jean und Henri de Bourlémont in den Besitz von Jean. Später wechselte das Anwesen in den Besitz der Familie de Vigneulles und verfiel zu einer Ruine. Louis de Vigneulles und seine Frau Nicole de Merlet verkauften diese am 11. August 1598 an Claude de Verrières. Das Geld dazu stammte aus der 60.000 Franc barrois umfassenden Mitgift, die dessen Frau Louise de Salles mit in die Ehe gebracht hatte. Schon kurz nach dem Kauf begann das Paar mit dem Bau des heutigen Schlosses als eine 57 × 60 Meter messende Vierflügelanlage mit bastionierten Ecktürmen. Der Architekt ist unbekannt, möglicherweise handelte es sich um einen der italienischen Baumeister am Hofe des lothringischen Herzogs Karl III., dessen Kammerherr Claude de Verrières’ Vater war. Die Bauarbeiten wurden 1611 durch Louise de Salles’ Tod vorübergehend unterbrochen, nach Claudes zweiter Heirat am 7. November 1611 mit Julia della Valle aber wieder aufgenommen. Nachdem Claude bei seinem Tod keine Kinder hinterließ, schenkte seine Witwe das Schloss Montbras am 28. März 1638 einer Großnichte ihres verstorbenen Mannes, Marie de Mery, als diese Jacques de Leviston heiratete. Das Paar weilte aber nur selten in Montbras. Im September 1643 übertrug es seine Rechte am Schloss und an der Domäne an Simon de Sommyèvre, einem anderen Verwandten Claude de Verrières’. Dieser residierte aber nicht auf Montbras, und auch sein Sohn Jacques nutzte es nur gelegentlich.","w":"https://de.wikipedia.org/wiki/Schloss_Montbras"},"ch-Q22932731":{"n":"Schloss La Rochelambert","c":"Schloss in Frankreich","r":"Das Schloss La Rochelambert ist eine historische Burg im Département Haute-Loire in der Region Auvergne-Rhône-Alpes, Frankreich. Die Burg befindet sich auf einem Felsen oberhalb des Tals der Ance, etwa zehn Kilometer westlich der Stadt Le Puy-en-Velay. Die Anlage ist heute für ihre gut erhaltenen Ruinen sowie ihre beeindruckende Architektur der Renaissance und Geschichte bekannt.","h":"Die erste dokumentierte Person, die das Schloss besaß, war der Ritter Pierre de la Rochelambert, der im Jahr 1074 auf den Ruinen eines antiken Gasthauses eine Festung errichtete. Das Hauptziel des Schlosses war die Überwachung der Chaussée Jules César, einer alten Straße, die unterhalb des Schlosses verlief und als strategischer Kontrollpunkt auf der Jakobsstraße diente. Im August 1562 erlitt das Schloss schwere Schäden bei einem Angriff der Protestanten. Zu Beginn des 17. Jahrhunderts ließ Hélène de Lestrange, die Ehefrau des Marquis de la Rochelambert, das Gebäude wiederaufbauen. Sie starb 1614, nachdem sie das Schloss in den Zustand versetzt hat, in dem es heutzutage noch ist. Das Schloss befand sich bis 1922 im Besitz der Familie de la Rochelambert, als es von der Tochter des letzten Marquises, Marie Auguste Aimé, verkauft wurde. 1939 erwarb der bekannte Antiquitätenhändler Herr Bresset das Schloss und ergänzte es mit historischen Sammlungsstücken, die noch heute im Rahmen von Besichtigungen zu sehen sind. Am 31. Januar 1945 wurde das Schloss als historisches Denkmal eingestuft. Während ihrer Reise nach Velay besuchte Georges Sand am Dienstag, den 14. Juni 1859, das Schloss. Sie wählte es als Schauplatz für ihren Roman „Jean de la Roche“, den sie im darauffolgenden Monat verfasste. Über das Schloss schrieb sie Folgendes:","w":"https://de.wikipedia.org/wiki/Schloss_La_Rochelambert"},"ch-Q22935598":{"c":"Schloss in Frankreich"},"ch-Q22941256":{"n":"Burg Les Étangs (Bossée)","c":"Schloss im Département Indre-et-Loire, Frankreich","r":"Die ehemalige Burg Les Étangs ist eine Burgruine in Bossée im französischen Département Indre-et-Loire. Sie wurde 1949 als Monument historique in die französische Denkmalliste aufgenommen.","w":"https://de.wikipedia.org/wiki/Burg_Les_%C3%89tangs_(Boss%C3%A9e)"},"ch-Q22941579":{"c":"Palast in Frankreich"},"ch-Q22943784":{"c":"Schloss in Frankreich"},"ch-Q22941847":{"c":"Schloss in Frankreich"},"ch-Q22996392":{"c":"Palast in Frankreich"},"ch-Q16937101":{"n":"Herzogsburg von Châtillon-sur-Seine","c":"Schloss in Bourgogne-Franche-Comté, Frankreich","r":"Die Herzogsburg Châtillon-sur-Seine war die Burg der Herzöge von Burgund. Sie befindet sich in der französischen Stadt Châtillon-sur-Seine im Département Côte-d’Or (Burgund-Franche-Comté) und steht seit 1909 als Monument historique unter Denkmalschutz.","h":"Die Burg, die wahrscheinlich im 12. Jahrhundert von den Herzögen von Burgund errichtet wurde, nahm einen Teil des castrums ein, das bis 973 im alleinigen Besitz der Bischöfe von Langres gewesen war. Die Herzogsburg und die Bischofsresidenz wurden von einer gemeinsamen Ringmauer umschlossen, von der nur noch einige Teile und der Gissey-Turm im Norden erhalten geblieben sind. 1359 wurde die Burg von den Engländern schwer beschädigt und nachfolgend teilweise wieder aufgebaut. Nach den Hugenottenkriegen wurde sie von den Einwohnern abgetragen, König Heinrich IV. gab ihnen am 30. Januar 1598 dazu die nötige Erlaubnis. 1608 wurde das Erdgeschoss des Saint-Anne-Turmes als Wachhaus genutzt, später – wahrscheinlich im 19. Jahrhundert – wurde dort ein Brotbackofen eingerichtet.","w":"https://de.wikipedia.org/wiki/Herzogsburg_Ch%C3%A2tillon-sur-Seine"},"ch-Q16507468":{"c":"Schloss in Frankreich"},"ch-Q16954210":{"n":"Schloss Tronjoly","c":"Schloss in Frankreich","r":"Das Schloss Tronjoly ist ein Landschloss nordwestlich von Cléder in der Bretagne. Im 16. Jahrhundert begonnen und im 17. Jahrhundert umgebaut, steht die dreiflügelige Anlage seit dem 23. Juli 1981 als klassifiziertes Monument historique unter Denkmalschutz. Ihr Park und die Schlosskapelle stehen Besuchern das ganze Jahr hindurch unentgeltlich offen. An jeweils einem Tag in den Monaten Juli und August sind im Rahmen einer Führung auch die Innenräume des Gebäudes zu besichtigen.","h":"Ein erstes festes Haus an diesem Ort ist bereits für das Jahr 1390 verbürgt. Sein damaliger Besitzer Guyon de Kergoët stammte aus einer alten bretonischen Familie, die erstmals 1296 erwähnt wurde. Sein Nachfahr Christophe der Kergoët, Seigneur von Tronjoly, ließ ab 1535 einen Neubau errichten. Sein Wappen und sein Motto S’il plaît à Dieu (deutsch Wenn es Gott gefällt) finden sich heute noch mehrfach in dem Schloss. Charles Louis de Kergoët ließ diese Anlage während des 17. Jahrhunderts im Stil des klassizistischen Barocks verändern und eine erhöhte Terrasse gegenüber dem Nordflügel errichten. Sein Enkel Louis Charles de Kergoët, Sohn von Ollivier Gabriel de Kergoët und seiner Frau Françoise Gabrielle de Goujon de la Palue, starb 1774 ohne Nachkommen, und so kam der Besitz an dessen Neffen Ambroise Toussaint de Parcevaux, seigneur de Kerarméar. Er war der Sohn von Louis Charles’ Schwester Marie Madeleine de Kergoët, die 1738 Claude-Marie de Parcevaux geheiratet hatte. 1883 gelangte die Anlage – wieder durch Heirat einer Tochter des Besitzers – an die Familie Hervé du Penhoat. Heute ist sie Eigentum der Familie Sagazan.","w":"https://de.wikipedia.org/wiki/Schloss_Tronjoly"},"ch-Q22920450":{"c":"Schloss in Frankreich"},"ch-Q19753104":{"c":"Schloss in Frankreich"},"ch-Q22920566":{"c":"Schloss in Frankreich"},"ch-Q22994100":{"c":"Schloss in Frankreich"},"ch-Q22959925":{"n":"Schloss Vic-sur-Seille","c":"Schloss im Département Moselle, Frankreich","r":"Das Schlossportal in Vic-sur-Seille, einer französischen Gemeinde im Département Moselle in der historischen Region Lothringen, wurde im 14. Jahrhundert errichtet. Das Schlossportal wurde im Jahr 1930 als Monument historique in die Liste der Baudenkmäler in Frankreich aufgenommen.","h":"Das Schloss der Bischöfe von Metz entstand ab dem 12. Jahrhundert und wurde im 13. Jahrhundert vergrößert. Unter dem Bischof Dietrich Bayer von Boppard (Bischof von 1365 bis 1384) wurden der Wassergraben angelegt, Türme erbaut und die Wohnräume vergrößert. Davon sind außer dem Portal nur noch kleine Reste erhalten. Der Park der Anlage ist heute öffentlich.","w":"https://de.wikipedia.org/wiki/Schlossportal_(Vic-sur-Seille)"},"ch-Q22960740":{"c":"Schloss in Frankreich"},"ch-Q22959915":{"n":"Schloss Volkrange","c":"Schloss im Département Moselle, Frankreich","r":"Das Schloss in Volkrange, einem Ortsteil von Thionville im Département Moselle in der historischen Region Lothringen, wurde ursprünglich im 13. Jahrhundert errichtet und im 18. Jahrhundert wesentlich verändert. Das Schloss wurde im Jahr 1984 als Monument historique in die Liste der Baudenkmäler in Frankreich aufgenommen.","w":"https://de.wikipedia.org/wiki/Schloss_Volkrange"},"ch-Q22994180":{"n":"Burg Le Coudray-Montpensier","c":"Schloss in Frankreich","r":"Die Burg Le Coudray-Montpensier, eine alte Châtellenie, die zu Montsoreau gehörte, liegt an der Straße, die Chinon mit Seuilly verbindet, eingebettet zwischen Feldern und Weinbergen. Die Geschichte von Le Coudray-Montpensier reicht bis ins 11. Jahrhundert zurück. Das Anwesen war nacheinander im Besitz verschiedener Adelsfamilien und -linien: die Montsoreau, die ersten nachgewiesenen Herren, die Marmande, die Sainte Maure, die Artois, die Bournan, die Bourbon, die Escoubleau, die de Vallière und schließlich die Familie Lamote-Baracé.","h":"Le Coudray-Montpensier ist eine alte Burg, deren Bedeutung auf zwei Faktoren zurückzuführen ist. Einerseits durch ihre Nähe zu Chinon, andererseits aber auch durch die Macht und das Prestige der Familien, die diese Ländereien besaßen und die sich über mehrere Jahrhunderte hinweg abwechselten. Der Chevalier Guillaume de Montsoreau ist der erste bekannte Herr von Le Coudray am Ende des 11. Jahrhunderts (1090). Er ist auch der Gründer der Abtei von Seuilly. Die Ländereien von Le Coudray blieben bis zum Beginn des 13. Jahrhunderts im Besitz der Montsoreau. Dann gingen sie in den Besitz der Familie Marmande (in der Touraine) über, der wir die Kapelle von Le Coudray verdanken. Philippe de Marmande, die Tochter von Guillaume de Marmande, dem neunten Herrn von Le Coudray, heiratete Ende des 13. Jahrhunderts Hugues de Brisay und übertrug ihm Le Coudray für kurze Zeit. Da sie kinderlos starb, ging das Land über Mahaut de Marmande, eine mit Pierre de Sainte-Maure verheiratete Verwandte, bis in die erste Hälfte des 14. Jahrhunderts in den Besitz der Familie Sainte-Maure über. Ende des 14. Jahrhunderts ging Le Coudray in den Besitz von Ludwig I. von Anjou, Herzog von Touraine und Anjou, Titularkönig von Sizilien und Jerusalem, über. 1399 bekam seine Witwe Marie de Châtillon, Tochter von Charles de Blois, Herzog der Bretagne, und Jeanne de Bretagne, das Gut Le Coudray, das sie gegen eine Rente an Pierre de Bournan weitergab. Die Familie de Bournan, mit Pierre und seinem Sohn Louis, ist den Quellen zufolge die erste Familie, die Bauarbeiten an der Burg unternimmt, die anfangs nur „eine einfache, von Gräben und Holzzäunen umgebene Behausung“ war. Die Bournans wären somit die Urheber der ersten Bauarbeiten an der Burg, die im Jahr 1401 begannen und fast vierzig Jahre lang andauerten.","w":"https://de.wikipedia.org/wiki/Burg_Le_Coudray-Montpensier"},"ch-Q20036724":{"c":"Schloss in Frankreich"},"ch-Q22988143":{"c":"Schloss in Frankreich"},"ch-Q22988205":{"c":"Schloss in Frankreich"},"ch-Q22963211":{"c":"Schloss in Frankreich"},"ch-Q22963259":{"c":"Schloss in Frankreich"},"ch-Q22963391":{"c":"Schloss in Frankreich"},"ch-Q22939848":{"c":"Schloss in Frankreich"},"ch-Q22940152":{"n":"Schloss La Motte (Bardigues)","c":"Schloss in Frankreich","r":"Das Schloss La Motte ist ein Schloss aus dem 18. Jahrhundert in der Gemeinde Bardigues im französischen Département Tarn-et-Garonne in der Region Okzitanien.","h":"Das Lehen Bardigues wurde 1315 von Raymond-Arnaud de Goth, dem Neffen von Clemens V., dem ersten Papst in Avignon, erworben. Die Familie Goth baute im Laufe des 14. Jahrhunderts ein erstes Schloss, das im 16. Jahrhundert umgebaut wurde. Als Béraud de Goth sich der Armee des Königs anschloss, verfasste er am 26. Juni 1589 sein Testament zugunsten seiner Frau und eines potenziellen Kindes, blieb aber ohne Nachkommen. Als Ersatzerben hatte er Pierre de Cruzy-Marcillac eingesetzt, mit der Maßgabe, dass er seinem Namen den der Goth hinzuzufüge. Dies geschah am 12. Januar 1633. Pierre de Goth de Cruzy-Marcillac, der mit Madeleine de Voisins-Montaut verheiratet war, hatte als alleinige Erbin eine Tochter, Charlotte, die er am 2. Januar 1625 mit Jean-François d’Esparbès de Lussan verheiratete. Mit dieser Heirat vermachte er seinem Schwiegersohn seinen gesamten Besitz und wies ihn ebenfalls an, seinem Familiennamen den Namen de Goth hinzuzufügen. Dies geschah bei der Geburt seines einzigen Enkels, Sylvestre d’Esparbès de Lussan de Goth († nach 1741). Die bekanntesten Besitzer bzw. Bewohner des Schlosses aus der Familie Esparbès sind: Michel d'Esparbès de Lussan de Goth (1682–1776), Baron de La Motte-Bardigues, Sohn von Sylvestre Jean Jacques Pierre d’Esparbès de Lussan (1720–1810), dessen Sohn, Baron de Lamotte-Bardigues, Generalgouverneur von Sainte-Domingue, starb auf dem Schloss Louis François d’Esparbes de Lussan (1732–1810), dessen Bruder, Baron de La Motte-Bardigues, starb auf dem Schloss Louise d’Esparbès de Lussan (1764–1804), dessen Tochter, geboren auf dem Schloss, durch ihre Ehe Vicomtesse de Polastron, 1785 Mätresse des Comte d’Artois Das heutige Schloss wurde im Laufe des 18. Jahrhunderts auf den Grundmauern des alten Gebäudes errichtet.","w":"https://de.wikipedia.org/wiki/Schloss_La_Motte_(Bardigues)"},"ch-Q28370827":{"c":"Schule in Frankreich"},"ch-Q22967287":{"c":"Schloss in Frankreich"},"ch-Q22967383":{"c":"Schloss in Frankreich"},"ch-Q22967425":{"c":"Schloss in Frankreich"},"ch-Q22997598":{"c":"Schloss in Frankreich"},"ch-Q22998429":{"c":"Schloss in Frankreich"},"ch-Q22966581":{"c":"Schloss in Frankreich"},"ch-Q28952441":{"c":"Schloss in Frankreich"},"ch-Q22966562":{"c":"Schloss in Frankreich"},"ch-Q22965347":{"c":"Schloss in Frankreich"},"ch-Q22968953":{"c":"Schloss in Frankreich"},"ch-Q22967011":{"c":"Schloss in Frankreich"},"ch-Q22967030":{"c":"Schloss in Frankreich"},"ch-Q26257847":{"n":"Burg Esch","c":"Schloss in Frankreich","r":"Die Burg Esch ist eine Burg im französischen Département Moselle. Sie gehört zur Gemeinde Schwerdorff.","h":"Die Ursprünge der Familie der Ritter von Esch sind nicht eindeutig belegt. Sie könnte von einem deutschen Zweig aus Trier, aus dem luxemburgischen Esch-Sauer (Esch-sur-Sûre) oder aus Metz stammen. Urkundlich erscheint nach J. Siebmacher zuerst im Jahr 1346 Hesso von Esch und 1353 (wahrscheinlich derselbe) Hesso von Esch; 1383, 1387, 1392 Ensfried von Esch; 1383 Bertram von Esch, Abt zu Mettlach; 1385 war Ensfried von Esch Vasall des Grafen von Nassau-Saarbrücken. Sein Sohn Gerhard wurde im Jahr 1430 belehnt mit Gütern zu Rimersweiler, Exweiler, Friemersdorf etc. Wahrscheinlich dessen Bruder war Johann Edelknecht von Esch, Vasall von Nassau-Saarbrücken. Dessen Sohn Hesso wurde belehnt mit Rimersweiler und Exweiler 1430. Des Letzteren Sohn Jacob wurde 1473 belehnt mit Mechern, Friemersdorf, der Mühle Merzig und Gütern zu Rimersweiler und Exweiler. Sein Sohn Wilhelm belehnt 1490 wie sein Vater. Er war der letzte männliche Sprosse und hatte nur eine Tochter Margaretha, 1512 vermählt mit Caspar von Kerpen, welcher mit einem Teil von Esch belehnt wurde. Das Wappen dieser Familie von Esch war ein roter Schild, darin 2 silberne Balken, der obere mit 3, der untere mit 2 schwarzen Kugeln belegt. Auf dem Helme 2 Büffelhörner wie der Schild gezeichnet. Hesso von Esch siegelt 1430–38 mit einem Häuschen zwischen den Hörnern des Helmes, welche Abweichung ein Grabstein der Familie zu St. Arnual bei Saarbrücken bestätigt. Die Stammhäuser dieses ebenfalls Lothringischen Geschlechts waren Burg Esch bei Busendorf und Burg Siersberg, östlich von Saarlouis. Urkundlich erscheint nur 1405 ein Ysenbardas von Esche als lothringischer Burggraf zu Siersberg. Aus einer Türkheim’schen Stammtafel ersehen wir auch das Wappen der Familie, speziell eines N. von Esch gen.","w":"https://de.wikipedia.org/wiki/Burg_Esch"},"ch-Q28497214":{"n":"Château de la Rivière","c":"Schloss in Frankreich","r":"Château de la Rivière ist ein französisches Schloss und bekanntes Weingut in der Gemeinde La Rivière im Département de la Gironde.","h":"Das Schloss Château de la Rivière in der Weinbauregion Bordeaux hat eine Geschichte, die bis zum 8. Jahrhundert zurückreicht. Die Anlage des Château de la Rivière war ursprünglich ein befestigtes Lager, das Karl der Große erbauen ließ. Archäologische Hinweise deuten auf eine frühere römische Siedlung hin. Mit über 65 Hektar Rebfläche ist es das größte Weingut in der Appellation Fronsac. Das Anwesen umfasst auch eine Reihe von alten Steinbrüchen mit Kellergewölben die als große Lagerflächen für Weinfässer genutzt werden. 1962 wurde das Schloss restauriert. 1995 wurde durch den Besitzer Jean Leprince die Weinkellerei umfangreich erweitert. Die Weinberge im Château de la Rivière sind zu zwei Dritteln mit Trauben der Sorte Merlot bestockt und der weitere Teil setzt sich aus Cabernet Sauvignon, Cabernet Franc und Petit Verdot zusammen. Nach dem Tode von Jean Leprince 2002 wurde das Anwesen von James Edmond Grégoire, Geschäftsführer und Inhaber der Firma Grégoire, einem führenden Hersteller von Erntemaschinen gekauft. Ende 2013 erwarb eine chinesische Unternehmensgruppe das Schloss mit den dazugehörigen 65 Hektar Weinbergen. Der bisherige Besitzer James Grégoire, Eigner eines Helikopters Robinson R44 und Inhaber eines Helikopterflugscheins wollte dem neuen Eigentümer Lam Kok nach dem Verkaufsabschluss bei einem Rundflug seinen neuen Besitz aus der Luft zeigen. Ein Fotograf der Nachrichtenagentur AFP berichtete, auch der 12-jährige Sohn des chinesischen Milliardärs sowie ein Übersetzer seien mitgeflogen. Die Ehefrau von Lam Kok habe sich dagegen in letzter Minute dagegen entschieden. Als der Helikopter nach einiger Zeit nicht zurückkehrte, alarmierten die Zurückgebliebenen die Polizei, die daraufhin zwei Helikopter zur Suche nach den Vermissten entsandte.","w":"https://de.wikipedia.org/wiki/Ch%C3%A2teau_de_la_Rivi%C3%A8re"},"ch-Q30281725":{"n":"Château de Longchamp","c":"Schloss in Paris, Frankreich"},"ch-Q30737476":{"n":"Burg Schwarzenbourg","r":"Die Burg Schwarzenberg ist die Ruine einer Höhenburg bei Griesbach-au-Val im Département Haut-Rhin im Elsass. Sie steht auf 540 Höhenmetern über dem Münstertal.","h":"Die Erstnennung der Burg erfolgte im Jahr 1261. Vermutlich hatte Walter von Geroldseck, der Bischof von Straßburg, den Bau im Baseler Einflussbereich angeordnet, um sich gegenüber der Abtei Münster Geltung zu verschaffen. Nach der Schlacht von Hausbergen 1262 ging die Burg in den Besitz des Bischofs von Basel über. 1293 wurde der seit 1282 amtierende Schultheiß von Colmar, Walter Rösselmann, im Bergfried inhaftiert und verstarb dort im Folgejahr. 1301 übernahm Johann von Wartenfels als Kastellan die Burg, 1341 folgten die Münch von Landskron – jeweils Vasallen des Bistums Basel. Im Jahr 1402 befand sich Burg Schwarzenberg in Händen der Beger von Geispolsheim, welche die Burg 1479 erneuerten. Bis zum Aussterben der Familie 1532 kam es mehrfach zu Auseinandersetzungen mit der Abtei Münster, so in den Jahren 1435 und 1522. Im Dreißigjährigen Krieg wurde das Burggelände von 1633 bis 1636 von französischen Truppen besetzt, 1651 folgte die württembergische Armee. Während des Ersten Weltkriegs nutzte die deutsche Artillerie die Ruine als Beobachtungsposten und errichtete in ihr ein Blockhaus.","w":"https://de.wikipedia.org/wiki/Burg_Schwarzenberg_(Elsass)"},"ch-Q31187878":{"c":"Palast in Frankreich"},"ch-Q32998722":{"n":"Schloss Dommerville","c":"Burg in Frankreich","r":"Das Schloss Dommerville in Dommerville, einem Ortsteil der französischen Gemeinde Angerville im Département Essonne in der Region Île-de-France, wurde von 1777 bis 1782 errichtet. Das Schloss ist seit 1977 als Monument historique auf der Liste der Baudenkmäler in Frankreich.","h":"Der Bauherr, der Marquis de Hallot, ließ den Vorgängerbau abreißen, von dem lediglich ein eisernes Tor an der Route de Chartres zeugt. Die Dreiflügelanlage mit Ehrenhof wurde ab 1869 als Bauernhof genutzt und nach dem Besitzerwechsel im Jahr 1963 umfassend renoviert. Das zweigeschossige Bauwerk besitzt im Innern originale Ausstattungsstücke wie zum Beispiel ein Ofen aus Fayence und ein gusseisernes Treppengeländer. In der Parkanlage steht ein kleiner sechseckiger Pavillon aus dem 18. Jahrhundert, der für die Rebhuhnjagd genutzt wurde.","w":"https://de.wikipedia.org/wiki/Schloss_Dommerville"},"ch-Q26910878":{"n":"Château d’Ardennes","c":"Schloss in Frankreich","r":"Das Schloss Ardennes ist eine zum Schloss umgebaute ehemalige Wasserburg auf dem Gebiet der Gemeinde Fléac-sur-Seugne südlich von Pons im Département Charente-Maritime, Frankreich. Es befindet sich etwa drei Kilometer ostsüdöstlich der Kernsiedlung und etwa 500 m südlich der Straße D 249 nach Marignac.","h":"Eine kleine Burg wurde im 12. Jahrhundert vermutlich von den Templern erbaut, kam nach der Auflösung des Ordens 1312 zunächst an die Johanniter und spätestens im ersten Quartal des 15. Jahrhunderts an die im Angoumois und in der Saintonge begüterte Familie de Balodes, die 1420 als Besitzer beurkundet ist. Sie vergrößerte die Anlage erheblich und ließ sie zum Schloss umbauen. Im Jahre 1610 ist der einem aus Wales eingewanderten Geschlecht entstammende Daniel Green de Saint Marsault als Besitzer genannt. 1618 kaufte Pierre Dugua de Mons (1558–1628), der Gründer der ersten dauerhaften Siedlung in Neufrankreich (Kanada), das Schloss. Dugua war von 1610 bis 1618 Gouverneur von Pons und lebte danach bis zu seinem Tod 1628 in seinem Château d’Ardennes. Er ließ das Schloss, insbesondere die oberen Geschosse, noch einmal gründlich renovieren und erweitern. Nach seinem Tod wurde er unter einem großen Baum vor dem Schlosseingang bestattet. Duguas Ehe war kinderlos geblieben, und das Schloss wechselte nach seinem Tod mehrfach den Besitzer. Es war lange Zeit, bis in die 1970er Jahre, im Besitz eines Zweigs der Familie Pandin de Lussaudière. Ein neuer Eigentümer restaurierte ab 1982 die Wirtschaftsgebäude und die hofseitigen überdachten Galerien. Das Anwesen wurde seitdem erneut weiterverkauft.","w":"https://de.wikipedia.org/wiki/Schloss_Ardennes"},"ch-Q30740362":{"n":"Château de Montmorency","c":"Schloss in Val-d'Oise, Frankreich"},"ch-Q55935101":{"c":"Burg in Frankreich"},"ch-Q55460708":{"c":"Schloss in Frankreich"},"ch-Q65153288":{"c":"Schloss in Frankreich"},"ch-Q83718015":{"n":"Pont-Saint-Pierre Schloss","c":"schloss in Pont-Saint-Pierre"},"ch-Q107283437":{"c":"Schloss in Frankreich"},"ch-Q107414543":{"n":"Schloss Montauriol","c":"Schloss in Frankreich","r":"Das Schloss Montauriol steht heute im Stadtgebiet von Montauban im Südwesten Frankreichs, dem Verwaltungssitz des Départements Tarn-et-Garonne.","w":"https://de.wikipedia.org/wiki/Schloss_Montauriol"},"ch-Q108749249":{"n":"Burg Saint-Paul","r":"Die Burg Saint-Paul bei Weißenburg im Elsass bildete im Mittelalter zusammen mit der Burg St. German und weiteren Anlagen eine vorgelagerte Verteidigungslinie für das Reichskloster Weißenburg.","h":"Die Burg ging aus einer Kapelle hervor, die schon in der Zeit um 800 bezeugt ist. Auch später hatte die Burg immer eine Burgkapelle. Die Burg ist seit dem 11. Jh. nachweisbar. Nach einer Zerstörung im 13. Jh. wurde sie unter Abt Edelin (1262–1293) wiedererrichtet. Die Burg war als Lehen des Klosters und späteren Stifts Weißenburg an die Grafen von Leiningen vergeben, die damit die Herren von Fleckenstein als Unterlehen beliehen hatten. Im Weißenburger Krieg (1469–1472) besetzten die kurpfälzischen Angreifer auf Weißenburg und das Kloster am 7. Januar 1469 die Burg St. Paul und nutzten sie als Ausgangs- und Rückzugsort bei ihren Angriffen auf Stadt und Kloster. Am 6. August 1470 schlossen das Kloster und die Stadt Weißenburg ein Bündnis mit Herzog Ludwig I. von Pfalz-Zweibrücken und den Grafen von Leiningen. Am 10. August 1470 stürmte diese Allianz die Burg und vertrieb die kurpfälzische Besatzung. Bei der Burg bestand eine winzige Siedlung, die vor dieser Fehde zwei steuerpflichtige Einwohner hatte. Die Burg wurde nach der Beschädigung im Weißenburger Krieg wieder aufgebaut. Seit der Französischen Revolution befindet sie sich in Privatbesitz.","w":"https://de.wikipedia.org/wiki/Burg_Saint-Paul"},"ch-Q10137":{"n":"Schloss Charly","c":"Schloss in Frankreich"},"ch-Q10945":{"n":"Château de Beauregard","c":"Schlossruine in Frankreich"}};
